class CuotaCobrar {
  int numero;
  double monto;
  String fecha;       // fecha de vencimiento de la cuota
  bool pagada;
  String? fechaPago;  // fecha en que fue abonada

  CuotaCobrar({
    required this.numero,
    required this.monto,
    required this.fecha,
    this.pagada = false,
    this.fechaPago,
  });

  factory CuotaCobrar.fromMap(Map<String, dynamic> m) => CuotaCobrar(
    numero: int.tryParse(m['numero'].toString()) ?? 0,
    monto: double.tryParse(m['monto'].toString()) ?? 0,
    fecha: m['fecha']?.toString() ?? '',
    pagada: m['pagada'] == true || m['pagada'] == 1,
    fechaPago: m['fecha_pago']?.toString(),
  );

  Map<String, dynamic> toMap() => {
    'numero': numero,
    'monto': monto,
    'fecha': fecha,
    'pagada': pagada,
    'fecha_pago': fechaPago,
  };
}

class CuentaPorCobrar {
  int? id;
  final String cedula, nombre, telefono, correo;
  double montoTotal;
  List<Map<String,dynamic>> pagos;
  List<CuotaCobrar> cuotas;
  String notas;
  /// Nombre de la financiadora (Weppa, Cashea, FPB, Krece, etc.).
  /// Vacío si la cuenta no fue creada por una factura financiada.
  String financiadora;
  /// Saldo A FAVOR del cliente (por sobrepago). Cuando se registra un
  /// pago mayor al saldo restante, el excedente queda acá. Se aplica
  /// automáticamente al aumentar la deuda de la cuenta.
  double saldoFavor;

  CuentaPorCobrar({this.id, required this.cedula, required this.nombre,
      required this.telefono, required this.correo, required this.montoTotal,
      this.notas = "", this.financiadora = "", this.saldoFavor = 0,
      List<Map<String,dynamic>>? pagos,
      List<CuotaCobrar>? cuotas})
      : pagos = pagos ?? [],
        cuotas = cuotas ?? [];

  /// Suma de todos los pagos libres registrados
  double get totalPagado =>
      pagos.fold(0.0, (s, p) => s + (double.tryParse(p['monto'].toString()) ?? 0));

  /// Suma de cuotas marcadas como pagadas
  double get totalCuotasPagadas =>
      cuotas.where((c) => c.pagada).fold(0.0, (s, c) => s + c.monto);

  double get saldoRestante =>
      (montoTotal - totalPagado - totalCuotasPagadas).clamp(0, double.infinity);

  /// Próxima cuota pendiente (la de menor número no pagada)
  CuotaCobrar? get proximaCuota =>
      cuotas.where((c) => !c.pagada).fold<CuotaCobrar?>(null, (prev, c) {
        if (prev == null) return c;
        return c.numero < prev.numero ? c : prev;
      });

  factory CuentaPorCobrar.fromMap(Map<String,dynamic> m) => CuentaPorCobrar(
    id: m['id'] is int ? m['id'] : int.tryParse(m['id']?.toString() ?? ''),
    cedula: m['cedula'] ?? '',
    nombre: m['nombre'] ?? '',
    telefono: m['telefono'] ?? '',
    correo: m['correo'] ?? '',
    montoTotal: double.tryParse(m['monto_total'].toString()) ?? 0,
    notas: m['notas'] ?? '',
    financiadora: (m['financiadora'] ?? '').toString(),
    saldoFavor: double.tryParse(m['saldo_favor']?.toString() ?? '0') ?? 0,
    pagos: List<Map<String,dynamic>>.from(m['pagos'] ?? []),
    cuotas: ((m['cuotas'] as List?) ?? [])
        .map((c) => CuotaCobrar.fromMap(c as Map<String, dynamic>))
        .toList()
      ..sort((a, b) => a.numero.compareTo(b.numero)),
  );

  Map<String,dynamic> toMap() => {
    'cedula': cedula, 'nombre': nombre, 'telefono': telefono,
    'correo': correo, 'monto_total': montoTotal, 'notas': notas,
    'financiadora': financiadora,
    'saldo_favor': saldoFavor,
  };

  Map<String,dynamic> toMapConCuotas() => {
    ...toMap(),
    'cuotas': cuotas.map((c) => c.toMap()).toList(),
  };
}

// ── CUENTAS POR PAGAR ────────────────────────────────────────
// ── SALDO A FAVOR APARTADO (cuentas por pagar) ───────────────
//  En las cuentas por pagar el saldo a favor no es una columna de la
//  base: es la diferencia entre lo que se pagó y lo que se debe. Eso
//  alcanza para mostrarlo, pero no para decidir qué hacer con él:
//  al cargarle una factura nueva al proveedor el excedente se
//  descontaba solo, sin preguntar.
//
//  Para poder responder "no, guardame el saldo para la próxima" hace
//  falta recordar cuánto queda apartado. El único campo libre que el
//  backend ya persiste en estas tablas es `notas`, así que la cifra se
//  anota ahí en una línea con la marca `[[favor:N]]` que la interfaz
//  nunca muestra (para eso está `notasVisibles`).
//
//  Con R = saldo apartado:
//    deudaEfectiva  = montoTotal + R
//    saldoRestante  = deudaEfectiva − pagado      (nunca negativo)
//    saldoFavor     = (pagado − deudaEfectiva) + R
final RegExp _reFavorApartado = RegExp(r'\[\[favor:([0-9]+(?:\.[0-9]+)?)\]\]');

double _leerFavorApartado(String notas) {
  final m = _reFavorApartado.firstMatch(notas);
  if (m == null) return 0;
  return double.tryParse(m.group(1) ?? '') ?? 0;
}

/// Devuelve las notas con la marca `[[favor:N]]` puesta al valor dado
/// (o quitada si el valor es cero).
String _escribirFavorApartado(String notas, double valor) {
  final limpio = notas.replaceAll(_reFavorApartado, '').trimRight();
  if (valor <= 0.001) return limpio;
  final marca = '[[favor:${valor.toStringAsFixed(2)}]]';
  return limpio.isEmpty ? marca : '$limpio\n$marca';
}

String _notasSinMarcas(String notas) =>
    notas.replaceAll(_reFavorApartado, '').trim();

class CuentaPorPagar {
  int? id;
  final String rif, nombre, telefono, correo;
  double montoTotal;
  List<Map<String,dynamic>> pagos;
  List<CuotaCobrar> cuotas;
  String notas;

  CuentaPorPagar({this.id, required this.rif, required this.nombre,
      required this.telefono, required this.correo, required this.montoTotal,
      this.notas = "", List<Map<String,dynamic>>? pagos,
      List<CuotaCobrar>? cuotas})
      : pagos = pagos ?? [],
        cuotas = cuotas ?? [];

  double get totalPagado =>
      pagos.fold(0.0, (s, p) => s + (double.tryParse(p['monto'].toString()) ?? 0));
  double get totalCuotasPagadas =>
      cuotas.where((c) => c.pagada).fold(0.0, (s, c) => s + c.monto);

  /// Saldo a favor que el usuario decidió NO aplicar todavía. Se
  /// guarda dentro de `notas`; ver la explicación de arriba.
  double get favorApartado => _leerFavorApartado(notas);
  set favorApartado(double v) { notas = _escribirFavorApartado(notas, v); }

  /// Notas tal como se le muestran al usuario (sin la marca interna).
  String get notasVisibles => _notasSinMarcas(notas);

  /// Lo que realmente hay que cubrir: la deuda más lo que quedó
  /// apartado a favor y por lo tanto no cancela ninguna factura.
  double get deudaEfectiva => montoTotal + favorApartado;

  double get saldoRestante =>
      (deudaEfectiva - totalPagado - totalCuotasPagadas)
          .clamp(0, double.infinity);

  /// SALDO A FAVOR: cuánto se pagó DE MÁS sobre la deuda.
  ///
  /// Antes este excedente desaparecía: `saldoRestante` lo recortaba a 0
  /// con el `.clamp()`, así que si se registraba un pago de $6.000 sobre
  /// una deuda de $5.506, la pantalla mostraba "saldo $0,00" y los $494
  /// de más no figuraban en ningún lado.
  ///
  /// Se calcula a partir de los pagos ya guardados en lugar de leerse de
  /// una columna nueva, así el saldo aparece también en las cuentas que
  /// ya estaban sobrepagadas antes de este cambio.
  double get saldoFavor =>
      (totalPagado + totalCuotasPagadas - deudaEfectiva)
          .clamp(0, double.infinity) +
      favorApartado;

  /// true si la cuenta quedó sobrepagada (hay saldo a favor).
  bool get tieneSaldoFavor => saldoFavor > 0.001;

  CuotaCobrar? get proximaCuota =>
      cuotas.where((c) => !c.pagada).fold<CuotaCobrar?>(null, (prev, c) {
        if (prev == null) return c;
        return c.numero < prev.numero ? c : prev;
      });

  factory CuentaPorPagar.fromMap(Map<String,dynamic> m) => CuentaPorPagar(
    id: m['id'] is int ? m['id'] : int.tryParse(m['id']?.toString() ?? ''), rif: m['rif']??'', nombre: m['nombre']??'',
    telefono: m['telefono']??'', correo: m['correo']??'',
    montoTotal: double.tryParse(m['monto_total'].toString())??0,
    notas: m['notas']??'',
    pagos: List<Map<String,dynamic>>.from(m['pagos']??[]),
    cuotas: ((m['cuotas'] as List?) ?? [])
        .map((c) => CuotaCobrar.fromMap(c as Map<String,dynamic>))
        .toList()
      ..sort((a, b) => a.numero.compareTo(b.numero)));

  Map<String,dynamic> toMap() => {'rif':rif,'nombre':nombre,'telefono':telefono,
    'correo':correo,'monto_total':montoTotal,'notas':notas};
}

// ── CUENTAS POR PAGAR PROVEEDOR ──────────────────────────────
class CuentaPorPagarProveedor {
  int? id;
  final String rif, nombre, telefono, correo, fechaLimite;
  double montoTotal;
  List<Map<String,dynamic>> pagos;
  List<CuotaCobrar> cuotas;
  String notas;

  CuentaPorPagarProveedor({this.id, required this.rif, required this.nombre,
      required this.telefono, required this.correo, required this.montoTotal,
      required this.fechaLimite, this.notas = "",
      List<Map<String,dynamic>>? pagos,
      List<CuotaCobrar>? cuotas})
      : pagos = pagos ?? [],
        cuotas = cuotas ?? [];

  double get totalPagado =>
      pagos.fold(0.0, (s, p) => s + (double.tryParse(p['monto'].toString()) ?? 0));
  double get totalCuotasPagadas =>
      cuotas.where((c) => c.pagada).fold(0.0, (s, c) => s + c.monto);

  /// Saldo a favor apartado. Ver [CuentaPorPagar.favorApartado].
  double get favorApartado => _leerFavorApartado(notas);
  set favorApartado(double v) { notas = _escribirFavorApartado(notas, v); }

  /// Notas tal como se le muestran al usuario (sin la marca interna).
  String get notasVisibles => _notasSinMarcas(notas);

  /// Deuda más el saldo apartado. Ver [CuentaPorPagar.deudaEfectiva].
  double get deudaEfectiva => montoTotal + favorApartado;

  double get saldoRestante =>
      (deudaEfectiva - totalPagado - totalCuotasPagadas)
          .clamp(0, double.infinity);

  /// Excedente pagado por encima de la deuda. Ver la explicación en
  /// [CuentaPorPagar.saldoFavor] — misma lógica y mismo motivo.
  double get saldoFavor =>
      (totalPagado + totalCuotasPagadas - deudaEfectiva)
          .clamp(0, double.infinity) +
      favorApartado;

  /// true si la cuenta quedó sobrepagada (hay saldo a favor).
  bool get tieneSaldoFavor => saldoFavor > 0.001;

  CuotaCobrar? get proximaCuota =>
      cuotas.where((c) => !c.pagada).fold<CuotaCobrar?>(null, (prev, c) {
        if (prev == null) return c;
        return c.numero < prev.numero ? c : prev;
      });

  factory CuentaPorPagarProveedor.fromMap(Map<String,dynamic> m) => CuentaPorPagarProveedor(
    id: m['id'] is int ? m['id'] : int.tryParse(m['id']?.toString() ?? ''), rif: m['rif']??'', nombre: m['nombre']??'',
    telefono: m['telefono']??'', correo: m['correo']??'',
    montoTotal: double.tryParse(m['monto_total'].toString())??0,
    fechaLimite: m['fecha_limite']??'', notas: m['notas']??'',
    pagos: List<Map<String,dynamic>>.from(m['pagos']??[]),
    cuotas: ((m['cuotas'] as List?) ?? [])
        .map((c) => CuotaCobrar.fromMap(c as Map<String,dynamic>))
        .toList()
      ..sort((a, b) => a.numero.compareTo(b.numero)));

  Map<String,dynamic> toMap() => {'rif':rif,'nombre':nombre,'telefono':telefono,
    'correo':correo,'monto_total':montoTotal,'fecha_limite':fechaLimite,'notas':notas};
}

// ── USUARIO ───────────────────────────────────────────────────
class Usuario {
  int? id;
  final String nombre, cedula, correo, clave, rol;
  double sueldoBase;
  /// Tienda a la que pertenece el usuario. Vacío = todas las tiendas
  /// (sólo aplica a Administrador/Dueño/Gerente).
  String tienda;
  /// Si es false, el usuario NO recibe comisiones (sus productos no
  /// generan comisión para él, y si es cajero, no se lleva el split).
  /// Útil para administradores/dueños que no deben aparecer en la
  /// ventana de comisiones.
  bool ganaComisiones;

  Usuario({this.id, required this.nombre, required this.cedula,
      required this.correo, required this.clave, required this.rol,
      this.sueldoBase = 0, this.tienda = '', this.ganaComisiones = true});

  factory Usuario.fromMap(Map<String,dynamic> m) => Usuario(
    // MySQL devuelve los enteros como STRING (ej. "id":"1") porque
    // PDO en modo emulación los serializa así. Convertimos a int
    // explícitamente para evitar el error "type 'String' is not a
    // subtype of type 'int?'".
    id: m['id'] is int ? m['id']
        : int.tryParse(m['id']?.toString() ?? ''),
    nombre: m['nombre']??'', cedula: m['cedula']??'',
    correo: m['correo']??'', clave: m['clave']??'', rol: m['rol']??'',
    sueldoBase: double.tryParse(m['sueldo_base'].toString())??0,
    tienda: (m['tienda'] ?? '').toString(),
    // Default true: para usuarios viejos que no tienen el flag
    // guardado, asumimos que ganan comisiones (comportamiento previo).
    // Solo se vuelve false si el admin explícitamente lo desactiva.
    ganaComisiones: m['gana_comisiones'] == null
        ? true
        : (m['gana_comisiones'].toString() == '1' ||
           m['gana_comisiones'].toString().toLowerCase() == 'true'));

  Map<String,dynamic> toMap() => {'nombre':nombre,'cedula':cedula,'correo':correo,
    'clave':clave,'rol':rol,'sueldo_base':sueldoBase,'tienda':tienda,
    'gana_comisiones': ganaComisiones ? 1 : 0};
}

// ── SERVICIO TÉCNICO ──────────────────────────────────────────
// Representa una orden de servicio técnico tal como aparece en la
// planilla física: datos del cliente, equipo, checklist de componentes
// recibidos, diagnóstico y estado de pago.
class ServicioTecnico {
  int? id;

  // ── Cabecera / montos ─────────────────────────────────────
  double monto;           // Monto total del servicio (lo que se cobra al cliente)
  double abono;           // Abono inicial del cliente
  double costoRepuestos;  // Costo de los repuestos/insumos usados (lo que GASTÓ el negocio)
  double get resta => (monto - abono).clamp(0, double.infinity);
  /// Ganancia neta del servicio: lo cobrado al cliente menos lo gastado
  /// en repuestos. Si todavía no se ha cargado el costo, devuelve `monto`.
  double get ganancia => monto - costoRepuestos;
  bool pagado;            // Si está completamente pagado

  // ── Fechas ────────────────────────────────────────────────
  final DateTime fecha;   // Fecha de recepción
  String horaRecibido;    // Hora en que se recibió el equipo
  String fechaEntrega;    // Fecha estimada/real de entrega (texto libre)

  // ── Cliente ───────────────────────────────────────────────
  String nombreCliente;
  String telefono;
  String rifCi;           // RIF o Cédula

  // ── Equipo ────────────────────────────────────────────────
  String modelo;
  String marca;
  String descripcion;     // Descripción del problema / motivo
  String imei;
  String contrasena;      // Patrón o PIN para que el técnico pueda probar

  // ── Checklist de componentes (cada uno: true=SI, false=NO, null=no revisado) ──
  // Columna izquierda
  bool? chip, memoria, bateria, tapa;
  bool? encendido, apagado, camara, corneta;
  bool? flash, flashConDefecto;
  // Columna derecha
  bool? tactilPartido, auricular, microfono, contrasenaChk;
  bool? track, botonVolumen, teclado, botonEncendido, pantallaConDefecto;

  // ── Notas finales ─────────────────────────────────────────
  String observacion;
  String tecnico;
  String estado; // Recibido, En reparación, Listo, Entregado

  /// Fotos del equipo al momento de la recepción. Se guardan como
  /// strings base64 (data URI o data crudo). El backend las persiste
  /// dentro del bloque __META__ de la descripción, así que no
  /// requieren columna extra. Útil para dejar constancia visual de
  /// rayones, manchas o piezas faltantes al recibir el equipo.
  List<String> fotosRecepcion;

  ServicioTecnico({
    this.id,
    required this.monto,
    required this.fecha,
    this.abono = 0,
    this.costoRepuestos = 0,
    this.pagado = false,
    this.horaRecibido = '',
    this.fechaEntrega = '',
    this.nombreCliente = '',
    this.telefono = '',
    this.rifCi = '',
    this.modelo = '',
    this.marca = '',
    this.descripcion = '',
    this.imei = '',
    this.contrasena = '',
    this.chip, this.memoria, this.bateria, this.tapa,
    this.encendido, this.apagado, this.camara, this.corneta,
    this.flash, this.flashConDefecto,
    this.tactilPartido, this.auricular, this.microfono, this.contrasenaChk,
    this.track, this.botonVolumen, this.teclado, this.botonEncendido,
    this.pantallaConDefecto,
    this.observacion = '',
    this.tecnico = '',
    this.estado = 'Recibido',
    List<String>? fotosRecepcion,
  }) : fotosRecepcion = fotosRecepcion ?? [];

  /// Alias retro-compatible con el campo "nota" original.
  /// Combina descripción + observación para la vista de lista.
  String get nota {
    final parts = <String>[];
    if (descripcion.isNotEmpty) parts.add(descripcion);
    if (observacion.isNotEmpty) parts.add('Obs: $observacion');
    return parts.join(' · ');
  }

  factory ServicioTecnico.fromMap(Map<String, dynamic> m) {
    // Helper: convierte un valor numérico o booleano opcional a bool?
    // 1 → true, 0 → false, null/vacío → null
    bool? _bn(dynamic v) {
      if (v == null) return null;
      if (v is bool) return v;
      final s = v.toString().trim();
      if (s.isEmpty || s == 'null') return null;
      if (s == '1' || s.toLowerCase() == 'true' || s.toLowerCase() == 'si') return true;
      if (s == '0' || s.toLowerCase() == 'false' || s.toLowerCase() == 'no') return false;
      return null;
    }

    // Helper: devuelve el primer valor no-null/no-vacío entre varias claves.
    // Útil cuando el backend responde con nombres de columna que varían
    // según la versión de la API (p.ej. 'nombre_cliente' vs 'cliente',
    // 'rif_ci' vs 'cedula', 'hora_recibido' vs 'horaRecibido', etc.).
    String _pickStr(List<String> keys) {
      for (final k in keys) {
        final v = m[k];
        if (v == null) continue;
        final s = v.toString();
        if (s.trim().isNotEmpty) return s;
      }
      return '';
    }

    // ═══════════════════════════════════════════════════════════
    //  DESEMPAQUETADO DEL BLOQUE __META__
    //  El backend no guarda varios campos (cédula, marca, modelo,
    //  contraseña, hora_recibido, fecha_entrega, checklist). Para
    //  persistirlos igualmente sin tocar el backend, los empaquetamos
    //  como JSON al INICIO del campo `descripcion` (que SÍ se guarda)
    //  con la marca `__META__{...}\n---\n`.
    //
    //  Al leer, detectamos esa marca, extraemos el JSON y dejamos en
    //  `descripcion` solo el texto real (lo que viene después de `---`).
    //  Si no hay marca, se lee la descripción tal cual.
    // ═══════════════════════════════════════════════════════════
    String descripcionRaw = _pickStr(['descripcion', 'nota']);
    Map<String, dynamic> meta = const {};
    String descripcionLimpia = descripcionRaw;

    if (descripcionRaw.startsWith('__META__')) {
      // Buscar el separador `\n---\n` o `\n---` al final de la línea META
      final idx = descripcionRaw.indexOf('\n---');
      if (idx > 0) {
        final jsonStr = descripcionRaw.substring('__META__'.length, idx);
        // Lo que viene después del separador es la descripción real
        final resto = descripcionRaw.substring(idx + '\n---'.length);
        descripcionLimpia = resto.startsWith('\n')
            ? resto.substring(1)
            : resto;
        try {
          final parsed = jsonDecode(jsonStr);
          if (parsed is Map) meta = Map<String, dynamic>.from(parsed);
        } catch (_) {
          // JSON corrupto: conservamos la descripción original completa
          descripcionLimpia = descripcionRaw;
        }
      }
    }

    // Helper: lee un bool? del META checklist
    bool? _metaBn(String key) {
      final chk = meta['chk'];
      if (chk is! Map) return null;
      return _bn(chk[key]);
    }

    // Helper: lee un string del META con fallback a las columnas sueltas
    // (así si algún día el backend sí empieza a guardar esos campos,
    // la lectura sigue funcionando).
    String _metaOrCol(String metaKey, List<String> colKeys) {
      final v = meta[metaKey];
      if (v != null && v.toString().trim().isNotEmpty) return v.toString();
      return _pickStr(colKeys);
    }

    return ServicioTecnico(
      id: m['id'] is int ? m['id'] : int.tryParse(m['id']?.toString() ?? ''),
      monto: double.tryParse(m['monto'].toString()) ?? 0,
      abono: double.tryParse(m['abono']?.toString() ?? '0') ?? 0,
      // Costo de repuestos: empaquetado en META (el backend no tiene
      // columna propia). Si el JSON META no lo tiene, queda en 0.
      costoRepuestos: double.tryParse(
        (meta['costoRepuestos'] ?? m['costo_repuestos'] ?? '0').toString()) ?? 0,
      pagado: (m['pagado'] ?? 0) == 1 || m['pagado'] == true,
      fecha: DateTime.tryParse(m['fecha'] ?? '') ?? DateTime.now(),

      // Campos empaquetados en META (con fallback a columnas, por si
      // el backend las guarda realmente en alguna instalación).
      horaRecibido  : _metaOrCol('hora',     ['hora_recibido', 'horaRecibido', 'hora']),
      fechaEntrega  : _metaOrCol('entrega',  ['fecha_entrega', 'fechaEntrega', 'entrega']),
      rifCi         : _metaOrCol('rif',      ['rif_ci', 'rifCi', 'rif', 'ci', 'cedula']),
      marca         : _metaOrCol('marca',    ['marca']),
      modelo        : _metaOrCol('modelo',   ['modelo']),
      contrasena    : _metaOrCol('pass',     ['contrasena', 'password']),

      // Campos que el backend sí guarda normalmente
      nombreCliente: _pickStr(['nombre_cliente', 'nombreCliente', 'cliente', 'nombre']),
      telefono: _pickStr(['telefono']),
      descripcion: descripcionLimpia.trim(),
      imei: _pickStr(['imei']),

      // Checklist: primero intentar del META, luego de columnas (fallback)
      chip:              _metaBn('chip')            ?? _bn(m['chip']),
      memoria:           _metaBn('memoria')         ?? _bn(m['memoria']),
      bateria:           _metaBn('bateria')         ?? _bn(m['bateria']),
      tapa:              _metaBn('tapa')            ?? _bn(m['tapa']),
      encendido:         _metaBn('encendido')       ?? _bn(m['encendido']),
      apagado:           _metaBn('apagado')         ?? _bn(m['apagado']),
      camara:            _metaBn('camara')          ?? _bn(m['camara']),
      corneta:           _metaBn('corneta')         ?? _bn(m['corneta']),
      flash:             _metaBn('flash')           ?? _bn(m['flash']),
      flashConDefecto:   _metaBn('flashDef')        ?? _bn(m['flash_con_defecto']),
      tactilPartido:     _metaBn('tactilPart')      ?? _bn(m['tactil_partido']),
      auricular:         _metaBn('auricular')       ?? _bn(m['auricular']),
      microfono:         _metaBn('microfono')       ?? _bn(m['microfono']),
      contrasenaChk:     _metaBn('passChk')         ?? _bn(m['contrasena_chk']),
      track:             _metaBn('track')           ?? _bn(m['track']),
      botonVolumen:      _metaBn('btnVol')          ?? _bn(m['boton_volumen']),
      teclado:           _metaBn('teclado')         ?? _bn(m['teclado']),
      botonEncendido:    _metaBn('btnEnc')          ?? _bn(m['boton_encendido']),
      pantallaConDefecto:_metaBn('pantallaDef')     ?? _bn(m['pantalla_con_defecto']),

      observacion: _pickStr(['observacion', 'observaciones']),
      tecnico: _pickStr(['tecnico']),
      estado: _pickStr(['estado']).isEmpty ? 'Recibido' : _pickStr(['estado']),
      // Fotos del meta (lista de strings base64). Si no hay, lista vacía.
      fotosRecepcion: (meta['fotos'] is List)
          ? List<String>.from(
              (meta['fotos'] as List).map((e) => e.toString()))
          : <String>[],
    );
  }

  Map<String, dynamic> toMap() {
    // Helper: serializa bool? como 1/0/null
    int? _bi(bool? v) => v == null ? null : (v ? 1 : 0);

    // ═══════════════════════════════════════════════════════════
    //  EMPAQUETADO DE CAMPOS NO PERSISTIDOS
    //  El backend solo guarda un subconjunto de columnas
    //  (monto, abono, pagado, fecha, telefono, imei, descripcion,
    //   nombre_cliente, observacion, tecnico, estado, nota).
    //  Los campos que no tienen columna propia los empaquetamos
    //  como JSON al inicio del campo `descripcion` con la marca
    //  `__META__{...}\n---\n`. Al releer se desempaquetan.
    // ═══════════════════════════════════════════════════════════
    final meta = <String, dynamic>{
      'rif'       : rifCi,
      'marca'     : marca,
      'modelo'    : modelo,
      'pass'      : contrasena,
      'hora'      : horaRecibido,
      'entrega'   : fechaEntrega,
      // Costo de repuestos: lo gastado en reparar este equipo.
      // El backend no tiene columna dedicada; lo guardamos aquí.
      'costoRepuestos': costoRepuestos,
      // Fotos de recepción (lista de base64). Cada foto deja
      // constancia del estado del equipo al recibirlo.
      'fotos': fotosRecepcion,
      'chk'       : {
        'chip'        : _bi(chip),
        'memoria'     : _bi(memoria),
        'bateria'     : _bi(bateria),
        'tapa'        : _bi(tapa),
        'encendido'   : _bi(encendido),
        'apagado'     : _bi(apagado),
        'camara'      : _bi(camara),
        'corneta'     : _bi(corneta),
        'flash'       : _bi(flash),
        'flashDef'    : _bi(flashConDefecto),
        'tactilPart'  : _bi(tactilPartido),
        'auricular'   : _bi(auricular),
        'microfono'   : _bi(microfono),
        'passChk'     : _bi(contrasenaChk),
        'track'       : _bi(track),
        'btnVol'      : _bi(botonVolumen),
        'teclado'     : _bi(teclado),
        'btnEnc'      : _bi(botonEncendido),
        'pantallaDef' : _bi(pantallaConDefecto),
      },
    };

    // Construir el campo descripción con META al inicio y la
    // descripción real después del separador.
    final descPersistida =
        '__META__${jsonEncode(meta)}\n---\n${descripcion.trim()}';

    return {
      // ── Montos / pago ──
      'monto': monto,
      'abono': abono,
      // Costo de repuestos: lo enviamos también como columna por si
      // el backend la tiene/agrega en el futuro. La fuente de verdad
      // sigue siendo el bloque META (ver arriba).
      'costo_repuestos': costoRepuestos,
      'pagado': pagado ? 1 : 0,

      // ── Fecha base ──
      'fecha': fecha.toIso8601String(),

      // ── Cliente: nombre y teléfono se guardan normalmente en sus columnas.
      //    La cédula/RIF va empaquetada en META. Enviamos igual las variantes
      //    por si el backend sí las acepta en columnas reales.
      'nombre_cliente': nombreCliente,
      'nombreCliente' : nombreCliente,
      'cliente'       : nombreCliente,
      'nombre'        : nombreCliente,
      'telefono'      : telefono,
      // Enviamos también RIF sueltos por si hay columna; el dato "de verdad"
      // viaja en META, así que no depende de esto.
      'rif_ci': rifCi,
      'rifCi' : rifCi,
      'cedula': rifCi,

      // ── Equipo: descripción lleva META + texto real ──
      'descripcion': descPersistida,
      'nota'       : descPersistida,  // alias para APIs viejas
      'imei'       : imei,

      // También enviamos marca/modelo/hora/entrega/contrasena sueltos por
      // si el backend SÍ los acepta en columnas reales; si no, al menos
      // quedan en META dentro de `descripcion`.
      'marca'        : marca,
      'modelo'       : modelo,
      'hora_recibido': horaRecibido,
      'fecha_entrega': fechaEntrega,
      'contrasena'   : contrasena,

      // ── Checklist: también enviamos las columnas sueltas como fallback ──
      'chip': _bi(chip),
      'memoria': _bi(memoria),
      'bateria': _bi(bateria),
      'tapa': _bi(tapa),
      'encendido': _bi(encendido),
      'apagado': _bi(apagado),
      'camara': _bi(camara),
      'corneta': _bi(corneta),
      'flash': _bi(flash),
      'flash_con_defecto': _bi(flashConDefecto),
      'tactil_partido': _bi(tactilPartido),
      'auricular': _bi(auricular),
      'microfono': _bi(microfono),
      'contrasena_chk': _bi(contrasenaChk),
      'track': _bi(track),
      'boton_volumen': _bi(botonVolumen),
      'teclado': _bi(teclado),
      'boton_encendido': _bi(botonEncendido),
      'pantalla_con_defecto': _bi(pantallaConDefecto),

      // ── Notas finales ──
      'observacion': observacion,
      'tecnico': tecnico,
      'estado': estado,
    };
  }
}

// ── FACTURA ───────────────────────────────────────────────────
class PagoFactura {
  final String metodo, tipo;
  /// FINANCIADOR = la persona/usuario que entrega el equipo al cliente.
  /// Es un nombre de usuario del sistema. Puede ser null si no aplica.
  final String? financiador;
  /// FINANCIADORA = la aplicación con la que el cliente se lleva el
  /// equipo (Cashea / Weppa / Krece). Viene del dropdown F/D.
  /// El Reporte por Financiadora se agrupa por ESTE campo.
  final String? financiadora;
  final double monto;

  // ── Datos extra para Pago Móvil (todos opcionales) ────────────
  // Se llenan SOLO cuando el método es "Pago Móvil". Para los demás
  // métodos quedan en null y el backend los ignora.
  /// Código SUDEBAN (4 dígitos) del banco DESTINO del pago móvil
  /// — la cuenta del comercio donde llega el dinero. Sólo aplica a
  /// Pago Móvil. "0102" = Banco de Venezuela (único que admite
  /// conciliación API).
  final String? bancoDestino;
  /// Código SUDEBAN del banco ORIGEN (de donde sale el dinero).
  final String? bancoOrigen;
  /// Referencia del pago móvil (la que aparece en el SMS / App).
  final String? referencia;
  /// Cédula del pagador con letra ("V12345678" / "E12345678" / "J...").
  final String? cedulaPagador;
  /// Teléfono celular asociado al pago.
  final String? telefonoPagador;
  /// Teléfono celular destino registrado en PagomóvilBDV.
  final String? telefonoDestino;
  /// Fecha del pago en formato "YYYY-MM-DD".
  final String? fechaPago;

  /// true si el vendedor marcó este pago como la INICIAL que el
  /// cliente paga de su bolsillo. El reporte por financiadora usa
  /// este flag para saber exactamente qué monto restar como inicial
  /// en la fórmula (Base − Inicial) − 3.5% = Deuda. Si ningún pago
  /// está marcado, el reporte cae al criterio anterior (pagos de
  /// tipo "Contado" o sin financiador).
  final bool esInicial;

  // ── Resultado de la conciliación con BDV ──────────────────────
  /// true si la conciliación con BDV devolvió code 1000 (transacción
  /// localizada). false si devolvió otro código o falló la red. null
  /// si nunca se intentó conciliar (por ejemplo banco distinto a BDV
  /// o conciliación deshabilitada en el panel admin).
  final bool? conciliadoBDV;
  /// Código de respuesta del API BDV (1000 OK, 1010 no existe, etc).
  final int? codigoConciliacion;
  /// Mensaje completo devuelto por el API BDV (para auditoría).
  final String? mensajeConciliacion;

  /// ── DATOS DE FINANCIAMIENTO ──────────────────────────────────
  /// Número de cuotas pactadas con la financiadora (3, 4, 6, etc.).
  /// Solo se llena cuando tipo == 'Financiado'.
  final int? numeroCuotas;
  /// Monto de cada cuota en USD. Solo se llena cuando tipo == 'Financiado'.
  final double? montoCuota;
  /// Tasa Bs/USD al momento de crear el pago. Se guarda para que el
  /// equivalente USD en la factura se MANTENGA con esta tasa histórica
  /// aunque la tasa del sistema cambie después.
  final double? tasaCambio;
  /// Nombre de la lista de precios que se usó al facturar el equipo
  /// con esta financiadora. Permite distinguir entre la lista normal
  /// y listas de promoción (ej. "Cashea Black Friday"). El reporte
  /// por financiadora usa este nombre para encontrar el precio CORRECTO
  /// de la lista que se aplicó, no cualquier lista de la financiadora.
  final String? nombreLista;

  PagoFactura({
    required this.metodo,
    required this.monto,
    required this.tipo,
    this.financiador,
    this.financiadora,
    this.bancoDestino,
    this.bancoOrigen,
    this.referencia,
    this.cedulaPagador,
    this.telefonoPagador,
    this.telefonoDestino,
    this.fechaPago,
    this.esInicial = false,
    this.conciliadoBDV,
    this.codigoConciliacion,
    this.mensajeConciliacion,
    this.numeroCuotas,
    this.montoCuota,
    this.tasaCambio,
    this.nombreLista,
  });

  factory PagoFactura.fromMap(Map<String,dynamic> m) => PagoFactura(
    metodo: m['metodo']??'', tipo: m['tipo']??'',
    financiador: m['financiador'],
    financiadora: m['financiadora'] as String?,
    monto: double.tryParse(m['monto'].toString())??0,
    // _strONull en vez de `as String?`: el backend puede devolver la
    // referencia o el teléfono como número y el cast reventaba.
    bancoDestino       : _strONull(m['banco_destino']),
    bancoOrigen        : _strONull(m['banco_origen']),
    referencia         : _strONull(m['referencia']),
    cedulaPagador      : _strONull(m['cedula_pagador']),
    telefonoPagador    : _strONull(m['telefono_pagador']),
    telefonoDestino    : _strONull(m['telefono_destino']),
    fechaPago          : _strONull(m['fecha_pago']),
    esInicial          : m['es_inicial'] == true || m['es_inicial'] == 1
        || m['es_inicial'].toString() == '1'
        || m['es_inicial'].toString().toLowerCase() == 'true',
    conciliadoBDV      : m['conciliado_bdv'] == null
        ? null
        : (m['conciliado_bdv'] == true || m['conciliado_bdv'] == 1
            || m['conciliado_bdv'].toString() == '1'
            || m['conciliado_bdv'].toString().toLowerCase() == 'true'),
    codigoConciliacion : m['codigo_conciliacion'] == null
        ? null
        : int.tryParse(m['codigo_conciliacion'].toString()),
    mensajeConciliacion: m['mensaje_conciliacion'] as String?,
    numeroCuotas       : m['numero_cuotas'] == null
        ? null
        : int.tryParse(m['numero_cuotas'].toString()),
    montoCuota         : m['monto_cuota'] == null
        ? null
        : double.tryParse(m['monto_cuota'].toString()),
    tasaCambio         : m['tasa_cambio'] == null
        ? null
        : double.tryParse(m['tasa_cambio'].toString()),
    nombreLista        : m['nombre_lista'] as String?,
  );

  Map<String,dynamic> toMap() => {
    'metodo':metodo,'tipo':tipo,'financiador':financiador,'monto':monto,
    'financiadora': financiadora,
    'es_inicial': esInicial,
    // Sólo se incluyen los campos extra si el método es Pago Móvil
    // (evita ensuciar el JSON de los pagos en efectivo, transferencia, etc).
    if (bancoDestino        != null) 'banco_destino'        : bancoDestino,
    if (bancoOrigen         != null) 'banco_origen'         : bancoOrigen,
    if (referencia          != null) 'referencia'           : referencia,
    if (cedulaPagador       != null) 'cedula_pagador'       : cedulaPagador,
    if (telefonoPagador     != null) 'telefono_pagador'     : telefonoPagador,
    if (telefonoDestino     != null) 'telefono_destino'     : telefonoDestino,
    if (fechaPago           != null) 'fecha_pago'           : fechaPago,
    if (conciliadoBDV       != null) 'conciliado_bdv'       : conciliadoBDV,
    if (codigoConciliacion  != null) 'codigo_conciliacion'  : codigoConciliacion,
    if (mensajeConciliacion != null) 'mensaje_conciliacion' : mensajeConciliacion,
    if (numeroCuotas        != null) 'numero_cuotas'        : numeroCuotas,
    if (montoCuota          != null) 'monto_cuota'          : montoCuota,
    if (tasaCambio          != null) 'tasa_cambio'          : tasaCambio,
    if (nombreLista         != null) 'nombre_lista'         : nombreLista,
  };
}

class FacturaModel {
  int? id;
  final String cliente, cedula, telefono, nroFactura, vendedor, fecha, tienda;
  final List<ImeiRegistro> equipos;
  final List<Producto> itemsSinImei;
  final List<PagoFactura> pagos;
  /// Vendedor asignado a cada IMEI (Map imei → nombre del vendedor).
  /// Si un IMEI no aparece o el valor es null/vacío, el vendedor del
  /// producto es el creador de la factura (campo `vendedor` arriba).
  /// Esto permite tener varios vendedores en una sola factura (ej: el
  /// cajero factura, pero cada equipo va a su comisionista).
  final Map<String, String?> vendedorPorImei;
  /// Lo mismo pero para items sin IMEI: Map código → nombre del vendedor.
  final Map<String, String?> vendedorPorCodigo;
  /// Rol del creador al momento de facturar (Cajero/Vendedor/Administrador).
  /// Se usa en el cálculo de comisiones para detectar el "split cajero".
  /// Si está vacío, se asume el rol actual del usuario en `vendedor`.
  final String creadorRol;

  FacturaModel({this.id, required this.cliente, required this.cedula,
      required this.tienda, required this.telefono, required this.nroFactura,
      required this.equipos, required this.itemsSinImei, required this.pagos,
      required this.vendedor, required this.fecha,
      Map<String, String?>? vendedorPorImei,
      Map<String, String?>? vendedorPorCodigo,
      this.creadorRol = ''})
      : vendedorPorImei = vendedorPorImei ?? {},
        vendedorPorCodigo = vendedorPorCodigo ?? {};

  double get total => pagos.fold(0.0,(s,p) => s + p.monto);

  /// Devuelve el nombre del vendedor que tiene asignado el equipo con
  /// Devuelve el nombre del vendedor asignado a un IMEI específico.
  ///
  /// CAMBIO IMPORTANTE: si no hay vendedor asignado explícitamente al
  /// equipo, devuelve string vacío. ANTES devolvía `vendedor` (el
  /// creador de la factura), lo que provocaba que el creador cobrara
  /// comisión por productos sin vendedor asignado. Ahora un vendedor
  /// vacío indica "no asignado" y el módulo de comisiones NO le paga
  /// a nadie por ese producto — que es la regla correcta.
  String vendedorDeEquipo(String imei) {
    final asignado = vendedorPorImei[imei];
    if (asignado != null && asignado.isNotEmpty) return asignado;
    return '';
  }

  /// Devuelve el nombre del vendedor del item sin IMEI (por código).
  /// Mismo criterio que `vendedorDeEquipo`: si no hay asignación
  /// explícita, devuelve vacío (no el creador). Comisión no se paga.
  String vendedorDeItem(String codigo) {
    final asignado = vendedorPorCodigo[codigo];
    if (asignado != null && asignado.isNotEmpty) return asignado;
    return '';
  }

  Map<String,dynamic> toApiMap() => {
    'nro_factura':nroFactura,'cedula':cedula,'cliente':cliente,'telefono':telefono,
    'vendedor':vendedor,'tienda':tienda,'fecha':fecha,'total':total,
    'creador_rol':creadorRol,
    // Equipos/items ahora se mandan como objetos con su vendedor asignado.
    // Si vendedorPorImei[imei] es null o vacío, el backend lo guarda como
    // null y el reporte cae al creador.
    'equipos': equipos.map((e) => {
      'imei': e.imei,
      'vendedor': vendedorPorImei[e.imei] ?? '',
    }).toList(),
    'items': itemsSinImei.map((p) => {
      'codigo': p.codigo,
      'vendedor': vendedorPorCodigo[p.codigo] ?? '',
    }).toList(),
    'pagos':pagos.map((p) => p.toMap()).toList()};
}

/// Parser de fecha flexible que acepta:
///   · "dd/MM/yyyy"           (formato local, como guarda la app)
///   · "dd-MM-yyyy"
///   · "yyyy-MM-dd"           (ISO, como puede venir del backend)
///   · "yyyy-MM-dd HH:mm:ss"  (DATETIME MySQL)
///   · "yyyy-MM-ddTHH:mm:ss"  (ISO completo)
/// Devuelve null si no puede parsearla.
DateTime? parseFechaFlexible(String? texto) {
  if (texto == null) return null;
  final s = texto.trim();
  if (s.isEmpty) return null;

  // Intento 1: ISO directo
  final iso = DateTime.tryParse(s);
  if (iso != null) return iso;

  // Intento 2: dd/MM/yyyy o dd-MM-yyyy (con separador / o -)
  final m = RegExp(r'^(\d{1,2})[/\-](\d{1,2})[/\-](\d{4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?$').firstMatch(s);
  if (m != null) {
    final d  = int.tryParse(m.group(1) ?? '') ?? 1;
    final mo = int.tryParse(m.group(2) ?? '') ?? 1;
    final y  = int.tryParse(m.group(3) ?? '') ?? 1970;
    final h  = int.tryParse(m.group(4) ?? '0') ?? 0;
    final mi = int.tryParse(m.group(5) ?? '0') ?? 0;
    final se = int.tryParse(m.group(6) ?? '0') ?? 0;
    return DateTime(y, mo, d, h, mi, se);
  }
  return null;
}

// ── EXTRACCIÓN ────────────────────────────────────────────────
class Extraccion {
  int? id;
  final String metodo, monto, motivo, fecha;
  Extraccion({this.id, required this.metodo, required this.monto, required this.motivo, required this.fecha});
  factory Extraccion.fromMap(Map<String,dynamic> m) => Extraccion(
    id: m['id'] is int ? m['id'] : int.tryParse(m['id']?.toString() ?? ''), metodo: m['metodo']??'', monto: m['monto']??'',
    motivo: m['motivo']??'', fecha: m['fecha']??'');
  Map<String,dynamic> toMap() => {'metodo':metodo,'monto':monto,'motivo':motivo,'fecha':fecha};
}

// ── CIERRE DE CAJA ────────────────────────────────────────────
class CierreCaja {
  final int? idDb;
  final String id, tienda, usuarioCierre;
  final DateTime fecha;
  final double montoTotal;
  final Map<String,double> metodosPago;

  CierreCaja({this.idDb, required this.id, required this.fecha, required this.tienda,
      required this.montoTotal, required this.usuarioCierre, required this.metodosPago});

  factory CierreCaja.fromMap(Map<String,dynamic> m) {
    final mets = <String,double>{};
    for (final met in (m['metodos'] as List? ?? [])) {
      mets[met['metodo']] = double.tryParse(met['monto'].toString())??0;
    }
    return CierreCaja(idDb: m['id'], id: m['uid']??'', tienda: m['tienda']??'',
      usuarioCierre: m['usuario_cierre']??'',
      fecha: DateTime.tryParse(m['fecha']??'')??DateTime.now(),
      montoTotal: double.tryParse(m['monto_total'].toString())??0, metodosPago: mets);
  }
  Map<String,dynamic> toApiMap() => {'uid':id,'tienda':tienda,'monto_total':montoTotal,
    'usuario_cierre':usuarioCierre,
    'metodos':metodosPago.entries.map((e) => {'metodo':e.key,'monto':e.value}).toList()};
}

// ── COMISIONES ────────────────────────────────────────────────
//
// El sistema de comisiones se basa en CATEGORÍAS DINÁMICAS:
// el administrador puede agregar/editar/eliminar categorías
// (ej: Accesorio, Teléfono, Servicio Técnico, etc.) desde el
// panel de configuración.
//
// Cada categoría tiene un "tipo de conteo" que determina cómo
// se cuenta: por categoría de producto vendido, por servicios
// técnicos pagados, por venta financiada con cierto financiador,
// o por porcentaje sobre ventas Weppa.
//
// Las 6 categorías originales (Accesorio, Teléfono, Línea,
// Televisor, Línea Blanca, Financiador) están "protegidas" — no
// se pueden eliminar, pero sí editar tarifa. Las nuevas que
// agregue el usuario son borrables.

/// Tipo de conteo de una categoría de comisión: define qué se cuenta
/// como "una unidad" para multiplicarla por la tarifa USD.
enum TipoConteoComision {
  /// Cuenta cada equipo/item vendido cuya categoría coincida con
  /// `valorConteo` (ej: "Accesorio", "Telefono", "Televisor",
  /// "Linea Blanca", "Servicio Tecnico"...).
  categoriaProducto,
  /// Cuenta cada activación de línea telefónica de la venta
  /// (independiente de la categoría del producto).
  lineaTelefonica,
  /// Cuenta cada venta financiada cuyo `financiador` se asigne a
  /// este vendedor — típicamente aplica al "vendedor financiador".
  ventaFinanciada,
  /// Cuenta cada servicio técnico ENTREGADO/PAGADO en el rango,
  /// atribuyéndolo al técnico de la ficha. La tarifa USD se aplica
  /// como una cantidad fija por servicio (igual que un producto).
  servicioTecnico,
  /// No usa tarifa fija: aplica un % sobre el precio de venta de
  /// cada producto vendido en una factura financiada con Weppa.
  /// El % se toma de la lista Weppa, no del campo `tarifaUSD`.
  porcentajeWeppa,
}

extension TipoConteoComisionX on TipoConteoComision {
  String get clave => toString().split('.').last;
  static TipoConteoComision desdeString(String s) {
    return TipoConteoComision.values.firstWhere(
      (t) => t.clave == s,
      orElse: () => TipoConteoComision.categoriaProducto);
  }
  String get descripcion {
    switch (this) {
      case TipoConteoComision.categoriaProducto:
        return 'Por cada producto vendido de cierta categoría';
      case TipoConteoComision.lineaTelefonica:
        return 'Por cada línea telefónica activada';
      case TipoConteoComision.ventaFinanciada:
        return 'Por cada venta financiada gestionada';
      case TipoConteoComision.servicioTecnico:
        return 'Por cada servicio técnico pagado/entregado';
      case TipoConteoComision.porcentajeWeppa:
        return 'Porcentaje sobre ventas Weppa (no usa tarifa fija)';
    }
  }
}

/// Modelo de una categoría de comisión configurable.
// ════════════════════════════════════════════════════════════
//  CATEGORÍAS DE PRODUCTOS (editables y persistidas)
// ════════════════════════════════════════════════════════════
//  Lista global y editable de categorías que se usan al crear
//  productos. De aquí también nacen las categorías de comisión:
//  cuando se agrega una categoría nueva acá, automáticamente se
//  crea (si no existía) una entrada equivalente en `categoriasGlobal`
//  de comisiones, lista para que el admin le configure la tarifa.
/// Modelo de una categoría de producto con configuración de IMEI.
///
/// Antes las categorías eran solo `List<String>`. Ahora cada categoría
/// guarda también si los productos de esa categoría requieren IMEI
/// (número de serie único por unidad). Por defecto solo "Telefono" lo
/// requiere; las demás no, pero el admin puede activarlo en categorías
/// como "Tablet", "Laptop", etc. desde la pantalla de Inventario.
class CategoriaProducto {
  String nombre;
  bool usaIMEI;
  CategoriaProducto({required this.nombre, this.usaIMEI = false});
  Map<String, dynamic> toMap() => {
    'nombre': nombre,
    'usa_imei': usaIMEI,
  };
  factory CategoriaProducto.fromMap(Map<String, dynamic> m) =>
      CategoriaProducto(
        nombre: '${m['nombre'] ?? ''}',
        usaIMEI: m['usa_imei'] == true || m['usa_imei'] == 1,
      );
}

class CategoriasProductos {
  /// Lista en memoria. Por defecto trae las 6 originales del sistema.
  /// "Telefono" tiene IMEI activado por defecto. Las demás categorías
  /// nuevas o existentes pueden activar/desactivar IMEI desde Inventario.
  static List<CategoriaProducto> listaObjetos = [
    CategoriaProducto(nombre: 'Telefono', usaIMEI: true),
    CategoriaProducto(nombre: 'Accesorio'),
    CategoriaProducto(nombre: 'Televisor'),
    CategoriaProducto(nombre: 'Linea Blanca'),
    CategoriaProducto(nombre: 'Linea'),
    CategoriaProducto(nombre: 'Servicio Tecnico'),
  ];

  /// Compatibilidad — la lista de nombres legacy. Muchos lugares del
  /// código usan `CategoriasProductos.lista` como `List<String>` para
  /// dropdowns y filtros. Esta getter mantiene esa interfaz.
  static List<String> get lista =>
      listaObjetos.map((c) => c.nombre).toList();

  static set lista(List<String> nombres) {
    listaObjetos = nombres
        .map((n) => CategoriaProducto(
              nombre: n,
              usaIMEI: n.toLowerCase() == 'telefono',
            ))
        .toList();
  }

  /// Devuelve true si la categoría dada usa IMEI (requiere número de
  /// serie único por unidad). Función central — usar en todos los
  /// lugares en lugar de `categoria == 'Telefono'` para que el toggle
  /// funcione con cualquier categoría.
  static bool usaIMEI(String? categoria) {
    if (categoria == null) return false;
    final c = listaObjetos.firstWhere(
        (x) => x.nombre.toLowerCase() == categoria.toLowerCase(),
        orElse: () => CategoriaProducto(nombre: ''));
    return c.usaIMEI ||
        _categoriasConSeriales.contains(categoria.trim().toLowerCase());
  }

  /// Categorías que tienen al menos un serial/IMEI cargado en la BD.
  ///
  /// El interruptor "usa IMEI" de cada categoría se guardaba SOLO en el
  /// dispositivo donde se activó. En cualquier otro equipo (o tras
  /// reinstalar) la categoría volvía a contarse por `stock_manual`, que
  /// para productos con serial es 0: un televisor con 7 seriales
  /// cargados aparecía con existencia 0 y ni siquiera salía en ventas.
  ///
  /// Los datos mandan: si la categoría tiene seriales registrados, se
  /// cuenta por seriales en todos los dispositivos.
  static Set<String> _categoriasConSeriales = {};

  static void registrarCategoriasConSeriales(List<ImeiRegistro> imeis) {
    _categoriasConSeriales = {
      for (final i in imeis)
        if (i.producto.categoria.trim().isNotEmpty)
          i.producto.categoria.trim().toLowerCase(),
    };
  }

  static const String _claveBackend = 'cfg_categorias_productos';
  static const String _prefsSincronizado = 'categorias_productos_sync';

  /// Comparte la lista de categorías (y su interruptor de IMEI) entre
  /// todos los dispositivos usando el endpoint `configuracion`.
  ///
  ///  · La primera vez que un dispositivo sincroniza, FUSIONA lo suyo
  ///    con lo del servidor (une las categorías y deja el IMEI activo
  ///    si lo estaba en cualquiera de los dos) y sube el resultado. Así
  ///    no se pierde lo que cada equipo tenía configurado por su lado.
  ///  · Después manda el servidor: lo que se cambie en un equipo llega
  ///    a los demás en su próximo inicio.
  static Future<void> sincronizarConBackend() async {
    try {
      final raw = await _Api.get('configuracion');
      final prefs = await SharedPreferences.getInstance();
      final yaSincronizado = prefs.getBool(_prefsSincronizado) ?? false;

      List<CategoriaProducto> remotas = [];
      final texto = raw is Map ? (raw[_claveBackend] ?? '').toString() : '';
      if (texto.isNotEmpty) {
        remotas = (jsonDecode(texto) as List)
            .whereType<Map>()
            .map((m) => CategoriaProducto.fromMap(
                m.map((k, v) => MapEntry(k.toString(), v))))
            .where((c) => c.nombre.trim().isNotEmpty)
            .toList();
      }

      if (remotas.isNotEmpty && yaSincronizado) {
        listaObjetos = remotas;
        await _guardarLocal();
        return;
      }

      // Primera sincronización de este dispositivo: fusionar y subir.
      for (final r in remotas) {
        final idx = listaObjetos.indexWhere(
            (c) => c.nombre.toLowerCase() == r.nombre.toLowerCase());
        if (idx < 0) {
          listaObjetos.add(r);
        } else if (r.usaIMEI) {
          listaObjetos[idx].usaIMEI = true;
        }
      }
      await _guardarLocal();
      await _subirAlBackend();
      await prefs.setBool(_prefsSincronizado, true);
    } catch (e) {
      debugPrint('[CategoriasProductos] sincronizar error: $e');
    }
  }

  static Future<void> _subirAlBackend() async {
    await _Api.post('configuracion', {
      _claveBackend: jsonEncode(listaObjetos.map((c) => c.toMap()).toList()),
    });
  }

  /// Activa o desactiva el uso de IMEI para una categoría.
  /// El cambio se persiste y aplica inmediatamente en toda la app.
  static Future<void> setUsaIMEI(String categoria, bool valor) async {
    final c = listaObjetos.firstWhere(
        (x) => x.nombre.toLowerCase() == categoria.toLowerCase(),
        orElse: () => CategoriaProducto(nombre: ''));
    if (c.nombre.isEmpty) return;
    c.usaIMEI = valor;
    await guardar();
  }

  static const String _prefsKey = 'categorias_productos_v2';
  static const String _prefsKeyOld = 'categorias_productos_v1';

  /// Carga la lista desde SharedPreferences (al iniciar la app).
  /// Migra desde v1 (sin IMEI) si existe.
  static Future<void> cargar() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      // Primero intentar v2 (formato nuevo con usaIMEI)
      final json = prefs.getString(_prefsKey);
      if (json != null && json.isNotEmpty) {
        final dec = jsonDecode(json) as List;
        listaObjetos = dec
            .whereType<Map>()
            .map((m) => CategoriaProducto.fromMap(
                m.map((k, v) => MapEntry(k.toString(), v))))
            .toList();
        return;
      }
      // Migración: si solo hay v1 (lista de strings), convertir
      final jsonOld = prefs.getString(_prefsKeyOld);
      if (jsonOld != null && jsonOld.isNotEmpty) {
        final dec = jsonDecode(jsonOld) as List;
        listaObjetos = dec.map((e) {
          final nombre = e.toString();
          return CategoriaProducto(
            nombre: nombre,
            usaIMEI: nombre.toLowerCase() == 'telefono',
          );
        }).toList();
        await guardar(); // guardar en formato nuevo
      }
    } catch (e) {
      debugPrint('[CategoriasProductos] cargar error: $e');
    }
  }

  /// Persiste la lista actual en formato v2 (con usaIMEI por categoría).
  static Future<void> guardar() async {
    await _guardarLocal();
    // Sync al backend en segundo plano — si falla, el disco local
    // sigue con los datos.
    _subirAlBackend().catchError((e) {
      debugPrint('[CategoriasProductos] Error enviando al backend: $e');
    });
  }

  static Future<void> _guardarLocal() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(_prefsKey,
          jsonEncode(listaObjetos.map((c) => c.toMap()).toList()));
    } catch (e) {
      debugPrint('[CategoriasProductos] guardar error: $e');
    }
  }

  /// Agrega una categoría nueva (si no existe). Devuelve true si se
  /// agregó. La comparación es case-insensitive trimeada.
  static Future<bool> agregar(String nombre, {bool usaIMEI = false}) async {
    final n = nombre.trim();
    if (n.isEmpty) return false;
    final existe = listaObjetos.any((c) =>
        c.nombre.toLowerCase() == n.toLowerCase());
    if (existe) return false;
    listaObjetos.add(CategoriaProducto(nombre: n, usaIMEI: usaIMEI));
    await guardar();
    return true;
  }

  /// Renombra una categoría existente.
  static Future<bool> renombrar(String viejo, String nuevo) async {
    final n = nuevo.trim();
    if (n.isEmpty) return false;
    final idx = listaObjetos.indexWhere((c) => c.nombre == viejo);
    if (idx < 0) return false;
    listaObjetos[idx].nombre = n;
    await guardar();
    return true;
  }

  /// Elimina una categoría. Devuelve true si se eliminó.
  static Future<bool> eliminar(String nombre) async {
    final n0 = listaObjetos.length;
    listaObjetos.removeWhere((c) => c.nombre == nombre);
    if (listaObjetos.length == n0) return false;
    await guardar();
    return true;
  }
}


class CategoriaComision {
  /// Identificador único e inmutable. Para las 6 originales son
  /// strings fijos ("accesorio", "telefono"...) — se usa como clave
  /// en `ResumenComision.conteos`. Para nuevas, se genera con timestamp.
  final String id;
  /// Nombre visible al usuario ("Accesorio", "Servicio Técnico"...).
  String nombre;
  /// Tarifa en USD por cada unidad contada.
  double tarifaUSD;
  /// Tipo de conteo: define cómo se cuentan las unidades.
  TipoConteoComision tipoConteo;
  /// Valor auxiliar del tipo de conteo. Para `categoriaProducto`
  /// es la categoría a buscar (ej: "Accesorio", "Televisor"). Para
  /// `ventaFinanciada` es el nombre del financiador a filtrar
  /// (vacío = cualquier financiador).
  String valorConteo;
  /// Clave de ícono — debe ser una de las claves de
  /// `CategoriaComision.iconosDisponibles`. Se persiste como string
  /// (no como codePoint dinámico) para preservar el tree-shaking de
  /// iconos en builds de release. Los IconData del mapa SON
  /// constantes en tiempo de compilación, así que el compilador
  /// puede saber exactamente qué iconos se usan.
  String iconoKey;
  /// Color hex (ej: "#FF0000") para mostrar en la tabla.
  String colorHex;
  /// Si es true, no se puede eliminar (las 6 originales).
  final bool protegida;

  CategoriaComision({
    required this.id,
    required this.nombre,
    required this.tarifaUSD,
    required this.tipoConteo,
    this.valorConteo = '',
    this.iconoKey = 'work',
    this.colorHex = '#1565C0',
    this.protegida = false,
  });

  /// Mapa de iconos disponibles. CADA IconData es una constante
  /// (`Icons.foo` es `const`), por lo que el compilador puede hacer
  /// tree-shaking. Esta lista define TODOS los iconos que las
  /// categorías de comisión pueden usar — si necesitas más, hay que
  /// agregarlos aquí (no se pueden cargar dinámicamente).
  static const Map<String, IconData> iconosDisponibles = {
    'work':           Icons.work_outline,
    'extension':      Icons.extension_outlined,
    'phone_android':  Icons.phone_android_outlined,
    'sim_card':       Icons.sim_card_outlined,
    'tv':             Icons.tv_outlined,
    'kitchen':        Icons.kitchen_outlined,
    'account_balance': Icons.account_balance_outlined,
    'build':          Icons.build_outlined,
    'handyman':       Icons.handyman_outlined,
    'support_agent':  Icons.support_agent_outlined,
    'store':          Icons.store_outlined,
    'local_shipping': Icons.local_shipping_outlined,
    'headset_mic':    Icons.headset_mic_outlined,
    'shield':         Icons.shield_outlined,
    'savings':        Icons.savings_outlined,
    'card_giftcard':  Icons.card_giftcard_outlined,
    'computer':       Icons.computer_outlined,
    'tablet_mac':     Icons.tablet_mac_outlined,
    'watch':          Icons.watch_outlined,
    'devices':        Icons.devices_outlined,
  };

  /// Devuelve el IconData asociado a `iconoKey`, o un fallback si la
  /// clave no existe en el mapa (por ejemplo, datos viejos que tenían
  /// un codePoint pero ahora migran a clave).
  IconData get icono =>
      iconosDisponibles[iconoKey] ?? Icons.work_outline;

  Color get color {
    final h = colorHex.replaceAll('#', '');
    return Color(int.parse('FF$h', radix: 16));
  }

  Map<String, dynamic> toMap() => {
        'id': id,
        'nombre': nombre,
        'tarifa_usd': tarifaUSD,
        'tipo_conteo': tipoConteo.clave,
        'valor_conteo': valorConteo,
        'icono_key': iconoKey,
        'color_hex': colorHex,
        'protegida': protegida,
      };

  factory CategoriaComision.fromMap(Map<String, dynamic> m) {
    // RETROCOMPATIBILIDAD: si el dato guardado tiene `icono_code_point`
    // (versión vieja del modelo, antes del refactor a iconoKey),
    // intentamos mapear ese codePoint a una clave conocida. Si no
    // se encuentra, usamos el icono por defecto.
    String iconoKey = m['icono_key']?.toString() ?? '';
    if (iconoKey.isEmpty) {
      final cp = int.tryParse(m['icono_code_point']?.toString() ?? '');
      if (cp != null) {
        // Buscar la clave cuyo IconData tenga este codePoint
        iconoKey = iconosDisponibles.entries
                .firstWhere(
                  (e) => e.value.codePoint == cp,
                  orElse: () => const MapEntry('work', Icons.work_outline),
                )
                .key;
      } else {
        iconoKey = 'work';
      }
    }
    return CategoriaComision(
      id: m['id']?.toString() ?? '',
      nombre: m['nombre']?.toString() ?? '',
      tarifaUSD: double.tryParse(m['tarifa_usd'].toString()) ?? 0,
      tipoConteo: TipoConteoComisionX.desdeString(
          m['tipo_conteo']?.toString() ?? 'categoriaProducto'),
      valorConteo: m['valor_conteo']?.toString() ?? '',
      iconoKey: iconoKey,
      colorHex: m['color_hex']?.toString() ?? '#1565C0',
      protegida: m['protegida'] == true || m['protegida'] == 1
          || m['protegida'].toString() == '1'
          || m['protegida'].toString().toLowerCase() == 'true',
    );
  }

  /// Devuelve la lista predeterminada con las 6 categorías originales.
  /// Estas son las que existían antes del refactor — se mantienen como
  /// "protegidas" para no romper los datos guardados ni la lógica.
  static List<CategoriaComision> defaults() => [
        CategoriaComision(
          id: 'accesorio',
          nombre: 'Accesorio',
          tarifaUSD: 0.50,
          tipoConteo: TipoConteoComision.categoriaProducto,
          valorConteo: 'Accesorio',
          iconoKey: 'extension',
          colorHex: '#009688',
          protegida: true,
        ),
        CategoriaComision(
          id: 'telefono',
          nombre: 'Teléfono',
          tarifaUSD: 1.00,
          tipoConteo: TipoConteoComision.categoriaProducto,
          valorConteo: 'Telefono',
          iconoKey: 'phone_android',
          colorHex: '#1565C0',
          protegida: true,
        ),
        CategoriaComision(
          id: 'linea',
          nombre: 'Línea',
          tarifaUSD: 0.50,
          tipoConteo: TipoConteoComision.lineaTelefonica,
          iconoKey: 'sim_card',
          colorHex: '#7B1FA2',
          protegida: true,
        ),
        CategoriaComision(
          id: 'televisor',
          nombre: 'Televisor',
          tarifaUSD: 2.00,
          tipoConteo: TipoConteoComision.categoriaProducto,
          valorConteo: 'Televisor',
          iconoKey: 'tv',
          colorHex: '#E64A19',
          protegida: true,
        ),
        CategoriaComision(
          id: 'linea_blanca',
          nombre: 'Línea Blanca',
          tarifaUSD: 1.00,
          tipoConteo: TipoConteoComision.categoriaProducto,
          valorConteo: 'Linea Blanca',
          iconoKey: 'kitchen',
          colorHex: '#3949AB',
          protegida: true,
        ),
        // ── CATEGORÍA "FINANCIADOR" — ELIMINADA ──────────────────
        // Antes existía una categoría protegida `financiador` que
        // pagaba $1,00 al vendedor por cada pago financiado que
        // gestionara (Cashea, Weppa, Krece...). Por decisión del dueño
        // el financiador YA NO gana comisión, así que la categoría se
        // quitó del sistema.
        //
        // No se borra el id de las constantes de retrocompatibilidad
        // (`conteos['financiador']` en toMap/fromMap) para que los
        // resúmenes YA GUARDADOS en el historial sigan mostrando los
        // montos que se pagaron en su momento. Lo que se elimina es la
        // capacidad de generar comisiones NUEVAS por este concepto.
        // Ver `kCategoriaComisionEliminada` y el filtro en
        // `cargarCategoriasComision()`.
      ];
}

/// ID de la categoría de comisión retirada del sistema.
///
/// La categoría "Financiador" estaba marcada como `protegida`, así que
/// el admin no podía eliminarla desde el panel, y además ya quedó
/// persistida en SharedPreferences de todos los equipos instalados.
/// Por eso no alcanza con sacarla de `defaults()`: hay que filtrarla
/// también al cargar la lista guardada.
const String kCategoriaComisionEliminada = 'financiador';

class ResumenComision {
  String vendedor;
  /// Conteos por categoría: clave = `CategoriaComision.id`,
  /// valor = cantidad de unidades contadas para esa categoría.
  /// Reemplaza los antiguos campos individuales (accesorios,
  /// telefonos, etc) — el sistema ahora es completamente dinámico.
  final Map<String, int> conteos = {};
  /// Snapshot de tarifas USD por categoría usadas al momento de
  /// generar este resumen. Permite que un historial conserve los
  /// montos correctos aunque el admin cambie las tarifas después.
  final Map<String, double> tarifasUsadas = {};
  /// Snapshot de los nombres de categoría al momento de generar
  /// (para mostrar columnas con el nombre correcto en histórico).
  final Map<String, String> nombresCategorias = {};
  double base = 40, domingo = 0, descuentoBs = 0;
  /// Comisión adicional por financiamiento Weppa: % sobre el precio
  /// de venta de los productos financiados con Weppa.
  double comisionWeppa = 0;
  /// Ajuste por split cajero 35/65.
  /// · Si este usuario es CAJERO y facturó la venta de otro vendedor,
  ///   acumula AQUÍ el % que le toca (positivo).
  /// · Si este usuario es VENDEDOR y un cajero facturó su venta,
  ///   acumula AQUÍ lo que pierde (negativo).
  /// El balance es exacto: lo que pierde un vendedor lo gana el cajero.
  double ajusteComisionUSD = 0;
  /// Cuántas facturas creó este usuario actuando como cajero.
  /// Solo se incrementa si el creador es cajero. Útil para mostrar
  /// "facturó X ventas para otros vendedores" en la UI.
  int facturasCajero = 0;

  ResumenComision({required this.vendedor}) {
    base = ConfigSistema.comisionBaseDefault;
  }

  /// Total de comisión en USD: suma de (conteo × tarifa) por cada
  /// categoría, más la comisión Weppa acumulada, más el ajuste por
  /// split cajero (puede ser negativo si pierde dinero por un cajero
  /// que facturó su venta).
  double get totalComision {
    double total = 0;
    for (final entry in conteos.entries) {
      final tarifa = tarifasUsadas[entry.key] ?? 0;
      total += entry.value * tarifa;
    }
    return total + comisionWeppa + ajusteComisionUSD;
  }

  /// Total a pagar al vendedor en USD (comisión + base + domingo).
  double totalPagar() => totalComision + base + domingo;

  /// Total a pagar convertido a Bolívares: usa la tasa proporcionada
  /// (BCV o manual según la pantalla de comisiones) y resta el
  /// descuento que el admin haya capturado en Bs.
  double totalBs(double tasa) => (totalPagar() * tasa) - descuentoBs;

  /// Helper: lee el conteo de una categoría específica (0 si no existe).
  int conteoDe(String idCategoria) => conteos[idCategoria] ?? 0;

  Map<String, dynamic> toMap() => {
        'vendedor': vendedor,
        'conteos': conteos,
        'tarifas_usadas': tarifasUsadas,
        'nombres_categorias': nombresCategorias,
        'base': base,
        'domingo': domingo,
        'descuento_bs': descuentoBs,
        'comision_weppa': comisionWeppa,
        'ajuste_comision_usd': ajusteComisionUSD,
        'facturas_cajero': facturasCajero,
        // ── RETROCOMPATIBILIDAD ──
        // Mantenemos los campos antiguos en el JSON para que cualquier
        // backend o reporte que los lea siga funcionando. Se computan
        // desde `conteos` usando los IDs originales.
        'accesorios': conteos['accesorio'] ?? 0,
        'telefonos': conteos['telefono'] ?? 0,
        'lineas': conteos['linea'] ?? 0,
        'televisores': conteos['televisor'] ?? 0,
        'linea_blanca': conteos['linea_blanca'] ?? 0,
        'financiador': conteos['financiador'] ?? 0,
      };

  factory ResumenComision.fromMap(Map<String, dynamic> m) {
    final r = ResumenComision(vendedor: m['vendedor'] ?? '');
    // Si el JSON tiene la estructura nueva (`conteos`), la usamos.
    if (m['conteos'] is Map) {
      (m['conteos'] as Map).forEach((k, v) {
        r.conteos[k.toString()] =
            int.tryParse(v.toString()) ?? 0;
      });
    } else {
      // RETROCOMPATIBILIDAD: histórico guardado con campos antiguos.
      r.conteos['accesorio']    = int.tryParse(m['accesorios'].toString())   ?? 0;
      r.conteos['telefono']     = int.tryParse(m['telefonos'].toString())    ?? 0;
      r.conteos['linea']        = int.tryParse(m['lineas'].toString())       ?? 0;
      r.conteos['televisor']    = int.tryParse(m['televisores'].toString())  ?? 0;
      r.conteos['linea_blanca'] = int.tryParse(m['linea_blanca'].toString()) ?? 0;
      r.conteos['financiador']  = int.tryParse(m['financiador'].toString())  ?? 0;
    }
    if (m['tarifas_usadas'] is Map) {
      (m['tarifas_usadas'] as Map).forEach((k, v) {
        r.tarifasUsadas[k.toString()] =
            double.tryParse(v.toString()) ?? 0;
      });
    } else {
      // Para histórico viejo, usar tarifas actuales (mejor que nada).
      for (final c in ConfigSistema.categoriasComision) {
        r.tarifasUsadas[c.id] = c.tarifaUSD;
      }
    }
    if (m['nombres_categorias'] is Map) {
      (m['nombres_categorias'] as Map).forEach((k, v) {
        r.nombresCategorias[k.toString()] = v.toString();
      });
    }
    r.base = double.tryParse(m['base'].toString()) ?? ConfigSistema.comisionBaseDefault;
    r.domingo = double.tryParse(m['domingo'].toString()) ?? 0;
    r.descuentoBs = double.tryParse(m['descuento_bs'].toString()) ?? 0;
    r.comisionWeppa = double.tryParse((m['comision_weppa'] ?? 0).toString()) ?? 0;
    r.ajusteComisionUSD = double.tryParse((m['ajuste_comision_usd'] ?? 0).toString()) ?? 0;
    r.facturasCajero = int.tryParse((m['facturas_cajero'] ?? 0).toString()) ?? 0;
    return r;
  }
}

class HistorialComision {
  int? id;
  final DateTime fechaInicio, fechaFin;
  final double tasa;
  final List<ResumenComision> data;
  HistorialComision({this.id, required this.fechaInicio, required this.fechaFin,
      required this.tasa, required this.data});
  factory HistorialComision.fromMap(Map<String,dynamic> m) => HistorialComision(
    id: m['id'] is int ? m['id'] : int.tryParse(m['id']?.toString() ?? ''),
    fechaInicio: DateTime.tryParse(m['fecha_inicio']??'')??DateTime.now(),
    fechaFin: DateTime.tryParse(m['fecha_fin']??'')??DateTime.now(),
    tasa: double.tryParse(m['tasa'].toString())??1,
    data: List<Map<String,dynamic>>.from(m['detalle']??[])
        .map((d) => ResumenComision.fromMap(d)).toList());
}

// ── LISTAS DE PRECIOS ─────────────────────────────────────────

/// FUNCIÓN CONFIGURABLE DE UNA COLUMNA DE PRECIOS
/// ------------------------------------------------------------
/// Cada columna de una lista puede tener su propia "función": la
/// regla con la que se calcula su precio para TODOS los productos.
/// Antes las columnas eran solo un título y el precio se escribía a
/// mano uno por uno; ahora el usuario define, por ejemplo:
///
///   · "Mayorista"  = costo + 12 %          (redondeado al entero)
///   · "Detal"      = venta × 1.35          (terminado en ,99)
///   · "Contado"    = [Detal] − 20 $
///   · "Bs"         = [Detal] × tasa        (múltiplos de 5)
///   · "Especial"   = si(costo > 200; costo*1.15; costo*1.25)
///
/// Modos disponibles:
///   manual        → nadie toca el precio; lo escribe el usuario
///   porcentaje    → origen + (origen × valor / 100)
///   monto         → origen + valor
///   multiplicador → origen × valor
///   expresion     → fórmula libre escrita por el usuario
class FormulaColumna {
  static const modoManual        = 'manual';
  static const modoPorcentaje    = 'porcentaje';
  static const modoMonto         = 'monto';
  static const modoMultiplicador = 'multiplicador';
  static const modoExpresion     = 'expresion';

  /// Prefijo que identifica a las columnas virtuales de fórmula.
  static const prefijoVirtual = '__fx__';

  /// Cómo se calcula: manual / porcentaje / monto / multiplicador /
  /// expresion.
  String modo;

  /// De dónde sale el número de partida: 'venta' (precio de venta del
  /// catálogo), 'costo' (precio de costo), 'base' (primera columna de
  /// la lista) o 'columna' (otra columna, ver [columnaOrigen]).
  String origen;

  /// Nombre de la columna de la que se toma el valor de partida
  /// cuando [origen] es 'columna'.
  String columnaOrigen;

  /// Número que acompaña al modo (el %, el monto o el multiplicador).
  double valor;

  /// Fórmula libre cuando [modo] es 'expresion'.
  String expresion;

  /// Redondeo final: 'ninguno', 'dos' (2 decimales), 'entero',
  /// 'arriba', 'abajo', 'psicologico' (termina en ,99) o 'multiplo'.
  String redondeo;

  /// Múltiplo al que se redondea cuando [redondeo] es 'multiplo'
  /// (ej. 5 → 145, 150, 155…).
  double multiplo;

  /// Multiplica el resultado por la tasa del día de la lista. Útil
  /// para columnas en bolívares dentro de una lista en dólares.
  bool aplicarTasa;

  /// Suma el % adicional configurado en la lista antes de redondear.
  bool aplicarAdicional;

  /// Si es true la columna se recalcula sola (al poblar la lista, al
  /// cambiar la tasa o al editar el precio base). Si es false la
  /// fórmula existe pero solo se aplica cuando el usuario pulsa
  /// "Aplicar ahora".
  bool auto;

  FormulaColumna({
    this.modo = modoManual,
    this.origen = 'venta',
    this.columnaOrigen = '',
    this.valor = 0,
    this.expresion = '',
    this.redondeo = 'dos',
    this.multiplo = 1,
    this.aplicarTasa = false,
    this.aplicarAdicional = false,
    this.auto = true,
  });

  bool get esManual => modo == modoManual;

  FormulaColumna copiar() => FormulaColumna(
        modo: modo,
        origen: origen,
        columnaOrigen: columnaOrigen,
        valor: valor,
        expresion: expresion,
        redondeo: redondeo,
        multiplo: multiplo,
        aplicarTasa: aplicarTasa,
        aplicarAdicional: aplicarAdicional,
        auto: auto,
      );

  /// Etiqueta corta para mostrar debajo del nombre de la columna.
  String get descripcion {
    if (esManual) return 'Manual';
    final o = origen == 'venta'
        ? 'Venta'
        : origen == 'costo'
            ? 'Costo'
            : origen == 'base'
                ? 'Base'
                : (columnaOrigen.isEmpty ? 'Columna' : columnaOrigen);
    String txt;
    switch (modo) {
      case modoPorcentaje:
        txt = '$o ${valor >= 0 ? '+' : '−'} '
            '${valor.abs().toStringAsFixed(valor.abs() % 1 == 0 ? 0 : 2)} %';
        break;
      case modoMonto:
        txt = '$o ${valor >= 0 ? '+' : '−'} ${valor.abs().toStringAsFixed(2)}';
        break;
      case modoMultiplicador:
        txt = '$o × ${valor.toStringAsFixed(valor % 1 == 0 ? 0 : 4)}';
        break;
      case modoExpresion:
        txt = expresion.length > 28
            ? '${expresion.substring(0, 28)}…'
            : expresion;
        break;
      default:
        txt = 'Manual';
    }
    if (aplicarAdicional) txt += ' +adic.';
    if (aplicarTasa) txt += ' × tasa';
    return txt;
  }

  Map<String, dynamic> toJson() => {
        'modo': modo,
        'origen': origen,
        'columna_origen': columnaOrigen,
        'valor': valor,
        'expresion': expresion,
        'redondeo': redondeo,
        'multiplo': multiplo,
        'aplicar_tasa': aplicarTasa,
        'aplicar_adicional': aplicarAdicional,
        'auto': auto,
      };

  factory FormulaColumna.fromJson(Map<String, dynamic> m) {
    double d(dynamic v, [double def = 0]) {
      if (v == null) return def;
      if (v is num) return v.toDouble();
      return double.tryParse(v.toString()) ?? def;
    }

    bool b(dynamic v, [bool def = false]) {
      if (v == null) return def;
      if (v is bool) return v;
      final s = v.toString().toLowerCase();
      return s == '1' || s == 'true';
    }

    return FormulaColumna(
      modo: '${m['modo'] ?? modoManual}',
      origen: '${m['origen'] ?? 'venta'}',
      columnaOrigen: '${m['columna_origen'] ?? ''}',
      valor: d(m['valor']),
      expresion: '${m['expresion'] ?? ''}',
      redondeo: '${m['redondeo'] ?? 'dos'}',
      multiplo: d(m['multiplo'], 1),
      aplicarTasa: b(m['aplicar_tasa']),
      aplicarAdicional: b(m['aplicar_adicional']),
      auto: b(m['auto'], true),
    );
  }

  /// Serializa la fórmula en un texto seguro para viajar dentro del
  /// NOMBRE de una columna virtual (ver `ListaPrecio.toMap`). El
  /// backend guarda las columnas como simples cadenas, así que ésta es
  /// la forma de persistir la configuración sin tocar el esquema.
  String aCodigo(String nombreColumna) =>
      '$prefijoVirtual${base64Url.encode(utf8.encode(jsonEncode({
            'c': nombreColumna,
            'f': toJson(),
          })))}';

  /// true si el nombre corresponde a una columna virtual (de fórmula
  /// o de los overrides de financiamiento). Éstas NUNCA se muestran.
  static bool esNombreVirtual(String nombre) =>
      nombre.startsWith(prefijoVirtual) ||
      (nombre.startsWith('__') && nombre.endsWith('__'));

  /// Decodifica una columna virtual. Devuelve (nombreColumna, fórmula)
  /// o null si el texto no es válido.
  static MapEntry<String, FormulaColumna>? deCodigo(String codigo) {
    if (!codigo.startsWith(prefijoVirtual)) return null;
    try {
      final json = jsonDecode(utf8
          .decode(base64Url.decode(codigo.substring(prefijoVirtual.length))));
      if (json is! Map) return null;
      final nombre = '${json['c'] ?? ''}';
      if (nombre.isEmpty) return null;
      return MapEntry(nombre,
          FormulaColumna.fromJson(Map<String, dynamic>.from(json['f'] as Map)));
    } catch (_) {
      return null;
    }
  }
}

/// EVALUADOR DE FÓRMULAS
/// ------------------------------------------------------------
/// Intérprete pequeño para las expresiones que escribe el usuario en
/// una columna. Soporta:
///   · números (con , o . como decimal)   · paréntesis
///   · + − × / ^  y el módulo `mod`
///   · variables: costo, venta, base, tasa, adicional, inicial,
///     cuotas, recargo, stock
///   · otras columnas entre corchetes: [Mayorista]
///   · funciones: redondear(x[;dec]), techo(x), piso(x), abs(x),
///     min(a;b), max(a;b), pot(a;b), raiz(x), si(cond; a; b)
///   · comparaciones >, <, >=, <=, =, <> y los conectores `y` / `o`
///
/// Los argumentos se separan con `;` o con `,`.
class EvaluadorFormula {
  final Map<String, double> variables;
  final String _src;
  int _i = 0;

  EvaluadorFormula(String fuente, this.variables)
      : _src = fuente.replaceAll('\n', ' ');

  /// Evalúa la expresión. Devuelve null si la fórmula tiene un error.
  static double? evaluar(String expresion, Map<String, double> variables) {
    if (expresion.trim().isEmpty) return null;
    try {
      final e = EvaluadorFormula(expresion, variables);
      final v = e._expresion();
      e._saltarEspacios();
      if (e._i < e._src.length) return null; // sobró texto → error
      if (v.isNaN || v.isInfinite) return null;
      return v;
    } catch (_) {
      return null;
    }
  }

  /// Valida una fórmula y devuelve el mensaje de error, o null si es
  /// correcta. Se usa para avisar en el editor mientras se escribe.
  static String? validar(String expresion, Map<String, double> variables) {
    if (expresion.trim().isEmpty) return 'Escribe una fórmula';
    if (evaluar(expresion, variables) == null) {
      return 'Fórmula inválida — revisa nombres, ; y paréntesis';
    }
    return null;
  }

  void _saltarEspacios() {
    while (_i < _src.length && _src[_i] == ' ') {
      _i++;
    }
  }

  bool _consumir(String texto) {
    _saltarEspacios();
    if (_src.startsWith(texto, _i)) {
      _i += texto.length;
      return true;
    }
    return false;
  }

  /// Consume una palabra completa (no parte de un identificador).
  bool _consumirPalabra(String palabra) {
    _saltarEspacios();
    if (!_src.startsWith(palabra, _i)) return false;
    final fin = _i + palabra.length;
    if (fin < _src.length && _esLetra(_src[fin])) return false;
    _i = fin;
    return true;
  }

  bool _esLetra(String c) =>
      RegExp(r'[A-Za-zÁÉÍÓÚÑáéíóúñ_0-9]').hasMatch(c);

  // expresion := comparacion (('y'|'o') comparacion)*
  double _expresion() {
    var izq = _comparacion();
    while (true) {
      _saltarEspacios();
      if (_consumirPalabra('y')) {
        final der = _comparacion();
        izq = (izq != 0 && der != 0) ? 1 : 0;
      } else if (_consumirPalabra('o')) {
        final der = _comparacion();
        izq = (izq != 0 || der != 0) ? 1 : 0;
      } else {
        return izq;
      }
    }
  }

  double _comparacion() {
    final izq = _suma();
    _saltarEspacios();
    for (final op in ['>=', '<=', '<>', '!=', '==', '>', '<', '=']) {
      if (_consumir(op)) {
        final der = _suma();
        switch (op) {
          case '>=':
            return izq >= der ? 1 : 0;
          case '<=':
            return izq <= der ? 1 : 0;
          case '>':
            return izq > der ? 1 : 0;
          case '<':
            return izq < der ? 1 : 0;
          case '<>':
          case '!=':
            return (izq - der).abs() > 1e-9 ? 1 : 0;
          default:
            return (izq - der).abs() < 1e-9 ? 1 : 0;
        }
      }
    }
    return izq;
  }

  double _suma() {
    var v = _producto();
    while (true) {
      _saltarEspacios();
      if (_consumir('+')) {
        v += _producto();
      } else if (_consumir('-') || _consumir('−')) {
        v -= _producto();
      } else {
        return v;
      }
    }
  }

  double _producto() {
    var v = _potencia();
    while (true) {
      _saltarEspacios();
      if (_consumir('*') || _consumir('×')) {
        v *= _potencia();
      } else if (_consumir('/') || _consumir('÷')) {
        final d = _potencia();
        if (d == 0) throw const FormatException('división entre cero');
        v /= d;
      } else if (_consumirPalabra('mod')) {
        final d = _potencia();
        if (d == 0) throw const FormatException('módulo cero');
        v = v % d;
      } else {
        return v;
      }
    }
  }

  double _potencia() {
    final base = _unario();
    _saltarEspacios();
    if (_consumir('^')) {
      return math.pow(base, _potencia()).toDouble();
    }
    return base;
  }

  double _unario() {
    _saltarEspacios();
    if (_consumir('-') || _consumir('−')) return -_unario();
    if (_consumir('+')) return _unario();
    return _atomo();
  }

  double _atomo() {
    _saltarEspacios();
    if (_i >= _src.length) throw const FormatException('fin inesperado');

    // Paréntesis
    if (_consumir('(')) {
      final v = _expresion();
      if (!_consumir(')')) throw const FormatException('falta )');
      return v;
    }

    // Referencia a otra columna: [Mayorista]
    if (_consumir('[')) {
      final cierre = _src.indexOf(']', _i);
      if (cierre < 0) throw const FormatException('falta ]');
      final nombre = _src.substring(_i, cierre).trim();
      _i = cierre + 1;
      final v = variables['[${nombre.toLowerCase()}]'];
      if (v == null) throw FormatException('columna "$nombre" no existe');
      return v;
    }

    // Número
    final mNum = RegExp(r'^[0-9]+([.,][0-9]+)?').firstMatch(_src.substring(_i));
    if (mNum != null) {
      _i += mNum.group(0)!.length;
      return double.parse(mNum.group(0)!.replaceAll(',', '.'));
    }

    // Identificador: función o variable
    final mId = RegExp(r'^[A-Za-zÁÉÍÓÚÑáéíóúñ_][A-Za-zÁÉÍÓÚÑáéíóúñ_0-9]*')
        .firstMatch(_src.substring(_i));
    if (mId == null) {
      throw FormatException('símbolo inesperado en "${_src.substring(_i)}"');
    }
    final id = mId.group(0)!.toLowerCase();
    _i += mId.group(0)!.length;

    _saltarEspacios();
    if (_i < _src.length && _src[_i] == '(') {
      return _llamarFuncion(id, _argumentos());
    }

    final v = variables[id];
    if (v == null) throw FormatException('variable "$id" no existe');
    return v;
  }

  List<double> _argumentos() {
    if (!_consumir('(')) throw const FormatException('falta (');
    final args = <double>[];
    _saltarEspacios();
    if (_consumir(')')) return args;
    while (true) {
      args.add(_expresion());
      _saltarEspacios();
      if (_consumir(';') || _consumir(',')) continue;
      if (_consumir(')')) return args;
      throw const FormatException('falta ) o ;');
    }
  }

  double _llamarFuncion(String nombre, List<double> a) {
    double arg(int i) {
      if (i >= a.length) throw FormatException('faltan argumentos en $nombre');
      return a[i];
    }

    switch (nombre) {
      case 'redondear':
        final dec = a.length > 1 ? a[1].round() : 2;
        final f = math.pow(10, dec).toDouble();
        return (arg(0) * f).round() / f;
      case 'techo':
        return arg(0).ceilToDouble();
      case 'piso':
        return arg(0).floorToDouble();
      case 'abs':
        return arg(0).abs();
      case 'min':
        return math.min(arg(0), arg(1));
      case 'max':
        return math.max(arg(0), arg(1));
      case 'pot':
        return math.pow(arg(0), arg(1)).toDouble();
      case 'raiz':
        return math.sqrt(arg(0));
      case 'si':
        return arg(0) != 0 ? arg(1) : arg(2);
      default:
        throw FormatException('función "$nombre" no existe');
    }
  }
}

class ColumnaPrecio {
  String nombre;

  /// Función configurable que calcula el precio de esta columna para
  /// todos los productos. Por defecto es manual.
  FormulaColumna formula;

  ColumnaPrecio({required this.nombre, FormulaColumna? formula})
      : formula = formula ?? FormulaColumna();
}

class ItemListaPrecio {
  final Producto producto;
  Map<String,double> preciosPorColumna;
  int stockDisponible;
  /// Override manual de la inicial (modo financiamiento).
  /// Si es null, se calcula automáticamente: precioBase × porcentajeInicial.
  /// Si tiene valor, se usa tal cual lo escribió el admin.
  double? inicialManual;
  /// Override manual de la cuota (modo financiamiento).
  /// Si es null, se calcula automáticamente desde precioBase, inicial y nCuotas.
  /// Si tiene valor, se usa tal cual.
  double? cuotaManual;

  // ── Condiciones propias de este producto ───────────────────
  // Una misma lista de financiadora puede tener condiciones
  // distintas por marca o por modelo: 30% de inicial en Samsung y
  // 40% en Apple, 6 cuotas en la gama alta y 12 en el resto. Antes
  // el % de inicial y el número de cuotas eran de TODA la lista, así
  // que para eso había que crear una lista por combinación.
  //
  // Cuando estos campos son null se usan los de la lista; cuando
  // tienen valor, mandan ellos. Son PORCENTAJE y CANTIDAD, no montos:
  // el monto de la inicial y de la cuota se siguen calculando solos
  // a partir del precio (para fijar un monto exacto están
  // `inicialManual` y `cuotaManual`).

  /// % de inicial propio de este producto. null = el de la lista.
  double? pctInicialOverride;

  /// N° de cuotas propio de este producto. null = el de la lista.
  int? cuotasOverride;

  ItemListaPrecio({
    required this.producto,
    required this.preciosPorColumna,
    this.stockDisponible = 0,
    this.inicialManual,
    this.cuotaManual,
    this.pctInicialOverride,
    this.cuotasOverride,
  });

  /// true si este producto tiene condiciones propias (distintas a
  /// las generales de la lista).
  bool get tieneCondicionesPropias =>
      pctInicialOverride != null || cuotasOverride != null;
}

class ListaPrecio {
  int? id;
  String nombre, fechaCreacion;
  String categoria;
  String marcaFiltro;
  List<ColumnaPrecio> columnas;
  List<ItemListaPrecio> items;
  bool esEnBolivares;
  double tasaDelDia;
  // ── Nuevos campos ──────────────────────────────────────────
  double porcentajeAdicional; // % que se suma al precio venta
  bool esFinanciamiento;
  String? financiadora;
  double porcentajeInicial;   // % para calcular la inicial
  int numeroCuotas;
  // ── % de comisión Weppa ─────────────────────────────────────
  // Solo aplica cuando la financiadora es Weppa. Se utiliza para
  // calcular comisiones del vendedor en base al precio de venta
  // del producto vendido con financiamiento Weppa.
  double porcentajeComisionWeppa;
  // ── ¿Esta financiadora maneja cuotas? ────────────────────────
  // Algunas financiadoras (ej. ciertas modalidades de Cashea o
  // Krece) NO dividen el saldo en cuotas — el cliente paga la
  // inicial y la financiadora se encarga del resto sin que la
  // tienda tenga que mostrar/calcular cuotas. Si esto es false,
  // las pantallas ocultan los campos de "Número de cuotas" y
  // "Cuota mensual" y solo muestran Base − Inicial = Deuda.
  bool tieneCuotas;
  // ── % de recargo sobre el total a financiar ────────────────
  // Se aplica al monto total de cuotas antes de dividir entre el
  // número de cuotas. Ej: resto=$60, recargo=20%, cuotas=6
  //   → total a financiar = 60 × 1.20 = 72 → cuota = 72/6 = $12
  double porcentajeRecargoCuotas;

  ListaPrecio({
    this.id,
    required this.nombre,
    required this.fechaCreacion,
    this.categoria = "Todos",
    this.marcaFiltro = "Todas",
    List<ColumnaPrecio>? columnas,
    List<ItemListaPrecio>? items,
    this.esEnBolivares = false,
    this.tasaDelDia = 1.0,
    this.porcentajeAdicional = 0.0,
    this.esFinanciamiento = false,
    this.financiadora,
    this.porcentajeInicial = 0.0,
    this.numeroCuotas = 12,
    this.porcentajeComisionWeppa = 0.0,
    this.porcentajeRecargoCuotas = 0.0,
    this.tieneCuotas = true,
  }) : columnas = columnas ?? [], items = items ?? [];

  // ── CONDICIONES EFECTIVAS DE UN PRODUCTO ───────────────────
  // Todo lo que muestra o calcula inicial y cuotas debe pasar por
  // acá: así una condición puesta a una marca o a un modelo vale
  // igual en la pantalla de la lista, en el PDF, en la imagen que se
  // comparte, en la consulta rápida y en los reportes.

  /// % de inicial que le corresponde a [it] (el propio si lo tiene).
  double pctInicialDe(ItemListaPrecio it) =>
      it.pctInicialOverride ?? porcentajeInicial;

  /// N° de cuotas que le corresponde a [it] (el propio si lo tiene).
  int cuotasDe(ItemListaPrecio it) => it.cuotasOverride ?? numeroCuotas;

  /// Monto de la inicial de [it] sobre un precio base dado.
  double inicialDe(ItemListaPrecio it, double precioBase) =>
      it.inicialManual ??
      redondearPrecio(precioBase * (pctInicialDe(it) / 100));

  /// Monto de cada cuota de [it]. Devuelve 0 si la lista no maneja
  /// cuotas.
  double cuotaDe(ItemListaPrecio it, double precioBase) {
    if (it.cuotaManual != null) return it.cuotaManual!;
    if (!tieneCuotas) return 0;
    final n = cuotasDe(it) > 0 ? cuotasDe(it) : 1;
    final resto = precioBase - inicialDe(it, precioBase);
    return redondearPrecio(resto * (1 + porcentajeRecargoCuotas / 100) / n);
  }

  /// N° de cuotas cuando TODOS los productos comparten el mismo;
  /// null si hay condiciones distintas por marca o modelo (en ese
  /// caso los encabezados no pueden anunciar un número único).
  int? get cuotasUniformes {
    if (items.isEmpty) return numeroCuotas;
    final n = cuotasDe(items.first);
    for (final it in items) {
      if (cuotasDe(it) != n) return null;
    }
    return n;
  }

  // ── FUNCIONES DE COLUMNA ───────────────────────────────────
  // Una columna puede tener una funcion propia (ver FormulaColumna).
  // Todo lo que recalcula precios pasa por aca, asi la regla que el
  // usuario configuro vale igual al poblar la lista, al cambiar la
  // tasa, al editar el precio base y al pulsar "Aplicar ahora".

  /// Tasa efectiva de la lista (la del dia; si no hay, la del sistema).
  double get tasaEfectiva {
    if (tasaDelDia > 0) return tasaDelDia;
    return ConfigSistema.tasaCambio > 0 ? ConfigSistema.tasaCambio : 1.0;
  }

  /// Variables disponibles para las formulas de [it].
  Map<String, double> variablesDe(ItemListaPrecio it) {
    final base = columnas.isEmpty
        ? 0.0
        : (it.preciosPorColumna[columnas.first.nombre] ?? 0.0);
    final vars = <String, double>{
      'costo': it.producto.precioCosto,
      'venta': it.producto.precioVenta,
      'base': base,
      'tasa': tasaEfectiva,
      'adicional': porcentajeAdicional,
      'inicial': pctInicialDe(it),
      'cuotas': cuotasDe(it).toDouble(),
      'recargo': porcentajeRecargoCuotas,
      'stock': it.stockDisponible.toDouble(),
    };
    // Cada columna se puede referenciar con [Nombre] (sin distinguir
    // mayusculas) y tambien por su nombre suelto si es una sola palabra.
    for (final c in columnas) {
      final v = it.preciosPorColumna[c.nombre] ?? 0.0;
      vars['[${c.nombre.toLowerCase()}]'] = v;
      final simple = c.nombre.toLowerCase().trim();
      if (RegExp(r'^[a-zA-ZáéíóúñÁÉÍÓÚÑ_][a-zA-Z0-9áéíóúñÁÉÍÓÚÑ_]*$')
              .hasMatch(simple) &&
          !vars.containsKey(simple)) {
        vars[simple] = v;
      }
    }
    return vars;
  }

  /// Aplica el redondeo configurado en [f].
  static double aplicarRedondeo(double v, FormulaColumna f) {
    switch (f.redondeo) {
      case 'ninguno':
        return v;
      case 'entero':
        return v.roundToDouble();
      case 'arriba':
        return v.ceilToDouble();
      case 'abajo':
        return v.floorToDouble();
      case 'psicologico':
        // Termina siempre en ,99 (149.30 → 149.99; 150.00 → 149.99)
        final techo = v.ceilToDouble();
        return (techo - v).abs() < 0.0001 ? v - 0.01 : techo - 0.01;
      case 'multiplo':
        final m = f.multiplo > 0 ? f.multiplo : 1;
        return (v / m).roundToDouble() * m;
      default: // 'dos'
        return redondearPrecio(v);
    }
  }

  /// Calcula el precio que le corresponde a [it] en la columna [col]
  /// segun la funcion configurada. Devuelve null si la columna es
  /// manual o si la formula tiene un error.
  double? calcularColumna(ColumnaPrecio col, ItemListaPrecio it) {
    final f = col.formula;
    if (f.esManual) return null;
    final vars = variablesDe(it);

    double? bruto;
    if (f.modo == FormulaColumna.modoExpresion) {
      bruto = EvaluadorFormula.evaluar(f.expresion, vars);
    } else {
      double origen;
      switch (f.origen) {
        case 'costo':
          origen = it.producto.precioCosto;
          break;
        case 'base':
          origen = vars['base'] ?? 0;
          break;
        case 'columna':
          // Una columna no puede alimentarse de si misma.
          if (f.columnaOrigen.isEmpty ||
              f.columnaOrigen.toLowerCase() == col.nombre.toLowerCase()) {
            return null;
          }
          origen = it.preciosPorColumna[f.columnaOrigen] ??
              vars['[${f.columnaOrigen.toLowerCase()}]'] ??
              0;
          break;
        default:
          origen = it.producto.precioVenta;
      }
      switch (f.modo) {
        case FormulaColumna.modoPorcentaje:
          bruto = origen * (1 + f.valor / 100);
          break;
        case FormulaColumna.modoMonto:
          bruto = origen + f.valor;
          break;
        case FormulaColumna.modoMultiplicador:
          bruto = origen * f.valor;
          break;
        default:
          bruto = origen;
      }
    }
    if (bruto == null || bruto.isNaN || bruto.isInfinite) return null;
    if (f.aplicarAdicional) bruto = bruto * (1 + porcentajeAdicional / 100);
    if (f.aplicarTasa) bruto = bruto * tasaEfectiva;
    return aplicarRedondeo(bruto, f);
  }

  /// Recalcula las columnas con funcion y escribe los precios.
  ///
  /// [soloAutomaticas] limita el recalculo a las columnas marcadas
  /// como "auto"; [soloColumna] recalcula una sola columna.
  /// Devuelve cuantos precios cambiaron.
  int aplicarFormulas({
    bool soloAutomaticas = true,
    String? soloColumna,
  }) {
    var cambios = 0;
    // En orden: asi una columna que se apoya en otra ya calculada usa
    // el valor nuevo y no el viejo.
    for (final col in columnas) {
      if (col.formula.esManual) continue;
      if (soloAutomaticas && !col.formula.auto) continue;
      if (soloColumna != null && col.nombre != soloColumna) continue;
      for (final it in items) {
        final nuevo = calcularColumna(col, it);
        if (nuevo == null) continue;
        final actual = it.preciosPorColumna[col.nombre];
        if (actual == null || (actual - nuevo).abs() > 0.0001) {
          it.preciosPorColumna[col.nombre] = nuevo;
          cambios++;
        }
      }
    }
    return cambios;
  }

  /// true si alguna columna tiene funcion configurada.
  bool get tieneFormulas => columnas.any((c) => !c.formula.esManual);

  Map<String, dynamic> toMap() => {
    if (id != null) 'id': id,
    'nombre': nombre,
    'fecha_creacion': fechaCreacion,
    'categoria': categoria,
    'marca_filtro': marcaFiltro,
    'es_en_bolivares': esEnBolivares ? 1 : 0,
    'tasa_del_dia': tasaDelDia,
    'porcentaje_adicional': porcentajeAdicional,
    'es_financiamiento': esFinanciamiento ? 1 : 0,
    'financiadora': financiadora,
    'porcentaje_inicial': porcentajeInicial,
    'numero_cuotas': numeroCuotas,
    'porcentaje_comision_weppa': porcentajeComisionWeppa,
    'porcentaje_recargo_cuotas': porcentajeRecargoCuotas,
    'tiene_cuotas': tieneCuotas ? 1 : 0,
    // Las columnas e items van en arrays nested que `guardarListaPrecios`
    // del backend procesa como tablas relacionales separadas.
    // Las columnas viajan con su nombre y, cuando tienen una funcion
    // configurada, tambien con la funcion serializada. Ademas de la
    // clave `formula` (que un backend actualizado puede guardar tal
    // cual) mandamos una columna VIRTUAL `__fx__...` por cada funcion:
    // el backend guarda las columnas por nombre, asi que ese nombre
    // codificado sobrevive el viaje aunque el esquema no cambie.
    // `fromMap` las vuelve a separar y nunca se muestran en pantalla.
    'columnas': [
      ...columnas.map((c) => {
        'nombre': c.nombre,
        'formula': jsonEncode(c.formula.toJson()),
      }),
      ...columnas
          .where((c) => !c.formula.esManual)
          .map((c) => {'nombre': c.formula.aCodigo(c.nombre)}),
    ],
    'items': items.map((it) {
      // Construimos la lista base de "valores" con los precios reales.
      final valores = it.preciosPorColumna.entries.map((e) => {
        'columna_nombre': e.key,
        'precio': e.value,
      }).toList();
      // Si el item tiene inicial/cuota manuales (modo financiamiento),
      // las persistimos como columnas "virtuales" con prefijo __.
      // Esto evita tocar el esquema de la BD y el backend las trata
      // como columnas normales. Al releer las separamos.
      if (it.inicialManual != null) {
        valores.add({
          'columna_nombre': '__inicial_manual__',
          'precio': it.inicialManual!,
        });
      }
      if (it.cuotaManual != null) {
        valores.add({
          'columna_nombre': '__cuota_manual__',
          'precio': it.cuotaManual!,
        });
      }
      // Condiciones propias por marca/modelo. Mismo truco que arriba:
      // viajan como columnas virtuales para no tocar el esquema.
      if (it.pctInicialOverride != null) {
        valores.add({
          'columna_nombre': '__pct_inicial__',
          'precio': it.pctInicialOverride!,
        });
      }
      if (it.cuotasOverride != null) {
        valores.add({
          'columna_nombre': '__n_cuotas__',
          'precio': it.cuotasOverride!.toDouble(),
        });
      }
      return {
        'producto_codigo': it.producto.codigo,
        'stock_disponible': it.stockDisponible,
        'valores': valores,
      };
    }).toList(),
  };

  factory ListaPrecio.fromMap(Map<String, dynamic> m) {
    int? toInt(dynamic v) {
      if (v == null) return null;
      if (v is int) return v;
      return int.tryParse(v.toString());
    }
    double toDouble(dynamic v) {
      if (v == null) return 0;
      if (v is double) return v;
      if (v is int) return v.toDouble();
      return double.tryParse(v.toString()) ?? 0;
    }
    bool toBool(dynamic v) =>
        v == 1 || v == '1' || v == true;

    // Reconstruir columnas.
    //  · Las columnas reales entran con su nombre y, si el backend la
    //    guardo, con su funcion en la clave `formula`.
    //  · Las columnas VIRTUALES `__fx__...` no son columnas: llevan la
    //    funcion de una columna real codificada en su propio nombre.
    //    Se decodifican, se aplican a su columna y se descartan.
    final cols = <ColumnaPrecio>[];
    final formulasVirtuales = <String, FormulaColumna>{};
    if (m['columnas'] is List) {
      for (final c in (m['columnas'] as List)) {
        final nombreCol = '${c['nombre'] ?? ''}';
        if (nombreCol.isEmpty) continue;
        // Columna virtual con la funcion de otra columna
        if (nombreCol.startsWith(FormulaColumna.prefijoVirtual)) {
          final par = FormulaColumna.deCodigo(nombreCol);
          if (par != null) formulasVirtuales[par.key] = par.value;
          continue;
        }
        // Cualquier otra columna con nombre reservado (__x__) tampoco
        // es una columna de precios visible.
        if (FormulaColumna.esNombreVirtual(nombreCol)) continue;
        // Duplicados: el backend puede devolver la misma columna dos
        // veces si se guardo mal alguna vez.
        if (cols.any((x) => x.nombre.toLowerCase() ==
            nombreCol.toLowerCase())) {
          continue;
        }
        FormulaColumna? f;
        final rawF = c['formula'];
        if (rawF != null && '$rawF'.isNotEmpty) {
          try {
            final j = rawF is Map ? rawF : jsonDecode('$rawF');
            if (j is Map) {
              f = FormulaColumna.fromJson(Map<String, dynamic>.from(j));
            }
          } catch (_) {/* funcion ilegible: queda manual */}
        }
        cols.add(ColumnaPrecio(nombre: nombreCol, formula: f));
      }
    }
    // Aplicar las funciones que llegaron en columnas virtuales
    for (final col in cols) {
      final f = formulasVirtuales[col.nombre];
      if (f != null) col.formula = f;
    }
    if (cols.isEmpty) cols.add(ColumnaPrecio(nombre: 'Precio'));

    // Reconstruir items (necesitamos el catálogo global para encontrar
    // el Producto correspondiente al código)
    final items = <ItemListaPrecio>[];
    if (m['items'] is List) {
      for (final it in (m['items'] as List)) {
        final codigo = '${it['producto_codigo'] ?? ''}';
        final prod = catalogoGlobal
            .where((p) => p.codigo == codigo)
            .firstOrNull;
        if (prod == null) continue; // producto no existe ya
        // El mapa usa el NOMBRE de la columna como clave, no el objeto.
        final precios = <String, double>{};
        double? inicialMan, cuotaMan, pctInicialOv;
        int? cuotasOv;
        if (it['valores'] is List) {
          for (final v in (it['valores'] as List)) {
            final colNombre = '${v['columna_nombre'] ?? ''}';
            if (colNombre.isEmpty) continue;
            // Columnas virtuales para overrides manuales del modo
            // financiamiento. Se persisten como columnas normales en
            // la BD pero acá las separamos a sus propios campos.
            if (colNombre == '__inicial_manual__') {
              inicialMan = toDouble(v['precio']);
              continue;
            }
            if (colNombre == '__cuota_manual__') {
              cuotaMan = toDouble(v['precio']);
              continue;
            }
            if (colNombre == '__pct_inicial__') {
              pctInicialOv = toDouble(v['precio']);
              continue;
            }
            if (colNombre == '__n_cuotas__') {
              final n = toDouble(v['precio']).round();
              if (n > 0) cuotasOv = n;
              continue;
            }
            // Cualquier otro nombre reservado (__x__) se ignora: no es
            // una columna de precios de verdad.
            if (FormulaColumna.esNombreVirtual(colNombre)) continue;
            precios[colNombre] = toDouble(v['precio']);
          }
        }
        items.add(ItemListaPrecio(
          producto: prod,
          preciosPorColumna: precios,
          stockDisponible: toInt(it['stock_disponible']) ?? 0,
          inicialManual: inicialMan,
          cuotaManual: cuotaMan,
          pctInicialOverride: pctInicialOv,
          cuotasOverride: cuotasOv,
        ));
      }
    }

    return ListaPrecio(
      id: toInt(m['id']),
      nombre: '${m['nombre'] ?? ''}',
      fechaCreacion: '${m['fecha_creacion'] ?? ''}',
      categoria: '${m['categoria'] ?? 'Todos'}',
      marcaFiltro: '${m['marca_filtro'] ?? 'Todas'}',
      esEnBolivares: toBool(m['es_en_bolivares']),
      tasaDelDia: toDouble(m['tasa_del_dia']),
      porcentajeAdicional: toDouble(m['porcentaje_adicional']),
      esFinanciamiento: toBool(m['es_financiamiento']),
      financiadora: m['financiadora']?.toString(),
      porcentajeInicial: toDouble(m['porcentaje_inicial']),
      numeroCuotas: toInt(m['numero_cuotas']) ?? 12,
      porcentajeComisionWeppa: toDouble(m['porcentaje_comision_weppa']),
      porcentajeRecargoCuotas: toDouble(m['porcentaje_recargo_cuotas']),
      // Default true para compatibilidad con listas viejas creadas
      // antes de agregar este campo
      tieneCuotas: m['tiene_cuotas'] == null
          ? true
          : toBool(m['tiene_cuotas']),
      columnas: cols,
      items: items,
    );
  }
}

List<ListaPrecio> listasPreciosGlobal = [];

// ============================================================
//  LISTAS EN MEMORIA (se recargan desde la API en cada pantalla)
// ============================================================
List<FacturaModel>             ventasGlobal                   = [];
List<LineaModel>               lineasGlobal                   = [];
List<Producto>                 catalogoGlobal                 = [];
List<ImeiRegistro>             _stockImeiGlobal               = [];
List<ImeiRegistro> get stockImeiGlobal => _stockImeiGlobal;
/// Cada vez que se recarga el stock de IMEIs se anotan las categorías
/// que tienen seriales registrados, para que `CategoriasProductos.usaIMEI`
/// las reconozca aunque este dispositivo no tenga el interruptor activado.
set stockImeiGlobal(List<ImeiRegistro> lista) {
  _stockImeiGlobal = lista;
  CategoriasProductos.registrarCategoriasConSeriales(lista);
}
List<CuentaPorCobrar>          cuentasGlobal                  = [];
List<CuentaPorPagar>           cuentasPorPagarGlobal          = [];
List<CuentaPorPagarProveedor>  cuentasPorPagarProveedorGlobal = [];
List<ServicioTecnico>          serviciosGlobal                = [];
List<CierreCaja>               cierresGlobal                  = [];
List<ResumenComision>          comisionesGuardadas            = [];
List<HistorialComision>        historialComisiones            = [];
List<Extraccion>               extraccionesGlobal             = [];

// ────────────────────────────────────────────────────────────
//  HELPERS DE PERMISOS POR TIENDA
//  Administrador, Dueño y Gerente pueden ver todas las tiendas.
//  El resto sólo ve la tienda que tiene asignada.
// ────────────────────────────────────────────────────────────
bool puedeVerTodasLasTiendas() {
  final rol = usuarioSesion?.rol;
  return rol == 'Administrador' || rol == 'Dueño' || rol == 'Gerente';
}

/// Devuelve la tienda asignada al usuario actual. Vacío = sin restricción
/// (normalmente sólo para roles altos que no tienen tienda configurada).
String tiendaUsuarioActual() => usuarioSesion?.tienda ?? '';

/// Filtra una lista de registros (mapas) dejando sólo los que pertenecen
/// a la tienda que el usuario puede ver. Si `puedeVerTodasLasTiendas()` es
/// true, respeta `tiendaFiltro` (null/"Todas" = no filtra).
List<Map<String, dynamic>> filtrarPorTienda(
    List<Map<String, dynamic>> registros, {String? tiendaFiltro}) {
  if (puedeVerTodasLasTiendas()) {
    if (tiendaFiltro == null || tiendaFiltro.isEmpty || tiendaFiltro == 'Todas') {
      return registros;
    }
    return registros.where((r) =>
        (r['tienda'] ?? '').toString() == tiendaFiltro).toList();
  }
  final miTienda = tiendaUsuarioActual();
  if (miTienda.isEmpty) return registros; // sin tienda asignada: no filtra
  return registros.where((r) =>
      (r['tienda'] ?? '').toString() == miTienda).toList();
}

// ── Buscar producto por código (versión async que consulta la API) ──
Future<Producto?> buscarProductoPorCodigoAsync(String codigo) async {
  try {
    final raw = await _Api.get('productos', {'codigo': codigo});
    if (raw != null) return Producto.fromMap(raw);
  } catch (e) { debugPrint('buscarProducto por código: $e'); }
  try {
    final imeiRaw = await _Api.get('stock_imei', {'imei': codigo});
    if (imeiRaw != null && imeiRaw['vendido'] == 0) {
      final prodRaw = await _Api.get('productos', {'codigo': imeiRaw['producto_codigo']});
      if (prodRaw != null) return Producto.fromMap(prodRaw);
    }
  } catch (e) { debugPrint('buscarProducto por IMEI: $e'); }
  return null;
}

// Versión síncrona que usa las listas en memoria
Producto? buscarProductoPorCodigo(String codigo) {
  // firstWhere lanza StateError si no encuentra — usamos orElse para evitarlo
  final porCodigo = catalogoGlobal.where((p) => p.codigo == codigo).firstOrNull;
  if (porCodigo != null) return porCodigo;
  final imei = stockImeiGlobal.where((i) => i.imei == codigo && !i.vendido).firstOrNull;
  if (imei != null) {
    return catalogoGlobal.where((p) => p.codigo == imei.producto.codigo).firstOrNull;
  }
  return null;
}

// ════════════════════════════════════════════════════════════
//  INGRESO RÁPIDO DE STOCK (productos SIN IMEI)
// ════════════════════════════════════════════════════════════
//  Los accesorios, forros, cargadores, etc. no llevan IMEI: su
//  existencia es un simple contador (`stock_manual`). Antes, para
//  cargar mercancía había que abrir la ficha completa del producto,
//  editar el campo cantidad y guardar todo el formulario — lento y
//  arriesgado, porque cualquier campo tocado sin querer se guardaba
//  junto con el stock.
//
//  Estas funciones ajustan SOLO el stock, reutilizando el resto de
//  los datos del producto tal como están.
// ════════════════════════════════════════════════════════════

/// Resultado de un ajuste de stock.
class ResultadoAjusteStock {
  final bool ok;
  final String mensaje;
  /// Stock que quedó guardado (el valor viejo si falló).
  final int stockFinal;
  const ResultadoAjusteStock(this.ok, this.mensaje, this.stockFinal);
}

/// Suma [delta] unidades al stock manual de [prod] y lo persiste.
///
/// [delta] puede ser negativo para descontar. El stock nunca baja de 0.
/// Si el producto no trae `id` (lista construida a mano o backend viejo),
/// se resuelve buscándolo por `codigo`.
///
/// Actualiza el objeto [prod] en memoria sólo si el guardado tuvo éxito,
/// para que la pantalla no muestre un número que el servidor no aceptó.
Future<ResultadoAjusteStock> ajustarStockManual(
    Producto prod, int delta) async {
  final nuevo = (prod.stockManual + delta).clamp(0, 999999);
  return establecerStockManual(prod, nuevo);
}

/// Fija el stock manual de [prod] en [nuevoStock] y lo persiste.
Future<ResultadoAjusteStock> establecerStockManual(
    Producto prod, int nuevoStock) async {
  final anterior = prod.stockManual;
  final destino = nuevoStock < 0 ? 0 : nuevoStock;
  if (destino == anterior) {
    return ResultadoAjusteStock(true, 'Sin cambios', anterior);
  }
  try {
    // El backend identifica por id numérico, no por SKU.
    int? id = prod.id;
    if (id == null) {
      final raw = await _Api.get('productos', {'codigo': prod.codigo});
      if (raw is Map && raw['id'] != null) {
        id = raw['id'] is int
            ? raw['id'] as int
            : int.tryParse(raw['id'].toString());
      }
    }
    if (id == null) {
      return ResultadoAjusteStock(false,
          'No se encontró "${prod.nombre}" en la base de datos. '
          'Refrescá el inventario e intentá de nuevo.', anterior);
    }
    // Mandamos el producto completo con el stock nuevo: el endpoint
    // `productos` es un PUT de reemplazo, no un PATCH parcial.
    prod.stockManual = destino;
    await _Api.put('productos', id.toString(), prod.toMap());
    prod.id = id; // cachear para los próximos ajustes
    return ResultadoAjusteStock(true,
        '${prod.nombre}: $anterior → $destino', destino);
  } catch (e) {
    prod.stockManual = anterior; // revertir el optimismo
    debugPrint('[ajustarStock] Error: $e');
    return ResultadoAjusteStock(false, 'No se pudo guardar: $e', anterior);
  }
}

// ── CONTRATO WEPPA ────────────────────────────────────────────
//  Modelo para los contratos de venta a cuotas de Weppa Group.
//  Cada contrato queda guardado en el historial (tabla
//  `contratos_weppa` del backend) y se envía por correo al cliente.
// ============================================================
class CuotaContrato {
  int numero;
  DateTime fecha;
  double monto;
  CuotaContrato({required this.numero, required this.fecha, required this.monto});

  Map<String, dynamic> toMap() => {
    'numero': numero,
    'fecha': "${fecha.year}-${fecha.month.toString().padLeft(2,'0')}-${fecha.day.toString().padLeft(2,'0')}",
    'monto': monto,
  };

  factory CuotaContrato.fromMap(Map m) {
    DateTime parseFecha(String s) {
      try { return DateTime.parse(s); } catch (_) { return DateTime.now(); }
    }
    return CuotaContrato(
      numero: (m['numero'] is int) ? m['numero'] : int.tryParse('${m['numero']}') ?? 0,
      fecha: parseFecha('${m['fecha'] ?? ''}'),
      monto: (m['monto'] is num) ? (m['monto'] as num).toDouble() : double.tryParse('${m['monto']}') ?? 0,
    );
  }
}


// ── CONTRATO DE CAMBIO DE SIM CARD / eSIM ────────────────────
//  Modelo para el "Formato de Autorización para Cambio de Sim
//  Card y Cambio de Número" de Telefónica Venezolana (Movistar).
//  Se genera automáticamente desde la ventana de Líneas cuando
//  el tipo es "Sim a Sim", "eSim a eSIM", "Sim a eSIM" o
//  "eSIM a Sim". Guarda el registro en el historial
//  (tabla `contratos_simcard` del backend).
// ============================================================
class ContratoSimCard {
  int? id;
  String fechaCreacion;          // ISO yyyy-MM-dd HH:mm:ss
  String fechaSolicitud;         // Fecha que aparece en el formato (dd/mm/yyyy)
  String tipoCambio;             // "Sim a Sim", "eSim a eSIM", etc.
  // Datos de la gestión
  String centroServicio;         // Centro de Servicio / AA
  String numeroCuenta;           // Cuenta Movistar
  // Datos del cliente titular
  String nombreCliente;
  String cedulaCliente;
  String correoCliente;
  String numeroMovil;            // Nº móvil de contacto del titular
  // Datos SIM/eSIM
  String iccidAnterior;
  String iccidNuevo;
  String numeroTelefonicoAnterior;
  String numeroTelefonicoNuevo;
  // Datos del vendedor
  String codigoVentaAA;          // VI_____
  String nombreVendedor;
  // Firma y huellas
  String? firmaBase64;
  String? huellaPulgarIzquierdoBase64;
  String? huellaIndiceDerechoBase64;
  // Foto de cédula (opcional)
  String? cedulaFotoBase64;
  // Estado y PDF
  String estado;                 // Activo, Anulado
  String? pdfBase64;
  // Referencia a la línea asociada (si se creó desde Líneas)
  int? lineaId;

  ContratoSimCard({
    this.id,
    required this.fechaCreacion,
    required this.fechaSolicitud,
    required this.tipoCambio,
    this.centroServicio = '',
    this.numeroCuenta = '',
    required this.nombreCliente,
    required this.cedulaCliente,
    this.correoCliente = '',
    this.numeroMovil = '',
    this.iccidAnterior = '',
    this.iccidNuevo = '',
    this.numeroTelefonicoAnterior = '',
    this.numeroTelefonicoNuevo = '',
    this.codigoVentaAA = '',
    this.nombreVendedor = '',
    this.firmaBase64,
    this.huellaPulgarIzquierdoBase64,
    this.huellaIndiceDerechoBase64,
    this.cedulaFotoBase64,
    this.estado = 'Activo',
    this.pdfBase64,
    this.lineaId,
  });

  Map<String, dynamic> toMap() => {
    if (id != null) 'id': id,
    'fecha_creacion': fechaCreacion,
    'fecha_solicitud': fechaSolicitud,
    'tipo_cambio': tipoCambio,
    'centro_servicio': centroServicio,
    'numero_cuenta': numeroCuenta,
    'nombre_cliente': nombreCliente,
    'cedula_cliente': cedulaCliente,
    'correo_cliente': correoCliente,
    'numero_movil': numeroMovil,
    'iccid_anterior': iccidAnterior,
    'iccid_nuevo': iccidNuevo,
    'numero_telefonico_anterior': numeroTelefonicoAnterior,
    'numero_telefonico_nuevo': numeroTelefonicoNuevo,
    'codigo_venta_aa': codigoVentaAA,
    'nombre_vendedor': nombreVendedor,
    'estado': estado,
    if (firmaBase64 != null) 'firma_base64': firmaBase64,
    if (huellaPulgarIzquierdoBase64 != null)
      'huella_pulgar_izquierdo_base64': huellaPulgarIzquierdoBase64,
    if (huellaIndiceDerechoBase64 != null)
      'huella_indice_derecho_base64': huellaIndiceDerechoBase64,
    if (cedulaFotoBase64 != null) 'cedula_foto_base64': cedulaFotoBase64,
    if (pdfBase64 != null) 'pdf_base64': pdfBase64,
    if (lineaId != null) 'linea_id': lineaId,
  };

  factory ContratoSimCard.fromMap(Map m) {
    int toInt(dynamic v) =>
        (v is int) ? v : int.tryParse('${v ?? 0}') ?? 0;
    return ContratoSimCard(
      id: m['id'] == null ? null : toInt(m['id']),
      fechaCreacion: '${m['fecha_creacion'] ?? ''}',
      fechaSolicitud: '${m['fecha_solicitud'] ?? ''}',
      tipoCambio: '${m['tipo_cambio'] ?? ''}',
      centroServicio: '${m['centro_servicio'] ?? ''}',
      numeroCuenta: '${m['numero_cuenta'] ?? ''}',
      nombreCliente: '${m['nombre_cliente'] ?? ''}',
      cedulaCliente: '${m['cedula_cliente'] ?? ''}',
      correoCliente: '${m['correo_cliente'] ?? ''}',
      numeroMovil: '${m['numero_movil'] ?? ''}',
      iccidAnterior: '${m['iccid_anterior'] ?? ''}',
      iccidNuevo: '${m['iccid_nuevo'] ?? ''}',
      numeroTelefonicoAnterior: '${m['numero_telefonico_anterior'] ?? ''}',
      numeroTelefonicoNuevo: '${m['numero_telefonico_nuevo'] ?? ''}',
      codigoVentaAA: '${m['codigo_venta_aa'] ?? ''}',
      nombreVendedor: '${m['nombre_vendedor'] ?? ''}',
      firmaBase64: m['firma_base64'] as String?,
      huellaPulgarIzquierdoBase64:
          m['huella_pulgar_izquierdo_base64'] as String?,
      huellaIndiceDerechoBase64:
          m['huella_indice_derecho_base64'] as String?,
      cedulaFotoBase64: m['cedula_foto_base64'] as String?,
      estado: '${m['estado'] ?? 'Activo'}',
      pdfBase64: m['pdf_base64'] as String?,
      lineaId: m['linea_id'] == null ? null : toInt(m['linea_id']),
    );
  }
}

/// Lista global de contratos SIM Card (historial en memoria).
List<ContratoSimCard> contratosSimCardGlobal = [];

// ============================================================
//  FUNCIONES DE CARGA DESDE API (llenan las listas globales)
//  Usa Future.wait para cargar en paralelo y reducir el tiempo
//  total de inicio de sesión.
// ============================================================
Future<void> cargarTodosLosDatos() async {
  // Cargar productos, IMEIs, líneas, usuarios y clientes en paralelo
  final results = await Future.wait([
    _Api.get('productos').catchError((e) { debugPrint('Error productos: $e'); return null; }),
    _Api.get('stock_imei').catchError((e) { debugPrint('Error stock_imei: $e'); return null; }),
    _Api.get('lineas').catchError((e) { debugPrint('Error lineas: $e'); return null; }),
    _Api.get('usuarios').catchError((e) { debugPrint('Error usuarios: $e'); return null; }),
  ]);

  // ── Productos ──────────────────────────────────────────────
  if (results[0] != null) {
    catalogoGlobal = ((results[0] as List?) ?? [])
        .map((m) => Producto.fromMap(m)).toList();
  }

  // ── IMEIs + stock de teléfonos ────────────────────────────
  if (results[1] != null) {
    stockImeiGlobal = ((results[1] as List?) ?? [])
        .map((m) => ImeiRegistro.fromMap(m)).toList();
    for (final p in catalogoGlobal) {
      if (CategoriasProductos.usaIMEI(p.categoria)) {
        p.stockTotal = stockImeiGlobal
            .where((i) => i.producto.codigo == p.codigo && !i.vendido)
            .length;
      } else {
        p.stockTotal = p.stockManual;
      }
    }
  }

  // ── Líneas ────────────────────────────────────────────────
  if (results[2] != null) {
    lineasGlobal = ((results[2] as List?) ?? [])
        .map((m) => LineaModel.fromMap(m)).toList();
  }

  // ── Usuarios ──────────────────────────────────────────────
  if (results[3] != null) {
    final todos = ((results[3] as List?) ?? [])
        .map((m) => Usuario.fromMap(m)).toList();
    // Excluir al UsuarioMaestro de la lista global (no debe aparecer
    // en selectores de vendedor, comisiones, ranking, etc.).
    usuariosSistema = UsuarioMaestro.ocultar<Usuario>(
        todos, (u) => u.correo);
  }

  // ── Clientes ──────────────────────────────────────────────
  // Los clientes NO se cargan desde un endpoint propio — se
  // reconstruyen a partir de las facturas (agrupando por cédula).
  // La función `reconstruirClientesDesdeFacturas()` se llama junto
  // con `actualizarConteoCompras()` más abajo.

  // ── Conteo de compras por cliente + lista de clientes ──────
  // Carga las facturas, cuenta cuántas veces ha comprado cada cédula
  // y genera el listado global de clientes desde esa misma fuente.
  // No bloquea la app si falla (solo queda todo vacío).
  await reconstruirClientesDesdeFacturas();

  // ── Garantizar que el admin maestro siempre esté presente ─
  // (Aunque no esté en la BD o la API haya fallado.)
  // TODO: configurar correo admin real de Tecno Líder
  const _adminCorreoMaestro = 'tecnolider@gmail.com';
  final tieneAdmin = usuariosSistema.any((u) =>
      u.correo.toLowerCase() == _adminCorreoMaestro);
  if (!tieneAdmin) {
    usuariosSistema.insert(0, Usuario(
      id: 1,
      nombre: 'Administrador',
      cedula: 'ADMIN',
      correo: _adminCorreoMaestro,
      clave: 'TecnoLider.1508', // TODO: cambiar clave por defecto
      rol: 'Administrador',
      sueldoBase: 0,
    ));
  }

  // Facturas: se carga vacío al inicio, se llenan por pantalla
  ventasGlobal = [];
}

// ============================================================
//  APP PRINCIPAL
// ============================================================
class MyApp extends StatefulWidget {
  const MyApp({super.key});
  @override
  State<MyApp> createState() => _MyAppState();
}

class _MyAppState extends State<MyApp> {
  @override
  void initState() {
    super.initState();
    // ── Solicitar permisos DESPUÉS de que el primer frame se haya
    //    renderizado. Es CRÍTICO hacerlo aquí (y no en main() antes
    //    de runApp) porque varios dispositivos Android — especialmente
    //    Xiaomi, Huawei y Samsung — NO muestran los diálogos del SO
    //    si la app aún no tiene Activity visible. Esperar al primer
    //    frame garantiza que la Activity está creada y enganchada al
    //    WindowManager, lo que permite al SO mostrar los prompts. ──
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      // Pequeño delay extra para asegurar que la animación de splash
      // termine antes de mostrar los diálogos del sistema.
      await Future.delayed(const Duration(milliseconds: 500));
      try {
        await PermisosApp.solicitarTodos();
      } catch (e) {
        debugPrint('[MyApp] Error al solicitar permisos: $e');
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      title: 'Tecno Líder',
      // Tema CLARO siempre. La app NO sigue el modo oscuro del SO —
      // se mantiene siempre con la identidad visual clara de Tecno
      // Líder (azul royal + amarillo dorado sobre fondos claros).
      themeMode: ThemeMode.light,
      theme: _buildAppTheme(Brightness.light),
      home: const LoginPage(),
    );
  }
}

// ════════════════════════════════════════════════════════════════════
//  CONSTRUCTOR DEL TEMA — CLARO Y OSCURO
// ════════════════════════════════════════════════════════════════════
//  Genera un ThemeData consistente con la identidad visual Tecno
//  Líder. Toma `Brightness.light` o `Brightness.dark` y configura
//  todos los componentes (AppBar, botones, inputs, cards, dialogs,
//  snackbars, FAB) acordes al modo.
//
//  Decisiones clave:
//    · `useMaterial3: true` → usa Material You / M3 (UI moderna)
//    · ColorScheme generado desde el azul de marca como semilla
//    · AppBar SIEMPRE en azul royal (refuerza marca, ambos modos)
//    · FAB SIEMPRE en amarillo (CTA visualmente distintivo)
//    · Inputs con bordes redondeados y focus en amarillo
//      (el amarillo "energiza" el campo activo, mejor que azul
//       sobre azul que se pierde visualmente)
//    · Card sombra de marca en claro, profunda en oscuro
// ════════════════════════════════════════════════════════════════════
/// Tema claro de la app, para `tool/capturas_ipad_test.dart`, que dibuja
/// las pantallas fuera de la app para las capturas de App Store.
@visibleForTesting
ThemeData temaAppClaro() => _buildAppTheme(Brightness.light);

ThemeData _buildAppTheme(Brightness brightness) {
  final isDark = brightness == Brightness.dark;

  // Superficies que cambian entre modos
  final surface       = isDark ? AppColors.darkSurface     : AppColors.surfaceCard;
  final surfaceAlt    = isDark ? AppColors.darkSurfaceAlt  : AppColors.surfaceTintBlueSoft;
  final scaffoldBg    = isDark ? AppColors.darkBackground  : AppColors.surfaceTintBlue;
  final textPrimary   = isDark ? AppColors.darkTextPrimary : AppColors.textPrimary;
  final textSecondary = isDark ? AppColors.darkTextSecondary : AppColors.textSecondary;
  final divider       = isDark ? AppColors.darkBorder      : AppColors.cardBorderTinted;

  return ThemeData(
    useMaterial3: true,
    brightness: brightness,
    colorScheme: ColorScheme.fromSeed(
      seedColor: AppColors.brandBlue,
      brightness: brightness,
      primary: AppColors.brandBlue,
      onPrimary: Colors.white,
      secondary: AppColors.brandYellow,
      onSecondary: AppColors.brandBlueDeeper,
      tertiary: AppColors.brandBlueDark,
      surface: surface,
      onSurface: textPrimary,
      error: AppColors.statusRed,
      onError: Colors.white,
    ),

    scaffoldBackgroundColor: scaffoldBg,
    canvasColor: surface,

    // ── AppBar: azul royal con sombra sutil amarilla (marca) ──
    appBarTheme: const AppBarTheme(
      backgroundColor: AppColors.brandBlueDark,
      foregroundColor: Colors.white,
      surfaceTintColor: Colors.transparent,
      elevation: 0,
      scrolledUnderElevation: 4,
      shadowColor: AppColors.brandBlueDeeper,
      centerTitle: false,
      titleTextStyle: TextStyle(
        color: Colors.white,
        fontSize: 18,
        fontWeight: FontWeight.w800,
        letterSpacing: 0.4,
      ),
      iconTheme: IconThemeData(color: Colors.white),
      actionsIconTheme: IconThemeData(color: Colors.white),
    ),

    // ── Botón principal: gradient implícito vía estilo ────────
    elevatedButtonTheme: ElevatedButtonThemeData(
      style: ElevatedButton.styleFrom(
        backgroundColor: AppColors.brandBlueDark,
        foregroundColor: Colors.white,
        padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 14),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
        elevation: 0,
        textStyle: const TextStyle(
          fontSize: 15, fontWeight: FontWeight.w600, letterSpacing: 0.5),
      ),
    ),

    // ── Botón outline ─────────────────────────────────────────
    outlinedButtonTheme: OutlinedButtonThemeData(
      style: OutlinedButton.styleFrom(
        foregroundColor: AppColors.brandBlue,
        side: const BorderSide(color: AppColors.brandBlue, width: 1.5),
        padding: const EdgeInsets.symmetric(horizontal: 22, vertical: 13),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
      ),
    ),

    // ── Botón texto ───────────────────────────────────────────
    textButtonTheme: TextButtonThemeData(
      style: TextButton.styleFrom(
        foregroundColor: AppColors.brandBlue,
        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
      ),
    ),

    // ── Inputs: focus en azul de marca (cohesión total) ──────
    inputDecorationTheme: InputDecorationTheme(
      filled: true,
      fillColor: surfaceAlt,
      labelStyle: TextStyle(color: textSecondary, fontWeight: FontWeight.w500),
      hintStyle: TextStyle(color: textSecondary.withValues(alpha: 0.7)),
      prefixIconColor: AppColors.brandBlue,
      suffixIconColor: textSecondary,
      border: OutlineInputBorder(
        borderRadius: BorderRadius.circular(12),
        borderSide: BorderSide.none,
      ),
      enabledBorder: OutlineInputBorder(
        borderRadius: BorderRadius.circular(12),
        borderSide: BorderSide(color: divider, width: 1),
      ),
      focusedBorder: OutlineInputBorder(
        borderRadius: BorderRadius.circular(12),
        borderSide: const BorderSide(color: AppColors.brandBlue, width: 2),
      ),
      errorBorder: OutlineInputBorder(
        borderRadius: BorderRadius.circular(12),
        borderSide: const BorderSide(color: AppColors.statusRed, width: 1.5),
      ),
      focusedErrorBorder: OutlineInputBorder(
        borderRadius: BorderRadius.circular(12),
        borderSide: const BorderSide(color: AppColors.statusRed, width: 2),
      ),
      contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 16),
    ),

    // ── Cards: bordes sutiles azules + sombra cálida ──────────
    cardTheme: CardThemeData(
      color: surface,
      elevation: isDark ? 0 : 1,
      shadowColor: isDark
          ? Colors.black.withValues(alpha: 0.3)
          : AppColors.brandBlue.withValues(alpha: 0.10),
      surfaceTintColor: Colors.transparent,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(16),
        side: BorderSide(
          color: isDark
              ? divider
              : AppColors.brandBlue.withValues(alpha: 0.08),
          width: 1,
        ),
      ),
      margin: EdgeInsets.zero,
    ),

    // ── FAB: amarillo de marca (ambos modos) ─────────────────
    floatingActionButtonTheme: const FloatingActionButtonThemeData(
      backgroundColor: AppColors.brandYellow,
      foregroundColor: AppColors.brandBlueDeeper,
      elevation: 6,
      focusElevation: 8,
      hoverElevation: 8,
      highlightElevation: 4,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.all(Radius.circular(16)),
      ),
    ),

    // ── Chips ─────────────────────────────────────────────────
    chipTheme: ChipThemeData(
      backgroundColor: surfaceAlt,
      selectedColor: AppColors.brandBlue.withValues(alpha: 0.15),
      labelStyle: TextStyle(color: textPrimary, fontWeight: FontWeight.w500),
      side: BorderSide(color: divider),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
    ),

    // ── SnackBar ──────────────────────────────────────────────
    snackBarTheme: SnackBarThemeData(
      behavior: SnackBarBehavior.floating,
      backgroundColor: isDark ? AppColors.darkSurface : AppColors.brandBlueDark,
      contentTextStyle: const TextStyle(color: Colors.white),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.all(Radius.circular(12)),
      ),
      actionTextColor: AppColors.brandYellow,
    ),

    // ── Diálogos ─────────────────────────────────────────────
    dialogTheme: DialogThemeData(
      backgroundColor: surface,
      surfaceTintColor: Colors.transparent,
      elevation: 8,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.all(Radius.circular(20)),
      ),
      titleTextStyle: TextStyle(
        color: textPrimary,
        fontSize: 18,
        fontWeight: FontWeight.w700,
      ),
      contentTextStyle: TextStyle(color: textPrimary, fontSize: 14),
    ),

    // ── BottomSheet ───────────────────────────────────────────
    bottomSheetTheme: BottomSheetThemeData(
      backgroundColor: surface,
      surfaceTintColor: Colors.transparent,
      elevation: 8,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
    ),

    // ── Divider ───────────────────────────────────────────────
    dividerTheme: DividerThemeData(
      color: divider,
      space: 1,
      thickness: 1,
    ),

    // ── ListTile ──────────────────────────────────────────────
    listTileTheme: ListTileThemeData(
      iconColor: AppColors.brandBlue,
      textColor: textPrimary,
      titleTextStyle: TextStyle(
        color: textPrimary, fontSize: 15, fontWeight: FontWeight.w500),
      subtitleTextStyle: TextStyle(color: textSecondary, fontSize: 13),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
    ),

    // ── Switch / Checkbox / Radio: amarillo cuando activo ────
    switchTheme: SwitchThemeData(
      thumbColor: WidgetStateProperty.resolveWith(
        (states) => states.contains(WidgetState.selected)
            ? AppColors.brandYellow
            : Colors.grey,
      ),
      trackColor: WidgetStateProperty.resolveWith(
        (states) => states.contains(WidgetState.selected)
            ? AppColors.brandYellow.withValues(alpha: 0.4)
            : Colors.grey.withValues(alpha: 0.3),
      ),
    ),
    checkboxTheme: CheckboxThemeData(
      fillColor: WidgetStateProperty.resolveWith(
        (states) => states.contains(WidgetState.selected)
            ? AppColors.brandBlue : Colors.transparent,
      ),
      checkColor: const WidgetStatePropertyAll(Colors.white),
      side: BorderSide(color: divider, width: 1.5),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(4)),
    ),

    // ── ProgressIndicator ─────────────────────────────────────
    progressIndicatorTheme: const ProgressIndicatorThemeData(
      color: AppColors.brandYellow,
      linearTrackColor: Color(0x33FFC20E),
      circularTrackColor: Color(0x22FFC20E),
    ),

    // ── Tipografía ────────────────────────────────────────────
    textTheme: TextTheme(
      headlineLarge:  TextStyle(color: textPrimary, fontWeight: FontWeight.w800),
      headlineMedium: TextStyle(color: textPrimary, fontWeight: FontWeight.w700),
      titleLarge:     TextStyle(color: textPrimary, fontWeight: FontWeight.w700),
      titleMedium:    TextStyle(color: textPrimary, fontWeight: FontWeight.w600),
      bodyLarge:      TextStyle(color: textPrimary),
      bodyMedium:     TextStyle(color: textPrimary),
      bodySmall:      TextStyle(color: textSecondary),
      labelLarge:     TextStyle(color: textPrimary, fontWeight: FontWeight.w600),
    ),

    iconTheme: IconThemeData(color: textSecondary),
    primaryIconTheme: const IconThemeData(color: Colors.white),

    // ── Tab bar ───────────────────────────────────────────────
    tabBarTheme: const TabBarThemeData(
      labelColor: Colors.white,
      unselectedLabelColor: Colors.white70,
      indicatorColor: AppColors.brandYellow,
      indicatorSize: TabBarIndicatorSize.label,
      labelStyle: TextStyle(fontWeight: FontWeight.w700),
    ),
  );
}

// ============================================================
//  LOGIN — consulta la base de datos real
// ============================================================
class LoginPage extends StatefulWidget {
  const LoginPage({super.key});
  @override State<LoginPage> createState() => _LoginPageState();
}

class _LoginPageState extends State<LoginPage> with SingleTickerProviderStateMixin {
  final _u = TextEditingController(), _p = TextEditingController();
  bool _cargando = false;
  bool _verClave = false; // toggle visibilidad contraseña
  bool _intentandoAutoLogin = true;

  /// Tienda seleccionada antes de iniciar sesión. Si está marcada,
  /// el flujo de login NO mostrará el diálogo de selección posterior
  /// (mejora la UX en dispositivos donde el operador siempre trabaja
  /// en el mismo PDV). Null = preguntar después como antes.
  String? _tiendaSeleccionada;

  // ── Animación de entrada ──────────────────────────────────
  late final AnimationController _animCtrl;
  late final Animation<double> _animFade;
  late final Animation<Offset> _animSlide;

  @override
  void initState() {
    super.initState();
    _animCtrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 700),
    );
    _animFade = CurvedAnimation(parent: _animCtrl, curve: Curves.easeOut);
    _animSlide = Tween<Offset>(
      begin: const Offset(0, 0.08),
      end: Offset.zero,
    ).animate(CurvedAnimation(parent: _animCtrl, curve: Curves.easeOutCubic));
    _animCtrl.forward();
    // Sincronizar tiendas con el backend antes de nada. Así el
    // selector de tienda del login (si aparece) o el auto-login
    // muestran las tiendas reales, no la lista hardcodeada.
    sincronizarTiendasBackend();
    // Sincronizar la configuración global (días de garantía, texto
    // de pie de factura, nombre de empresa, etc.) desde el backend.
    // Si el backend está vacío, hace push automático de lo local.
    ConfigSistema.sincronizarConfigBackend();
    // Categorías de producto y su interruptor de IMEI: compartidos
    // entre todos los dispositivos.
    CategoriasProductos.sincronizarConBackend();
    _intentarAutoLogin();
  }

  @override
  void dispose() {
    _animCtrl.dispose();
    _u.dispose();
    _p.dispose();
    super.dispose();
  }

  /// Intenta auto-login con las credenciales guardadas. Si tiene éxito,
  /// navega directamente a la pantalla principal sin mostrar el form.
  /// Si falla (credenciales inválidas o sin sesión guardada), muestra
  /// el formulario normal de login.
  Future<void> _intentarAutoLogin() async {
    try {
      final cred = await SesionPersistente.leer();
      if (cred == null) {
        if (mounted) setState(() => _intentandoAutoLogin = false);
        return;
      }
      // Pre-llenar los campos para que si el auto-login falla, el
      // usuario vea sus credenciales y pueda corregir/reintentar.
      _u.text = cred.correo;
      _p.text = cred.clave;
      // Disparar el flujo normal de login
      await _login();
    } catch (e) {
      debugPrint('[Sesion] auto-login: $e');
    } finally {
      if (mounted) setState(() => _intentandoAutoLogin = false);
    }
  }

  Future<void> _login() async {
    final correo = _u.text.trim().toLowerCase();
    final clave  = _p.text; // NO aplicar trim a contraseñas

    // ── Validaciones locales ────────────────────────────────
    if (correo.isEmpty) {
      _mostrarError("Por favor ingrese su correo o usuario.");
      return;
    }
    // Validación básica de formato de correo
    final emailRegex = RegExp(r'^[^@\s]+@[^@\s]+\.[^@\s]+$');
    if (!emailRegex.hasMatch(correo)) {
      _mostrarError("Ingrese un correo electrónico válido.");
      return;
    }
    if (clave.isEmpty) {
      _mostrarError("Por favor ingrese su contraseña.");
      return;
    }
    if (clave.length < 4) {
      _mostrarError("La contraseña debe tener al menos 4 caracteres.");
      return;
    }

    setState(() => _cargando = true);

    // ═══════════════════════════════════════════════════════════════
    //  RECONOCIMIENTO DEL USUARIO MAESTRO (proveedor Tecno Líder)
    //  El maestro tiene credenciales hardcoded (UsuarioMaestro.correo
    //  + clave) y bypasea TODAS las verificaciones: API, BD, licencia.
    //  Usado para soporte y para gestionar el bloqueo del sistema.
    // ═══════════════════════════════════════════════════════════════
    final esUsuarioMaestro = UsuarioMaestro.esMaestro(correo, clave);

    // Mantenemos el "admin maestro" antiguo (admin de la empresa cliente)
    // como fallback de emergencia si la API se cae. Esto NO es el maestro
    // del proveedor — solo un admin de respaldo del cliente.
    // TODO: configurar correo admin real de Tecno Líder
    const _adminCorreo = 'tecnolider@gmail.com';
    const _adminClave  = 'TecnoLider.1508'; // TODO: cambiar clave por defecto
    final esAdminMaestro = (correo == _adminCorreo && clave == _adminClave);

    // ═══════════════════════════════════════════════════════════════
    //  VERIFICACIÓN DE LICENCIA — solo aplica a usuarios normales
    //  El UsuarioMaestro PUEDE entrar siempre (es quien controla el
    //  bloqueo). Los demás son rechazados si la app está suspendida.
    // ═══════════════════════════════════════════════════════════════
    if (!esUsuarioMaestro) {
      try {
        await LicenciaService.cargarEstado();
      } catch (_) { /* ignoramos errores; usaremos el último estado */ }

      final estado = LicenciaService.estadoActual;
      if (estado.bloqueada) {
        if (!mounted) return;
        setState(() => _cargando = false);
        // Mostrar pantalla de bloqueo en lugar de la pantalla principal.
        Navigator.pushReplacement(
          context,
          MaterialPageRoute(builder: (_) => const PantallaBloqueoLicencia()),
        );
        return;
      }
    }

    try {
      dynamic raw;

      if (esUsuarioMaestro) {
        // Maestro: NO consultamos BD. Construimos su sesión directamente.
        debugPrint('[Login] ✔ Acceso UsuarioMaestro (proveedor)');
        raw = null; // se manejará en el bloque de fallback
      } else {
        try {
          raw = await _Api.get('usuarios', {'correo': correo, 'clave': clave});
        } catch (e) {
          // Si la API falla pero son las credenciales del admin maestro
          // local, permitimos el ingreso offline (modo de emergencia).
          if (!esAdminMaestro) rethrow;
          debugPrint('[Login] API no disponible, usando admin local: $e');
          raw = null;
        }
      }

      if (raw == null) {
        if (esUsuarioMaestro) {
          // Sesión del UsuarioMaestro (proveedor Tecno Líder).
          // NO se persiste, NO aparece en lista de Usuarios. Tiene rol
          // especial 'Maestro' que da acceso al Panel Maestro oculto.
          usuarioSesion = Usuario(
            id: -1,  // ID negativo = no real, no afecta BD
            nombre: UsuarioMaestro.nombre,
            cedula: 'MAESTRO',
            correo: UsuarioMaestro.correo,
            clave: UsuarioMaestro.clave,
            rol: 'Maestro',
            sueldoBase: 0,
          );
          debugPrint('[Login] ✔ Ingreso como UsuarioMaestro');
        } else if (esAdminMaestro) {
          // Fallback: admin local de la empresa cliente cuando la API
          // está caída.
          usuarioSesion = Usuario(
            id: 1,
            nombre: 'Administrador',
            cedula: 'ADMIN',
            correo: _adminCorreo,
            clave: _adminClave,
            rol: 'Administrador',
            sueldoBase: 0,
          );
          debugPrint('[Login] ✔ Ingreso como admin maestro (fallback local)');
        } else {
          if (!mounted) return;
          _mostrarError(
            "Credenciales incorrectas. Verifique su usuario y contraseña.",
            duracion: const Duration(seconds: 5),
          );
          return;
        }
      } else {
        usuarioSesion = Usuario.fromMap(raw);
      }

      // ── Guardar sesión persistente ──
      // Próxima vez que se abra la app, hará auto-login con estas
      // credenciales sin pedir el formulario de login.
      // EXCEPCIÓN: el UsuarioMaestro NO se persiste por seguridad
      // (sus credenciales no quedan guardadas en el dispositivo).
      if (usuarioSesion != null && !esUsuarioMaestro) {
        await SesionPersistente.guardar(correo, clave);
      }

      // Cargar datos globales al iniciar sesión (en paralelo donde sea posible)
      if (mounted) {
        // Mostrar indicador de carga mientras se cargan los datos
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
          content: Row(children: [
            SizedBox(width: 16, height: 16,
              child: CircularProgressIndicator(color: Colors.white, strokeWidth: 2)),
            SizedBox(width: 12),
            Text("Cargando datos del sistema..."),
          ]),
          duration: Duration(seconds: 10),
          backgroundColor: AppColors.royalBlue,
        ));
      }

      await cargarTodosLosDatos();
      NotificacionesService.iniciar();

      if (!mounted) return;
      ScaffoldMessenger.of(context).hideCurrentSnackBar();

      // Selección de tienda — si el usuario ya eligió en el formulario
      // del login (selector visible), saltamos este diálogo y vamos
      // directo a Ventas. Si no, se muestra como antes para no romper
      // el flujo en sesiones donde la preferencia no se cargó.
      String? tiendaSeleccionada = _tiendaSeleccionada;
      if (tiendaSeleccionada != null &&
          ConfigSistema.tiendas.contains(tiendaSeleccionada)) {
        // Validamos que la tienda elegida exista en la lista actual
        // (la lista se actualiza en `cargarTodosLosDatos`).
      } else {
        tiendaSeleccionada = await showDialog<String>(
        context: context,
        barrierDismissible: false,
        builder: (context) => AlertDialog(
          title: const Row(children: [
            Icon(Icons.store, color: AppColors.primaryBlue),
            SizedBox(width: 8),
            Text("Seleccione Punto de Venta"),
          ]),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                "Bienvenido, ${usuarioSesion?.nombre ?? 'Usuario'}",
                style: const TextStyle(color: AppColors.textSecondary, fontSize: 13),
              ),
              const SizedBox(height: 12),
              ...ConfigSistema.tiendas.map((tienda) => Padding(
                padding: const EdgeInsets.only(bottom: 6),
                child: ListTile(
                  leading: Container(
                    padding: const EdgeInsets.all(8),
                    decoration: BoxDecoration(
                      color: AppColors.primaryBlue.withValues(alpha: 0.1),
                      borderRadius: BorderRadius.circular(8),
                    ),
                    child: const Icon(Icons.storefront_outlined, color: AppColors.royalBlue, size: 20),
                  ),
                  title: Text(tienda, style: const TextStyle(fontWeight: FontWeight.w600)),
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
                  tileColor: AppColors.surfaceGrey,
                  contentPadding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
                  trailing: const Icon(Icons.arrow_forward_ios, size: 14, color: AppColors.textSecondary),
                  onTap: () => Navigator.pop(context, tienda),
                ),
              )),
            ],
          ),
        ),
        );
      }

      if (!mounted) return;
      if (tiendaSeleccionada != null) {
        final tiendaFinal = tiendaSeleccionada;
        // La tienda elegida AL INICIAR SESIÓN se convierte en la
        // tienda activa del usuario para esta sesión. Esto reemplaza
        // a la "tienda asignada" que antes se fijaba al crear el
        // usuario — ahora cada vez que inicia sesión, elige la
        // ubicación donde va a trabajar ese día.
        if (usuarioSesion != null) {
          usuarioSesion!.tienda = tiendaFinal;
        }
        Navigator.pushReplacement(
          context,
          MaterialPageRoute(builder: (c) => VentasPrincipal(tienda: tiendaFinal)),
        );
      }

    } catch (e) {
      debugPrint('[_login] Error: $e');
      if (!mounted) return;
      ScaffoldMessenger.of(context).hideCurrentSnackBar();

      final esTimeout    = e.toString().contains('TimeoutException');
      final esConexion   = e.toString().contains('SocketException') ||
                           e.toString().contains('ClientException') ||
                           e.toString().contains('Connection refused');
      final esCredencial = e.toString().toLowerCase().contains('credencial') ||
                           e.toString().contains('401') ||
                           e.toString().contains('403');

      // Mostramos el error EXACTO en pantalla para diagnosticar.
      // Antes mostrábamos "Error al iniciar sesión" genérico — eso
      // hacía imposible saber qué fallaba en producción.
      final mensaje = esTimeout
          ? "Tiempo de espera agotado. Verifique su conexión a la red."
          : esConexion
              ? "No se pudo conectar al servidor.\nDetalle: $e"
              : esCredencial
                  ? "Credenciales incorrectas. Verifique su usuario y contraseña."
                  : "Error: $e";

      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(mensaje),
        duration: const Duration(seconds: 12),
        backgroundColor: AppColors.statusRed,
        action: (esConexion || esTimeout)
            ? SnackBarAction(
                label: "Config.",
                textColor: Colors.white,
                onPressed: () => Navigator.push(context,
                  MaterialPageRoute(builder: (_) => const VentanaConfiguracion())),
              )
            : null,
      ));
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  /// Muestra un SnackBar de error con estilo uniforme.
  void _mostrarError(String mensaje, {Duration duracion = const Duration(seconds: 4)}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Row(children: [
        const Icon(Icons.error_outline, color: Colors.white, size: 18),
        const SizedBox(width: 8),
        Expanded(child: Text(mensaje)),
      ]),
      backgroundColor: AppColors.statusRed,
      duration: duracion,
      behavior: SnackBarBehavior.floating,
    ));
  }

