  }

  Widget _buildBotonAcceder() {
    return SizedBox(
      width: double.infinity, height: 56,
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 200),
        decoration: BoxDecoration(
          gradient: _cargando ? null : AppColors.gradientCTA,
          color: _cargando ? AppColors.brandYellow.withValues(alpha: 0.7) : null,
          borderRadius: BorderRadius.circular(14),
          boxShadow: _cargando ? [] : AppColors.shadowYellowGlow(),
        ),
        child: Material(
          color: Colors.transparent,
          child: InkWell(
            onTap: _cargando ? null : _login,
            borderRadius: BorderRadius.circular(14),
            child: Center(
              child: _cargando
                  ? const SizedBox(
                      width: 24, height: 24,
                      child: CircularProgressIndicator(
                        color: AppColors.brandBlueDeeper,
                        strokeWidth: 2.8,
                      ),
                    )
                  : Row(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: const [
                        Text('ACCEDER',
                          style: TextStyle(
                            color: AppColors.brandBlueDeeper,
                            fontSize: 15,
                            fontWeight: FontWeight.w900,
                            letterSpacing: 2.5,
                          ),
                        ),
                        SizedBox(width: 10),
                        Icon(
                          Icons.arrow_forward_rounded,
                          color: AppColors.brandBlueDeeper,
                          size: 22,
                        ),
                      ],
                    ),
            ),
          ),
        ),
      ),
    );
  }
}

// ════════════════════════════════════════════════════════════════════
//  PANTALLA DE BLOQUEO DE LICENCIA
// ════════════════════════════════════════════════════════════════════
//  Se muestra a TODOS los usuarios (excepto al UsuarioMaestro) cuando
//  la licencia está suspendida. Bloquea el acceso completo a la app
//  hasta que el proveedor desbloquee desde el Panel Maestro.
//
//  El usuario puede:
//   · Ver el motivo del bloqueo y el teléfono de contacto
//   · Llamar directamente al proveedor (botón Llamar)
//   · Reintentar (vuelve al login para que el maestro entre y desbloquee)
// ════════════════════════════════════════════════════════════════════
class PantallaBloqueoLicencia extends StatelessWidget {
  const PantallaBloqueoLicencia({super.key});

  @override
  Widget build(BuildContext context) {
    final estado = LicenciaService.estadoActual;

    return Scaffold(
      backgroundColor: AppColors.brandBlueDeeper,
      body: Stack(children: [
        // Fondo con gradiente azul Tecno Líder
        const DecoratedBox(
          decoration: BoxDecoration(gradient: AppColors.gradientHero),
          child: SizedBox.expand(),
        ),

        SafeArea(
          child: Center(
            child: SingleChildScrollView(
              padding: const EdgeInsets.all(28),
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 460),
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    // Icono grande de candado con resplandor amarillo
                    Container(
                      width: 110, height: 110,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        color: AppColors.brandYellow.withValues(alpha: 0.15),
                        border: Border.all(
                          color: AppColors.brandYellow.withValues(alpha: 0.4),
                          width: 2,
                        ),
                        boxShadow: [
                          BoxShadow(
                            color: AppColors.brandYellow.withValues(alpha: 0.3),
                            blurRadius: 28,
                          ),
                        ],
                      ),
                      child: const Icon(
                        Icons.lock_outline_rounded,
                        size: 56,
                        color: AppColors.brandYellow,
                      ),
                    ),
                    const SizedBox(height: 28),
                    // Título
                    const Text('SERVICIO SUSPENDIDO',
                      textAlign: TextAlign.center,
                      style: TextStyle(
                        color: Colors.white,
                        fontSize: 26,
                        fontWeight: FontWeight.w900,
                        letterSpacing: 2.5,
                      ),
                    ),
                    const SizedBox(height: 10),
                    // Línea decorativa amarilla
                    Container(
                      width: 60, height: 3,
                      decoration: BoxDecoration(
                        color: AppColors.brandYellow,
                        borderRadius: BorderRadius.circular(2),
                      ),
                    ),
                    const SizedBox(height: 24),
                    // Card con el motivo y contacto
                    Container(
                      padding: const EdgeInsets.all(24),
                      decoration: BoxDecoration(
                        color: Colors.white.withValues(alpha: 0.95),
                        borderRadius: BorderRadius.circular(20),
                        boxShadow: [
                          BoxShadow(
                            color: Colors.black.withValues(alpha: 0.4),
                            blurRadius: 30,
                            offset: const Offset(0, 14),
                          ),
                        ],
                      ),
                      child: Column(children: [
                        Text(
                          estado.motivo,
                          textAlign: TextAlign.center,
                          style: const TextStyle(
                            color: AppColors.textPrimary,
                            fontSize: 16,
                            fontWeight: FontWeight.w600,
                            height: 1.4,
                          ),
                        ),
                        const SizedBox(height: 16),
                        const Divider(),
                        const SizedBox(height: 12),
                        const Text(
                          'Para reactivar el servicio,\ncontacte al proveedor:',
                          textAlign: TextAlign.center,
                          style: TextStyle(
                            color: AppColors.textSecondary,
                            fontSize: 13,
                          ),
                        ),
                        const SizedBox(height: 12),
                        // Teléfono de contacto en grande
                        Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 18, vertical: 14),
                          decoration: BoxDecoration(
                            color: AppColors.brandBlue.withValues(alpha: 0.08),
                            borderRadius: BorderRadius.circular(12),
                            border: Border.all(
                              color: AppColors.brandBlue.withValues(alpha: 0.2),
                            ),
                          ),
                          child: Row(
                            mainAxisAlignment: MainAxisAlignment.center,
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              const Icon(Icons.phone_rounded,
                                color: AppColors.brandBlue, size: 22),
                              const SizedBox(width: 10),
                              Text(
                                estado.telefonoContacto,
                                style: const TextStyle(
                                  color: AppColors.brandBlue,
                                  fontSize: 18,
                                  fontWeight: FontWeight.w800,
                                  letterSpacing: 0.5,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ]),
                    ),
                    const SizedBox(height: 24),
                    // Botón "Llamar al proveedor"
                    SizedBox(
                      width: double.infinity, height: 52,
                      child: ElevatedButton.icon(
                        icon: const Icon(Icons.call_rounded, size: 22),
                        label: const Text('LLAMAR AL PROVEEDOR',
                          style: TextStyle(
                            fontSize: 14,
                            fontWeight: FontWeight.w900,
                            letterSpacing: 1.5,
