                          final tel = estado.telefonoContacto
                              .replaceAll(RegExp(r'[^0-9+]'), '');
                          if (tel.isEmpty) return;
                          final uri = Uri.parse('tel:$tel');
                          if (await canLaunchUrl(uri)) {
                            await launchUrl(uri);
                          }
                        },
