                // Ranking de rendimiento
                Builder(builder: (_) {
                  if (ventasGlobal.isEmpty) return const SizedBox.shrink();
                  final nombre = usuarioSesion?.nombre ?? '';
                  if (nombre.isEmpty) return const SizedBox.shrink();
                  final Map<String, double> porVendedor = {};
                  for (final f in ventasGlobal) {
                    porVendedor[f.vendedor] =
                        (porVendedor[f.vendedor] ?? 0) + f.total;
                  }
                  final sorted = porVendedor.entries.toList()
                    ..sort((a, b) => b.value.compareTo(a.value));
                  final idx = sorted.indexWhere((e) => e.key == nombre);
                  if (idx < 0) return const SizedBox.shrink();
                  final pos = idx + 1;
                  final medallas = ['🥇', '🥈', '🥉'];
                  final emoji = pos <= 3 ? medallas[pos - 1] : '🏅';
                  return Padding(
                    padding: const EdgeInsets.only(top: 12),
