      if (checkAccess(['Gerente','Administrador','Dueño']))
        _itemDrawer(Icons.leaderboard_outlined, "Estadísticas de Productos", () =>
          Navigator.push(context, MaterialPageRoute(builder: (c) => const VentanaEstadisticasProductos()))),
      // Listas de Precios: visible a TODOS los roles (incluido Vendedor).
      // La lógica interna (`esAdmin` en VentanaListasPrecios) ya restringe
      // edición/creación a Administrador. Vendedores ven en modo lectura.
      _itemDrawer(Icons.format_list_bulleted, "Listas de Precios", () =>
        Navigator.push(context, MaterialPageRoute(builder: (c) => const VentanaListasPrecios()))),
      // ── Consulta Rápida de Precios ─────────────────────────────
      // Buscador ultrarápido por nombre/modelo/marca. Muestra TODOS
      // los precios del producto en TODAS las listas a la vez (BCV,
      // divisas, financiadoras). Pensado para que el vendedor no
      // tenga que abrir cada lista individualmente.
      _itemDrawer(Icons.search, "Consulta Rápida de Precios", () =>
        Navigator.push(context, MaterialPageRoute(
            builder: (c) => const VentanaConsultaRapidaPrecios()))),
      if (checkAccess(['Administrador','Dueño']))
        _itemDrawer(Icons.bar_chart_outlined, "Comisiones", () =>
          Navigator.push(context, MaterialPageRoute(builder: (_) => const VentanaComisiones()))),
      if (checkAccess(['Gerente','Administrador','Encargado','Dueño']))
        _itemDrawer(Icons.point_of_sale_outlined, "Cierre de Caja", () =>
          Navigator.push(context, MaterialPageRoute(builder: (c) => const VentanaCierre()))),
      if (checkAccess(['Gerente','Administrador','Encargado','Dueño']))
        _itemDrawer(Icons.download_outlined, "Reportes", () =>
          Navigator.push(context, MaterialPageRoute(builder: (c) => const VentanaReportes()))),
      // ── Cotizaciones (Admin/Dueño/Gerente) ─────────────────────
      // Genera cotizaciones profesionales para clientes (PDF con logo,
      // productos, IVA opcional). Se guardan en BD y se pueden cobrar
      // vinculándolas a una factura desde el historial.
      if (checkAccess(['Administrador','Dueño','Gerente']))
        _itemDrawer(Icons.request_quote_outlined, "Cotizaciones", () =>
          Navigator.push(context, MaterialPageRoute(builder: (c) => const VentanaCotizacion()))),
      // ── Conectar Impresora: accesible para TODOS los roles,
      //    sin exponer el resto de la configuración del sistema ──
      _itemDrawer(Icons.print_outlined, "Conectar Impresora", () =>
        Navigator.push(context, MaterialPageRoute(builder: (c) => const VentanaConectarImpresora()))
        .then((_) => setState((){}))),
      if (checkAccess(['Administrador','Dueño'])) ...[
        const Divider(color: Colors.white24, thickness: 0.5, indent: 16, endIndent: 16),
        _itemDrawer(Icons.admin_panel_settings_outlined, "Panel Administrativo", () =>
          Navigator.push(context, MaterialPageRoute(builder: (c) => const VentanaPanelAdmin()))
          .then((_) => setState((){}))),
        _itemDrawer(Icons.settings_outlined, "Configuración", () =>
          Navigator.push(context, MaterialPageRoute(builder: (c) => const VentanaConfiguracion()))
          .then((_) => setState((){}))),
      ],
      // ── PANEL MAESTRO — visible SOLO al UsuarioMaestro (proveedor) ──
      // Le permite bloquear/desbloquear el sistema y ver el historial
      // de auditoría. Los usuarios normales (incluyendo Administrador
      // y Dueño) NO ven este botón.
      if (usuarioSesion?.rol == 'Maestro') ...[
        const Divider(
          color: AppColors.brandYellow,
          thickness: 1,
          indent: 16,
          endIndent: 16,
        ),
        _itemDrawer(Icons.workspace_premium_outlined, "Panel Maestro", () =>
          Navigator.push(context, MaterialPageRoute(builder: (c) => const VentanaPanelMaestro()))
          .then((_) => setState((){}))),
      ],
      const Divider(color: Colors.white24, thickness: 0.5, indent: 16, endIndent: 16),
      _itemDrawer(Icons.logout, "Cerrar Sesión", () async {
        final confirmar = await showDialog<bool>(
          context: context,
          builder: (ctx) => AlertDialog(
            title: const Row(children: [
              Icon(Icons.logout, color: AppColors.statusRed),
              SizedBox(width: 8),
              Text("Cerrar Sesión"),
            ]),
            content: Text("¿Está seguro que desea cerrar la sesión de ${usuarioSesion?.nombre ?? 'usuario'}?"),
            actions: [
              TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text("Cancelar")),
              ElevatedButton(
                style: ElevatedButton.styleFrom(backgroundColor: AppColors.statusRed),
                onPressed: () => Navigator.pop(ctx, true),
                child: const Text("Cerrar Sesión", style: TextStyle(color: Colors.white))),
            ],
          ),
        );
        if (confirmar != true || !context.mounted) return;
        NotificacionesService.detener();
        notificacionesGlobal.clear();
        MensajesLeidosService.limpiarCache();
        usuarioSesion = null;
        // Borrar sesión persistida — en la próxima apertura de la app
        // se volverá a mostrar el formulario de login.
        await SesionPersistente.borrar();
        if (!context.mounted) return;
        Navigator.pushAndRemoveUntil(context,
          MaterialPageRoute(builder: (context) => const LoginPage()),
          (route) => false);
      }, color: Colors.red[300]!),
      const SizedBox(height: 16),
        ], // children del ListView
      ), // ListView
    ), // Container con gradiente
  ); // Drawer

  Widget _itemDrawer(IconData icon, String title, VoidCallback onTap, {Color color = Colors.white}) {
    final esRojo = color != Colors.white;
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 1),
      child: Material(
        color: Colors.transparent,
        child: InkWell(
          onTap: () { Navigator.pop(context); onTap(); },
          borderRadius: BorderRadius.circular(12),
          // Hover/splash con tinte amarillo (acento de marca)
          hoverColor: AppColors.brandYellow.withValues(alpha: 0.1),
          splashColor: AppColors.brandYellow.withValues(alpha: 0.2),
          highlightColor: AppColors.brandYellow.withValues(alpha: 0.08),
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 10),
            child: Row(
              children: [
                // Icono dentro de un cuadradito redondeado con tinte
                Container(
                  width: 38, height: 38,
                  decoration: BoxDecoration(
                    color: esRojo
                        ? color.withValues(alpha: 0.18)
                        : AppColors.brandYellow.withValues(alpha: 0.12),
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(
                      color: esRojo
                          ? color.withValues(alpha: 0.3)
                          : AppColors.brandYellow.withValues(alpha: 0.25),
                      width: 1,
                    ),
                  ),
                  child: Icon(
                    icon,
                    color: esRojo ? color : AppColors.brandYellow,
                    size: 20,
                  ),
                ),
                const SizedBox(width: 14),
                // Título
                Expanded(
                  child: Text(
                    title,
                    style: TextStyle(
                      color: esRojo ? color : Colors.white,
                      fontWeight: FontWeight.w600,
                      fontSize: 14,
                      letterSpacing: 0.2,
                    ),
                  ),
                ),
                // Flecha sutil a la derecha
                Icon(
                  Icons.chevron_right_rounded,
                  color: Colors.white.withValues(alpha: 0.3),
                  size: 18,
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

// ============================================================
//  VENTANA DISPONIBLE
// ============================================================
class VentanaDisponible extends StatefulWidget {
  const VentanaDisponible({super.key});
  @override State<VentanaDisponible> createState() => _VentanaDisponibleState();
}

class _VentanaDisponibleState extends State<VentanaDisponible> {
  List<Producto> _productos = [];
  List<ImeiRegistro> _imeis = [];
  bool _cargando = true;
  String _query = '';
  String _filtroCategoria = 'Todos';

  /// Tienda activa para filtrar el stock. Para Dueño/Admin/Maestro
  /// puede ser '' (Todas); otros roles van forzados a su tienda.
  String _tiendaFiltro = '';
  bool get _puedeVerTodas {
    final r = usuarioSesion?.rol;
    // REGLA ESTRICTA: solo el DUEÑO ve el inventario de todas las tiendas.
    // Cualquier otro rol (Administrador, Gerente, Cajero, Vendedor,
    // Maestro, Encargado, etc.) queda restringido a su propia tienda.
    // Antes era permisivo para Admin/Gerente/Maestro también, pero el
    // dueño pidió que la separación de inventarios sea absoluta.
    return r == 'Dueño';
  }

  @override
  void initState() {
    super.initState();
    if (!_puedeVerTodas) {
      _tiendaFiltro = usuarioSesion?.tienda ?? '';
    }
    _cargar();
  }

  Future<void> _cargar() async {
    setState(() => _cargando = true);
    try {
      final results = await Future.wait([
        _Api.get('productos'),
        _Api.get('stock_imei'),
      ]);
      final rawP = results[0];
      final rawI = results[1];

      // PRIMERO productos (catalogoGlobal lo necesita ImeiRegistro.fromMap)
      _productos = ((rawP as List?) ?? [])
          .map((m) => Producto.fromMap(m))
          .toList();
      catalogoGlobal = _productos;

      // DESPUÉS IMEIs (ya con catalogoGlobal listo)
      _imeis = ((rawI as List?) ?? [])
          .map((m) => ImeiRegistro.fromMap(m))
          .toList();
      stockImeiGlobal = _imeis;

      // Calcular stockTotal por producto, filtrado por tienda activa
      for (final p in _productos) {
        if (CategoriasProductos.usaIMEI(p.categoria)) {
          p.stockTotal = _imeis.where((i) =>
              i.producto.codigo == p.codigo
              && !i.vendido
              && (_tiendaFiltro.isEmpty
                  || i.ubicacion == _tiendaFiltro)
          ).length;
        } else {
          p.stockTotal = p.stockManual;
        }
      }

      // Sumar el stock de los SUBPRODUCTOS al padre — el padre es lo
      // que se muestra; el stock debe reflejar el total agregado.
      final hijosPorPadre = <String, List<Producto>>{};
      for (final p in _productos) {
        if (p.productoPadreCodigo.isNotEmpty) {
          hijosPorPadre.putIfAbsent(p.productoPadreCodigo, () => [])
              .add(p);
        }
      }
      for (final padre in _productos.where((p) => p.productoPadreCodigo.isEmpty)) {
        final hijos = hijosPorPadre[padre.codigo] ?? const <Producto>[];
        for (final h in hijos) {
          padre.stockTotal += h.stockTotal;
        }
      }

      // Ordenar: más stock primero
      _productos.sort((a, b) => b.stockTotal.compareTo(a.stockTotal));
    } catch (e) {
      debugPrint('[VentanaDisponible._cargar] Error: $e');
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Error al cargar datos: $e'),
          backgroundColor: AppColors.statusRed,
          duration: const Duration(seconds: 4)));
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  List<Producto> get _productosFiltrados {
    return _productos.where((p) {
      // EXCLUIR subproductos — solo padres en el listado.
      if (p.productoPadreCodigo.isNotEmpty) return false;

      // ── FILTRO POR TIENDA ──────────────────────────────────
      // Esta pantalla mostraba los productos SIN IMEI (accesorios,
      // forros, cargadores...) de TODAS las tiendas a cualquier
      // usuario: para ellos se hacía `stockTotal = stockManual`, que
      // es un valor global, y acá no se filtraba nada. Un vendedor de
      // la sucursal veía como disponible el stock de la principal.
      //
      // Se aplica la misma regla que ya usa VentanaInventario:
      //  · CON IMEI  → cuenta los IMEIs físicamente en esa tienda.
      //  · SIN IMEI  → el producto pertenece a la tienda del campo
      //                `productos.tienda`; si está vacío es
      //                inventario general y se ve desde cualquiera.
      if (_tiendaFiltro.isNotEmpty &&
          !CategoriasProductos.usaIMEI(p.categoria)) {
        if (p.tienda.isNotEmpty && p.tienda != _tiendaFiltro) return false;
      }

      final matchQuery = _query.isEmpty ||
          p.nombre.toLowerCase().contains(_query.toLowerCase()) ||
          p.codigo.toLowerCase().contains(_query.toLowerCase()) ||
          p.marca.toLowerCase().contains(_query.toLowerCase());
      final matchCat = _filtroCategoria == 'Todos' || p.categoria == _filtroCategoria;
      return matchQuery && matchCat && p.stockTotal > 0;
    }).toList();
  }

  @override
  Widget build(BuildContext context) {
    final categorias = ['Todos', ...{ for (var p in _productos) p.categoria }];
    final filtrados = _productosFiltrados;
    final totalUnidades = filtrados.fold(0, (s, p) => s + p.stockTotal);

    return Scaffold(
      appBar: AppBar(
        title: const Text("Stock Disponible"),
        actions: [IconButton(icon: const Icon(Icons.refresh), tooltip: "Actualizar", onPressed: _cargar)],
      ),
      body: Column(children: [
        // Barra de búsqueda y filtros
        Container(
          color: Colors.white,
          padding: const EdgeInsets.fromLTRB(12, 8, 12, 0),
          child: Column(children: [
            TextField(
              decoration: InputDecoration(
                hintText: "Buscar producto, código o marca...",
                prefixIcon: const Icon(Icons.search, color: AppColors.primaryBlue),
                suffixIcon: _query.isNotEmpty
                  ? IconButton(icon: const Icon(Icons.clear, size: 18), onPressed: () => setState(() => _query = ''))
                  : null,
                filled: true, fillColor: AppColors.surfaceGrey,
                border: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: BorderSide.none),
                contentPadding: const EdgeInsets.symmetric(vertical: 0, horizontal: 16),
              ),
              onChanged: (v) => setState(() => _query = v),
            ),
            const SizedBox(height: 8),
            SizedBox(height: 34, child: ListView(scrollDirection: Axis.horizontal, children: [
              ...categorias.map((cat) => Padding(
                padding: const EdgeInsets.only(right: 8),
                child: FilterChip(
                  label: Text(cat, style: const TextStyle(fontSize: 12)),
                  selected: _filtroCategoria == cat,
                  onSelected: (_) => setState(() => _filtroCategoria = cat),
                  selectedColor: AppColors.primaryBlue.withValues(alpha: 0.15),
                  checkmarkColor: AppColors.primaryBlue,
                ),
              )),
            ])),
            const SizedBox(height: 8),
          ]),
        ),
        // Resumen
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
          color: AppColors.surfaceGrey,
          child: Row(children: [
            Text("${filtrados.length} productos · $totalUnidades unidades",
              style: const TextStyle(color: AppColors.textSecondary, fontSize: 13)),
          ]),
        ),
        if (_cargando)
          const Expanded(child: Center(child: CircularProgressIndicator()))
        else if (filtrados.isEmpty)
          const Expanded(child: EmptyState(mensaje: "No hay productos disponibles.", icono: Icons.inventory_2_outlined))
        else
          Expanded(child: RefreshIndicator(
            onRefresh: _cargar,
            child: ListView.builder(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
              itemCount: filtrados.length,
              itemBuilder: (context, index) {
                final p = filtrados[index];
                final stockColor = p.stockTotal >= 5 ? AppColors.statusGreen
                    : p.stockTotal >= 2 ? AppColors.statusOrange
                    : AppColors.statusRed;
                return Card(
                  margin: const EdgeInsets.only(bottom: 8),
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                  elevation: 1,
                  child: ListTile(
                    contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
                    leading: Container(
                      width: 44, height: 44,
                      decoration: BoxDecoration(
                        color: stockColor.withValues(alpha: 0.1),
                        borderRadius: BorderRadius.circular(10),
                      ),
                      child: Center(child: Text("${p.stockTotal}",
                        style: TextStyle(fontWeight: FontWeight.bold, fontSize: 18, color: stockColor))),
                    ),
                    title: Text("${p.nombre}",
                      style: const TextStyle(fontWeight: FontWeight.w600, color: AppColors.textPrimary)),
                    subtitle: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Text("${p.codigo} · ${p.marca}", style: const TextStyle(fontSize: 12, color: AppColors.textSecondary)),
                      if (p.categoria == "iPhone" && p.porcentajeBateria != null)
                        Row(children: [
                          const Icon(Icons.battery_charging_full, size: 13, color: AppColors.statusGreen),
                          const SizedBox(width: 2),
                          Text("Batería: ${p.porcentajeBateria}%",
                            style: const TextStyle(fontSize: 11, color: AppColors.statusGreen)),
                        ]),
                    ]),
                    trailing: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
                      Text(formatCurrency(p.precioVenta),
                        style: const TextStyle(fontWeight: FontWeight.bold, color: AppColors.primaryBlue)),
                      const Icon(Icons.chevron_right, size: 16, color: AppColors.textSecondary),
                    ]),
                    onTap: () => _mostrarUbicaciones(p),
                  ),
                );
              },
            ),
          )),
      ]),
    );
  }

  void _mostrarUbicaciones(Producto p) {
    final imeis = _imeis.where((i) => i.producto.codigo == p.codigo && !i.vendido).toList();
    Map<String,List<ImeiRegistro>> porUbicacion = {};
    for (var i in imeis) {
      porUbicacion.putIfAbsent(i.ubicacion, () => []).add(i);
    }
    showModalBottomSheet(
      context: context,
      shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(20))),
      builder: (c) => Padding(
        padding: const EdgeInsets.all(24),
        child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text(p.nombre, style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
          Text("${p.codigo} · ${imeis.length} unidades", style: const TextStyle(color: AppColors.textSecondary)),
          const Divider(height: 24),
          ...porUbicacion.entries.map((e) => ListTile(
            contentPadding: EdgeInsets.zero,
            leading: const Icon(Icons.location_on_outlined, color: AppColors.primaryBlue),
            title: Text(e.key, style: const TextStyle(fontWeight: FontWeight.w600)),
            trailing: Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
              decoration: BoxDecoration(color: AppColors.primaryBlue.withValues(alpha: 0.1), borderRadius: BorderRadius.circular(12)),
              child: Text("${e.value.length} uds", style: const TextStyle(color: AppColors.primaryBlue, fontWeight: FontWeight.bold)),
            ),
          )),
          const SizedBox(height: 8),
        ]),
      ),
    );
  }
}

// ============================================================
//  VENTANA LÍNEAS — carga desde la API
// ============================================================
// ─── Eliminadas: clases (líneas 11190-13123 originales) ─── eliminado en rediseño v2.1
class _LineaItem extends StatefulWidget {
  final LineaModel linea;
  final Color estadoColor;
  final String estadoLabel;
  final String queryResaltado;
  final Future<void> Function(LineaModel) onGuardar;
  const _LineaItem({
    super.key,
    required this.linea,
    required this.estadoColor,
    required this.estadoLabel,
    this.queryResaltado = '',
    required this.onGuardar,
  });
  @override State<_LineaItem> createState() => _LineaItemState();
}

class _LineaItemState extends State<_LineaItem> {
  // Controllers exclusivos de esta fila — nunca se comparten con otras
  late final TextEditingController _ctrlAsignado;
  late final TextEditingController _ctrlEsim;
  bool _guardando = false;

  @override
  void initState() {
    super.initState();
    _ctrlAsignado = TextEditingController(text: widget.linea.asignado);
    _ctrlEsim     = TextEditingController(text: widget.linea.esim);
  }

  @override
  void dispose() {
    _ctrlAsignado.dispose();
    _ctrlEsim.dispose();
    super.dispose();
  }

  LineaModel get l => widget.linea;

  @override
  Widget build(BuildContext context) {
    return Card(
      margin: const EdgeInsets.only(bottom: 8),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
      elevation: 1,
      clipBehavior: Clip.antiAlias,
      child: ExpansionTile(
        leading: CircleAvatar(
          backgroundColor: widget.estadoColor.withValues(alpha: 0.12),
          child: Icon(
            l.activada ? Icons.check_circle_outline : Icons.pending_outlined,
            color: widget.estadoColor, size: 22),
        ),
        title: _resaltar(l.nombre,
          const TextStyle(fontWeight: FontWeight.w600)),
        subtitle: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
              decoration: BoxDecoration(
                color: widget.estadoColor.withValues(alpha: 0.1),
                borderRadius: BorderRadius.circular(10)),
              child: Text(widget.estadoLabel,
                style: TextStyle(fontSize: 11, color: widget.estadoColor,
                  fontWeight: FontWeight.w600)),
            ),
            const SizedBox(width: 6),
            Flexible(child: _resaltar("${l.tipo} · ${l.vendedor}",
              const TextStyle(fontSize: 11, color: AppColors.textSecondary))),
          ]),
          // Muestra nro/eSIM asignados si ya existen (visible sin expandir)
          if (l.asignado.isNotEmpty || l.esim.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 3),
              child: Wrap(spacing: 10, children: [
                if (l.asignado.isNotEmpty)
                  Row(mainAxisSize: MainAxisSize.min, children: [
                    const Icon(Icons.call, size: 12, color: AppColors.statusGreen),
                    const SizedBox(width: 3),
                    Text(l.asignado, style: const TextStyle(fontSize: 11,
                      color: AppColors.statusGreen, fontWeight: FontWeight.w600)),
                  ]),
                if (l.esim.isNotEmpty)
                  Row(mainAxisSize: MainAxisSize.min, children: [
                    const Icon(Icons.contactless, size: 12,
                      color: AppColors.primaryBlue),
                    const SizedBox(width: 3),
                    Text("eSIM: ${l.esim}", style: const TextStyle(fontSize: 11,
                      color: AppColors.primaryBlue, fontWeight: FontWeight.w600)),
                  ]),
              ]),
            ),
        ]),
        trailing: l.recargada
            ? const Icon(Icons.bolt, color: AppColors.statusYellow)
            : null,
        children: [
          Container(
            padding: const EdgeInsets.all(16),
            color: AppColors.surfaceGrey,
            child: Column(children: [
              // Info de la línea
              Wrap(spacing: 16, runSpacing: 8, children: [
                _ir(Icons.badge_outlined,      "C.I.",    l.cedula),
                _ir(Icons.phone_outlined,      "Tel.",    l.telefono),
                _ir(Icons.email_outlined,      "Correo",  l.correo),
                _ir(Icons.smartphone_outlined, "Modelo",  l.modelo),
                _ir(Icons.pin_outlined,        "IMEI 1",  l.imei1),
                if (l.imei2.isNotEmpty)
                  _ir(Icons.pin_outlined,      "IMEI 2",  l.imei2),
                _ir(Icons.signal_cellular_alt, "Plan",    l.plan),
                _ir(Icons.sim_card_outlined,   "Chip",    l.chip),
              ]),
              const SizedBox(height: 12),

              // Campos editables exclusivos de esta fila.
              // El campo "eSIM Asignada" solo se muestra cuando el tipo de
              // línea está relacionado con eSIM (Esim Nueva, eSim a eSIM,
              // Sim a eSIM, eSIM a Sim).
              // ── El Vendedor NO puede editar Nro Asignado ni eSIM Asignada.
              Builder(builder: (_) {
                final mostrarEsim =
                    l.tipo.toLowerCase().contains('esim');
                final esVendedor = usuarioSesion?.rol == 'Vendedor';
                return Row(children: [
                  Expanded(child: TextField(
                    controller: _ctrlAsignado,   // ← propio de esta fila
                    readOnly: esVendedor,
                    enableInteractiveSelection: true,
                    decoration: InputDecoration(
                      labelText: 'Nro Asignado',
                      prefixIcon: const Icon(Icons.call, size: 18),
                      isDense: true,
                      filled: esVendedor,
                      fillColor: esVendedor ? Colors.grey.shade100 : null,
                      helperText: esVendedor ? 'Solo lectura para vendedores' : null,
                      helperStyle: const TextStyle(fontSize: 10, color: Colors.grey),
                    ),
                    keyboardType: TextInputType.phone,
                    onChanged: esVendedor ? null : (v) => l.asignado = v,
                  )),
                  if (mostrarEsim) ...[
                    const SizedBox(width: 12),
                    Expanded(child: TextField(
                      controller: _ctrlEsim,       // ← propio de esta fila
                      readOnly: esVendedor,
                      enableInteractiveSelection: true,
                      decoration: InputDecoration(
                        labelText: 'eSIM Asignada',
                        prefixIcon: const Icon(Icons.contactless, size: 18),
                        isDense: true,
                        filled: esVendedor,
                        fillColor: esVendedor ? Colors.grey.shade100 : null,
                        helperText: esVendedor ? 'Solo lectura para vendedores' : null,
                        helperStyle: const TextStyle(fontSize: 10, color: Colors.grey),
                      ),
                      keyboardType: TextInputType.number,
                      onChanged: esVendedor ? null : (v) => l.esim = v,
                    )),
                  ],
                ]);
              }),

              // Campo código de activación (solo cuando se solicita)
              if (l.solicitandoCodigo) ...[
                const SizedBox(height: 12),
                Container(
                  padding: const EdgeInsets.all(12),
                  decoration: BoxDecoration(
                    color: AppColors.statusOrange.withValues(alpha: 0.08),
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(
                      color: AppColors.statusOrange.withValues(alpha: 0.4))),
                  child: Column(crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                    const Row(children: [
                      Icon(Icons.key, size: 16, color: AppColors.statusOrange),
                      SizedBox(width: 6),
                      Text("Código de activación solicitado",
                        style: TextStyle(fontWeight: FontWeight.w600,
                          color: AppColors.statusOrange, fontSize: 13)),
                    ]),
                    const SizedBox(height: 8),
                    TextField(
                      decoration: InputDecoration(
                        labelText: 'Ingresar código aquí',
                        hintText: 'Escribe el código...',
                        prefixIcon: const Icon(Icons.dialpad, size: 18,
                          color: AppColors.statusOrange),
                        filled: true, fillColor: Colors.white,
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(8)),
                        focusedBorder: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(8),
                          borderSide: const BorderSide(
                            color: AppColors.statusOrange, width: 2)), isDense: true),
                      style: const TextStyle(fontWeight: FontWeight.bold,
                        fontSize: 15, letterSpacing: 1.5),
                      onChanged: (v) =>
                        l.codigoSolicitado = v.isEmpty ? null : v,
                    ),
                  ]),
                ),
              ],

              // Código ya enviado
              if (!l.solicitandoCodigo &&
                  l.codigoSolicitado != null &&
                  l.codigoSolicitado!.isNotEmpty) ...[
                const SizedBox(height: 8),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12, vertical: 8),
                  decoration: BoxDecoration(
                    color: AppColors.statusGreen.withValues(alpha: 0.08),
                    borderRadius: BorderRadius.circular(8),
                    border: Border.all(
                      color: AppColors.statusGreen.withValues(alpha: 0.3))),
                  child: Row(children: [
                    const Icon(Icons.check_circle_outline,
                      size: 16, color: AppColors.statusGreen),
                    const SizedBox(width: 6),
                    Text("Código: ${l.codigoSolicitado}",
                      style: const TextStyle(fontWeight: FontWeight.bold,
                        color: AppColors.statusGreen, fontSize: 13,
                        letterSpacing: 1)),
                  ]),
                ),
              ],

              const SizedBox(height: 14),
              // Único botón: GUARDAR
              SizedBox(
                width: double.infinity,
                child: ElevatedButton.icon(
                  style: ElevatedButton.styleFrom(
                    backgroundColor: AppColors.royalBlue,
                    padding: const EdgeInsets.symmetric(vertical: 12),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(10))),
                  icon: _guardando
                    ? const SizedBox(width: 18, height: 18,
                        child: CircularProgressIndicator(
                          strokeWidth: 2, color: Colors.white))
                    : const Icon(Icons.save_outlined, size: 18),
                  label: Text(_guardando ? "Guardando..." : "Guardar",
                    style: const TextStyle(
                      fontWeight: FontWeight.bold, fontSize: 15)),
                  onPressed: _guardando ? null : () async {
                    setState(() => _guardando = true);
                    await widget.onGuardar(l);
                    if (mounted) setState(() => _guardando = false);
                  },
                ),
              ),
            ]),
          ),
        ],
      ),
    );
  }

  Widget _ir(IconData icon, String label, String value) =>
    value.isEmpty ? const SizedBox() :
    Row(mainAxisSize: MainAxisSize.min, children: [
      Icon(icon, size: 14, color: AppColors.textSecondary),
      const SizedBox(width: 4),
      Text("$label: ", style: const TextStyle(
        fontSize: 12, color: AppColors.textSecondary)),
      _resaltar(value, const TextStyle(fontSize: 12, fontWeight: FontWeight.w500)),
    ]);

  /// Resalta en amarillo las coincidencias del query dentro del texto.
  Widget _resaltar(String texto, TextStyle estilo) {
    final q = widget.queryResaltado.toLowerCase().trim();
    if (q.isEmpty) return Text(texto, style: estilo);
    final lower = texto.toLowerCase();
    final idx = lower.indexOf(q);
    if (idx == -1) return Text(texto, style: estilo);
    return RichText(
      text: TextSpan(style: estilo, children: <InlineSpan>[
        if (idx > 0) TextSpan(text: texto.substring(0, idx)),
        TextSpan(
          text: texto.substring(idx, idx + q.length),
          style: estilo.copyWith(
            backgroundColor: Colors.yellow.shade300,
            fontWeight: FontWeight.bold,
            color: Colors.black87)),
        if (idx + q.length < texto.length)
          TextSpan(text: texto.substring(idx + q.length)),
      ]),
    );
  }
}

// ============================================================
//  VENTANA ACTIVACIÓN
// ============================================================
// ─── Eliminadas: clases (líneas 13422-14478 originales) ─── eliminado en rediseño v2.1
class VentanaServicioTecnico extends StatefulWidget {
  const VentanaServicioTecnico({super.key});
  @override State<VentanaServicioTecnico> createState() => _VentanaServicioTecnicoState();
}

class _VentanaServicioTecnicoState extends State<VentanaServicioTecnico> {
  List<ServicioTecnico> _servicios = [];
  bool _cargando = true;
  String? _error;
  String _query = '';

  @override
  void initState() { super.initState(); _cargar(); }

  Future<void> _cargar() async {
    setState(() { _cargando = true; _error = null; });
    try {
      final raw = await _Api.get('servicios');
      _servicios = ((raw as List?) ?? []).map((m) => ServicioTecnico.fromMap(m)).toList();
      _servicios.sort((a, b) => b.fecha.compareTo(a.fecha));
      serviciosGlobal = _servicios;
    } catch (e) {
      debugPrint('[Servicios._cargar] Error: $e');
      _error = e.toString();
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Error al cargar datos: $e'),
          backgroundColor: AppColors.statusRed,
          duration: const Duration(seconds: 4)));
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  List<ServicioTecnico> get _filtrados {
    if (_query.trim().isEmpty) return _servicios;
    final q = _query.toLowerCase();
    return _servicios.where((s) =>
      s.nombreCliente.toLowerCase().contains(q) ||
      s.telefono.toLowerCase().contains(q) ||
      s.rifCi.toLowerCase().contains(q) ||
      s.marca.toLowerCase().contains(q) ||
      s.modelo.toLowerCase().contains(q) ||
      s.imei.toLowerCase().contains(q) ||
      s.descripcion.toLowerCase().contains(q)
    ).toList();
  }

  @override
  Widget build(BuildContext context) {
    final servicios = _filtrados;
    double total = servicios.fold(0, (sum, item) => sum + item.monto);
    double totalAbonos = servicios.fold(0, (sum, item) => sum + item.abono);
    double totalPendiente = servicios.fold(0, (sum, item) => sum + item.resta);
    double totalCostos = servicios.fold(0, (sum, item) => sum + item.costoRepuestos);
    double totalGanancia = total - totalCostos;

    return Scaffold(
      appBar: AppBar(
        title: const Text("Servicio Técnico"),
        actions: [
          IconButton(
            icon: const Icon(Icons.assessment_outlined),
            tooltip: "Reporte de rentabilidad",
            onPressed: () => Navigator.push(context, MaterialPageRoute(
              builder: (_) => VentanaReporteRentabilidadServicios(servicios: _servicios))),
          ),
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: "Actualizar",
            onPressed: _cargar),
        ],
      ),
      body: Column(children: [
        // ── Banner resumen con KPIs (cobrado / costos / ganancia) ──
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 14),
          decoration: const BoxDecoration(
            gradient: LinearGradient(
              colors: [AppColors.brandBlue, AppColors.brandBlueDark],
              begin: Alignment.topLeft, end: Alignment.bottomRight,
            ),
          ),
          width: double.infinity,
          child: Column(
            children: [
              // Fila 1: Cobrado / Abonado / Pendiente
              Row(mainAxisAlignment: MainAxisAlignment.spaceAround, children: [
                _kpi("Cobrado", formatCurrency(total), Colors.white),
                Container(width: 1, height: 34, color: Colors.white24),
                _kpi("Abonado", formatCurrency(totalAbonos), AppColors.brandYellow),
                Container(width: 1, height: 34, color: Colors.white24),
                _kpi("Pendiente", formatCurrency(totalPendiente), Colors.white70),
                Container(width: 1, height: 34, color: Colors.white24),
                _kpi("Servicios", "${servicios.length}", Colors.white),
              ]),
              const SizedBox(height: 10),
              const Divider(color: Colors.white12, height: 1),
              const SizedBox(height: 10),
              // Fila 2: Cobrado / Costos / Ganancia
              Row(mainAxisAlignment: MainAxisAlignment.spaceAround, children: [
                _kpi("Costo Repuestos", formatCurrency(totalCostos), Colors.orangeAccent),
                Container(width: 1, height: 34, color: Colors.white24),
                _kpi("Ganancia",
                    formatCurrency(totalGanancia),
                    totalGanancia >= 0 ? AppColors.brandYellow : Colors.redAccent),
                Container(width: 1, height: 34, color: Colors.white24),
                _kpi("Margen",
                    total > 0 ? "${(totalGanancia / total * 100).toStringAsFixed(1)}%" : "0%",
                    totalGanancia >= 0 ? Colors.greenAccent : Colors.redAccent),
              ]),
            ],
          ),
        ),

        // ── Buscador ──
        Container(
          color: Colors.white,
          padding: const EdgeInsets.fromLTRB(12, 10, 12, 10),
          child: TextField(
            decoration: InputDecoration(
              hintText: "Buscar por cliente, teléfono, IMEI, marca...",
              prefixIcon: const Icon(Icons.search, color: AppColors.primaryBlue),
              suffixIcon: _query.isNotEmpty
                ? IconButton(
                    icon: const Icon(Icons.clear, size: 18),
                    onPressed: () => setState(() => _query = ''))
                : null,
              filled: true, fillColor: AppColors.surfaceGrey,
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(12),
                borderSide: BorderSide.none),
              contentPadding: const EdgeInsets.symmetric(vertical: 0, horizontal: 16),
            ),
            onChanged: (v) => setState(() => _query = v),
          ),
        ),

        // ── Lista ──
        if (_cargando)
          const Expanded(child: Center(child: CircularProgressIndicator()))
        else if (_error != null)
          Expanded(child: ErrorCard(mensaje: _error!, onReintentar: _cargar))
        else if (servicios.isEmpty)
          const Expanded(child: EmptyState(
            mensaje: "No hay servicios registrados.\nPresione + para agregar uno.",
            icono: Icons.build_outlined))
        else
          Expanded(child: RefreshIndicator(
            onRefresh: _cargar,
            child: ListView.builder(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
              itemCount: servicios.length,
              itemBuilder: (c, i) => _buildCardServicio(servicios[i]),
            ),
          )),
      ]),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: _mostrarFormularioNuevo,
        icon: const Icon(Icons.add, color: Colors.white),
        label: const Text("Nuevo", style: TextStyle(color: Colors.white)),
      ),
    );
  }

  Widget _kpi(String label, String value, Color color) => Column(children: [
    Text(label, style: const TextStyle(color: Colors.white70, fontSize: 10)),
    Text(value, style: TextStyle(color: color, fontSize: 15, fontWeight: FontWeight.bold)),
  ]);

  Widget _buildCardServicio(ServicioTecnico s) {
    final estadoColor = {
      'Recibido': AppColors.statusOrange,
      'En reparación': AppColors.primaryBlue,
      'Listo': AppColors.statusGreen,
      'Entregado': Colors.grey,
    }[s.estado] ?? AppColors.statusOrange;

    return Card(
      margin: const EdgeInsets.only(bottom: 8),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
      elevation: 1,
      child: InkWell(
        borderRadius: BorderRadius.circular(12),
        onTap: () => _abrirDetalle(s),
        child: Padding(
          padding: const EdgeInsets.all(12),
          child: Row(children: [
            // ── Icono categoría ──
            Container(
              width: 46, height: 46,
              decoration: BoxDecoration(
                color: AppColors.royalBlue.withValues(alpha: 0.1),
                borderRadius: BorderRadius.circular(10)),
              child: const Icon(Icons.build_outlined,
                color: AppColors.royalBlue, size: 24),
            ),
            const SizedBox(width: 12),

            // ── Info ──
            Expanded(child: Column(
              crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                Expanded(child: Text(
                  s.nombreCliente.isNotEmpty ? s.nombreCliente : '(sin nombre)',
                  style: const TextStyle(fontWeight: FontWeight.w600, fontSize: 14),
                  overflow: TextOverflow.ellipsis)),
                // Badge estado
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
                  decoration: BoxDecoration(
                    color: estadoColor.withValues(alpha: 0.15),
                    borderRadius: BorderRadius.circular(10)),
                  child: Text(s.estado,
                    style: TextStyle(fontSize: 10, fontWeight: FontWeight.bold,
                      color: estadoColor)),
                ),
              ]),
              const SizedBox(height: 3),
              Text(
                [if (s.marca.isNotEmpty) s.marca,
                 if (s.modelo.isNotEmpty) s.modelo,
                 if (s.imei.isNotEmpty) "IMEI ${s.imei}"].join(' · '),
                style: const TextStyle(fontSize: 12, color: AppColors.textSecondary),
                maxLines: 1, overflow: TextOverflow.ellipsis),
              if (s.descripcion.isNotEmpty) ...[
                const SizedBox(height: 2),
                Text(s.descripcion,
                  style: const TextStyle(fontSize: 11, color: AppColors.textSecondary),
                  maxLines: 1, overflow: TextOverflow.ellipsis),
              ],
              const SizedBox(height: 4),
              Row(children: [
                Text(formatCurrency(s.monto),
                  style: const TextStyle(fontWeight: FontWeight.bold,
                    color: AppColors.primaryBlue, fontSize: 13)),
                if (s.resta > 0) ...[
                  const SizedBox(width: 8),
                  Text("Resta: ${formatCurrency(s.resta)}",
                    style: const TextStyle(fontSize: 11, color: AppColors.statusRed)),
                ],
                if (s.pagado) ...[
                  const SizedBox(width: 8),
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 1),
                    decoration: BoxDecoration(
                      color: AppColors.statusGreen.withValues(alpha: 0.15),
                      borderRadius: BorderRadius.circular(6)),
                    child: const Text("PAGADO",
                      style: TextStyle(fontSize: 9, fontWeight: FontWeight.bold,
                        color: AppColors.statusGreen)),
                  ),
                ],
                const Spacer(),
                Text(_formatoFecha(s.fecha),
                  style: const TextStyle(fontSize: 10, color: AppColors.textSecondary)),
              ]),
            ])),
          ]),
        ),
      ),
    );
  }

  String _formatoFecha(DateTime f) =>
    "${f.day.toString().padLeft(2,'0')}/${f.month.toString().padLeft(2,'0')}/${f.year}";

  // ── Navegar a vista de detalle ───────────────────────────
  Future<void> _abrirDetalle(ServicioTecnico s) async {
    await Navigator.push(context, MaterialPageRoute(
      builder: (_) => _DetalleServicioTecnico(servicio: s)));
    if (mounted) _cargar();
  }

  // ── Eliminar servicio ────────────────────────────────────
  Future<void> _eliminarServicio(ServicioTecnico s) async {
    final confirmar = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Row(children: [
          Icon(Icons.delete_outline, color: AppColors.statusRed),
          SizedBox(width: 8),
          Text("Eliminar Servicio"),
        ]),
        content: Text("¿Eliminar el servicio de '${s.nombreCliente}'? Esta acción no se puede deshacer."),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text("Cancelar")),
          ElevatedButton.icon(
            style: ElevatedButton.styleFrom(backgroundColor: AppColors.statusRed),
            icon: const Icon(Icons.delete_forever_outlined, size: 16, color: Colors.white),
            label: const Text("Eliminar", style: TextStyle(color: Colors.white)),
            onPressed: () => Navigator.pop(ctx, true)),
        ],
      ),
    );
    if (confirmar != true || !mounted) return;
    try {
      if (s.id == null) throw Exception('Servicio sin ID. Recargue la pantalla.');
      await _Api.delete('servicios', s.id!.toString());
      setState(() => _servicios.removeWhere((x) => x.id == s.id));
      serviciosGlobal.removeWhere((x) => x.id == s.id);
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text("Servicio eliminado correctamente."),
        backgroundColor: AppColors.statusGreen));
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text("Error al eliminar: $e"),
        backgroundColor: AppColors.statusRed));
    }
  }

  // ── Abrir formulario para crear nuevo servicio ───────────
  Future<void> _mostrarFormularioNuevo() async {
    await Navigator.push(context, MaterialPageRoute(
      builder: (_) => const _FormularioServicioTecnico()));
    if (mounted) _cargar();
  }
}

// ============================================================
//  FORMULARIO DE SERVICIO TÉCNICO  (crear / editar)
//  Replica la planilla física: datos del cliente, equipo,
//  checklist de componentes, observaciones y montos.
// ============================================================
class _FormularioServicioTecnico extends StatefulWidget {
  final ServicioTecnico? servicio;   // null = nuevo
  const _FormularioServicioTecnico({this.servicio});

  @override
  State<_FormularioServicioTecnico> createState() => _FormularioServicioTecnicoState();
}

class _FormularioServicioTecnicoState extends State<_FormularioServicioTecnico> {
  final _formKey = GlobalKey<FormState>();

  // Controladores
  late TextEditingController _montoCtrl, _abonoCtrl, _costoRepuestosCtrl;
  late TextEditingController _nombreCtrl, _telefonoCtrl, _rifCtrl;
  late TextEditingController _modeloCtrl, _marcaCtrl, _descripcionCtrl;
  late TextEditingController _imeiCtrl, _contrasenaCtrl;
  late TextEditingController _observacionCtrl, _tecnicoCtrl;
  late TextEditingController _horaRecibidoCtrl, _fechaEntregaCtrl;

  // Checklist — cada uno puede ser true/false/null (no revisado)
  bool? chip, memoria, bateria, tapa;
  bool? encendido, apagado, camara, corneta;
  bool? flash, flashConDefecto;
  bool? tactilPartido, auricular, microfono, contrasenaChk;
  bool? track, botonVolumen, teclado, botonEncendido, pantallaConDefecto;

  bool _pagado = false;
  String _estado = 'Recibido';
  late DateTime _fecha;
  bool _guardando = false;
  /// Fotos del equipo al recibirlo (base64). Vacío por defecto.
  List<String> _fotosRecepcion = [];

  final List<String> _estados = ['Recibido', 'En reparación', 'Listo', 'Entregado'];

  @override
  void initState() {
    super.initState();
    final s = widget.servicio;
    _fecha = s?.fecha ?? DateTime.now();

    // Helper local: formatea un monto para un TextField sin mostrar ".0"
    // innecesario (150.0 → "150", 150.5 → "150.5"). Si es 0 o null,
    // devuelve cadena vacía para que el hint del campo sea visible.
    String _numToField(double? v) {
      if (v == null || v == 0) return '';
      // Si es entero (ej: 150.0) → "150". Si no, como está (ej: 150.5 → "150.5").
      return v == v.roundToDouble() ? v.toInt().toString() : v.toString();
    }

    _montoCtrl         = TextEditingController(text: _numToField(s?.monto));
    _abonoCtrl         = TextEditingController(text: _numToField(s?.abono));
    _costoRepuestosCtrl = TextEditingController(text: _numToField(s?.costoRepuestos));
    _nombreCtrl        = TextEditingController(text: s?.nombreCliente ?? '');
    _telefonoCtrl      = TextEditingController(text: s?.telefono ?? '');
    _rifCtrl           = TextEditingController(text: s?.rifCi ?? '');
    _modeloCtrl        = TextEditingController(text: s?.modelo ?? '');
    _marcaCtrl         = TextEditingController(text: s?.marca ?? '');
    _descripcionCtrl   = TextEditingController(text: s?.descripcion ?? '');
    _imeiCtrl          = TextEditingController(text: s?.imei ?? '');
    _contrasenaCtrl    = TextEditingController(text: s?.contrasena ?? '');
    _observacionCtrl   = TextEditingController(text: s?.observacion ?? '');
    _tecnicoCtrl       = TextEditingController(text: s?.tecnico ?? (usuarioSesion?.nombre ?? ''));
    _horaRecibidoCtrl  = TextEditingController(text: s?.horaRecibido ?? _horaActual());
    _fechaEntregaCtrl  = TextEditingController(text: s?.fechaEntrega ?? '');

    chip                = s?.chip;
    memoria             = s?.memoria;
    bateria             = s?.bateria;
    tapa                = s?.tapa;
    encendido           = s?.encendido;
    apagado             = s?.apagado;
    camara              = s?.camara;
    corneta             = s?.corneta;
    flash               = s?.flash;
    flashConDefecto     = s?.flashConDefecto;
    tactilPartido       = s?.tactilPartido;
    auricular           = s?.auricular;
    microfono           = s?.microfono;
    contrasenaChk       = s?.contrasenaChk;
    track               = s?.track;
    botonVolumen        = s?.botonVolumen;
    teclado             = s?.teclado;
    botonEncendido      = s?.botonEncendido;
    pantallaConDefecto  = s?.pantallaConDefecto;
    _pagado             = s?.pagado ?? false;
    // Si el backend devuelve un estado desconocido (datos antiguos, case
    // distinto, etc.), el Dropdown explotaría porque `value` no estaría
    // en `items`. Caemos a 'Recibido' por defecto para evitarlo.
    final estadoCargado = s?.estado ?? 'Recibido';
    _estado = _estados.contains(estadoCargado) ? estadoCargado : 'Recibido';
    // Cargar fotos existentes (al editar) o lista vacía
    _fotosRecepcion = List<String>.from(s?.fotosRecepcion ?? const <String>[]);
  }

  @override
  void dispose() {
    _montoCtrl.dispose(); _abonoCtrl.dispose(); _costoRepuestosCtrl.dispose();
    _nombreCtrl.dispose(); _telefonoCtrl.dispose(); _rifCtrl.dispose();
    _modeloCtrl.dispose(); _marcaCtrl.dispose(); _descripcionCtrl.dispose();
    _imeiCtrl.dispose(); _contrasenaCtrl.dispose();
    _observacionCtrl.dispose(); _tecnicoCtrl.dispose();
    _horaRecibidoCtrl.dispose(); _fechaEntregaCtrl.dispose();
    super.dispose();
  }

  String _horaActual() {
    final n = DateTime.now();
    return "${n.hour.toString().padLeft(2,'0')}:${n.minute.toString().padLeft(2,'0')}";
  }

