  Widget _montoBox(String label, String value, Color color) {
    return Expanded(child: Container(
      padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 8),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.15),
        borderRadius: BorderRadius.circular(10)),
      child: Column(children: [
        Text(label, style: const TextStyle(color: Colors.white70, fontSize: 11)),
        const SizedBox(height: 2),
        Text(value, style: TextStyle(color: color, fontSize: 14,
          fontWeight: FontWeight.bold)),
      ]),
    ));
  }

  /// Grid de fotos de recepción. Cada foto es un thumbnail que al
  /// tocarse abre un viewer a pantalla completa con zoom y deslizar
  /// entre fotos. Las fotos se decodifican desde base64.
  Widget _galeriaFotosRecepcion() {
    return Card(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
      elevation: 1,
      child: Padding(
        padding: const EdgeInsets.all(12),
        child: GridView.builder(
          shrinkWrap: true,
          physics: const NeverScrollableScrollPhysics(),
          itemCount: s.fotosRecepcion.length,
          gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
            crossAxisCount: 3,
            crossAxisSpacing: 8,
            mainAxisSpacing: 8,
            childAspectRatio: 1.0,
          ),
          itemBuilder: (_, i) => _miniaturaFoto(i),
        ),
      ),
    );
  }

  /// Miniatura cuadrada que abre el viewer al pulsarla.
  Widget _miniaturaFoto(int idx) {
    final dataB64 = s.fotosRecepcion[idx];
    Uint8List? bytes;
    try {
      final clean = dataB64.contains(',')
          ? dataB64.split(',').last : dataB64;
      bytes = base64Decode(clean);
    } catch (_) {
      bytes = null;
    }
    return GestureDetector(
      onTap: bytes == null ? null : () => _abrirViewerFotos(idx),
      child: Container(
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(8),
          border: Border.all(color: Colors.grey.shade300),
          color: Colors.grey.shade100,
        ),
        clipBehavior: Clip.antiAlias,
        child: bytes != null
            ? Stack(fit: StackFit.expand, children: [
                Image.memory(bytes, fit: BoxFit.cover),
                // Ícono indicando que se puede ampliar
                const Positioned(
                  bottom: 4, right: 4,
                  child: Icon(Icons.zoom_in,
                      color: Colors.white, size: 18,
                      shadows: [Shadow(blurRadius: 4,
                          color: Colors.black54)]),
                ),
              ])
            : const Center(
                child: Icon(Icons.broken_image,
                    color: Colors.grey)),
      ),
    );
  }

  /// Abre un visor a pantalla completa con la foto inicial [idx] y
  /// permite navegar entre todas las fotos del servicio.
  void _abrirViewerFotos(int idx) {
    Navigator.of(context).push(MaterialPageRoute(
      builder: (_) => _ViewerFotosServicio(
        fotos: s.fotosRecepcion,
        indiceInicial: idx,
      ),
    ));
  }

  Widget _tituloSeccion(String titulo, IconData icono) => Padding(
    padding: const EdgeInsets.only(bottom: 8),
    child: Row(children: [
      Icon(icono, color: AppColors.royalBlue, size: 18),
      const SizedBox(width: 6),
      Text(titulo, style: const TextStyle(
        fontWeight: FontWeight.bold, color: AppColors.royalBlue)),
    ]),
  );

  Widget _infoTarjeta(List<Widget> filas) => Card(
    margin: EdgeInsets.zero,
    shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
    child: Padding(
      padding: const EdgeInsets.all(14),
      child: Column(children: filas),
    ),
  );

  Widget _filaInfo(String label, String valor) => Padding(
    padding: const EdgeInsets.symmetric(vertical: 4),
    child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
      SizedBox(width: 110, child: Text("$label:",
        style: const TextStyle(color: AppColors.textSecondary, fontSize: 12))),
      Expanded(child: Text(valor.isEmpty ? '—' : valor,
        style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w500))),
    ]),
  );

  Widget _chkRow(String label, bool? value) {
    String txt; Color color;
    if (value == null) { txt = "—"; color = Colors.grey; }
    else if (value)    { txt = "SI"; color = AppColors.statusGreen; }
    else               { txt = "NO"; color = AppColors.statusRed; }
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 3),
      child: Row(children: [
        Expanded(child: Text(label, style: const TextStyle(fontSize: 11))),
        Container(
          width: 30, padding: const EdgeInsets.symmetric(vertical: 2),
          decoration: BoxDecoration(
            color: color.withValues(alpha: 0.15),
            borderRadius: BorderRadius.circular(4),
            border: Border.all(color: color.withValues(alpha: 0.5), width: 0.8)),
          child: Text(txt, textAlign: TextAlign.center,
            style: TextStyle(fontSize: 9, fontWeight: FontWeight.bold, color: color)),
        ),
      ]),
    );
  }

  // ── Acciones ─────────────────────────────────────────────
  Future<void> _editar() async {
    await Navigator.push(context, MaterialPageRoute(
      builder: (_) => _FormularioServicioTecnico(servicio: s)));
    if (!mounted) return;
    // Al volver, recargar el servicio para mostrar cambios
    if (s.id != null) {
      try {
        final raw = await _Api.get('servicios', {'id': s.id!.toString()});
        if (!mounted) return;
        if (raw != null) {
          final actualizado = ServicioTecnico.fromMap(raw is List ? raw.first : raw);
          setState(() => s = actualizado);
        }
      } catch (_) {
        // si falla, cerrar para volver a la lista
        if (mounted) Navigator.pop(context);
      }
    } else {
      if (mounted) Navigator.pop(context);
    }
  }

  Future<void> _eliminar() async {
    final confirmar = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text("¿Eliminar servicio?"),
        content: const Text("Esta acción no se puede deshacer."),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false),
            child: const Text("Cancelar")),
          ElevatedButton(
            style: ElevatedButton.styleFrom(backgroundColor: AppColors.statusRed),
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text("Eliminar", style: TextStyle(color: Colors.white))),
        ],
      ),
    );
    if (confirmar != true || !mounted) return;
    try {
      if (s.id != null) {
        await _Api.delete('servicios', s.id!.toString());
      }
      if (!mounted) return;
      Navigator.pop(context);
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text("Servicio eliminado."),
        backgroundColor: AppColors.statusGreen));
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text("Error: $e"), backgroundColor: AppColors.statusRed));
    }
  }

  // ── Generar y mostrar PDF para imprimir ──────────────────
  Future<void> _imprimir() async {
    // Preguntar formato al usuario (o usar el preferido si ya lo eligió)
    final formato = await ImpresionHelper.obtenerFormato(context);
    if (formato == null) return;
    final esTermica = ImpresionHelper.esTermica(formato);
    final escala = ImpresionHelper.escalaFuente(formato);
    double fs(double base) => base * escala;

    try {
      final pdf = pw.Document();

      // Encabezado de la sede (si hay configurado)
      String nombreSede = ConfigSistema.tiendas.isNotEmpty
          ? ConfigSistema.tiendas.first
          : ConfigSistema.nombreEmpresa;
      final enc = ConfigSistema.encabezadoDe(nombreSede);

      // Helper para renderizar una casilla SI/NO (tamaño adaptativo)
      pw.Widget _chkPdf(String label, bool? v) {
        final txt = v == null ? '—' : (v ? 'SI' : 'NO');
        return pw.Padding(
          padding: const pw.EdgeInsets.symmetric(vertical: 1.5),
          child: pw.Row(children: [
            pw.Expanded(child: pw.Text(label, style: pw.TextStyle(fontSize: fs(9)))),
            pw.Container(
              width: esTermica ? 22 : 26,
              padding: const pw.EdgeInsets.symmetric(vertical: 1),
              decoration: pw.BoxDecoration(
                border: pw.Border.all(width: 0.5),
                borderRadius: pw.BorderRadius.circular(2)),
              child: pw.Text(txt, textAlign: pw.TextAlign.center,
                style: pw.TextStyle(fontSize: fs(8), fontWeight: pw.FontWeight.bold)),
            ),
          ]),
        );
      }

      pw.Widget _celda(String label, String val) => pw.Padding(
        padding: const pw.EdgeInsets.symmetric(vertical: 2),
        child: pw.RichText(
          text: pw.TextSpan(children: [
            pw.TextSpan(text: "$label: ",
              style: pw.TextStyle(
                fontSize: fs(10),
                color: PdfColors.black,
                fontWeight: pw.FontWeight.normal)),
            pw.TextSpan(text: val.isEmpty ? '—' : val,
              style: pw.TextStyle(
                fontSize: fs(10),
                fontWeight: pw.FontWeight.bold,
                color: PdfColors.black)),
          ]),
        ),
      );

      // ═══════════════════════════════════════════════════════════
      //  LAYOUT TÉRMICO (80mm / 58mm) — elegante y compacto
      // ═══════════════════════════════════════════════════════════
      if (esTermica) {
        // Helpers locales para este layout.
        // Header de sección: fondo NEGRO + texto BLANCO, igual que el
        // ticket de factura. El gris claro anterior (grey200) se perdía
        // totalmente en papel térmico (bajo contraste).
        pw.Widget secHdr(String t) => pw.Container(
          width: double.infinity,
          padding: const pw.EdgeInsets.symmetric(vertical: 3, horizontal: 5),
          margin: const pw.EdgeInsets.only(bottom: 3, top: 2),
          decoration: const pw.BoxDecoration(
            color: PdfColors.black,
            borderRadius: pw.BorderRadius.all(pw.Radius.circular(2))),
          child: pw.Text(t,
            style: pw.TextStyle(
              fontSize: fs(8.5),
              fontWeight: pw.FontWeight.bold,
              color: PdfColors.white,
              letterSpacing: 0.8)));

        pw.Widget sep() => pw.Container(
          height: 0.4, color: PdfColors.black,
          margin: const pw.EdgeInsets.symmetric(vertical: 3));
        pw.Widget sepG() => pw.Container(
          height: 0.8, color: PdfColors.black,
          margin: const pw.EdgeInsets.symmetric(vertical: 3));

        pdf.addPage(pw.Page(
          pageFormat: ImpresionHelper.formatoPdf(formato),
          margin: const pw.EdgeInsets.all(4),
          build: (_) => pw.Column(
            crossAxisAlignment: pw.CrossAxisAlignment.start,
            children: [
            // ═══════════════════════════════════════════════════
            //  ENCABEZADO — badge destacado
            // ═══════════════════════════════════════════════════
            pw.Container(
              width: double.infinity,
              padding: const pw.EdgeInsets.symmetric(vertical: 5, horizontal: 6),
              decoration: const pw.BoxDecoration(
                color: PdfColors.black,
                borderRadius: pw.BorderRadius.all(pw.Radius.circular(2))),
              child: pw.Center(child: pw.Text('SERVICIO TÉCNICO',
                style: pw.TextStyle(
                  fontSize: fs(12),
                  fontWeight: pw.FontWeight.bold,
                  color: PdfColors.white,
                  letterSpacing: 1.2))),
            ),
            pw.SizedBox(height: 5),

            // Datos de empresa (sin tienda específica).
            // Solo imprime si hay un nombre configurado; si está vacío,
            // omitimos la línea completamente para no dejar espacio en blanco.
            if (ConfigSistema.nombreEmpresa.trim().isNotEmpty)
              pw.Center(child: pw.Text(ConfigSistema.nombreEmpresa,
                style: pw.TextStyle(
                  fontSize: fs(10),
                  fontWeight: pw.FontWeight.bold))),
            if (enc.rif.isNotEmpty)
              pw.Center(child: pw.Text("RIF: ${enc.rif}",
                style: pw.TextStyle(
                  fontSize: fs(8),
                  fontWeight: pw.FontWeight.bold,
                  color: PdfColors.black))),
            if (enc.telefono.isNotEmpty)
              pw.Center(child: pw.Text("Tel: ${enc.telefono}",
                style: pw.TextStyle(
                  fontSize: fs(8),
                  fontWeight: pw.FontWeight.bold,
                  color: PdfColors.black))),

            pw.SizedBox(height: 4),
            sepG(),

            // ═══════════════════════════════════════════════════
            //  ORDEN Y FECHA
            // ═══════════════════════════════════════════════════
            pw.Row(mainAxisAlignment: pw.MainAxisAlignment.spaceBetween, children: [
              pw.Container(
                padding: const pw.EdgeInsets.symmetric(horizontal: 5, vertical: 2),
                decoration: pw.BoxDecoration(
                  border: pw.Border.all(width: 0.8, color: PdfColors.black),
                  borderRadius: const pw.BorderRadius.all(pw.Radius.circular(2))),
                child: pw.Text("ORDEN Nº ${s.id ?? "—"}",
                  style: pw.TextStyle(
                    fontSize: fs(9),
                    fontWeight: pw.FontWeight.bold)),
              ),
              pw.Text(
                "${s.fecha.day.toString().padLeft(2,'0')}/"
                "${s.fecha.month.toString().padLeft(2,'0')}/"
                "${s.fecha.year}",
                style: pw.TextStyle(
                  fontSize: fs(9),
                  fontWeight: pw.FontWeight.bold)),
            ]),
            pw.SizedBox(height: 4),

            // ═══════════════════════════════════════════════════
            //  CLIENTE
            // ═══════════════════════════════════════════════════
            secHdr("CLIENTE"),
            pw.Text(s.nombreCliente.isEmpty ? '—' : s.nombreCliente,
              style: pw.TextStyle(
                fontSize: fs(9.5),
                fontWeight: pw.FontWeight.bold)),
            if (s.rifCi.isNotEmpty) _celda("C.I./RIF", s.rifCi),
            if (s.telefono.isNotEmpty) _celda("Tel", s.telefono),
            if (s.horaRecibido.isNotEmpty) _celda("Recibido", s.horaRecibido),
            if (s.fechaEntrega.isNotEmpty) _celda("Entrega", s.fechaEntrega),
            sep(),

            // ═══════════════════════════════════════════════════
            //  EQUIPO (con borde lateral tipo acento)
            // ═══════════════════════════════════════════════════
            secHdr("EQUIPO"),
            pw.Container(
              padding: const pw.EdgeInsets.only(left: 6, right: 2, top: 2, bottom: 4),
              decoration: const pw.BoxDecoration(
                border: pw.Border(
                  left: pw.BorderSide(width: 2, color: PdfColors.black))),
              child: pw.Column(
                crossAxisAlignment: pw.CrossAxisAlignment.start,
                children: [
                  if (s.marca.isNotEmpty || s.modelo.isNotEmpty)
                    pw.Text("${s.marca} ${s.modelo}".trim(),
                      style: pw.TextStyle(
                        fontSize: fs(9.5),
                        fontWeight: pw.FontWeight.bold)),
                  if (s.imei.isNotEmpty) _celda("IMEI", s.imei),
                  if (s.contrasena.isNotEmpty) _celda("Contraseña", s.contrasena),
                  if (s.descripcion.isNotEmpty) _celda("Descripción", s.descripcion),
                ],
              ),
            ),
            sep(),

            // ═══════════════════════════════════════════════════
            //  MONTOS (caja con borde negro nítido)
            // ═══════════════════════════════════════════════════
            secHdr("MONTOS"),
            pw.Container(
              padding: const pw.EdgeInsets.all(5),
              decoration: pw.BoxDecoration(
                border: pw.Border.all(width: 0.6, color: PdfColors.black),
                borderRadius: const pw.BorderRadius.all(pw.Radius.circular(2))),
              child: pw.Column(children: [
                pw.Row(mainAxisAlignment: pw.MainAxisAlignment.spaceBetween, children: [
                  pw.Text("Total",
                    style: pw.TextStyle(
                      fontSize: fs(9),
                      color: PdfColors.black)),
                  pw.Text(formatCurrency(s.monto),
                    style: pw.TextStyle(
                      fontSize: fs(9.5),
                      fontWeight: pw.FontWeight.bold,
                      color: PdfColors.black)),
                ]),
                pw.SizedBox(height: 2),
                pw.Row(mainAxisAlignment: pw.MainAxisAlignment.spaceBetween, children: [
                  pw.Text("Abono",
                    style: pw.TextStyle(
                      fontSize: fs(9),
                      color: PdfColors.black)),
                  pw.Text(formatCurrency(s.abono),
                    style: pw.TextStyle(
                      fontSize: fs(9.5),
                      fontWeight: pw.FontWeight.bold,
                      color: PdfColors.black)),
                ]),
                pw.Container(height: 0.5, color: PdfColors.black,
                  margin: const pw.EdgeInsets.symmetric(vertical: 3)),
                pw.Row(mainAxisAlignment: pw.MainAxisAlignment.spaceBetween, children: [
                  pw.Text("RESTA",
                    style: pw.TextStyle(
                      fontSize: fs(10),
                      fontWeight: pw.FontWeight.bold,
                      color: PdfColors.black)),
                  pw.Text(formatCurrency(s.resta),
                    style: pw.TextStyle(
                      fontSize: fs(11),
                      fontWeight: pw.FontWeight.bold,
                      color: PdfColors.black)),
                ]),
              ]),
            ),
            pw.SizedBox(height: 3),
            // Estado de pago
            pw.Center(child: pw.Container(
              padding: const pw.EdgeInsets.symmetric(horizontal: 8, vertical: 2),
              decoration: pw.BoxDecoration(
                color: s.pagado ? PdfColors.black : PdfColors.white,
                border: pw.Border.all(width: 0.8, color: PdfColors.black),
                borderRadius: const pw.BorderRadius.all(pw.Radius.circular(2))),
              child: pw.Text(s.pagado ? "✓  PAGADO" : "✗  PENDIENTE",
                style: pw.TextStyle(
                  fontSize: fs(9),
                  fontWeight: pw.FontWeight.bold,
                  color: s.pagado ? PdfColors.white : PdfColors.black,
                  letterSpacing: 1)))),
            sep(),

            // ═══════════════════════════════════════════════════
            //  CHECKLIST — solo ítems marcados (SI / NO)
            //  Los ítems no revisados (null) se omiten para mantener
            //  el ticket limpio y legible. Se separan los "SI" (estado
            //  correcto al recibir) de los "NO" (componentes faltantes
            //  o con defecto al recibir el equipo).
            // ═══════════════════════════════════════════════════
            ...(() {
              final items = <MapEntry<String, bool>>[
                if (s.chip               != null) MapEntry("Chip",                 s.chip!),
                if (s.memoria            != null) MapEntry("Memoria",              s.memoria!),
                if (s.bateria            != null) MapEntry("Batería",              s.bateria!),
                if (s.tapa               != null) MapEntry("Tapa",                 s.tapa!),
                if (s.encendido          != null) MapEntry("Encendido",            s.encendido!),
                if (s.apagado            != null) MapEntry("Apagado",              s.apagado!),
                if (s.camara             != null) MapEntry("Cámara",               s.camara!),
                if (s.corneta            != null) MapEntry("Corneta",              s.corneta!),
                if (s.flash              != null) MapEntry("Flash",                s.flash!),
                if (s.flashConDefecto    != null) MapEntry("Flash con defecto",    s.flashConDefecto!),
                if (s.tactilPartido      != null) MapEntry("Táctil partido",       s.tactilPartido!),
                if (s.auricular          != null) MapEntry("Auricular",            s.auricular!),
                if (s.microfono          != null) MapEntry("Micrófono",            s.microfono!),
                if (s.contrasenaChk      != null) MapEntry("Contraseña OK",        s.contrasenaChk!),
                if (s.track              != null) MapEntry("Track",                s.track!),
                if (s.botonVolumen       != null) MapEntry("Botón volumen",        s.botonVolumen!),
                if (s.teclado            != null) MapEntry("Teclado",              s.teclado!),
                if (s.botonEncendido     != null) MapEntry("Botón encendido",      s.botonEncendido!),
                if (s.pantallaConDefecto != null) MapEntry("Pantalla con defecto", s.pantallaConDefecto!),
              ];
              if (items.isEmpty) return <pw.Widget>[];
              return <pw.Widget>[
                secHdr("CHECKLIST DEL EQUIPO"),
                ...items.map((it) => _chkPdf(it.key, it.value)),
                sep(),
              ];
            })(),

            // ═══════════════════════════════════════════════════
            //  NOTAS FINALES
            // ═══════════════════════════════════════════════════
            if (s.observacion.isNotEmpty) ...[
              secHdr("OBSERVACIÓN"),
              pw.Text(s.observacion,
                style: pw.TextStyle(fontSize: fs(8.5))),
              pw.SizedBox(height: 3),
            ],
            pw.Row(children: [
              pw.Expanded(child: _celda("Técnico", _resolverNombreVendedor(s.tecnico))),
            ]),
            pw.Row(children: [
              pw.Expanded(child: _celda("Estado", s.estado)),
            ]),

            pw.SizedBox(height: 5),
            sepG(),
            pw.SizedBox(height: 4),

            // ═══════════════════════════════════════════════════
            //  CONDICIONES (caja con borde nítido)
            // ═══════════════════════════════════════════════════
            pw.Container(
              width: double.infinity,
              padding: const pw.EdgeInsets.all(5),
              decoration: pw.BoxDecoration(
                border: pw.Border.all(width: 0.6, color: PdfColors.black),
                borderRadius: const pw.BorderRadius.all(pw.Radius.circular(2))),
              child: pw.Column(
                crossAxisAlignment: pw.CrossAxisAlignment.start,
                children: [
                  pw.Text("CONDICIONES:",
                    style: pw.TextStyle(
                      fontSize: fs(8),
                      fontWeight: pw.FontWeight.bold,
                      color: PdfColors.black,
                      letterSpacing: 0.5)),
                  pw.SizedBox(height: 2),
                  pw.Text(
                    "• Por favor retirar chip, tapa, batería y memoria. "
                    "No nos hacemos responsables si los dejan sin nuestro consentimiento.",
                    style: pw.TextStyle(
                      fontSize: fs(7),
                      color: PdfColors.black),
                    textAlign: pw.TextAlign.justify),
                  pw.SizedBox(height: 2),
                  pw.Text(
                    "• No respondemos por equipos dejados más de 15 días.",
                    style: pw.TextStyle(
                      fontSize: fs(7),
                      color: PdfColors.black),
                    textAlign: pw.TextAlign.justify),
                ],
              ),
            ),

            // ═══════════════════════════════════════════════════
            //  FIRMAS
            // ═══════════════════════════════════════════════════
            pw.SizedBox(height: 28),
            pw.Center(child: pw.Container(
              width: 140, height: 0.6, color: PdfColors.black)),
            pw.Center(child: pw.Text("Firma del Cliente",
              style: pw.TextStyle(
                fontSize: fs(8),
                fontWeight: pw.FontWeight.bold))),

            pw.SizedBox(height: 22),
            pw.Center(child: pw.Container(
              width: 140, height: 0.6, color: PdfColors.black)),
            pw.Center(child: pw.Text("Quien Recibe",
              style: pw.TextStyle(
                fontSize: fs(8),
                fontWeight: pw.FontWeight.bold))),

            pw.SizedBox(height: 20),
            ],
          ),
        ));
      } else {
        // ═══════════════════════════════════════════════════════════
        //  LAYOUT A4 / CARTA — diseño profesional con caja destacada
        // ═══════════════════════════════════════════════════════════
        pdf.addPage(pw.Page(
          pageFormat: ImpresionHelper.formatoPdf(formato),
          margin: const pw.EdgeInsets.all(28),
          build: (context) => pw.Column(
            crossAxisAlignment: pw.CrossAxisAlignment.start,
            children: [
              // ═══════════════════════════════════════════════════
              //  ENCABEZADO con banda oscura
              // ═══════════════════════════════════════════════════
              pw.Container(
                padding: const pw.EdgeInsets.all(14),
                decoration: pw.BoxDecoration(
                  color: PdfColors.grey100,
                  borderRadius: const pw.BorderRadius.all(pw.Radius.circular(6)),
                  border: pw.Border.all(width: 1, color: PdfColors.grey400)),
                child: pw.Row(
                  crossAxisAlignment: pw.CrossAxisAlignment.center,
                  children: [
                    // Izquierda: título + empresa
                    pw.Expanded(child: pw.Column(
                      crossAxisAlignment: pw.CrossAxisAlignment.start,
                      children: [
                        pw.Container(
                          padding: const pw.EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                          decoration: const pw.BoxDecoration(
                            color: PdfColors.black,
                            borderRadius: pw.BorderRadius.all(pw.Radius.circular(3))),
                          child: pw.Text('SERVICIO TÉCNICO',
                            style: pw.TextStyle(
                              fontSize: 16,
                              fontWeight: pw.FontWeight.bold,
                              color: PdfColors.white,
                              letterSpacing: 1.2)),
                        ),
                        pw.SizedBox(height: 8),
                        if (ConfigSistema.nombreEmpresa.trim().isNotEmpty)
                          pw.Text(ConfigSistema.nombreEmpresa,
                            style: pw.TextStyle(
                              fontSize: 14,
                              fontWeight: pw.FontWeight.bold)),
                        if (enc.rif.isNotEmpty)
                          pw.Text("RIF: ${enc.rif}",
                            style: pw.TextStyle(
                              fontSize: 9,
                              fontWeight: pw.FontWeight.normal,
                              color: PdfColors.black)),
                        if (enc.direccion.isNotEmpty)
                          pw.Text(enc.direccion,
                            style: pw.TextStyle(
                              fontSize: 9,
                              fontWeight: pw.FontWeight.normal,
                              color: PdfColors.black)),
                        if (enc.telefono.isNotEmpty)
                          pw.Text("Tel: ${enc.telefono}",
                            style: pw.TextStyle(
                              fontSize: 9,
                              fontWeight: pw.FontWeight.normal,
                              color: PdfColors.black)),
                      ])),
                    // Derecha: orden + fecha
                    pw.Column(
                      crossAxisAlignment: pw.CrossAxisAlignment.end,
                      children: [
                        if (s.id != null)
                          pw.Container(
                            padding: const pw.EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                            decoration: pw.BoxDecoration(
                              border: pw.Border.all(width: 1.2, color: PdfColors.black),
                              borderRadius: const pw.BorderRadius.all(pw.Radius.circular(3))),
                            child: pw.Text("Orden Nº ${s.id}",
                              style: pw.TextStyle(
                                fontSize: 12,
                                fontWeight: pw.FontWeight.bold)),
                          ),
                        pw.SizedBox(height: 6),
                        pw.Container(
                          padding: const pw.EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                          decoration: const pw.BoxDecoration(
                            color: PdfColors.black,
                            borderRadius: pw.BorderRadius.all(pw.Radius.circular(3))),
                          child: pw.Text(
                            "${s.fecha.day.toString().padLeft(2,'0')}/"
                            "${s.fecha.month.toString().padLeft(2,'0')}/"
                            "${s.fecha.year}",
                            style: pw.TextStyle(
                              fontSize: 11,
                              fontWeight: pw.FontWeight.bold,
                              color: PdfColors.white)),
                        ),
                      ]),
                  ]),
              ),
              pw.SizedBox(height: 12),

              // ═══════════════════════════════════════════════════
              //  MONTOS (banner horizontal destacado)
              // ═══════════════════════════════════════════════════
              pw.Container(
                padding: const pw.EdgeInsets.all(10),
                decoration: pw.BoxDecoration(
                  color: PdfColors.grey100,
                  borderRadius: const pw.BorderRadius.all(pw.Radius.circular(6))),
                child: pw.Row(children: [
                  pw.Expanded(child: pw.Column(
                    crossAxisAlignment: pw.CrossAxisAlignment.start,
                    children: [
                      pw.Text("MONTO TOTAL",
                        style: pw.TextStyle(
                          fontSize: 9,
                          fontWeight: pw.FontWeight.bold,
                          color: PdfColors.black,
                          letterSpacing: 0.5)),
                      pw.Text(formatCurrency(s.monto),
                        style: pw.TextStyle(fontSize: 14, fontWeight: pw.FontWeight.bold)),
                    ])),
                  pw.Container(width: 1, height: 32, color: PdfColors.grey400),
                  pw.SizedBox(width: 10),
                  pw.Expanded(child: pw.Column(
                    crossAxisAlignment: pw.CrossAxisAlignment.start,
                    children: [
                      pw.Text("ABONO",
                        style: pw.TextStyle(
                          fontSize: 9,
                          fontWeight: pw.FontWeight.bold,
                          color: PdfColors.black,
                          letterSpacing: 0.5)),
                      pw.Text(formatCurrency(s.abono),
                        style: pw.TextStyle(fontSize: 14, fontWeight: pw.FontWeight.bold)),
                    ])),
                  pw.Container(width: 1, height: 32, color: PdfColors.grey400),
                  pw.SizedBox(width: 10),
                  pw.Expanded(child: pw.Column(
                    crossAxisAlignment: pw.CrossAxisAlignment.start,
                    children: [
                      pw.Text("RESTA",
                        style: pw.TextStyle(
                          fontSize: 9,
                          fontWeight: pw.FontWeight.bold,
                          color: PdfColors.black,
                          letterSpacing: 0.5)),
                      pw.Text(formatCurrency(s.resta),
                        style: pw.TextStyle(
                          fontSize: 14,
                          fontWeight: pw.FontWeight.bold,
                          color: s.resta > 0 ? PdfColors.red800 : PdfColors.green800)),
                    ])),
                  pw.Container(
                    padding: const pw.EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                    decoration: pw.BoxDecoration(
                      color: s.pagado ? PdfColors.green700 : PdfColors.grey300,
                      borderRadius: const pw.BorderRadius.all(pw.Radius.circular(20))),
                    child: pw.Text(s.pagado ? "✓  PAGADO" : "PENDIENTE",
                      style: pw.TextStyle(
                        fontSize: 11,
                        fontWeight: pw.FontWeight.bold,
                        color: s.pagado ? PdfColors.white : PdfColors.grey800,
                        letterSpacing: 0.8)),
                  ),
                ]),
              ),
              pw.SizedBox(height: 12),

              // ═══════════════════════════════════════════════════
              //  CLIENTE (caja)
              // ═══════════════════════════════════════════════════
              pw.Container(
                padding: const pw.EdgeInsets.all(10),
                decoration: pw.BoxDecoration(
                  border: pw.Border.all(width: 0.6, color: PdfColors.grey400),
                  borderRadius: const pw.BorderRadius.all(pw.Radius.circular(6))),
                child: pw.Column(
                  crossAxisAlignment: pw.CrossAxisAlignment.start,
                  children: [
                    pw.Text("DATOS DEL CLIENTE",
                      style: pw.TextStyle(
                        fontSize: 10,
                        fontWeight: pw.FontWeight.bold,
                        color: PdfColors.black,
                        letterSpacing: 0.5)),
                    pw.SizedBox(height: 6),
                    _celda("Nombre", s.nombreCliente),
                    pw.Row(children: [
                      pw.Expanded(child: _celda("Tel", s.telefono)),
                      pw.Expanded(child: _celda("C.I./RIF", s.rifCi)),
                    ]),
                    pw.Row(children: [
                      pw.Expanded(child: _celda("Hora recibido", s.horaRecibido)),
                      pw.Expanded(child: _celda("Fecha entrega", s.fechaEntrega)),
                    ]),
                  ]),
              ),
              pw.SizedBox(height: 10),

              // ═══════════════════════════════════════════════════
              //  EQUIPO (caja)
              // ═══════════════════════════════════════════════════
              pw.Container(
                padding: const pw.EdgeInsets.all(10),
                decoration: pw.BoxDecoration(
                  border: pw.Border.all(width: 0.6, color: PdfColors.grey400),
                  borderRadius: const pw.BorderRadius.all(pw.Radius.circular(6))),
                child: pw.Column(
                  crossAxisAlignment: pw.CrossAxisAlignment.start,
                  children: [
                    pw.Text("DATOS DEL EQUIPO",
                      style: pw.TextStyle(
                        fontSize: 10,
                        fontWeight: pw.FontWeight.bold,
                        color: PdfColors.black,
                        letterSpacing: 0.5)),
                    pw.SizedBox(height: 6),
                    pw.Row(children: [
                      pw.Expanded(child: _celda("Marca", s.marca)),
                      pw.Expanded(child: _celda("Modelo", s.modelo)),
                    ]),
                    pw.Row(children: [
                      pw.Expanded(child: _celda("IMEI", s.imei)),
                      pw.Expanded(child: _celda("Contraseña", s.contrasena)),
                    ]),
                    if (s.descripcion.isNotEmpty) _celda("Descripción", s.descripcion),
                  ]),
              ),
              pw.SizedBox(height: 10),

              // ═══════════════════════════════════════════════════
              //  CHECKLIST (solo ítems marcados — caja con 2 columnas
              //  balanceadas). Los ítems no revisados (null) se omiten
              //  para que el reporte quede limpio y profesional.
              // ═══════════════════════════════════════════════════
              ...(() {
                final items = <MapEntry<String, bool>>[
                  if (s.chip               != null) MapEntry("Chip",                 s.chip!),
                  if (s.memoria            != null) MapEntry("Memoria",              s.memoria!),
                  if (s.bateria            != null) MapEntry("Batería",              s.bateria!),
                  if (s.tapa               != null) MapEntry("Tapa",                 s.tapa!),
                  if (s.encendido          != null) MapEntry("Encendido",            s.encendido!),
                  if (s.apagado            != null) MapEntry("Apagado",              s.apagado!),
                  if (s.camara             != null) MapEntry("Cámara",               s.camara!),
                  if (s.corneta            != null) MapEntry("Corneta",              s.corneta!),
                  if (s.flash              != null) MapEntry("Flash",                s.flash!),
                  if (s.flashConDefecto    != null) MapEntry("Flash con defecto",    s.flashConDefecto!),
                  if (s.tactilPartido      != null) MapEntry("Táctil partido",       s.tactilPartido!),
                  if (s.auricular          != null) MapEntry("Auricular",            s.auricular!),
                  if (s.microfono          != null) MapEntry("Micrófono",            s.microfono!),
                  if (s.contrasenaChk      != null) MapEntry("Contraseña",           s.contrasenaChk!),
                  if (s.track              != null) MapEntry("Track",                s.track!),
                  if (s.botonVolumen       != null) MapEntry("Botón de volumen",     s.botonVolumen!),
                  if (s.teclado            != null) MapEntry("Teclado",              s.teclado!),
                  if (s.botonEncendido     != null) MapEntry("Botón de encendido",   s.botonEncendido!),
                  if (s.pantallaConDefecto != null) MapEntry("Pantalla con defecto", s.pantallaConDefecto!),
                ];
                if (items.isEmpty) return <pw.Widget>[];
                final mid = (items.length + 1) ~/ 2;
                final col1 = items.sublist(0, mid);
                final col2 = items.sublist(mid);
                return <pw.Widget>[
                  pw.Container(
                    padding: const pw.EdgeInsets.all(10),
                    decoration: pw.BoxDecoration(
                      border: pw.Border.all(width: 0.6, color: PdfColors.grey400),
                      borderRadius: const pw.BorderRadius.all(pw.Radius.circular(6))),
                    child: pw.Column(
                      crossAxisAlignment: pw.CrossAxisAlignment.start,
                      children: [
                        pw.Text("CHECKLIST DEL EQUIPO",
                          style: pw.TextStyle(
                            fontSize: 10,
                            fontWeight: pw.FontWeight.bold,
                            color: PdfColors.black,
                            letterSpacing: 0.5)),
                        pw.SizedBox(height: 8),
                        pw.Row(
                          crossAxisAlignment: pw.CrossAxisAlignment.start,
                          children: [
                            pw.Expanded(child: pw.Column(
                              children: col1.map((e) => _chkPdf(e.key, e.value)).toList())),
                            pw.SizedBox(width: 12),
                            pw.Expanded(child: pw.Column(
                              children: col2.map((e) => _chkPdf(e.key, e.value)).toList())),
                          ]),
                      ]),
                  ),
                  pw.SizedBox(height: 10),
                ];
              })(),

              // ═══════════════════════════════════════════════════
              //  OBSERVACIÓN + TÉCNICO + ESTADO
              // ═══════════════════════════════════════════════════
              pw.Container(
                padding: const pw.EdgeInsets.all(10),
                decoration: pw.BoxDecoration(
                  border: pw.Border.all(width: 0.6, color: PdfColors.grey400),
                  borderRadius: const pw.BorderRadius.all(pw.Radius.circular(6))),
                child: pw.Column(
                  crossAxisAlignment: pw.CrossAxisAlignment.start,
                  children: [
                    if (s.observacion.isNotEmpty) ...[
                      pw.Text("OBSERVACIÓN",
                        style: pw.TextStyle(
                          fontSize: 9,
                          fontWeight: pw.FontWeight.bold,
                          color: PdfColors.black,
                          letterSpacing: 0.5)),
                      pw.SizedBox(height: 3),
                      pw.Text(s.observacion,
                        style: const pw.TextStyle(fontSize: 10)),
                      pw.SizedBox(height: 8),
                    ],
                    pw.Row(children: [
                      pw.Expanded(child: _celda("Técnico", _resolverNombreVendedor(s.tecnico))),
                      pw.Expanded(child: _celda("Estado", s.estado)),
                    ]),
                  ]),
              ),
              pw.SizedBox(height: 12),

              // ═══════════════════════════════════════════════════
              //  CONDICIONES
              // ═══════════════════════════════════════════════════
              pw.Container(
                padding: const pw.EdgeInsets.all(10),
                decoration: pw.BoxDecoration(
                  color: PdfColors.grey100,
                  borderRadius: const pw.BorderRadius.all(pw.Radius.circular(6))),
                child: pw.Column(
                  crossAxisAlignment: pw.CrossAxisAlignment.start,
                  children: [
                    pw.Text("CONDICIONES Y TÉRMINOS",
                      style: pw.TextStyle(
                        fontSize: 9,
                        fontWeight: pw.FontWeight.bold,
                        color: PdfColors.black,
                        letterSpacing: 0.5)),
                    pw.SizedBox(height: 5),
                    pw.Text(
                      "• Por favor retirar chip, tapa, batería y memoria de su equipo. "
                      "No nos hacemos responsables si los dejan sin nuestro consentimiento.",
                      style: const pw.TextStyle(fontSize: 8)),
                    pw.SizedBox(height: 3),
                    pw.Text(
                      "• No respondemos por equipos dejados por más de 15 días.",
                      style: const pw.TextStyle(fontSize: 8)),
                  ]),
              ),

              // ═══════════════════════════════════════════════════
              //  FIRMAS
              // ═══════════════════════════════════════════════════
              pw.SizedBox(height: 40),
              pw.Row(children: [
                pw.Expanded(child: pw.Column(children: [
                  pw.Container(height: 0.8, color: PdfColors.black),
                  pw.SizedBox(height: 4),
                  pw.Text("Firma del Cliente",
                    style: pw.TextStyle(fontSize: 10, fontWeight: pw.FontWeight.bold)),
                ])),
                pw.SizedBox(width: 40),
                pw.Expanded(child: pw.Column(children: [
                  pw.Container(height: 0.8, color: PdfColors.black),
                  pw.SizedBox(height: 4),
                  pw.Text("Quien Recibe",
                    style: pw.TextStyle(fontSize: 10, fontWeight: pw.FontWeight.bold)),
                ])),
              ]),
            ],
          ),
        ));
      }

      // Imprimir: intenta Bluetooth directo si es térmica y hay impresora;
      // si no, abre el diálogo del sistema.
      final bytes = await pdf.save();
      if (mounted) {
        await ImpresionHelper.imprimirPdfInteligente(
          context: context,
          pdfBytes: bytes,
          formato: formato,
          nombreArchivo: 'servicio_tecnico_${s.id ?? "nuevo"}');
      }
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text("Error al imprimir: $e"),
        backgroundColor: AppColors.statusRed));
    }
  }
}

// ════════════════════════════════════════════════════════════
//  VISOR DE FOTOS DE RECEPCIÓN (pantalla completa)
// ════════════════════════════════════════════════════════════
//  Muestra las fotos del servicio en pantalla completa con:
//   · Swipe horizontal para cambiar de foto
//   · Zoom con pellizco
//   · Indicador "1 / N" en la barra superior
class _ViewerFotosServicio extends StatefulWidget {
  final List<String> fotos;
  final int indiceInicial;
  const _ViewerFotosServicio({
    required this.fotos, required this.indiceInicial});
  @override State<_ViewerFotosServicio> createState() =>
      _ViewerFotosServicioState();
}

class _ViewerFotosServicioState extends State<_ViewerFotosServicio> {
  late PageController _pageCtrl;
  late int _indice;

  @override
  void initState() {
    super.initState();
    _indice = widget.indiceInicial;
    _pageCtrl = PageController(initialPage: widget.indiceInicial);
  }

  @override
  void dispose() {
    _pageCtrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.black,
      appBar: AppBar(
        backgroundColor: Colors.black,
        foregroundColor: Colors.white,
        title: Text("${_indice + 1} / ${widget.fotos.length}"),
      ),
      body: PageView.builder(
        controller: _pageCtrl,
        itemCount: widget.fotos.length,
        onPageChanged: (i) => setState(() => _indice = i),
        itemBuilder: (_, i) {
          Uint8List? bytes;
          try {
            final raw = widget.fotos[i];
            final clean = raw.contains(',')
                ? raw.split(',').last : raw;
            bytes = base64Decode(clean);
          } catch (_) {
            bytes = null;
          }
          if (bytes == null) {
            return const Center(child: Icon(Icons.broken_image,
                color: Colors.white54, size: 80));
          }
          // InteractiveViewer permite zoom con pellizco y pan
          return InteractiveViewer(
            minScale: 1.0,
            maxScale: 4.0,
            child: Center(child: Image.memory(bytes,
                fit: BoxFit.contain)),
          );
        },
      ),
    );
  }
}

// ============================================================
//  USUARIOS — carga y guarda en la API
// ============================================================
class VentanaUsuarios extends StatefulWidget {
  const VentanaUsuarios({super.key});
  @override State<VentanaUsuarios> createState() => _VentanaUsuariosState();
}

class _VentanaUsuariosState extends State<VentanaUsuarios> {
  List<Usuario> _usuarios = [];
  bool _cargando = true;

  @override
  void initState() { super.initState(); _cargar(); }

  Future<void> _cargar() async {
    setState(() => _cargando = true);
    try {
      final raw = await _Api.get('usuarios');
      final todos = ((raw as List?) ?? [])
          .map((m) => Usuario.fromMap(m)).toList();
      // ── Ocultar al UsuarioMaestro (proveedor Tecno Líder) ──
      // Si por algún motivo su correo terminó en la BD, no debe
      // aparecer ni ser editable desde la ventana de Usuarios.
      _usuarios = UsuarioMaestro.ocultar<Usuario>(
          todos, (u) => u.correo);
      usuariosSistema = _usuarios;
    } catch (e) {
      debugPrint('[_cargar] Error: $e');
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Error al cargar datos: $e'), backgroundColor: AppColors.statusRed, duration: const Duration(seconds: 4)));
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  void _editarUsuario(Usuario usuario) {
    final correoCtrl = TextEditingController(text: usuario.correo);
    final claveCtrl = TextEditingController(text: usuario.clave);
    final nombreCtrl = TextEditingController(text: usuario.nombre);
    final cedulaCtrl = TextEditingController(text: usuario.cedula);
    final sueldoCtrl = TextEditingController(text: usuario.sueldoBase.toStringAsFixed(2));
    String rol = usuario.rol;
    bool ganaComisiones = usuario.ganaComisiones;
    bool verClave = false;
    bool guardando = false;
    final formKey = GlobalKey<FormState>();

    showDialog(context: context, builder: (ctx) => StatefulBuilder(
      builder: (context, setS) => AlertDialog(
        title: Row(children: [
          CircleAvatar(
            radius: 18,
            backgroundColor: _colorRol(usuario.rol).withValues(alpha: 0.15),
            child: Text(usuario.nombre.isNotEmpty ? usuario.nombre[0].toUpperCase() : '?',
              style: TextStyle(color: _colorRol(usuario.rol), fontWeight: FontWeight.bold)),
          ),
          const SizedBox(width: 10),
          const Text("Editar Usuario"),
        ]),
        content: SingleChildScrollView(
          child: Form(
            key: formKey,
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              TextFormField(
                controller: nombreCtrl,
                textCapitalization: TextCapitalization.words,
                decoration: const InputDecoration(labelText: "Nombre completo *", prefixIcon: Icon(Icons.person_outline)),
                validator: (v) => (v == null || v.trim().isEmpty) ? "El nombre es obligatorio" : null,
              ),
              const SizedBox(height: 10),
              TextFormField(
                controller: cedulaCtrl,
                keyboardType: TextInputType.number,
                decoration: const InputDecoration(labelText: "Cédula", prefixIcon: Icon(Icons.badge_outlined)),
              ),
              const SizedBox(height: 10),
              TextFormField(
                controller: correoCtrl,
                keyboardType: TextInputType.emailAddress,
                decoration: const InputDecoration(labelText: "Correo / Usuario *", prefixIcon: Icon(Icons.email_outlined)),
                validator: (v) {
                  if (v == null || v.trim().isEmpty) return "El correo es obligatorio";
                  final emailRegex = RegExp(r'^[^@\s]+@[^@\s]+\.[^@\s]+$');
                  if (!emailRegex.hasMatch(v.trim())) return "Ingrese un correo válido";
                  return null;
                },
              ),
              const SizedBox(height: 10),
              TextFormField(
                controller: claveCtrl,
                obscureText: !verClave,
                decoration: InputDecoration(
                  labelText: "Contraseña *",
                  prefixIcon: const Icon(Icons.lock_outline),
                  suffixIcon: IconButton(
                    icon: Icon(verClave ? Icons.visibility_off_outlined : Icons.visibility_outlined),
                    onPressed: () => setS(() => verClave = !verClave),
                  ),
                ),
                validator: (v) {
                  if (v == null || v.isEmpty) return "La contraseña es obligatoria";
                  if (v.length < 4) return "La contraseña debe tener al menos 4 caracteres";
                  return null;
                },
              ),
              const SizedBox(height: 10),
              TextFormField(
                controller: sueldoCtrl,
                keyboardType: const TextInputType.numberWithOptions(decimal: true),
                decoration: const InputDecoration(labelText: "Sueldo base (\$)", prefixIcon: Icon(Icons.attach_money)),
              ),
              const SizedBox(height: 10),
              DropdownButtonFormField<String>(
                value: rol,
                items: ["Dueño","Administrador","Gerente","Encargado","Activador","Vendedor"]
                    .map((e) => DropdownMenuItem(value: e, child: Text(e))).toList(),
                onChanged: (v) { if (v != null) setS(() => rol = v); },
                decoration: const InputDecoration(labelText: "Rol / Permisos", prefixIcon: Icon(Icons.security_outlined)),
              ),
              const SizedBox(height: 6),
              // ── Toggle "Gana comisiones" (Fase 3) ──
              SwitchListTile(
                contentPadding: EdgeInsets.zero,
                title: const Text("Gana comisiones",
                    style: TextStyle(fontSize: 14,
                        fontWeight: FontWeight.w600)),
                subtitle: const Text(
                    "Si está apagado, este usuario NO aparece en el reporte de comisiones",
                    style: TextStyle(fontSize: 11)),
                value: ganaComisiones,
                onChanged: (v) => setS(() => ganaComisiones = v),
                activeThumbColor: AppColors.royalBlue,
              ),
              // ── Tienda al iniciar sesión ─────────────────────────
              // Ya no se asigna al usuario una tienda fija. El usuario
              // elige la ubicación cada vez que inicia sesión.
              const SizedBox(height: 10),
              Container(
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(
                  color: AppColors.surfaceTintBlue,
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(
                      color: AppColors.brandBlue.withValues(alpha: 0.2)),
                ),
                child: Row(children: const [
                  Icon(Icons.info_outline,
                      size: 16, color: AppColors.brandBlue),
                  SizedBox(width: 8),
                  Expanded(child: Text(
                    "La tienda se selecciona al iniciar sesión.",
                    style: TextStyle(fontSize: 12,
                        color: AppColors.textPrimary))),
                ]),
              ),
            ]),
          ),
        ),
        actions: [
          TextButton(child: const Text("Cancelar"), onPressed: () => Navigator.pop(ctx)),
          ElevatedButton.icon(
            icon: guardando
              ? const SizedBox(width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
              : const Icon(Icons.save_outlined, size: 18),
            label: const Text("Guardar"),
            onPressed: guardando ? null : () async {
              if (!formKey.currentState!.validate()) return;
              setS(() => guardando = true);
              try {
                if (usuario.id == null) throw Exception('Usuario sin ID');
                  await _Api.put('usuarios', usuario.id!.toString(), {
                  'nombre': nombreCtrl.text.trim(),
                  'cedula': cedulaCtrl.text.trim(),
                  'correo': correoCtrl.text.trim(),
                  'clave': claveCtrl.text.trim(),
                  'rol': rol,
                  'sueldo_base': double.tryParse(sueldoCtrl.text) ?? 0,
                  // tienda queda vacía — se asigna al iniciar sesión
                  'tienda': '',
                  'gana_comisiones': ganaComisiones ? 1 : 0,
                });
                if (!ctx.mounted) return;
                Navigator.pop(ctx);
                await _cargar();
                if (mounted) ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(content: Text("Usuario actualizado correctamente"), backgroundColor: AppColors.statusGreen));
              } catch (e) {
                setS(() => guardando = false);
                if (ctx.mounted) ScaffoldMessenger.of(context).showSnackBar(
                  SnackBar(content: Text('Error: $e'), backgroundColor: AppColors.statusRed));
              }
            },
          ),
        ],
      ),
    ));
  }

  void _crearUsuario() {
    final correoCtrl = TextEditingController();
    final claveCtrl = TextEditingController();
    final confirmarClaveCtrl = TextEditingController();
    final nombreCtrl = TextEditingController();
    final cedulaCtrl = TextEditingController();
    final sueldoCtrl = TextEditingController(text: "0");
    String rol = "Vendedor";
    bool ganaComisiones = true;
    bool verClave = false;
    bool guardando = false;
    final formKey = GlobalKey<FormState>();

    showDialog(context: context, builder: (ctx) => StatefulBuilder(
      builder: (_, setS) => AlertDialog(
        title: const Row(children: [
          Icon(Icons.person_add_outlined, color: AppColors.royalBlue),
          SizedBox(width: 8),
          Text("Nuevo Usuario"),
