            ...cuenta.pagos.asMap().entries.map((entry) {
              final i = entry.key;
              final pago = entry.value;
              return Card(
                  margin: const EdgeInsets.only(bottom: 6),
                  shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(10)),
                  elevation: 1,
                  child: ListTile(
                    leading: const CircleAvatar(
                        backgroundColor: Color(0xFFE8F5E9),
                        child: Icon(Icons.payment_outlined,
                            color: AppColors.statusGreen, size: 20)),
                    title: Text(
                        formatCurrency(
                            double.tryParse(pago['monto'].toString()) ?? 0),
                        style: const TextStyle(
                            fontWeight: FontWeight.bold,
                            color: AppColors.statusGreen)),
                    subtitle: Text(
                        "${pago['metodo']} · ${pago['fecha']}"
                        // Datos del pago móvil (ref, cédula, teléfono).
                        "${datosPagoMovilTexto(pago).isEmpty ? '' : '\n${datosPagoMovilTexto(pago)}'}",
                        style: const TextStyle(
                            fontSize: 12, color: AppColors.textSecondary)),
                    // Botón eliminar por abono (solo Admin/Dueño/Gerente)
                    trailing: puedeGestionar
                        ? IconButton(
                            icon: const Icon(Icons.delete_outline,
                                color: AppColors.statusRed, size: 20),
                            tooltip: 'Eliminar abono',
                            onPressed: () => _eliminarAbono(i),
                          )
                        : null,
                  ),
              );
            }),
          const SizedBox(height: 80),
        ]),
      ),
      floatingActionButton: puedeEditar && !saldado
          ? FloatingActionButton.extended(
              onPressed: _registrarPago,
              icon: const Icon(Icons.attach_money),
              label: const Text("Registrar Pago"),
            )
          : null,
    );
  }

  /// Marca una cuota individual como pagada
  void _pagarCuota(CuotaCobrar cuota) {
    if (widget.cuenta.id == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text("Error: cuenta sin ID. Recargue la pantalla."),
          backgroundColor: AppColors.statusRed));
      return;
    }
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Row(children: [
          const Icon(Icons.check_circle_outline, color: AppColors.statusGreen),
          const SizedBox(width: 8),
          Text("Pagar Cuota ${cuota.numero}"),
        ]),
        content: Column(mainAxisSize: MainAxisSize.min, children: [
          ListTile(
            contentPadding: EdgeInsets.zero,
            leading: const Icon(Icons.attach_money, color: AppColors.statusGreen),
            title: Text("Monto: ${formatCurrency(cuota.monto)}",
                style: const TextStyle(fontWeight: FontWeight.bold)),
            subtitle: Text("Vencimiento: ${cuota.fecha}"),
          ),
          const Text("¿Confirma que esta cuota fue pagada hoy?"),
        ]),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text("Cancelar")),
          ElevatedButton.icon(
            icon: const Icon(Icons.check, size: 16),
            label: const Text("Confirmar pago"),
            style: ElevatedButton.styleFrom(backgroundColor: AppColors.statusGreen),
            onPressed: () async {
              Navigator.pop(ctx);
              try {
                final fechaHoy = obtenerFechaActual();
                await _Api.put('cuentas_cobrar', widget.cuenta.id.toString(), {
                  'cuota_pagada': {
                    'numero': cuota.numero,
                    'fecha_pago': fechaHoy,
                  }
                });
                if (!mounted) return;
                setState(() {
                  cuota.pagada = true;
                  cuota.fechaPago = fechaHoy;
                });
                ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                  content: Text(
                      "Cuota ${cuota.numero} marcada como pagada (${formatCurrency(cuota.monto)})"),
                  backgroundColor: AppColors.statusGreen));
              } catch (e) {
                if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                    content: Text("Error al registrar pago de cuota: $e"),
                    backgroundColor: AppColors.statusRed));
              }
            },
          ),
        ],
      ),
    );
  }

  Widget _infoRow(IconData icon, String label, String value) => Padding(
    padding: const EdgeInsets.symmetric(vertical: 3),
    child: Row(children: [
      Icon(icon, size: 16, color: AppColors.textSecondary),
      const SizedBox(width: 6),
      Text("$label: ", style: const TextStyle(color: AppColors.textSecondary, fontSize: 13)),
      Text(value, style: const TextStyle(fontWeight: FontWeight.w500, fontSize: 13)),
    ]),
  );
}

// ============================================================
//  CUENTAS POR PAGAR — carga desde la API
// ============================================================
// ════════════════════════════════════════════════════════════
//  AGREGAR DEUDA A UNA CUENTA POR PAGAR
// ════════════════════════════════════════════════════════════
//  Cuando llega una factura nueva de un proveedor al que ya se le
//  debe, no se crea otra cuenta: se le suma a la que ya tiene. Y si
//  ese proveedor venía con saldo a favor (se le pagó de más antes),
//  el sistema pregunta si esa factura se cancela con el saldo.
//
//  Lo usan las DOS pantallas de cuentas por pagar (empleados y
//  proveedores), que trabajan con modelos distintos pero con la misma
//  aritmética, así que el cálculo y el diálogo viven acá una sola vez.
// ════════════════════════════════════════════════════════════

/// Lo que hay que guardar después de agregar una factura.
class ResultadoAgregarDeuda {
  /// Monto de la factura que se agregó.
  final double monto;
  /// Cuánto del saldo a favor se aplicó a esta factura.
  final double aplicadoDeFavor;
  /// Nuevo `monto_total` de la cuenta.
  final double nuevoMontoTotal;
  /// Nuevo saldo a favor que queda apartado para la próxima compra.
  final double nuevoFavorApartado;
  /// Texto que escribió el usuario (puede ir vacío).
  final String concepto;

  const ResultadoAgregarDeuda({
    required this.monto,
    required this.aplicadoDeFavor,
    required this.nuevoMontoTotal,
    required this.nuevoFavorApartado,
    required this.concepto,
  });

  /// Lo que queda pendiente de ESTA factura después de aplicar el
  /// saldo a favor.
  double get pendienteDeEstaFactura => monto - aplicadoDeFavor;
}

/// Calcula cómo queda la cuenta al agregarle una factura de [monto].
///
/// [pagado] es todo lo que se le pagó al acreedor (abonos + cuotas
/// pagadas) y [favorApartado] la parte del saldo a favor que en una
/// operación anterior se decidió NO usar.
///
/// El saldo a favor disponible tiene dos partes: la que se ve sola
/// (haber pagado de más) y la que quedó apartada. Al aplicarlo, la
/// primera se consume sola con sólo aumentar la deuda; la segunda hay
/// que descontarla a mano. Al NO aplicarlo, la parte suelta se aparta
/// para que la factura nueva quede pendiente por su valor completo.
ResultadoAgregarDeuda calcularAgregarDeuda({
  required double montoTotal,
  required double pagado,
  required double favorApartado,
  required double monto,
  required bool usarFavor,
  String concepto = '',
}) {
  final favorSuelto =
      (pagado - montoTotal - favorApartado).clamp(0.0, double.infinity);
  final favorDisponible = favorSuelto + favorApartado;

  double aplicado;
  double nuevoApartado;
  if (usarFavor && favorDisponible > 0.001) {
    aplicado = math.min(favorDisponible, monto);
    // Del saldo apartado sólo se toca lo que la factura no alcanzó a
    // cubrir con la parte suelta.
    final delApartado =
        math.max(0.0, math.min(favorApartado, monto - favorSuelto));
    nuevoApartado = favorApartado - delApartado;
  } else {
    aplicado = 0;
    nuevoApartado = favorApartado + favorSuelto;
  }

  return ResultadoAgregarDeuda(
    monto: monto,
    aplicadoDeFavor: aplicado,
    nuevoMontoTotal: montoTotal + monto,
    nuevoFavorApartado: nuevoApartado,
    concepto: concepto,
  );
}

/// Abre el diálogo "Agregar deuda". Devuelve null si el usuario
/// cancela o si el monto no es válido.
Future<ResultadoAgregarDeuda?> pedirAgregarDeuda(
  BuildContext context, {
  required String nombreAcreedor,
  required double montoTotal,
  required double pagado,
  required double favorApartado,
  required double saldoFavor,
}) {
  final ctrlMonto = TextEditingController();
  final ctrlConcepto = TextEditingController();
  // Por defecto SÍ se usa el saldo a favor: es lo que casi siempre
  // se quiere y evita que quede plata "olvidada" con el proveedor.
  bool usarFavor = true;
  final hayFavor = saldoFavor > 0.001;

  return showDialog<ResultadoAgregarDeuda>(
    context: context,
    builder: (ctx) => StatefulBuilder(builder: (ctx, setS) {
      final monto =
          double.tryParse(ctrlMonto.text.trim().replaceAll(',', '.')) ?? 0;
      final previa = monto > 0
          ? calcularAgregarDeuda(
              montoTotal: montoTotal,
              pagado: pagado,
              favorApartado: favorApartado,
              monto: monto,
              usarFavor: usarFavor)
          : null;

      return AlertDialog(
        title: const Row(children: [
          Icon(Icons.add_shopping_cart, color: AppColors.statusOrange),
          SizedBox(width: 8),
          Expanded(child: Text('Agregar deuda')),
        ]),
        content: SingleChildScrollView(
          child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(nombreAcreedor,
                    style: const TextStyle(
                        fontWeight: FontWeight.bold, fontSize: 14)),
                Text('Deuda actual: ${formatCurrency(montoTotal)}',
                    style: const TextStyle(
                        fontSize: 12, color: AppColors.textSecondary)),
                const SizedBox(height: 14),
                TextField(
                  controller: ctrlMonto,
                  autofocus: true,
                  keyboardType:
                      const TextInputType.numberWithOptions(decimal: true),
                  decoration: const InputDecoration(
                    labelText: 'Monto de la factura (\$)',
                    prefixIcon: Icon(Icons.attach_money),
                    border: OutlineInputBorder(),
                  ),
                  onChanged: (_) => setS(() {}),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: ctrlConcepto,
                  maxLines: 2,
                  decoration: const InputDecoration(
                    labelText: 'Concepto (opcional)',
                    hintText: 'Ej: Factura 00123, mercancía del 03/09',
                    prefixIcon: Icon(Icons.notes),
                    border: OutlineInputBorder(),
                  ),
                ),
                // ── Pregunta por el saldo a favor ──────────────
                if (hayFavor) ...[
                  const SizedBox(height: 14),
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(12),
                    decoration: BoxDecoration(
                      color: AppColors.statusGreen.withValues(alpha: 0.09),
                      borderRadius: BorderRadius.circular(10),
                      border: Border.all(
                          color:
                              AppColors.statusGreen.withValues(alpha: 0.4)),
                    ),
                    child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Row(children: [
                            const Icon(Icons.savings,
                                color: AppColors.statusGreen, size: 20),
                            const SizedBox(width: 8),
                            Expanded(
                              child: Text(
                                'Tenés ${formatCurrency(saldoFavor)} a favor '
                                'con $nombreAcreedor.',
                                style: const TextStyle(
                                    fontSize: 12,
                                    fontWeight: FontWeight.w600),
                              ),
                            ),
                          ]),
                          const SizedBox(height: 6),
                          const Text(
                              '¿Querés usarlo en esta factura?',
                              style: TextStyle(fontSize: 12)),
                          const SizedBox(height: 8),
                          Row(children: [
                            Expanded(
                              child: ChoiceChip(
                                label: const Text('Sí, descontarlo',
                                    style: TextStyle(fontSize: 12)),
                                selected: usarFavor,
                                selectedColor: AppColors.statusGreen
                                    .withValues(alpha: 0.25),
                                onSelected: (_) =>
                                    setS(() => usarFavor = true),
                              ),
                            ),
                            const SizedBox(width: 8),
                            Expanded(
                              child: ChoiceChip(
                                label: const Text('No, guardarlo',
                                    style: TextStyle(fontSize: 12)),
                                selected: !usarFavor,
                                selectedColor: AppColors.statusOrange
                                    .withValues(alpha: 0.25),
                                onSelected: (_) =>
                                    setS(() => usarFavor = false),
                              ),
                            ),
                          ]),
                        ]),
                  ),
                ],
                // ── Cómo queda ────────────────────────────────
                if (previa != null) ...[
                  const SizedBox(height: 14),
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(12),
                    decoration: BoxDecoration(
                      color: AppColors.surfaceGrey,
                      borderRadius: BorderRadius.circular(10),
                    ),
                    child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          const Text('Cómo queda',
                              style: TextStyle(
                                  fontSize: 11,
                                  letterSpacing: 0.5,
                                  fontWeight: FontWeight.bold,
                                  color: AppColors.textSecondary)),
                          const SizedBox(height: 6),
                          _filaResumenDeuda(
                              'Factura', formatCurrency(previa.monto)),
                          if (previa.aplicadoDeFavor > 0.001)
                            _filaResumenDeuda(
                                'Saldo a favor aplicado',
                                '− ${formatCurrency(previa.aplicadoDeFavor)}',
                                color: AppColors.statusGreen),
                          const Divider(height: 12),
                          _filaResumenDeuda(
                              'Pendiente de esta factura',
                              formatCurrency(previa.pendienteDeEstaFactura),
                              negrita: true),
                          if (previa.nuevoFavorApartado > 0.001)
                            _filaResumenDeuda(
                                'Queda a favor',
                                formatCurrency(previa.nuevoFavorApartado),
                                color: AppColors.statusGreen),
                        ]),
                  ),
                ],
              ]),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text('Cancelar')),
          ElevatedButton.icon(
            icon: const Icon(Icons.check, size: 18),
            label: const Text('Agregar'),
            style: ElevatedButton.styleFrom(
                backgroundColor: AppColors.statusOrange,
                foregroundColor: Colors.white),
            onPressed: previa == null
                ? null
                : () => Navigator.pop(
                    ctx,
                    calcularAgregarDeuda(
                      montoTotal: montoTotal,
                      pagado: pagado,
                      favorApartado: favorApartado,
                      monto: previa.monto,
                      usarFavor: usarFavor,
                      concepto: ctrlConcepto.text.trim(),
                    )),
          ),
        ],
      );
    }),
  );
}

Widget _filaResumenDeuda(String etiqueta, String valor,
        {Color? color, bool negrita = false}) =>
    Padding(
      padding: const EdgeInsets.symmetric(vertical: 2),
      child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
        Text(etiqueta,
            style: TextStyle(
                fontSize: 12,
                color: color ?? AppColors.textSecondary,
                fontWeight: negrita ? FontWeight.w600 : FontWeight.normal)),
        Text(valor,
            style: TextStyle(
                fontSize: negrita ? 14 : 12,
                color: color ?? AppColors.textPrimary,
                fontWeight: negrita ? FontWeight.bold : FontWeight.w600)),
      ]),
    );

/// Arma la línea de bitácora que se agrega a las notas de la cuenta
/// cada vez que se le suma una factura, para poder reconstruir de
/// dónde salió cada aumento.
String lineaNotaAumento(ResultadoAgregarDeuda r) {
  final buf = StringBuffer('[${obtenerFechaActual()}] '
      '+${formatCurrency(r.monto)}');
  if (r.concepto.isNotEmpty) buf.write(' — ${r.concepto}');
  if (r.aplicadoDeFavor > 0.001) {
    buf.write(' (aplicado ${formatCurrency(r.aplicadoDeFavor)} '
        'de saldo a favor)');
  }
  return buf.toString();
}

class VentanaCuentasPorPagar extends StatefulWidget {
  const VentanaCuentasPorPagar({super.key});
  @override State<VentanaCuentasPorPagar> createState() => _VentanaCuentasPorPagarState();
}

class _VentanaCuentasPorPagarState extends State<VentanaCuentasPorPagar> {
  List<CuentaPorPagar> _cuentas = [];
  bool _cargando = true;
  String _query = '';
  bool get puedeEditar => (usuarioSesion?.rol == "Administrador" || usuarioSesion?.rol == "Maestro" || usuarioSesion?.rol == "Dueño");

  @override
  void initState() { super.initState(); _cargar(); }

  Future<void> _cargar() async {
    setState(() => _cargando = true);
    try {
      final raw = await _Api.get('cuentas_pagar');
      _cuentas = ((raw as List?) ?? []).map((m) => CuentaPorPagar.fromMap(m)).toList();
      _cuentas.sort((a, b) => b.saldoRestante.compareTo(a.saldoRestante));
      cuentasPorPagarGlobal = _cuentas;
    } catch (e) {
      debugPrint('[_cargar] Error: $e');
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Error al cargar datos: $e'), backgroundColor: AppColors.statusRed, duration: const Duration(seconds: 4)));
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  List<CuentaPorPagar> get _filtradas => _cuentas.where((c) =>
    _query.isEmpty ||
    c.nombre.toLowerCase().contains(_query.toLowerCase()) ||
    c.rif.contains(_query)).toList();

  void _crearCuenta() {
    final rifCtrl   = TextEditingController();
    final nomCtrl   = TextEditingController();
    final telCtrl   = TextEditingController();
    final corCtrl   = TextEditingController();
    final deudaCtrl = TextEditingController();
    final notasCtrl = TextEditingController();
    final formKey   = GlobalKey<FormState>();
    bool guardando  = false;
    bool usarCuotas = false;
    int  numCuotas  = 1;
    List<List<TextEditingController>> cuotasCtrl = [
      [TextEditingController(), TextEditingController()],
    ];

    late void Function(void Function(void Function()), int) actualizarCuotas;
    actualizarCuotas = (setS, nuevaCant) {
      setS(() {
        numCuotas = nuevaCant.clamp(1, 60);
        while (cuotasCtrl.length < numCuotas) {
          cuotasCtrl.add([TextEditingController(), TextEditingController()]);
        }
        while (cuotasCtrl.length > numCuotas) {
          for (final c in cuotasCtrl.last) c.dispose();
          cuotasCtrl.removeLast();
        }
        final total = double.tryParse(deudaCtrl.text.trim()) ?? 0;
        if (total > 0) {
          final porCuota = (total / numCuotas).toStringAsFixed(2);
          for (final par in cuotasCtrl) par[0].text = porCuota;
        }
      });
    };

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(20))),
      builder: (ctx) => StatefulBuilder(
        builder: (context, setS) => DraggableScrollableSheet(
          initialChildSize: 0.92,
          minChildSize: 0.5,
          maxChildSize: 0.97,
          expand: false,
          builder: (_, scrollCtrl) => Padding(
            padding: EdgeInsets.only(
                bottom: MediaQuery.of(ctx).viewInsets.bottom,
                left: 24, right: 24, top: 20),
            child: Form(
              key: formKey,
              child: ListView(
                controller: scrollCtrl,
                children: [
                  Row(children: [
                    const Icon(Icons.request_quote_outlined, color: AppColors.royalBlue),
                    const SizedBox(width: 8),
                    const Text("Nueva Cuenta por Pagar",
                        style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
                    const Spacer(),
                    IconButton(icon: const Icon(Icons.close), onPressed: () => Navigator.pop(ctx)),
                  ]),
                  const Divider(),
                  const SizedBox(height: 8),
                  const Text("Datos del proveedor / acreedor",
                      style: TextStyle(fontWeight: FontWeight.w600, color: AppColors.royalBlue, fontSize: 13)),
                  const SizedBox(height: 10),
                  TextFormField(
                    controller: rifCtrl,
                    textCapitalization: TextCapitalization.characters,
                    textInputAction: TextInputAction.next,
                    decoration: const InputDecoration(labelText: "RIF / Documento *", prefixIcon: Icon(Icons.receipt_outlined)),
                    validator: (v) => (v?.trim().isEmpty ?? true) ? "El RIF es obligatorio" : null,
                  ),
                  const SizedBox(height: 10),
                  TextFormField(
                    controller: nomCtrl,
                    textCapitalization: TextCapitalization.words,
                    textInputAction: TextInputAction.next,
                    decoration: const InputDecoration(labelText: "Proveedor / Nombre *", prefixIcon: Icon(Icons.business_outlined)),
                    validator: (v) => (v?.trim().isEmpty ?? true) ? "El nombre es obligatorio" : null,
                  ),
                  const SizedBox(height: 10),
                  Row(children: [
                    Expanded(child: TextFormField(
                      controller: telCtrl,
                      keyboardType: TextInputType.phone,
                      textInputAction: TextInputAction.next,
                      decoration: const InputDecoration(labelText: "Teléfono", prefixIcon: Icon(Icons.phone_outlined)),
                    )),
                    const SizedBox(width: 10),
                    Expanded(child: TextFormField(
                      controller: corCtrl,
                      keyboardType: TextInputType.emailAddress,
                      textInputAction: TextInputAction.next,
                      decoration: const InputDecoration(labelText: "Correo", prefixIcon: Icon(Icons.email_outlined)),
                    )),
                  ]),
                  const SizedBox(height: 10),
                  TextFormField(
                    controller: deudaCtrl,
                    keyboardType: const TextInputType.numberWithOptions(decimal: true),
                    textInputAction: TextInputAction.next,
                    decoration: const InputDecoration(
                        labelText: "Monto total *",
                        prefixIcon: Icon(Icons.attach_money),
                        ),
                    onChanged: (_) { if (usarCuotas) actualizarCuotas(setS, numCuotas); },
                    validator: (v) {
                      final d = double.tryParse(v?.trim() ?? '');
                      return (d == null || d <= 0) ? "Ingrese un monto válido mayor a 0" : null;
                    },
                  ),
                  const SizedBox(height: 10),
                  TextFormField(
                    controller: notasCtrl,
                    maxLines: 2,
                    textInputAction: TextInputAction.done,
                    decoration: const InputDecoration(labelText: "Notas / concepto", prefixIcon: Icon(Icons.notes_outlined)),
                  ),
                  const SizedBox(height: 18),
                  // ── Sección Cuotas ──────────────────────────
                  Container(
                    decoration: BoxDecoration(
                      color: AppColors.surfaceGrey,
                      borderRadius: BorderRadius.circular(12),
                      border: Border.all(color: AppColors.cardBorder),
                    ),
                    child: Column(children: [
                      SwitchListTile(
                        value: usarCuotas,
                        onChanged: (v) => setS(() => usarCuotas = v),
                        title: const Text("Dividir en cuotas", style: TextStyle(fontWeight: FontWeight.w600)),
                        subtitle: const Text("Define número, fecha y monto de cada cuota", style: TextStyle(fontSize: 11)),
                        secondary: const Icon(Icons.calendar_month_outlined, color: AppColors.royalBlue),
                        activeColor: AppColors.royalBlue,
                      ),
                      if (usarCuotas) ...[
                        const Divider(height: 1),
                        Padding(
                          padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
                          child: Row(children: [
                            const Text("Número de cuotas:", style: TextStyle(fontWeight: FontWeight.w500)),
                            const Spacer(),
                            IconButton(
                              icon: const Icon(Icons.remove_circle_outline, color: AppColors.statusRed),
                              onPressed: () => actualizarCuotas(setS, numCuotas - 1),
                            ),
                            Container(width: 40, alignment: Alignment.center,
                              child: Text("$numCuotas", style: const TextStyle(fontSize: 20, fontWeight: FontWeight.bold))),
                            IconButton(
                              icon: const Icon(Icons.add_circle_outline, color: AppColors.statusGreen),
                              onPressed: () => actualizarCuotas(setS, numCuotas + 1),
                            ),
                          ]),
                        ),
                        Padding(
                          padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
                          child: Column(
                            children: List.generate(numCuotas, (i) {
                              final mc = cuotasCtrl[i][0];
                              final fc = cuotasCtrl[i][1];
                              return Padding(
                                padding: const EdgeInsets.only(bottom: 10),
                                child: Row(children: [
                                  Container(
                                    width: 28, height: 28,
                                    decoration: const BoxDecoration(color: AppColors.royalBlue, shape: BoxShape.circle),
                                    child: Center(child: Text("${i + 1}",
                                        style: const TextStyle(color: Colors.white, fontSize: 12, fontWeight: FontWeight.bold))),
                                  ),
                                  const SizedBox(width: 8),
                                  Expanded(flex: 2, child: TextFormField(
                                    controller: mc,
                                    keyboardType: const TextInputType.numberWithOptions(decimal: true),
                                    decoration: InputDecoration(
                                        labelText: "Monto", isDense: true, 
                                        border: OutlineInputBorder(borderRadius: BorderRadius.circular(8))),
                                    validator: (v) {
                                      if (!usarCuotas) return null;
                                      final d = double.tryParse(v?.trim() ?? '');
                                      return (d == null || d <= 0) ? "Requerido" : null;
                                    },
                                  )),
                                  const SizedBox(width: 8),
                                  Expanded(flex: 3, child: TextFormField(
                                    controller: fc,
                                    readOnly: true,
                                    decoration: InputDecoration(
                                        labelText: "Fecha venc.", isDense: true,
                                        prefixIcon: const Icon(Icons.event_outlined, size: 16),
                                        border: OutlineInputBorder(borderRadius: BorderRadius.circular(8))),
                                    onTap: () async {
                                      final picked = await showDatePicker(
                                        context: context,
                                        initialDate: DateTime.now().add(Duration(days: 30 * (i + 1))),
                                        firstDate: DateTime.now().subtract(const Duration(days: 1)),
                                        lastDate: DateTime.now().add(const Duration(days: 1825)),
                                      );
                                      if (picked != null) {
                                        setS(() => fc.text =
                                            "${picked.day.toString().padLeft(2, '0')}/${picked.month.toString().padLeft(2, '0')}/${picked.year}");
                                      }
                                    },
                                    validator: (v) {
                                      if (!usarCuotas) return null;
                                      return (v == null || v.trim().isEmpty) ? "Requerida" : null;
                                    },
                                  )),
                                ]),
                              );
                            }),
                          ),
                        ),
                        // Resumen suma
                        Padding(
                          padding: const EdgeInsets.fromLTRB(16, 0, 16, 12),
                          child: Builder(builder: (_) {
                            final suma = cuotasCtrl.fold(0.0, (s, p) => s + (double.tryParse(p[0].text.trim()) ?? 0));
                            final total = double.tryParse(deudaCtrl.text.trim()) ?? 0;
                            final ok = (total - suma).abs() < 0.01;
                            return Container(
                              padding: const EdgeInsets.all(10),
                              decoration: BoxDecoration(
                                color: (ok ? AppColors.statusGreen : AppColors.statusOrange).withValues(alpha: 0.08),
                                borderRadius: BorderRadius.circular(8),
                                border: Border.all(color: ok ? AppColors.statusGreen : AppColors.statusOrange, width: 0.8),
                              ),
                              child: Row(children: [
                                Icon(ok ? Icons.check_circle_outline : Icons.info_outline,
                                    size: 16, color: ok ? AppColors.statusGreen : AppColors.statusOrange),
                                const SizedBox(width: 6),
                                Expanded(child: Text(
                                  ok ? "Total cuotas: ${formatCurrency(suma)} ✓"
                                      : "Total cuotas: ${formatCurrency(suma)}  (diferencia: ${formatCurrency((total - suma).abs())})",
                                  style: TextStyle(fontSize: 12, color: ok ? AppColors.statusGreen : AppColors.statusOrange),
                                )),
                              ]),
                            );
                          }),
                        ),
                      ],
                    ]),
                  ),
                  const SizedBox(height: 20),
                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton.icon(
                      icon: guardando
                          ? const SizedBox(width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                          : const Icon(Icons.save_outlined),
                      label: const Text("Crear Cuenta"),
                      style: ElevatedButton.styleFrom(
                          backgroundColor: AppColors.royalBlue,
                          padding: const EdgeInsets.symmetric(vertical: 14),
                          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10))),
                      onPressed: guardando ? null : () async {
                        if (!formKey.currentState!.validate()) return;
                        if (usarCuotas) {
                          final suma = cuotasCtrl.fold(0.0, (s, p) => s + (double.tryParse(p[0].text.trim()) ?? 0));
                          final total = double.tryParse(deudaCtrl.text.trim()) ?? 0;
                          if ((total - suma).abs() >= 0.01) {
                            ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
                              content: Text("La suma de cuotas no coincide con el total"),
                              backgroundColor: AppColors.statusOrange));
                            return;
                          }
                        }
                        setS(() => guardando = true);
                        try {
                          final cuotas = usarCuotas
                              ? List.generate(numCuotas, (i) => {
                                    'numero': i + 1,
                                    'monto': double.tryParse(cuotasCtrl[i][0].text.trim()) ?? 0,
                                    'fecha': cuotasCtrl[i][1].text.trim(),
                                    'pagada': false,
                                  })
                              : <Map<String, dynamic>>[];
                          await _Api.post('cuentas_pagar', {
                            'rif': rifCtrl.text.trim(),
                            'nombre': nomCtrl.text.trim(),
                            'telefono': telCtrl.text.trim(),
                            'correo': corCtrl.text.trim(),
                            'monto_total': double.tryParse(deudaCtrl.text.trim()) ?? 0,
                            'notas': notasCtrl.text.trim(),
                            'cuotas': cuotas,
                          });
                          if (!mounted) return;
                          Navigator.pop(ctx);
                          await _cargar();
                          if (mounted) ScaffoldMessenger.of(context).showSnackBar(
                              const SnackBar(content: Text("Cuenta por pagar creada exitosamente"), backgroundColor: AppColors.statusGreen));
                        } catch (e) {
                          setS(() => guardando = false);
                          if (mounted) ScaffoldMessenger.of(context).showSnackBar(
                              SnackBar(content: Text("Error: $e"), backgroundColor: AppColors.statusRed));
                        }
                      },
                    ),
                  ),
                  const SizedBox(height: 24),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final filtradas = _filtradas;
    final totalPendiente = filtradas.fold(0.0, (s, c) => s + c.saldoRestante);
    return Scaffold(
      appBar: AppBar(
        title: const Text("Cuentas por Pagar"),
        actions: [IconButton(icon: const Icon(Icons.refresh), tooltip: "Actualizar", onPressed: _cargar)],
      ),
      body: Column(children: [
        Container(
          width: double.infinity,
          padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 14),
          color: AppColors.statusRed,
          child: Row(children: [
            Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              const Text("TOTAL POR PAGAR", style: TextStyle(color: Colors.white70, fontSize: 11, letterSpacing: 1)),
              Text(formatCurrency(totalPendiente),
                style: const TextStyle(color: Colors.white, fontSize: 28, fontWeight: FontWeight.bold)),
            ]),
            const Spacer(),
            Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
              const Text("Cuentas", style: TextStyle(color: Colors.white70, fontSize: 11)),
              Text("${filtradas.length}", style: const TextStyle(color: Colors.white, fontSize: 22, fontWeight: FontWeight.bold)),
            ]),
          ]),
        ),
        Padding(
          padding: const EdgeInsets.all(12),
          child: TextField(
            decoration: InputDecoration(
              hintText: "Buscar por nombre o RIF...",
              prefixIcon: const Icon(Icons.search, color: AppColors.primaryBlue),
              filled: true, fillColor: Colors.white,
              border: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: BorderSide.none),
              contentPadding: const EdgeInsets.symmetric(vertical: 0, horizontal: 16),
            ),
            onChanged: (v) => setState(() => _query = v),
          ),
        ),
        if (_cargando)
          const Expanded(child: Center(child: CircularProgressIndicator()))
        else if (filtradas.isEmpty)
          const Expanded(child: EmptyState(mensaje: "No hay cuentas por pagar.", icono: Icons.request_quote_outlined))
        else
          Expanded(child: RefreshIndicator(
            onRefresh: _cargar,
            child: ListView.builder(
              padding: const EdgeInsets.symmetric(horizontal: 12),
              itemCount: filtradas.length,
              itemBuilder: (c, i) {
                final cuenta = filtradas[i];
                final pct = cuenta.montoTotal > 0
                    ? (1 - cuenta.saldoRestante / cuenta.montoTotal).clamp(0.0, 1.0)
                    : 1.0;
                final saldado = cuenta.saldoRestante <= 0;
                return Card(
                  margin: const EdgeInsets.only(bottom: 8),
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                  elevation: 1,
                  child: InkWell(
                    borderRadius: BorderRadius.circular(12),
                    onTap: () => Navigator.push(context,
                      MaterialPageRoute(builder: (_) => DetalleCuentaPorPagar(cuenta: cuenta)))
                      .then((_) => _cargar()),
                    child: Padding(
                      padding: const EdgeInsets.all(14),
                      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                        Row(children: [
                          CircleAvatar(
                            radius: 20,
                            backgroundColor: (saldado ? AppColors.statusGreen : AppColors.statusRed).withValues(alpha: 0.12),
                            child: Icon(Icons.business_outlined, size: 18,
                              color: saldado ? AppColors.statusGreen : AppColors.statusRed),
                          ),
                          const SizedBox(width: 10),
                          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                            // El saldo a favor va pegado al nombre: es
                            // lo primero que hay que ver antes de
                            // pagarle otra factura a este acreedor.
                            Row(children: [
                              Flexible(
                                child: Text(cuenta.nombre,
                                    overflow: TextOverflow.ellipsis,
                                    style: const TextStyle(
                                        fontWeight: FontWeight.w600)),
                              ),
                              ChipSaldoFavor(saldoFavor: cuenta.saldoFavor),
                            ]),
                            Text("RIF: ${cuenta.rif}", style: const TextStyle(fontSize: 12, color: AppColors.textSecondary)),
                          ])),
                          Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
                            Text(formatCurrency(cuenta.saldoRestante),
                              style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16,
                                color: saldado ? AppColors.statusGreen : AppColors.statusRed)),
                            Text("de ${formatCurrency(cuenta.montoTotal)}",
                              style: const TextStyle(fontSize: 11, color: AppColors.textSecondary)),
                          ]),
                        ]),
                        const SizedBox(height: 10),
                        ClipRRect(
                          borderRadius: BorderRadius.circular(4),
                          child: LinearProgressIndicator(
                            value: pct, minHeight: 5,
                            backgroundColor: Colors.grey[200],
                            valueColor: AlwaysStoppedAnimation<Color>(
                              saldado ? AppColors.statusGreen : (pct > 0.5 ? AppColors.statusOrange : AppColors.statusRed)),
                          ),
                        ),
                        const SizedBox(height: 4),
                        Row(children: [
                          Text("${(pct * 100).toStringAsFixed(0)}% pagado",
                            style: const TextStyle(fontSize: 11, color: AppColors.textSecondary)),
                          const Spacer(),
                          if (cuenta.proximaCuota != null)
                            Container(
                              padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 2),
                              decoration: BoxDecoration(
                                color: AppColors.statusOrange.withValues(alpha: 0.1),
                                borderRadius: BorderRadius.circular(8),
                                border: Border.all(color: AppColors.statusOrange.withValues(alpha: 0.4), width: 0.7),
                              ),
                              child: Row(mainAxisSize: MainAxisSize.min, children: [
                                const Icon(Icons.event_outlined, size: 11, color: AppColors.statusOrange),
                                const SizedBox(width: 3),
                                Text(
                                  "Cuota ${cuenta.proximaCuota!.numero}: ${formatCurrency(cuenta.proximaCuota!.monto)} · ${cuenta.proximaCuota!.fecha}",
                                  style: const TextStyle(fontSize: 10, color: AppColors.statusOrange),
                                ),
                              ]),
                            )
                          else if (cuenta.cuotas.isNotEmpty && saldado)
                            const Text("Todas las cuotas pagadas ✓",
                              style: TextStyle(fontSize: 11, color: AppColors.statusGreen)),
                        ]),
                      ]),
                    ),
                  ),
                );
              },
            ),
          )),
      ]),
      floatingActionButton: puedeEditar
          ? FloatingActionButton.extended(
              onPressed: _crearCuenta,
              icon: const Icon(Icons.add),
              label: const Text("Nueva Cuenta"),
            )
          : null,
    );
  }
}

class DetalleCuentaPorPagar extends StatefulWidget {
  final CuentaPorPagar cuenta;
  const DetalleCuentaPorPagar({super.key, required this.cuenta});
  @override State<DetalleCuentaPorPagar> createState() => _DetalleCuentaPorPagarState();
}

class _DetalleCuentaPorPagarState extends State<DetalleCuentaPorPagar> {
  bool get puedeEditar => (usuarioSesion?.rol == "Administrador" || usuarioSesion?.rol == "Maestro" || usuarioSesion?.rol == "Dueño");

  /// Le suma una factura nueva a la cuenta que ya existe, en vez de
  /// abrir otra cuenta para el mismo acreedor.
  ///
  /// Si tiene saldo a favor el diálogo pregunta si se usa en esta
  /// factura; si la respuesta es que sí, el descuento lo hace el
  /// sistema. Si es que no, el saldo queda apartado para la próxima.
  Future<void> _agregarDeuda() async {
    final cuenta = widget.cuenta;
    final res = await pedirAgregarDeuda(
      context,
      nombreAcreedor: cuenta.nombre,
      montoTotal    : cuenta.montoTotal,
      pagado        : cuenta.totalPagado + cuenta.totalCuotasPagadas,
      favorApartado : cuenta.favorApartado,
      saldoFavor    : cuenta.saldoFavor,
    );
    if (res == null || !mounted) return;
    if (cuenta.id == null) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text("La cuenta no tiene ID: no se puede actualizar"),
        backgroundColor: AppColors.statusRed));
      return;
    }
    // Guardamos el estado anterior para poder revertir si el servidor
    // rechaza el cambio; si no, la pantalla quedaría mostrando una
    // deuda que en la base no existe.
    final montoAnterior  = cuenta.montoTotal;
    final notasAnteriores = cuenta.notas;
    final visibles = cuenta.notasVisibles;
    final linea = lineaNotaAumento(res);
    cuenta.montoTotal = res.nuevoMontoTotal;
    cuenta.notas = visibles.isEmpty ? linea : '$visibles\n$linea';
    cuenta.favorApartado = res.nuevoFavorApartado;
    try {
      await _Api.put('cuentas_pagar', cuenta.id!.toString(), cuenta.toMap());
      if (!mounted) return;
      setState(() {});
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(res.aplicadoDeFavor > 0.001
            ? "Deuda agregada. Se aplicaron "
              "${formatCurrency(res.aplicadoDeFavor)} de saldo a favor; "
              "quedan ${formatCurrency(res.pendienteDeEstaFactura)} "
              "pendientes de esta factura."
            : "Deuda de ${formatCurrency(res.monto)} agregada."),
        backgroundColor: AppColors.statusGreen,
        duration: const Duration(seconds: 6)));
    } catch (e) {
      cuenta.montoTotal = montoAnterior;
      cuenta.notas      = notasAnteriores;
      if (!mounted) return;
      setState(() {});
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text("No se pudo guardar el aumento: $e"),
        backgroundColor: AppColors.statusRed));
    }
  }

  void _registrarPago() {
    final montoController = TextEditingController();
    final tasaController = TextEditingController(
      text: ConfigSistema.tasaCambio.toStringAsFixed(2));
    String metodo = "Efectivo \$";
    final formKey = GlobalKey<FormState>();

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(20))),
      builder: (c) => StatefulBuilder(
        builder: (ctx, setLocal) {
          // Métodos en Bs según el helper común. Antes era comparación exacta
          // y "Pago Móvil" / "Punto de venta" (los de la configuración) no
          // pedían tasa: el monto en Bs se guardaba como si fueran $.
          final requiereTasa = esMetodoEnBolivares(metodo);
          return Padding(
            padding: EdgeInsets.only(
              bottom: MediaQuery.of(ctx).viewInsets.bottom,
              left: 24, right: 24, top: 24),
            child: Form(key: formKey, child: Column(mainAxisSize: MainAxisSize.min, children: [
              const Text("Registrar Pago", style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
              const SizedBox(height: 16),
              DropdownButtonFormField<String>(
                value: metodo,
                decoration: const InputDecoration(labelText: "Método de pago", prefixIcon: Icon(Icons.payment_outlined)),
                items: ConfigSistema.metodossPago
                    .map((e) => DropdownMenuItem(value: e, child: Text(e))).toList(),
                onChanged: (v) => setLocal(() => metodo = v!),
              ),
              const SizedBox(height: 12),
              TextFormField(
                controller: montoController,
                keyboardType: const TextInputType.numberWithOptions(decimal: true),
                decoration: InputDecoration(
                  labelText: requiereTasa ? "Monto en Bolívares (Bs)" : "Monto en Dólares (\$)",
                  prefixIcon: const Icon(Icons.attach_money)),
                validator: (v) {
                  final d = double.tryParse(v?.trim() ?? '');
                  return (d == null || d <= 0) ? "Ingrese un monto válido" : null;
                },
              ),
              if (requiereTasa) ...[
                const SizedBox(height: 12),
                TextFormField(
                  controller: tasaController,
                  keyboardType: const TextInputType.numberWithOptions(decimal: true),
                  decoration: const InputDecoration(
                    labelText: "Tasa de cambio (Bs/\$)",
                    prefixIcon: Icon(Icons.currency_exchange),
                    helperText: "Tasa BCV cargada automáticamente"),
                  validator: (v) {
                    final d = double.tryParse(v?.trim() ?? '');
                    return (d == null || d <= 0) ? "Ingrese una tasa válida" : null;
                  },
                ),
              ],
              const SizedBox(height: 20),
              SizedBox(width: double.infinity, child: ElevatedButton(
                onPressed: () async {
                  if (!formKey.currentState!.validate()) return;
                  // Tolerar coma decimal (formato venezolano)
                  final montoRaw = double.tryParse(
                    montoController.text.trim().replaceAll(',', '.')) ?? 0;
                  final tasaNum = double.tryParse(
                    tasaController.text.trim().replaceAll(',', '.')) ?? 0;
                  if (montoRaw <= 0) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(content: Text('Monto inválido'),
                        backgroundColor: AppColors.statusRed));
                    return;
                  }
                  if (requiereTasa && tasaNum <= 0) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(content: Text('Tasa inválida'),
                        backgroundColor: AppColors.statusRed));
                    return;
                  }
                  double montoFinal = requiereTasa
                    ? montoRaw / tasaNum
                    : montoRaw;
                  try {
                    if (widget.cuenta.id == null) throw Exception('Cuenta sin ID');
                    final nuevoPago = {
                      'monto': montoFinal,
                      'fecha': obtenerFechaActual(),
                      'metodo': metodo,
                    };
                    // Enviamos estado completo para garantizar persistencia
                    final pagosActualizados = [
                      ...widget.cuenta.pagos.map((p) => Map<String, dynamic>.from(p)),
                      nuevoPago,
                    ];
                    final payload = <String, dynamic>{
                      ...widget.cuenta.toMap(),
                      'pago': nuevoPago,
                      'pagos': pagosActualizados,
                    };
                    await _Api.put('cuentas_pagar', widget.cuenta.id!.toString(), payload);
                    if (!mounted) return;
                    setState(() {
                      widget.cuenta.pagos.add(nuevoPago);
                    });
                    Navigator.pop(ctx);
                    // Si el pago superó la deuda, avisamos del excedente
                    // en vez de dejarlo pasar en silencio.
                    final favor = widget.cuenta.saldoFavor;
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                        content: Text(favor > 0.001
                            ? "Pago de ${formatCurrency(montoFinal)} registrado. "
                              "Quedan ${formatCurrency(favor)} a favor."
                            : "Pago de ${formatCurrency(montoFinal)} registrado"),
                        duration: Duration(seconds: favor > 0.001 ? 6 : 4),
                        backgroundColor: AppColors.statusGreen));
                  } catch (e) {
                    if (!mounted) return;
                    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text("Error: $e")));
                  }
                },
                child: const Text("Registrar Pago"),
              )),
              const SizedBox(height: 16),
            ])),
          );
        },
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final cuenta = widget.cuenta;
    final pct = cuenta.montoTotal > 0
        ? (1 - cuenta.saldoRestante / cuenta.montoTotal).clamp(0.0, 1.0)
        : 1.0;
    final saldado = cuenta.saldoRestante <= 0;
    final tieneCuotas = cuenta.cuotas.isNotEmpty;
    final cuotasPendientes = cuenta.cuotas.where((c) => !c.pagada).length;
    return Scaffold(
      appBar: AppBar(
        title: Text(cuenta.nombre),
        actions: [
          if (puedeEditar)
            IconButton(
              icon: const Icon(Icons.add_shopping_cart),
              tooltip: "Agregar deuda (factura nueva)",
              onPressed: _agregarDeuda),
        ],
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Card(
            shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Row(children: [
                  const Icon(Icons.business_outlined, color: AppColors.royalBlue),
                  const SizedBox(width: 8),
                  Expanded(child: Text(cuenta.nombre,
                      style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 16))),
                  if (saldado)
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                      decoration: BoxDecoration(color: AppColors.statusGreen.withValues(alpha: 0.12), borderRadius: BorderRadius.circular(20)),
                      child: const Text("SALDADO", style: TextStyle(fontSize: 11, fontWeight: FontWeight.bold, color: AppColors.statusGreen)),
                    ),
                ]),
                const Divider(height: 20),
                _iRow(Icons.receipt_outlined, "RIF", cuenta.rif),
                _iRow(Icons.phone_outlined, "Teléfono", cuenta.telefono),
                if (cuenta.correo.isNotEmpty) _iRow(Icons.email_outlined, "Correo", cuenta.correo),
                if (cuenta.notasVisibles.isNotEmpty)
                  _iRow(Icons.notes_outlined, "Notas", cuenta.notasVisibles),
                const SizedBox(height: 12),
                Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
                  Text("Deuda total: ${formatCurrency(cuenta.montoTotal)}",
                      style: const TextStyle(color: AppColors.textSecondary, fontSize: 13)),
                  Text("${(pct * 100).toStringAsFixed(0)}% pagado",
                      style: const TextStyle(color: AppColors.textSecondary, fontSize: 13)),
                ]),
                const SizedBox(height: 6),
                ClipRRect(
                  borderRadius: BorderRadius.circular(6),
                  child: LinearProgressIndicator(
                    value: pct, minHeight: 10,
                    backgroundColor: Colors.grey[200],
                    valueColor: AlwaysStoppedAnimation<Color>(saldado ? AppColors.statusGreen : AppColors.statusRed),
                  ),
                ),
                const SizedBox(height: 12),
                Container(
                  width: double.infinity,
                  padding: const EdgeInsets.all(12),
                  decoration: BoxDecoration(
                    color: (saldado ? AppColors.statusGreen : AppColors.statusRed).withValues(alpha: 0.08),
                    borderRadius: BorderRadius.circular(10),
                  ),
                  child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
                    Text("SALDO RESTANTE", style: TextStyle(
                        color: saldado ? AppColors.statusGreen : AppColors.statusRed,
                        fontWeight: FontWeight.w600, fontSize: 12, letterSpacing: 0.5)),
                    Text(formatCurrency(cuenta.saldoRestante), style: TextStyle(
                        color: saldado ? AppColors.statusGreen : AppColors.statusRed,
                        fontWeight: FontWeight.bold, fontSize: 22)),
                  ]),
                ),
                // Si se pagó de más, el excedente queda acá a la vista.
                BannerSaldoFavor(
                  saldoFavor: cuenta.saldoFavor,
                  nota: 'Pagaste de más. Queda a favor con este acreedor.',
                ),
              ]),
            ),
          ),
          const SizedBox(height: 16),
          // ── Cuotas ───────────────────────────────────────
          if (tieneCuotas) ...[
            Row(children: [
              const Text("Plan de Cuotas", style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
              const SizedBox(width: 8),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
                decoration: BoxDecoration(
                    color: AppColors.primaryBlue.withValues(alpha: 0.1), borderRadius: BorderRadius.circular(10)),
                child: Text("$cuotasPendientes pendiente${cuotasPendientes != 1 ? 's' : ''}",
                    style: const TextStyle(fontSize: 11, color: AppColors.primaryBlue, fontWeight: FontWeight.w600)),
              ),
            ]),
            const SizedBox(height: 8),
            ...cuenta.cuotas.map((cuota) => Card(
              margin: const EdgeInsets.only(bottom: 8),
              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
              elevation: 1,
              child: ListTile(
                contentPadding: const EdgeInsets.symmetric(horizontal: 14, vertical: 6),
                leading: Container(
                  width: 36, height: 36,
                  decoration: BoxDecoration(
                    color: (cuota.pagada ? AppColors.statusGreen : AppColors.statusOrange).withValues(alpha: 0.12),
                    shape: BoxShape.circle,
                  ),
                  child: Center(child: Text("${cuota.numero}", style: TextStyle(
                      fontWeight: FontWeight.bold,
                      color: cuota.pagada ? AppColors.statusGreen : AppColors.statusOrange))),
                ),
                title: Row(children: [
                  Text(formatCurrency(cuota.monto), style: TextStyle(
                      fontWeight: FontWeight.bold, fontSize: 15,
                      color: cuota.pagada ? AppColors.statusGreen : AppColors.textPrimary)),
                  const Spacer(),
                  if (cuota.pagada)
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
                      decoration: BoxDecoration(color: AppColors.statusGreen.withValues(alpha: 0.1), borderRadius: BorderRadius.circular(8)),
                      child: const Text("Pagada", style: TextStyle(fontSize: 11, color: AppColors.statusGreen, fontWeight: FontWeight.w600)),
                    )
                  else if (puedeEditar)
                    TextButton.icon(
                      icon: const Icon(Icons.check_circle_outline, size: 16),
                      label: const Text("Pagar", style: TextStyle(fontSize: 12)),
                      style: TextButton.styleFrom(
                          foregroundColor: AppColors.statusGreen,
                          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                          minimumSize: Size.zero, tapTargetSize: MaterialTapTargetSize.shrinkWrap),
                      onPressed: () => _pagarCuota(cuota),
                    ),
                ]),
                subtitle: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Row(children: [
                    const Icon(Icons.event_outlined, size: 12, color: AppColors.textSecondary),
                    const SizedBox(width: 4),
                    Text("Vence: ${cuota.fecha}", style: const TextStyle(fontSize: 11, color: AppColors.textSecondary)),
                  ]),
                  if (cuota.pagada && cuota.fechaPago != null)
                    Row(children: [
                      const Icon(Icons.check_outlined, size: 12, color: AppColors.statusGreen),
                      const SizedBox(width: 4),
                      Text("Pagada el: ${cuota.fechaPago}", style: const TextStyle(fontSize: 11, color: AppColors.statusGreen)),
                    ]),
                ]),
              ),
            )),
            const SizedBox(height: 16),
          ],
          // ── Historial de pagos libres ─────────────────────
          const Text("Historial de Pagos", style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
          const SizedBox(height: 8),
          if (cuenta.pagos.isEmpty && !tieneCuotas)
            const EmptyState(mensaje: "Sin pagos registrados aún.", icono: Icons.payment_outlined)
          else if (cuenta.pagos.isEmpty)
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 8),
              child: Text("Sin abonos adicionales registrados.",
                  style: const TextStyle(fontSize: 13, color: AppColors.textSecondary)),
            )
          else
            ...cuenta.pagos.map((pago) => Card(
              margin: const EdgeInsets.only(bottom: 6),
              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
              elevation: 1,
              child: ListTile(
                leading: const CircleAvatar(
                    backgroundColor: Color(0xFFE8F5E9),
                    child: Icon(Icons.payment_outlined, color: AppColors.statusGreen, size: 20)),
                title: Text(formatCurrency(double.tryParse(pago['monto'].toString()) ?? 0),
                    style: const TextStyle(fontWeight: FontWeight.bold, color: AppColors.statusGreen)),
                subtitle: Text("${pago['metodo']} · ${pago['fecha']}",
                    style: const TextStyle(fontSize: 12, color: AppColors.textSecondary)),
              ),
            )),
          const SizedBox(height: 80),
        ]),
      ),
      floatingActionButton: puedeEditar && !saldado
          ? FloatingActionButton.extended(
              onPressed: _registrarPago,
              icon: const Icon(Icons.attach_money),
              label: const Text("Registrar Pago"),
            )
          : null,
    );
  }

  void _pagarCuota(CuotaCobrar cuota) {
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Row(children: [
          const Icon(Icons.check_circle_outline, color: AppColors.statusGreen),
          const SizedBox(width: 8),
          Text("Pagar Cuota ${cuota.numero}"),
        ]),
        content: Column(mainAxisSize: MainAxisSize.min, children: [
          ListTile(
            contentPadding: EdgeInsets.zero,
            leading: const Icon(Icons.attach_money, color: AppColors.statusGreen),
            title: Text("Monto: ${formatCurrency(cuota.monto)}", style: const TextStyle(fontWeight: FontWeight.bold)),
            subtitle: Text("Vencimiento: ${cuota.fecha}"),
          ),
          const Text("¿Confirma que esta cuota fue pagada hoy?"),
        ]),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text("Cancelar")),
          ElevatedButton.icon(
            icon: const Icon(Icons.check, size: 16),
            label: const Text("Confirmar pago"),
            style: ElevatedButton.styleFrom(backgroundColor: AppColors.statusGreen),
            onPressed: () async {
              Navigator.pop(ctx);
              try {
                final fechaHoy = obtenerFechaActual();
                if (widget.cuenta.id == null) throw Exception('Cuenta sin ID');
                    await _Api.put('cuentas_pagar', widget.cuenta.id!.toString(), {
                  'cuota_pagada': {'numero': cuota.numero, 'fecha_pago': fechaHoy}
                });
                if (!mounted) return;
                setState(() { cuota.pagada = true; cuota.fechaPago = fechaHoy; });
                ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                    content: Text("Cuota ${cuota.numero} pagada (${formatCurrency(cuota.monto)})"),
                    backgroundColor: AppColors.statusGreen));
              } catch (e) {
                if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                    content: Text("Error: $e"), backgroundColor: AppColors.statusRed));
              }
            },
          ),
        ],
      ),
    );
  }

  Widget _iRow(IconData icon, String label, String value) => Padding(
    padding: const EdgeInsets.symmetric(vertical: 3),
    child: Row(children: [
      Icon(icon, size: 16, color: AppColors.textSecondary),
      const SizedBox(width: 6),
      Text("$label: ", style: const TextStyle(color: AppColors.textSecondary, fontSize: 13)),
      Expanded(child: Text(value, style: const TextStyle(fontWeight: FontWeight.w500, fontSize: 13))),
    ]),
  );
}

// ============================================================
//  CUENTAS POR PAGAR PROVEEDOR
// ============================================================
class VentanaCuentasPorPagarProveedor extends StatefulWidget {
  const VentanaCuentasPorPagarProveedor({super.key});
  @override State<VentanaCuentasPorPagarProveedor> createState() => _VentanaCuentasPorPagarProveedorState();
}

class _VentanaCuentasPorPagarProveedorState extends State<VentanaCuentasPorPagarProveedor> {
  List<CuentaPorPagarProveedor> _cuentas = [];
  bool _cargando = true;
  bool get puedeEditar => (usuarioSesion?.rol == "Administrador" || usuarioSesion?.rol == "Maestro" || usuarioSesion?.rol == "Dueño");

  @override
  void initState() { super.initState(); _cargar(); }

  Future<void> _cargar() async {
    setState(() => _cargando = true);
    try {
      final raw = await _Api.get('cuentas_pagar_proveedor');
      _cuentas = ((raw as List?) ?? []).map((m) => CuentaPorPagarProveedor.fromMap(m)).toList();
      cuentasPorPagarProveedorGlobal = _cuentas;
    } catch (e) {
      debugPrint('[_cargar] Error: $e');
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Error al cargar datos: $e'), backgroundColor: AppColors.statusRed, duration: const Duration(seconds: 4)));
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  void _crearCuenta() {
    final rifCtrl         = TextEditingController();
    final nomCtrl         = TextEditingController();
    final telCtrl         = TextEditingController();
    final corCtrl         = TextEditingController();
    final deudaCtrl       = TextEditingController();
    final fechaLimiteCtrl = TextEditingController();
    final formKey         = GlobalKey<FormState>();
    bool guardando        = false;
    bool usarCuotas       = false;
    int  numCuotas        = 1;
    List<List<TextEditingController>> cuotasCtrl = [
      [TextEditingController(), TextEditingController()],
    ];

    late void Function(void Function(void Function()), int) actualizarCuotas;
    actualizarCuotas = (setS, nuevaCant) {
      setS(() {
        numCuotas = nuevaCant.clamp(1, 60);
        while (cuotasCtrl.length < numCuotas) {
          cuotasCtrl.add([TextEditingController(), TextEditingController()]);
        }
        while (cuotasCtrl.length > numCuotas) {
          for (final c in cuotasCtrl.last) c.dispose();
          cuotasCtrl.removeLast();
        }
        final total = double.tryParse(deudaCtrl.text.trim()) ?? 0;
        if (total > 0) {
          final porCuota = (total / numCuotas).toStringAsFixed(2);
          for (final par in cuotasCtrl) par[0].text = porCuota;
        }
      });
    };

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(20))),
      builder: (ctx) => StatefulBuilder(
        builder: (context, setS) => DraggableScrollableSheet(
          initialChildSize: 0.92,
          minChildSize: 0.5,
          maxChildSize: 0.97,
          expand: false,
          builder: (_, scrollCtrl) => Padding(
            padding: EdgeInsets.only(
                bottom: MediaQuery.of(ctx).viewInsets.bottom,
                left: 24, right: 24, top: 20),
            child: Form(
              key: formKey,
              child: ListView(
                controller: scrollCtrl,
                children: [
                  Row(children: [
                    const Icon(Icons.business_center, color: AppColors.royalBlue),
                    const SizedBox(width: 8),
                    const Text("Nueva CxP Proveedor",
                        style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
                    const Spacer(),
                    IconButton(icon: const Icon(Icons.close), onPressed: () => Navigator.pop(ctx)),
                  ]),
                  const Divider(),
                  const SizedBox(height: 8),
                  const Text("Datos del proveedor",
                      style: TextStyle(fontWeight: FontWeight.w600, color: AppColors.royalBlue, fontSize: 13)),
                  const SizedBox(height: 10),
                  TextFormField(
                    controller: rifCtrl,
                    textCapitalization: TextCapitalization.characters,
                    textInputAction: TextInputAction.next,
                    decoration: const InputDecoration(labelText: "RIF *", prefixIcon: Icon(Icons.receipt_outlined)),
                    validator: (v) => (v?.trim().isEmpty ?? true) ? "El RIF es obligatorio" : null,
                  ),
                  const SizedBox(height: 10),
                  TextFormField(
                    controller: nomCtrl,
                    textCapitalization: TextCapitalization.words,
                    textInputAction: TextInputAction.next,
                    decoration: const InputDecoration(labelText: "Nombre proveedor *", prefixIcon: Icon(Icons.business_outlined)),
                    validator: (v) => (v?.trim().isEmpty ?? true) ? "El nombre es obligatorio" : null,
                  ),
                  const SizedBox(height: 10),
                  Row(children: [
                    Expanded(child: TextFormField(
                      controller: telCtrl,
                      keyboardType: TextInputType.phone,
                      textInputAction: TextInputAction.next,
                      decoration: const InputDecoration(labelText: "Teléfono", prefixIcon: Icon(Icons.phone_outlined)),
                    )),
                    const SizedBox(width: 10),
                    Expanded(child: TextFormField(
                      controller: corCtrl,
                      keyboardType: TextInputType.emailAddress,
                      textInputAction: TextInputAction.next,
                      decoration: const InputDecoration(labelText: "Correo", prefixIcon: Icon(Icons.email_outlined)),
                    )),
                  ]),
                  const SizedBox(height: 10),
                  TextFormField(
                    controller: deudaCtrl,
                    keyboardType: const TextInputType.numberWithOptions(decimal: true),
                    textInputAction: TextInputAction.next,
                    decoration: const InputDecoration(
                        labelText: "Monto total *",
                        prefixIcon: Icon(Icons.attach_money),
                        ),
                    onChanged: (_) { if (usarCuotas) actualizarCuotas(setS, numCuotas); },
                    validator: (v) {
                      final d = double.tryParse(v?.trim() ?? '');
                      return (d == null || d <= 0) ? "Ingrese un monto válido" : null;
                    },
                  ),
                  const SizedBox(height: 10),
                  TextFormField(
                    controller: fechaLimiteCtrl,
                    readOnly: true,
                    decoration: const InputDecoration(
                        labelText: "Fecha límite *",
                        prefixIcon: Icon(Icons.event_outlined)),
                    onTap: () async {
                      final picked = await showDatePicker(
                        context: context,
                        initialDate: DateTime.now().add(const Duration(days: 30)),
                        firstDate: DateTime.now(),
                        lastDate: DateTime.now().add(const Duration(days: 1825)),
                      );
                      if (picked != null) {
                        setS(() => fechaLimiteCtrl.text =
                            "${picked.day.toString().padLeft(2, '0')}/${picked.month.toString().padLeft(2, '0')}/${picked.year}");
                      }
                    },
                    validator: (v) => (v == null || v.trim().isEmpty) ? "Ingrese la fecha límite" : null,
                  ),
                  const SizedBox(height: 18),
                  // ── Sección Cuotas ──────────────────────────
                  Container(
                    decoration: BoxDecoration(
                      color: AppColors.surfaceGrey,
                      borderRadius: BorderRadius.circular(12),
                      border: Border.all(color: AppColors.cardBorder),
                    ),
                    child: Column(children: [
                      SwitchListTile(
                        value: usarCuotas,
                        onChanged: (v) => setS(() => usarCuotas = v),
                        title: const Text("Dividir en cuotas", style: TextStyle(fontWeight: FontWeight.w600)),
                        subtitle: const Text("Define número, fecha y monto de cada cuota", style: TextStyle(fontSize: 11)),
                        secondary: const Icon(Icons.calendar_month_outlined, color: AppColors.royalBlue),
                        activeColor: AppColors.royalBlue,
                      ),
                      if (usarCuotas) ...[
                        const Divider(height: 1),
                        Padding(
                          padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
                          child: Row(children: [
                            const Text("Número de cuotas:", style: TextStyle(fontWeight: FontWeight.w500)),
                            const Spacer(),
                            IconButton(
                              icon: const Icon(Icons.remove_circle_outline, color: AppColors.statusRed),
                              onPressed: () => actualizarCuotas(setS, numCuotas - 1),
                            ),
                            Container(width: 40, alignment: Alignment.center,
                              child: Text("$numCuotas", style: const TextStyle(fontSize: 20, fontWeight: FontWeight.bold))),
                            IconButton(
                              icon: const Icon(Icons.add_circle_outline, color: AppColors.statusGreen),
                              onPressed: () => actualizarCuotas(setS, numCuotas + 1),
                            ),
                          ]),
                        ),
                        Padding(
                          padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
                          child: Column(
                            children: List.generate(numCuotas, (i) {
                              final mc = cuotasCtrl[i][0];
                              final fc = cuotasCtrl[i][1];
                              return Padding(
                                padding: const EdgeInsets.only(bottom: 10),
                                child: Row(children: [
                                  Container(
                                    width: 28, height: 28,
                                    decoration: const BoxDecoration(color: AppColors.royalBlue, shape: BoxShape.circle),
                                    child: Center(child: Text("${i + 1}",
                                        style: const TextStyle(color: Colors.white, fontSize: 12, fontWeight: FontWeight.bold))),
                                  ),
                                  const SizedBox(width: 8),
                                  Expanded(flex: 2, child: TextFormField(
                                    controller: mc,
                                    keyboardType: const TextInputType.numberWithOptions(decimal: true),
                                    decoration: InputDecoration(
                                        labelText: "Monto", isDense: true, 
                                        border: OutlineInputBorder(borderRadius: BorderRadius.circular(8))),
                                    validator: (v) {
                                      if (!usarCuotas) return null;
                                      final d = double.tryParse(v?.trim() ?? '');
                                      return (d == null || d <= 0) ? "Requerido" : null;
                                    },
                                  )),
                                  const SizedBox(width: 8),
                                  Expanded(flex: 3, child: TextFormField(
                                    controller: fc,
                                    readOnly: true,
                                    decoration: InputDecoration(
                                        labelText: "Fecha venc.", isDense: true,
                                        prefixIcon: const Icon(Icons.event_outlined, size: 16),
                                        border: OutlineInputBorder(borderRadius: BorderRadius.circular(8))),
                                    onTap: () async {
                                      final picked = await showDatePicker(
                                        context: context,
                                        initialDate: DateTime.now().add(Duration(days: 30 * (i + 1))),
                                        firstDate: DateTime.now().subtract(const Duration(days: 1)),
                                        lastDate: DateTime.now().add(const Duration(days: 1825)),
                                      );
                                      if (picked != null) {
                                        setS(() => fc.text =
                                            "${picked.day.toString().padLeft(2, '0')}/${picked.month.toString().padLeft(2, '0')}/${picked.year}");
                                      }
                                    },
                                    validator: (v) {
                                      if (!usarCuotas) return null;
                                      return (v == null || v.trim().isEmpty) ? "Requerida" : null;
                                    },
                                  )),
                                ]),
                              );
                            }),
                          ),
                        ),
                        Padding(
                          padding: const EdgeInsets.fromLTRB(16, 0, 16, 12),
                          child: Builder(builder: (_) {
                            final suma = cuotasCtrl.fold(0.0, (s, p) => s + (double.tryParse(p[0].text.trim()) ?? 0));
                            final total = double.tryParse(deudaCtrl.text.trim()) ?? 0;
                            final ok = (total - suma).abs() < 0.01;
                            return Container(
                              padding: const EdgeInsets.all(10),
                              decoration: BoxDecoration(
                                color: (ok ? AppColors.statusGreen : AppColors.statusOrange).withValues(alpha: 0.08),
                                borderRadius: BorderRadius.circular(8),
                                border: Border.all(color: ok ? AppColors.statusGreen : AppColors.statusOrange, width: 0.8),
                              ),
                              child: Row(children: [
                                Icon(ok ? Icons.check_circle_outline : Icons.info_outline,
                                    size: 16, color: ok ? AppColors.statusGreen : AppColors.statusOrange),
                                const SizedBox(width: 6),
                                Expanded(child: Text(
                                  ok ? "Total cuotas: ${formatCurrency(suma)} ✓"
                                      : "Total cuotas: ${formatCurrency(suma)}  (diferencia: ${formatCurrency((total - suma).abs())})",
                                  style: TextStyle(fontSize: 12, color: ok ? AppColors.statusGreen : AppColors.statusOrange),
                                )),
                              ]),
                            );
                          }),
                        ),
                      ],
                    ]),
                  ),
                  const SizedBox(height: 20),
                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton.icon(
                      icon: guardando
                          ? const SizedBox(width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                          : const Icon(Icons.save_outlined),
                      label: const Text("Crear Cuenta"),
                      style: ElevatedButton.styleFrom(
                          backgroundColor: AppColors.royalBlue,
                          padding: const EdgeInsets.symmetric(vertical: 14),
                          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10))),
                      onPressed: guardando ? null : () async {
                        if (!formKey.currentState!.validate()) return;
                        if (usarCuotas) {
                          final suma = cuotasCtrl.fold(0.0, (s, p) => s + (double.tryParse(p[0].text.trim()) ?? 0));
                          final total = double.tryParse(deudaCtrl.text.trim()) ?? 0;
                          if ((total - suma).abs() >= 0.01) {
                            ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
                              content: Text("La suma de cuotas no coincide con el total"),
                              backgroundColor: AppColors.statusOrange));
                            return;
                          }
                        }
                        setS(() => guardando = true);
                        try {
                          final cuotas = usarCuotas
                              ? List.generate(numCuotas, (i) => {
                                    'numero': i + 1,
                                    'monto': double.tryParse(cuotasCtrl[i][0].text.trim()) ?? 0,
                                    'fecha': cuotasCtrl[i][1].text.trim(),
                                    'pagada': false,
                                  })
                              : <Map<String, dynamic>>[];
                          await _Api.post('cuentas_pagar_proveedor', {
                            'rif': rifCtrl.text.trim(),
                            'nombre': nomCtrl.text.trim(),
                            'telefono': telCtrl.text.trim(),
                            'correo': corCtrl.text.trim(),
                            'monto_total': double.tryParse(deudaCtrl.text) ?? 0,
                            'fecha_limite': fechaLimiteCtrl.text.trim(),
                            'cuotas': cuotas,
                          });
                          if (!ctx.mounted) return;
                          Navigator.pop(ctx);
                          await _cargar();
                          if (mounted) ScaffoldMessenger.of(context).showSnackBar(
                              const SnackBar(content: Text("Cuenta creada exitosamente"), backgroundColor: AppColors.statusGreen));
                        } catch (e) {
                          setS(() => guardando = false);
                          if (ctx.mounted) ScaffoldMessenger.of(context).showSnackBar(
                              SnackBar(content: Text("Error: $e"), backgroundColor: AppColors.statusRed));
                        }
                      },
                    ),
                  ),
                  const SizedBox(height: 24),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final total = _cuentas.fold(0.0, (sum, c) => sum + c.saldoRestante);
    final vencidas = _cuentas.where((c) => c.saldoRestante > 0).length;

    return Scaffold(
      appBar: AppBar(
        title: const Text("CxP Proveedores"),
        actions: [IconButton(icon: const Icon(Icons.refresh), tooltip: "Actualizar", onPressed: _cargar)],
      ),
      body: Column(children: [
        // Header con estadísticas
        Container(
          width: double.infinity,
          padding: const EdgeInsets.fromLTRB(20, 16, 20, 20),
          decoration: const BoxDecoration(
            gradient: LinearGradient(
              colors: [AppColors.royalBlue, Color(0xFF003580)],
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
            ),
          ),
          child: Row(children: [
            Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              const Text("TOTAL POR PAGAR", style: TextStyle(color: Colors.white60, fontSize: 11, letterSpacing: 1)),
              const SizedBox(height: 4),
              Text(formatCurrency(total),
                style: const TextStyle(color: Colors.white, fontSize: 28, fontWeight: FontWeight.bold)),
            ])),
            Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                decoration: BoxDecoration(
                  color: Colors.white.withValues(alpha: 0.15),
                  borderRadius: BorderRadius.circular(20),
                ),
                child: Text("$vencidas pendientes",
                  style: const TextStyle(color: Colors.white, fontSize: 12, fontWeight: FontWeight.w600)),
              ),
            ]),
          ]),
        ),
        if (_cargando)
          const Expanded(child: Center(child: CircularProgressIndicator()))
        else if (_cuentas.isEmpty)
          const Expanded(child: EmptyState(mensaje: "No hay cuentas por pagar registradas.", icono: Icons.business_outlined))
        else
          Expanded(child: RefreshIndicator(
            onRefresh: _cargar,
            child: ListView.builder(
              padding: const EdgeInsets.all(12),
              itemCount: _cuentas.length,
              itemBuilder: (c, i) {
                final cuenta = _cuentas[i];
                final saldado = cuenta.saldoRestante <= 0;
                final pct = cuenta.montoTotal > 0
                  ? (1 - cuenta.saldoRestante / cuenta.montoTotal).clamp(0.0, 1.0)
                  : 1.0;
                return Card(
                  margin: const EdgeInsets.only(bottom: 8),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(12),
                    side: saldado
                      ? const BorderSide(color: AppColors.statusGreen, width: 1)
                      : BorderSide.none,
                  ),
                  child: InkWell(
                    borderRadius: BorderRadius.circular(12),
                    onTap: () => Navigator.push(context,
                      MaterialPageRoute(builder: (_) => DetalleCuentaProveedor(cuenta: cuenta)))
                      .then((_) => _cargar()),
                    child: Padding(
                      padding: const EdgeInsets.all(14),
                      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                        Row(children: [
                          Container(
                            padding: const EdgeInsets.all(8),
                            decoration: BoxDecoration(
                              color: (saldado ? AppColors.statusGreen : AppColors.statusRed).withValues(alpha: 0.1),
                              borderRadius: BorderRadius.circular(8),
                            ),
                            child: Icon(Icons.business_outlined,
                              color: saldado ? AppColors.statusGreen : AppColors.statusRed, size: 20),
                          ),
                          const SizedBox(width: 10),
                          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                            // Igual que en cuentas por pagar: el saldo
                            // a favor del proveedor, al lado del nombre.
                            Row(children: [
                              Flexible(
                                child: Text(cuenta.nombre,
                                    overflow: TextOverflow.ellipsis,
                                    style: const TextStyle(
                                        fontWeight: FontWeight.w600,
                                        fontSize: 14)),
                              ),
                              ChipSaldoFavor(saldoFavor: cuenta.saldoFavor),
                            ]),
                            Text("RIF: ${cuenta.rif} · Vence: ${cuenta.fechaLimite}",
                              style: const TextStyle(fontSize: 11, color: AppColors.textSecondary)),
                          ])),
                          Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
                            Text(formatCurrency(cuenta.saldoRestante),
                              style: TextStyle(
                                fontWeight: FontWeight.bold, fontSize: 15,
                                color: saldado ? AppColors.statusGreen : AppColors.statusRed)),
                            Text(saldado ? "SALDADO" : "PENDIENTE",
                              style: TextStyle(
                                fontSize: 9, fontWeight: FontWeight.bold, letterSpacing: 0.5,
                                color: saldado ? AppColors.statusGreen : AppColors.statusRed)),
                          ]),
                        ]),
                        const SizedBox(height: 10),
                        ClipRRect(
                          borderRadius: BorderRadius.circular(4),
                          child: LinearProgressIndicator(
                            value: pct, minHeight: 6,
                            backgroundColor: Colors.grey[200],
                            valueColor: AlwaysStoppedAnimation<Color>(
                              saldado ? AppColors.statusGreen : AppColors.primaryBlue),
                          ),
                        ),
                        const SizedBox(height: 4),
                        Row(children: [
                          Expanded(
                            child: Text(
                              "${(pct * 100).toStringAsFixed(0)}% pagado de ${formatCurrency(cuenta.montoTotal)}",
                              style: const TextStyle(fontSize: 10, color: AppColors.textSecondary)),
                          ),
                          if (cuenta.proximaCuota != null)
                            Container(
                              padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 2),
                              decoration: BoxDecoration(
                                color: AppColors.statusOrange.withValues(alpha: 0.1),
                                borderRadius: BorderRadius.circular(8),
                                border: Border.all(
                                    color: AppColors.statusOrange.withValues(alpha: 0.4),
                                    width: 0.7),
                              ),
                              child: Row(mainAxisSize: MainAxisSize.min, children: [
                                const Icon(Icons.event_outlined,
                                    size: 11, color: AppColors.statusOrange),
                                const SizedBox(width: 3),
                                Text(
                                  "Cuota ${cuenta.proximaCuota!.numero}: ${formatCurrency(cuenta.proximaCuota!.monto)} · ${cuenta.proximaCuota!.fecha}",
                                  style: const TextStyle(
                                      fontSize: 10, color: AppColors.statusOrange),
                                ),
                              ]),
                            )
                          else if (cuenta.cuotas.isNotEmpty && saldado)
                            const Text("Todas las cuotas pagadas ✓",
                                style: TextStyle(fontSize: 10, color: AppColors.statusGreen)),
                        ]),
                      ]),
                    ),
                  ),
                );
              },
            ),
          )),
      ]),
      floatingActionButton: puedeEditar
          ? FloatingActionButton.extended(
              onPressed: _crearCuenta,
              icon: const Icon(Icons.add),
              label: const Text("Nueva Cuenta"),
            )
          : null,
    );
  }
}

class DetalleCuentaProveedor extends StatefulWidget {
  final CuentaPorPagarProveedor cuenta;
  const DetalleCuentaProveedor({super.key, required this.cuenta});
  @override State<DetalleCuentaProveedor> createState() => _DetalleCuentaProveedorState();
}

class _DetalleCuentaProveedorState extends State<DetalleCuentaProveedor> {
  bool get puedeEditar => (usuarioSesion?.rol == "Administrador" || usuarioSesion?.rol == "Maestro" || usuarioSesion?.rol == "Dueño");

  /// Le suma una factura nueva a la cuenta que ya existe, en vez de
  /// abrir otra cuenta para el mismo acreedor.
  ///
  /// Si tiene saldo a favor el diálogo pregunta si se usa en esta
  /// factura; si la respuesta es que sí, el descuento lo hace el
  /// sistema. Si es que no, el saldo queda apartado para la próxima.
  Future<void> _agregarDeuda() async {
    final cuenta = widget.cuenta;
    final res = await pedirAgregarDeuda(
      context,
      nombreAcreedor: cuenta.nombre,
      montoTotal    : cuenta.montoTotal,
      pagado        : cuenta.totalPagado + cuenta.totalCuotasPagadas,
      favorApartado : cuenta.favorApartado,
      saldoFavor    : cuenta.saldoFavor,
    );
    if (res == null || !mounted) return;
    if (cuenta.id == null) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text("La cuenta no tiene ID: no se puede actualizar"),
        backgroundColor: AppColors.statusRed));
      return;
    }
    // Guardamos el estado anterior para poder revertir si el servidor
    // rechaza el cambio; si no, la pantalla quedaría mostrando una
    // deuda que en la base no existe.
    final montoAnterior  = cuenta.montoTotal;
    final notasAnteriores = cuenta.notas;
    final visibles = cuenta.notasVisibles;
    final linea = lineaNotaAumento(res);
    cuenta.montoTotal = res.nuevoMontoTotal;
    cuenta.notas = visibles.isEmpty ? linea : '$visibles\n$linea';
    cuenta.favorApartado = res.nuevoFavorApartado;
    try {
      await _Api.put('cuentas_pagar_proveedor', cuenta.id!.toString(),
          cuenta.toMap());
      if (!mounted) return;
      setState(() {});
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(res.aplicadoDeFavor > 0.001
            ? "Deuda agregada. Se aplicaron "
              "${formatCurrency(res.aplicadoDeFavor)} de saldo a favor; "
              "quedan ${formatCurrency(res.pendienteDeEstaFactura)} "
              "pendientes de esta factura."
            : "Deuda de ${formatCurrency(res.monto)} agregada."),
        backgroundColor: AppColors.statusGreen,
        duration: const Duration(seconds: 6)));
    } catch (e) {
      cuenta.montoTotal = montoAnterior;
      cuenta.notas      = notasAnteriores;
      if (!mounted) return;
      setState(() {});
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text("No se pudo guardar el aumento: $e"),
        backgroundColor: AppColors.statusRed));
    }
  }

  void _registrarPago() {
    final montoController = TextEditingController();
    final tasaController = TextEditingController(text: ConfigSistema.tasaCambio.toStringAsFixed(2));
    String metodo = "Efectivo \$";
    bool guardando = false;
    final formKey = GlobalKey<FormState>();

    showDialog(context: context, builder: (ctx) => StatefulBuilder(
      builder: (context, setS) {
        // Métodos en Bs según el helper común. Antes era comparación exacta
        // y "Pago Móvil" / "Punto de venta" (los de la configuración) no
        // pedían tasa: el monto en Bs se guardaba como si fueran $.
        bool requiereTasa = esMetodoEnBolivares(metodo);
        return AlertDialog(
          title: const Row(children: [
            Icon(Icons.attach_money, color: AppColors.statusGreen),
            SizedBox(width: 8),
            Text("Registrar Pago"),
          ]),
          content: Form(
            key: formKey,
            child: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
              // Saldo pendiente
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(
                  color: AppColors.statusRed.withValues(alpha: 0.07),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
                  const Text("Saldo pendiente:", style: TextStyle(fontSize: 13, color: AppColors.textSecondary)),
                  Text(formatCurrency(widget.cuenta.saldoRestante),
                    style: const TextStyle(fontSize: 15, fontWeight: FontWeight.bold, color: AppColors.statusRed)),
                ]),
              ),
              const SizedBox(height: 12),
              DropdownButtonFormField<String>(
                value: metodo,
                items: ConfigSistema.metodossPago.isNotEmpty
                  ? ConfigSistema.metodossPago.map((e) => DropdownMenuItem(value: e, child: Text(e))).toList()
                  : ["Efectivo \$","Efectivo Bs","Pago móvil","Transferencia","Zelle","Punto"]
                      .map((e) => DropdownMenuItem(value: e, child: Text(e))).toList(),
                onChanged: (v) { if (v != null) setS(() => metodo = v); },
                decoration: const InputDecoration(labelText: "Método de pago", prefixIcon: Icon(Icons.payment_outlined)),
              ),
              const SizedBox(height: 10),
              TextFormField(
                controller: montoController,
                keyboardType: const TextInputType.numberWithOptions(decimal: true),
                decoration: InputDecoration(
                  labelText: requiereTasa ? "Monto en Bolívares (Bs)" : "Monto en Dólares \$",
                  prefixIcon: const Icon(Icons.attach_money),
                ),
                validator: (v) {
                  final d = double.tryParse(v?.trim() ?? '');
                  if (d == null || d <= 0) return "Ingrese un monto válido";
                  return null;
                },
              ),
              if (requiereTasa) ...[
                const SizedBox(height: 10),
                TextFormField(
                  controller: tasaController,
                  keyboardType: const TextInputType.numberWithOptions(decimal: true),
                  decoration: const InputDecoration(
                    labelText: "Tasa de cambio (Bs/\$)",
                    prefixIcon: Icon(Icons.currency_exchange),
                  ),
                  validator: (v) {
                    final d = double.tryParse(v?.trim() ?? '');
                    if (d == null || d <= 0) return "Ingrese una tasa válida";
                    return null;
                  },
                ),
              ],
            ])),
          ),
          actions: [
            TextButton(onPressed: () => Navigator.pop(ctx), child: const Text("Cancelar")),
            ElevatedButton.icon(
              icon: guardando
                ? const SizedBox(width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                : const Icon(Icons.check, size: 18),
              label: const Text("Registrar"),
              style: ElevatedButton.styleFrom(backgroundColor: AppColors.statusGreen),
              onPressed: guardando ? null : () async {
                if (!formKey.currentState!.validate()) return;
                double monto = double.tryParse(montoController.text) ?? 0;
                double montoFinal = monto;
                if (requiereTasa) {
                  final tasa = double.tryParse(tasaController.text) ?? ConfigSistema.tasaCambio;
                  montoFinal = tasa > 0 ? monto / tasa : monto;
                }
                setS(() => guardando = true);
                try {
                  if (widget.cuenta.id == null) throw Exception('Cuenta sin ID');
                  final nuevoPago = {
                    'monto': montoFinal,
                    'fecha': obtenerFechaActual(),
                    'metodo': metodo,
                  };
                  // Enviamos estado completo para garantizar persistencia
                  final pagosActualizados = [
                    ...widget.cuenta.pagos.map((p) => Map<String, dynamic>.from(p)),
                    nuevoPago,
                  ];
                  final payload = <String, dynamic>{
                    ...widget.cuenta.toMap(),
                    'pago': nuevoPago,
                    'pagos': pagosActualizados,
                  };
                  await _Api.put('cuentas_pagar_proveedor', widget.cuenta.id!.toString(), payload);
                  if (!ctx.mounted) return;
                  setState(() {
                    widget.cuenta.pagos.add(nuevoPago);
                  });
                  Navigator.pop(ctx);
                  // Si el pago superó la deuda, avisamos del excedente
                  // en vez de dejarlo pasar en silencio.
                  final favor = widget.cuenta.saldoFavor;
                  if (mounted) ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text(favor > 0.001
                          ? "Pago de ${formatCurrency(montoFinal)} registrado. "
                            "Quedan ${formatCurrency(favor)} a favor."
                          : "Pago de ${formatCurrency(montoFinal)} registrado correctamente"),
                      duration: Duration(seconds: favor > 0.001 ? 6 : 4),
                      backgroundColor: AppColors.statusGreen));
                } catch (e) {
                  setS(() => guardando = false);
                  if (ctx.mounted) ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(content: Text('Error al registrar pago: $e'), backgroundColor: AppColors.statusRed));
                }
              },
            ),
          ],
        );
      },
    ));
  }

  @override
  Widget build(BuildContext context) {
    final cuenta = widget.cuenta;
    final pct = cuenta.montoTotal > 0
        ? (1 - cuenta.saldoRestante / cuenta.montoTotal).clamp(0.0, 1.0)
        : 1.0;
    final saldado = cuenta.saldoRestante <= 0;
    final tieneCuotas = cuenta.cuotas.isNotEmpty;
    final cuotasPendientes = cuenta.cuotas.where((c) => !c.pagada).length;

    return Scaffold(
      appBar: AppBar(
        title: Text(cuenta.nombre),
        actions: [
          if (puedeEditar)
            IconButton(
              icon: const Icon(Icons.add_shopping_cart),
              tooltip: "Agregar deuda (factura nueva)",
              onPressed: _agregarDeuda),
        ],
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          // ── Card resumen ─────────────────────────────────
          Card(
            shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Row(children: [
                  const Icon(Icons.business_outlined, color: AppColors.royalBlue),
                  const SizedBox(width: 8),
                  Expanded(child: Text(cuenta.nombre,
                      style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 16))),
                  if (saldado)
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                      decoration: BoxDecoration(
                          color: AppColors.statusGreen.withValues(alpha: 0.12),
                          borderRadius: BorderRadius.circular(20)),
                      child: const Text("SALDADO",
                          style: TextStyle(fontSize: 11, fontWeight: FontWeight.bold,
                              color: AppColors.statusGreen)),
                    ),
                ]),
                const Divider(height: 20),
                _infoRow(Icons.receipt_outlined, "RIF", cuenta.rif),
                _infoRow(Icons.phone_outlined, "Teléfono", cuenta.telefono),
                if (cuenta.correo.isNotEmpty)
                  _infoRow(Icons.email_outlined, "Correo", cuenta.correo),
                _infoRow(Icons.event_outlined, "Fecha límite", cuenta.fechaLimite),
                const SizedBox(height: 12),
                Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
                  Text("Deuda total: ${formatCurrency(cuenta.montoTotal)}",
                      style: const TextStyle(color: AppColors.textSecondary, fontSize: 13)),
                  Text("${(pct * 100).toStringAsFixed(0)}% pagado",
                      style: const TextStyle(color: AppColors.textSecondary, fontSize: 13)),
                ]),
                const SizedBox(height: 6),
                ClipRRect(
                  borderRadius: BorderRadius.circular(6),
                  child: LinearProgressIndicator(
                    value: pct, minHeight: 10,
                    backgroundColor: Colors.grey[200],
                    valueColor: AlwaysStoppedAnimation<Color>(
                        saldado ? AppColors.statusGreen : AppColors.statusRed),
                  ),
                ),
                const SizedBox(height: 12),
                Container(
                  width: double.infinity,
                  padding: const EdgeInsets.all(12),
                  decoration: BoxDecoration(
                    color: (saldado ? AppColors.statusGreen : AppColors.statusRed)
                        .withValues(alpha: 0.08),
                    borderRadius: BorderRadius.circular(10),
                  ),
                  child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
                    Text("SALDO RESTANTE",
                        style: TextStyle(
                            color: saldado ? AppColors.statusGreen : AppColors.statusRed,
                            fontWeight: FontWeight.w600, fontSize: 12, letterSpacing: 0.5)),
                    Text(formatCurrency(cuenta.saldoRestante),
                        style: TextStyle(
                            color: saldado ? AppColors.statusGreen : AppColors.statusRed,
                            fontWeight: FontWeight.bold, fontSize: 22)),
                  ]),
                ),
                // Si se pagó de más, el excedente queda acá a la vista.
                BannerSaldoFavor(
                  saldoFavor: cuenta.saldoFavor,
                  nota: 'Pagaste de más. Queda a favor con este proveedor.',
                ),
              ]),
            ),
          ),
          const SizedBox(height: 16),

          // ── Plan de Cuotas ───────────────────────────────
          if (tieneCuotas) ...[
            Row(children: [
              const Text("Plan de Cuotas",
                  style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
              const SizedBox(width: 8),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
                decoration: BoxDecoration(
                    color: AppColors.primaryBlue.withValues(alpha: 0.1),
                    borderRadius: BorderRadius.circular(10)),
                child: Text(
                    "$cuotasPendientes pendiente${cuotasPendientes != 1 ? 's' : ''}",
                    style: const TextStyle(fontSize: 11,
                        color: AppColors.primaryBlue, fontWeight: FontWeight.w600)),
              ),
            ]),
            const SizedBox(height: 8),
            ...cuenta.cuotas.map((cuota) => Card(
              margin: const EdgeInsets.only(bottom: 8),
              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
              elevation: 1,
              child: ListTile(
                contentPadding: const EdgeInsets.symmetric(horizontal: 14, vertical: 6),
                leading: Container(
                  width: 36, height: 36,
                  decoration: BoxDecoration(
                    color: (cuota.pagada ? AppColors.statusGreen : AppColors.statusOrange)
                        .withValues(alpha: 0.12),
                    shape: BoxShape.circle,
                  ),
                  child: Center(
                    child: Text("${cuota.numero}",
                        style: TextStyle(
                            fontWeight: FontWeight.bold,
                            color: cuota.pagada
                                ? AppColors.statusGreen
                                : AppColors.statusOrange)),
                  ),
                ),
                title: Row(children: [
                  Text(formatCurrency(cuota.monto),
                      style: TextStyle(
                          fontWeight: FontWeight.bold,
                          fontSize: 15,
                          color: cuota.pagada
                              ? AppColors.statusGreen
                              : AppColors.textPrimary)),
                  const Spacer(),
                  if (cuota.pagada)
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
                      decoration: BoxDecoration(
                          color: AppColors.statusGreen.withValues(alpha: 0.1),
                          borderRadius: BorderRadius.circular(8)),
                      child: const Text("Pagada",
                          style: TextStyle(fontSize: 11,
                              color: AppColors.statusGreen,
                              fontWeight: FontWeight.w600)),
                    )
                  else if (puedeEditar)
                    TextButton.icon(
                      icon: const Icon(Icons.check_circle_outline, size: 16),
                      label: const Text("Pagar", style: TextStyle(fontSize: 12)),
                      style: TextButton.styleFrom(
                          foregroundColor: AppColors.statusGreen,
                          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                          minimumSize: Size.zero,
                          tapTargetSize: MaterialTapTargetSize.shrinkWrap),
                      onPressed: () => _pagarCuota(cuota),
                    ),
                ]),
                subtitle: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Row(children: [
                    const Icon(Icons.event_outlined, size: 12, color: AppColors.textSecondary),
                    const SizedBox(width: 4),
                    Text("Vence: ${cuota.fecha}",
                        style: const TextStyle(fontSize: 11, color: AppColors.textSecondary)),
                  ]),
                  if (cuota.pagada && cuota.fechaPago != null)
                    Row(children: [
                      const Icon(Icons.check_outlined, size: 12, color: AppColors.statusGreen),
                      const SizedBox(width: 4),
                      Text("Pagada el: ${cuota.fechaPago}",
                          style: const TextStyle(fontSize: 11, color: AppColors.statusGreen)),
                    ]),
                ]),
              ),
            )),
            const SizedBox(height: 16),
          ],

          // ── Historial de pagos libres ─────────────────────
          const Text("Historial de Pagos",
              style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
          const SizedBox(height: 8),
          if (cuenta.pagos.isEmpty && !tieneCuotas)
            const EmptyState(
                mensaje: "Sin pagos registrados aún.",
                icono: Icons.payment_outlined)
          else if (cuenta.pagos.isEmpty)
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 8),
              child: Text("Sin abonos adicionales registrados.",
                  style: const TextStyle(fontSize: 13, color: AppColors.textSecondary)),
            )
          else
            ...cuenta.pagos.map((pago) => Card(
              margin: const EdgeInsets.only(bottom: 6),
              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
              elevation: 1,
              child: ListTile(
                leading: const CircleAvatar(
                    backgroundColor: Color(0xFFE8F5E9),
                    child: Icon(Icons.payment_outlined,
                        color: AppColors.statusGreen, size: 20)),
                title: Text(
                    formatCurrency(double.tryParse(pago['monto'].toString()) ?? 0),
                    style: const TextStyle(
                        fontWeight: FontWeight.bold, color: AppColors.statusGreen)),
                subtitle: Text("${pago['metodo']} · ${pago['fecha']}",
                    style: const TextStyle(
                        fontSize: 12, color: AppColors.textSecondary)),
              ),
            )),
          const SizedBox(height: 80),
        ]),
      ),
      floatingActionButton: puedeEditar && !saldado
          ? FloatingActionButton.extended(
              onPressed: _registrarPago,
              icon: const Icon(Icons.attach_money),
              label: const Text("Registrar Pago"),
            )
          : null,
    );
  }

  void _pagarCuota(CuotaCobrar cuota) {
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Row(children: [
          const Icon(Icons.check_circle_outline, color: AppColors.statusGreen),
          const SizedBox(width: 8),
          Text("Pagar Cuota ${cuota.numero}"),
        ]),
        content: Column(mainAxisSize: MainAxisSize.min, children: [
          ListTile(
            contentPadding: EdgeInsets.zero,
            leading: const Icon(Icons.attach_money, color: AppColors.statusGreen),
            title: Text("Monto: ${formatCurrency(cuota.monto)}",
                style: const TextStyle(fontWeight: FontWeight.bold)),
            subtitle: Text("Vencimiento: ${cuota.fecha}"),
          ),
          const Text("¿Confirma que esta cuota fue pagada hoy?"),
        ]),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text("Cancelar")),
          ElevatedButton.icon(
            icon: const Icon(Icons.check, size: 16),
            label: const Text("Confirmar pago"),
            style: ElevatedButton.styleFrom(backgroundColor: AppColors.statusGreen),
            onPressed: () async {
              Navigator.pop(ctx);
              try {
                if (widget.cuenta.id == null) throw Exception('Cuenta sin ID. Recargue.');
                final fechaHoy = obtenerFechaActual();
                await _Api.put('cuentas_pagar_proveedor',
                    widget.cuenta.id!.toString(), {
                  'cuota_pagada': {'numero': cuota.numero, 'fecha_pago': fechaHoy}
                });
                if (!mounted) return;
                setState(() {
                  cuota.pagada = true;
                  cuota.fechaPago = fechaHoy;
                });
                ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                    content: Text(
                        "Cuota ${cuota.numero} pagada (${formatCurrency(cuota.monto)})"),
                    backgroundColor: AppColors.statusGreen));
              } catch (e) {
                if (mounted)
                  ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                      content: Text("Error: $e"),
                      backgroundColor: AppColors.statusRed));
              }
            },
          ),
        ],
      ),
    );
  }

  Widget _infoRow(IconData icon, String label, String value) => Padding(
    padding: const EdgeInsets.symmetric(vertical: 3),
    child: Row(children: [
      Icon(icon, size: 16, color: AppColors.textSecondary),
      const SizedBox(width: 6),
      Text("$label: ", style: const TextStyle(color: AppColors.textSecondary, fontSize: 13)),
      Expanded(child: Text(value, style: const TextStyle(fontWeight: FontWeight.w500, fontSize: 13))),
    ]),
  );
}

// ============================================================
//  INVENTARIO — carga desde la API
// ============================================================
class VentanaInventario extends StatefulWidget {
  const VentanaInventario({super.key});
  @override State<VentanaInventario> createState() => _VentanaInventarioState();
}

class _VentanaInventarioState extends State<VentanaInventario> {
  List<Producto> _productos = [];
  /// IMEIs cargados (para filtros por tienda/ubicación).
  List<ImeiRegistro> _imeis = [];
  bool _cargando = true;
  String _query = '';
  String _filtroCategoria = 'Todos';

  /// Lista de tiendas conocidas (cargada de la tabla `tiendas`).
  List<String> _todasTiendas = [];

  /// Tienda activa en el filtro:
  ///  · Para Dueño/Administrador/Maestro: pueden cambiarla; ''=Todas.
  ///  · Para otros roles: forzada a la tienda del usuario.
  String _tiendaFiltro = '';

  bool get _puedeVerTodas {
    final r = usuarioSesion?.rol;
    // REGLA ESTRICTA: solo el DUEÑO ve el inventario de todas las tiendas.
    // Cualquier otro rol (Administrador, Gerente, Cajero, Vendedor,
    // Maestro, Encargado, etc.) queda restringido a su propia tienda.
    // Antes era permisivo para Admin/Gerente/Maestro también, pero el
    // dueño pidió que la separación de inventarios sea absoluta.
    return r == 'Dueño';
  }

  @override
  void initState() {
    super.initState();
    // Tienda inicial:
    //  · Si el usuario NO puede ver todas → su tienda forzada
    //  · Si SÍ puede ver todas → '' (significa Todas)
    if (!_puedeVerTodas) {
      _tiendaFiltro = usuarioSesion?.tienda ?? '';
    }
    _cargar();
  }

  // ── PUNTO 1: Eliminar producto del catálogo ──
  Future<void> _eliminarProducto(Producto p) async {
    final stockActual = CategoriasProductos.usaIMEI(p.categoria)
        ? stockImeiGlobal.where((i) => i.producto.codigo == p.codigo && !i.vendido).length
        : p.stockManual;

    final ok = await showDialog<bool>(
      context: context,
      builder: (c) => AlertDialog(
        shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(14)),
        icon: const Icon(Icons.warning_amber_rounded,
            color: AppColors.statusRed, size: 40),
        title: const Text("Eliminar producto"),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text("¿Eliminar \"${p.nombre}\" del catálogo?",
                style: const TextStyle(fontSize: 14)),
            const SizedBox(height: 8),
            Text("Código: ${p.codigo}",
                style: const TextStyle(fontSize: 12,
                    color: AppColors.textSecondary)),
            if (stockActual > 0) ...[
              const SizedBox(height: 10),
              Container(
                padding: const EdgeInsets.all(8),
                decoration: BoxDecoration(
                  color: AppColors.statusRed.withValues(alpha: 0.1),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: Row(children: [
                  const Icon(Icons.inventory_2_outlined,
                      size: 16, color: AppColors.statusRed),
                  const SizedBox(width: 6),
                  Expanded(
                    child: Text(
                      "Este producto tiene $stockActual unidad(es) en stock. "
                      "Al eliminarlo perderás esa información.",
                      style: const TextStyle(fontSize: 11,
                          color: AppColors.statusRed),
                    ),
                  ),
                ]),
              ),
            ],
            const SizedBox(height: 8),
            const Text("Esta acción no se puede deshacer.",
                style: TextStyle(fontSize: 11, fontStyle: FontStyle.italic,
                    color: AppColors.textSecondary)),
          ],
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(c, false),
              child: const Text("Cancelar")),
          FilledButton(
            style: FilledButton.styleFrom(
                backgroundColor: AppColors.statusRed),
            onPressed: () => Navigator.pop(c, true),
            child: const Text("Eliminar")),
        ],
      ),
    );
    if (ok != true) return;

    try {
      final raw = await _Api.get('productos');
      final fila = (raw as List).cast<Map<String, dynamic>>().firstWhere(
          (m) => m['codigo'] == p.codigo,
          orElse: () => <String, dynamic>{});
      if (fila['id'] != null) {
        await _Api.delete('productos', fila['id'].toString());
      }
      catalogoGlobal.removeWhere((x) =>
          x.codigo == p.codigo || x.productoPadreCodigo == p.codigo);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text("\"${p.nombre}\" eliminado"),
          backgroundColor: AppColors.statusGreen));
        _cargar();
      }
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text("Error al eliminar: $e"),
          backgroundColor: AppColors.statusRed));
    }
  }

  Future<void> _cargar() async {
    setState(() => _cargando = true);
    try {
      // Traer productos, IMEIs y tiendas en paralelo
      final results = await Future.wait([
        _Api.get('productos'),
        _Api.get('stock_imei'),
        _Api.get('tiendas'),
      ]);

      final rawP  = results[0];
      final rawI  = results[1];
      final rawT  = results[2];

      // Lista de tiendas (para el selector de Dueño/Admin)
      _todasTiendas = ((rawT as List?) ?? [])
          .map((m) => (m as Map)['nombre']?.toString() ?? '')
          .where((n) => n.isNotEmpty)
          .toList();

      // ── PASO 1: cargar productos PRIMERO ────────────────────────
      // Es CRÍTICO actualizar catalogoGlobal ANTES de mapear los IMEIs.
      // ImeiRegistro.fromMap usa catalogoGlobal para resolver los datos
      // del producto (nombre, marca, modelo, precios) cuando el backend
      // no hace JOIN. Si lo hacemos al revés, los IMEIs quedan con
      // producto vacío y el stockTotal cuenta 0.
      _productos = ((rawP as List?) ?? [])
          .map((m) => Producto.fromMap(m))
          .toList();
      catalogoGlobal = _productos;

      // ── PASO 2: ahora sí cargar IMEIs (con catalogoGlobal listo) ──
      final imeis = ((rawI as List?) ?? [])
          .map((m) => ImeiRegistro.fromMap(m))
          .toList();
      stockImeiGlobal = imeis;
      _imeis = imeis;

      // ── PASO 3: calcular stockTotal de cada producto ────────────
      // Teléfonos  → contar IMEIs no vendidos del producto que estén
      //              en la tienda activa (`_tiendaFiltro`). Si la
      //              tienda activa es '' (Todas), cuenta todos.
      // Otros      → `stock_manual` global. NOTA: los productos no
      //              teléfono actualmente NO tienen división por
      //              tienda en BD (un único stock_manual). Mientras
      //              no se haga esa migración, se muestra el global
      //              en todas las vistas.
      for (final p in _productos) {
        if (CategoriasProductos.usaIMEI(p.categoria)) {
          p.stockTotal = imeis.where((i) =>
              i.producto.codigo == p.codigo
              && !i.vendido
              && (_tiendaFiltro.isEmpty
                  || i.ubicacion == _tiendaFiltro)
          ).length;
        } else {
          p.stockTotal = p.stockManual;
        }
      }

      // ── PASO 4: sumar el stock de los SUBPRODUCTOS al padre ─────
      // Los subproductos NO se muestran en el listado del inventario
      // (solo el padre). Pero el stock total mostrado en el padre
      // debe reflejar también el stock de sus variantes — si no, el
      // dueño vería un Redmi A5 con 0 unidades cuando en realidad
      // tiene 5 blancos + 3 negros + 2 azules.
      final hijosPorPadre = <String, List<Producto>>{};
      for (final p in _productos) {
        if (p.productoPadreCodigo.isNotEmpty) {
          hijosPorPadre.putIfAbsent(p.productoPadreCodigo, () => [])
              .add(p);
        }
      }
      for (final padre in _productos.where((p) => p.productoPadreCodigo.isEmpty)) {
        final hijos = hijosPorPadre[padre.codigo] ?? const <Producto>[];
        for (final h in hijos) {
          padre.stockTotal += h.stockTotal;
        }
      }

    } catch (e) {
      debugPrint('[VentanaInventario._cargar] Error: $e');
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Error al cargar inventario: $e'),
          backgroundColor: AppColors.statusRed,
          duration: const Duration(seconds: 4)));
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  /// Abre un diálogo donde el admin puede activar/desactivar el uso
  /// de IMEI por cada categoría de producto. Cuando una categoría
  /// usa IMEI, el sistema obliga a escanear/escribir un número de
  /// serie único por cada unidad (igual que los teléfonos).
  ///
  /// El cambio aplica inmediatamente en TODA la app y persiste en
  /// SharedPreferences para que se respete al cerrar y reabrir.
  Future<void> _abrirConfigIMEICategorias() async {
    await showDialog<void>(
      context: context,
      builder: (ctx) => StatefulBuilder(builder: (ctx, setDlg) {
        return Dialog(
          shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(16)),
          insetPadding: const EdgeInsets.all(20),
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 500, maxHeight: 600),
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              Container(
                padding: const EdgeInsets.all(16),
                decoration: const BoxDecoration(
                  color: AppColors.royalBlue,
                  borderRadius: BorderRadius.vertical(
                      top: Radius.circular(16)),
                ),
                child: Row(children: [
                  const Icon(Icons.qr_code_scanner,
                      color: Colors.white, size: 26),
                  const SizedBox(width: 10),
                  Expanded(child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: const [
                        Text('Categorías con IMEI',
                            style: TextStyle(
                                color: Colors.white,
                                fontSize: 17,
                                fontWeight: FontWeight.bold)),
                        Text(
                            'Activa el switch para que los productos '
                            'de esa categoría usen IMEI',
                            style: TextStyle(
                                color: Colors.white70, fontSize: 11)),
                      ])),
                  IconButton(
                    icon: const Icon(Icons.close, color: Colors.white),
                    onPressed: () => Navigator.pop(ctx),
                  ),
                ]),
              ),
              Expanded(child: ListView.builder(
                padding: const EdgeInsets.symmetric(vertical: 8),
                itemCount: CategoriasProductos.listaObjetos.length,
                itemBuilder: (c, i) {
                  final cat = CategoriasProductos.listaObjetos[i];
                  return Container(
                    margin: const EdgeInsets.symmetric(
                        horizontal: 12, vertical: 4),
                    decoration: BoxDecoration(
                      color: cat.usaIMEI
                          ? AppColors.royalBlue.withValues(alpha: 0.06)
                          : Colors.grey[50],
                      borderRadius: BorderRadius.circular(10),
                      border: Border.all(
                          color: cat.usaIMEI
                              ? AppColors.royalBlue.withValues(alpha: 0.4)
                              : Colors.grey[300]!),
                    ),
                    child: SwitchListTile(
                      title: Row(children: [
                        Icon(
                            cat.usaIMEI
                                ? Icons.qr_code_2
                                : Icons.inventory_2_outlined,
                            color: cat.usaIMEI
                                ? AppColors.royalBlue
                                : Colors.grey[600],
                            size: 20),
                        const SizedBox(width: 8),
                        Expanded(child: Text(cat.nombre,
                            style: const TextStyle(
                                fontSize: 14,
                                fontWeight: FontWeight.bold))),
                      ]),
                      subtitle: Text(
                          cat.usaIMEI
                              ? 'Requiere IMEI único por unidad'
                              : 'Stock manual (sin IMEI)',
                          style: const TextStyle(fontSize: 11)),
                      value: cat.usaIMEI,
                      activeColor: AppColors.royalBlue,
                      onChanged: (v) async {
                        await CategoriasProductos.setUsaIMEI(
                            cat.nombre, v);
                        setDlg(() {});
                      },
                    ),
                  );
                },
              )),
              Container(
                padding: const EdgeInsets.all(12),
                color: Colors.grey[50],
                child: Row(children: [
                  const Expanded(child: Text(
                      'Los cambios se aplican inmediatamente y '
                      'se guardan automáticamente.',
                      style: TextStyle(
                          fontSize: 11, color: AppColors.textSecondary,
                          fontStyle: FontStyle.italic))),
                  TextButton(
                    onPressed: () => Navigator.pop(ctx),
                    child: const Text('Cerrar'),
                  ),
                ]),
              ),
            ]),
          ),
        );
      }),
    );
    // Refrescar el listado por si cambiaron las categorías que usan IMEI
    if (mounted) _cargar();
  }

  // ═══════════════════════════════════════════════════════════
  //  AJUSTE RÁPIDO DE STOCK (productos sin IMEI)
  // ═══════════════════════════════════════════════════════════

  /// Suma o resta [delta] unidades desde los botones +/− de la lista.
  ///
  /// Actualiza la pantalla al instante (optimista) y revierte si el
  /// servidor rechaza el cambio, para que el número que se ve sea
  /// siempre el que está guardado.
  Future<void> _ajusteRapido(Producto p, int delta) async {
    final messenger = ScaffoldMessenger.of(context);
    // Feedback inmediato: el usuario ve el número moverse mientras
    // viaja el PUT. Si falla, `ajustarStockManual` deja el valor viejo.
    setState(() {
      p.stockTotal = (p.stockTotal + delta).clamp(0, 999999);
    });
    final res = await ajustarStockManual(p, delta);
    if (!mounted) return;
    setState(() {
      // Sincronizar con lo que realmente quedó guardado.
      p.stockTotal = res.stockFinal;
    });
    if (!res.ok) {
      messenger.showSnackBar(SnackBar(
        content: Text(res.mensaje),
        backgroundColor: AppColors.statusRed,
        duration: const Duration(seconds: 4)));
    }
  }

  /// Abre un diálogo para escribir la cantidad exacta del producto.
  /// Se llega tocando el número de stock en la lista.
  Future<void> _editarStockDirecto(Producto p) async {
    final ctrl = TextEditingController(text: p.stockManual.toString());
    final nuevo = await showDialog<int>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Row(children: [
          const Icon(Icons.inventory_2_outlined,
              color: AppColors.primaryBlue),
          const SizedBox(width: 8),
          Expanded(child: Text(p.nombre,
              style: const TextStyle(fontSize: 16),
              overflow: TextOverflow.ellipsis)),
        ]),
        content: Column(mainAxisSize: MainAxisSize.min, children: [
          Text("${p.codigo} · ${p.categoria}",
              style: const TextStyle(
                  fontSize: 12, color: AppColors.textSecondary)),
          const SizedBox(height: 14),
          TextField(
            controller: ctrl,
            autofocus: true,
            keyboardType: TextInputType.number,
            textAlign: TextAlign.center,
            style: const TextStyle(
                fontSize: 28, fontWeight: FontWeight.bold),
            decoration: const InputDecoration(
              labelText: "Unidades en stock",
              border: OutlineInputBorder(),
            ),
            onSubmitted: (v) =>
                Navigator.pop(ctx, int.tryParse(v.trim())),
          ),
        ]),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text("Cancelar")),
          ElevatedButton.icon(
            icon: const Icon(Icons.check, size: 18),
            label: const Text("Guardar"),
            onPressed: () =>
                Navigator.pop(ctx, int.tryParse(ctrl.text.trim())),
          ),
        ],
      ),
    );
    if (nuevo == null || !mounted) return;
    final messenger = ScaffoldMessenger.of(context);
    final res = await establecerStockManual(p, nuevo);
    if (!mounted) return;
    setState(() => p.stockTotal = res.stockFinal);
    messenger.showSnackBar(SnackBar(
      content: Text(res.ok
          ? "Stock actualizado — ${res.mensaje}"
          : res.mensaje),
      backgroundColor:
          res.ok ? AppColors.statusGreen : AppColors.statusRed));
  }

  /// Exporta el inventario a Excel.
  ///
  /// Antes bajaba TODO el inventario de una tienda y había que
  /// filtrar el Excel a mano. Ahora el diálogo pide las dos cosas que
  /// hacían falta: de qué tienda y de qué categoría. La tienda sólo
  /// se puede elegir si el usuario ve más de una; el resto exporta la
  /// suya, pero igual puede elegir categoría.
  Future<void> _exportarInventario() async {
    // Categorías presentes en el inventario cargado, más las
    // configuradas en el sistema (por si alguna todavía no tiene
    // productos, para que el usuario no la busque sin encontrarla).
    final categorias = <String>{
      ..._productos
          .where((p) => p.productoPadreCodigo.isEmpty)
          .map((p) => p.categoria)
          .where((c) => c.trim().isNotEmpty),
      ...CategoriasProductos.lista,
    }.toList()
      ..sort();

    String tiendaSel = _tiendaFiltro;   // '' = todas
    String categoriaSel = '';           // '' = todas

    final confirmado = await showDialog<bool>(
      context: context,
      builder: (ctx) => StatefulBuilder(builder: (ctx, setS) => AlertDialog(
        title: const Row(children: [
          Icon(Icons.download_outlined, color: AppColors.brandBlue),
          SizedBox(width: 8),
          Expanded(child: Text("Descargar inventario")),
        ]),
        content: SingleChildScrollView(
          child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                if (_puedeVerTodas) ...[
                  DropdownButtonFormField<String>(
                    value: _todasTiendas.contains(tiendaSel) ? tiendaSel : '',
                    isExpanded: true,
                    decoration: const InputDecoration(
                      labelText: "Tienda",
                      prefixIcon: Icon(Icons.store_outlined),
                      border: OutlineInputBorder(),
                    ),
                    items: [
                      const DropdownMenuItem(
                          value: '', child: Text("Todas las tiendas")),
                      ..._todasTiendas.map((t) =>
                          DropdownMenuItem(value: t, child: Text(t))),
                    ],
                    onChanged: (v) => setS(() => tiendaSel = v ?? ''),
                  ),
                  const SizedBox(height: 12),
                ] else
                  Padding(
                    padding: const EdgeInsets.only(bottom: 12),
                    child: Text(
                        tiendaSel.isEmpty
                            ? "Inventario general"
                            : "Tienda: $tiendaSel",
                        style: const TextStyle(
                            fontSize: 12, color: AppColors.textSecondary)),
                  ),
                DropdownButtonFormField<String>(
                  value: categorias.contains(categoriaSel)
                      ? categoriaSel
                      : '',
                  isExpanded: true,
                  decoration: const InputDecoration(
                    labelText: "Categoría",
                    prefixIcon: Icon(Icons.category_outlined),
                    border: OutlineInputBorder(),
                  ),
                  items: [
                    const DropdownMenuItem(
                        value: '', child: Text("Todas las categorías")),
                    ...categorias.map((c) =>
                        DropdownMenuItem(value: c, child: Text(c))),
                  ],
                  onChanged: (v) => setS(() => categoriaSel = v ?? ''),
                ),
              ]),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text("Cancelar")),
          ElevatedButton.icon(
            icon: const Icon(Icons.download, size: 18),
            label: const Text("Descargar"),
            onPressed: () => Navigator.pop(ctx, true),
          ),
        ],
      )),
    );
    if (confirmado != true) return; // canceló

    final String tiendaExport = tiendaSel;
    final String categoriaExport = categoriaSel;

    try {
      // Calcular productos a exportar según la tienda elegida.
      // Para teléfonos, contamos IMEIs de esa tienda; para los demás
      // se reporta el stock_manual global (con una nota).
      final excel = Excel.createExcel();
      excel.delete('Sheet1');
      // Excel no acepta nombres de hoja de más de 31 caracteres ni
      // con los signos : \\ / ? * [ ], así que se limpian.
      final nombreHoja = _nombreHojaExcel(
          tiendaExport.isEmpty ? 'Inventario' : tiendaExport,
          categoriaExport);
      final hoja = excel[nombreHoja];
      hoja.appendRow([
        TextCellValue('Código'),
        TextCellValue('Producto'),
        TextCellValue('Categoría'),
        TextCellValue('Marca'),
        TextCellValue('Modelo'),
        TextCellValue('Stock'),
        TextCellValue('Costo unit. USD'),
        TextCellValue('Venta unit. USD'),
        TextCellValue('Valor stock USD'),
      ]);

      double totalValor = 0;
      // Recalcular stock por la tienda elegida (no por la del filtro)
      // y dejar sólo la categoría pedida.
      for (final p in _productos.where((p) =>
          p.productoPadreCodigo.isEmpty &&
          (categoriaExport.isEmpty || p.categoria == categoriaExport))) {
        int stock;
        if (CategoriasProductos.usaIMEI(p.categoria)) {
          stock = _imeis.where((i) =>
              i.producto.codigo == p.codigo
              && !i.vendido
              && (tiendaExport.isEmpty
                  || i.ubicacion == tiendaExport)
          ).length;
        } else {
          // No-teléfonos: stock global (sin división por tienda)
          stock = p.stockManual;
        }
        // Sumar también stock de variantes
        for (final h in _productos.where(
            (h) => h.productoPadreCodigo == p.codigo)) {
          if (CategoriasProductos.usaIMEI(h.categoria)) {
            stock += _imeis.where((i) =>
                i.producto.codigo == h.codigo
                && !i.vendido
                && (tiendaExport.isEmpty
                    || i.ubicacion == tiendaExport)
            ).length;
          } else {
            stock += h.stockManual;
          }
        }
        if (stock == 0) continue;
        final valor = stock * p.precioCosto;
        totalValor += valor;
        hoja.appendRow([
          TextCellValue(p.codigo),
          TextCellValue(p.nombre),
          TextCellValue(p.categoria),
          TextCellValue(p.marca),
          TextCellValue(p.modelo),
          IntCellValue(stock),
          DoubleCellValue(p.precioCosto),
          DoubleCellValue(p.precioVenta),
          DoubleCellValue(valor),
        ]);
      }
      hoja.appendRow([]);
      hoja.appendRow([
        TextCellValue(''),
        TextCellValue('TOTAL'),
        TextCellValue(''),
        TextCellValue(''),
        TextCellValue(''),
        TextCellValue(''),
        TextCellValue(''),
        TextCellValue(''),
        DoubleCellValue(totalValor),
      ]);

      final bytes = excel.encode();
      if (bytes == null) throw 'No se pudo generar Excel';
      final etiqueta = tiendaExport.isEmpty ? 'todas'
          : tiendaExport.replaceAll(' ', '_');
      final etiquetaCat = categoriaExport.isEmpty
          ? ''
          : '${categoriaExport.replaceAll(' ', '_')}_';
      final nombre = 'Inventario_${etiqueta}_$etiquetaCat'
          '${DateTime.now().millisecondsSinceEpoch}.xlsx';
      await descargarArchivo(
        Uint8List.fromList(bytes),
        nombre,
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      );
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text('✅ Inventario exportado '
              '(${tiendaExport.isEmpty ? "todas las tiendas" : tiendaExport}'
              '${categoriaExport.isEmpty ? "" : " · $categoriaExport"}): '
              '$nombre'),
          backgroundColor: AppColors.statusGreen,
          duration: const Duration(seconds: 5)));
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text('Error al exportar: $e'),
          backgroundColor: AppColors.statusRed));
    }
  }

  /// Nombre válido para una hoja de Excel: máximo 31 caracteres y sin
  /// los signos que Excel prohíbe.
  String _nombreHojaExcel(String base, String categoria) {
    var n = categoria.isEmpty ? base : '$base - $categoria';
    n = n.replaceAll(RegExp(r'[:\\/?*\[\]]'), ' ');
    return n.length <= 31 ? n : n.substring(0, 31);
  }

  /// Cantidad de subproductos (variantes) que tiene un padre.
  int _cantidadVariantes(String codigoPadre) {
    return _productos
        .where((p) => p.productoPadreCodigo == codigoPadre)
        .length;
  }

  List<Producto> get _filtrados => _productos.where((p) {
    // EXCLUIR subproductos del listado — solo se muestran los padres.
    if (p.productoPadreCodigo.isNotEmpty) return false;

    // ── FILTRO POR TIENDA ──
    // La lógica difiere según el tipo de producto:
    //
    // TELÉFONOS: el campo productos.tienda NO importa. Lo que importa
    // es DÓNDE están físicamente sus IMEIs. Un teléfono aparece en una
    // tienda si tiene al menos 1 IMEI con ubicacion = esa tienda.
    // Si filtras por "Todas", siempre aparece.
    //
    // NO-TELÉFONOS: el stock_manual sigue al campo productos.tienda.
    // Un producto aparece en una tienda específica si:
    //   · tiene tienda asignada == filtro, O
    //   · tiene tienda vacía (inventario general/sin asignar).
    if (_tiendaFiltro.isNotEmpty) {
      if (CategoriasProductos.usaIMEI(p.categoria)) {
        // ¿Tiene al menos 1 IMEI no-vendido en esta tienda?
        final tieneImeiAqui = _imeis.any((i) =>
            i.producto.codigo == p.codigo
            && !i.vendido
            && i.ubicacion == _tiendaFiltro);
        if (!tieneImeiAqui) return false;
      } else {
        // No-teléfono: filtrar por campo tienda
        if (p.tienda != _tiendaFiltro && p.tienda.isNotEmpty) {
          return false;
        }
        // Si stockManual = 0, no mostrar (es residuo de un traslado total)
        if (p.stockManual <= 0 && p.tienda.isNotEmpty) {
          return false;
        }
      }
    }

    final matchQuery = _query.isEmpty ||
        p.nombre.toLowerCase().contains(_query.toLowerCase()) ||
        p.codigo.toLowerCase().contains(_query.toLowerCase()) ||
        p.marca.toLowerCase().contains(_query.toLowerCase());
    final matchCat = _filtroCategoria == 'Todos' || p.categoria == _filtroCategoria;
    return matchQuery && matchCat;
  }).toList();

  Widget _buildTotalInfo(String label, String value, Color valueColor) => Column(children: [
    Text(label, style: const TextStyle(color: Colors.white70, fontSize: 10)),
    Text(value, style: TextStyle(color: valueColor, fontSize: 18, fontWeight: FontWeight.bold)),
  ]);

  @override
  Widget build(BuildContext context) {
    final filtrados = _filtrados;
    final categorias = ['Todos', ...{ for (var p in _productos) p.categoria }];
    double totalCosto = filtrados.fold(0, (sum, p) => sum + (p.precioCosto * p.stockTotal));
    double totalVenta = filtrados.fold(0, (sum, p) => sum + (p.precioVenta * p.stockTotal));

    return Scaffold(
      appBar: AppBar(
        title: Text(_puedeVerTodas && _tiendaFiltro.isEmpty
            ? "Inventario General (Todas)"
            : "Inventario · ${_tiendaFiltro.isEmpty ? '?' : _tiendaFiltro}"),
        actions: [
          // Selector de tienda — solo para roles que pueden ver todas
          if (_puedeVerTodas)
            PopupMenuButton<String>(
              icon: const Icon(Icons.store_outlined),
              tooltip: "Ver inventario de tienda...",
              onSelected: (v) {
                setState(() => _tiendaFiltro = v);
                _cargar();
              },
              itemBuilder: (_) => [
                const PopupMenuItem(
                    value: '',
                    child: Text("📍 Todas las tiendas")),
                const PopupMenuDivider(),
                ..._todasTiendas.map((t) => PopupMenuItem(
                    value: t, child: Text(t))),
              ],
            ),
          // Carga de mercancía en volumen (productos sin IMEI).
          IconButton(
            icon: const Icon(Icons.playlist_add),
            tooltip: "Ingreso rápido de stock",
            onPressed: () async {
              final huboCambios = await Navigator.push<bool>(
                  context,
                  MaterialPageRoute(
                      builder: (_) =>
                          VentanaIngresoStock(tienda: _tiendaFiltro)));
              if (huboCambios == true && mounted) _cargar();
            },
          ),
          IconButton(
              icon: const Icon(Icons.download_outlined),
              tooltip: "Exportar inventario",
              onPressed: _exportarInventario),
          IconButton(
              icon: const Icon(Icons.refresh),
              tooltip: "Actualizar",
              onPressed: _cargar),
          // ── Realizar Inventario Físico ──
          // Abre una pantalla donde el usuario escanea o escribe los
          // IMEIs/códigos de los productos físicos en la tienda y el
          // sistema cuenta cuántos faltan vs el inventario teórico.
          IconButton(
              icon: const Icon(Icons.fact_check_outlined),
              tooltip: "Realizar inventario físico",
              onPressed: () {
                Navigator.push(context, MaterialPageRoute(
                    builder: (_) => VentanaInventarioFisico(
                      tiendaFiltro: _tiendaFiltro,
                    ))).then((_) => _cargar());
              }),
          // ── Configurar categorías (usa IMEI o no) ──
          // Solo para Admin/Dueño/Gerente/Maestro. Permite activar
          // o desactivar el uso de IMEI por categoría.
          if (_puedeVerTodas)
            IconButton(
                icon: const Icon(Icons.qr_code_scanner_outlined),
                tooltip: "Configurar IMEI por categoría",
                onPressed: _abrirConfigIMEICategorias),
        ],
      ),
      body: Column(children: [
        // Banner KPI
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
          color: AppColors.royalBlue,
          child: Row(mainAxisAlignment: MainAxisAlignment.spaceAround, children: [
            _buildTotalInfo("COSTO TOTAL", formatCurrency(totalCosto), Colors.white),
            Container(width: 1, height: 40, color: Colors.white24),
            _buildTotalInfo("VENTA PROYECTADA", formatCurrency(totalVenta), AppColors.statusYellow),
            Container(width: 1, height: 40, color: Colors.white24),
            _buildTotalInfo("PRODUCTOS", "${filtrados.length}", Colors.white70),
          ]),
        ),
        // Búsqueda + filtros
        Container(
          color: Colors.white,
          padding: const EdgeInsets.fromLTRB(12, 10, 12, 0),
          child: Column(children: [
            TextField(
              decoration: InputDecoration(
                hintText: "Buscar por nombre, código o marca...",
                prefixIcon: const Icon(Icons.search, color: AppColors.primaryBlue),
                suffixIcon: _query.isNotEmpty
                  ? IconButton(icon: const Icon(Icons.clear, size: 18), onPressed: () => setState(() => _query = ''))
                  : null,
                filled: true, fillColor: AppColors.surfaceGrey,
                border: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: BorderSide.none),
                contentPadding: const EdgeInsets.symmetric(vertical: 0, horizontal: 16),
              ),
              onChanged: (v) => setState(() => _query = v),
            ),
            const SizedBox(height: 8),
            SizedBox(height: 34, child: ListView(scrollDirection: Axis.horizontal, children: [
              ...categorias.map((cat) => Padding(
                padding: const EdgeInsets.only(right: 8),
                child: FilterChip(
                  label: Text(cat, style: const TextStyle(fontSize: 12)),
                  selected: _filtroCategoria == cat,
                  onSelected: (_) => setState(() => _filtroCategoria = cat),
                  selectedColor: AppColors.primaryBlue.withValues(alpha: 0.15),
                  checkmarkColor: AppColors.primaryBlue,
                ),
              )),
            ])),
            const SizedBox(height: 8),
          ]),
        ),
        if (_cargando)
          const Expanded(child: Center(child: CircularProgressIndicator()))
        else if (filtrados.isEmpty)
          Expanded(child: Center(
            child: Padding(
              padding: const EdgeInsets.all(32),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  const Icon(Icons.inventory_2_outlined,
                      size: 64, color: Colors.grey),
                  const SizedBox(height: 16),
                  Text(
                    _tiendaFiltro.isEmpty
                        ? "No se encontraron productos."
                        : "No hay productos en \"$_tiendaFiltro\".",
                    style: const TextStyle(
                        fontSize: 15, color: Colors.grey),
                    textAlign: TextAlign.center),
                  const SizedBox(height: 8),
                  Text(
                    _tiendaFiltro.isEmpty
                        ? "Si acabas de hacer un traslado, recarga la lista."
                        : "Si acabas de trasladar un equipo a esta tienda, "
                          "recarga la lista o cambia el filtro a \"Todas\" "
                          "para ver todos los productos.",
                    style: const TextStyle(
                        fontSize: 12, color: Colors.grey),
                    textAlign: TextAlign.center),
                  const SizedBox(height: 16),
                  Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      ElevatedButton.icon(
                        icon: const Icon(Icons.refresh, size: 18),
                        label: const Text('Recargar'),
                        onPressed: _cargar,
                        style: ElevatedButton.styleFrom(
                          backgroundColor: AppColors.primaryBlue,
                          foregroundColor: Colors.white,
                        ),
                      ),
                      if (_tiendaFiltro.isNotEmpty && _puedeVerTodas) ...[
                        const SizedBox(width: 8),
                        OutlinedButton.icon(
                          icon: const Icon(Icons.list, size: 18),
                          label: const Text('Ver todas'),
                          onPressed: () => setState(() {
                            _tiendaFiltro = '';
                            _cargar();
                          }),
                        ),
                      ],
                    ],
                  ),
                  // ── Diagnóstico: lista de tiendas donde sí hay productos ──
                  // Muestra al usuario en qué tiendas tiene productos sus
                  // datos actuales. Útil cuando filtra por "Sucursal X" y
                  // está vacío — le dice claramente "tus productos están
                  // en Sucursal Y, Z". Solo se muestra para admin/dueño
                  // (no para encargado, que tiene una sola tienda).
                  if (_tiendaFiltro.isNotEmpty && _puedeVerTodas) ...[
                    const SizedBox(height: 20),
                    const Divider(),
                    const SizedBox(height: 8),
                    Text("Tus productos están en:",
                        style: TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.bold,
                            color: Colors.grey[700])),
                    const SizedBox(height: 6),
                    Builder(builder: (_) {
                      // Contar productos por tienda (no-teléfonos por p.tienda,
                      // teléfonos por ubicaciones de sus IMEIs)
                      final conteo = <String, int>{};
                      for (final p in _productos) {
                        if (p.productoPadreCodigo.isNotEmpty) continue;
                        if (CategoriasProductos.usaIMEI(p.categoria)) {
                          for (final i in _imeis.where((x) =>
                              x.producto.codigo == p.codigo && !x.vendido)) {
                            final t = i.ubicacion.isEmpty ? '(sin tienda)' : i.ubicacion;
                            conteo[t] = (conteo[t] ?? 0) + 1;
                          }
                        } else {
                          if (p.stockManual <= 0) continue;
                          final t = p.tienda.isEmpty ? '(sin tienda)' : p.tienda;
                          conteo[t] = (conteo[t] ?? 0) + p.stockManual;
                        }
                      }
                      if (conteo.isEmpty) {
                        return const Text('No hay productos con stock en ninguna tienda.',
                            style: TextStyle(fontSize: 11, color: Colors.grey));
                      }
                      return Wrap(
                        spacing: 6,
                        runSpacing: 6,
                        alignment: WrapAlignment.center,
                        children: conteo.entries.map((e) => Chip(
                          backgroundColor: Colors.blue.shade50,
                          side: BorderSide(color: Colors.blue.shade200),
                          label: Text(
                            '${e.key}: ${e.value} unidades',
                            style: TextStyle(
                                fontSize: 11,
                                color: Colors.blue.shade900)),
                          padding: const EdgeInsets.symmetric(
                              horizontal: 4, vertical: 0),
                        )).toList(),
                      );
                    }),
                  ],
                ],
              ),
            ),
          ))
        else
          Expanded(child: RefreshIndicator(
            onRefresh: _cargar,
            child: ListView.builder(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
              itemCount: filtrados.length,
              itemBuilder: (c, i) {
                final p = filtrados[i];
                final stockColor = p.stockTotal >= 3
                    ? AppColors.statusGreen
                    : p.stockTotal >= 1
                        ? AppColors.statusOrange
                        : AppColors.statusRed;
                final stockLabel = p.stockTotal == 0
                    ? "Sin stock"
                    : p.stockTotal == 1 ? "Último" : "En stock";
                // Cantidad de variantes (subproductos) del padre, para
                // mostrar un badge informativo en la tile.
                final numVariantes = _cantidadVariantes(p.codigo);

                return Card(
                  margin: const EdgeInsets.only(bottom: 8),
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                  elevation: 1,
                  child: Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
                    child: Row(children: [
                      // ── Ícono categoría ──────────────────────
                      Container(
                        width: 44, height: 44,
                        decoration: BoxDecoration(
                          color: AppColors.royalBlue.withValues(alpha: 0.08),
                          borderRadius: BorderRadius.circular(10),
                        ),
                        child: Icon(
                          CategoriasProductos.usaIMEI(p.categoria) ? Icons.phone_android
                            : p.categoria == 'Televisor' ? Icons.tv_outlined
                            : Icons.extension_outlined,
                          color: AppColors.royalBlue, size: 22),
                      ),
                      const SizedBox(width: 12),

                      // ── Info del producto ────────────────────
                      Expanded(child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Row(children: [
                            Expanded(child: Text(p.nombre,
                              style: const TextStyle(fontWeight: FontWeight.w600,
                                color: AppColors.textPrimary, fontSize: 14))),
                            // Badge: cuántas variantes tiene este producto
                            if (numVariantes > 0) ...[
                              const SizedBox(width: 6),
                              Container(
                                padding: const EdgeInsets.symmetric(
                                    horizontal: 8, vertical: 3),
                                decoration: BoxDecoration(
                                  color: AppColors.brandBlue
                                      .withValues(alpha: 0.12),
                                  borderRadius: BorderRadius.circular(10),
                                  border: Border.all(
                                      color: AppColors.brandBlue
                                          .withValues(alpha: 0.3)),
                                ),
                                child: Row(
                                    mainAxisSize: MainAxisSize.min,
                                    children: [
                                  const Icon(Icons.account_tree_outlined,
                                      size: 12,
                                      color: AppColors.brandBlue),
                                  const SizedBox(width: 3),
                                  Text(
                                      "$numVariantes "
                                      "${numVariantes == 1 ? 'variante' : 'variantes'}",
                                      style: const TextStyle(
                                          fontSize: 10,
                                          fontWeight: FontWeight.w700,
                                          color: AppColors.brandBlue)),
                                ]),
                              ),
                            ],
                          ]),
                          const SizedBox(height: 2),
                          Text("${p.codigo} · ${p.categoria} · ${p.marca}",
                            style: const TextStyle(fontSize: 11, color: AppColors.textSecondary)),
                          const SizedBox(height: 4),
                          Row(children: [
                            Text("Costo: ${formatCurrency(p.precioCosto)}",
                              style: const TextStyle(fontSize: 11, color: AppColors.textSecondary)),
                            const SizedBox(width: 8),
                            Text("Venta: ${formatCurrency(p.precioVenta)}",
                              style: const TextStyle(fontSize: 11,
                                color: AppColors.primaryBlue, fontWeight: FontWeight.w500)),
                          ]),
                        ],
                      )),

                      // ── STOCK DESTACADO ──────────────────────
                      Column(mainAxisAlignment: MainAxisAlignment.center, children: [
                        InkWell(
                          borderRadius: BorderRadius.circular(10),
                          // Tocar el número abre el teclado para escribir
                          // la cantidad exacta (útil al cargar una caja
                          // entera). Solo en productos sin IMEI.
                          onTap: (!CategoriasProductos.usaIMEI(p.categoria) &&
                                  !p.esSubproducto)
                              ? () => _editarStockDirecto(p)
                              : null,
                          child: Container(
                            width: 54,
                            padding: const EdgeInsets.symmetric(vertical: 6),
                            decoration: BoxDecoration(
                              color: stockColor,
                              borderRadius: BorderRadius.circular(10),
                            ),
                            child: Column(children: [
                              Text("${p.stockTotal}",
                                textAlign: TextAlign.center,
                                style: const TextStyle(fontWeight: FontWeight.bold,
                                  fontSize: 22, color: Colors.white, height: 1.1)),
                              Text("uds", textAlign: TextAlign.center,
                                style: const TextStyle(fontSize: 9,
                                  color: Colors.white70, letterSpacing: 0.5)),
                            ]),
                          ),
                        ),
                        const SizedBox(height: 3),
                        Text(stockLabel,
                          style: TextStyle(fontSize: 9,
                            fontWeight: FontWeight.w600, color: stockColor)),
                      ]),

                      // ── AJUSTE RÁPIDO DE STOCK ───────────────
                      // Solo para productos SIN IMEI (accesorios,
                      // forros, cargadores...). Los que llevan IMEI
                      // suman stock registrando cada equipo, así que
                      // acá no tiene sentido tocarles el contador.
                      //
                      // Antes había que entrar a la ficha completa del
                      // producto para cambiar una cantidad. Con esto se
                      // suma o resta desde la misma lista.
                      if (!CategoriasProductos.usaIMEI(p.categoria) &&
                          !p.esSubproducto) ...[
                        const SizedBox(width: 4),
                        Column(mainAxisSize: MainAxisSize.min, children: [
                          _BotonStockRapido(
                            icono: Icons.add,
                            color: AppColors.statusGreen,
                            tooltip: 'Sumar 1 unidad',
                            onTap: () => _ajusteRapido(p, 1),
                          ),
                          const SizedBox(height: 4),
                          _BotonStockRapido(
                            icono: Icons.remove,
                            color: AppColors.statusRed,
                            tooltip: 'Restar 1 unidad',
                            onTap: p.stockManual > 0
                                ? () => _ajusteRapido(p, -1)
                                : null,
                          ),
                        ]),
                      ],
                      const SizedBox(width: 6),

                      // ── Botón editar ─────────────────────────
                      IconButton(
                        icon: const Icon(Icons.edit_outlined,
                          color: AppColors.primaryBlue, size: 20),
                        padding: EdgeInsets.zero,
                        constraints: const BoxConstraints(),
                        onPressed: () async {
                          await Navigator.push(context, MaterialPageRoute(
                            builder: (c) => FormularioProducto(productoAEditar: p)));
                          if (mounted) _cargar();
                        }),

                      // ── PUNTO 1: Botón eliminar producto ──────
                      // Solo roles con permiso (Maestro/Administrador/Dueño).
                      if (usuarioSesion?.rol == "Maestro" ||
                          usuarioSesion?.rol == "Administrador" ||
                          usuarioSesion?.rol == "Dueño") ...[
                        const SizedBox(width: 2),
                        IconButton(
                          icon: const Icon(Icons.delete_outline,
                            color: AppColors.statusRed, size: 20),
                          padding: EdgeInsets.zero,
                          constraints: const BoxConstraints(),
                          onPressed: () => _eliminarProducto(p)),
                      ],
                    ]),
                  ),
                );
              },
            ),
          )),
      ]),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: () async {
          // La tienda que el usuario está viendo se lleva al
          // formulario ya seleccionada: si el dueño está mirando
          // "Sucursal", el producto nuevo entra en Sucursal sin que
          // tenga que elegirla otra vez.
          await Navigator.push(context, MaterialPageRoute(
              builder: (c) => FormularioProducto(
                    tiendaInicial: _tiendaFiltro,
                  )));
          if (mounted) _cargar();
        },
        icon: const Icon(Icons.add, color: Colors.white),
        label: Text(
            _tiendaFiltro.isEmpty
                ? "Nuevo Producto"
                : "Nuevo en $_tiendaFiltro",
            style: const TextStyle(color: Colors.white)),
      ),
    );
  }
}

// ════════════════════════════════════════════════════════════
//  INGRESO RÁPIDO DE STOCK — carga de mercancía en volumen
// ════════════════════════════════════════════════════════════
//  Pensada para descargar una caja entera: se escanea (o teclea) el
//  código, se pone la cantidad, Enter, y el foco vuelve al campo de
//  código listo para el siguiente. Nada se guarda hasta apretar
//  "Guardar todo", así que un error se corrige antes de tocar la BD.
//
//  Solo trabaja con productos SIN IMEI. Los que llevan IMEI suman
//  stock registrando cada equipo con su número de serie, que es lo
//  que hace la ventana de IMEIs.
// ════════════════════════════════════════════════════════════

/// Una línea de la carga en curso (todavía sin guardar).
class _LineaIngresoStock {
  final Producto producto;
  int cantidad;
  _LineaIngresoStock(this.producto, this.cantidad);
}

class VentanaIngresoStock extends StatefulWidget {
  /// Tienda activa. Solo se ofrecen productos de esta tienda (o del
  /// inventario general). Vacío = sin restricción.
  final String tienda;
  const VentanaIngresoStock({super.key, this.tienda = ''});
  @override
  State<VentanaIngresoStock> createState() => _VentanaIngresoStockState();
}

class _VentanaIngresoStockState extends State<VentanaIngresoStock> {
  final _codigoCtrl = TextEditingController();
  final _cantidadCtrl = TextEditingController(text: '1');
  final _focoCodigo = FocusNode();
  final _focoCantidad = FocusNode();

  /// Tienda a la que entra la mercancía de esta carga. Arranca con la
  /// que traía la pantalla de Inventario y el dueño la puede cambiar
  /// desde la barra superior sin salir de acá.
  late String _tienda;

  /// ¿Este usuario puede cargar mercancía en cualquier tienda?
  bool get _puedeElegirTienda {
    final rol = usuarioSesion?.rol ?? '';
    return rol == 'Maestro' || rol == 'Dueño' || rol == 'Administrador';
  }

  /// Catálogo de productos sin IMEI disponibles para cargar.
  List<Producto> _catalogo = [];
  /// Líneas cargadas en esta sesión, la más reciente primero.
  final List<_LineaIngresoStock> _lineas = [];
  bool _cargando = true;
  bool _guardando = false;
  /// Producto que coincide con lo tecleado ahora mismo (preview).
  Producto? _encontrado;

  @override
  void initState() {
    super.initState();
    _tienda = widget.tienda.trim();
    _cargarCatalogo();
  }

  @override
  void dispose() {
    _codigoCtrl.dispose();
    _cantidadCtrl.dispose();
    _focoCodigo.dispose();
    _focoCantidad.dispose();
    super.dispose();
  }

  Future<void> _cargarCatalogo() async {
    setState(() => _cargando = true);
    try {
      final raw = await _Api.get('productos');
      final todos =
          ((raw as List?) ?? []).map((m) => Producto.fromMap(m)).toList();
      final t = _tienda;
      _catalogo = todos.where((p) {
        // Sin IMEI: el stock es un contador y se puede ajustar acá.
        if (CategoriasProductos.usaIMEI(p.categoria)) return false;
        // Respetar la tienda: no se carga stock de otro local.
        if (t.isNotEmpty && p.tienda.isNotEmpty && p.tienda != t) {
          return false;
        }
        return true;
      }).toList();
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text('Error al cargar productos: $e'),
          backgroundColor: AppColors.statusRed));
      }
    } finally {
      if (mounted) {
        setState(() => _cargando = false);
        _focoCodigo.requestFocus();
      }
    }
  }

  /// Busca por código exacto primero; si no hay, por coincidencia de
  /// nombre. Devuelve null si nada matchea.
  Producto? _buscar(String texto) {
    final q = texto.trim().toLowerCase();
    if (q.isEmpty) return null;
    final exacto =
        _catalogo.where((p) => p.codigo.toLowerCase() == q).firstOrNull;
    if (exacto != null) return exacto;
    return _catalogo
        .where((p) => p.nombre.toLowerCase().contains(q))
        .firstOrNull;
  }

  /// Agrega la línea actual a la lista pendiente.
  void _agregarLinea() {
    final prod = _encontrado ?? _buscar(_codigoCtrl.text);
    if (prod == null) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text('No se encontró ningún producto sin IMEI con '
            '"${_codigoCtrl.text.trim()}"'),
        backgroundColor: AppColors.statusOrange));
      return;
    }
    final cant = int.tryParse(_cantidadCtrl.text.trim()) ?? 0;
    if (cant == 0) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text('Ingresá una cantidad distinta de cero'),
        backgroundColor: AppColors.statusOrange));
      return;
    }
    setState(() {
      // Si el producto ya está en la lista, acumulamos en vez de
      // duplicar la fila — así escanear dos veces el mismo código
      // suma, que es lo que uno espera al descargar una caja.
      final existente = _lineas
          .where((l) => l.producto.codigo == prod.codigo)
          .firstOrNull;
      if (existente != null) {
        existente.cantidad += cant;
      } else {
        _lineas.insert(0, _LineaIngresoStock(prod, cant));
      }
      _codigoCtrl.clear();
      _cantidadCtrl.text = '1';
      _encontrado = null;
    });
    _focoCodigo.requestFocus();
  }

  /// Aplica todas las líneas pendientes al inventario.
  Future<void> _guardarTodo() async {
    if (_lineas.isEmpty) return;
    setState(() => _guardando = true);
    final messenger = ScaffoldMessenger.of(context);
    final navigator = Navigator.of(context);
    int ok = 0;
    final fallidos = <String>[];
    for (final linea in _lineas) {
      // Si el producto todavía no tenía tienda (inventario general) y
      // acá se está cargando en una tienda concreta, queda asignado a
      // ella: es la única forma de que ese stock sea de ESE local y no
      // aparezca como disponible en los otros.
      if (_tienda.isNotEmpty && linea.producto.tienda.trim().isEmpty) {
        linea.producto.tienda = _tienda;
      }
      final res = await ajustarStockManual(linea.producto, linea.cantidad);
      if (res.ok) {
        ok++;
      } else {
        fallidos.add('${linea.producto.nombre}: ${res.mensaje}');
      }
    }
    if (!mounted) return;
    setState(() => _guardando = false);
    if (fallidos.isEmpty) {
      messenger.showSnackBar(SnackBar(
        content: Text('$ok ${ok == 1 ? "producto actualizado" : "productos actualizados"}'),
        backgroundColor: AppColors.statusGreen));
      navigator.pop(true);
      return;
    }
    // Algo falló: dejamos la pantalla abierta con las líneas que no
    // se guardaron, para poder reintentar sin volver a escanear todo.
    setState(() {
      _lineas.removeWhere((l) =>
          !fallidos.any((f) => f.startsWith(l.producto.nombre)));
    });
    messenger.showSnackBar(SnackBar(
      content: Text('$ok guardados, ${fallidos.length} con error. '
          '${fallidos.first}'),
      backgroundColor: AppColors.statusRed,
      duration: const Duration(seconds: 7)));
  }

  @override
  Widget build(BuildContext context) {
    final totalUnidades =
        _lineas.fold<int>(0, (s, l) => s + l.cantidad);
    return Scaffold(
      backgroundColor: AppColors.surfaceTintBlue,
      appBar: AppBar(
        backgroundColor: AppColors.royalBlue,
        foregroundColor: Colors.white,
        title: Text(_tienda.isEmpty
            ? 'Ingreso rápido de stock'
            : 'Ingreso de stock · $_tienda'),
        actions: [
          // Cambiar de tienda sin salir de la pantalla (sólo roles
          // que manejan más de un local).
