                  ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
                    content: Text('Guardá o quitá las líneas pendientes '
                        'antes de cambiar de tienda'),
                    backgroundColor: AppColors.statusOrange));
                  return;
                }
                setState(() => _tienda = v);
                _cargarCatalogo();
              },
              itemBuilder: (_) => [
                const PopupMenuItem(
                    value: '', child: Text('📍 Inventario general')),
                const PopupMenuDivider(),
                ...ConfigSistema.tiendas.map((t) => PopupMenuItem(
                    value: t, child: Text(t))),
              ],
            ),
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: 'Recargar catálogo',
            onPressed: _cargando ? null : _cargarCatalogo),
        ],
      ),
      body: _cargando
          ? const Center(child: CircularProgressIndicator())
          : Column(children: [
              // ── Formulario de carga ──────────────────────────
              Container(
                color: Colors.white,
                padding: const EdgeInsets.all(14),
                child: Column(children: [
                  if (_tienda.isNotEmpty) ...[
                    Container(
                      width: double.infinity,
                      padding: const EdgeInsets.symmetric(
                          horizontal: 10, vertical: 8),
                      decoration: BoxDecoration(
                        color: AppColors.royalBlue.withValues(alpha: 0.07),
                        borderRadius: BorderRadius.circular(8),
                        border: Border.all(
                            color:
                                AppColors.royalBlue.withValues(alpha: 0.3)),
                      ),
                      child: Row(children: [
                        const Icon(Icons.storefront_outlined,
                            size: 16, color: AppColors.royalBlue),
                        const SizedBox(width: 6),
                        Expanded(
                          child: Text(
                            'Esta mercancía entra en "$_tienda". Los '
                            'productos que todavía no tengan tienda '
                            'quedarán asignados a ella.',
                            style: const TextStyle(
                                fontSize: 11, color: AppColors.royalBlue),
                          ),
                        ),
                      ]),
                    ),
                    const SizedBox(height: 10),
                  ],
                  Row(children: [
                    Expanded(
                      child: TextField(
                        controller: _codigoCtrl,
                        focusNode: _focoCodigo,
                        textInputAction: TextInputAction.next,
                        decoration: InputDecoration(
                          labelText: 'Código o nombre',
                          prefixIcon: const Icon(Icons.qr_code),
                          border: const OutlineInputBorder(),
                          helperText: _encontrado?.nombre,
                          helperStyle: const TextStyle(
                              color: AppColors.statusGreen,
                              fontWeight: FontWeight.w600),
                        ),
                        onChanged: (v) =>
                            setState(() => _encontrado = _buscar(v)),
                        onSubmitted: (_) => _focoCantidad.requestFocus(),
                      ),
                    ),
                    const SizedBox(width: 8),
                    // Escanear con la cámara
                    IconButton.filled(
                      icon: const Icon(Icons.camera_alt),
                      tooltip: 'Escanear código',
                      style: IconButton.styleFrom(
                          backgroundColor: AppColors.royalBlue,
                          foregroundColor: Colors.white),
                      onPressed: () {
                        Navigator.push(
                            context,
                            MaterialPageRoute(
                                builder: (_) => ScannerPage(onDetect: (code) {
                                      _codigoCtrl.text = code;
                                      setState(() =>
                                          _encontrado = _buscar(code));
                                      _focoCantidad.requestFocus();
                                    })));
                      },
                    ),
                  ]),
                  const SizedBox(height: 10),
                  Row(children: [
                    SizedBox(
                      width: 120,
                      child: TextField(
                        controller: _cantidadCtrl,
                        focusNode: _focoCantidad,
                        keyboardType: TextInputType.number,
                        textAlign: TextAlign.center,
                        textInputAction: TextInputAction.done,
                        style: const TextStyle(
                            fontSize: 20, fontWeight: FontWeight.bold),
                        decoration: const InputDecoration(
                          labelText: 'Cantidad',
