                    : ListView.builder(
                        padding: const EdgeInsets.all(12),
                        itemCount: _lineas.length,
                        itemBuilder: (c, i) {
                          final l = _lineas[i];
                          final suma = l.cantidad > 0;
                          return Card(
                            margin: const EdgeInsets.only(bottom: 8),
                            child: ListTile(
                              leading: CircleAvatar(
