                    top: false,
                    child: Row(children: [
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text('${_lineas.length} '
                                '${_lineas.length == 1 ? "producto" : "productos"}',
                                style: const TextStyle(
                                    fontWeight: FontWeight.bold,
                                    fontSize: 15)),
                            Text('$totalUnidades unidades en total',
                                style: const TextStyle(
                                    fontSize: 12,
                                    color: AppColors.textSecondary)),
