}

/// Botón compacto +/− para ajustar stock desde la lista de inventario.
/// Se deshabilita solo (gris, sin onTap) cuando [onTap] es null —
/// por ejemplo el "−" cuando el stock ya está en 0.
class _BotonStockRapido extends StatelessWidget {
  final IconData icono;
  final Color color;
  final String tooltip;
  final VoidCallback? onTap;
  const _BotonStockRapido({
    required this.icono,
    required this.color,
    required this.tooltip,
    this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final habilitado = onTap != null;
    final c = habilitado ? color : Colors.grey[400]!;
    return Tooltip(
      message: tooltip,
      child: InkWell(
        onTap: onTap,
        borderRadius: BorderRadius.circular(8),
        child: Container(
          width: 30,
          height: 26,
          decoration: BoxDecoration(
            color: c.withValues(alpha: habilitado ? 0.12 : 0.06),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(color: c.withValues(alpha: 0.45)),
          ),
          child: Icon(icono, size: 17, color: c),
        ),
      ),
    );
  }
}

// ============================================================
//  INVENTARIO FÍSICO — escanea o escribe IMEIs/códigos y cuenta
//  cuántos productos físicos hay vs el inventario teórico del
//  sistema. Permite detectar diferencias (faltantes / sobrantes).
// ============================================================
class VentanaInventarioFisico extends StatefulWidget {
  final String tiendaFiltro;
  const VentanaInventarioFisico({super.key, required this.tiendaFiltro});
  @override
  State<VentanaInventarioFisico> createState() =>
      _VentanaInventarioFisicoState();
}

class _VentanaInventarioFisicoState
    extends State<VentanaInventarioFisico> {
  final _codigoCtrl = TextEditingController();
  final _focusCodigo = FocusNode();

  /// IMEIs esperados según el inventario teórico (vienen de la BD).
  /// Solo para productos cuyas categorías usen IMEI.
  Set<String> _imeisEsperados = {};

  /// IMEIs ya inventariados físicamente (los que el usuario escaneó).
  Set<String> _imeisInventariados = {};

  /// Códigos esperados de productos SIN IMEI (con stock manual).
  /// Mapa código → cantidad teórica
  Map<String, int> _codigosEsperados = {};

  /// Códigos inventariados con cantidad contada
  Map<String, int> _codigosContados = {};

  /// IMEIs/códigos escaneados que NO están en el sistema (sobrantes
  /// detectados que el usuario debe registrar manualmente o que están
  /// en otra tienda).
  List<String> _noReconocidos = [];

  /// Productos que ya estaban inventariados (para mostrar listado).
  /// Cada entrada tiene: producto, imei (opcional), tiempo
  final List<Map<String, dynamic>> _historialEscaneos = [];

  bool _cargando = true;
  bool _soloFaltantes = false;
  String _filtroCategoria = 'Todas';

  @override
  void initState() {
    super.initState();
    _cargar();
  }

  @override
  void dispose() {
    _codigoCtrl.dispose();
    _focusCodigo.dispose();
    super.dispose();
  }

  /// Carga el inventario teórico desde el sistema para la tienda
  /// indicada (todas si está vacía).
  Future<void> _cargar() async {
    if (!mounted) return;
    setState(() => _cargando = true);
    try {
      // ─── IMEIs esperados ───
      final imeisFiltrados = stockImeiGlobal.where((i) {
        if (i.vendido) return false;
        if (widget.tiendaFiltro.isEmpty) return true;
        // ImeiRegistro guarda la tienda/ubicación en `ubicacion`
        return i.ubicacion == widget.tiendaFiltro;
      }).toList();
      _imeisEsperados = imeisFiltrados.map((i) => i.imei).toSet();

      // ─── Productos sin IMEI (stock manual) ───
      _codigosEsperados.clear();
      for (final p in catalogoGlobal) {
        if (p.esSubproducto) continue;
        // Solo productos cuya categoría NO usa IMEI
        if (CategoriasProductos.usaIMEI(p.categoria)) continue;
        // TODO: filtrar por tienda si tu Producto tiene stock por tienda
        if (p.stockManual > 0) {
          _codigosEsperados[p.codigo] = p.stockManual;
        }
      }
    } catch (e) {
      debugPrint('[InvFisico] Error cargando: $e');
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  /// Procesa un código/IMEI escaneado o escrito por el usuario.
  void _procesarCodigo(String raw) {
    final codigo = raw.trim();
    if (codigo.isEmpty) return;

    // ¿Es un IMEI esperado?
    if (_imeisEsperados.contains(codigo)) {
      if (_imeisInventariados.contains(codigo)) {
        _mostrarSnackbar(
            '⚠️ Ya escaneado: $codigo', Colors.orange);
      } else {
        setState(() {
          _imeisInventariados.add(codigo);
          // Buscar producto sin orElse — si no se encuentra, usamos
          // un nombre genérico (no necesitamos crear un Producto fake)
          String nombreProd = '(producto desconocido)';
          try {
            final imei = stockImeiGlobal.firstWhere(
                (i) => i.imei == codigo);
            nombreProd = imei.producto.nombre.isEmpty
                ? '(sin nombre)'
                : imei.producto.nombre;
          } catch (_) {}
          _historialEscaneos.insert(0, {
            'codigo': codigo,
            'tipo': 'IMEI',
            'producto': nombreProd,
            'tiempo': DateTime.now(),
          });
        });
        _mostrarSnackbar(
            '✓ IMEI registrado', AppColors.statusGreen);
      }
    }
    // ¿Es un código de producto esperado (sin IMEI)?
    else if (_codigosEsperados.containsKey(codigo)) {
      setState(() {
        _codigosContados[codigo] = (_codigosContados[codigo] ?? 0) + 1;
        // Buscar producto en el catálogo (sin orElse fake)
        String nombreProd = '(producto desconocido)';
        try {
          final prod = catalogoGlobal.firstWhere(
              (p) => p.codigo == codigo);
          nombreProd = prod.nombre.isEmpty
              ? '(sin nombre)'
              : prod.nombre;
        } catch (_) {}
        _historialEscaneos.insert(0, {
          'codigo': codigo,
          'tipo': 'CÓDIGO',
          'producto': nombreProd,
          'tiempo': DateTime.now(),
          'cantidad': _codigosContados[codigo],
        });
      });
      _mostrarSnackbar(
          '✓ Producto contado (${_codigosContados[codigo]}/'
          '${_codigosEsperados[codigo]})',
          AppColors.statusGreen);
    } else {
      // No reconocido — puede ser sobrante o producto de otra tienda
      setState(() {
        if (!_noReconocidos.contains(codigo)) {
          _noReconocidos.add(codigo);
        }
        _historialEscaneos.insert(0, {
          'codigo': codigo,
          'tipo': 'NO RECONOCIDO',
          'producto': '?',
          'tiempo': DateTime.now(),
        });
      });
      _mostrarSnackbar(
          '⚠️ No reconocido: $codigo', Colors.orange);
    }

    _codigoCtrl.clear();
    _focusCodigo.requestFocus();
  }

  void _mostrarSnackbar(String texto, Color color) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).clearSnackBars();
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(texto, style: const TextStyle(fontSize: 13)),
      backgroundColor: color,
      duration: const Duration(milliseconds: 1200),
    ));
  }

  /// Reinicia todo el inventario físico.
  Future<void> _reiniciar() async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (c) => AlertDialog(
        title: const Text('Reiniciar inventario'),
        content: const Text('¿Descartar todos los escaneos actuales?'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(c, false),
              child: const Text('Cancelar')),
          ElevatedButton(
              onPressed: () => Navigator.pop(c, true),
              style: ElevatedButton.styleFrom(
                  backgroundColor: AppColors.statusRed),
              child: const Text('Reiniciar',
                  style: TextStyle(color: Colors.white))),
        ],
      ),
    );
    if (ok == true) {
      setState(() {
        _imeisInventariados.clear();
        _codigosContados.clear();
        _noReconocidos.clear();
        _historialEscaneos.clear();
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final totalEsperados = _imeisEsperados.length +
        _codigosEsperados.values.fold<int>(0, (a, b) => a + b);
    final totalContados = _imeisInventariados.length +
        _codigosContados.values.fold<int>(0, (a, b) => a + b);
    final faltantes = totalEsperados - totalContados;
    final porcentaje = totalEsperados > 0
        ? (totalContados / totalEsperados * 100)
        : 0.0;

    return Scaffold(
      appBar: AppBar(
        backgroundColor: AppColors.royalBlue,
        foregroundColor: Colors.white,
        title: const Text('Inventario Físico'),
        actions: [
          IconButton(
              icon: const Icon(Icons.refresh),
              tooltip: 'Reiniciar',
              onPressed: _reiniciar),
        ],
      ),
      body: _cargando
          ? const Center(child: CircularProgressIndicator())
          : Column(children: [
              // ── Banner de progreso ──
              Container(
                color: AppColors.royalBlue,
                padding: const EdgeInsets.all(12),
                child: Column(children: [
                  Row(mainAxisAlignment: MainAxisAlignment.spaceAround,
                      children: [
                    _kpiInvFisico('CONTADOS', '$totalContados',
                        Colors.white),
                    _kpiInvFisico('TOTAL', '$totalEsperados',
                        Colors.white70),
                    _kpiInvFisico('FALTAN',
                        faltantes < 0 ? '0' : '$faltantes',
                        faltantes > 0
                            ? AppColors.statusYellow
                            : AppColors.statusGreen),
                    _kpiInvFisico('SOBRAN', '${_noReconocidos.length}',
                        _noReconocidos.isEmpty
                            ? Colors.white70
                            : AppColors.statusOrange),
                  ]),
                  const SizedBox(height: 12),
                  // Barra de progreso
                  ClipRRect(
                    borderRadius: BorderRadius.circular(8),
                    child: LinearProgressIndicator(
                      value: totalEsperados > 0
                          ? totalContados / totalEsperados
                          : 0,
                      minHeight: 8,
                      backgroundColor: Colors.white24,
                      valueColor: AlwaysStoppedAnimation(
                          porcentaje >= 100
