  Widget _kpiInvFisico(String label, String valor, Color color) {
    return Column(children: [
      Text(valor,
          style: TextStyle(
              fontSize: 20, fontWeight: FontWeight.bold, color: color)),
      Text(label,
          style: TextStyle(fontSize: 10, color: color.withValues(alpha: 0.8))),
    ]);
  }

  /// Tab con la lista de productos pendientes de inventariar.
  Widget _tabAInventariar() {
    // Agrupar por producto
    final filas = <Map<String, dynamic>>[];
    // IMEIs por producto
    final imeisPorProd = <String, List<String>>{};
    for (final imei in _imeisEsperados) {
      // Buscar el registro del IMEI; si no se encuentra, saltamos
      String? codigoProd;
      try {
        final reg = stockImeiGlobal.firstWhere((i) => i.imei == imei);
        codigoProd = reg.producto.codigo;
      } catch (_) {
        codigoProd = null;
      }
      if (codigoProd == null || codigoProd.isEmpty) continue;
      imeisPorProd.putIfAbsent(codigoProd, () => []).add(imei);
    }
    imeisPorProd.forEach((codigo, imeis) {
      // Buscar producto; si no existe en catálogo, saltamos
      Producto? prod;
      try {
        prod = catalogoGlobal.firstWhere((p) => p.codigo == codigo);
      } catch (_) {
        prod = null;
      }
      if (prod == null) return;
      final inventariados = imeis
          .where((i) => _imeisInventariados.contains(i)).length;
      if (_soloFaltantes && inventariados >= imeis.length) return;
      filas.add({
        'producto': prod,
        'usa_imei': true,
        'esperados': imeis.length,
        'contados': inventariados,
        'imeis': imeis,
      });
    });
    _codigosEsperados.forEach((codigo, cantidad) {
      Producto? prod;
      try {
        prod = catalogoGlobal.firstWhere((p) => p.codigo == codigo);
      } catch (_) {
        prod = null;
      }
      if (prod == null) return;
      final contados = _codigosContados[codigo] ?? 0;
      if (_soloFaltantes && contados >= cantidad) return;
      filas.add({
        'producto': prod,
        'usa_imei': false,
        'esperados': cantidad,
        'contados': contados,
      });
    });
    filas.sort((a, b) {
      final pa = (a['producto'] as Producto);
      final pb = (b['producto'] as Producto);
      return pa.nombre.toLowerCase().compareTo(pb.nombre.toLowerCase());
    });

    if (filas.isEmpty) {
      return Center(child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(_soloFaltantes ? Icons.check_circle : Icons.inventory,
                size: 60, color: Colors.grey),
            const SizedBox(height: 12),
            Text(
                _soloFaltantes
                    ? '¡Sin faltantes! Inventario completo.'
                    : 'No hay productos a inventariar',
                style: const TextStyle(fontSize: 14, color: Colors.grey)),
          ]));
    }

    return ListView.builder(
      itemCount: filas.length,
      itemBuilder: (c, i) {
        final f = filas[i];
        final prod = f['producto'] as Producto;
        final contados = f['contados'] as int;
        final esperados = f['esperados'] as int;
        final completo = contados >= esperados;
        return Container(
          margin: const EdgeInsets.symmetric(
              horizontal: 10, vertical: 3),
          decoration: BoxDecoration(
            color: completo
                ? AppColors.statusGreen.withValues(alpha: 0.05)
                : Colors.white,
            borderRadius: BorderRadius.circular(8),
            border: Border.all(
                color: completo
                    ? AppColors.statusGreen.withValues(alpha: 0.3)
                    : Colors.grey[300]!),
          ),
          child: ListTile(
            dense: true,
            leading: Icon(
                completo
                    ? Icons.check_circle
                    : Icons.inventory_2_outlined,
                color: completo
                    ? AppColors.statusGreen
                    : AppColors.royalBlue),
            title: Text(prod.nombre,
                style: const TextStyle(
                    fontSize: 13, fontWeight: FontWeight.w600)),
            subtitle: Text(
                '${prod.marca} · ${prod.modelo} '
                '${(f['usa_imei'] as bool) ? "· con IMEI" : "· stock manual"}',
                style: const TextStyle(fontSize: 11)),
            trailing: Text('$contados / $esperados',
                style: TextStyle(
                    fontSize: 14,
                    fontWeight: FontWeight.bold,
                    color: completo
                        ? AppColors.statusGreen
                        : (contados > 0
                            ? AppColors.statusYellow
                            : Colors.grey[600]))),
          ),
        );
      },
    );
  }

  /// Tab con los códigos no reconocidos (sobrantes / errores)
  Widget _tabSobrantes() {
    if (_noReconocidos.isEmpty) {
      return const Center(child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(Icons.check_circle, size: 60, color: Colors.green),
            SizedBox(height: 12),
            Text('Sin sobrantes ni errores',
                style: TextStyle(fontSize: 14, color: Colors.grey)),
          ]));
    }
    return ListView.builder(
      itemCount: _noReconocidos.length,
      itemBuilder: (c, i) {
        final cod = _noReconocidos[i];
        return ListTile(
          dense: true,
          leading: const Icon(Icons.warning, color: Colors.orange),
          title: Text(cod, style: const TextStyle(fontFamily: 'monospace')),
          subtitle: const Text(
              'No coincide con ningún producto/IMEI del sistema',
              style: TextStyle(fontSize: 11)),
          trailing: IconButton(
            icon: const Icon(Icons.delete_outline, size: 18),
            onPressed: () =>
                setState(() => _noReconocidos.removeAt(i)),
          ),
        );
      },
    );
  }

  /// Tab con el historial completo de escaneos
  Widget _tabHistorial() {
    if (_historialEscaneos.isEmpty) {
      return const Center(child: Text(
          'Aún no has escaneado nada',
          style: TextStyle(color: Colors.grey)));
    }
    return ListView.builder(
      itemCount: _historialEscaneos.length,
      itemBuilder: (c, i) {
        final h = _historialEscaneos[i];
        final t = h['tipo'] as String;
        return ListTile(
          dense: true,
          leading: Icon(
              t == 'NO RECONOCIDO'
                  ? Icons.warning
                  : Icons.check_circle,
              color: t == 'NO RECONOCIDO'
                  ? Colors.orange
                  : AppColors.statusGreen,
              size: 20),
          title: Text(
              '${h['producto']}',
              style: const TextStyle(fontSize: 12)),
          subtitle: Text('${h['codigo']} · $t',
              style: const TextStyle(
                  fontSize: 10, fontFamily: 'monospace')),
          trailing: Text(
              _fmtHora(h['tiempo'] as DateTime),
              style: const TextStyle(
                  fontSize: 10, color: AppColors.textSecondary)),
        );
      },
    );
  }

  String _fmtHora(DateTime d) =>
      '${d.hour.toString().padLeft(2, '0')}:'
      '${d.minute.toString().padLeft(2, '0')}:'
      '${d.second.toString().padLeft(2, '0')}';
}

// ============================================================
//  FORMULARIO PRODUCTO — guarda en la API
// ============================================================
class FormularioProducto extends StatefulWidget {
  final Producto? productoAEditar;
  /// Tienda con la que arranca el formulario al CREAR un producto.
  /// La manda la pantalla de Inventario con la tienda que el usuario
  /// está viendo, para que el dueño no tenga que elegirla de nuevo.
  /// Vacío = usar la tienda de la sesión.
  final String tiendaInicial;
  const FormularioProducto({
    super.key,
    this.productoAEditar,
    this.tiendaInicial = '',
  });
  @override State<FormularioProducto> createState() => _FormularioProductoState();
}

class _FormularioProductoState extends State<FormularioProducto> {
  late TextEditingController _cod, _nom, _marca, _modelo, _prov, _pc, _pv, _cant, _imeiInput;
  late String _categoria;
  /// Tienda asignada al producto (vacío = sin asignar, solo lo ven
  /// los roles administrativos). El selector usa ConfigSistema.tiendas.
  late String _tienda;
  String _colorSel = "";
  List<String> _imeisTemporales = [];
  /// Variantes (subproductos) que el usuario agrega DURANTE la creación
  /// del producto principal. Quedan en memoria hasta que se guarde el
  /// padre — después se persisten todas en cadena. Al editar, este
  /// arreglo no se usa (las variantes se persisten directamente).
  final List<Producto> _variantesPendientes = [];

  // Marcas conocidas para el autocompletado
  static const _marcasSugeridas = [
    "Apple","Samsung","Xiaomi","Motorola","Huawei","OPPO","Vivo",
    "OnePlus","Realme","Nokia","LG","Sony","ZTE","Alcatel","Honor",
  ];

  @override
  void initState() {
    super.initState();
    final p = widget.productoAEditar;
    _cod      = TextEditingController(text: p?.codigo ?? "");
    _nom      = TextEditingController(text: p?.nombre ?? "");
    _marca    = TextEditingController(text: p?.marca != "Genérico" ? (p?.marca ?? "") : "");
    _modelo   = TextEditingController(text: p?.modelo != "N/A" ? (p?.modelo ?? "") : "");
    _prov     = TextEditingController(text: "");
    _pc       = TextEditingController(text: p?.precioCosto.toString() ?? "");
    _pv       = TextEditingController(text: p?.precioVenta.toString() ?? "");
    _cant     = TextEditingController(text: p?.stockManual.toString() ?? "0");
    _imeiInput = TextEditingController();
    _categoria = p?.categoria ?? "Accesorio";
    // Tienda inicial: si edito, la del producto. Si creo, la tienda
    // de la sesión del usuario (si la tiene) — así los productos se
    // asignan automáticamente a la tienda de quien los registra.
    // Al CREAR: la tienda que venga de la pantalla que abrió el
    // formulario (el dueño ya eligió una en Inventario) y, si no
    // vino ninguna, la de la sesión. Al EDITAR: la del producto.
    _tienda = p?.tienda ??
        (widget.tiendaInicial.trim().isNotEmpty
            ? widget.tiendaInicial.trim()
            : (usuarioSesion?.tienda ?? ''));
    if (p != null && CategoriasProductos.usaIMEI(p.categoria)) {
      _imeisTemporales = stockImeiGlobal
          .where((i) => i.producto.codigo == p.codigo && !i.vendido)
          .map((i) => i.imei).toList();
    }
  }

  @override
  void dispose() {
    _cod.dispose(); _nom.dispose(); _marca.dispose(); _modelo.dispose();
    _prov.dispose(); _pc.dispose(); _pv.dispose(); _cant.dispose();
    _imeiInput.dispose();
    super.dispose();
  }

  /// Abre un dialog para gestionar las categorías de productos.
  /// Permite agregar, renombrar y eliminar. Al cerrar, la lista
  /// editada queda guardada en SharedPreferences vía
  /// `CategoriasProductos.guardar()`. Si se agrega una categoría
  /// nueva, se sincroniza también una nueva categoría de comisión.
  Future<void> _abrirGestorCategorias() async {
    final nuevoCtrl = TextEditingController();
    await showDialog<void>(
      context: context,
      builder: (ctx) => StatefulBuilder(builder: (ctx, setS) {
        return AlertDialog(
          title: const Row(children: [
            Icon(Icons.category, color: AppColors.brandBlue),
            SizedBox(width: 8),
            Text("Gestionar categorías"),
          ]),
          content: SizedBox(
            width: 420,
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              const Text(
                "Las categorías que crees aquí estarán disponibles "
                "al registrar productos. Al agregar una nueva, también "
                "se crea automáticamente la categoría equivalente en "
                "Comisiones (con tarifa \$0 — la configuras desde la "
                "ventana de Comisiones).",
                style: TextStyle(fontSize: 12,
                    color: AppColors.textSecondary)),
              const SizedBox(height: 12),
              Row(children: [
                Expanded(child: TextField(
                  controller: nuevoCtrl,
                  decoration: const InputDecoration(
                      labelText: "Nueva categoría",
                      isDense: true,
                      border: OutlineInputBorder()),
                )),
                const SizedBox(width: 8),
                FilledButton.icon(
                  icon: const Icon(Icons.add, size: 18),
                  label: const Text("Agregar"),
                  onPressed: () async {
                    final nombre = nuevoCtrl.text.trim();
                    if (nombre.isEmpty) return;
                    final ok = await CategoriasProductos.agregar(nombre);
                    if (ok) {
                      // Crear categoría de comisión equivalente si no existe
                      await _sincronizarCategoriaComision(nombre);
                      nuevoCtrl.clear();
                      setS(() {});
                    } else {
                      if (ctx.mounted) {
                        ScaffoldMessenger.of(ctx).showSnackBar(
                          const SnackBar(content: Text(
                              "Esa categoría ya existe")));
                      }
                    }
                  },
                ),
              ]),
              const SizedBox(height: 12),
              const Divider(),
              ConstrainedBox(
                constraints: const BoxConstraints(maxHeight: 320),
                child: ListView.separated(
                  shrinkWrap: true,
                  itemCount: CategoriasProductos.lista.length,
                  separatorBuilder: (_,__) => const Divider(height: 1),
                  itemBuilder: (_, i) {
                    final cat = CategoriasProductos.lista[i];
                    return ListTile(
                      dense: true,
                      leading: const Icon(Icons.label_outline),
                      title: Text(cat),
                      trailing: Row(mainAxisSize: MainAxisSize.min, children: [
                        IconButton(
                          icon: const Icon(Icons.edit_outlined, size: 18),
                          tooltip: "Renombrar",
                          onPressed: () async {
                            final ctrl = TextEditingController(text: cat);
                            final nuevo = await showDialog<String>(
                              context: ctx,
                              builder: (c) => AlertDialog(
                                title: const Text("Renombrar"),
                                content: TextField(controller: ctrl,
                                    autofocus: true),
                                actions: [
                                  TextButton(
                                    onPressed: () => Navigator.pop(c),
                                    child: const Text("Cancelar")),
                                  FilledButton(
                                    onPressed: () => Navigator.pop(c,
                                        ctrl.text.trim()),
                                    child: const Text("Guardar")),
                                ],
                              ),
                            );
                            if (nuevo != null && nuevo.isNotEmpty
                                && nuevo != cat) {
                              await CategoriasProductos.renombrar(cat, nuevo);
                              setS(() {});
                            }
                          },
                        ),
                        IconButton(
                          icon: const Icon(Icons.delete_outline,
                              size: 18, color: Colors.red),
                          tooltip: "Eliminar",
                          onPressed: () async {
                            final ok = await showDialog<bool>(
                              context: ctx,
                              builder: (c) => AlertDialog(
                                title: const Text("Eliminar categoría"),
                                content: Text(
                                    "¿Eliminar la categoría \"$cat\"?\n"
                                    "Los productos con esta categoría no "
                                    "se eliminan, pero quedarán con la "
                                    "categoría asignada."),
                                actions: [
                                  TextButton(
                                    onPressed: () => Navigator.pop(c, false),
                                    child: const Text("Cancelar")),
                                  FilledButton(
                                    style: FilledButton.styleFrom(
                                        backgroundColor: Colors.red),
                                    onPressed: () => Navigator.pop(c, true),
                                    child: const Text("Eliminar")),
                                ],
                              ),
                            );
                            if (ok == true) {
                              await CategoriasProductos.eliminar(cat);
                              setS(() {});
                            }
                          },
                        ),
                      ]),
                    );
                  },
                ),
              ),
            ]),
          ),
          actions: [
            FilledButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text("Cerrar")),
          ],
        );
      }),
    );
  }

  /// Cuando se agrega una nueva categoría de producto, también
  /// crea la entrada equivalente en categorías de comisión (si no
  /// existía ya). El admin después configura la tarifa desde la
  /// ventana de Comisiones.
  Future<void> _sincronizarCategoriaComision(String nombre) async {
    // ¿Ya existe una comisión con ese mismo nombre?
    final yaExiste = ConfigSistema.categoriasComision.any(
        (c) => c.nombre.toLowerCase().trim()
            == nombre.toLowerCase().trim());
    if (yaExiste) return;
    // Crear con tarifa 0 — el admin la ajustará
    ConfigSistema.categoriasComision.add(CategoriaComision(
      id: 'cat_${DateTime.now().millisecondsSinceEpoch}',
      nombre: nombre,
      tarifaUSD: 0.0,
      tipoConteo: TipoConteoComision.categoriaProducto,
      valorConteo: nombre,
      iconoKey: 'work',
      colorHex: '#1565C0',
    ));
    await ConfigSistema.guardarCategoriasComision();
  }

  /// ¿El usuario puede asignar productos a CUALQUIER tienda?
  /// Solo Maestro, Dueño y Administrador. Los demás roles quedan
  /// fijados a su tienda.
  bool get _puedeElegirCualquierTienda {
    final rol = usuarioSesion?.rol ?? '';
    return rol == 'Maestro' || rol == 'Dueño' || rol == 'Administrador';
  }

  /// Construye el selector de tienda del formulario de producto.
  ///
  /// Va PRIMERO y dentro de una tarjeta destacada porque es el campo
  /// que decide en qué local queda la mercancía: el stock y los IMEIs
  /// que se carguen abajo se registran en la tienda elegida acá. Antes
  /// pasaba desapercibido entre los demás campos y el producto
  /// terminaba en la tienda equivocada.
  Widget _construirSelectorTienda() {
    final tiendas = List<String>.from(ConfigSistema.tiendas);
    // Si _tienda actual no está en la lista (caso de tienda eliminada),
    // la agregamos para no romper el dropdown.
    if (_tienda.isNotEmpty && !tiendas.contains(_tienda)) {
      tiendas.add(_tienda);
    }
    final puedeElegir = _puedeElegirCualquierTienda;
    final esTelefono = CategoriasProductos.usaIMEI(_categoria);
    return Container(
      padding: const EdgeInsets.fromLTRB(14, 10, 14, 14),
      decoration: BoxDecoration(
        color: AppColors.royalBlue.withValues(alpha: 0.06),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
            color: AppColors.royalBlue.withValues(alpha: 0.35), width: 1.2),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          const Icon(Icons.store, size: 18, color: AppColors.royalBlue),
          const SizedBox(width: 6),
          const Text("¿En qué tienda entra este producto?",
              style: TextStyle(
                  fontWeight: FontWeight.bold,
                  fontSize: 13,
                  color: AppColors.royalBlue)),
        ]),
        const SizedBox(height: 8),
        DropdownButtonFormField<String>(
          value: _tienda.isEmpty ? null : _tienda,
          isExpanded: true,
          decoration: InputDecoration(
            labelText: "Tienda / Ubicación",
            filled: true,
            fillColor: Colors.white,
            prefixIcon: const Icon(Icons.storefront_outlined),
            helperMaxLines: 3,
            helperText: !puedeElegir
                ? "Asignado a tu tienda (no puedes cambiarlo)"
                : (esTelefono
                    ? "Los IMEIs que cargues abajo quedan en esta tienda"
                    : "El stock que cargues abajo queda en esta tienda"),
          ),
          items: [
            // Opción "sin asignar" solo disponible para roles admin
            if (puedeElegir) const DropdownMenuItem(
                value: '',
                child: Text('(Sin asignar — visible en todas)')),
            ...tiendas.map((t) => DropdownMenuItem(
                value: t, child: Text(t))),
          ],
          onChanged: puedeElegir
              ? (v) => setState(() => _tienda = v ?? '')
              : null,
        ),
      ]),
    );
  }

  @override
  Widget build(BuildContext context) {
    final esEdicion = widget.productoAEditar != null;
    // Antes era `_categoria == "Telefono"` — ahora usamos la API
    // central de CategoriasProductos para que cualquier categoría
    // configurada con IMEI active el flujo de IMEI.
    final esTelefono = CategoriasProductos.usaIMEI(_categoria);
    // Si la categoría actual no está en la lista dinámica (caso raro al
    // editar un producto viejo), la agregamos al menos en el dropdown.
    final cats = List<String>.from(CategoriasProductos.lista);
    if (!cats.contains(_categoria)) cats.add(_categoria);
    return Scaffold(
      appBar: AppBar(
        title: Text(esEdicion ? "Editar Producto" : "Nuevo Producto"),
        actions: [
          IconButton(
            icon: const Icon(Icons.tune),
            tooltip: "Gestionar categorías",
            onPressed: () async {
              await _abrirGestorCategorias();
              if (mounted) setState(() {});
            },
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(20),
        child: ListView(children: [
          // ── Tienda / Ubicación ──
          // Va primero porque es la decisión que define dónde queda la
          // mercancía. Si el usuario tiene tienda asignada y NO es
          // admin, se preselecciona y bloquea (no puede asignar
          // productos a otra tienda).
          _construirSelectorTienda(),
          const SizedBox(height: 12),

          // ── Categoría (lista editable) ──
          DropdownButtonFormField<String>(
            value: _categoria,
            isExpanded: true,
            decoration: const InputDecoration(
                labelText: "Categoría",
                prefixIcon: Icon(Icons.category)),
            items: cats.map((e) => DropdownMenuItem(
                value: e, child: Text(e))).toList(),
            onChanged: esEdicion ? null : (v) => setState(() => _categoria = v!)),
          const SizedBox(height: 12),

          // ── Código SKU con botón scanner ──
          Row(children: [
            Expanded(child: TextField(
              controller: _cod,
              decoration: const InputDecoration(
                  labelText: "Código SKU",
                  prefixIcon: Icon(Icons.qr_code_2)),
            )),
            const SizedBox(width: 8),
            // Botón para escanear código de barras directamente al SKU
            IconButton.filledTonal(
              icon: const Icon(Icons.qr_code_scanner),
              tooltip: "Escanear código de barras",
              onPressed: () async {
                await Navigator.push(context, MaterialPageRoute(
                  builder: (_) => ScannerPage(
                    onDetect: (code) {
                      _cod.text = code;
                    }),
                ));
                if (mounted) setState(() {});
              },
            ),
          ]),
          const SizedBox(height: 12),

          // ── Marca (OBLIGATORIA para todos los productos) ──────────
          // Antes solo se pedía para teléfonos. Ahora cualquier
          // producto debe tener marca para poder filtrar por marca
          // en inventario, reportes y estadísticas.
          Autocomplete<String>(
            optionsBuilder: (tv) {
              if (tv.text.isEmpty) return _marcasSugeridas;
              return _marcasSugeridas.where(
                (m) => m.toLowerCase().contains(tv.text.toLowerCase()));
            },
            fieldViewBuilder: (ctx, ctrl, node, onSub) {
              return TextFormField(
                controller: _marca,
                focusNode: node,
                onChanged: (_) => setState(() {}),
                decoration: InputDecoration(
                  labelText: "Marca *",
                  hintText: "Ej: Apple, Samsung, Xiaomi, JBL...",
                  prefixIcon: const Icon(Icons.business),
                  errorText: _marca.text.trim().isEmpty
                      ? "La marca es obligatoria" : null,
                ),
              );
            },
            onSelected: (sel) => setState(() { _marca.text = sel; }),
            displayStringForOption: (s) => s,
          ),
          const SizedBox(height: 12),

          // ── Modelo (solo para teléfonos) ──
          if (esTelefono) ...[
            TextField(
              controller: _modelo,
              onChanged: (_) => setState(() {}),
              decoration: const InputDecoration(
                labelText: "Modelo",
                hintText: "Ej: iPhone 15 Pro, Galaxy S24 Ultra...",
                prefixIcon: Icon(Icons.phone_android)),
            ),
            const SizedBox(height: 12),
          ],

          // ── Código SKU ──
          TextField(
            controller: _cod,
            decoration: const InputDecoration(
              labelText: 'Código (SKU)',
              prefixIcon: Icon(Icons.qr_code)),
            readOnly: esEdicion),
          const SizedBox(height: 8),

          // ── Nombre (con sugerencia automática marca+modelo) ──
          TextField(
            controller: _nom,
            onChanged: (_) => setState(() {}),
            decoration: InputDecoration(
              labelText: 'Nombre del Producto',
              prefixIcon: const Icon(Icons.label),
              suffixIcon: esTelefono && _marca.text.isNotEmpty && _modelo.text.isNotEmpty
                  ? IconButton(
                      icon: const Icon(Icons.auto_fix_high, color: AppColors.primaryBlue),
                      tooltip: "Completar con Marca + Modelo",
                      onPressed: () => setState(() =>
                          _nom.text = "${_marca.text.trim()} ${_modelo.text.trim()}"))
                  : null,
              helperText: esTelefono && _marca.text.isNotEmpty && _modelo.text.isNotEmpty
                  ? "💡 Toca ✨ para usar: ${_marca.text.trim()} ${_modelo.text.trim()}"
                  : null),
          ),
          const SizedBox(height: 8),

          // ── Precios ──
          Row(children: [
            Expanded(child: TextField(
              controller: _pc,
              decoration: const InputDecoration(
                labelText: 'Costo \$', prefixIcon: Icon(Icons.attach_money)),
              keyboardType: TextInputType.numberWithOptions(decimal: true))),
            const SizedBox(width: 10),
            Expanded(child: TextField(
              controller: _pv,
              decoration: const InputDecoration(
                labelText: 'Precio Venta \$', prefixIcon: Icon(Icons.sell)),
              keyboardType: TextInputType.numberWithOptions(decimal: true))),
          ]),
          const SizedBox(height: 8),

          if (esTelefono) ...[
            // ── Proveedor ──
            TextField(
              controller: _prov,
              decoration: const InputDecoration(
                labelText: "Proveedor",
                hintText: "Nombre del proveedor o distribuidor",
                prefixIcon: Icon(Icons.local_shipping)),
            ),
            const SizedBox(height: 20),

            // ── Gestión de IMEIs ──
            Row(children: [
              const Icon(Icons.smartphone, color: AppColors.primaryBlue),
              const SizedBox(width: 8),
              const Text("IMEIs de entrada", style: TextStyle(fontWeight: FontWeight.bold, fontSize: 15)),
              const Spacer(),
              if (_imeisTemporales.isNotEmpty)
                Chip(
                  backgroundColor: AppColors.primaryBlue.withValues(alpha: 0.12),
                  label: Text("${_imeisTemporales.length} equipo(s)",
                    style: const TextStyle(color: AppColors.primaryBlue, fontWeight: FontWeight.bold, fontSize: 12))),
            ]),
            const SizedBox(height: 8),
            Row(children: [
              Expanded(child: TextField(
                controller: _imeiInput,
                keyboardType: TextInputType.number,
                decoration: const InputDecoration(
                  hintText: "Ingrese o escanee IMEI",
                  prefixIcon: Icon(Icons.pin), isDense: true),
                onSubmitted: (_) => _agregarImei())),
              IconButton(
                icon: const Icon(Icons.add_box, color: Colors.green, size: 34),
                tooltip: "Agregar IMEI",
                onPressed: _agregarImei),
              IconButton(
                icon: const Icon(Icons.qr_code_scanner, color: AppColors.primaryBlue, size: 28),
                tooltip: "Escanear",
                onPressed: () => Navigator.push(context,
                  MaterialPageRoute(builder: (_) => ScannerPage(onDetect: (c) {
                    setState(() { if (!_imeisTemporales.contains(c)) _imeisTemporales.add(c); });
                  })))),
            ]),
            if (_imeisTemporales.isNotEmpty) ...[
              const SizedBox(height: 10),
              Wrap(spacing: 8, runSpacing: 4,
                children: _imeisTemporales.map((imei) => Chip(
                  label: Text(imei, style: const TextStyle(fontSize: 12)),
                  deleteIcon: const Icon(Icons.close, size: 16),
                  onDeleted: () => setState(() => _imeisTemporales.remove(imei)),
                )).toList()),
            ],
          ] else ...[
            TextField(
              controller: _cant,
              decoration: const InputDecoration(
                labelText: 'Cantidad en Stock', prefixIcon: Icon(Icons.inventory)),
              keyboardType: TextInputType.number),
          ],
          const SizedBox(height: 24),

          // ── Subproductos (variantes con SKU propio) ───────────
          // Al EDITAR: las variantes se persisten directamente contra
          // el backend (necesitamos el código del padre, que ya existe).
          // Al CREAR: las variantes se acumulan en _variantesPendientes
          // y se guardan en cadena DESPUÉS de crear el padre.
          if (esEdicion && widget.productoAEditar != null) ...[
            _seccionSubproductos(widget.productoAEditar!),
            const SizedBox(height: 24),
          ] else ...[
            _seccionVariantesPendientes(),
            const SizedBox(height: 24),
          ],

          ElevatedButton(
            style: ElevatedButton.styleFrom(
              backgroundColor: AppColors.royalBlue, padding: const EdgeInsets.all(15)),
            onPressed: _guardar,
            child: Text(esEdicion ? "ACTUALIZAR PRODUCTO" : "GUARDAR PRODUCTO",
              style: const TextStyle(color: Colors.white, fontSize: 15))),
        ]),
      ),
    );
  }

  /// Sección que lista las variantes (subproductos) del producto y
  /// permite agregar/eliminar. Cada variante tiene su propio SKU
  /// independiente y es buscable/escaneable como cualquier producto.
  Widget _seccionSubproductos(Producto padre) {
    final hijos = catalogoGlobal
        .where((p) => p.productoPadreCodigo == padre.codigo)
        .toList();
    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: AppColors.surfaceTintBlue,
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: AppColors.brandBlue.withValues(alpha: 0.15)),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          const Icon(Icons.account_tree_outlined,
              color: AppColors.brandBlue, size: 20),
          const SizedBox(width: 8),
          const Expanded(child: Text("Subproductos / variantes",
              style: TextStyle(
                  fontWeight: FontWeight.w700, fontSize: 14))),
          OutlinedButton.icon(
            icon: const Icon(Icons.add, size: 16),
            label: const Text("Agregar variante"),
            onPressed: () => _dialogNuevoSubproducto(padre),
          ),
        ]),
        const SizedBox(height: 4),
        const Text(
          "Variantes del producto (color/almacenamiento/etc), cada "
          "una con su propio SKU escaneable.",
          style: TextStyle(fontSize: 11, color: AppColors.textSecondary)),
        const SizedBox(height: 8),
        if (hijos.isEmpty)
          const Padding(
            padding: EdgeInsets.symmetric(vertical: 8),
            child: Text("Sin variantes registradas.",
                style: TextStyle(
                    color: AppColors.textSecondary,
                    fontStyle: FontStyle.italic, fontSize: 12)),
          )
        else
          ...hijos.map((h) => Container(
            margin: const EdgeInsets.only(bottom: 6),
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(8),
              border: Border.all(color: Colors.grey.shade300),
            ),
            child: Row(children: [
              const Icon(Icons.qr_code_2,
                  color: AppColors.brandBlue, size: 18),
              const SizedBox(width: 8),
              Expanded(child: Column(
                crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text(h.variante.isEmpty ? h.nombre : h.variante,
                      style: const TextStyle(
                          fontWeight: FontWeight.w600, fontSize: 13)),
                  Text("SKU: ${h.codigo}",
                      style: const TextStyle(
                          fontSize: 11,
                          color: AppColors.textSecondary)),
                ])),
              Text("\$${h.precioVenta.toStringAsFixed(2)}",
                  style: const TextStyle(
                      fontWeight: FontWeight.w600,
                      color: AppColors.brandBlue)),
              IconButton(
                icon: const Icon(Icons.delete_outline,
                    size: 18, color: Colors.red),
                tooltip: "Eliminar variante",
                onPressed: () => _eliminarSubproducto(h),
              ),
            ]),
          )),
      ]),
    );
  }

  /// Dialog para crear un subproducto. Hereda categoría/marca/modelo
  /// del padre y solo pide los datos propios de la variante.
  /// Sección de variantes para el modo CREACIÓN. Las variantes
  /// quedan en `_variantesPendientes` (memoria) y se guardan en
  /// cadena cuando el usuario pulse "GUARDAR PRODUCTO".
  Widget _seccionVariantesPendientes() {
    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: AppColors.surfaceTintBlue,
        borderRadius: BorderRadius.circular(10),
        border: Border.all(
            color: AppColors.brandBlue.withValues(alpha: 0.15)),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          const Icon(Icons.account_tree_outlined,
              color: AppColors.brandBlue, size: 20),
          const SizedBox(width: 8),
          const Expanded(child: Text("Subproductos / variantes",
              style: TextStyle(
                  fontWeight: FontWeight.w700, fontSize: 14))),
          OutlinedButton.icon(
            icon: const Icon(Icons.add, size: 16),
            label: const Text("Agregar variante"),
            onPressed: _dialogVariantePendiente,
          ),
        ]),
        const SizedBox(height: 4),
        const Text(
          "Variantes del mismo modelo con SKU propio (ej: color blanco, "
          "color negro, almacenamiento distinto). Se guardarán junto "
          "con el producto cuando pulses GUARDAR.",
          style: TextStyle(fontSize: 11, color: AppColors.textSecondary)),
        const SizedBox(height: 8),
        if (_variantesPendientes.isEmpty)
          const Padding(
            padding: EdgeInsets.symmetric(vertical: 8),
            child: Text("Sin variantes agregadas.",
                style: TextStyle(
                    color: AppColors.textSecondary,
                    fontStyle: FontStyle.italic, fontSize: 12)),
          )
        else
          ..._variantesPendientes.asMap().entries.map((entry) {
            final i = entry.key;
            final v = entry.value;
            return Container(
              margin: const EdgeInsets.only(bottom: 6),
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius: BorderRadius.circular(8),
                border: Border.all(color: Colors.grey.shade300),
              ),
              child: Row(children: [
                const Icon(Icons.qr_code_2,
                    color: AppColors.brandBlue, size: 18),
                const SizedBox(width: 8),
                Expanded(child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start, children: [
                    Text(v.variante.isEmpty ? v.nombre : v.variante,
                        style: const TextStyle(
                            fontWeight: FontWeight.w600, fontSize: 13)),
                    Text("SKU: ${v.codigo}",
                        style: const TextStyle(
                            fontSize: 11,
                            color: AppColors.textSecondary)),
                  ])),
                Text("\$${v.precioVenta.toStringAsFixed(2)}",
                    style: const TextStyle(
                        fontWeight: FontWeight.w600,
                        color: AppColors.brandBlue)),
                IconButton(
                  icon: const Icon(Icons.delete_outline,
                      size: 18, color: Colors.red),
                  tooltip: "Quitar variante",
                  onPressed: () => setState(
                      () => _variantesPendientes.removeAt(i)),
                ),
              ]),
            );
          }),
      ]),
    );
  }

  /// Dialog para agregar una variante PENDIENTE (modo creación).
  /// No persiste al backend — solo la añade a _variantesPendientes.
  /// Hereda marca/modelo de los campos actuales del formulario.
  Future<void> _dialogVariantePendiente() async {
    final ctrlSku = TextEditingController();
    final ctrlVar = TextEditingController();
    final ctrlCant = TextEditingController(text: "0");
    // Precios SOLO de lectura — se muestran como info y al guardar
    // se leen DIRECTAMENTE de los campos del padre (_pc / _pv).
    final pcPadre = double.tryParse(_pc.text.trim()) ?? 0;
    final pvPadre = double.tryParse(_pv.text.trim()) ?? 0;

    await showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(builder: (ctx, setS) => AlertDialog(
        title: Text(
            "Nueva variante de ${_modelo.text.isEmpty ? 'producto' : _modelo.text}",
            style: const TextStyle(fontSize: 16)),
        content: SizedBox(
          width: 400,
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            Row(children: [
              Expanded(child: TextField(
                controller: ctrlSku,
                decoration: const InputDecoration(
                  labelText: "Código SKU",
                  prefixIcon: Icon(Icons.qr_code_2),
                ))),
              const SizedBox(width: 6),
              IconButton.filledTonal(
                icon: const Icon(Icons.qr_code_scanner),
                tooltip: "Escanear",
                onPressed: () async {
                  await Navigator.push(ctx, MaterialPageRoute(
                    builder: (_) => ScannerPage(onDetect: (code) {
                      ctrlSku.text = code;
                    }),
                  ));
                  setS(() {});
                },
              ),
            ]),
            const SizedBox(height: 10),
            TextField(
              controller: ctrlVar,
              decoration: const InputDecoration(
                labelText: "Variante (ej. Color blanco 64GB)",
                prefixIcon: Icon(Icons.palette_outlined),
              )),
            const SizedBox(height: 10),
            TextField(
              controller: ctrlCant,
              keyboardType: TextInputType.number,
              decoration: const InputDecoration(
                labelText: "Stock",
                prefixIcon: Icon(Icons.inventory_2_outlined),
              )),
            const SizedBox(height: 12),
            // Aviso de que los precios se heredan del padre
            Container(
              padding: const EdgeInsets.all(10),
              decoration: BoxDecoration(
                color: AppColors.surfaceTintBlue,
                borderRadius: BorderRadius.circular(8),
                border: Border.all(
                    color: AppColors.brandBlue.withValues(alpha: 0.2)),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Row(children: [
                    Icon(Icons.info_outline,
                        size: 16, color: AppColors.brandBlue),
                    SizedBox(width: 6),
                    Text("Precios heredados del producto principal",
                        style: TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w700,
                            color: AppColors.brandBlue)),
                  ]),
                  const SizedBox(height: 6),
                  Row(children: [
                    Expanded(child: Text(
                        "P. Costo: \$${pcPadre.toStringAsFixed(2)}",
                        style: const TextStyle(fontSize: 12))),
                    Expanded(child: Text(
                        "P. Venta: \$${pvPadre.toStringAsFixed(2)}",
                        style: const TextStyle(fontSize: 12))),
                  ]),
                ],
              ),
            ),
          ]),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx),
            child: const Text("Cancelar")),
          FilledButton(
            onPressed: () {
              final sku = ctrlSku.text.trim();
              if (sku.isEmpty) {
                ScaffoldMessenger.of(ctx).showSnackBar(
                  const SnackBar(content: Text("El SKU es obligatorio")));
                return;
              }
              // Validar contra catálogo global Y contra otras variantes
              // pendientes (que aún no se han guardado).
              if (catalogoGlobal.any((p) => p.codigo == sku)
                  || _variantesPendientes.any((v) => v.codigo == sku)) {
                ScaffoldMessenger.of(ctx).showSnackBar(
                  const SnackBar(content: Text(
                      "Ya existe un producto/variante con ese SKU")));
                return;
              }
              final variante = ctrlVar.text.trim();
              // Los precios SE HEREDAN del padre. La fuente de verdad
              // son los campos del formulario (_pc / _pv) al momento
              // de _guardar — si el usuario cambia el precio del padre
              // antes de guardar, las variantes lo reflejarán.
              // Aquí guardamos los precios actuales como valor inicial;
              // en _guardar se sobreescriben con los del padre final.
              _variantesPendientes.add(Producto(
                codigo: sku,
                nombre: '${_nom.text.trim()} - $variante',
                categoria: _categoria,
                marca: _marca.text.trim(),
                modelo: _modelo.text.trim(),
                tipo: '',
                precioCosto: pcPadre,
                precioVenta: pvPadre,
                stockManual: int.tryParse(ctrlCant.text.trim()) ?? 0,
                productoPadreCodigo: '', // se asigna en _guardar
                variante: variante,
              ));
              Navigator.pop(ctx);
              setState(() {});
            },
            child: const Text("Agregar")),
        ],
      )),
    );
  }

  Future<void> _dialogNuevoSubproducto(Producto padre) async {
    final ctrlSku    = TextEditingController();
    final ctrlVar    = TextEditingController();
    final ctrlCant   = TextEditingController(text: "0");

    await showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(builder: (ctx, setS) => AlertDialog(
        title: Text("Nueva variante de ${padre.modelo}",
            style: const TextStyle(fontSize: 16)),
        content: SizedBox(
          width: 400,
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            Row(children: [
              Expanded(child: TextField(
                controller: ctrlSku,
                decoration: const InputDecoration(
                  labelText: "Código SKU",
                  prefixIcon: Icon(Icons.qr_code_2),
                ))),
              const SizedBox(width: 6),
              IconButton.filledTonal(
                icon: const Icon(Icons.qr_code_scanner),
                tooltip: "Escanear",
                onPressed: () async {
                  await Navigator.push(ctx, MaterialPageRoute(
                    builder: (_) => ScannerPage(onDetect: (code) {
                      ctrlSku.text = code;
                    }),
                  ));
                  setS(() {});
                },
              ),
            ]),
            const SizedBox(height: 10),
            TextField(
              controller: ctrlVar,
              decoration: const InputDecoration(
                labelText: "Variante (ej. Color blanco 64GB)",
                prefixIcon: Icon(Icons.palette_outlined),
              )),
            const SizedBox(height: 10),
            TextField(
              controller: ctrlCant,
              keyboardType: TextInputType.number,
              decoration: const InputDecoration(
                labelText: "Stock",
                prefixIcon: Icon(Icons.inventory_2_outlined),
              )),
            const SizedBox(height: 12),
            // Aviso visual: precios heredados del padre
            Container(
              padding: const EdgeInsets.all(10),
              decoration: BoxDecoration(
                color: AppColors.surfaceTintBlue,
                borderRadius: BorderRadius.circular(8),
                border: Border.all(
                    color: AppColors.brandBlue.withValues(alpha: 0.2)),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Row(children: [
                    Icon(Icons.info_outline,
                        size: 16, color: AppColors.brandBlue),
                    SizedBox(width: 6),
                    Text("Precios heredados del producto principal",
                        style: TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w700,
                            color: AppColors.brandBlue)),
                  ]),
                  const SizedBox(height: 6),
                  Row(children: [
                    Expanded(child: Text(
                        "P. Costo: \$${padre.precioCosto.toStringAsFixed(2)}",
                        style: const TextStyle(fontSize: 12))),
                    Expanded(child: Text(
                        "P. Venta: \$${padre.precioVenta.toStringAsFixed(2)}",
                        style: const TextStyle(fontSize: 12))),
                  ]),
                ],
              ),
            ),
          ]),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx),
            child: const Text("Cancelar")),
          FilledButton(
            onPressed: () async {
              final sku = ctrlSku.text.trim();
              if (sku.isEmpty) {
                ScaffoldMessenger.of(ctx).showSnackBar(
                  const SnackBar(content: Text("El SKU es obligatorio")));
                return;
              }
              if (catalogoGlobal.any((p) => p.codigo == sku)) {
                ScaffoldMessenger.of(ctx).showSnackBar(
                  const SnackBar(content: Text("Ya existe un producto con ese SKU")));
                return;
              }
              final variante = ctrlVar.text.trim();
              final sub = Producto(
                codigo: sku,
                nombre: '${padre.nombre} - $variante',
                categoria: padre.categoria,
                marca: padre.marca,
                modelo: padre.modelo,
                tipo: padre.tipo,
                // Precios SIEMPRE heredados del padre
                precioCosto: padre.precioCosto,
                precioVenta: padre.precioVenta,
                stockManual: int.tryParse(ctrlCant.text.trim()) ?? 0,
                productoPadreCodigo: padre.codigo,
                variante: variante,
              );
              try {
                await _Api.post('productos', sub.toMap());
                catalogoGlobal.add(sub);
                if (ctx.mounted) Navigator.pop(ctx);
                if (mounted) setState(() {});
              } catch (e) {
                if (ctx.mounted) ScaffoldMessenger.of(ctx).showSnackBar(
                    SnackBar(content: Text("Error: $e")));
              }
            },
            child: const Text("Guardar variante")),
        ],
      )),
    );
  }

  Future<void> _eliminarSubproducto(Producto sub) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (c) => AlertDialog(
        title: const Text("Eliminar variante"),
        content: Text("¿Eliminar la variante \"${sub.variante.isEmpty ? sub.nombre : sub.variante}\"?"),
        actions: [
          TextButton(onPressed: () => Navigator.pop(c, false),
              child: const Text("Cancelar")),
          FilledButton(
            style: FilledButton.styleFrom(backgroundColor: Colors.red),
            onPressed: () => Navigator.pop(c, true),
            child: const Text("Eliminar")),
        ],
      ),
    );
    if (ok != true) return;
    try {
      // Buscar por código en la API (el endpoint usa id, no codigo)
      final raw = await _Api.get('productos');
      final fila = (raw as List).cast<Map<String,dynamic>>().firstWhere(
          (m) => m['codigo'] == sub.codigo,
          orElse: () => <String,dynamic>{});
      if (fila['id'] != null) {
        await _Api.delete('productos', fila['id'].toString());
      }
      catalogoGlobal.removeWhere((p) => p.codigo == sub.codigo);
      if (mounted) setState(() {});
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text("Error: $e")));
    }
  }

  void _agregarImei() {
    final imei = _imeiInput.text.trim();
    if (imei.isEmpty) return;
    if (_imeisTemporales.contains(imei)) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text("Este IMEI ya está en la lista")));
      return;
    }
    setState(() { _imeisTemporales.add(imei); _imeiInput.clear(); });
  }

  Future<void> _guardar() async {
    final esEdicion = widget.productoAEditar != null;
    // Usar el toggle de IMEI por categoría (antes era hardcoded a "Telefono")
    final esTelefono = CategoriasProductos.usaIMEI(_categoria);

    if (_cod.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text("Ingrese el código SKU")));
      return;
    }
    if (_nom.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text("Ingrese el nombre del producto")));
      return;
    }
    // La marca ahora es OBLIGATORIA para CUALQUIER producto (antes
    // solo para teléfonos). Permite filtrar por marca en inventario,
    // reportes y estadísticas para todas las categorías.
    if (_marca.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: const Text("La marca es obligatoria"),
        backgroundColor: Colors.orange[700]));
      return;
    }
    if (esTelefono && _imeisTemporales.isEmpty && !esEdicion) {
      final continuar = await showDialog<bool>(
        context: context,
        builder: (ctx) => AlertDialog(
          title: const Text("Sin IMEIs"),
          content: const Text("No ingresó ningún IMEI. ¿Desea guardar el producto sin stock?"),
          actions: [
            TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text("Agregar IMEIs")),
            ElevatedButton(onPressed: () => Navigator.pop(ctx, true), child: const Text("Guardar igual")),
          ]));
      if (continuar != true || !mounted) return;
    }

    // Marca siempre del campo (validamos arriba que no esté vacía).
    final marcaFinal  = _marca.text.trim();
    final modeloFinal = esTelefono
        ? (_modelo.text.trim().isEmpty ? _nom.text.trim() : _modelo.text.trim())
        : "N/A";

    final prod = Producto(
      codigo: _cod.text.trim(), nombre: _nom.text.trim(), tipo: _nom.text.trim(),
      categoria: _categoria, marca: marcaFinal, modelo: modeloFinal,
      precioCosto: double.tryParse(_pc.text) ?? 0,
      precioVenta: double.tryParse(_pv.text) ?? 0,
      stockManual: int.tryParse(_cant.text) ?? 0,
      tienda: _tienda); // Asignación de tienda/ubicación

    try {
      if (esEdicion) {
        // El backend usa `id` numérico como identificador, no el SKU
        // (campo `codigo`). Tenemos que resolver el id antes del PUT
        // — buscando la fila por su `codigo` en la lista de productos.
        final raw = await _Api.get('productos');
        final fila = (raw as List).cast<Map<String, dynamic>>().firstWhere(
            (m) => m['codigo'] == widget.productoAEditar!.codigo,
            orElse: () => <String, dynamic>{});
        if (fila['id'] == null) {
          throw 'No se encontró el producto en la base de datos. '
                'Refresca el inventario y vuelve a intentar.';
        }
        await _Api.put('productos', fila['id'].toString(), prod.toMap());
      } else {
        await _Api.post('productos', prod.toMap());
      }

      // ── Persistir variantes pendientes (solo en modo creación) ──
      // Cada variante se guarda como un Producto independiente con
      // su propio SKU, apuntando al padre vía productoPadreCodigo.
      if (!esEdicion && _variantesPendientes.isNotEmpty) {
        int okVar = 0;
        int failVar = 0;
        for (final v in _variantesPendientes) {
          try {
            // Heredar marca/modelo/categoría del padre que se acaba
            // de crear (por si el usuario los cambió tras agregar
            // variantes). Asignar productoPadreCodigo correctamente.
            final variante = Producto(
              codigo: v.codigo,
              nombre: '${prod.nombre} - ${v.variante}',
              categoria: prod.categoria,
              marca: prod.marca,
              modelo: prod.modelo,
              tipo: prod.tipo,
              precioCosto: prod.precioCosto, // hereda del padre
              precioVenta: prod.precioVenta, // hereda del padre
              stockManual: v.stockManual,
              productoPadreCodigo: prod.codigo,
              variante: v.variante,
              tienda: prod.tienda, // la variante vive donde el padre
            );
            await _Api.post('productos', variante.toMap());
            catalogoGlobal.add(variante);
            okVar++;
          } catch (e) {
            debugPrint('Variante ${v.codigo} error: $e');
            failVar++;
          }
        }
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(SnackBar(
            content: Text(failVar == 0
                ? "✅ Producto + $okVar variante(s) guardadas"
                : "⚠ Producto guardado, $okVar variantes OK, $failVar fallaron"),
            backgroundColor: failVar == 0
                ? AppColors.statusGreen : AppColors.statusOrange));
        }
      }

      if (esTelefono && _imeisTemporales.isNotEmpty) {
        final proveedor = _prov.text.trim().isEmpty ? "Sin especificar" : _prov.text.trim();
        // Tienda elegida arriba. Sólo si quedó "(Sin asignar)" caemos
        // al almacén por defecto, como hacía antes.
        final ubicacionImeis = _tienda.trim().isNotEmpty
            ? _tienda.trim()
            : (ConfigSistema.ubicacionesAlmacen.isNotEmpty
                ? ConfigSistema.ubicacionesAlmacen.first
                : (ConfigSistema.tiendas.isNotEmpty
                    ? ConfigSistema.tiendas.first
                    : ''));
        int guardados = 0;
        for (final imei in _imeisTemporales) {
          try {
            await _Api.post('stock_imei', {
              'imei': imei, 'producto_codigo': prod.codigo,
              'fecha_ingreso': obtenerFechaActual(),
              'proveedor': proveedor, 'color': 'N/A',
              // La ubicación del equipo es LA TIENDA QUE ELIGIÓ EL
              // USUARIO en este formulario. Antes se guardaba siempre
              // en el primer almacén de la configuración, así que el
              // dueño elegía "Sucursal" y los teléfonos aparecían en
              // la principal: la selección de tienda no servía de nada.
              'ubicacion': ubicacionImeis,
              'vendido': 0,
            });
            guardados++;
          } catch (e) { debugPrint('IMEI $imei error: $e'); }
        }
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text("✅ ${prod.nombre} guardado con $guardados IMEI(s)"),
          backgroundColor: AppColors.statusGreen));
      }

      if (!mounted) return;
      Navigator.pop(context);
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text("Error al guardar: $e"), backgroundColor: AppColors.statusRed));
    }
  }
}

// ============================================================
//  BUSCADOR IMEI — carga desde la API
// ============================================================
class VentanaImei extends StatefulWidget {
  const VentanaImei({super.key});
  @override State<VentanaImei> createState() => _VentanaImeiState();
}

class _VentanaImeiState extends State<VentanaImei> {
  final _search = TextEditingController();
  String _filtroUbicacion = "Todos";
  List<ImeiRegistro> _listaCompleta = [];
  bool _cargando = true;

  /// Lista de ubicaciones disponibles: tiendas reales de la BD +
  /// cualquier ubicación que aparezca en los IMEIs existentes
  /// (por compatibilidad con datos antiguos). Se recalcula cada
  /// vez que se carga la ventana.
  List<String> _ubicacionesDisponibles = [];

  /// Solo Administrador y Dueño pueden eliminar IMEIs.
  bool get _puedeEliminar =>
      (usuarioSesion?.rol == 'Administrador' || usuarioSesion?.rol == 'Maestro') ||
      (usuarioSesion?.rol == 'Dueño' || usuarioSesion?.rol == 'Maestro');

  @override
  void initState() { super.initState(); _cargar(); }

  @override
  void dispose() {
    _search.dispose();
    super.dispose();
  }

  Future<void> _cargar() async {
    setState(() => _cargando = true);
    try {
      // Asegurar que catalogoGlobal esté cargado para que ImeiRegistro
      // pueda resolver marca/modelo desde productos cuando el backend
      // no haga JOIN. Si ya está poblado, no recargamos.
      if (catalogoGlobal.isEmpty) {
        try {
          final rawProd = await _Api.get('productos');
          catalogoGlobal = ((rawProd as List?) ?? [])
              .map((m) => Producto.fromMap(m)).toList();
        } catch (e) {
          debugPrint('[VentanaImei] productos: $e');
        }
      }

      // ── Cargar tiendas reales desde la BD ──────────────────
      // En lugar de usar la lista hardcoded ["Almacen","Tienda 1","Tienda 2"],
      // pedimos al servidor las tiendas que realmente existen.
      // Si la petición falla, usamos como fallback las tiendas conocidas
      // en ConfigSistema.tiendas (que el usuario puede editar en Ajustes).
      List<String> tiendasReales = [];
      try {
        final rawTiendas = await _Api.get('tiendas');
        tiendasReales = ((rawTiendas as List?) ?? [])
            .map((m) => (m as Map)['nombre']?.toString() ?? '')
            .where((n) => n.isNotEmpty)
            .toList();
        // Sincronizar con ConfigSistema.tiendas para mantener consistencia
        // en el resto de la app
        if (tiendasReales.isNotEmpty) {
          ConfigSistema.tiendas = List<String>.from(tiendasReales);
        }
      } catch (e) {
        debugPrint('[VentanaImei] tiendas: $e — usando fallback');
      }
      // Si la BD aún no tiene tiendas configuradas, usamos las que ya
      // hay en ConfigSistema (que el usuario gestiona desde Ajustes).
      if (tiendasReales.isEmpty) {
        tiendasReales = List<String>.from(ConfigSistema.tiendas);
      }

      final raw = await _Api.get('stock_imei');
      _listaCompleta = ((raw as List?) ?? []).map((m) => ImeiRegistro.fromMap(m)).toList();
      stockImeiGlobal = _listaCompleta;

      // ── Construir lista de ubicaciones disponibles ─────────
      // Combinamos las tiendas reales con las ubicaciones que ya
      // aparecen en los IMEIs (para mostrar también "Almacen" y otras
      // ubicaciones históricas si todavía hay IMEIs ahí).
      final ubicacionesEnImeis = <String>{};
      for (final i in _listaCompleta) {
        final u = i.ubicacion.trim();
        if (u.isNotEmpty) ubicacionesEnImeis.add(u);
      }
      // Tiendas reales primero, luego ubicaciones históricas que NO sean
      // ya una tienda real (para no duplicar). Esto mantiene "Almacen"
      // u otros si todavía hay IMEIs ahí, pero al frente las tiendas.
      _ubicacionesDisponibles = [
        ...tiendasReales,
        ...ubicacionesEnImeis.where((u) => !tiendasReales.contains(u)),
      ];

      // Si el filtro actual ya no existe en la lista, resetearlo a "Todos"
      if (_filtroUbicacion != 'Todos' &&
          !_ubicacionesDisponibles.contains(_filtroUbicacion)) {
        _filtroUbicacion = 'Todos';
      }
    } catch (e) {
      debugPrint('[_cargar] Error: $e');
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Error al cargar datos: $e'), backgroundColor: AppColors.statusRed, duration: const Duration(seconds: 4)));
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  // ── Eliminar IMEI con confirmación ────────────────────────────
  Future<void> _eliminarImei(ImeiRegistro reg, {VoidCallback? onSuccess}) async {
    // Advertencia adicional si el equipo está marcado como vendido
    final esVendido = reg.vendido;

    final confirmar = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Row(children: [
          Icon(Icons.delete_forever_outlined, color: AppColors.statusRed),
          SizedBox(width: 8),
          Flexible(child: Text("Eliminar IMEI")),
        ]),
        content: Column(mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start, children: [
          // Tarjeta resumen del equipo
          Container(
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: AppColors.surfaceGrey,
              borderRadius: BorderRadius.circular(10),
              border: Border.all(color: AppColors.cardBorder),
            ),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(reg.producto.nombre,
                style: const TextStyle(fontWeight: FontWeight.w600, fontSize: 14)),
              const SizedBox(height: 4),
              Row(children: [
                const Icon(Icons.pin_outlined, size: 13, color: AppColors.textSecondary),
                const SizedBox(width: 4),
                Expanded(child: Text("IMEI: ${reg.imei}",
                  style: const TextStyle(fontSize: 12,
                    color: AppColors.textSecondary, fontFamily: 'monospace'))),
              ]),
              const SizedBox(height: 2),
              Row(children: [
                const Icon(Icons.location_on_outlined, size: 13, color: AppColors.textSecondary),
                const SizedBox(width: 4),
                Text(reg.ubicacion,
                  style: const TextStyle(fontSize: 12, color: AppColors.textSecondary)),
              ]),
              const SizedBox(height: 4),
              // Estado actual
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                decoration: BoxDecoration(
                  color: (esVendido ? Colors.grey : AppColors.statusGreen).withValues(alpha: 0.12),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: Text(
                  esVendido ? "VENDIDO" : "DISPONIBLE",
                  style: TextStyle(
                    fontSize: 11, fontWeight: FontWeight.bold,
                    color: esVendido ? Colors.grey : AppColors.statusGreen)),
              ),
            ]),
          ),
          const SizedBox(height: 12),
          // Alerta si está vendido
          if (esVendido)
            Container(
              padding: const EdgeInsets.all(10),
              decoration: BoxDecoration(
                color: AppColors.statusOrange.withValues(alpha: 0.08),
                borderRadius: BorderRadius.circular(8),
                border: Border.all(color: AppColors.statusOrange.withValues(alpha: 0.3)),
              ),
              child: const Row(children: [
                Icon(Icons.warning_amber, size: 16, color: AppColors.statusOrange),
                SizedBox(width: 8),
                Expanded(child: Text(
                  "Este equipo está marcado como VENDIDO. "
                  "Eliminarlo no revertirá la factura asociada.",
                  style: TextStyle(fontSize: 11, color: AppColors.statusOrange))),
              ]),
            ),
          if (!esVendido)
            const Text("Esta acción es permanente. El equipo se quitará del stock disponible.",
              style: TextStyle(color: AppColors.statusRed, fontSize: 12)),
        ]),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text("Cancelar")),
          ElevatedButton.icon(
            style: ElevatedButton.styleFrom(
              backgroundColor: AppColors.statusRed),
            icon: const Icon(Icons.delete_forever_outlined,
              size: 16, color: Colors.white),
            label: const Text("Eliminar Definitivamente",
              style: TextStyle(color: Colors.white)),
            onPressed: () => Navigator.pop(ctx, true)),
        ],
      ),
    );

    if (confirmar != true || !mounted) return;

    try {
      // Buscar el id NUMÉRICO real del IMEI en la BD.
      // No podemos mandar el IMEI físico (ej. 862315087856349) como ID
      // porque la columna `id` de la tabla stock_imei es un entero
      // autoincremental (1, 2, 4, 5...). El backend espera ese número.
      // Primero buscamos la fila por su campo `imei` y extraemos el id.
      final raw = await _Api.get('stock_imei');
      final fila = (raw as List).cast<Map<String, dynamic>>()
          .firstWhere((m) => m['imei']?.toString() == reg.imei,
              orElse: () => <String, dynamic>{});
      if (fila['id'] == null) {
        throw 'No se encontró el IMEI ${reg.imei} en la base de datos';
      }
      await _Api.delete('stock_imei', fila['id'].toString());

      // Actualizar listas en memoria
      setState(() => _listaCompleta.removeWhere((x) => x.imei == reg.imei));
      stockImeiGlobal.removeWhere((x) => x.imei == reg.imei);

      // Actualizar stock del producto en catalogoGlobal
      final prodIdx = catalogoGlobal.indexWhere(
        (p) => p.codigo == reg.producto.codigo);
      if (prodIdx != -1 && !esVendido) {
        catalogoGlobal[prodIdx].stockTotal =
            (catalogoGlobal[prodIdx].stockTotal - 1).clamp(0, 999999);
      }

      onSuccess?.call(); // cerrar el bottom sheet si viene de _mostrarDetalle

      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Row(children: [
          const Icon(Icons.check_circle_outline, color: Colors.white, size: 16),
          const SizedBox(width: 8),
          Expanded(child: Text("IMEI ${reg.imei} eliminado correctamente.")),
        ]),
        backgroundColor: AppColors.statusGreen,
        duration: const Duration(seconds: 3)));
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text("Error al eliminar IMEI: $e"),
        backgroundColor: AppColors.statusRed,
        duration: const Duration(seconds: 4)));
    }
  }

  @override
  Widget build(BuildContext context) {
    final listaFiltrada = _listaCompleta.where((i) {
      final coincideBusqueda = i.imei.contains(_search.text) ||
          i.producto.nombre.toLowerCase().contains(_search.text.toLowerCase()) ||
          i.proveedor.toLowerCase().contains(_search.text.toLowerCase());
      final coincideUbicacion = _filtroUbicacion == "Todos" || i.ubicacion == _filtroUbicacion;
      return coincideBusqueda && coincideUbicacion;
    }).toList();

    final totalDisponibles = listaFiltrada.where((i) => !i.vendido).length;
    final totalVendidos = listaFiltrada.where((i) => i.vendido).length;

    return Scaffold(
      appBar: AppBar(
        title: const Text("Gestión de IMEIs"),
        actions: [
          if (_puedeEliminar)
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 8),
              child: Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
                decoration: BoxDecoration(
                  color: Colors.white.withValues(alpha: 0.18),
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(color: Colors.white.withValues(alpha: 0.3)),
                ),
                child: Row(mainAxisSize: MainAxisSize.min, children: [
                  const Icon(Icons.admin_panel_settings, size: 13, color: AppColors.statusYellow),
                  const SizedBox(width: 4),
                  Text(usuarioSesion?.rol ?? '',
                    style: const TextStyle(
                      color: AppColors.statusYellow, fontSize: 10,
                      fontWeight: FontWeight.bold)),
                ]),
              ),
            ),
          IconButton(icon: const Icon(Icons.refresh), tooltip: "Actualizar", onPressed: _cargar),
          IconButton(
            icon: const Icon(Icons.add_circle_outline),
            tooltip: "Registrar IMEI",
            onPressed: () => _abrirFormularioIngreso(context)),
        ],
      ),
      body: Column(children: [
        // Barra de búsqueda y filtros
        Container(
          padding: const EdgeInsets.fromLTRB(12, 12, 12, 8),
          color: AppColors.royalBlue,
          child: Column(children: [
            TextField(
              controller: _search,
              onChanged: (v) => setState(() {}),
              style: const TextStyle(color: Colors.white),
              decoration: InputDecoration(
                hintText: "Buscar por IMEI, modelo o proveedor...",
                hintStyle: const TextStyle(color: Colors.white70),
                prefixIcon: const Icon(Icons.search, color: Colors.white),
                suffixIcon: _search.text.isNotEmpty
                  ? IconButton(
                      icon: const Icon(Icons.clear, color: Colors.white70, size: 18),
                      onPressed: () => setState(() => _search.clear()))
                  : null,
                filled: true,
                fillColor: Colors.white.withValues(alpha: 0.12),
                border: OutlineInputBorder(borderRadius: BorderRadius.circular(10), borderSide: BorderSide.none),
                contentPadding: const EdgeInsets.symmetric(vertical: 0, horizontal: 16),
              ),
            ),
            const SizedBox(height: 8),
            SingleChildScrollView(
              scrollDirection: Axis.horizontal,
              child: Row(
                children: ["Todos", ..._ubicacionesDisponibles].map((u) => Padding(
                  padding: const EdgeInsets.only(right: 8),
                  child: ChoiceChip(
                    label: Text(u, style: TextStyle(
                      color: _filtroUbicacion == u ? Colors.white : Colors.white70,
                      fontSize: 12)),
                    selected: _filtroUbicacion == u,
                    selectedColor: AppColors.primaryBlue,
                    backgroundColor: Colors.white.withValues(alpha: 0.1),
                    onSelected: (val) => setState(() => _filtroUbicacion = u),
                  ),
                )).toList(),
              ),
            ),
            const SizedBox(height: 6),
            // Estadísticas rápidas
            Row(children: [
              _statChip(Icons.check_circle_outline, "$totalDisponibles disponibles", Colors.greenAccent),
              const SizedBox(width: 8),
              _statChip(Icons.sell_outlined, "$totalVendidos vendidos", Colors.orange.shade200),
            ]),
          ]),
        ),
        if (_cargando)
          const Expanded(child: Center(child: CircularProgressIndicator()))
        else if (listaFiltrada.isEmpty)
          const Expanded(child: EmptyState(mensaje: "No se encontraron IMEIs.", icono: Icons.smartphone_outlined))
        else
          Expanded(child: RefreshIndicator(
            onRefresh: _cargar,
            child: ListView.builder(
              padding: const EdgeInsets.all(12),
              itemCount: listaFiltrada.length,
              itemBuilder: (c, i) {
                final reg = listaFiltrada[i];
                return Card(
                  margin: const EdgeInsets.only(bottom: 6),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(10),
                    side: reg.vendido
                      ? BorderSide(color: Colors.grey[300]!)
                      : const BorderSide(color: AppColors.statusGreen, width: 0.5),
                  ),
                  child: InkWell(
                    borderRadius: BorderRadius.circular(10),
                    onTap: () => _mostrarDetalle(reg),
                    child: Padding(
                      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
                      child: Row(children: [
                        // ── Ícono ──────────────────────────────────
                        Container(
                          padding: const EdgeInsets.all(8),
                          decoration: BoxDecoration(
                            color: (reg.vendido ? Colors.grey : AppColors.primaryBlue)
                                .withValues(alpha: 0.1),
                            borderRadius: BorderRadius.circular(8),
                          ),
                          child: Icon(Icons.smartphone,
                            color: reg.vendido ? Colors.grey : AppColors.primaryBlue,
                            size: 22),
                        ),
                        const SizedBox(width: 12),

                        // ── Info ────────────────────────────────────
                        Expanded(child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(reg.producto.nombre,
                              style: TextStyle(
                                fontWeight: FontWeight.w600,
                                color: reg.vendido
                                  ? AppColors.textSecondary
                                  : AppColors.textPrimary)),
                            // Modelo (si está disponible)
                            if (reg.producto.modelo.trim().isNotEmpty) ...[
                              const SizedBox(height: 2),
                              Text("Modelo: ${reg.producto.modelo}",
                                style: TextStyle(
                                  fontSize: 12,
                                  fontWeight: FontWeight.w500,
                                  color: reg.vendido
                                    ? AppColors.textSecondary
                                    : AppColors.primaryBlue)),
                            ],
                            const SizedBox(height: 2),
                            Text("IMEI: ${reg.imei}",
                              style: const TextStyle(fontSize: 12,
                                fontFamily: 'monospace', color: AppColors.textSecondary)),
                            Row(children: [
                              const Icon(Icons.location_on_outlined,
                                size: 12, color: AppColors.textSecondary),
                              const SizedBox(width: 2),
                              Text(reg.ubicacion,
                                style: const TextStyle(fontSize: 11,
                                  color: AppColors.textSecondary)),
                              if (reg.proveedor.isNotEmpty) ...[
                                const Text(" · ",
                                  style: TextStyle(color: AppColors.textSecondary)),
                                Text(reg.proveedor,
                                  style: const TextStyle(fontSize: 11,
                                    color: AppColors.textSecondary)),
                              ],
                            ]),
                          ],
                        )),

                        // ── Badge estado ────────────────────────────
                        Container(
                          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                          decoration: BoxDecoration(
                            color: (reg.vendido ? Colors.grey : AppColors.statusGreen)
                                .withValues(alpha: 0.1),
                            borderRadius: BorderRadius.circular(8),
                          ),
                          child: Text(
                            reg.vendido ? "VENDIDO" : "DISP.",
                            style: TextStyle(
                              fontSize: 10, fontWeight: FontWeight.bold,
                              color: reg.vendido ? Colors.grey : AppColors.statusGreen)),
                        ),

                        // ── Botón eliminar (solo admin/dueño) ───────
                        if (_puedeEliminar) ...[
                          const SizedBox(width: 4),
                          IconButton(
                            icon: const Icon(Icons.delete_outline,
                              color: AppColors.statusRed, size: 20),
                            padding: EdgeInsets.zero,
                            constraints: const BoxConstraints(),
                            tooltip: "Eliminar IMEI",
                            onPressed: () => _eliminarImei(reg)),
                        ],
                      ]),
                    ),
                  ),
                );
              },
            ),
          )),
      ]),
    );
  }

