  void _moverImei(ImeiRegistro reg) {
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Row(children: [
          const Icon(Icons.swap_horiz, color: AppColors.royalBlue),
          const SizedBox(width: 8),
          Expanded(child: Text("Mover: ${reg.producto.nombre}",
            style: const TextStyle(fontSize: 15))),
        ]),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text("Ubicación actual: ${reg.ubicacion}",
              style: const TextStyle(color: AppColors.textSecondary, fontSize: 13)),
            const SizedBox(height: 12),
            ..._ubicacionesDisponibles
              .where((u) => u != reg.ubicacion)
              .map((u) => ListTile(
                contentPadding: EdgeInsets.zero,
                leading: const Icon(Icons.location_on_outlined, color: AppColors.primaryBlue),
                title: Text(u, style: const TextStyle(fontWeight: FontWeight.w500)),
                trailing: const Icon(Icons.arrow_forward_ios, size: 14, color: AppColors.textSecondary),
                onTap: () async {
                  final anterior = reg.ubicacion;
                  Navigator.pop(ctx);
                  try {
                    reg.ubicacion = u;
                    // Buscar id numérico real del IMEI (mismo fix que el DELETE)
                    final raw = await _Api.get('stock_imei');
                    final fila = (raw as List).cast<Map<String, dynamic>>()
                        .firstWhere((m) => m['imei']?.toString() == reg.imei,
                            orElse: () => <String, dynamic>{});
                    if (fila['id'] == null) {
                      throw 'No se encontró el IMEI ${reg.imei} en la base de datos';
                    }
                    await _Api.put('stock_imei', fila['id'].toString(), reg.toMap());
                    if (mounted) {
                      setState(() {});
                      ScaffoldMessenger.of(context).showSnackBar(
                        SnackBar(
                          content: Text("Movido de '$anterior' → '$u'"),
                          backgroundColor: AppColors.statusGreen));
                    }
                  } catch (e) {
                    reg.ubicacion = anterior; // revertir
                    if (mounted) ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(content: Text("Error al mover: $e"), backgroundColor: AppColors.statusRed));
                  }
                },
              )).toList(),
          ],
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text("Cancelar")),
        ],
      ),
    );
  }

  void _abrirFormularioIngreso(BuildContext parentContext) {
    // Lista de IMEIs a ingresar (permite agregar varios)
    final List<TextEditingController> imeiCtrls = [TextEditingController()];
    final tProv = TextEditingController();
    final tCol  = TextEditingController();
    final tBat  = TextEditingController();

    Producto? pSel;
    // La ubicación por defecto es la primera tienda real disponible.
    // Si no hay ninguna (BD vacía), usamos la primera de ConfigSistema.tiendas
    // como último fallback. Ya no hardcodeamos "Almacen".
    String uSel = _ubicacionesDisponibles.isNotEmpty
        ? _ubicacionesDisponibles.first
        : (ConfigSistema.tiendas.isNotEmpty
            ? ConfigSistema.tiendas.first
            : '');

    // Todos los productos del catálogo que usan IMEI, ordenados por nombre
    final todosModelos = catalogoGlobal
        .where((p) => CategoriasProductos.usaIMEI(p.categoria))
        .toList()
      ..sort((a, b) => a.nombre.compareTo(b.nombre));

    showDialog(context: parentContext, builder: (dialogContext) {
      return StatefulBuilder(builder: (ctx, setL) {
        final esIphone = pSel?.nombre.toLowerCase().contains("iphone") == true;

        return AlertDialog(
          title: const Row(children: [
            Icon(Icons.smartphone, color: AppColors.primaryBlue),
            SizedBox(width: 8),
            Text("Ingresar Equipos"),
          ]),
          content: SizedBox(
            width: double.maxFinite,
            child: SingleChildScrollView(child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // ── Modelo (sin requerir marca) ──────────────────
                const Text("Modelo *",
                  style: TextStyle(fontWeight: FontWeight.bold,
                    fontSize: 12, color: AppColors.royalBlue)),
                const SizedBox(height: 6),

                // Buscar producto por SKU (manual o escaneando)
                Row(children: [
                  Expanded(child: TextField(
                    decoration: const InputDecoration(
                      labelText: "Buscar por SKU",
                      hintText: "Pega o escanea el código",
                      prefixIcon: Icon(Icons.qr_code_2, size: 18),
                      isDense: true,
                      border: OutlineInputBorder(),
                    ),
                    onSubmitted: (sku) {
                      final s = sku.trim();
                      if (s.isEmpty) return;
                      final encontrado = todosModelos.firstWhere(
                        (p) => p.codigo == s,
                        orElse: () => Producto(
                            codigo: '', nombre: '', categoria: '',
                            marca: '', modelo: '', precioCosto: 0,
                            tipo: '', precioVenta: 0),
                      );
                      if (encontrado.codigo.isNotEmpty) {
                        setL(() => pSel = encontrado);
                      } else {
                        ScaffoldMessenger.of(ctx).showSnackBar(SnackBar(
                          content: Text("SKU no encontrado: $s"),
                          backgroundColor: Colors.orange));
                      }
                    },
                  )),
                  const SizedBox(width: 6),
                  IconButton.filledTonal(
                    icon: const Icon(Icons.qr_code_scanner),
                    tooltip: "Escanear SKU",
                    onPressed: () async {
                      await Navigator.push(ctx, MaterialPageRoute(
                        builder: (_) => ScannerPage(onDetect: (code) {
                          final encontrado = todosModelos.firstWhere(
                            (p) => p.codigo == code,
                            orElse: () => Producto(
                                codigo: '', nombre: '', categoria: '',
                                marca: '', modelo: '', precioCosto: 0,
                                tipo: '', precioVenta: 0),
                          );
                          if (encontrado.codigo.isNotEmpty) {
                            setL(() => pSel = encontrado);
                          } else {
                            ScaffoldMessenger.of(ctx).showSnackBar(SnackBar(
                              content: Text("SKU no encontrado: $code"),
                              backgroundColor: Colors.orange));
                          }
                        }),
                      ));
                    },
                  ),
                ]),
                const SizedBox(height: 8),

                DropdownButtonFormField<Producto>(
                  value: pSel,
                  hint: const Text("O elige el modelo aquí..."),
                  decoration: const InputDecoration(
                    isDense: true,
                    prefixIcon: Icon(Icons.phone_android, size: 18),
                    border: OutlineInputBorder()),
                  isExpanded: true,
                  items: todosModelos.map((p) => DropdownMenuItem(
                    value: p,
                    child: Text("${p.nombre} (${p.marca})",
                      overflow: TextOverflow.ellipsis))).toList(),
                  onChanged: (v) => setL(() => pSel = v),
                ),
                const SizedBox(height: 14),

                // ── Datos adicionales ─────────────────────────────
                TextField(
                  controller: tProv,
                  decoration: const InputDecoration(
                    labelText: "Proveedor",
                    prefixIcon: Icon(Icons.local_shipping), isDense: true, border: OutlineInputBorder())),
                const SizedBox(height: 8),
                TextField(
                  controller: tCol,
                  decoration: const InputDecoration(
                    labelText: "Color",
                    prefixIcon: Icon(Icons.color_lens), isDense: true, border: OutlineInputBorder())),
                if (esIphone) ...[
                  const SizedBox(height: 8),
                  TextField(
                    controller: tBat,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(
                      labelText: "% Batería",
                      prefixIcon: Icon(Icons.battery_charging_full), isDense: true, border: OutlineInputBorder())),
                ],
                const SizedBox(height: 8),
                DropdownButtonFormField<String>(
                  // Si la ubicación seleccionada por defecto ya no está
                  // en la lista (porque las tiendas cambiaron), usamos
                  // la primera disponible para evitar el "value not in items" crash.
                  value: _ubicacionesDisponibles.contains(uSel)
                      ? uSel
                      : (_ubicacionesDisponibles.isNotEmpty
                          ? _ubicacionesDisponibles.first
                          : null),
                  decoration: const InputDecoration(
                    labelText: "Ubicación",
                    prefixIcon: Icon(Icons.warehouse), isDense: true, border: OutlineInputBorder()),
                  items: _ubicacionesDisponibles
                      .map((u) => DropdownMenuItem(value: u, child: Text(u))).toList(),
                  onChanged: (v) => setL(() => uSel = v ?? uSel)),
                const SizedBox(height: 16),

                // ── IMEIs (múltiples) ──────────────────────────────
                Row(children: [
                  const Text("IMEIs a ingresar *",
                    style: TextStyle(fontWeight: FontWeight.bold,
                      fontSize: 12, color: AppColors.royalBlue)),
                  const Spacer(),
                  TextButton.icon(
                    icon: const Icon(Icons.add, size: 16),
                    label: const Text("Agregar otro", style: TextStyle(fontSize: 12)),
                    onPressed: () => setL(() =>
                      imeiCtrls.add(TextEditingController())),
                  ),
                ]),
                ...imeiCtrls.asMap().entries.map((entry) {
                  final idx = entry.key;
                  final ctrl = entry.value;
                  return Padding(
                    padding: const EdgeInsets.only(bottom: 8),
                    child: Row(children: [
                      Expanded(child: TextField(
                        controller: ctrl,
                        keyboardType: TextInputType.number,
                        decoration: InputDecoration(
                          labelText: "IMEI ${idx + 1}",
                          prefixIcon: const Icon(Icons.pin), isDense: true,
                          border: const OutlineInputBorder()),
                      )),
                      // Botón scanner por IMEI — escanea código de barras y
                      // escribe el valor en este controller específico.
                      IconButton(
                        icon: const Icon(Icons.qr_code_scanner,
                          color: AppColors.primaryBlue),
                        tooltip: "Escanear IMEI ${idx + 1}",
                        onPressed: () => Navigator.push(context,
                          MaterialPageRoute(builder: (_) => ScannerPage(
                            onDetect: (c) => setL(() => ctrl.text = c)))),
                      ),
                      if (imeiCtrls.length > 1)
                        IconButton(
                          icon: const Icon(Icons.remove_circle_outline,
                            color: AppColors.statusRed),
                          tooltip: "Quitar",
                          onPressed: () => setL(() {
                            ctrl.dispose();
                            imeiCtrls.removeAt(idx);
                          }),
                        ),
                    ]),
                  );
                }),
                const Text("Mínimo 14 dígitos por IMEI",
                  style: TextStyle(fontSize: 11, color: AppColors.textSecondary)),
              ],
            )),
          ),
          actions: [
            TextButton(
              onPressed: () {
                Navigator.pop(dialogContext);
                for (final c in imeiCtrls) c.dispose();
                tProv.dispose(); tCol.dispose(); tBat.dispose();
              },
              child: const Text("CANCELAR")),
            ElevatedButton.icon(
              icon: const Icon(Icons.save),
              label: Text("GUARDAR ${imeiCtrls.length > 1 ? '(${imeiCtrls.length})' : ''}"),
              onPressed: () async {
                if (pSel == null) {
                  ScaffoldMessenger.of(parentContext).showSnackBar(
                    const SnackBar(content: Text("Seleccione el modelo del equipo")));
                  return;
                }
                final imeisValidos = imeiCtrls
                    .map((c) => c.text.trim())
                    .where((s) => s.isNotEmpty)
                    .toList();
                if (imeisValidos.isEmpty) {
                  ScaffoldMessenger.of(parentContext).showSnackBar(
                    const SnackBar(content: Text("Ingrese al menos un IMEI")));
                  return;
                }
                final invalidos = imeisValidos.where((s) => s.length < 14).toList();
                if (invalidos.isNotEmpty) {
                  ScaffoldMessenger.of(parentContext).showSnackBar(SnackBar(
                    content: Text("IMEI inválido (menos de 14 dígitos): ${invalidos.join(', ')}")));
                  return;
                }

                // ── Validación previa: detectar duplicados ──
                // Antes de mandar nada al servidor, verificamos:
                //  1. Duplicados dentro de la misma lista (el usuario
                //     escribió el mismo IMEI dos veces).
                //  2. Duplicados con IMEIs ya existentes en la BD.
                // Esto evita errores 500 del servidor por UNIQUE KEY.
                final yaEnLista = <String>{};
                final duplicadosLocal = <String>[];
                for (final i in imeisValidos) {
                  if (!yaEnLista.add(i)) duplicadosLocal.add(i);
                }
                if (duplicadosLocal.isNotEmpty) {
                  ScaffoldMessenger.of(parentContext).showSnackBar(SnackBar(
                    content: Text("Hay IMEIs repetidos en el formulario: ${duplicadosLocal.join(', ')}"),
                    backgroundColor: AppColors.statusOrange));
                  return;
                }
                final yaEnBd = stockImeiGlobal.map((r) => r.imei).toSet();
                final duplicadosBd = imeisValidos.where((i) => yaEnBd.contains(i)).toList();
                if (duplicadosBd.isNotEmpty) {
                  if (!mounted) return;
                  final continuar = await showDialog<bool>(
                    context: parentContext,
                    builder: (c) => AlertDialog(
                      title: const Row(children: [
                        Icon(Icons.warning_amber, color: AppColors.statusOrange),
                        SizedBox(width: 8),
                        Text('IMEIs duplicados'),
                      ]),
                      content: Column(mainAxisSize: MainAxisSize.min,
                        crossAxisAlignment: CrossAxisAlignment.start, children: [
                        Text('${duplicadosBd.length} IMEI(s) ya están registrados:',
                            style: const TextStyle(fontSize: 13)),
                        const SizedBox(height: 8),
                        ...duplicadosBd.take(5).map((i) => Text('• $i',
                            style: const TextStyle(fontSize: 11, fontFamily: 'monospace'))),
                        if (duplicadosBd.length > 5)
                          Text('… y ${duplicadosBd.length - 5} más',
                              style: const TextStyle(fontSize: 11, color: Colors.grey)),
                        const SizedBox(height: 12),
                        const Text('¿Continuar guardando solo los nuevos?',
                            style: TextStyle(fontWeight: FontWeight.bold)),
                      ]),
                      actions: [
                        TextButton(onPressed: () => Navigator.pop(c, false),
                          child: const Text('Cancelar')),
                        ElevatedButton(onPressed: () => Navigator.pop(c, true),
                          child: const Text('Continuar')),
                      ],
                    ),
                  );
                  if (continuar != true) return;
                }
                // Lista final: sin duplicados con la BD.
                final imeisAGuardar = imeisValidos
                    .where((i) => !yaEnBd.contains(i)).toList();
                if (imeisAGuardar.isEmpty) {
                  if (!mounted) return;
                  ScaffoldMessenger.of(parentContext).showSnackBar(const SnackBar(
                      content: Text("No hay IMEIs nuevos para guardar"),
                      backgroundColor: AppColors.statusOrange));
                  return;
                }

                // ── Guardar uno por uno, capturando errores específicos
                // Mostrar feedback en pantalla mientras se guardan.
                if (!mounted) return;
                ScaffoldMessenger.of(parentContext).showSnackBar(SnackBar(
                    content: Row(children: [
                      const SizedBox(width: 16, height: 16,
                          child: CircularProgressIndicator(
                              strokeWidth: 2, color: Colors.white)),
                      const SizedBox(width: 12),
                      Text('Guardando ${imeisAGuardar.length} IMEI(s)...'),
                    ]),
                    duration: const Duration(seconds: 30)));

                int guardados = 0;
                final List<String> fallidos = [];
                final Map<String, String> motivos = {};
                for (final imei in imeisAGuardar) {
                  try {
                    await _Api.post('stock_imei', {
                      'imei': imei,
                      'producto_codigo': pSel!.codigo,
                      'fecha_ingreso': obtenerFechaActual(),
                      'proveedor': tProv.text.trim().isEmpty ? "Sin especificar" : tProv.text.trim(),
                      'color': tCol.text.trim().isEmpty ? "N/A" : tCol.text.trim(),
                      'ubicacion': uSel,
                      'porcentaje_bateria': int.tryParse(tBat.text.trim()),
                      'vendido': 0,
                    });
                    guardados++;
                  } catch (e) {
                    fallidos.add(imei);
                    final msg = e.toString();
                    // Mensaje corto y útil
                    if (msg.contains('Duplicate') || msg.contains('UNIQUE')) {
                      motivos[imei] = 'ya existe en la BD';
                    } else if (msg.contains('Timeout') || msg.contains('timeout')) {
                      motivos[imei] = 'tiempo agotado (verificar conexión)';
                    } else {
                      motivos[imei] = msg.length > 60 ? '${msg.substring(0, 60)}...' : msg;
                    }
                    debugPrint('[StockImei] Error guardando $imei: $e');
                  }
                }

                if (!mounted) return;
                ScaffoldMessenger.of(parentContext).hideCurrentSnackBar();
                Navigator.pop(dialogContext);
                await _cargar();
                for (final c in imeiCtrls) c.dispose();
                tProv.dispose(); tCol.dispose(); tBat.dispose();

                if (fallidos.isEmpty) {
                  ScaffoldMessenger.of(parentContext).showSnackBar(SnackBar(
                    content: Text("✅ $guardados equipo(s) ${pSel!.nombre} ingresado(s) correctamente"),
                    backgroundColor: AppColors.statusGreen));
                } else {
                  // Mostrar diálogo con detalle de fallidos
                  showDialog(context: parentContext, builder: (c) => AlertDialog(
                    title: Row(children: [
                      const Icon(Icons.info_outline, color: AppColors.statusOrange),
                      const SizedBox(width: 8),
                      Text('$guardados guardados · ${fallidos.length} fallidos'),
                    ]),
                    content: SingleChildScrollView(child: Column(
                      mainAxisSize: MainAxisSize.min,
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        if (guardados > 0)
                          Text('✅ $guardados IMEI(s) guardados con éxito.',
                              style: const TextStyle(color: AppColors.statusGreen)),
                        const SizedBox(height: 8),
                        const Text('❌ Fallidos:',
                            style: TextStyle(fontWeight: FontWeight.bold,
                                color: AppColors.statusRed)),
                        const SizedBox(height: 4),
                        ...fallidos.map((i) => Padding(
                          padding: const EdgeInsets.symmetric(vertical: 2),
                          child: Text('• $i — ${motivos[i] ?? "error desconocido"}',
                              style: const TextStyle(fontSize: 11)),
                        )),
                      ],
                    )),
                    actions: [
                      TextButton(onPressed: () => Navigator.pop(c),
                          child: const Text('OK')),
                    ],
                  ));
                }
              }),
          ],
        );
      });
    });
  }
} // fin _VentanaImeiState

// ============================================================
//  CIERRE DE CAJA — carga y guarda en la API
// ============================================================
class VentanaCierre extends StatefulWidget {
  const VentanaCierre({super.key});
  @override State<VentanaCierre> createState() => _VentanaCierreState();
}

class _VentanaCierreState extends State<VentanaCierre> {
  final List<String> tiendasDisponibles = ConfigSistema.tiendas;
  List<CierreCaja> _cierres = [];
  bool _cargando = true;
  String _tiendaFiltro = "Todas";

  @override
  void initState() {
    super.initState();
    // Si el usuario no es admin/dueño/gerente, forzar el filtro a su
    // tienda asignada — no puede ver ni seleccionar otras tiendas.
    if (!puedeVerTodasLasTiendas()) {
      final miTienda = tiendaUsuarioActual();
      if (miTienda.isNotEmpty) _tiendaFiltro = miTienda;
    }
    _cargar();
  }

  Future<void> _cargar() async {
    setState(() => _cargando = true);
    try {
      final raw = await _Api.get('cierres');
      var lista = ((raw as List?) ?? []).map((m) => CierreCaja.fromMap(m)).toList();
      // Restricción server-agnostic: si no es rol alto, quitamos cierres
      // de otras tiendas antes de mostrarlos.
      if (!puedeVerTodasLasTiendas()) {
        final miTienda = tiendaUsuarioActual();
        if (miTienda.isNotEmpty) {
          lista = lista.where((c) => c.tienda == miTienda).toList();
        }
      }
      _cierres = lista;
      cierresGlobal = _cierres;
    } catch (e) {
      debugPrint('[_cargar] Error: $e');
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Error al cargar datos: $e'), backgroundColor: AppColors.statusRed, duration: const Duration(seconds: 4)));
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  void _verDetalleCierre(CierreCaja cierre) {
    final fecha = "${cierre.fecha.day.toString().padLeft(2,'0')}/"
                  "${cierre.fecha.month.toString().padLeft(2,'0')}/"
                  "${cierre.fecha.year}";

    showDialog(context: context, builder: (ctx) => AlertDialog(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      title: const Row(children: [
        Icon(Icons.account_balance_wallet, color: AppColors.royalBlue),
        SizedBox(width: 8),
        Text("Detalle de Cierre",
          style: TextStyle(color: AppColors.royalBlue, fontWeight: FontWeight.bold)),
      ]),
      content: SingleChildScrollView(
        child: Column(mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start, children: [
          // ── Info general ──────────────────────────────────
          _filaInfo("ID Operación", cierre.id),
          _filaInfo("Tienda", cierre.tienda),
          _filaInfo("Fecha", fecha),
          _filaInfo("Responsable", cierre.usuarioCierre),
          const Divider(height: 20),

          // ── Métodos de pago con colores ───────────────────
          const Row(children: [
            Icon(Icons.payments_outlined, size: 14, color: AppColors.textSecondary),
            SizedBox(width: 6),
            Text("MÉTODOS DE PAGO",
              style: TextStyle(fontWeight: FontWeight.bold,
                fontSize: 12, letterSpacing: 0.5, color: AppColors.textSecondary)),
          ]),
          const SizedBox(height: 10),

          ...cierre.metodosPago.entries.map((e) {
            final color = _colorMetodoPago(e.key);
            return Container(
              margin: const EdgeInsets.only(bottom: 8),
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
              decoration: BoxDecoration(
                color: color.withValues(alpha: 0.06),
                borderRadius: BorderRadius.circular(10),
                border: Border.all(color: color.withValues(alpha: 0.25)),
              ),
              child: Row(children: [
                Container(
                  width: 32, height: 32,
                  decoration: BoxDecoration(
                    color: color.withValues(alpha: 0.12),
                    borderRadius: BorderRadius.circular(8)),
                  child: Icon(_iconoMetodoPago(e.key), color: color, size: 17),
                ),
                const SizedBox(width: 10),
                Expanded(child: Text(e.key,
                  style: TextStyle(fontWeight: FontWeight.w600,
                    fontSize: 13, color: color))),
                Text(formatMontoPorMetodo(e.value, e.key),
                  style: TextStyle(fontWeight: FontWeight.bold,
                    fontSize: 15, color: color)),
              ]),
            );
          }),

          const Divider(height: 20),
          // ── Total destacado ───────────────────────────────
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: AppColors.statusGreen.withValues(alpha: 0.08),
              borderRadius: BorderRadius.circular(10),
            ),
            child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
              const Text("TOTAL DEL CIERRE",
                style: TextStyle(fontWeight: FontWeight.bold,
                  fontSize: 13, color: AppColors.statusGreen)),
              // Total por moneda real ("$X + Bs Y"). `montoTotal` de los
              // cierres viejos suma Bs con $ y no sirve para mostrarse.
              Flexible(child: Text(
                cierre.metodosPago.isEmpty
                    ? formatCurrency(cierre.montoTotal)
                    : formatTotalesPorMetodos(cierre.metodosPago),
                textAlign: TextAlign.right,
                style: const TextStyle(fontWeight: FontWeight.bold,
                  fontSize: 18, color: AppColors.statusGreen))),
            ]),
          ),
        ]),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(ctx),
          child: const Text("CERRAR")),
      ],
    ));
  }

  Widget _filaInfo(String label, String valor) => Padding(
    padding: const EdgeInsets.symmetric(vertical: 4),
    child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
      Text(label, style: const TextStyle(fontSize: 13)),
      Text(valor, style: const TextStyle(fontWeight: FontWeight.w600, fontSize: 13)),
    ]));

  Future<void> _dialogoNuevoCierre() async {
    String tiendaSel = tiendasDisponibles[0];
    DateTime fechaSel = DateTime.now();
    bool generando = false;
    // Preview calculado antes de guardar
    Map<String, double>? previewMetodos;
    double previewTotal = 0;
    bool calculando = false;

    await showDialog(context: context, builder: (ctx) => StatefulBuilder(
      builder: (dialogCtx, setS) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Row(children: [
          Icon(Icons.summarize, color: AppColors.royalBlue),
          SizedBox(width: 8),
          Text("Generar Cierre de Caja"),
        ]),
        content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
          DropdownButtonFormField<String>(
            value: tiendaSel,
            decoration: const InputDecoration(
              labelText: "Tienda",
              prefixIcon: Icon(Icons.store_outlined)),
            items: tiendasDisponibles
              .map((t) => DropdownMenuItem(value: t, child: Text(t)))
              .toList(),
            onChanged: generando ? null : (val) {
              setS(() {
                tiendaSel = val!;
                previewMetodos = null; // resetear preview al cambiar tienda
              });
            }),
          const SizedBox(height: 16),
          InkWell(
            borderRadius: BorderRadius.circular(10),
            onTap: generando ? null : () async {
              final picked = await showDatePicker(
                context: dialogCtx,
                initialDate: fechaSel,
                firstDate: DateTime(2023),
                lastDate: DateTime.now());
              if (picked != null) {
                setS(() {
                  fechaSel = picked;
                  previewMetodos = null; // resetear preview al cambiar fecha
                });
              }
            },
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
              decoration: BoxDecoration(
                color: AppColors.surfaceGrey,
                borderRadius: BorderRadius.circular(10),
                border: Border.all(color: AppColors.cardBorder),
              ),
              child: Row(children: [
                const Icon(Icons.calendar_today, color: AppColors.primaryBlue, size: 18),
                const SizedBox(width: 10),
                Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  const Text("Fecha del cierre",
                    style: TextStyle(fontSize: 11, color: AppColors.textSecondary)),
                  Text(
                    "${fechaSel.day.toString().padLeft(2,'0')}/"
                    "${fechaSel.month.toString().padLeft(2,'0')}/"
                    "${fechaSel.year}",
                    style: const TextStyle(fontWeight: FontWeight.w600, fontSize: 15)),
                ]),
                const Spacer(),
                const Icon(Icons.edit_calendar_outlined, size: 16, color: AppColors.textSecondary),
              ]),
            ),
          ),

          // ── Botón para previsualizar ──────────────────────
          const SizedBox(height: 12),
          SizedBox(
            width: double.infinity,
            child: OutlinedButton.icon(
              icon: calculando
                ? const SizedBox(width: 14, height: 14,
                    child: CircularProgressIndicator(strokeWidth: 2))
                : const Icon(Icons.preview_outlined, size: 16),
              label: Text(calculando ? "Calculando..." : "Previsualizar ventas del día"),
              style: OutlinedButton.styleFrom(
                side: const BorderSide(color: AppColors.royalBlue),
                foregroundColor: AppColors.royalBlue),
              onPressed: (calculando || generando) ? null : () async {
                setS(() => calculando = true);
                try {
                  final rawV = await _Api.get('facturas');
                  final Map<String, double> metodos = {};
                  double total = 0;
                  for (final v in ((rawV as List?) ?? [])) {
                    try {
                      final partes = (v['fecha'] as String? ?? '').split("/");
                      if (partes.length != 3) continue;
                      final fFact = DateTime(int.parse(partes[2]), int.parse(partes[1]), int.parse(partes[0]));
                      if (v['tienda'] != tiendaSel ||
                          fFact.year != fechaSel.year ||
                          fFact.month != fechaSel.month ||
                          fFact.day != fechaSel.day) continue;
                      // Total en $ equivalentes: los pagos en Bs se
                      // convierten con su tasa (antes se sumaban crudos).
                      final pagosV = (v['pagos'] as List?) ?? [];
                      total += pagosV.isEmpty
                          ? (double.tryParse(v['total'].toString()) ?? 0)
                          : totalesPagosPorMoneda(pagosV).equivUsd;
                      final pagos = v['pagos'] as List? ?? [];
                      if (pagos.isNotEmpty) {
                        for (final p in pagos) {
                          final met = p['metodo']?.toString() ?? 'Otros';
                          metodos[met] = (metodos[met] ?? 0) + (double.tryParse(p['monto'].toString()) ?? 0);
                        }
                      } else {
                        metodos['Ventas del día'] = (metodos['Ventas del día'] ?? 0) +
                            (double.tryParse(v['total'].toString()) ?? 0);
                      }
                    } catch (_) {}
                  }
                  setS(() {
                    previewMetodos = metodos;
                    previewTotal   = total;
                    calculando     = false;
                  });
                } catch (e) {
                  setS(() => calculando = false);
                }
              },
            ),
          ),

          // ── Preview resultado ─────────────────────────────
          if (previewMetodos != null) ...[
            const SizedBox(height: 12),
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: AppColors.surfaceGrey,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: AppColors.cardBorder),
              ),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Row(children: [
                  const Icon(Icons.receipt_long, size: 14, color: AppColors.royalBlue),
                  const SizedBox(width: 6),
                  Text("$tiendaSel — ${fechaSel.day.toString().padLeft(2,'0')}/${fechaSel.month.toString().padLeft(2,'0')}/${fechaSel.year}",
                    style: const TextStyle(fontWeight: FontWeight.w600,
                      fontSize: 12, color: AppColors.royalBlue)),
                ]),
                const SizedBox(height: 8),
                if (previewMetodos!.isEmpty)
                  const Text("Sin ventas registradas para este día.",
                    style: TextStyle(color: AppColors.textSecondary, fontSize: 12))
                else ...[
                  ...previewMetodos!.entries.map((e) {
                    final color = _colorMetodoPago(e.key);
                    return Padding(
                      padding: const EdgeInsets.symmetric(vertical: 3),
                      child: Row(children: [
                        Icon(_iconoMetodoPago(e.key), size: 14, color: color),
                        const SizedBox(width: 6),
                        Expanded(child: Text(e.key,
                          style: TextStyle(fontSize: 12, color: color, fontWeight: FontWeight.w500))),
                        Text(formatMontoPorMetodo(e.value, e.key),
                          style: TextStyle(fontSize: 12, fontWeight: FontWeight.bold, color: color)),
                      ]),
                    );
                  }),
                  const Divider(height: 12),
                  Row(children: [
                    const Expanded(child: Text("TOTAL",
                      style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13))),
                    Flexible(child: Text(
                      formatTotalesPorMetodos(previewMetodos!),
                      textAlign: TextAlign.right,
                      style: const TextStyle(fontWeight: FontWeight.bold,
                        fontSize: 15, color: AppColors.statusGreen))),
                  ]),
                  // Equivalente en $ (Bs convertidos con la tasa de cada
                  // pago). Es lo que se guarda como total del cierre.
                  Align(
                    alignment: Alignment.centerRight,
                    child: Text("Equivale a ${formatCurrency(previewTotal)}",
                      style: const TextStyle(fontSize: 11,
                        color: AppColors.textSecondary,
                        fontStyle: FontStyle.italic))),
                ],
              ]),
            ),
          ],

          if (generando) ...[
            const SizedBox(height: 12),
            const Row(children: [
              SizedBox(width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2)),
              SizedBox(width: 12),
              Text("Guardando cierre...",
                style: TextStyle(fontSize: 13, color: AppColors.textSecondary)),
            ]),
          ],
        ])),
        actions: [
          TextButton(
            onPressed: generando ? null : () => Navigator.pop(dialogCtx),
            child: const Text("CANCELAR")),
          ElevatedButton.icon(
            style: ElevatedButton.styleFrom(backgroundColor: AppColors.royalBlue),
            icon: generando
              ? const SizedBox(width: 16, height: 16,
                  child: CircularProgressIndicator(color: Colors.white, strokeWidth: 2))
              : const Icon(Icons.check_circle_outline, color: Colors.white, size: 18),
            label: Text(generando ? "Generando..." : "GENERAR",
              style: const TextStyle(color: Colors.white, fontWeight: FontWeight.bold)),
            onPressed: generando ? null : () async {
              setS(() => generando = true);
              try {
                // Usar los datos del preview si ya están calculados, sino recalcular
                Map<String, double> resumenMetodos;
                double totalGeneral;

                if (previewMetodos != null) {
                  resumenMetodos = previewMetodos!;
                  totalGeneral   = previewTotal;
                } else {
                  resumenMetodos = {};
                  totalGeneral   = 0;
                  final rawV = await _Api.get('facturas');
                  for (final v in ((rawV as List?) ?? [])) {
                    try {
                      final partes = (v['fecha'] as String? ?? '').split("/");
                      if (partes.length != 3) continue;
                      final fFact = DateTime(int.parse(partes[2]), int.parse(partes[1]), int.parse(partes[0]));
                      if (v['tienda'] != tiendaSel ||
                          fFact.year  != fechaSel.year ||
                          fFact.month != fechaSel.month ||
                          fFact.day   != fechaSel.day) continue;
                      final pagosV = (v['pagos'] as List?) ?? [];
                      totalGeneral += pagosV.isEmpty
                          ? (double.tryParse(v['total'].toString()) ?? 0)
                          : totalesPagosPorMoneda(pagosV).equivUsd;
                      final pagos = v['pagos'] as List? ?? [];
                      if (pagos.isNotEmpty) {
                        for (final p in pagos) {
                          final metodo = p['metodo']?.toString() ?? 'Otros';
                          resumenMetodos[metodo] = (resumenMetodos[metodo] ?? 0) +
                              (double.tryParse(p['monto'].toString()) ?? 0);
                        }
                      } else {
                        resumenMetodos['Ventas del día'] = (resumenMetodos['Ventas del día'] ?? 0) +
                            (double.tryParse(v['total'].toString()) ?? 0);
                      }
                    } catch (e) { debugPrint('Error parseo cierre: $e'); }
                  }
                }

                final now = DateTime.now();
                final uid = "C-${tiendaSel.substring(0, math.min(3, tiendaSel.length)).toUpperCase()}"
                            "-${now.day.toString().padLeft(2,'0')}"
                            "${now.month.toString().padLeft(2,'0')}"
                            "${now.year.toString().substring(2)}"
                            "-${now.millisecondsSinceEpoch.toString().substring(9)}";

                await _Api.post('cierres', {
                  'uid'           : uid,
                  'tienda'        : tiendaSel,
                  'monto_total'   : totalGeneral,
                  'usuario_cierre': usuarioSesion?.nombre ?? "Sistema",
                  'metodos'       : resumenMetodos.entries
                      .map((e) => {'metodo': e.key, 'monto': e.value}).toList(),
                });

                if (!dialogCtx.mounted) return;
                Navigator.pop(dialogCtx);
                await _cargar();

                if (mounted) {
                  ScaffoldMessenger.of(this.context).showSnackBar(SnackBar(
                    content: Text(
                      "✅ Cierre generado — Total: ${formatTotalesPorMetodos(resumenMetodos)} "
                      "· ${resumenMetodos.length} método(s)"),
                    backgroundColor: AppColors.statusGreen,
                    duration: const Duration(seconds: 5)));
                }
              } catch (e) {
                setS(() => generando = false);
                if (dialogCtx.mounted) {
                  ScaffoldMessenger.of(this.context).showSnackBar(SnackBar(
                    content: Text("Error al generar cierre: $e"),
                    backgroundColor: AppColors.statusRed,
                    duration: const Duration(seconds: 5)));
                }
              }
            },
          ),
        ],
      )));
  }

  @override
  Widget build(BuildContext context) {
    final cierresFiltrados = _tiendaFiltro == "Todas"
        ? _cierres
        : _cierres.where((c) => c.tienda == _tiendaFiltro).toList();

    return Scaffold(
      appBar: AppBar(
        title: const Text("Cierres de Caja"),
        actions: [
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: "Actualizar",
            onPressed: _cargar),
        ],
      ),
      body: Column(children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 16, 16, 8),
          child: SizedBox(width: double.infinity,
            child: ElevatedButton.icon(
              style: ElevatedButton.styleFrom(
                backgroundColor: AppColors.royalBlue,
                padding: const EdgeInsets.symmetric(vertical: 14),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(10))),
              icon: const Icon(Icons.summarize, color: Colors.white),
              label: const Text("GENERAR NUEVO CIERRE",
                style: TextStyle(color: Colors.white,
                  fontWeight: FontWeight.bold, fontSize: 15)),
              onPressed: _dialogoNuevoCierre))),

        // ── Filtro por tienda (sólo Admin/Dueño/Gerente) ───────
        if (puedeVerTodasLasTiendas() && !_cargando && _cierres.isNotEmpty)
          Padding(
            padding: const EdgeInsets.only(bottom: 4),
            child: SizedBox(
              height: 38,
              child: ListView(
                padding: const EdgeInsets.symmetric(horizontal: 12),
                scrollDirection: Axis.horizontal,
                children: ["Todas", ...tiendasDisponibles].map((t) {
                  final sel = _tiendaFiltro == t;
                  return Padding(
                    padding: const EdgeInsets.only(right: 8),
                    child: ChoiceChip(
                      label: Text(t, style: TextStyle(
                        fontSize: 12,
                        color: sel ? Colors.white : AppColors.royalBlue,
                        fontWeight: sel ? FontWeight.bold : FontWeight.normal)),
                      selected: sel,
                      selectedColor: AppColors.royalBlue,
                      backgroundColor: AppColors.royalBlue.withValues(alpha: 0.08),
                      side: BorderSide(
                        color: sel ? AppColors.royalBlue : AppColors.royalBlue.withValues(alpha: 0.3)),
                      onSelected: (_) => setState(() => _tiendaFiltro = t),
                    ));
                }).toList(),
              ),
            ),
          ),
        // Indicador para no-admin de "solo tu tienda"
        if (!puedeVerTodasLasTiendas() && tiendaUsuarioActual().isNotEmpty)
          Container(
            width: double.infinity,
            color: AppColors.royalBlue.withValues(alpha: 0.06),
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 6),
            child: Row(children: [
              const Icon(Icons.store_outlined,
                size: 14, color: AppColors.royalBlue),
              const SizedBox(width: 6),
              Text('Cierres de ${tiendaUsuarioActual()}',
                style: const TextStyle(fontSize: 11,
                  color: AppColors.royalBlue, fontWeight: FontWeight.w600)),
            ]),
          ),

        if (_cargando)
          const Expanded(child: Center(child: CircularProgressIndicator()))
        else if (cierresFiltrados.isEmpty)
          const Expanded(child: EmptyState(
            mensaje: "No hay cierres registrados.\nPresione el botón para generar uno.",
            icono: Icons.account_balance_wallet_outlined))
        else
          Expanded(child: RefreshIndicator(
            onRefresh: _cargar,
            child: ListView.builder(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
              itemCount: cierresFiltrados.length,
              itemBuilder: (ctx, i) {
                final c = cierresFiltrados[i];
                final fecha =
                  "${c.fecha.day.toString().padLeft(2,'0')}/"
                  "${c.fecha.month.toString().padLeft(2,'0')}/"
                  "${c.fecha.year}";
                return Card(
                  margin: const EdgeInsets.only(bottom: 8),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(12)),
                  elevation: 1,
                  child: InkWell(
                    borderRadius: BorderRadius.circular(12),
                    onTap: () => _verDetalleCierre(c),
                    child: Padding(
                      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                        // ── Fila superior: ícono + tienda + total ──
                        Row(children: [
                          Container(
                            width: 44, height: 44,
                            decoration: BoxDecoration(
                              color: AppColors.royalBlue.withValues(alpha: 0.1),
                              borderRadius: BorderRadius.circular(10)),
                            child: const Icon(Icons.account_balance_wallet_outlined,
                              color: AppColors.royalBlue, size: 22)),
                          const SizedBox(width: 12),
                          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                            Text(c.tienda,
                              style: const TextStyle(fontWeight: FontWeight.w600, fontSize: 15)),
                            Text(fecha,
                              style: const TextStyle(fontSize: 12, color: AppColors.textSecondary)),
                            Text("Por: ${c.usuarioCierre}",
                              style: const TextStyle(fontSize: 11, color: AppColors.textSecondary)),
                          ])),
                          Column(mainAxisAlignment: MainAxisAlignment.center,
                            crossAxisAlignment: CrossAxisAlignment.end, children: [
                            Text(
                              c.metodosPago.isEmpty
                                  ? formatCurrency(c.montoTotal)
                                  : formatTotalesPorMetodos(c.metodosPago),
                              style: const TextStyle(
                                color: AppColors.statusGreen,
                                fontWeight: FontWeight.bold, fontSize: 16)),
                            const Text("TOTAL", style: TextStyle(fontSize: 9, color: AppColors.textSecondary)),
                          ]),
                        ]),
                        // ── Métodos de pago ────────────────────────
                        // Mostramos SIEMPRE el desglose (o un mensaje claro
                        // si no hay datos). Antes solo se mostraba cuando
                        // metodosPago no estaba vacío — pero cuando un
                        // cierre se generó sin pagos detallados quedaba
                        // sin desglose visible y el cliente no entendía
                        // qué método había generado el total.
                        const SizedBox(height: 10),
                        const Divider(height: 1),
                        const SizedBox(height: 8),
                        if (c.metodosPago.isEmpty)
                          const Padding(
                            padding: EdgeInsets.symmetric(vertical: 4),
                            child: Text(
                              'Sin desglose de métodos de pago en este cierre',
                              style: TextStyle(
                                fontSize: 11,
                                fontStyle: FontStyle.italic,
                                color: AppColors.textSecondary,
                              ),
                            ),
                          )
                        else
                          // Lista vertical: cada método en su propia fila,
                          // bien legible, con monto en la moneda correcta.
                          // Antes era un Wrap de chips minúsculos donde el
                          // monto se cortaba con muchos métodos.
                          Column(
                            crossAxisAlignment: CrossAxisAlignment.stretch,
                            children: c.metodosPago.entries.map((e) {
                              final color = _colorMetodoPago(e.key);
                              return Padding(
                                padding: const EdgeInsets.symmetric(vertical: 3),
                                child: Row(children: [
                                  Container(
                                    width: 26, height: 26,
                                    decoration: BoxDecoration(
                                      color: color.withValues(alpha: 0.12),
                                      borderRadius: BorderRadius.circular(6),
                                    ),
                                    child: Icon(_iconoMetodoPago(e.key),
                                        size: 14, color: color),
                                  ),
                                  const SizedBox(width: 8),
                                  Expanded(
                                    child: Text(
                                      e.key,
                                      style: TextStyle(
                                        fontSize: 12.5,
                                        color: color,
                                        fontWeight: FontWeight.w500,
                                      ),
                                    ),
                                  ),
                                  Text(
                                    formatMontoPorMetodo(e.value, e.key),
                                    style: TextStyle(
                                      fontSize: 13,
                                      fontWeight: FontWeight.bold,
                                      color: color,
                                    ),
                                  ),
                                ]),
                              );
                            }).toList(),
                          ),
                      ]),
                    ),
                  ));
              }),
          )),
      ]),
    );
  }

  IconData _iconoMetodoPago(String metodo) {
    final m = metodo.toLowerCase();
    if (m.contains('efectivo') || m.contains('cash')) return Icons.payments_outlined;
    if (m.contains('transferencia') || m.contains('transfer')) return Icons.swap_horiz;
    if (m.contains('tarjeta') || m.contains('card') || m.contains('débito') || m.contains('credito')) return Icons.credit_card;
    if (m.contains('zelle')) return Icons.send_to_mobile;
    if (m.contains('pago') && m.contains('movil')) return Icons.phone_android;
    if (m.contains('dolar') || m.contains('divisas') || m.contains('usd')) return Icons.attach_money;
    if (m.contains('bolivar') || m.contains('bs')) return Icons.currency_exchange;
    if (m.contains('cashea') || m.contains('weppa') || m.contains('krece') || m.contains('financ')) return Icons.account_balance_outlined;
    return Icons.payment;
  }

  Color _colorMetodoPago(String metodo) {
    final m = metodo.toLowerCase();
    if (m.contains('efectivo') || m.contains('cash'))      return const Color(0xFF2E7D32); // verde oscuro
    if (m.contains('transferencia') || m.contains('transfer')) return const Color(0xFF1565C0); // azul
    if (m.contains('tarjeta') || m.contains('débito') || m.contains('credito')) return const Color(0xFF6A1B9A); // morado
    if (m.contains('zelle'))                               return const Color(0xFF6200EA); // púrpura
    if (m.contains('pago') && m.contains('movil'))         return const Color(0xFFE65100); // naranja
    if (m.contains('dolar') || m.contains('usd'))          return const Color(0xFF00695C); // teal
    if (m.contains('bolivar') || m.contains('bs'))         return const Color(0xFF283593); // índigo
    if (m.contains('cashea'))                              return const Color(0xFFC62828); // rojo
    if (m.contains('weppa') || m.contains('krece'))        return const Color(0xFF00838F); // cyan
    return AppColors.primaryBlue;
  }
}

// ============================================================
//  FORMULARIO FACTURA — guarda en la API
// ============================================================
class FormularioFactura extends StatefulWidget {
  final now = DateTime.now();
  final String tienda;
  final FacturaModel? facturaAEditar;
  FormularioFactura({super.key, required this.tienda, this.facturaAEditar});
  @override State<FormularioFactura> createState() => _FormularioFacturaState();
}

class _FormularioFacturaState extends State<FormularioFactura>
    with WidgetsBindingObserver {
  final _telCtrl=TextEditingController();
  final _correoClienteCtrl=TextEditingController();
  final _codigo=TextEditingController(), _montoPago=TextEditingController();
  final _deudaFpb=TextEditingController(); // monto de deuda para FPB
  String _metodo = ConfigSistema.metodossPago.isNotEmpty ? ConfigSistema.metodossPago.first : "Punto de venta";
  String _tipoVenta = "Contado";
  String _nombreProductoEncontrado = "";
  String? _financiadorSeleccionado;
  late TextEditingController _cliente, _cedula, _nro;
  List<ImeiRegistro> _equipos = [];
  List<Producto> _items = [];
  List<PagoFactura> _pagos = [];

  /// Clave única del borrador persistido. Usamos una clave por usuario
  /// para que dos sesiones distintas no se pisen.
  String get _claveBorrador =>
      'factura_borrador_${usuarioSesion?.correo ?? "anon"}';

  /// Indica si ya se intentó cargar el borrador (para evitar restaurarlo
  /// más de una vez en hot-reload o múltiples didChangeDependencies).
  bool _borradorRestaurado = false;

  /// Guard para evitar que el usuario haga doble-tap en "Guardar"
  /// y se dispare el POST dos veces (lo que provocaba el error 1062
  /// "Duplicate entry" de nro_factura).
  bool _guardando = false;

  // ── Financiamiento POR PRODUCTO (bug #1) ──────────────────
  // Cada producto e IMEI agregado a la factura puede tener su propio
  // tipo de venta (Contado / Cashea / Weppa / Krece / FPB) y financiador.
  // Así se puede, por ejemplo, financiar un teléfono por Weppa y vender
  // un accesorio de contado en la misma factura.
  //
  // Se indexan por la referencia del objeto (identityHashCode) en vez de
  // por posición en la lista, para no "mover" el dato si el usuario
  // reordena o elimina items.
  final Map<int, String>  _tipoVentaItem      = {};   // identityHash → tipoVenta
  final Map<int, String?> _financiadorItem    = {};   // identityHash → financiador
  final Map<int, String>  _tipoVentaEquipo    = {};   // identityHash → tipoVenta
  final Map<int, String?> _financiadorEquipo  = {};   // identityHash → financiador
  // ── Cuotas del financiamiento (solo aplica a financiados) ──
  final Map<int, int>    _cuotasEquipo        = {};   // identityHash → n° cuotas
  final Map<int, double> _montoCuotaEquipo    = {};   // identityHash → monto por cuota
  final Map<int, int>    _cuotasItem          = {};
  final Map<int, double> _montoCuotaItem      = {};
  // ── Lista de precios usada por equipo/item (para distinguir
  // promoción vs lista normal de la misma financiadora) ──
  final Map<int, String> _listaEquipo         = {};   // identityHash → nombre lista
  final Map<int, String> _listaItem           = {};
  // ── Vendedor asignado a cada equipo/item ──
  // Si está vacío, el reporte usa el creador de la factura como vendedor.
  // Permite que un cajero facture la venta de otro vendedor y que cada
  // producto se atribuya al vendedor correcto.
  final Map<int, String> _vendedorEquipo      = {};   // identityHash → nombre vendedor
  final Map<int, String> _vendedorItem        = {};

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _cliente = TextEditingController(text: widget.facturaAEditar?.cliente ?? "");
    _cedula = TextEditingController(text: widget.facturaAEditar?.cedula ?? "");
    // ── Generación de nro_factura ÚNICO ─────────────────────────────
    // Antes: ts + (ts % 9999) — totalmente determinista, dos formularios
    // abiertos en el mismo milisegundo generaban el MISMO número.
    // Ahora: timestamp + 4 dígitos REALMENTE aleatorios + 2 más de jitter
    // para casi eliminar la posibilidad de colisión.
    final ts = DateTime.now().millisecondsSinceEpoch;
    final rnd = math.Random.secure();
    final r1 = rnd.nextInt(10000).toString().padLeft(4, '0');
    final r2 = rnd.nextInt(100).toString().padLeft(2, '0');
    _nro = TextEditingController(
        text: widget.facturaAEditar?.nroFactura ?? "$ts-$r1$r2");
    if (widget.facturaAEditar != null) {
      _equipos = List.from(widget.facturaAEditar!.equipos);
      _items = List.from(widget.facturaAEditar!.itemsSinImei);
      _pagos = List.from(widget.facturaAEditar!.pagos);
      // ── REHIDRATAR datos del cliente al editar ──
      // Antes solo se restauraban cliente y cédula. El teléfono y
      // el correo quedaban en blanco, dando la sensación de que la
      // factura "no cargó los datos del cliente". Ahora se restauran
      // todos los campos.
      _telCtrl.text = widget.facturaAEditar!.telefono;

      // ── REHIDRATAR maps de Financiado/Contado, cuotas, lista y
      //    vendedor para cada equipo e ítem ──
      // Los maps _tipoVentaEquipo, _financiadorEquipo, etc. están
      // indexados por identityHashCode(equipo). Al cargar una factura
      // para editar, los ImeiRegistro y Producto son objetos NUEVOS
      // con identityHashCode distinto al de cuando se creó la factura.
      // Resultado: si no los rellenamos aquí, todos los chips F/D
      // aparecen como Contado y la financiadora se pierde.
      _rehidratarMapsDesdeFactura(widget.facturaAEditar!);
    }
    // Recargar catálogo con stock actualizado al abrir el formulario.
    // Si es una factura NUEVA (no edición), también intentar restaurar
    // un borrador previo si el proceso fue terminado por el sistema
    // (por ejemplo al abrir el scanner en pantalla completa con poca RAM).
    _refrescarCatalogo().then((_) {
      if (widget.facturaAEditar == null) _restaurarBorrador();
    });
  }

  /// Rellena los maps `_tipoVentaEquipo`, `_financiadorEquipo`,
  /// `_cuotasEquipo`, `_montoCuotaEquipo`, `_listaEquipo`,
  /// `_vendedorEquipo` (y sus equivalentes para items) usando los
  /// datos REALES de la factura que se está editando.
  ///
  /// Estrategia:
  ///   1. Si la factura tiene UN solo pago de tipo "Financiado",
  ///      asumimos que TODOS los equipos/items de esa factura están
  ///      financiados por la misma financiadora con las mismas cuotas
  ///      y lista. Esta es la suposición correcta para la inmensa
  ///      mayoría de las facturas reales (una factura = una venta
  ///      financiada con una sola financiadora).
  ///   2. Si la factura tiene MÚLTIPLES pagos financiados (caso raro:
  ///      mitad con Cashea y mitad con Krece), tomamos el primero como
  ///      default. El usuario puede ajustar cada equipo individualmente.
  ///   3. Si la factura es 100% contado, todos los chips quedan en
  ///      Contado y los maps de cuotas/lista quedan vacíos.
  ///   4. El vendedor por producto se lee de los maps que ya trae
  ///      `FacturaModel` (vendedorPorImei, vendedorPorCodigo).
  void _rehidratarMapsDesdeFactura(FacturaModel f) {
    // ── Localizar el pago financiado de referencia ──
    PagoFactura? pagoFinanciado;
    for (final p in f.pagos) {
      if (p.tipo == 'Financiado') {
        pagoFinanciado = p;
        break;
      }
    }

    final esFinanciada = pagoFinanciado != null;
    final financiadora = pagoFinanciado?.financiadora ?? '';
    final cuotas       = pagoFinanciado?.numeroCuotas ?? 0;
    final montoCuota   = pagoFinanciado?.montoCuota ?? 0.0;
    final lista        = pagoFinanciado?.nombreLista ?? '';

    // ── Rehidratar equipos ──
    for (final e in _equipos) {
      final hash = identityHashCode(e);
      _tipoVentaEquipo[hash] = esFinanciada ? 'Financiado' : 'Contado';
      if (esFinanciada && financiadora.isNotEmpty) {
        _financiadorEquipo[hash] = financiadora;
      }
      if (cuotas > 0) _cuotasEquipo[hash] = cuotas;
      if (montoCuota > 0) _montoCuotaEquipo[hash] = montoCuota;
      if (lista.isNotEmpty) _listaEquipo[hash] = lista;
      // Vendedor del equipo (ya viene en el modelo)
      final v = f.vendedorPorImei[e.imei];
      if (v != null && v.isNotEmpty) _vendedorEquipo[hash] = v;
    }

    // ── Rehidratar items ──
    for (final it in _items) {
      final hash = identityHashCode(it);
      _tipoVentaItem[hash] = esFinanciada ? 'Financiado' : 'Contado';
      if (esFinanciada && financiadora.isNotEmpty) {
        _financiadorItem[hash] = financiadora;
      }
      if (cuotas > 0) _cuotasItem[hash] = cuotas;
      if (montoCuota > 0) _montoCuotaItem[hash] = montoCuota;
      if (lista.isNotEmpty) _listaItem[hash] = lista;
      // Vendedor del item
      final v = f.vendedorPorCodigo[it.codigo];
      if (v != null && v.isNotEmpty) _vendedorItem[hash] = v;
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    super.didChangeAppLifecycleState(state);
    // Cuando la app pasa a background (el usuario abre cámara, otra
    // app, recibe llamada, etc.) guardamos el borrador para no perder
    // el trabajo si el SO termina el proceso.
    if (state == AppLifecycleState.paused ||
        state == AppLifecycleState.inactive ||
        state == AppLifecycleState.hidden) {
      _guardarBorrador();
    }
  }

  /// Guarda el estado actual de la factura como borrador en SharedPreferences.
  /// Solo guarda si NO es edición y si hay algún dato significativo.
  Future<void> _guardarBorrador() async {
    if (widget.facturaAEditar != null) return; // sólo facturas nuevas
    if (_equipos.isEmpty && _items.isEmpty &&
        _cliente.text.trim().isEmpty &&
        _cedula.text.trim().isEmpty) {
      return; // no hay nada que guardar
    }
    try {
      final data = {
        'cliente': _cliente.text,
        'cedula': _cedula.text,
        'telefono': _telCtrl.text,
        'correo': _correoClienteCtrl.text,
        'nro': _nro.text,
        'tipoVenta': _tipoVenta,
        'deudaFpb': _deudaFpb.text,
        'equiposImeis': _equipos.map((e) => e.imei).toList(),
        'itemsCodigos': _items.map((p) => p.codigo).toList(),
        // Pago completo (incluye referencia, cédula y teléfono del
        // pagador del pago móvil) para no perder datos de auditoría.
        'pagos': _pagos.map((p) => p.toMap()).toList(),
        'tipoVentaItem': _tipoVentaItem.map(
            (k, v) => MapEntry(k.toString(), v)),
        'financiadorItem': _financiadorItem.map(
            (k, v) => MapEntry(k.toString(), v)),
        'tipoVentaEquipo': _tipoVentaEquipo.map(
            (k, v) => MapEntry(k.toString(), v)),
        'financiadorEquipo': _financiadorEquipo.map(
            (k, v) => MapEntry(k.toString(), v)),
        'guardadoEn': DateTime.now().toIso8601String(),
      };
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(_claveBorrador, jsonEncode(data));
    } catch (e) {
      debugPrint('[Factura] Error guardando borrador: $e');
    }
  }

  /// Restaura un borrador previo si existe y es reciente (< 12 horas).
  /// Solo se llama si la factura es NUEVA (no edición).
  Future<void> _restaurarBorrador() async {
    if (_borradorRestaurado) return;
    _borradorRestaurado = true;
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_claveBorrador);
      if (raw == null || raw.isEmpty) return;
      final data = jsonDecode(raw) as Map<String, dynamic>;

      // Si el borrador es viejo (> 12h) lo descartamos para no llenar
      // el formulario con datos obsoletos.
      final guardadoEn = DateTime.tryParse(data['guardadoEn'] ?? '');
      if (guardadoEn != null &&
          DateTime.now().difference(guardadoEn).inHours > 12) {
        await prefs.remove(_claveBorrador);
        return;
      }

      // Si ya hay datos en el formulario (raro pero posible), no restaurar.
      if (_equipos.isNotEmpty || _items.isNotEmpty ||
          _cliente.text.isNotEmpty) {
        return;
      }

      _cliente.text = (data['cliente'] ?? '').toString();
      _cedula.text = (data['cedula'] ?? '').toString();
      _telCtrl.text = (data['telefono'] ?? '').toString();
      _correoClienteCtrl.text = (data['correo'] ?? '').toString();
      if ((data['nro'] ?? '').toString().isNotEmpty) {
        _nro.text = data['nro'].toString();
      }
      _tipoVenta = (data['tipoVenta'] ?? 'Contado').toString();
      _deudaFpb.text = (data['deudaFpb'] ?? '').toString();

      // Reconstruir equipos por IMEI
      // Un borrador viejo puede traer equipos que desde entonces se
      // trasladaron a otra tienda: ésos no se restauran.
      final imeis = ((data['equiposImeis'] as List?) ?? []).cast<String>();
      for (final imei in imeis) {
        final reg = stockImeiGlobal
            .where((i) => i.imei == imei).firstOrNull;
        if (reg == null || _esDeOtraTienda(reg.ubicacion)) continue;
        if (!_equipos.contains(reg)) _equipos.add(reg);
      }
      // Reconstruir items por código
      final codigos = ((data['itemsCodigos'] as List?) ?? []).cast<String>();
      for (final cod in codigos) {
        final p = catalogoGlobal
            .where((x) => x.codigo == cod).firstOrNull;
        if (p == null || _productoEsDeOtraTienda(p)) continue;
        _items.add(p);
      }
      // Reconstruir pagos
      final pagosRaw = ((data['pagos'] as List?) ?? []);
      _pagos = pagosRaw.map((p) {
        final m = Map<String, dynamic>.from(p as Map);
        if ((m['tipo'] ?? '').toString().isEmpty) m['tipo'] = 'Contado';
        return PagoFactura.fromMap(m);
      }).toList();

      if (mounted && (_equipos.isNotEmpty || _items.isNotEmpty)) {
        setState(() {});
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
          content: Text("📋 Borrador restaurado: tu factura anterior se recuperó"),
          backgroundColor: AppColors.statusGreen,
          duration: Duration(seconds: 3)));
      }
    } catch (e) {
      debugPrint('[Factura] Error restaurando borrador: $e');
    }
  }

  /// Borra el borrador. Se llama después de guardar la factura con éxito
  /// o cuando el usuario sale sin querer guardar.
  Future<void> _borrarBorrador() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.remove(_claveBorrador);
    } catch (_) {}
  }

  /// Recarga productos e IMEIs desde la API para tener el stock real
  /// al momento de crear la factura (evita vender stock agotado).
  Future<void> _refrescarCatalogo() async {
    try {
      final results = await Future.wait([
        _Api.get('productos'),
        _Api.get('stock_imei'),
      ]);
      final rawP = results[0];
      final rawI = results[1];
      final imeis = ((rawI as List?) ?? [])
          .map((m) => ImeiRegistro.fromMap(m))
          .toList();
      // ── STOCK ACOTADO A LA TIENDA DE LA FACTURA ──────────────
      // Antes el stock se calculaba en global: se contaban TODOS los
      // IMEIs no vendidos sin mirar en qué local están, y para los
      // accesorios se tomaba el `stock_manual` sin más. Resultado: se
      // podía facturar en la sucursal un equipo que estaba físicamente
      // en la principal, y el sistema lo dejaba pasar.
      //
      // `widget.tienda` es la tienda donde se está emitiendo la
      // factura. Si viene vacía (venta sin tienda asignada) no se
      // filtra nada, para no romper instalaciones de un solo local.
      final tiendaVenta = widget.tienda.trim();
      final prods = ((rawP as List?) ?? []).map((m) {
        final p = Producto.fromMap(m);
        if (CategoriasProductos.usaIMEI(p.categoria)) {
          p.stockTotal = imeis
              .where((i) =>
                  i.producto.codigo == p.codigo &&
                  !i.vendido &&
                  (tiendaVenta.isEmpty || i.ubicacion == tiendaVenta))
              .length;
        } else {
          // Accesorios y demás: pertenecen a la tienda de
          // `productos.tienda`. Vacío = inventario general, se puede
          // vender desde cualquier local.
          final esDeOtraTienda = tiendaVenta.isNotEmpty &&
              p.tienda.isNotEmpty &&
              p.tienda != tiendaVenta;
          p.stockTotal = esDeOtraTienda ? 0 : p.stockManual;
        }
        return p;
      }).toList();
      catalogoGlobal  = prods;
      stockImeiGlobal = imeis;
      if (mounted) setState(() {});
    } catch (e) {
      debugPrint('[FormularioFactura] Error refrescando catálogo: $e');
    }
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _telCtrl.dispose();
    _correoClienteCtrl.dispose();
    _codigo.dispose();
    _montoPago.dispose();
    _deudaFpb.dispose();
    _cliente.dispose();
    _cedula.dispose();
    _nro.dispose();
    super.dispose();
  }

  // ── VENTA ACOTADA A LA TIENDA ─────────────────────────
  // Un usuario sólo puede facturar lo que está FÍSICAMENTE en la
  // tienda donde trabaja (`widget.tienda`, la que eligió al iniciar
  // sesión). El stock ya se acotaba al calcular `stockTotal`, pero la
  // búsqueda por IMEI iba directo contra `stockImeiGlobal` sin mirar
  // la ubicación: escaneando el serial se podía facturar un equipo
  // que estaba físicamente en otro local.
  //
  // Estos helpers son el único camino por el que el formulario
  // resuelve un código, así que la regla no se puede saltar por
  // ninguna de las vías de carga (teclado, scanner o diálogo).

  /// Tienda donde se emite la factura. Vacío = instalación de un
  /// solo local: no se restringe nada.
  String get _tiendaVenta => widget.tienda.trim();

  /// IMEI no vendido, esté en la tienda que esté. Se usa para poder
  /// explicar DÓNDE está el equipo cuando no se puede vender acá.
  ImeiRegistro? _buscarImei(String val) => stockImeiGlobal
      .where((i) => i.imei == val && !i.vendido)
      .firstOrNull;

  /// true si esa ubicación/tienda es distinta a la de la factura.
  bool _esDeOtraTienda(String ubicacion) =>
      _tiendaVenta.isNotEmpty &&
      ubicacion.trim().isNotEmpty &&
      ubicacion.trim() != _tiendaVenta;

  /// true si ese producto es de otra tienda.
  ///
  /// Sólo vale para los productos SIN IMEI: en los que llevan IMEI la
  /// tienda la manda la ubicación de cada equipo (`stock_imei`), no el
  /// campo `productos.tienda` — que puede haber quedado con el valor
  /// de cuando se cargó el modelo por primera vez.
  bool _productoEsDeOtraTienda(Producto p) =>
      !CategoriasProductos.usaIMEI(p.categoria) && _esDeOtraTienda(p.tienda);

  /// Aviso claro de por qué no se puede agregar ese producto.
  void _avisarOtraTienda(String queCosa, String ubicacion) {
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text('⛔ $queCosa está en "$ubicacion". '
          'No se puede vender desde "$_tiendaVenta".'),
      backgroundColor: AppColors.statusRed,
      duration: const Duration(seconds: 5)));
  }

  void _verificarCodigo(String val) {
    setState(() {
      _nombreProductoEncontrado = "";
      final imei = _buscarImei(val);
      if (imei != null) {
        _nombreProductoEncontrado = _esDeOtraTienda(imei.ubicacion)
            ? "⛔ ${imei.producto.nombre} — está en ${imei.ubicacion}"
            : "📱 ${imei.producto.nombre}";
        return;
      }
      final prod = catalogoGlobal.where((p) => p.codigo == val).firstOrNull;
      if (prod != null) {
        if (_productoEsDeOtraTienda(prod)) {
          _nombreProductoEncontrado =
              "⛔ ${prod.nombre} — pertenece a ${prod.tienda}";
          return;
        }
        final yaAgregados = _items.where((p) => p.codigo == val).length;
        final stockDisponible = prod.stockTotal - yaAgregados;
        _nombreProductoEncontrado = "${prod.nombre} (Stock: $stockDisponible)";
      }
    });
  }

  void _agregarProducto() {
    final val = _codigo.text.trim();
    if (val.isEmpty) return;

    // ── Buscar por IMEI (teléfonos) ──
    final imei = _buscarImei(val);
    if (imei != null) {
      if (_esDeOtraTienda(imei.ubicacion)) {
        _avisarOtraTienda(
            'El equipo ${imei.producto.nombre} (IMEI ${imei.imei})',
            imei.ubicacion);
        return;
      }
      if (_equipos.contains(imei)) {
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text("Este equipo ya está en la lista")));
        return;
      }
      setState(() => _equipos.add(imei));
      _codigo.clear();
      setState(() => _nombreProductoEncontrado = "");
      return;
    }

    // ── Buscar por código SKU (accesorios / productos sin IMEI) ──
    final prod = catalogoGlobal.where((p) => p.codigo == val).firstOrNull;
    if (prod != null) {
      if (_productoEsDeOtraTienda(prod)) {
        _avisarOtraTienda('El producto ${prod.nombre}', prod.tienda);
        return;
      }
      // Verificar stock disponible considerando los ya agregados en esta factura
      final yaAgregados = _items.where((p) => p.codigo == val).length;
      final stockDisponible = prod.stockTotal - yaAgregados;
      if (stockDisponible <= 0) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text("Sin stock disponible para ${prod.nombre} (stock actual: ${prod.stockTotal})"),
          backgroundColor: Colors.orange[800],
        ));
        return;
      }
      setState(() => _items.add(prod));
      _codigo.clear();
      setState(() => _nombreProductoEncontrado = "");
      return;
    }

    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text("Producto no encontrado o ya vendido")));
  }

  void _agregarPago({
    String? bancoDestino,
    String? bancoOrigen,
    String? referenciaPM,
    String? cedulaPagador,
    String? telefonoPagador,
    String? telefonoDestino,
    String? fechaPago,
    bool esInicial = false,
    bool? conciliadoBDV,
    int? codigoConciliacion,
    String? mensajeConciliacion,
    // Cuotas ingresadas manualmente en el diálogo de "Registrar Pago".
    // Si el usuario las llenó, tienen prioridad sobre las derivadas
    // de los items — así, aunque los productos no vengan de una lista
    // financiada, el pago igual muestra N° de cuotas y monto en la
    // factura impresa.
    int? numeroCuotasManual,
    double? montoCuotaManual,
  }) {
    final monto = double.tryParse(_montoPago.text.trim());
    if (monto == null || monto <= 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text("Ingrese un monto de pago válido mayor a 0"),
          backgroundColor: AppColors.statusOrange));
      return;
    }
    setState(() {
      // ── Cambio bug #1: el tipo de venta (Financiado/Contado) y el
      // financiador se derivan AHORA de los productos individuales de
      // la factura, no de un F/D global.
      //
      // Lógica — DOS conceptos distintos:
      //  · FINANCIADORA = la app con la que el cliente se lleva el
      //    equipo (Cashea/Weppa/Krece). Viene del dropdown F/D, o sea
      //    de _tipoVentaItem / _tipoVentaEquipo.
      //  · FINANCIADOR = la persona/usuario que entrega el equipo.
      //    Viene de _financiadorItem / _financiadorEquipo.
      //
      // El Reporte por Financiadora se agrupa por FINANCIADORA.
      //
      // Reglas:
      //  · Si hay ≥1 producto con F/D = Cashea/Weppa/Krece → "Financiado"
      //    y se toma esa financiadora.
      //  · Si es FPB global (switch del formulario) → "Financiado".
      //  · En otro caso → "Contado".

      // Normaliza la financiadora a una de las 3 oficiales.
      String? normFinanciadora(String tipoVenta) {
        if (tipoVenta == 'Cashea' || tipoVenta == 'Weppa'
            || tipoVenta == 'Krece') {
          return tipoVenta;
        }
        return null;
      }

      String? financiadoraDerivada;  // Cashea / Weppa / Krece (del F/D)
      String? financiadorDerivado;   // Persona que entrega (del usuario)
      int? numeroCuotasDerivado;     // Del primer item/equipo financiado
      double? montoCuotaDerivado;    // Del primer item/equipo financiado
      String? nombreListaDerivado;   // Nombre de la lista de precios usada
      bool hayFinanciado = false;
      for (final p in _items) {
        final h = identityHashCode(p);
        final t = _tipoVentaItem[h] ?? "Contado";
        if (t == "Cashea" || t == "Weppa" || t == "Krece") {
          hayFinanciado = true;
          financiadoraDerivada ??= normFinanciadora(t);
          financiadorDerivado  ??= _financiadorItem[h];
          numeroCuotasDerivado ??= _cuotasItem[h];
          montoCuotaDerivado   ??= _montoCuotaItem[h];
          nombreListaDerivado  ??= _listaItem[h];
        }
      }
      for (final e in _equipos) {
        final h = identityHashCode(e);
        final t = _tipoVentaEquipo[h] ?? "Contado";
        if (t == "Cashea" || t == "Weppa" || t == "Krece") {
          hayFinanciado = true;
          financiadoraDerivada ??= normFinanciadora(t);
          financiadorDerivado  ??= _financiadorEquipo[h];
          numeroCuotasDerivado ??= _cuotasEquipo[h];
          montoCuotaDerivado   ??= _montoCuotaEquipo[h];
          nombreListaDerivado  ??= _listaEquipo[h];
        }
      }
      // ── FALLBACK: si todavía no tenemos cuotas pero hay valores en
      // CUALQUIER mapa (porque el usuario llenó campos sin que el
      // identityHash coincida), tomar el primero que haya.
      if (numeroCuotasDerivado == null && _cuotasEquipo.isNotEmpty) {
        numeroCuotasDerivado = _cuotasEquipo.values.first;
      }
      if (numeroCuotasDerivado == null && _cuotasItem.isNotEmpty) {
        numeroCuotasDerivado = _cuotasItem.values.first;
      }
      if (montoCuotaDerivado == null && _montoCuotaEquipo.isNotEmpty) {
        montoCuotaDerivado = _montoCuotaEquipo.values.first;
      }
      if (montoCuotaDerivado == null && _montoCuotaItem.isNotEmpty) {
        montoCuotaDerivado = _montoCuotaItem.values.first;
      }
      if (nombreListaDerivado == null && _listaEquipo.isNotEmpty) {
        nombreListaDerivado = _listaEquipo.values.first;
      }
      if (nombreListaDerivado == null && _listaItem.isNotEmpty) {
        nombreListaDerivado = _listaItem.values.first;
      }

      // Si el usuario tipeó cuotas manuales en el diálogo del pago,
      // FORZAR esFinanciado=true. Antes, si la venta no venía de una
      // lista financiada (Cashea/Weppa/Krece), esFinanciado quedaba
      // false y las cuotas que el usuario había tipeado se descartaban
      // silenciosamente (se guardaba null en numeroCuotas y montoCuota).
      // Ahora: si el vendedor tipeó cuotas > 0, la app respeta esa
      // intención y guarda todo como financiado.
      final ingresoCuotasManual = (numeroCuotasManual != null
              && numeroCuotasManual > 0)
          || (montoCuotaManual != null && montoCuotaManual > 0);
      final esFinanciado = hayFinanciado || _tipoVenta == "FPB"
          || ingresoCuotasManual;
      // ── DEBUG: log para diagnosticar problemas de guardado de cuotas ──
      debugPrint('[Pago] esFinanciado=$esFinanciado | '
          'financiadora=$financiadoraDerivada | '
          'numeroCuotas=$numeroCuotasDerivado | '
          'montoCuota=$montoCuotaDerivado | '
          'numeroCuotasManual=$numeroCuotasManual | '
          'montoCuotaManual=$montoCuotaManual | '
          '_cuotasEquipo=$_cuotasEquipo | '
          '_montoCuotaEquipo=$_montoCuotaEquipo');

      _pagos.add(PagoFactura(
        metodo: _metodo, monto: monto,
        tipo: esFinanciado ? "Financiado" : "Contado",
        financiador: financiadorDerivado,
        financiadora: financiadoraDerivada,
        bancoDestino: bancoDestino,
        bancoOrigen: bancoOrigen,
        referencia: referenciaPM,
        cedulaPagador: cedulaPagador,
        telefonoPagador: telefonoPagador,
        telefonoDestino: telefonoDestino,
        fechaPago: fechaPago,
        esInicial: esInicial,
        conciliadoBDV: conciliadoBDV,
        codigoConciliacion: codigoConciliacion,
        mensajeConciliacion: mensajeConciliacion,
        // Prioridad: MANUAL (lo que el usuario tipeó en el diálogo del
        // pago) > DERIVADO (calculado de los items con lista financiada).
        // Si el pago no es financiado, ambos se ignoran (null).
        numeroCuotas: esFinanciado
            ? (numeroCuotasManual ?? numeroCuotasDerivado)
            : null,
        montoCuota: esFinanciado
            ? (montoCuotaManual ?? montoCuotaDerivado)
            : null,
        // ── TASA HISTÓRICA ──
        // Guardamos la tasa del sistema al MOMENTO de crear el pago.
        // El equivalente en USD que aparece en el detalle y en la
        // factura impresa usa SIEMPRE esta tasa, NO la tasa actual.
        // Así si la tasa cambia mañana, la factura sigue mostrando el
        // equivalente correcto que se cobró ese día.
        tasaCambio: ConfigSistema.tasaCambio > 0
            ? ConfigSistema.tasaCambio
            : null,
        // ── NOMBRE DE LA LISTA APLICADA ──
        // Solo aplica cuando el pago es financiado. Identifica EXACTAMENTE
        // qué lista de precios se usó (normal vs promoción) para que el
        // reporte por financiadora calcule el precio correcto.
        nombreLista: esFinanciado ? nombreListaDerivado : null,
      ));
      _montoPago.clear();
    });
  }

  Future<void> _guardarFactura() async {
    // ── Anti-doble-click ─────────────────────────────────────
    // Si el usuario presiona "Guardar" mientras ya hay un POST en
    // curso, ignoramos el segundo tap. Esto evita que se dispare el
    // INSERT dos veces y MySQL responda con error 1062 (Duplicate
    // entry para nro_factura).
    if (_guardando) {
      debugPrint('[Factura] _guardarFactura ignorado: ya hay un guardado en curso');
      return;
    }
    _guardando = true;

    try {
      await _guardarFacturaInterno();
    } finally {
      // SIEMPRE liberar la guardia, ocurra lo que ocurra (validación
      // fallida, error de red, error de BD, éxito). Sin esto, un fallo
      // dejaría el botón "trabado" hasta cerrar la pantalla.
      _guardando = false;
    }
  }

  Future<void> _guardarFacturaInterno() async {
    // ── Validaciones completas antes de guardar ──────────────
    final clienteNombre = _cliente.text.trim();
    final clienteCedula = _cedula.text.trim();
    final clienteTel    = _telCtrl.text.trim();

    if (clienteNombre.isEmpty) {
      _mostrarValidacion("Ingrese el nombre del cliente.");
      return;
    }
    if (clienteNombre.length < 3) {
      _mostrarValidacion("El nombre debe tener al menos 3 caracteres.");
      return;
    }
    if (clienteCedula.isEmpty) {
      _mostrarValidacion("Ingrese la cédula del cliente.");
      return;
    }
    // Cédula venezolana: 6–8 dígitos
    if (!RegExp(r'^\d{6,8}$').hasMatch(clienteCedula.replaceAll(RegExp(r'[VE-]'), ''))) {
      _mostrarValidacion("La cédula debe tener entre 6 y 8 dígitos.");
      return;
    }
    if (_equipos.isEmpty && _items.isEmpty) {
      _mostrarValidacion("Agregue al menos un producto a la factura.");
      return;
    }
    if (_pagos.isEmpty) {
      _mostrarValidacion("Agregue al menos un método de pago.");
      return;
    }

    // Validar que el total de pagos coincida con el total de productos
    final totalProductos = _equipos.fold(0.0, (s, e) => s + e.producto.precioVenta)
        + _items.fold(0.0, (s, p) => s + p.precioVenta);
    final totalPagos = _pagos.fold(0.0, (s, p) => s + p.monto);
    if ((totalPagos - totalProductos).abs() > 0.10) { // tolerancia de $0.10
      final confirmar = await showDialog<bool>(
        context: context,
        builder: (ctx) => AlertDialog(
          title: const Row(children: [
            Icon(Icons.warning_amber, color: Colors.orange),
            SizedBox(width: 8),
            Text("Diferencia en totales"),
          ]),
          content: Column(mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text("Total productos: ${formatCurrency(totalProductos)}"),
            Text("Total pagos: ${formatCurrency(totalPagos)}"),
            const SizedBox(height: 8),
            const Text("¿Desea continuar de todas formas?",
              style: TextStyle(fontWeight: FontWeight.w500)),
          ]),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text("Corregir")),
            ElevatedButton(
              style: ElevatedButton.styleFrom(backgroundColor: Colors.orange),
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text("Continuar", style: TextStyle(color: Colors.white))),
          ],
        ),
      );
      if (confirmar != true || !mounted) return;
    }

    // Validación específica para FPB
    if (_tipoVenta == "FPB") {
      final deuda = double.tryParse(_deudaFpb.text.trim());
      if (deuda == null || deuda <= 0) {
        _mostrarValidacion(
          "Ingrese el monto de la deuda del cliente para FPB.",
          color: AppColors.statusOrange);
        return;
      }
    }

    // ── Mostrar indicador de carga ───────────────────────────
    showDialog(
      context: context,
      barrierDismissible: false,
      builder: (_) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        content: const Padding(
          padding: EdgeInsets.symmetric(vertical: 8),
          child: Row(children: [
            CircularProgressIndicator(),
            SizedBox(width: 20),
            Expanded(child: Text("Guardando factura y actualizando inventario...")),
          ]),
        ),
      ),
    );

    try {
      final ahora = DateTime.now();
      final fechaFormateada =
        "${ahora.day.toString().padLeft(2,'0')}/"
        "${ahora.month.toString().padLeft(2,'0')}/"
        "${ahora.year}";

      // ── Construir mapas vendedor por imei/código ──
      // Los maps internos del formulario usan identityHashCode como key
      // (porque puede haber varios items con el mismo código). Para
      // enviar al backend convertimos a mapas {imei → vendedor} y
      // {código → vendedor}.
      final Map<String, String?> mapaVendedorImei = {};
      for (final e in _equipos) {
        final v = _vendedorEquipo[identityHashCode(e)];
        if (v != null && v.isNotEmpty) mapaVendedorImei[e.imei] = v;
      }
      final Map<String, String?> mapaVendedorCodigo = {};
      for (final p in _items) {
        final v = _vendedorItem[identityHashCode(p)];
        if (v != null && v.isNotEmpty) mapaVendedorCodigo[p.codigo] = v;
      }

      var nuevaFactura = FacturaModel(
        tienda       : widget.tienda,
        cliente      : clienteNombre,
        cedula       : clienteCedula,
        telefono     : clienteTel,
        nroFactura   : _nro.text.trim(),
        equipos      : _equipos,
        itemsSinImei : _items,
        pagos        : _pagos,
        // Guardamos el NOMBRE del usuario (no el rol). Si el nombre viene
        // vacío, cae al fallback; si el nombre que está en el perfil de
        // sesión resulta ser un rol (caso de datos mal cargados), el helper
        // `_resolverNombreVendedor` lo reemplaza por el nombre real del
        // único usuario con ese rol, si lo hay.
        vendedor     : _resolverNombreVendedor(
                         (usuarioSesion?.nombre ?? '').trim().isEmpty
                           ? "Vendedor"
                           : usuarioSesion!.nombre),
        fecha        : fechaFormateada,
        // Maps de vendedor por producto y rol del creador. Permite
        // que el reporte atribuya cada producto a SU vendedor en vez
        // del creador de la factura.
        vendedorPorImei  : mapaVendedorImei,
        vendedorPorCodigo: mapaVendedorCodigo,
        creadorRol       : usuarioSesion?.rol ?? '',
      );

      // ── 1. GUARDAR FACTURA EN BASE DE DATOS ──────────────
      // Si estamos editando una factura existente, solo se actualizan
      // los datos del encabezado + pagos (PUT). NO se vuelve a tocar el
      // stock, porque ya fue descontado al crear la factura original.
      //
      // Si se está creando una factura nueva, se hace POST y luego se
      // ejecutan los efectos secundarios (pasos 2, 3, 4): marcar IMEIs,
      // decrementar stock manual y crear CxC para FPB.
      final esEdicion = widget.facturaAEditar?.id != null;

      if (esEdicion) {
        // Conservar id original para no romper relaciones (factura_equipos,
        // factura_items, factura_pagos siguen apuntando a ese id).
        nuevaFactura.id = widget.facturaAEditar!.id;
        await _Api.put('facturas', nuevaFactura.id!.toString(), nuevaFactura.toApiMap());
      } else {
        // ── POST con reintento automático si hay duplicado ────────
        // Si el backend responde con error 1062 ("Duplicate entry for
        // nro_factura"), regeneramos el número con un timestamp+random
        // nuevo y reintentamos UNA vez. Si vuelve a fallar, propagamos
        // el error al usuario.
        dynamic data;
        int reintentos = 0;
        while (true) {
          try {
            // ── DEBUG: imprimir el JSON que se manda al backend ──
            // Útil para verificar que numero_cuotas y monto_cuota están
            // viajando dentro del array `pagos`.
            final body = nuevaFactura.toApiMap();
            debugPrint('[Factura] Enviando POST facturas. '
                'pagos=${body['pagos']}');
            data = await _Api.post('facturas', body);
            break; // Éxito → salimos del while
          } catch (e) {
            final msg = e.toString();
            final esDuplicado = msg.contains('1062') ||
                                msg.contains('Duplicate entry') ||
                                msg.toLowerCase().contains('duplicate');
            if (esDuplicado && reintentos < 2) {
              reintentos++;
              // Generar nuevo número de factura y reintentar
              final ts2 = DateTime.now().millisecondsSinceEpoch;
              final r1 = math.Random.secure().nextInt(10000).toString().padLeft(4, '0');
              final r2 = math.Random.secure().nextInt(100).toString().padLeft(2, '0');
              final nuevoNro = "$ts2-$r1$r2";
              debugPrint('[Factura] Duplicate entry detectado. Regenerando nro: $nuevoNro');
              _nro.text = nuevoNro;
              // Recrear el FacturaModel con el nuevo nro
              nuevaFactura = FacturaModel(
                tienda       : nuevaFactura.tienda,
                cliente      : nuevaFactura.cliente,
                cedula       : nuevaFactura.cedula,
                telefono     : nuevaFactura.telefono,
                nroFactura   : nuevoNro,
                equipos      : nuevaFactura.equipos,
                itemsSinImei : nuevaFactura.itemsSinImei,
                pagos        : nuevaFactura.pagos,
                vendedor     : nuevaFactura.vendedor,
                fecha        : nuevaFactura.fecha,
                vendedorPorImei  : nuevaFactura.vendedorPorImei,
                vendedorPorCodigo: nuevaFactura.vendedorPorCodigo,
                creadorRol       : nuevaFactura.creadorRol,
              );
              continue; // Reintentar con el nuevo número
            }
            // No es duplicado o ya agotamos reintentos → propagar
            rethrow;
          }
        }
        // Extraer el id del Map devuelto, tolerando que data sea null,
        // un Map sin 'id', o que el id venga como String. Si nada de
        // esto funciona, dejamos id en null (no es bloqueante para los
        // pasos siguientes — solo no se podrá editar la factura recién
        // creada hasta que se recargue la lista).
        if (data is Map) {
          final idRaw = data['id'];
          if (idRaw != null) {
            nuevaFactura.id = idRaw is int ? idRaw : int.tryParse(idRaw.toString());
          }
        }
      }

      // ── 1a-bis. Actualizar contador local de compras ─────
      // Incrementamos el cache en memoria para que la UI refleje
      // inmediatamente la nueva factura sin tener que recargar.
      final cedulaKey = _normalizarCedula(clienteCedula);
      if (cedulaKey.isNotEmpty) {
        conteoComprasPorCedula[cedulaKey] =
            (conteoComprasPorCedula[cedulaKey] ?? 0) + 1;
      }

      // ── 1a. ACTUALIZAR LISTA LOCAL DE CLIENTES ───────────
      // Los clientes no se persisten en una tabla propia — se
      // reconstruyen desde las facturas al recargar. Mantenemos un
      // cache en memoria para que el autocompletado funcione durante
      // la sesión actual.
      try {
        final clienteData = ClienteModel(
          cedula: clienteCedula,
          nombre: clienteNombre,
          telefono: clienteTel,
          correo: _correoClienteCtrl.text.trim(),
        );
        final idx = clientesGlobal.indexWhere((c) =>
            _normalizarCedula(c.cedula) == _normalizarCedula(clienteCedula));
        if (idx >= 0) {
          // Conservar correo previo si el nuevo viene vacío
          final previo = clientesGlobal[idx];
          clientesGlobal[idx] = ClienteModel(
            cedula: clienteData.cedula,
            nombre: clienteData.nombre,
            telefono: clienteData.telefono,
            correo: clienteData.correo.isNotEmpty
                ? clienteData.correo
                : previo.correo,
          );
        } else {
          clientesGlobal.add(clienteData);
        }
      } catch (e) {
        debugPrint('[Clientes] No se pudo actualizar cache local: $e');
      }

      // ── 2. MARCAR IMEIs COMO VENDIDOS ────────────────────
      // NO se hace nada aquí. El backend (facturas.php → POST) YA
      // marca los IMEIs como vendidos atómicamente dentro de la
      // misma transacción que inserta la factura:
      //   UPDATE stock_imei SET vendido=1, fecha_venta=NOW(),
      //          factura_id=? WHERE imei=? AND vendido=0
      //
      // Antes este bloque hacía PUT /stock_imei pasando el número
      // de IMEI como si fuera el `id` (clave primaria), lo que
      // SIEMPRE fallaba (el endpoint busca por id numérico) y
      // mostraba la falsa advertencia "IMEIs no marcados como
      // vendidos". Como el backend ya hace el trabajo, eliminamos
      // la duplicación. Solo refrescamos la copia en memoria.
      final List<String> imeisFallidos = [];
      if (!esEdicion) {
        for (final equipo in _equipos) {
          equipo.vendido = true;
          final idx = stockImeiGlobal.indexWhere((i) => i.imei == equipo.imei);
          if (idx != -1) stockImeiGlobal[idx].vendido = true;
        }
      }

      // ── 3. REFRESCAR STOCK MANUAL EN LA SESIÓN ───────────
      // IMPORTANTE: el backend (api.php → guardarFactura) YA descuenta
      // el stock atómicamente dentro de la misma transacción que guarda
      // la factura. Antes aquí se volvía a descontar en Dart y se hacía
      // PUT /productos con el nuevo stock → se descontaba DOS VECES
      // (una en el INSERT de factura_items + una por el PUT de Dart),
      // causando un desajuste de inventario.
      //
      // Ahora solamente refrescamos el stock en memoria leyéndolo del
      // servidor para que la vista refleje lo que ya quedó en BD.
      final Map<String, int> cantidadPorCodigo = {};
      final List<String> productosFallidos = [];
      if (!esEdicion) {
        for (final prod in _items) {
          if (prod.categoria != 'Telefono') {
            cantidadPorCodigo[prod.codigo] =
                (cantidadPorCodigo[prod.codigo] ?? 0) + 1;
          }
        }

        for (final entry in cantidadPorCodigo.entries) {
          try {
            final rawFresh = await _Api.get('productos', {'codigo': entry.key});
            if (rawFresh == null) continue;

            int stockActual;
            if (rawFresh is List) {
              final match = (rawFresh as List)
                  .map((m) => Producto.fromMap(m as Map<String, dynamic>))
                  .where((p) => p.codigo == entry.key)
                  .firstOrNull;
              stockActual = match?.stockManual ?? 0;
            } else {
              stockActual = Producto.fromMap(
                rawFresh as Map<String, dynamic>).stockManual;
            }

            // Solo actualizamos la representación en memoria; el servidor
            // ya tiene el valor correcto.
            final prodEnSesion = catalogoGlobal
                .where((p) => p.codigo == entry.key)
                .firstOrNull;
            if (prodEnSesion != null) {
              prodEnSesion.stockManual = stockActual;
              prodEnSesion.stockTotal  = stockActual;
            }
            debugPrint('[Stock] ${entry.key}: refrescado en sesión → $stockActual');
          } catch (e) {
            debugPrint('Error refrescando stock ${entry.key}: $e');
            productosFallidos.add(entry.key);
          }
        }
      } // cierre de if (!esEdicion) del paso 3

      if (!mounted) return;
      Navigator.pop(context); // Cerrar loading

      // ── 4. CREAR CxC AUTOMÁTICA PARA FPB ─────────────────
      // Solo en creación. En edición no se crea una nueva cuenta por
      // cobrar; la original ya existe (o nunca existió si la venta no
      // era FPB cuando se creó).
      if (!esEdicion && _tipoVenta == "FPB") {
        final deuda = double.tryParse(_deudaFpb.text.trim()) ?? 0;
        if (deuda > 0) {
          // Resolver la financiadora de los pagos: el primer pago con
          // `financiador` no vacío gana. Si no hay ninguno, queda 'FPB'.
          final financiadora = _pagos
              .map((p) => (p.financiador ?? '').trim())
              .firstWhere((f) => f.isNotEmpty, orElse: () => 'FPB');
          try {
            await _Api.post('cuentas_cobrar', {
              'cedula'      : clienteCedula,
              'nombre'      : clienteNombre,
              'telefono'    : clienteTel,
              'correo'      : '',
              'monto_total' : deuda,
              'financiadora': financiadora,
              'notas'       : 'Generado automáticamente desde factura ${_nro.text.trim()}',
            });
            if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(
              content: Text("✅ Cuenta por cobrar creada: $clienteNombre — ${formatCurrency(deuda)}"),
              backgroundColor: AppColors.statusGreen,
              duration: const Duration(seconds: 4)));
          } catch (e) {
            debugPrint('Error creando CxC para FPB: $e');
          }
        }
      }

      // ── 5. MOSTRAR ADVERTENCIAS SI LAS HAY ───────────────
      if (imeisFallidos.isNotEmpty || productosFallidos.isNotEmpty) {
        await showDialog(
          context: context,
          builder: (ctx) => AlertDialog(
            title: const Row(children: [
              Icon(Icons.warning_amber_rounded, color: Colors.orange),
              SizedBox(width: 8),
              Flexible(child: Text("Factura guardada con advertencias")),
            ]),
            content: SingleChildScrollView(child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                const Text(
                  "La factura fue registrada, pero los siguientes ítems "
                  "no se pudieron actualizar en el inventario:"),
                if (imeisFallidos.isNotEmpty) ...[
                  const SizedBox(height: 12),
                  const Text("IMEIs no marcados como vendidos:",
                    style: TextStyle(fontWeight: FontWeight.bold)),
                  ...imeisFallidos.map((imei) => Text(
                    "• $imei", style: const TextStyle(color: Colors.red))),
                ],
                if (productosFallidos.isNotEmpty) ...[
                  const SizedBox(height: 12),
                  const Text("Productos sin descontar:",
                    style: TextStyle(fontWeight: FontWeight.bold)),
                  ...productosFallidos.map((cod) => Text(
                    "• $cod", style: const TextStyle(color: Colors.orange))),
                ],
                const SizedBox(height: 8),
                const Text("Verifique el inventario manualmente.",
                  style: TextStyle(fontStyle: FontStyle.italic, fontSize: 12)),
              ],
            )),
            actions: [
              ElevatedButton(
                onPressed: () => Navigator.pop(ctx),
                child: const Text("Entendido")),
            ],
          ),
        );
      }

      if (!mounted) return;
      // Factura guardada con éxito: borrar el borrador local para que
      // al abrir una nueva factura no aparezca un "borrador restaurado"
      // con datos antiguos.
      _borrarBorrador();
      Navigator.pop(context, nuevaFactura);

    } catch (e) {
      if (!mounted) return;
      Navigator.pop(context); // Cerrar loading
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text("Error al guardar la factura: $e"),
        backgroundColor: AppColors.statusRed,
        duration: const Duration(seconds: 6),
      ));
    }
  }

  /// Muestra mensaje de validación con estilo coherente.
  void _mostrarValidacion(String mensaje,
      {Color color = AppColors.statusRed}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Row(children: [
        Icon(color == AppColors.statusRed
            ? Icons.error_outline
            : Icons.warning_amber_outlined,
          color: Colors.white, size: 18),
        const SizedBox(width: 8),
        Expanded(child: Text(mensaje)),
      ]),
      backgroundColor: color,
      duration: const Duration(seconds: 4),
      behavior: SnackBarBehavior.floating,
    ));
  }

