  Widget _buildInfoField(String label, String value) => Padding(
    padding: const EdgeInsets.symmetric(vertical: 8),
    child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Text(label, style: const TextStyle(fontSize: 11, color: Colors.grey, fontWeight: FontWeight.bold)),
      const SizedBox(height: 4),
      Text(value, style: const TextStyle(fontSize: 16, color: Colors.black, fontWeight: FontWeight.w500)),
    ]));

  Widget _buildTextField(String label, TextEditingController controller) => Padding(
    padding: const EdgeInsets.symmetric(vertical: 8),
    child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Text(label, style: const TextStyle(fontSize: 11, color: Colors.grey, fontWeight: FontWeight.bold)),
      TextField(controller: controller, style: const TextStyle(fontSize: 15),
        decoration: InputDecoration(isDense: true,
          contentPadding: const EdgeInsets.symmetric(vertical: 8),
          enabledBorder: UnderlineInputBorder(borderSide: BorderSide(color: Colors.grey[300]!)))),
    ]));

  /// Variante de _buildTextField que dispara una callback cuando el
  /// usuario termina de escribir una cédula (pierde el foco o escribe
  /// al menos 6 dígitos). Se usa para autocompletar datos del cliente
  /// buscando en `clientesGlobal`.
  Widget _buildTextFieldConAutocompletado(
      String label, TextEditingController controller,
      {required Function(String) onCedulaCompleta}) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 8),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text(label, style: const TextStyle(fontSize: 11, color: Colors.grey, fontWeight: FontWeight.bold)),
        Focus(
          onFocusChange: (hasFocus) {
            if (!hasFocus && controller.text.trim().length >= 6) {
              onCedulaCompleta(controller.text.trim());
            }
          },
          child: TextField(
            controller: controller,
            style: const TextStyle(fontSize: 15),
            onSubmitted: (v) {
              if (v.trim().length >= 6) onCedulaCompleta(v.trim());
            },
            decoration: InputDecoration(
                isDense: true,
                contentPadding: const EdgeInsets.symmetric(vertical: 8),
                enabledBorder: UnderlineInputBorder(
                    borderSide: BorderSide(color: Colors.grey[300]!))),
          ),
        ),
      ]));
  }

  Widget _buildSectionHeader(String title, int count) => Row(children: [
    Text(title, style: const TextStyle(fontSize: 13, color: Colors.grey, fontWeight: FontWeight.w500)),
    const SizedBox(width: 8),
    Container(padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
      decoration: BoxDecoration(color: Colors.grey[200], borderRadius: BorderRadius.circular(4)),
      child: Text(count.toString(), style: const TextStyle(fontSize: 11, fontWeight: FontWeight.bold))),
  ]);

  /// Abre un diálogo para elegir qué vendedor se atribuye este equipo.
  /// La lista de candidatos sale de `usuariosSistema`. "Yo / Creador"
  /// remueve el override (queda en blanco → el reporte usa el creador).
  Future<void> _elegirVendedorEquipo(ImeiRegistro equipo) async {
    final actual = _vendedorEquipo[identityHashCode(equipo)] ?? '';
    final elegido = await _dialogoSeleccionVendedor(
        tituloEquipo: '${equipo.producto.nombre} (${equipo.imei})',
        valorActual: actual);
    if (elegido == null) return;
    setState(() {
      if (elegido.isEmpty) {
        _vendedorEquipo.remove(identityHashCode(equipo));
      } else {
        _vendedorEquipo[identityHashCode(equipo)] = elegido;
      }
    });
  }

  Future<void> _elegirVendedorItem(Producto p) async {
    final actual = _vendedorItem[identityHashCode(p)] ?? '';
    final elegido = await _dialogoSeleccionVendedor(
        tituloEquipo: '${p.nombre} (${p.codigo})',
        valorActual: actual);
    if (elegido == null) return;
    setState(() {
      if (elegido.isEmpty) {
        _vendedorItem.remove(identityHashCode(p));
      } else {
        _vendedorItem[identityHashCode(p)] = elegido;
      }
    });
  }

  /// Diálogo genérico de selección de vendedor.
  /// Devuelve:
  ///   · String vacío → "Yo / Creador" (sin override).
  ///   · String con nombre → vendedor específico elegido.
  ///   · null → el usuario canceló (no cambiar nada).
  Future<String?> _dialogoSeleccionVendedor({
    required String tituloEquipo,
    required String valorActual,
  }) {
    // Lista de candidatos: usuarios con rol Vendedor/Cajero/etc.
    // Excluir Administrador/Dueño? Por ahora mostrar todos. El cliente
    // ajusta el filtro si es necesario.
    final candidatos = usuariosSistema.toList()
      ..sort((a, b) => a.nombre.compareTo(b.nombre));
    return showDialog<String>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Vendedor del producto',
            style: TextStyle(fontWeight: FontWeight.w800)),
        content: SizedBox(
          width: 360,
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            Text(tituloEquipo,
                style: const TextStyle(fontSize: 12, color: Colors.grey)),
            const SizedBox(height: 12),
            Container(
              decoration: BoxDecoration(
                border: Border.all(color: Colors.grey.shade300),
                borderRadius: BorderRadius.circular(8),
              ),
              constraints: const BoxConstraints(maxHeight: 350),
              child: ListView(shrinkWrap: true, children: [
                // Opción "Sin asignar (no paga comisión)"
                // Antes esta opción se llamaba "(Yo / Creador)" y hacía
                // pensar que la comisión iba al creador de la factura.
                // Ahora aclara que dejar sin asignar significa que
                // NADIE cobra comisión por este producto. Si el creador
                // quiere cobrar comisión, tiene que seleccionarse
                // explícitamente en la lista de vendedores de abajo.
                ListTile(
                  dense: true,
                  leading: Icon(Icons.remove_circle_outline,
                      color: valorActual.isEmpty
                          ? AppColors.primaryBlue
                          : Colors.grey),
                  title: const Text('Sin asignar',
                      style: TextStyle(fontWeight: FontWeight.w600)),
                  subtitle: const Text(
                      'No se paga comisión por este producto',
                      style: TextStyle(fontSize: 11)),
                  trailing: valorActual.isEmpty
                      ? const Icon(Icons.check_circle,
                          color: AppColors.primaryBlue, size: 18)
                      : null,
                  onTap: () => Navigator.pop(ctx, ''),
                ),
                const Divider(height: 1),
                ...candidatos.map((u) {
                  final esActual = u.nombre == valorActual;
                  return ListTile(
                    dense: true,
                    leading: Icon(Icons.person,
                        color: esActual ? AppColors.primaryBlue : Colors.grey),
                    title: Text(u.nombre,
                        style: const TextStyle(fontWeight: FontWeight.w600)),
                    subtitle: Text(u.rol,
                        style: const TextStyle(fontSize: 11)),
                    trailing: esActual
                        ? const Icon(Icons.check_circle,
                            color: AppColors.primaryBlue, size: 18)
                        : null,
                    onTap: () => Navigator.pop(ctx, u.nombre),
                  );
                }),
              ]),
            ),
          ]),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text('Cancelar')),
        ],
      ),
    );
  }

  Widget _buildProductosTable() {
    if (_equipos.isEmpty && _items.isEmpty) {
      return const Padding(padding: EdgeInsets.symmetric(vertical: 10),
        child: Text("No hay productos agregados", style: TextStyle(fontSize: 12, color: Colors.grey, fontStyle: FontStyle.italic)));
    }
    // Helper: chip F/D compacto con color — misma paleta que el diálogo
    Widget chipFD(String tv) {
      const colores = <String, List<Color>>{
        'Contado': [Color(0xFFEDEDED), Color(0xFF111111)],
        'Cashea' : [Color(0xFFFFD600), Color(0xFF000000)],
        'Weppa'  : [Color(0xFF6A1B9A), Color(0xFFFFD600)],
        'Krece'  : [Color(0xFF006B7F), Color(0xFFFFFFFF)],
        'FPB'    : [Color(0xFF002366), Color(0xFFFFFFFF)],
      };
      final par = colores[tv] ?? const <Color>[Color(0xFFEDEDED), Color(0xFF111111)];
      return Container(
        margin: const EdgeInsets.only(top: 2),
        padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
        decoration: BoxDecoration(color: par[0], borderRadius: BorderRadius.circular(4)),
        child: Text(tv,
            style: TextStyle(color: par[1], fontSize: 10, fontWeight: FontWeight.bold)),
      );
    }
    return Table(
      border: TableBorder(bottom: BorderSide(color: Colors.grey[200]!)),
      columnWidths: const {0: FlexColumnWidth(2.2), 1: FlexColumnWidth(1.5), 2: FlexColumnWidth(0.8)},
      children: [
        const TableRow(children: [
          Padding(padding: EdgeInsets.symmetric(vertical: 10), child: Text("DESCRIPCIÓN", style: TextStyle(fontSize: 11, fontWeight: FontWeight.bold, color: Colors.grey))),
          Padding(padding: EdgeInsets.symmetric(vertical: 10), child: Text("ID/IMEI", style: TextStyle(fontSize: 11, fontWeight: FontWeight.bold, color: Colors.grey))),
          Padding(padding: EdgeInsets.symmetric(vertical: 10), child: Text("", style: TextStyle(fontSize: 11))),
        ]),
        ..._equipos.map((e) {
          final tv = _tipoVentaEquipo[identityHashCode(e)] ?? "Contado";
          final vEq = _vendedorEquipo[identityHashCode(e)];
          return TableRow(children: [
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 10),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text(e.producto.nombre, style: const TextStyle(fontSize: 13)),
                Text(formatCurrency(e.producto.precioVenta, symbol: ''), style: const TextStyle(fontSize: 11, color: AppColors.primaryBlue, fontWeight: FontWeight.bold)),
                // Chip F/D por equipo (bug #1)
                Align(alignment: Alignment.centerLeft, child: chipFD(tv)),
                // ── Chip de vendedor asignado ──
                // Si está vacío usa "(Yo)" indicando que el vendedor
                // es el creador. Tocando el chip se abre un selector.
                const SizedBox(height: 3),
                Align(
                  alignment: Alignment.centerLeft,
                  child: InkWell(
                    onTap: () => _elegirVendedorEquipo(e),
                    child: Container(
                      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                      decoration: BoxDecoration(
                        color: vEq == null || vEq.isEmpty
                            ? Colors.grey.shade200
                            : AppColors.primaryBlue.withValues(alpha: 0.12),
                        borderRadius: BorderRadius.circular(4),
                        border: Border.all(
                          color: vEq == null || vEq.isEmpty
                              ? Colors.grey.shade400
                              : AppColors.primaryBlue,
                          width: 0.5,
                        ),
                      ),
                      child: Row(mainAxisSize: MainAxisSize.min, children: [
                        const Icon(Icons.person_outline, size: 11,
                            color: AppColors.primaryBlue),
                        const SizedBox(width: 3),
                        Text(
                          vEq == null || vEq.isEmpty ? "Vendedor: (Yo)" : "Vendedor: $vEq",
                          style: TextStyle(
                            fontSize: 10,
                            fontWeight: FontWeight.w600,
                            color: vEq == null || vEq.isEmpty
                                ? Colors.grey.shade700
                                : AppColors.primaryBlue,
                          ),
                        ),
                      ]),
                    ),
                  ),
                ),
              ])),
            Padding(padding: const EdgeInsets.symmetric(vertical: 10), child: Text(e.imei, style: const TextStyle(fontSize: 12, color: Colors.deepPurple, fontWeight: FontWeight.bold))),
            InkWell(
              onTap: () => setState(() {
                _equipos.remove(e);
                _tipoVentaEquipo.remove(identityHashCode(e));
                _financiadorEquipo.remove(identityHashCode(e));
                _vendedorEquipo.remove(identityHashCode(e));
              }),
              child: const Padding(padding: EdgeInsets.symmetric(vertical: 10), child: Icon(Icons.remove_circle_outline, color: Colors.red, size: 20))),
          ]);
        }),
        ..._items.map((p) {
          final tv = _tipoVentaItem[identityHashCode(p)] ?? "Contado";
          final vIt = _vendedorItem[identityHashCode(p)];
          return TableRow(children: [
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 10),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text(p.nombre, style: const TextStyle(fontSize: 13)),
                Text(formatCurrency(p.precioVenta, symbol: ''), style: const TextStyle(fontSize: 11, color: AppColors.primaryBlue, fontWeight: FontWeight.bold)),
                // Chip F/D por producto (bug #1)
                Align(alignment: Alignment.centerLeft, child: chipFD(tv)),
                // ── Chip de vendedor asignado ──
                const SizedBox(height: 3),
                Align(
                  alignment: Alignment.centerLeft,
                  child: InkWell(
                    onTap: () => _elegirVendedorItem(p),
                    child: Container(
                      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                      decoration: BoxDecoration(
                        color: vIt == null || vIt.isEmpty
                            ? Colors.grey.shade200
                            : AppColors.primaryBlue.withValues(alpha: 0.12),
                        borderRadius: BorderRadius.circular(4),
                        border: Border.all(
                          color: vIt == null || vIt.isEmpty
                              ? Colors.grey.shade400
                              : AppColors.primaryBlue,
                          width: 0.5,
                        ),
                      ),
                      child: Row(mainAxisSize: MainAxisSize.min, children: [
                        const Icon(Icons.person_outline, size: 11,
                            color: AppColors.primaryBlue),
                        const SizedBox(width: 3),
                        Text(
                          vIt == null || vIt.isEmpty ? "Vendedor: (Yo)" : "Vendedor: $vIt",
                          style: TextStyle(
                            fontSize: 10,
                            fontWeight: FontWeight.w600,
                            color: vIt == null || vIt.isEmpty
                                ? Colors.grey.shade700
                                : AppColors.primaryBlue,
                          ),
                        ),
                      ]),
                    ),
                  ),
                ),
              ])),
            Padding(padding: const EdgeInsets.symmetric(vertical: 10), child: Text(p.codigo, style: const TextStyle(fontSize: 12, color: Colors.blueGrey))),
            InkWell(
              onTap: () => setState(() {
                _items.remove(p);
                _tipoVentaItem.remove(identityHashCode(p));
                _financiadorItem.remove(identityHashCode(p));
                _vendedorItem.remove(identityHashCode(p));
              }),
              child: const Padding(padding: EdgeInsets.symmetric(vertical: 10), child: Icon(Icons.remove_circle_outline, color: Colors.red, size: 20))),
          ]);
        }),
      ]);
  }

  Widget _buildPagosTable() {
    if (_pagos.isEmpty) {
      return const Padding(padding: EdgeInsets.symmetric(vertical: 10),
        child: Text("No hay pagos registrados", style: TextStyle(fontSize: 12, color: Colors.grey, fontStyle: FontStyle.italic)));
    }
    // Total separado por moneda: los pagos en Bs no se suman con los $.
    final totalesPagado =
        totalesPagosPorMoneda(_pagos.map((p) => p.toMap()));
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Table(
        border: TableBorder(bottom: BorderSide(color: Colors.grey[200]!)),
        columnWidths: const {0: FlexColumnWidth(2), 1: FlexColumnWidth(1.2), 2: FlexColumnWidth(0.5)},
        children: [
          const TableRow(children: [
            Padding(padding: EdgeInsets.symmetric(vertical: 10), child: Text("METODO", style: TextStyle(fontSize: 11, fontWeight: FontWeight.bold, color: Colors.grey))),
            Padding(padding: EdgeInsets.symmetric(vertical: 10), child: Text("MONTO", style: TextStyle(fontSize: 11, fontWeight: FontWeight.bold, color: Colors.grey))),
            Padding(padding: EdgeInsets.symmetric(vertical: 10), child: Text("", style: TextStyle(fontSize: 11))),
          ]),
          ..._pagos.map((p) => TableRow(children: [
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 10),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(p.metodo, style: const TextStyle(fontSize: 13)),
                  // Badge de conciliación BDV (sólo cuando hay un intento)
                  if (p.conciliadoBDV != null) ...[
                    const SizedBox(height: 3),
                    Container(
                      padding: const EdgeInsets.symmetric(
                          horizontal: 6, vertical: 2),
                      decoration: BoxDecoration(
                        color: p.conciliadoBDV!
                            ? AppColors.statusGreen.withValues(alpha: 0.12)
                            : Colors.orange.withValues(alpha: 0.15),
                        borderRadius: BorderRadius.circular(8),
                        border: Border.all(
                          color: p.conciliadoBDV!
                              ? AppColors.statusGreen
                              : Colors.orange.shade700,
                          width: 0.8),
                      ),
                      child: Row(mainAxisSize: MainAxisSize.min, children: [
                        Icon(
                          p.conciliadoBDV! ? Icons.verified : Icons.warning_amber,
                          size: 10,
                          color: p.conciliadoBDV!
                              ? AppColors.statusGreen
                              : Colors.orange.shade800),
                        const SizedBox(width: 3),
                        Text(
                          p.conciliadoBDV! ? "BDV ✓" : "No conciliado",
                          style: TextStyle(
                            fontSize: 9,
                            fontWeight: FontWeight.bold,
                            color: p.conciliadoBDV!
                                ? AppColors.statusGreen
                                : Colors.orange.shade800)),
                      ]),
                    ),
                  ],
                  // Datos del pago móvil (referencia, cédula y teléfono
                  // del pagador) para que el cajero los verifique.
                  if (datosPagoMovilTexto(p.toMap()).isNotEmpty) ...[
                    const SizedBox(height: 3),
                    Text(datosPagoMovilTexto(p.toMap()),
                      style: const TextStyle(
                          fontSize: 10, color: AppColors.textSecondary)),
                  ],
                ],
              ),
            ),
            Padding(padding: const EdgeInsets.symmetric(vertical: 10), child: Text(formatMontoPorMetodo(p.monto, p.metodo), style: const TextStyle(fontSize: 13, fontWeight: FontWeight.bold))),
            InkWell(
              onTap: () => setState(() => _pagos.remove(p)),
              child: const Padding(padding: EdgeInsets.symmetric(vertical: 10), child: Icon(Icons.remove_circle_outline, color: Colors.red, size: 20))),
          ])),
        ]),
      const SizedBox(height: 8),
      Row(mainAxisAlignment: MainAxisAlignment.end, children: [
        const Text("TOTAL PAGADO: ", style: TextStyle(fontSize: 13, fontWeight: FontWeight.bold)),
        Flexible(child: Text(
          formatTotalesPorMoneda(totalesPagado.usd, totalesPagado.bs),
          textAlign: TextAlign.right,
          style: const TextStyle(fontSize: 15, fontWeight: FontWeight.bold, color: AppColors.primaryBlue))),
      ]),
    ]);
  }

  void _mostrarDialogoBusqueda() {
    // Estado del diálogo: producto/equipo detectado + selección F/D por producto
    Producto? prodDetectado;
    ImeiRegistro? imeiDetectado;
    String tipoVentaSeleccionado = "Contado";
    String? financiadorSeleccionado;
    // ── Datos del financiamiento (solo si tipo != Contado) ──
    int? numeroCuotasSeleccionado;
    double? montoCuotaSeleccionado;
    String? listaSeleccionada;  // Nombre de la lista de precios elegida
    final cuotasCtrl = TextEditingController();
    final montoCuotaCtrl = TextEditingController();

    // Maps de colores para el dropdown F/D (mismo criterio visual que antes)
    const estilosFD = <String, List<Color>>{
      'Contado': [Color(0xFFEDEDED), Color(0xFF111111)],
      'Cashea' : [Color(0xFFFFD600), Color(0xFF000000)],
      'Weppa'  : [Color(0xFF6A1B9A), Color(0xFFFFD600)],
      'Krece'  : [Color(0xFF006B7F), Color(0xFFFFFFFF)],
      'FPB'    : [Color(0xFF002366), Color(0xFFFFFFFF)],
    };
    const opcionesFD = ['Contado', 'Cashea', 'Weppa', 'Krece', 'FPB'];

    Widget chipFD(String o, {bool compacto = false}) {
      final par = estilosFD[o] ?? const <Color>[Colors.white, Colors.black];
      return Container(
        padding: EdgeInsets.symmetric(
            horizontal: compacto ? 10 : 12, vertical: compacto ? 4 : 8),
        decoration: BoxDecoration(
          color: par[0],
          borderRadius: BorderRadius.circular(6),
          border: Border.all(
              color: par[0].computeLuminance() > 0.85
                  ? Colors.grey.shade400
                  : par[0],
              width: 1),
        ),
        child: Text(o,
            style: TextStyle(
                color: par[1],
                fontWeight: FontWeight.bold,
                fontSize: 13,
                letterSpacing: 0.3)),
      );
    }

    // Resuelve el código escaneado/tipeado y actualiza prodDetectado/imeiDetectado
    void resolverCodigo(String val, void Function(void Function()) setS) {
      final v = val.trim();
      prodDetectado = null;
      imeiDetectado = null;
      if (v.isEmpty) {
        setS(() {});
        return;
      }
      final imei = _buscarImei(v);
      if (imei != null) {
        // Un equipo de otra tienda no se "detecta": no hay nada que
        // agregar, sólo el aviso de dónde está realmente.
        if (_esDeOtraTienda(imei.ubicacion)) {
          _avisarOtraTienda(
              'El equipo ${imei.producto.nombre} (IMEI ${imei.imei})',
              imei.ubicacion);
          setS(() {});
          return;
        }
        imeiDetectado = imei;
        setS(() {});
        return;
      }
      final prod = catalogoGlobal.where((p) => p.codigo == v).firstOrNull;
      if (prod != null) {
        if (_productoEsDeOtraTienda(prod)) {
          _avisarOtraTienda('El producto ${prod.nombre}', prod.tienda);
          setS(() {});
          return;
        }
        prodDetectado = prod;
      }
      setS(() {});
    }

    showDialog(
      context: context,
      builder: (c) => StatefulBuilder(builder: (context, setS) {
        // Resumen del producto detectado
        String resumen = "";
        int? stockRestante;
        if (imeiDetectado != null) {
          resumen = "📱 ${imeiDetectado!.producto.nombre} — IMEI: ${imeiDetectado!.imei}";
        } else if (prodDetectado != null) {
          final yaAgregados =
              _items.where((p) => p.codigo == prodDetectado!.codigo).length;
          stockRestante = prodDetectado!.stockTotal - yaAgregados;
          resumen =
              "${prodDetectado!.nombre} (Stock: $stockRestante)";
        }
        final hayDetectado = imeiDetectado != null || prodDetectado != null;
        final puedeAgregar = hayDetectado &&
            (imeiDetectado != null ||
                (stockRestante != null && stockRestante > 0));

        return AlertDialog(
          title: const Row(children: [
            Icon(Icons.qr_code_scanner, color: AppColors.royalBlue),
            SizedBox(width: 8),
            Text("Añadir Producto"),
          ]),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // ── Campo de código con botón scanner (cámara) ──
                Row(children: [
                  Expanded(
                    child: TextField(
                      controller: _codigo,
                      autofocus: true,
                      keyboardType: TextInputType.text,
                      decoration: InputDecoration(
                        hintText: "IMEI o código SKU",
                        hintStyle: const TextStyle(fontSize: 13),
                        prefixIcon: const Icon(Icons.keyboard, size: 20),
                        suffixIcon: _codigo.text.isNotEmpty
                            ? IconButton(
                                icon: const Icon(Icons.clear, size: 18),
                                onPressed: () {
                                  _codigo.clear();
                                  resolverCodigo('', setS);
                                })
                            : null,
                      ),
                      onChanged: (val) => resolverCodigo(val, setS),
                      onSubmitted: (_) {
                        if (puedeAgregar) {
                          _agregarProductoConFinanciamiento(
                              tipoVentaSeleccionado,
                              financiadorSeleccionado,
                              numeroCuotasSeleccionado,
                              montoCuotaSeleccionado,
                              listaSeleccionada);
                          Navigator.pop(c);
                        }
                      }),
                  ),
                  const SizedBox(width: 8),
                  // Botón grande que abre la cámara como scanner de código
                  ElevatedButton.icon(
                    icon: const Icon(Icons.qr_code_scanner, size: 20),
                    label: const Text("Escanear"),
                    style: ElevatedButton.styleFrom(
                        backgroundColor: AppColors.primaryBlue,
                        foregroundColor: Colors.white,
                        padding: const EdgeInsets.symmetric(
                            horizontal: 12, vertical: 12)),
                    onPressed: () {
                      // Guardar borrador ANTES de abrir el scanner: si el
                      // SO mata el proceso por baja memoria mientras la
                      // cámara está activa (ocurre con frecuencia en
                      // teléfonos modestos), al volver podremos restaurar
                      // todos los items ya agregados a la factura.
                      _guardarBorrador();
                      // Abre el scanner; al detectar un código, lo escribe
                      // en _codigo y llama a resolverCodigo para refrescar
                      // el estado del diálogo con el producto encontrado.
                      Navigator.push(
                        context,
                        MaterialPageRoute(
                          builder: (_) => ScannerPage(
                            onDetect: (codigo) {
                              _codigo.text = codigo;
                              resolverCodigo(codigo, setS);
                            },
                          ),
                        ),
                      );
                    },
                  ),
                ]),
                const SizedBox(height: 12),
                // Estado de detección
                if (!hayDetectado && _codigo.text.isNotEmpty)
                  Container(
                    padding: const EdgeInsets.all(8),
                    decoration: BoxDecoration(
                        color: Colors.orange[50],
                        borderRadius: BorderRadius.circular(4)),
                    child: const Row(children: [
                      Icon(Icons.search_off,
                          color: Colors.orange, size: 16),
                      SizedBox(width: 8),
                      Expanded(
                          child: Text("Producto no encontrado o sin stock",
                              style: TextStyle(
                                  color: Colors.orange, fontSize: 12))),
                    ]),
                  ),
                if (hayDetectado)
                  Container(
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                        color: Colors.green[50],
                        borderRadius: BorderRadius.circular(6)),
                    child: Row(children: [
                      const Icon(Icons.check_circle,
                          color: Colors.green, size: 18),
                      const SizedBox(width: 8),
                      Expanded(
                          child: Text(resumen,
                              style: const TextStyle(
                                  color: Colors.green,
                                  fontWeight: FontWeight.bold,
                                  fontSize: 13))),
                    ]),
                  ),
                const SizedBox(height: 16),
                // ── F/D por producto (solo aparece con producto detectado) ──
                if (hayDetectado) ...[
                  const Text("Forma de venta (F/D) para este producto:",
                      style: TextStyle(
                          fontSize: 12,
                          fontWeight: FontWeight.bold,
                          color: AppColors.textSecondary)),
                  const SizedBox(height: 6),
                  DropdownButtonFormField<String>(
                    value: tipoVentaSeleccionado,
                    isExpanded: true,
                    decoration: const InputDecoration(
                      labelText: "F/D (Financiadora)",
                      border: OutlineInputBorder(),
                      contentPadding: EdgeInsets.symmetric(
                          horizontal: 10, vertical: 6),
                    ),
                    selectedItemBuilder: (ctx) => opcionesFD
                        .map((o) => Align(
                            alignment: Alignment.centerLeft,
                            child: chipFD(o, compacto: true)))
                        .toList(),
                    items: opcionesFD
                        .map((o) => DropdownMenuItem(
                            value: o, child: chipFD(o)))
                        .toList(),
                    onChanged: (v) {
                      if (v == null) return;
                      setS(() {
                        tipoVentaSeleccionado = v;
                        // Al cambiar de F/D se resetea el financiador
                        // (la persona) — solo aplica a ventas financiadas.
                        financiadorSeleccionado = null;
                      });
                    },
                  ),
                  // Si la venta es financiada (Cashea/Weppa/Krece), pedir
                  // el FINANCIADOR: la persona/usuario que entrega el equipo.
                  // OJO: esto es distinto de la FINANCIADORA (la app), que
                  // ya quedó definida arriba por el dropdown F/D.
                  if (tipoVentaSeleccionado == "Cashea" ||
                      tipoVentaSeleccionado == "Weppa" ||
                      tipoVentaSeleccionado == "Krece") ...[
                    const SizedBox(height: 8),
                    Container(
                      padding: const EdgeInsets.all(8),
                      decoration: BoxDecoration(
                        color: AppColors.brandBlue.withValues(alpha: 0.08),
                        borderRadius: BorderRadius.circular(8),
                      ),
                      child: Row(children: [
                        const Icon(Icons.account_balance,
                            size: 16, color: AppColors.brandBlue),
                        const SizedBox(width: 6),
                        Expanded(child: Text(
                          "Financiadora: $tipoVentaSeleccionado. "
                          "La deuda se calculará según la lista de "
                          "precios de $tipoVentaSeleccionado.",
                          style: const TextStyle(
                              fontSize: 11, height: 1.3),
                        )),
                      ]),
                    ),
                    const SizedBox(height: 10),
                    DropdownButtonFormField<String>(
                      value: financiadorSeleccionado,
                      isExpanded: true,
                      decoration: const InputDecoration(
                          labelText: "Financiador (quien entrega el equipo)",
                          border: OutlineInputBorder(),
                          isDense: true),
                      items: usuariosSistema
                          .map((u) => DropdownMenuItem(
                              value: u.nombre, child: Text(u.nombre)))
                          .toList(),
                      onChanged: (v) =>
                          setS(() => financiadorSeleccionado = v),
                    ),
                    const SizedBox(height: 10),
                    // ── Selector de Lista de Precios ──
                    // Buscar todas las listas de precios cuya financiadora
                    // coincida con la selección (Cashea/Weppa/Krece). Si
                    // hay 2+ listas (ej. normal y promoción) el vendedor
                    // DEBE escoger cuál se aplica para que el reporte
                    // distinga entre ellas. Si solo hay 1, se auto-selecciona.
                    Builder(builder: (_) {
                      final finLow = tipoVentaSeleccionado.toLowerCase();
                      final listasFin = listasPreciosGlobal.where((lp) {
                        final lpFin = (lp.financiadora ?? '').toLowerCase().trim();
                        if (lpFin.isEmpty) return false;
                        return lpFin.contains(finLow) || finLow.contains(lpFin);
                      }).toList();
                      // Auto-seleccionar si solo hay 1 lista disponible.
                      if (listasFin.length == 1 && listaSeleccionada == null) {
                        WidgetsBinding.instance.addPostFrameCallback((_) {
                          setS(() => listaSeleccionada = listasFin.first.nombre);
                        });
                      }
                      if (listasFin.isEmpty) {
                        return Container(
                          padding: const EdgeInsets.all(10),
                          decoration: BoxDecoration(
                            color: Colors.orange.withValues(alpha: 0.1),
                            border: Border.all(color: Colors.orange.shade300),
                            borderRadius: BorderRadius.circular(6),
                          ),
                          child: Row(children: [
                            Icon(Icons.warning_amber, size: 16,
                                color: Colors.orange.shade800),
                            const SizedBox(width: 8),
                            Expanded(child: Text(
                              "No hay listas de precios para $tipoVentaSeleccionado. "
                              "Crear una en el módulo de Listas para que el reporte "
                              "calcule bien.",
                              style: TextStyle(
                                  fontSize: 11,
                                  color: Colors.orange.shade900))),
                          ]),
                        );
                      }
                      return DropdownButtonFormField<String>(
                        value: listaSeleccionada,
                        isExpanded: true,
                        decoration: const InputDecoration(
                          labelText: "Lista de precios aplicada",
                          border: OutlineInputBorder(),
                          isDense: true,
                          prefixIcon: Icon(Icons.list_alt),
                        ),
                        items: listasFin
                            .map((lp) => DropdownMenuItem(
                                value: lp.nombre,
                                child: Text(lp.nombre,
                                    overflow: TextOverflow.ellipsis)))
                            .toList(),
                        onChanged: (v) =>
                            setS(() => listaSeleccionada = v),
                      );
                    }),
                    const SizedBox(height: 10),
                    // ── Cuotas del financiamiento ──
                    // El vendedor especifica N° de cuotas y monto de cada
                    // cuota. Estos datos se guardan en el pago y se
                    // imprimen en la factura como mensaje al final.
                    Row(children: [
                      Expanded(child: TextField(
                        controller: cuotasCtrl,
                        keyboardType: TextInputType.number,
                        decoration: const InputDecoration(
                          labelText: "N° de cuotas",
                          hintText: "Ej: 6",
                          border: OutlineInputBorder(),
                          isDense: true,
                          prefixIcon: Icon(Icons.format_list_numbered),
                        ),
                        onChanged: (v) => setS(() {
                          numeroCuotasSeleccionado = int.tryParse(v.trim());
                        }),
                      )),
                      const SizedBox(width: 8),
                      Expanded(child: TextField(
                        controller: montoCuotaCtrl,
                        keyboardType: const TextInputType.numberWithOptions(decimal: true),
                        decoration: const InputDecoration(
                          labelText: "Monto por cuota (\$)",
                          hintText: "Ej: 25.50",
                          border: OutlineInputBorder(),
                          isDense: true,
                          prefixIcon: Icon(Icons.attach_money),
                        ),
                        onChanged: (v) => setS(() {
                          montoCuotaSeleccionado = double.tryParse(v.trim());
                        }),
                      )),
                    ]),
                  ],
                ],
              ],
            ),
          ),
          actions: [
            TextButton(
                onPressed: () {
                  _codigo.clear();
                  Navigator.pop(c);
                },
                child: const Text("Cerrar")),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: puedeAgregar
                      ? AppColors.primaryBlue
                      : Colors.grey),
              onPressed: puedeAgregar
                  ? () {
                      _agregarProductoConFinanciamiento(
                          tipoVentaSeleccionado,
                          financiadorSeleccionado,
                          numeroCuotasSeleccionado,
                          montoCuotaSeleccionado,
                          listaSeleccionada);
                      Navigator.pop(c);
                    }
                  : null,
              child:
                  const Text("Agregar", style: TextStyle(color: Colors.white))),
          ]);
      }),
    );
  }

  /// Agrega el producto/equipo detectado (por _codigo) y registra el
  /// financiamiento por item en los mapas _tipoVentaItem/_financiadorItem,
  /// y los mapas de cuotas si el tipo de venta es financiado.
  void _agregarProductoConFinanciamiento(
      String tipoVenta,
      String? financiador,
      [int? numeroCuotas,
      double? montoCuota,
      String? nombreLista]) {
    final val = _codigo.text.trim();
    if (val.isEmpty) return;

    final imei = _buscarImei(val);
    if (imei != null) {
      if (_esDeOtraTienda(imei.ubicacion)) {
        _avisarOtraTienda(
            'El equipo ${imei.producto.nombre} (IMEI ${imei.imei})',
            imei.ubicacion);
        return;
      }
      if (_equipos.contains(imei)) {
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
            content: Text("Este equipo ya está en la lista")));
        return;
      }
      setState(() {
        _equipos.add(imei);
        final h = identityHashCode(imei);
        _tipoVentaEquipo[h] = tipoVenta;
        _financiadorEquipo[h] = financiador;
        if (numeroCuotas != null && numeroCuotas > 0) {
          _cuotasEquipo[h] = numeroCuotas;
        }
        if (montoCuota != null && montoCuota > 0) {
          _montoCuotaEquipo[h] = montoCuota;
        }
        if (nombreLista != null && nombreLista.isNotEmpty) {
          _listaEquipo[h] = nombreLista;
        }
      });
      _codigo.clear();
      return;
    }

    final prod = catalogoGlobal.where((p) => p.codigo == val).firstOrNull;
    if (prod != null) {
      if (_productoEsDeOtraTienda(prod)) {
        _avisarOtraTienda('El producto ${prod.nombre}', prod.tienda);
        return;
      }
      final yaAgregados =
          _items.where((p) => p.codigo == val).length;
      if (prod.stockTotal - yaAgregados <= 0) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
            content: Text(
                "Sin stock disponible para ${prod.nombre} (stock actual: ${prod.stockTotal})"),
            backgroundColor: Colors.orange[800]));
        return;
      }
      setState(() {
        _items.add(prod);
        final h = identityHashCode(prod);
        _tipoVentaItem[h] = tipoVenta;
        _financiadorItem[h] = financiador;
        if (numeroCuotas != null && numeroCuotas > 0) {
          _cuotasItem[h] = numeroCuotas;
        }
        if (montoCuota != null && montoCuota > 0) {
          _montoCuotaItem[h] = montoCuota;
        }
        if (nombreLista != null && nombreLista.isNotEmpty) {
          _listaItem[h] = nombreLista;
        }
      });
      _codigo.clear();
      return;
    }

    ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text("Producto no encontrado o ya vendido")));
  }

  /// Detecta si un nombre de método de pago corresponde a "Pago Móvil"
  /// (con o sin acento, mayúsculas/minúsculas).
  bool _esPagoMovil(String metodo) {
    final m = metodo.trim().toLowerCase();
    return m == 'pago móvil' || m == 'pago movil';
  }

  void _mostrarDialogoPago() {
    // ── Estado local del diálogo ───────────────────────────────
    // Banco destino (donde llega el pago — sólo aplica a Pago Móvil).
    // Por defecto sugerimos BDV (porque es el único con conciliación
    // automática en la app).
    String bancoDestinoSel = BancosVenezuela.codigoBDV;
    // Banco origen (de donde sale el dinero del cliente).
    String bancoOrigenSel = BancosVenezuela.codigoBDV;

    // Controllers para los campos de datos del pago móvil. Se crean
    // dentro del builder para que se reseteen cada vez que se abre
    // el diálogo. Se disponen al cerrar.
    final ctrlReferencia       = TextEditingController();
    final ctrlCedulaPagador    = TextEditingController();
    final ctrlTelefonoPagador  = TextEditingController();

    // Letra de la cédula del pagador (V/E/J/G/P).
    String letraCedula = 'V';
    // Fecha del pago — por defecto hoy.
    DateTime fechaPagoSel = DateTime.now();

    // Si el vendedor marca este pago como la INICIAL del cliente.
    // El reporte por financiadora usa este flag para saber qué monto
    // exacto restar como inicial en la fórmula (Base − Inicial) − 3.5%.
    bool marcarComoInicial = false;

    // Controllers para cuotas del financiamiento. Solo se usan si el
    // vendedor los llena manualmente (aparecen abajo del monto). Si el
    // usuario no los toca, se dejan las cuotas derivadas de los items
    // con lista de precios financiada (comportamiento anterior).
    final ctrlNumeroCuotas = TextEditingController();
    final ctrlMontoCuota   = TextEditingController();

    showDialog(context: context, builder: (c) => StatefulBuilder(builder: (context, setS) {
      final esPagoMovil = _esPagoMovil(_metodo);

      // ── Acción: aceptar el pago ──
      void aceptarPago() {
        final monto = double.tryParse(_montoPago.text.trim());
        if (monto == null || monto <= 0) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text("Ingrese un monto válido mayor a 0"),
              backgroundColor: AppColors.statusOrange));
          return;
        }

        if (esPagoMovil) {
          // Para pago móvil exigimos referencia, cédula y teléfono
          // afiliado del pagador: son los datos que auditoría necesita
          // para ubicar el pago en el estado de cuenta del banco.
          String? faltante;
          if (ctrlReferencia.text.trim().isEmpty) {
            faltante = "Ingrese la referencia del pago móvil";
          } else if (ctrlCedulaPagador.text.trim().isEmpty) {
            faltante = "Ingrese la cédula del pagador del pago móvil";
          } else if (ctrlTelefonoPagador.text.trim().length < 10) {
            faltante = "Ingrese el teléfono afiliado al pago móvil (ej. 04141234567)";
          }
          if (faltante != null) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(content: Text(faltante),
                backgroundColor: AppColors.statusOrange));
            return;
          }
          // Fecha del pago en formato YYYY-MM-DD
          final f = fechaPagoSel;
          final fechaFmt = '${f.year.toString().padLeft(4,"0")}-'
                           '${f.month.toString().padLeft(2,"0")}-'
                           '${f.day.toString().padLeft(2,"0")}';
          // Cédula con prefijo (puede estar vacía si el usuario no lo cargó
          // y no está intentando conciliar — el campo se queda en null)
          String? cedulaFmt;
          if (ctrlCedulaPagador.text.trim().isNotEmpty) {
            cedulaFmt = '$letraCedula${ctrlCedulaPagador.text.trim()}';
          }
          _agregarPago(
            bancoDestino       : bancoDestinoSel,
            bancoOrigen        : bancoOrigenSel,
            referenciaPM       : ctrlReferencia.text.trim(),
            cedulaPagador      : cedulaFmt,
            telefonoPagador    : ctrlTelefonoPagador.text.trim().isEmpty
                ? null : ctrlTelefonoPagador.text.trim(),
            // El teléfono destino siempre es el del comercio (no se
            // edita en el formulario, viene de ConfigBDV).
            telefonoDestino    : ConfigBDV.telefonoComercio,
            fechaPago          : fechaFmt,
            esInicial          : marcarComoInicial,
            numeroCuotasManual : int.tryParse(ctrlNumeroCuotas.text.trim()),
            montoCuotaManual   : double.tryParse(ctrlMontoCuota.text.trim()),
          );
        } else {
          _agregarPago(
            esInicial          : marcarComoInicial,
            numeroCuotasManual : int.tryParse(ctrlNumeroCuotas.text.trim()),
            montoCuotaManual   : double.tryParse(ctrlMontoCuota.text.trim()),
          );
        }
        Navigator.pop(c);
      }

      return AlertDialog(
        scrollable: true,
        title: Row(children: const [
          Icon(Icons.payment_outlined, color: AppColors.royalBlue),
          SizedBox(width: 8),
          Text("Registrar Pago"),
        ]),
        content: SizedBox(
          width: 420,
          child: Column(mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
            // ── Método de pago ─────────────────────────────────
            DropdownButtonFormField<String>(
              value: _metodo,
              isExpanded: true,
              decoration: const InputDecoration(
                labelText: "Método de pago",
                prefixIcon: Icon(Icons.payment)),
              items: ConfigSistema.metodossPago
                  .map((e) => DropdownMenuItem(value: e, child: Text(e))).toList(),
              onChanged: (v) => setS(() {
                _metodo = v!;
                // Al cambiar de método, reseteamos el resultado de
                // conciliación (porque puede dejar de aplicar).
              })),
            const SizedBox(height: 12),

            // ── Monto ──────────────────────────────────────────
            TextField(
              controller: _montoPago,
              autofocus: !esPagoMovil,
              keyboardType: const TextInputType.numberWithOptions(decimal: true),
              decoration: InputDecoration(
                labelText: esPagoMovil ? "Monto (Bs)" : "Monto",
                prefixIcon: const Icon(Icons.payments_outlined),
                helperText: esPagoMovil
                    ? "El importe se enviará al BDV en bolívares"
                    : null),
              onSubmitted: (_) {
                if (!esPagoMovil) aceptarPago();
              }),

            const SizedBox(height: 8),
            // ── Marcar como inicial ────────────────────────────
            // Este toggle le indica al sistema que ESTE pago en
            // específico es la inicial que el cliente paga de su
            // bolsillo. El Reporte por Financiadora lo usa en la
            // fórmula (Base − Inicial) − 3.5% = Deuda.
            Container(
              decoration: BoxDecoration(
                color: marcarComoInicial
                    ? AppColors.brandYellow.withValues(alpha: 0.15)
                    : AppColors.surfaceTintBlue,
                borderRadius: BorderRadius.circular(10),
                border: Border.all(
                  color: marcarComoInicial
                      ? AppColors.brandYellow
                      : Colors.transparent,
                  width: 1.5),
              ),
              child: SwitchListTile(
                value: marcarComoInicial,
                onChanged: (v) => setS(() => marcarComoInicial = v),
                activeColor: AppColors.brandBlue,
                contentPadding: const EdgeInsets.symmetric(horizontal: 12),
                title: const Text("Marcar como inicial del cliente",
                    style: TextStyle(
                        fontWeight: FontWeight.w700, fontSize: 13.5)),
                subtitle: const Text(
                    "Indica que este monto es la inicial que paga el "
                    "cliente. Se usa en el cálculo de deuda de la "
                    "financiadora.",
                    style: TextStyle(fontSize: 11, height: 1.3)),
                secondary: Icon(
                    marcarComoInicial
                        ? Icons.star
                        : Icons.star_outline,
                    color: marcarComoInicial
                        ? AppColors.brandYellow
                        : AppColors.textSecondary),
              ),
            ),

            // ── CUOTAS DEL FINANCIAMIENTO ─────────────────────
            // Estos campos aparecen SIEMPRE. Si el pago es financiado,
            // lo que se ingresa acá se guarda en el PagoFactura y se
            // imprime en la factura como "N cuotas de $Y c/u". Si el
            // pago no es financiado, se ignoran. Si se dejan vacíos y
            // hay algún item con lista de precios financiada, se usan
            // los valores derivados de esa lista (comportamiento previo).
            const SizedBox(height: 12),
            const Text(
              "Financiamiento (opcional)",
              style: TextStyle(
                fontSize: 11, fontWeight: FontWeight.w600,
                color: AppColors.textSecondary, letterSpacing: 0.5),
            ),
            const SizedBox(height: 6),
            Row(children: [
              Expanded(child: TextField(
                controller: ctrlNumeroCuotas,
                keyboardType: TextInputType.number,
                decoration: const InputDecoration(
                  labelText: "N° de cuotas",
                  hintText: "Ej: 6",
                  border: OutlineInputBorder(),
                  isDense: true,
                  prefixIcon: Icon(Icons.format_list_numbered),
                ),
              )),
              const SizedBox(width: 8),
              Expanded(child: TextField(
                controller: ctrlMontoCuota,
                keyboardType: const TextInputType.numberWithOptions(decimal: true),
                decoration: const InputDecoration(
                  labelText: "Monto por cuota (\$)",
                  hintText: "Ej: 25.50",
                  border: OutlineInputBorder(),
                  isDense: true,
                  prefixIcon: Icon(Icons.attach_money),
                ),
              )),
            ]),

            // ── Bloque específico de Pago Móvil ───────────────
            if (esPagoMovil) ...[
              const SizedBox(height: 16),
              const Divider(),
              const SizedBox(height: 4),
              Row(children: const [
                Icon(Icons.account_balance, size: 16,
                    color: AppColors.royalBlue),
                SizedBox(width: 6),
                Text("DATOS DEL PAGO MÓVIL",
                    style: TextStyle(fontWeight: FontWeight.bold,
                        fontSize: 12, color: AppColors.royalBlue,
                        letterSpacing: 0.5)),
              ]),
              const SizedBox(height: 10),

              // Banco destino (donde llega el pago — el del comercio)
              DropdownButtonFormField<String>(
                value: bancoDestinoSel,
                isExpanded: true,
                decoration: const InputDecoration(
                    labelText: "Banco destino (cuenta del comercio)",
                    prefixIcon: Icon(Icons.account_balance_wallet_outlined)),
                items: BancosVenezuela.listaOrdenada
                    .map((e) => DropdownMenuItem(
                        value: e.key,
                        child: Text(
                          '${e.key} — ${e.value}',
                          overflow: TextOverflow.ellipsis,
                        )))
                    .toList(),
                onChanged: (v) => setS(() {
                  bancoDestinoSel = v!;
                })),
              const SizedBox(height: 10),

              // Banco origen (de donde paga el cliente)
              DropdownButtonFormField<String>(
                value: bancoOrigenSel,
                isExpanded: true,
                decoration: const InputDecoration(
                    labelText: "Banco origen (cuenta del cliente)",
                    prefixIcon: Icon(Icons.compare_arrows_outlined)),
                items: BancosVenezuela.listaOrdenada
                    .map((e) => DropdownMenuItem(
                        value: e.key,
                        child: Text(
                          '${e.key} — ${e.value}',
                          overflow: TextOverflow.ellipsis,
                        )))
                    .toList(),
                onChanged: (v) => setS(() {
                  bancoOrigenSel = v!;
                })),
              const SizedBox(height: 10),

              // Referencia
              TextField(
                controller: ctrlReferencia,
                keyboardType: TextInputType.number,
                decoration: const InputDecoration(
                  labelText: "Referencia *",
                  hintText: "Número de referencia del pago",
                  prefixIcon: Icon(Icons.confirmation_number_outlined)),
              ),
              const SizedBox(height: 10),

              // Fecha del pago
              Builder(builder: (_) {
                final hoy = DateTime.now();
                return InkWell(
                  borderRadius: BorderRadius.circular(10),
                  onTap: () async {
                    final picked = await showDatePicker(
                      context: context,
                      initialDate: fechaPagoSel,
                      firstDate: DateTime(2020),
                      lastDate: hoy.add(const Duration(days: 1)),
                      helpText: "Selecciona la fecha del pago móvil",
                    );
                    if (picked != null) {
                      setS(() { fechaPagoSel = picked; });
                    }
                  },
                  child: InputDecorator(
                    decoration: const InputDecoration(
                        labelText: "Fecha del pago",
                        prefixIcon: Icon(Icons.event_outlined)),
                    child: Text(
                      '${fechaPagoSel.day.toString().padLeft(2,"0")}/'
                      '${fechaPagoSel.month.toString().padLeft(2,"0")}/'
                      '${fechaPagoSel.year}',
                      style: const TextStyle(fontSize: 14),
                    ),
                  ),
                );
              }),

              // ── Datos del pagador (auditoría manual) ──────────
              const SizedBox(height: 14),
              Container(
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(
                  color: AppColors.surfaceTintBlue,
                  borderRadius: BorderRadius.circular(8),
                ),
                child: Row(children: const [
                  Icon(Icons.info_outline, size: 16, color: AppColors.brandBlue),
                  SizedBox(width: 6),
                  Expanded(child: Text(
                    "Datos del pagador (obligatorios, para auditoría): "
                    "cédula y teléfono afiliado al pago móvil.",
                    style: TextStyle(fontSize: 11.5, height: 1.3),
                  )),
                ]),
              ),
              const SizedBox(height: 10),

              // Cédula del pagador (letra + número)
              Row(children: [
                SizedBox(
                  width: 90,
                  child: DropdownButtonFormField<String>(
                    value: letraCedula,
                    decoration: const InputDecoration(
                      labelText: "Tipo",
                      contentPadding: EdgeInsets.symmetric(
                          horizontal: 10, vertical: 14)),
                    items: const ['V', 'E', 'J', 'G', 'P']
                        .map((e) => DropdownMenuItem(
                            value: e, child: Text(e)))
                        .toList(),
                    onChanged: (v) => setS(() {
                      letraCedula = v!;
                    })),
                ),
                const SizedBox(width: 8),
                Expanded(child: TextField(
                  controller: ctrlCedulaPagador,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(
                    labelText: "Cédula del pagador *",
                    hintText: "12345678",
                    prefixIcon: Icon(Icons.badge_outlined)),
                )),
              ]),
              const SizedBox(height: 10),

              // Teléfono del pagador
              TextField(
                controller: ctrlTelefonoPagador,
                keyboardType: TextInputType.phone,
                decoration: const InputDecoration(
                  labelText: "Teléfono afiliado del pagador *",
                  hintText: "04127141363",
                  prefixIcon: Icon(Icons.phone_android)),
              ),
            ],
          ]),
        ),
        actions: [
          TextButton(
            onPressed: () { _montoPago.clear(); Navigator.pop(c); },
            child: const Text("Cancelar")),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: AppColors.primaryBlue),
            onPressed: aceptarPago,
            child: const Text("Confirmar",
                style: TextStyle(color: Colors.white))),
        ]);
    })).then((_) {
      // Limpiar controllers locales al cerrar el diálogo
      ctrlReferencia.dispose();
      ctrlCedulaPagador.dispose();
      ctrlTelefonoPagador.dispose();
    });
  }

  /// Versión validada de _agregarPago — retorna true si se agregó correctamente
  bool _agregarPagoValidado() {
    final monto = double.tryParse(_montoPago.text.trim());
    if (monto == null || monto <= 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text("Ingrese un monto válido mayor a 0"),
          backgroundColor: AppColors.statusOrange));
      return false;
    }
    _agregarPago();
    return true;
  }

}

// ════════════════════════════════════════════════════════════════════
//  BANNER DE RESULTADO DE CONCILIACIÓN BDV
//  Se muestra dentro del diálogo "Registrar Pago" cuando se ejecuta
//  la verificación contra el API del Banco de Venezuela.
//  · Verde   → code 1000 (transacción localizada y validada).
//  · Naranja → code 1010 u otro de negocio (no encontrado, datos
//              inválidos). El cajero puede aún registrar el pago,
//              pero queda marcado como "no conciliado".
//  · Rojo    → error de red / contrato JSON / conexión.
// ════════════════════════════════════════════════════════════════════

// ============================================================
//  BURBUJA DE AUDIO
// ============================================================
class BurbujaAudio extends StatefulWidget {
  final String path;
  const BurbujaAudio({super.key, required this.path});
  @override State<BurbujaAudio> createState() => _BurbujaAudioState();
}

class _BurbujaAudioState extends State<BurbujaAudio> {
  final AudioPlayer _audioPlayer = AudioPlayer();
  bool _reproduciendo = false;

  @override
  void initState() {
    super.initState();
    // Registrar listener una sola vez en initState, no en cada toque
    _audioPlayer.onPlayerComplete.listen((_) {
      if (mounted) setState(() => _reproduciendo = false);
    });
  }

  @override
  void dispose() {
    _audioPlayer.dispose();
    super.dispose();
  }

  Future<void> _toggleAudio() async {
    try {
      if (_reproduciendo) {
        await _audioPlayer.pause();
      } else {
        // Escoger la Source adecuada según el tipo de ruta.
        // Si viene una URL (http/https) o ruta relativa del servidor,
        // usamos UrlSource. Si es una ruta local legacy, DeviceFileSource.
        final p = widget.path;
        Source source;
        if (p.startsWith('http://') || p.startsWith('https://')) {
          source = UrlSource(p);
        } else if (p.startsWith('/') || p.startsWith('uploads/')) {
          final base = BASE_URL.replaceAll('/api.php', '');
          final sep = p.startsWith('/') ? '' : '/';
          source = UrlSource('$base$sep$p');
        } else {
          source = DeviceFileSource(p);
        }
        await _audioPlayer.play(source);
      }
      if (mounted) setState(() => _reproduciendo = !_reproduciendo);
    } catch (e) {
      debugPrint('[BurbujaAudio] Error: $e');
      if (mounted) setState(() => _reproduciendo = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Row(mainAxisSize: MainAxisSize.min, children: [
      IconButton(
        icon: Icon(_reproduciendo ? Icons.pause : Icons.play_arrow,
          color: Colors.white),
        onPressed: _toggleAudio),
      const Text("Mensaje de voz", style: TextStyle(color: Colors.white)),
    ]);
  }
}

// ============================================================
//  ESCANER QR/IMEI
// ============================================================
class ScannerPage extends StatefulWidget {
  final Function(String) onDetect;
  const ScannerPage({super.key, required this.onDetect});
  @override
  State<ScannerPage> createState() => _ScannerPageState();
}

class _ScannerPageState extends State<ScannerPage> {
  /// Bandera para que onDetect SOLO se dispare una vez. MobileScanner
  /// emite el barcode múltiples veces por segundo mientras la cámara lo
  /// "ve", y sin este guard cada detección hacía un Navigator.pop()
  /// extra, sacando al usuario varias rutas atrás (lo que vaciaba el
  /// estado de la pantalla de factura).
  bool _yaDetectado = false;
  MobileScannerController? _controller;

  @override
  void initState() {
    super.initState();
    _controller = MobileScannerController(
      detectionSpeed: DetectionSpeed.normal,
      facing: CameraFacing.back,
    );
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text("Escanear"),
        actions: [
          IconButton(
            icon: const Icon(Icons.flash_on),
            tooltip: "Flash",
            onPressed: () => _controller?.toggleTorch(),
          ),
          IconButton(
            icon: const Icon(Icons.cameraswitch),
            tooltip: "Cambiar cámara",
            onPressed: () => _controller?.switchCamera(),
          ),
        ],
      ),
      body: MobileScanner(
        controller: _controller,
        onDetect: (capture) {
          // Guard: solo procesar la PRIMERA detección. MobileScanner emite
          // el mismo código repetidamente y sin esta protección se hacían
          // múltiples Navigator.pop, sacando al usuario fuera de la
          // pantalla que abrió el escáner.
          if (_yaDetectado) return;
          final barcodes = capture.barcodes;
          for (final barcode in barcodes) {
            final String? code = barcode.rawValue;
            if (code != null && code.isNotEmpty) {
              _yaDetectado = true;
              // Detener la cámara INMEDIATAMENTE para que no siga emitiendo
              _controller?.stop();
              widget.onDetect(code);
              if (mounted) Navigator.pop(context);
              return;
            }
          }
        }),
    );
  }
}

// ============================================================
//  CONSULTA RÁPIDA DE PRECIOS
//  Buscador ultrarápido por nombre/modelo/marca que muestra TODOS
//  los precios del producto en TODAS las listas a la vez. Ideal
//  para vendedores que necesitan dar precios al cliente sin abrir
//  cada lista individualmente.
// ============================================================
class VentanaConsultaRapidaPrecios extends StatefulWidget {
  const VentanaConsultaRapidaPrecios({super.key});
  @override State<VentanaConsultaRapidaPrecios> createState() =>
      _VentanaConsultaRapidaPreciosState();
}

class _VentanaConsultaRapidaPreciosState
    extends State<VentanaConsultaRapidaPrecios> {
  String _busqueda = "";
  final _searchCtrl = TextEditingController();
  String _filtroCategoria = "Todas";
  String _filtroMarca = "Todas";
  bool _cargando = true;

  @override
  void initState() {
    super.initState();
    _cargarDatos();
  }

  /// Trae el catálogo y las listas de precios del servidor.
  ///
  /// Esta pantalla leía `listasPreciosGlobal` pero nunca lo llenaba:
  /// si el usuario no había entrado antes a "Listas de precios", la
  /// consulta abría sin un solo precio y parecía rota.
  Future<void> _cargarDatos() async {
    if (mounted) setState(() => _cargando = true);
    try {
      // El catálogo va primero: `ListaPrecio.fromMap` resuelve cada
      // item contra `catalogoGlobal` y descarta los que no encuentra.
      if (catalogoGlobal.isEmpty) {
        final rawP = await _Api.get('productos');
        catalogoGlobal = ((rawP as List?) ?? [])
            .map((m) => Producto.fromMap(m as Map<String, dynamic>))
            .toList();
      }
      final raw = await _Api.get('listas_precios');
      if (raw is List) {
        listasPreciosGlobal = raw
            .map((m) => ListaPrecio.fromMap(m as Map<String, dynamic>))
            .toList();
      }
      // Las selecciones viejas se guardaban por nombre y dos listas
      // con nombres parecidos ("KRECE" y "KRECE.") caían en la misma
      // clave, así que destildar una no ocultaba nada. Recién acá,
      // con las listas del servidor en la mano, se puede saber a qué
      // id corresponde cada nombre guardado y pasar la selección a
      // ids. Es una sola vez por equipo.
      await ConfigSistema.migrarSeleccionConsultaRapidaAIds(
          listasPreciosGlobal);
    } catch (e) {
      debugPrint('[ConsultaRapida] Error cargando datos: $e');
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text('No se pudieron cargar los precios: $e'),
          backgroundColor: AppColors.statusRed));
      }
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  @override
  void dispose() {
    _searchCtrl.dispose();
    super.dispose();
  }

  /// Obtiene todos los productos únicos del catálogo (excluyendo
  /// subproductos/variantes — solo padres).
  List<Producto> _productosFiltrados() {
    final productos = catalogoGlobal.where((p) {
      if (p.esSubproducto) return false;
      if (_filtroCategoria != "Todas" && p.categoria != _filtroCategoria) {
        return false;
      }
      if (_filtroMarca != "Todas" &&
          p.marca.toLowerCase() != _filtroMarca.toLowerCase()) {
        return false;
      }
      if (_busqueda.isEmpty) return true;
      final q = _busqueda.toLowerCase();
      return p.nombre.toLowerCase().contains(q) ||
          p.marca.toLowerCase().contains(q) ||
          p.modelo.toLowerCase().contains(q) ||
          p.codigo.toLowerCase().contains(q);
    }).toList();
    productos.sort((a, b) {
      final m = a.marca.toLowerCase().compareTo(b.marca.toLowerCase());
      return m != 0 ? m : a.nombre.toLowerCase().compareTo(b.nombre.toLowerCase());
    });
    return productos;
  }

  /// ¿Este usuario puede elegir qué listas se muestran acá?
  ///
  /// Sólo el DUEÑO. Es una decisión comercial —qué precios se le
  /// pueden cantar a un cliente—, no una preferencia de cada
  /// vendedor. (El Maestro entra también porque es la cuenta de
  /// soporte, que pasa todos los controles del sistema.)
  bool get _puedeElegirListas {
    final rol = usuarioSesion?.rol;
    return rol == 'Dueño' || rol == 'Maestro';
  }

  /// true si esa lista está entre las que el dueño dejó visibles.
  static bool _listaEsVisible(ListaPrecio l) =>
      ConfigSistema.listaVisibleEnConsultaRapida(l);

  /// true si hay otra lista cargada cuyo nombre se confunde con el
  /// de ésta. Cuando pasa, al nombre se le agrega el número de lista
  /// para que el dueño sepa cuál está tildando.
  bool _nombreSeRepite(ListaPrecio l) {
    final clave = ConfigSistema.normalizarNombreLista(l.nombre);
    var cuantas = 0;
    for (final o in listasPreciosGlobal) {
      if (ConfigSistema.normalizarNombreLista(o.nombre) == clave) cuantas++;
    }
    return cuantas > 1;
  }

  /// Cómo se llama una lista en los carteles y en el selector.
  /// Si su nombre se repite, se le agrega el número para poder
  /// distinguirla ("KRECE #80" y "KRECE #82").
  String _etiquetaLista(ListaPrecio l) =>
      _nombreSeRepite(l) && l.id != null ? '${l.nombre} #${l.id}' : l.nombre;

  /// Nombres de las listas visibles, tal como se llaman hoy, para
  /// mostrárselos al usuario en los avisos.
  List<String> get _nombresListasVisibles => listasPreciosGlobal
      .where(_listaEsVisible)
      .map(_etiquetaLista)
      .toList();

  /// Abre el selector de listas. Sólo lo llama el dueño.
  Future<void> _elegirListasVisibles() async {
    // TODAS las listas cargadas, una fila por lista. Antes se
    // agrupaban por nombre, así que dos listas distintas con el
    // mismo nombre compartían un solo checkbox y era imposible
    // ocultar una sin la otra.
    final todas = [...listasPreciosGlobal];
    todas.sort((a, b) {
      final n = a.nombre.toLowerCase().compareTo(b.nombre.toLowerCase());
      return n != 0 ? n : (a.id ?? 0).compareTo(b.id ?? 0);
    });

    if (todas.isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text('Todavía no hay listas de precios cargadas'),
        backgroundColor: AppColors.statusOrange));
      return;
    }

    // Arrancamos con lo que hoy está visible (sea lo configurado o
    // el valor por defecto), para que el dueño vea el estado real.
    // Se marca por clave (el id), no por nombre.
    final marcadas = todas
        .where(_listaEsVisible)
        .map(ConfigSistema.claveConsultaRapida)
        .toSet();

    final guardar = await showDialog<bool>(
      context: context,
      builder: (ctx) => StatefulBuilder(builder: (ctx, setDlg) => AlertDialog(
        shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16)),
        title: const Row(children: [
          Icon(Icons.price_check, color: AppColors.royalBlue),
          SizedBox(width: 8),
          Expanded(child: Text('Precios que se muestran')),
        ]),
        content: SizedBox(
          width: 420,
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            const Align(
              alignment: Alignment.centerLeft,
              child: Text(
                  'Marcá las listas cuyos precios pueden verse en la '
                  'consulta rápida. Vale para todos los equipos.',
                  style: TextStyle(
                      fontSize: 12, color: AppColors.textSecondary)),
            ),
            const SizedBox(height: 8),
            Row(children: [
              TextButton.icon(
                icon: const Icon(Icons.select_all, size: 16),
                label: const Text('Todas', style: TextStyle(fontSize: 12)),
                onPressed: () => setDlg(() => marcadas
                  ..clear()
                  ..addAll(todas.map(ConfigSistema.claveConsultaRapida))),
              ),
              TextButton.icon(
                icon: const Icon(Icons.deselect, size: 16),
                label: const Text('Ninguna', style: TextStyle(fontSize: 12)),
                onPressed: () => setDlg(marcadas.clear),
              ),
            ]),
            const Divider(height: 1),
            Flexible(
              child: ListView(
                shrinkWrap: true,
                children: todas.map((lista) {
                  final clave = ConfigSistema.claveConsultaRapida(lista);
                  return CheckboxListTile(
                    dense: true,
                    controlAffinity: ListTileControlAffinity.leading,
                    value: marcadas.contains(clave),
                    // Con el número al lado cuando el nombre se
                    // repite: si no, dos filas idénticas y el dueño
                    // no sabe cuál está tildando.
                    title: Text(_etiquetaLista(lista),
                        style: const TextStyle(
                            fontSize: 13, fontWeight: FontWeight.w600)),
                    subtitle: Text(
                        '${lista.esEnBolivares ? "Bs" : "\$"}'
                        '${lista.esFinanciamiento ? " · ${lista.financiadora ?? "Financiamiento"}" : ""}'
                        ' · ${lista.items.length} producto'
                        '${lista.items.length == 1 ? "" : "s"}',
                        style: const TextStyle(fontSize: 11)),
                    onChanged: (v) => setDlg(() {
                      if (v == true) {
                        marcadas.add(clave);
                      } else {
                        marcadas.remove(clave);
                      }
                    }),
                  );
                }).toList(),
              ),
            ),
            if (marcadas.isEmpty)
              const Padding(
                padding: EdgeInsets.only(top: 8),
                child: Text(
                    'Sin ninguna marcada se vuelve a la selección de '
                    'fábrica: Divisas, De contado, Krece y Cashea.',
                    style: TextStyle(
                        fontSize: 11,
                        fontStyle: FontStyle.italic,
                        color: AppColors.statusOrange)),
              ),
          ]),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancelar')),
          ElevatedButton.icon(
            icon: const Icon(Icons.check, size: 18),
            label: const Text('Guardar'),
            onPressed: () => Navigator.pop(ctx, true),
          ),
        ],
      )),
    );

    if (guardar != true) return;
    final elegidas = todas
        .where((l) => marcadas.contains(ConfigSistema.claveConsultaRapida(l)))
        .toList();
    await ConfigSistema.guardarListasConsultaRapida(elegidas);
    if (!mounted) return;
    setState(() {});
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(elegidas.isEmpty
          ? 'Se volvió a la selección de fábrica'
          : 'Se mostrarán ${elegidas.length} lista'
            '${elegidas.length == 1 ? "" : "s"}: '
            '${elegidas.map(_etiquetaLista).join(", ")}'),
      backgroundColor: AppColors.statusGreen,
      duration: const Duration(seconds: 4)));
  }

  /// Para un producto dado, devuelve [(nombreLista, precio, moneda)]
  /// con los precios de las listas que el dueño dejó visibles.
  List<Map<String, dynamic>> _preciosDelProducto(Producto p) {
    final resultados = <Map<String, dynamic>>[];
    for (final lista in listasPreciosGlobal.where(_listaEsVisible)) {
      // Buscar el item del producto en esta lista
      final item = lista.items.firstWhere(
          (it) => it.producto.codigo == p.codigo,
          orElse: () => ItemListaPrecio(
              producto: p,
              stockDisponible: 0,
              preciosPorColumna: {}));
      if (item.preciosPorColumna.isEmpty) continue;
      for (final col in lista.columnas) {
        final precio = item.preciosPorColumna[col.nombre];
        if (precio == null || precio == 0) continue;
        resultados.add({
          'lista': lista.nombre,
          'columna': col.nombre,
          'precio': precio,
          'moneda': lista.esEnBolivares ? 'Bs' : '\$',
          'es_financ': lista.esFinanciamiento,
          'financiadora': lista.financiadora,
          // Condiciones DE ESTE producto: una lista puede tener un
          // % de inicial y unas cuotas distintas por marca o modelo.
          'inicial_pct': lista.pctInicialDe(item),
          'tiene_cuotas': lista.tieneCuotas,
          'n_cuotas': lista.cuotasDe(item),
        });
      }
    }
    return resultados;
  }

  @override
  Widget build(BuildContext context) {
    final productos = _productosFiltrados();
    final categorias = <String>{"Todas"};
    final marcas = <String>{"Todas"};
    for (final p in catalogoGlobal) {
      if (!p.esSubproducto) {
        categorias.add(p.categoria);
        if (p.marca.isNotEmpty) marcas.add(p.marca);
      }
    }

    return Scaffold(
      appBar: AppBar(
        title: const Text("Consulta Rápida de Precios"),
        backgroundColor: AppColors.royalBlue,
        foregroundColor: Colors.white,
        actions: [
          // Elegir qué listas se muestran: sólo el dueño.
          if (_puedeElegirListas)
            IconButton(
              icon: const Icon(Icons.price_check),
              tooltip: 'Elegir qué precios se muestran',
              onPressed: _elegirListasVisibles,
            ),
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: 'Actualizar precios',
            onPressed: _cargando ? null : _cargarDatos,
          ),
        ],
      ),
      body: Column(children: [
        // ── Barra de búsqueda y filtros ──
        Container(
          padding: const EdgeInsets.all(12),
          color: AppColors.surfaceGrey,
          child: Column(children: [
            TextField(
              controller: _searchCtrl,
              decoration: InputDecoration(
                hintText: "Buscar por nombre, marca, modelo, código...",
                prefixIcon: const Icon(Icons.search),
                suffixIcon: _busqueda.isEmpty ? null : IconButton(
                  icon: const Icon(Icons.clear),
                  onPressed: () {
                    _searchCtrl.clear();
                    setState(() => _busqueda = "");
                  }),
                border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(10)),
                isDense: true,
                fillColor: Colors.white,
                filled: true,
              ),
              onChanged: (v) => setState(() => _busqueda = v),
              autofocus: true,
            ),
            // Qué listas se están mostrando. Si no hay ninguna, avisa
            // (y al dueño le ofrece el atajo para elegirlas).
            Builder(builder: (_) {
              final visibles = _nombresListasVisibles;
              final hayVisibles = visibles.isNotEmpty;
              final color = hayVisibles
                  ? AppColors.royalBlue
                  : AppColors.statusOrange;
              return Padding(
                padding: const EdgeInsets.only(top: 8),
                child: Container(
                  width: double.infinity,
                  padding: const EdgeInsets.all(10),
                  decoration: BoxDecoration(
                    color: color.withValues(alpha: 0.09),
                    borderRadius: BorderRadius.circular(8),
                    border: Border.all(color: color.withValues(alpha: 0.4)),
                  ),
                  child: Row(children: [
                    Icon(
                        hayVisibles
                            ? Icons.price_check
                            : Icons.info_outline,
                        size: 16,
                        color: color),
                    const SizedBox(width: 6),
                    Expanded(
                      child: Text(
                        hayVisibles
                            ? 'Mostrando: ${visibles.join(" · ")}'
                            : 'Ninguna de las listas configuradas está '
                              'cargada todavía.',
                        style: TextStyle(fontSize: 11, color: color),
                      ),
                    ),
                    if (_puedeElegirListas)
                      InkWell(
                        onTap: _elegirListasVisibles,
                        child: Padding(
                          padding: const EdgeInsets.symmetric(horizontal: 4),
                          child: Text('Cambiar',
                              style: TextStyle(
                                  fontSize: 11,
                                  fontWeight: FontWeight.bold,
                                  color: color)),
                        ),
                      ),
                  ]),
                ),
              );
            }),
            const SizedBox(height: 8),
            Row(children: [
              Expanded(child: DropdownButtonFormField<String>(
                value: _filtroCategoria,
                isDense: true,
                decoration: const InputDecoration(
                  labelText: "Categoría",
                  border: OutlineInputBorder(),
                  isDense: true,
                  contentPadding: EdgeInsets.symmetric(horizontal: 10, vertical: 8),
                ),
                items: categorias.map((c) => DropdownMenuItem(
                    value: c, child: Text(c, style: const TextStyle(fontSize: 12)))).toList(),
                onChanged: (v) => setState(() => _filtroCategoria = v ?? "Todas"),
              )),
              const SizedBox(width: 8),
              Expanded(child: DropdownButtonFormField<String>(
                value: marcas.contains(_filtroMarca) ? _filtroMarca : "Todas",
                isDense: true,
                decoration: const InputDecoration(
                  labelText: "Marca",
                  border: OutlineInputBorder(),
                  isDense: true,
                  contentPadding: EdgeInsets.symmetric(horizontal: 10, vertical: 8),
                ),
                items: marcas.map((m) => DropdownMenuItem(
                    value: m, child: Text(m, style: const TextStyle(fontSize: 12)))).toList(),
                onChanged: (v) => setState(() => _filtroMarca = v ?? "Todas"),
              )),
            ]),
          ]),
        ),
        // ── Resultados ──
        Expanded(child: _cargando
            ? const Center(child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  CircularProgressIndicator(),
                  SizedBox(height: 12),
                  Text('Cargando precios...',
                      style: TextStyle(color: Colors.grey, fontSize: 13)),
                ]))
            : productos.isEmpty
            ? Center(child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Icon(_busqueda.isEmpty ? Icons.touch_app : Icons.search_off,
                      size: 64, color: Colors.grey[300]),
                  const SizedBox(height: 12),
                  Text(_busqueda.isEmpty
                      ? "Escribe para buscar un producto"
                      : "No se encontraron productos",
                      style: const TextStyle(color: Colors.grey, fontSize: 14)),
                ]))
            : ListView.builder(
                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                itemCount: productos.length,
                itemBuilder: (c, i) {
                  final p = productos[i];
                  final precios = _preciosDelProducto(p);
                  return Card(
                    margin: const EdgeInsets.symmetric(vertical: 4),
                    elevation: 1,
                    shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(10)),
                    child: ExpansionTile(
                      tilePadding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
                      childrenPadding: const EdgeInsets.fromLTRB(12, 0, 12, 12),
                      leading: CircleAvatar(
                        backgroundColor: AppColors.royalBlue.withValues(alpha: 0.12),
                        child: Text(p.marca.isNotEmpty
                            ? p.marca.substring(0, 1).toUpperCase()
                            : "?",
                            style: const TextStyle(
                                color: AppColors.royalBlue,
                                fontWeight: FontWeight.bold)),
                      ),
                      title: Text(p.nombre,
                          style: const TextStyle(fontWeight: FontWeight.bold,
                              fontSize: 14)),
                      subtitle: Text("${p.marca} · ${p.modelo} · "
                          "${precios.length} precio${precios.length == 1 ? '' : 's'}",
                          style: const TextStyle(fontSize: 11)),
                      children: precios.isEmpty
                          ? [
                              const Padding(
                                padding: EdgeInsets.all(8),
                                child: Text(
                                    "Sin precio en las listas que se "
                                    "están mostrando",
                                    style: TextStyle(
                                        color: Colors.grey,
                                        fontStyle: FontStyle.italic,
                                        fontSize: 12)),
                              )
                            ]
                          : precios.map((pr) {
                              final esFinanc = pr['es_financ'] as bool;
                              final precio = pr['precio'] as double;
                              final moneda = pr['moneda'] as String;
                              return Container(
                                margin: const EdgeInsets.symmetric(vertical: 3),
                                padding: const EdgeInsets.all(10),
                                decoration: BoxDecoration(
                                  color: esFinanc
                                      ? AppColors.royalBlue.withValues(alpha: 0.06)
                                      : Colors.grey[50],
                                  borderRadius: BorderRadius.circular(8),
                                  border: Border.all(
                                      color: esFinanc
                                          ? AppColors.royalBlue.withValues(alpha: 0.3)
                                          : Colors.grey[300]!,
                                      width: 1),
                                ),
                                child: Row(children: [
                                  Icon(
                                      esFinanc
                                          ? Icons.account_balance
                                          : (moneda == 'Bs'
                                              ? Icons.account_balance_wallet
                                              : Icons.attach_money),
                                      color: esFinanc
                                          ? AppColors.royalBlue
                                          : (moneda == 'Bs'
                                              ? Colors.green[700]
                                              : AppColors.statusOrange),
                                      size: 20),
                                  const SizedBox(width: 8),
                                  Expanded(child: Column(
                                      crossAxisAlignment: CrossAxisAlignment.start,
                                      children: [
                                        Text("${pr['lista']}",
                                            style: const TextStyle(
                                                fontSize: 13,
                                                fontWeight: FontWeight.bold)),
                                        if (esFinanc) ...[
                                          Text(
                                            "${pr['financiadora']} · "
                                            "Inicial ${pr['inicial_pct']}%"
                                            "${(pr['tiene_cuotas'] as bool) ? ' · ${pr['n_cuotas']} cuotas' : ' · sin cuotas'}",
                                            style: const TextStyle(
                                                fontSize: 10,
                                                color: AppColors.textSecondary)),
                                        ] else
                                          Text("${pr['columna']}",
                                              style: const TextStyle(
                                                  fontSize: 10,
                                                  color: AppColors.textSecondary)),
                                      ])),
                                  Text(
                                      moneda == 'Bs'
                                          ? "${precio.toStringAsFixed(2)} Bs"
                                          : "\$${precio.toStringAsFixed(2)}",
                                      style: TextStyle(
                                          fontSize: 16,
                                          fontWeight: FontWeight.bold,
                                          color: esFinanc
                                              ? AppColors.royalBlue
                                              : Colors.black87)),
                                ]),
                              );
                            }).toList(),
                    ),
                  );
                })),
      ]),
    );
  }
}

// ============================================================
//  LISTAS DE PRECIOS
// ============================================================
class VentanaListasPrecios extends StatefulWidget {
  const VentanaListasPrecios({super.key});
  @override State<VentanaListasPrecios> createState() => _VentanaListasPreciosState();
}

class _VentanaListasPreciosState extends State<VentanaListasPrecios> {
  bool _cargando = true;

  /// Timer que recarga periódicamente las listas desde el servidor.
  /// Cuando el administrador edita una lista en su dispositivo, el resto
  /// de las sesiones abiertas la verán refrescada en máximo 10 segundos.
  Timer? _timerSync;

  /// Hash simple de la versión del servidor para detectar cambios y
  /// evitar setState innecesarios cuando no hubo modificaciones.
  String _ultimoHashServidor = '';

  @override
  void initState() {
    super.initState();
    _cargarDesdeServidor();
    // Auto-sincronización: cada 10 segundos pregunta al servidor por
    // las listas y, si hay cambios, refresca la pantalla de TODOS los
    // usuarios sin importar qué dispositivo hizo el cambio.
    _timerSync = Timer.periodic(const Duration(seconds: 10), (_) {
      if (!mounted) {
        _timerSync?.cancel();
        return;
      }
      _cargarDesdeServidor(silencioso: true);
    });
  }

  @override
  void dispose() {
    _timerSync?.cancel();
    super.dispose();
  }

  /// Carga las listas desde el backend.
  /// `silencioso=true` evita el spinner — usado por el polling para que
  /// no parpadee la UI.
  Future<void> _cargarDesdeServidor({bool silencioso = false}) async {
    if (!silencioso && mounted) setState(() => _cargando = true);
    try {
      final raw = await _Api.get('listas_precios');
      if (raw is List) {
        // Hash PROFUNDO: incluye precios, %, items, financiadora.
        // Antes solo se hashaba id+nombre+fecha_creacion → el polling
        // NO detectaba ediciones de precios hechas por otros usuarios
        // (porque esos campos no cambiaban). Ahora el hash captura el
        // CONTENIDO COMPLETO de cada lista para que cualquier cambio
        // en otro dispositivo se vea en tiempo real.
        final nuevoHash = StringBuffer();
        nuevoHash.write('${raw.length}|');
        for (final m in raw) {
          if (m is! Map) continue;
          nuevoHash
            ..write('${m['id']}-')
            ..write('${m['nombre']}-')
            ..write('${m['porcentaje_adicional']}-')
            ..write('${m['porcentaje_inicial']}-')
            ..write('${m['porcentaje_recargo_cuotas']}-')
            ..write('${m['numero_cuotas']}-')
            ..write('${m['tiene_cuotas']}-')
            ..write('${m['financiadora']}-')
            ..write('${m['tasa_del_dia']}-');
          // Hash de los items: código + valores (incluye precios e
          // overrides manuales de inicial/cuota)
          if (m['items'] is List) {
            for (final it in (m['items'] as List)) {
              if (it is! Map) continue;
              nuevoHash.write('${it['producto_codigo']}:');
              if (it['valores'] is List) {
                for (final v in (it['valores'] as List)) {
                  if (v is! Map) continue;
                  nuevoHash
                    ..write('${v['columna_nombre']}=')
                    ..write('${v['precio']},');
                }
              }
              nuevoHash.write(';');
            }
          }
          nuevoHash.write('|');
        }
        final nuevoHashStr = nuevoHash.toString();
        if (nuevoHashStr == _ultimoHashServidor) {
          if (!silencioso && mounted) setState(() => _cargando = false);
          return;
        }
        _ultimoHashServidor = nuevoHashStr;
        listasPreciosGlobal = raw
            .map((m) => ListaPrecio.fromMap(m as Map<String, dynamic>))
            .toList();
        if (mounted) setState(() {});
      }
    } catch (e) {
      debugPrint('[ListasPrecios] Error al cargar: $e');
    } finally {
      if (!silencioso && mounted) setState(() => _cargando = false);
    }
  }

  /// Persiste una lista al backend (solo metadatos, sin re-poblar
  /// productos). Usado por _editarLista cuando solo se cambian
  /// nombre, %, número de cuotas, financiadora, etc.
  Future<void> _guardarListaEnBackend(ListaPrecio lista) async {
    try {
      if (lista.id != null) {
        await _Api.put('listas_precios', lista.id.toString(),
            lista.toMap());
      } else {
        final resp = await _Api.post('listas_precios', lista.toMap());
        if (resp is Map && resp['id'] != null) {
          lista.id = resp['id'] is int
              ? resp['id']
              : int.tryParse(resp['id'].toString());
        }
      }
    } catch (e) {
      debugPrint('[ListaPrecio] Error persistiendo: $e');
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text('Error guardando: $e'),
          backgroundColor: Colors.orange));
      }
    }
  }

  /// Re-puebla la lista (productos del catálogo + tasa actual) y la
  /// PERSISTE en el backend. Antes el "Actualizar" sólo cambiaba la
  /// memoria local del admin: otros usuarios nunca veían los cambios.
  Future<void> _actualizarListaYPersistir(ListaPrecio lista) async {
    // 1) Re-poblar localmente
    setState(() => _poblarLista(lista));
    // 2) Persistir en BD: si ya tiene id, hacemos PUT; si no, POST.
    try {
      if (lista.id != null) {
        await _Api.put('listas_precios', lista.id.toString(), lista.toMap());
      } else {
        final resp = await _Api.post('listas_precios', lista.toMap());
        if (resp is Map && resp['id'] != null) {
          lista.id = resp['id'] is int
              ? resp['id']
              : int.tryParse(resp['id'].toString());
        }
      }
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text('✅ ${lista.items.length} productos actualizados '
              'y sincronizados con todos los usuarios'),
          backgroundColor: AppColors.statusGreen));
      }
      // Forzar siguiente refresh para los demás dispositivos
      _ultimoHashServidor = '';
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text('Error al guardar en servidor: $e'),
          backgroundColor: AppColors.statusRed));
      }
    }
  }

  /// Elimina la lista en backend y local. Antes sólo borraba en memoria,
  /// así que reaparecía al recargar y los otros usuarios la seguían viendo.
  Future<void> _eliminarListaYPersistir(ListaPrecio lista) async {
    try {
      if (lista.id != null) {
        await _Api.delete('listas_precios', lista.id!.toString());
      }
      if (mounted) {
        setState(() => listasPreciosGlobal.remove(lista));
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text('Lista "${lista.nombre}" eliminada'),
          backgroundColor: AppColors.statusGreen));
      }
      _ultimoHashServidor = '';
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text('Error al eliminar: $e'),
          backgroundColor: AppColors.statusRed));
      }
    }
  }

  // ── Lógica de auto-población ─────────────────────────────────
  /// Puebla los ítems de la lista automáticamente según su categoría y marca.
  /// Agrupa por marca+modelo, calcula el precio según la moneda y agrega
  /// una columna "Precio Venta" predeterminada con el stock disponible.
  /// Pobla o actualiza una lista con productos del catálogo.
  ///
  /// COMPORTAMIENTO INTELIGENTE (preserva trabajo del admin):
  ///   1. Productos NUEVOS en el catálogo → se agregan con precio
  ///      calculado del catálogo (precioVenta × factor × tasa).
  ///   2. Productos que YA estaban en la lista → SE PRESERVAN sus
  ///      precios manuales editados. NO se sobrescriben.
  ///   3. Productos eliminados del catálogo → se quitan de la lista.
  ///   4. Solo se actualiza el `stockDisponible` (info de stock).
  ///
  /// Esto evita que el admin pierda horas de trabajo editando precios
  /// solo porque pulsó "Actualizar" en la lista.
  void _poblarLista(ListaPrecio lista) {
    // Calcular tasa a usar (BCV si está disponible)
    final tasa = lista.esEnBolivares
        ? (ConfigSistema.tasaCambio > 0 ? ConfigSistema.tasaCambio : lista.tasaDelDia)
        : 1.0;

    // Filtrar productos según categoría y marca
    // PUNTO 2: Excluir subproductos (variantes) — solo productos padre.
    final productosFiltrados = catalogoGlobal.where((p) {
      if (p.esSubproducto) return false; // NO tomar subproductos/variantes
      final coincideCategoria = lista.categoria == "Todos" || p.categoria == lista.categoria;
      final coincideMarca = lista.marcaFiltro == "Todas" ||
          p.marca.toLowerCase() == lista.marcaFiltro.toLowerCase();
      return coincideCategoria && coincideMarca;
    }).toList();

    // Ordenar por marca → modelo
    productosFiltrados.sort((a, b) {
      final marcaCmp = a.marca.toLowerCase().compareTo(b.marca.toLowerCase());
      return marcaCmp != 0 ? marcaCmp : a.nombre.toLowerCase().compareTo(b.nombre.toLowerCase());
    });

    // Crear columna por defecto si la lista está vacía de columnas
    if (lista.columnas.isEmpty) {
      lista.columnas.add(ColumnaPrecio(nombre: lista.esEnBolivares ? "Precio (Bs)" : "Precio (\$)"));
    }

    // ── Indexar items existentes por código de producto ──
    // Esto nos permite RECONOCER productos que ya estaban en la lista
    // y conservar sus precios/configuraciones manuales.
    final existentes = <String, ItemListaPrecio>{};
    for (final it in lista.items) {
      existentes[it.producto.codigo] = it;
    }

    final nuevaListaItems = <ItemListaPrecio>[];
    int agregados = 0;
    int preservados = 0;

    for (final p in productosFiltrados) {
      // Calcular stock disponible real (siempre actualizado del catálogo)
      int stock;
      if (CategoriasProductos.usaIMEI(p.categoria)) {
        final imeisPropios = stockImeiGlobal.where(
            (i) => i.producto.codigo == p.codigo && !i.vendido).length;
        final variantes = catalogoGlobal.where(
            (x) => x.productoPadreCodigo == p.codigo).map((v) => v.codigo).toList();
        final imeisVariantes = stockImeiGlobal.where(
            (i) => variantes.contains(i.producto.codigo) && !i.vendido).length;
        stock = imeisPropios + imeisVariantes;
      } else {
        final stockVariantes = catalogoGlobal
            .where((x) => x.productoPadreCodigo == p.codigo)
            .fold<int>(0, (s, v) => s + v.stockManual);
        stock = p.stockManual + stockVariantes;
      }

      // ── ¿El producto ya estaba en la lista? ──
      final itemExistente = existentes[p.codigo];
      if (itemExistente != null) {
        // PRESERVAR: el admin pudo haber editado precios e iniciales
        // manuales. Solo actualizamos el stock (info, no precio).
        itemExistente.stockDisponible = stock;
        // Asegurar que tenga TODAS las columnas actuales (por si se
        // agregó una columna nueva). Las columnas nuevas reciben el
        // precio calculado por defecto; las existentes se preservan.
        final factorAdicional = 1 + (lista.porcentajeAdicional / 100);
        // Cálculo EXACTO en 2 pasos (USD redondeado → Bs redondeado)
        final precioUsdConMargen = redondearPrecio(p.precioVenta * factorAdicional);
        final precioPorDefecto = lista.esEnBolivares
            ? redondearPrecio(precioUsdConMargen * tasa)
            : precioUsdConMargen;
        for (final col in lista.columnas) {
          itemExistente.preciosPorColumna.putIfAbsent(
              col.nombre, () => precioPorDefecto);
        }
        nuevaListaItems.add(itemExistente);
        preservados++;
      } else {
        // NUEVO: producto que no estaba en la lista → agregar con
        // precio calculado del catálogo. Mismo cálculo exacto.
        final factorAdicional = 1 + (lista.porcentajeAdicional / 100);
        final precioUsdConMargen = redondearPrecio(p.precioVenta * factorAdicional);
        final precioBase = lista.esEnBolivares
            ? redondearPrecio(precioUsdConMargen * tasa)
            : precioUsdConMargen;

        nuevaListaItems.add(ItemListaPrecio(
          producto: p,
          stockDisponible: stock,
          preciosPorColumna: {
            for (var col in lista.columnas) col.nombre: precioBase
          },
        ));
        agregados++;
      }
    }

    // Reemplazar la lista — esto AUTOMÁTICAMENTE elimina productos
    // que ya no están en el catálogo (no se incluyeron en el bucle).
    final eliminados = lista.items.length - preservados;
    lista.items
      ..clear()
      ..addAll(nuevaListaItems);

    debugPrint('[_poblarLista] ${lista.nombre}: '
        '$preservados preservados, $agregados nuevos, '
        '$eliminados eliminados');
  }

  // ── Diálogo de creación ───────────────────────────────────────
  /// Edita la configuración de una lista existente (nombre, %,
  /// número de cuotas, financiadora, etc.) SIN borrar los precios
  /// ni los productos ya guardados. Después de guardar, persiste
  /// al backend para que el cambio se vea en todos los dispositivos.
  void _editarLista(ListaPrecio lista) {
    final nombreCtrl = TextEditingController(text: lista.nombre);
    final tasaCtrl = TextEditingController(
        text: lista.tasaDelDia.toStringAsFixed(2));
    final pctAdicionalCtrl = TextEditingController(
        text: lista.porcentajeAdicional.toString());
    final financiadoraCtrl = TextEditingController(
        text: lista.financiadora ?? '');
    final pctInicialCtrl = TextEditingController(
        text: lista.porcentajeInicial.toString());
    final cuotasCtrl = TextEditingController(
        text: lista.numeroCuotas.toString());
    final pctComisionWeppaCtrl = TextEditingController(
        text: lista.porcentajeComisionWeppa.toString());
    final pctRecargoCuotasCtrl = TextEditingController(
        text: lista.porcentajeRecargoCuotas.toString());
    bool esBs = lista.esEnBolivares;
    bool esFinanc = lista.esFinanciamiento;
    bool tieneCuotas = lista.tieneCuotas;

    showDialog(context: context, builder: (ctx) => StatefulBuilder(
      builder: (ctx, setDlg) => AlertDialog(
        shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16)),
        title: Row(children: const [
          Icon(Icons.edit_note, color: AppColors.statusOrange),
          SizedBox(width: 8),
          Text("Editar Lista"),
        ]),
        content: SizedBox(
          width: 450,
          child: SingleChildScrollView(
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              TextField(
                controller: nombreCtrl,
                decoration: const InputDecoration(
                  labelText: "Nombre de la lista",
                  prefixIcon: Icon(Icons.label),
                  border: OutlineInputBorder(),
                  isDense: true),
              ),
              const SizedBox(height: 10),
              // ── Toggle moneda ──
              Row(children: [
                Expanded(child: SwitchListTile(
                  dense: true,
                  contentPadding: EdgeInsets.zero,
                  title: Text(esBs ? "En Bolívares" : "En Divisas (USD)",
                      style: const TextStyle(fontSize: 13)),
                  subtitle: Text(esBs
                      ? "Tasa: ${tasaCtrl.text}"
                      : "Precios en dólares",
                      style: const TextStyle(fontSize: 10)),
                  value: esBs,
                  activeColor: Colors.green,
                  onChanged: (v) => setDlg(() => esBs = v),
                )),
              ]),
              if (esBs) ...[
                const SizedBox(height: 8),
                TextField(
                  controller: tasaCtrl,
                  keyboardType: const TextInputType.numberWithOptions(decimal: true),
                  decoration: const InputDecoration(
                    labelText: "Tasa del día (Bs por USD)",
                    prefixIcon: Icon(Icons.currency_exchange),
                    border: OutlineInputBorder(),
                    isDense: true),
                ),
              ],
              const SizedBox(height: 10),
              // ── % adicional ──
              TextField(
                controller: pctAdicionalCtrl,
                keyboardType: const TextInputType.numberWithOptions(decimal: true),
                decoration: const InputDecoration(
                  labelText: "% adicional sobre el precio base",
                  hintText: "Ej: 15",
                  prefixIcon: Icon(Icons.trending_up),
                  border: OutlineInputBorder(),
                  isDense: true,
                  helperText: "Este % se aplica al precio venta. "
                    "Ejemplo: precio \$100 + 15% = \$115",
                  helperMaxLines: 2),
              ),
              const SizedBox(height: 12),
              // ── Toggle financiamiento ──
              Container(
                decoration: BoxDecoration(
                  color: esFinanc
                      ? AppColors.royalBlue.withValues(alpha: 0.06)
                      : Colors.grey[100],
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(
                      color: esFinanc
                          ? AppColors.royalBlue.withValues(alpha: 0.4)
                          : Colors.grey[300]!),
                ),
                child: SwitchListTile(
                  dense: true,
                  title: const Text("Lista de Financiamiento",
                      style: TextStyle(fontSize: 13, fontWeight: FontWeight.w600)),
                  value: esFinanc,
                  activeColor: AppColors.royalBlue,
                  onChanged: (v) => setDlg(() => esFinanc = v),
                ),
              ),
              if (esFinanc) ...[
                const SizedBox(height: 10),
                TextField(
                  controller: financiadoraCtrl,
                  decoration: const InputDecoration(
                    labelText: "Nombre de la financiadora",
                    hintText: "Cashea / Weppa / Krece",
                    prefixIcon: Icon(Icons.account_balance),
                    border: OutlineInputBorder(),
                    isDense: true),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: pctInicialCtrl,
                  keyboardType: const TextInputType.numberWithOptions(decimal: true),
                  decoration: const InputDecoration(
                    labelText: "% Inicial",
                    hintText: "Ej: 36",
                    prefixIcon: Icon(Icons.percent),
                    border: OutlineInputBorder(),
                    isDense: true),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: pctComisionWeppaCtrl,
                  keyboardType: const TextInputType.numberWithOptions(decimal: true),
                  decoration: const InputDecoration(
                    labelText: "% comisión (Weppa) — opcional",
                    prefixIcon: Icon(Icons.handshake),
                    border: OutlineInputBorder(),
                    isDense: true),
                ),
                const SizedBox(height: 10),
                Container(
                  decoration: BoxDecoration(
                    color: tieneCuotas
                        ? AppColors.statusGreen.withValues(alpha: 0.06)
                        : Colors.grey[100],
                    borderRadius: BorderRadius.circular(8),
                    border: Border.all(
                        color: tieneCuotas
                            ? AppColors.statusGreen.withValues(alpha: 0.4)
                            : Colors.grey[300]!),
                  ),
                  child: SwitchListTile(
                    dense: true,
                    title: const Text("¿Maneja cuotas?",
                        style: TextStyle(fontSize: 13, fontWeight: FontWeight.w600)),
                    value: tieneCuotas,
                    activeColor: AppColors.statusGreen,
                    onChanged: (v) => setDlg(() => tieneCuotas = v),
                  ),
                ),
                if (tieneCuotas) ...[
                  const SizedBox(height: 10),
                  TextField(
                    controller: cuotasCtrl,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(
                      labelText: "Número de cuotas",
                      prefixIcon: Icon(Icons.calendar_month),
                      border: OutlineInputBorder(),
                      isDense: true),
                  ),
                  const SizedBox(height: 10),
                  TextField(
                    controller: pctRecargoCuotasCtrl,
                    keyboardType: const TextInputType.numberWithOptions(decimal: true),
                    decoration: const InputDecoration(
                      labelText: "% recargo sobre las cuotas",
                      hintText: "Ej: 20",
                      prefixIcon: Icon(Icons.trending_up),
                      border: OutlineInputBorder(),
                      isDense: true),
                  ),
                ],
                const SizedBox(height: 12),
                // Los valores de arriba son los GENERALES de la lista.
                // Acá se les ponen condiciones propias a marcas o
                // modelos puntuales (30% en Samsung, 40% en Apple)
                // sin tener que armar una lista por cada combinación.
                SizedBox(
                  width: double.infinity,
                  child: OutlinedButton.icon(
                    icon: const Icon(Icons.tune, size: 18),
                    label: const Text(
                        "Inicial y cuotas por marca o modelo",
                        style: TextStyle(fontSize: 13)),
                    style: OutlinedButton.styleFrom(
                        foregroundColor: AppColors.royalBlue,
                        padding: const EdgeInsets.symmetric(vertical: 12)),
                    onPressed: () async {
                      final cambio =
                          await ajustarCondicionesPorMarcaModelo(ctx, lista);
                      if (!cambio) return;
                      await _guardarListaEnBackend(lista);
                      if (!mounted) return;
                      setState(() {});
                      setDlg(() {});
                    },
                  ),
                ),
              ],
            ]),
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text("Cancelar")),
          ElevatedButton.icon(
            icon: const Icon(Icons.save),
            label: const Text("Guardar"),
            onPressed: () async {
              // Actualizar todos los campos en el objeto existente
              lista.nombre = nombreCtrl.text.trim().isEmpty
                  ? lista.nombre
                  : nombreCtrl.text.trim();
              lista.esEnBolivares = esBs;
              lista.tasaDelDia =
                  double.tryParse(tasaCtrl.text) ?? lista.tasaDelDia;
              lista.porcentajeAdicional =
                  double.tryParse(pctAdicionalCtrl.text) ?? 0.0;
              lista.esFinanciamiento = esFinanc;
              if (esFinanc) {
                lista.financiadora = financiadoraCtrl.text.trim().isEmpty
                    ? null
                    : financiadoraCtrl.text.trim();
                lista.porcentajeInicial =
                    double.tryParse(pctInicialCtrl.text) ?? 0.0;
                // ── Detectar cambio del número de cuotas ──
                // Si el usuario editó las cuotas (por ejemplo de 8 → 6),
                // el `cuotaManual` de cada item quedó "pegado" con el
                // monto calculado antes (150). Sin limpiarlo, la lista
                // seguiría mostrando 150 por cuota aunque ahora sean 6.
                // Al limpiar cuotaManual e inicialManual, el sistema
                // los recalcula al vuelo con el nuevo divisor.
                final nuevoNumeroCuotas =
                    int.tryParse(cuotasCtrl.text) ?? lista.numeroCuotas;
                final cambiaronCuotas = nuevoNumeroCuotas != lista.numeroCuotas;
                lista.numeroCuotas = nuevoNumeroCuotas;
                lista.porcentajeComisionWeppa =
                    double.tryParse(pctComisionWeppaCtrl.text) ?? 0.0;
                lista.porcentajeRecargoCuotas =
                    double.tryParse(pctRecargoCuotasCtrl.text) ?? 0.0;
                lista.tieneCuotas = tieneCuotas;
                if (cambiaronCuotas) {
                  for (final it in lista.items) {
                    it.cuotaManual   = null;
                    it.inicialManual = null;
                  }
                  debugPrint('[EditarLista] Cuotas cambiaron a '
                      '$nuevoNumeroCuotas — se limpiaron ${lista.items.length} '
                      'overrides manuales para recalcular al vuelo');
                }
              } else {
                lista.financiadora = null;
              }
              Navigator.pop(ctx);
              // Persistir el cambio al backend (multidispositivo)
              await _guardarListaEnBackend(lista);
              if (mounted) {
                setState(() {});
                ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                  content: Text("Lista \"${lista.nombre}\" actualizada"),
                  backgroundColor: AppColors.statusGreen));
              }
            },
          ),
        ],
      ),
    ));
  }

  void _crearNuevaLista() {
    final nombreCtrl      = TextEditingController();
    final tasaCtrl        = TextEditingController(text: ConfigSistema.tasaCambio.toStringAsFixed(2));
    final pctAdicionalCtrl = TextEditingController(text: "0");    // % adicional al precio
    final financiadoraCtrl = TextEditingController();
    final pctInicialCtrl   = TextEditingController(text: "0");   // % para la inicial
    final cuotasCtrl       = TextEditingController(text: "12");  // número de cuotas
    final pctComisionWeppaCtrl = TextEditingController(text: "0"); // % comisión Weppa
    final pctRecargoCuotasCtrl = TextEditingController(text: "0"); // % recargo sobre cuotas
    String categoria    = "Telefono";
    String marcaFiltro  = "Todas";
    bool esBs           = false;
    bool esFinanc       = false;  // ¿Es lista de financiamiento?
    bool tieneCuotas    = true;   // ¿La financiadora maneja cuotas?

    List<String> _marcasDisponibles(String cat) {
      final marcas = catalogoGlobal
          .where((p) => cat == "Todos" || p.categoria == cat)
          .map((p) => p.marca.trim())
          .where((m) => m.isNotEmpty)
          .toSet()
          .toList()..sort();
      return ["Todas", ...marcas];
    }

    final categorias = ["Telefono", "Accesorio", "Televisor", "Linea Blanca", "Linea", "Todos"];

    showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setDlg) {
          final marcas = _marcasDisponibles(categoria);
          if (!marcas.contains(marcaFiltro)) marcaFiltro = "Todas";

          return AlertDialog(
            title: const Row(children: [
              Icon(Icons.playlist_add, color: AppColors.royalBlue),
              SizedBox(width: 8),
              Text("Nueva Lista de Precios"),
            ]),
            content: SingleChildScrollView(child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // Nombre
                TextField(
                  controller: nombreCtrl,
                  decoration: const InputDecoration(
                    labelText: "Nombre de la lista",
                    prefixIcon: Icon(Icons.label_outline)),
                ),
                const SizedBox(height: 16),

                // Categoría
                const Text("Categoría de productos",
                  style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13)),
                const SizedBox(height: 6),
                Wrap(spacing: 8, runSpacing: 6, children: categorias.map((cat) {
                  final selected = categoria == cat;
                  return ChoiceChip(
                    avatar: Icon(_iconoCategoria(cat), size: 16,
                      color: selected ? Colors.white : AppColors.royalBlue),
                    label: Text(cat),
                    selected: selected,
                    selectedColor: AppColors.primaryBlue,
                    labelStyle: TextStyle(
                      color: selected ? Colors.white : Colors.black87,
                      fontWeight: selected ? FontWeight.bold : FontWeight.normal),
                    onSelected: (_) => setDlg(() { categoria = cat; marcaFiltro = "Todas"; }),
                  );
                }).toList()),
                const SizedBox(height: 14),

                // Filtro de marca
                DropdownButtonFormField<String>(
                  value: marcaFiltro,
                  decoration: const InputDecoration(
                    labelText: "Filtrar por marca",
                    prefixIcon: Icon(Icons.filter_list)),
                  items: marcas.map((m) =>
                    DropdownMenuItem(value: m, child: Text(m))).toList(),
                  onChanged: (v) => setDlg(() => marcaFiltro = v ?? "Todas"),
                ),
                const SizedBox(height: 14),

                // Moneda
                Container(
                  decoration: BoxDecoration(
                    color: Colors.grey[100],
                    borderRadius: BorderRadius.circular(8),
                    border: Border.all(color: Colors.grey[300]!)),
                  child: SwitchListTile(
                    title: const Text("Lista en Bolívares"),
                    subtitle: Text(esBs ? "Se usará la tasa BCV" : "Precios en dólares (\$)"),
                    value: esBs,
                    activeColor: AppColors.primaryBlue,
                    onChanged: (v) => setDlg(() => esBs = v),
                  ),
                ),
                if (esBs) ...[
                  const SizedBox(height: 12),
                  TextField(
                    controller: tasaCtrl,
                    keyboardType: const TextInputType.numberWithOptions(decimal: true),
                    decoration: InputDecoration(
                      labelText: "Tasa Bs/\$",
                      prefixIcon: const Icon(Icons.currency_exchange),
                      helperText: TasaBCVScheduler.ultimaTasa != null
                          ? "BCV hoy: ${TasaBCVScheduler.ultimaTasa!.valorFormateado}"
                          : null),
                  ),
                ],
                const SizedBox(height: 14),

                // ── Porcentaje adicional ──────────────────────────
                Container(
                  padding: const EdgeInsets.all(12),
                  decoration: BoxDecoration(
                    color: AppColors.primaryBlue.withValues(alpha: 0.05),
                    borderRadius: BorderRadius.circular(8),
                    border: Border.all(
                      color: AppColors.primaryBlue.withValues(alpha: 0.2))),
                  child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    const Text("% Adicional sobre precio de venta",
                      style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13)),
                    const Text("Se suma al precio de venta de cada equipo en esta lista",
                      style: TextStyle(fontSize: 11, color: AppColors.textSecondary)),
                    const SizedBox(height: 8),
                    TextField(
                      controller: pctAdicionalCtrl,
                      keyboardType: const TextInputType.numberWithOptions(decimal: true),
                      decoration: const InputDecoration(
                        labelText: "Porcentaje adicional (%)",
                        prefixIcon: Icon(Icons.percent), isDense: true,
                        helperText: "0 = sin porcentaje adicional"),
                    ),
                  ]),
                ),
                const SizedBox(height: 14),

                // ── ¿Es lista de financiamiento? ──────────────────
                Container(
                  decoration: BoxDecoration(
                    color: esFinanc
                      ? AppColors.royalBlue.withValues(alpha: 0.05)
                      : Colors.grey[100],
                    borderRadius: BorderRadius.circular(8),
                    border: Border.all(
                      color: esFinanc
                        ? AppColors.royalBlue.withValues(alpha: 0.3)
                        : Colors.grey[300]!)),
                  child: SwitchListTile(
                    title: const Text("Lista de Financiamiento"),
                    subtitle: const Text("Activa campos de financiadora, inicial y cuotas"),
                    value: esFinanc,
                    activeColor: AppColors.royalBlue,
                    onChanged: (v) => setDlg(() => esFinanc = v),
                  ),
                ),
                if (esFinanc) ...[
                  const SizedBox(height: 12),
                  TextField(
                    controller: financiadoraCtrl,
                    onChanged: (_) => setDlg(() {}),
                    decoration: const InputDecoration(
                      labelText: "Nombre de la financiadora *",
                      prefixIcon: Icon(Icons.account_balance_outlined),
                      border: OutlineInputBorder()),
                  ),
                  const SizedBox(height: 10),
                  Row(children: [
                    Expanded(child: TextField(
                      controller: pctAdicionalCtrl,
                      keyboardType: const TextInputType.numberWithOptions(decimal: true),
                      decoration: const InputDecoration(
                        labelText: "% adicional al precio base",
                        prefixIcon: Icon(Icons.add_chart),
                        border: OutlineInputBorder(), isDense: true),
                    )),
                    const SizedBox(width: 10),
                    Expanded(child: TextField(
                      controller: pctInicialCtrl,
                      keyboardType: const TextInputType.numberWithOptions(decimal: true),
                      decoration: const InputDecoration(
                        labelText: "% para inicial",
                        prefixIcon: Icon(Icons.percent),
                        border: OutlineInputBorder(), isDense: true),
                    )),
                  ]),
                  const SizedBox(height: 10),
                  // ── Toggle: ¿la financiadora maneja cuotas? ──
                  // Algunas financiadoras pagan a la tienda y se
                  // encargan ellas mismas del cobro al cliente,
                  // sin que la tienda deba mostrar cuotas.
                  Container(
                    decoration: BoxDecoration(
                      color: tieneCuotas
                        ? AppColors.statusGreen.withValues(alpha: 0.06)
                        : Colors.grey[100],
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(
                        color: tieneCuotas
                          ? AppColors.statusGreen.withValues(alpha: 0.4)
                          : Colors.grey[300]!),
                    ),
                    child: SwitchListTile(
                      dense: true,
                      title: const Text("¿Maneja cuotas?",
                        style: TextStyle(fontSize: 13,
                          fontWeight: FontWeight.w600)),
                      subtitle: Text(
                        tieneCuotas
                          ? "Sí — se mostrarán cuotas al cliente"
                          : "No — solo inicial, sin cuotas visibles",
                        style: const TextStyle(fontSize: 11)),
                      value: tieneCuotas,
                      activeColor: AppColors.statusGreen,
                      onChanged: (v) => setDlg(() => tieneCuotas = v),
                    ),
                  ),
                  // Los campos de cuotas SOLO aparecen si tieneCuotas==true
                  if (tieneCuotas) ...[
                  const SizedBox(height: 10),
                  TextField(
                    controller: cuotasCtrl,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(
                      labelText: "Número de cuotas",
                      prefixIcon: Icon(Icons.calendar_month),
                      border: OutlineInputBorder(), isDense: true),
                  ),
                  const SizedBox(height: 10),
                  // ── % Recargo sobre las cuotas ──
                  // Se aplica al monto total (precio - inicial) antes de
                  // dividirlo entre el número de cuotas. Útil para añadir
                  // intereses, gastos administrativos o cualquier
                  // margen adicional al financiamiento.
                  TextField(
                    controller: pctRecargoCuotasCtrl,
                    keyboardType: const TextInputType.numberWithOptions(decimal: true),
                    decoration: const InputDecoration(
                      labelText: "% recargo sobre las cuotas",
                      hintText: "Ej: 20",
                      prefixIcon: Icon(Icons.trending_up),
                      helperText: "Se aplica al total a financiar antes de dividir entre cuotas",
                      helperMaxLines: 2,
                      border: OutlineInputBorder(), isDense: true),
                  ),
                  ],
                  // ── % Comisión Weppa (solo visible si la financiadora es Weppa) ──
                  if (financiadoraCtrl.text.trim().toLowerCase().contains('weppa')) ...[
                    const SizedBox(height: 10),
                    Container(
                      padding: const EdgeInsets.all(10),
                      decoration: BoxDecoration(
                        color: AppColors.statusGreen.withValues(alpha: 0.06),
                        borderRadius: BorderRadius.circular(8),
                        border: Border.all(
                            color: AppColors.statusGreen.withValues(alpha: 0.4)),
                      ),
                      child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(children: const [
                              Icon(Icons.percent,
                                  size: 16, color: AppColors.statusGreen),
                              SizedBox(width: 6),
                              Text('Comisión Weppa',
                                  style: TextStyle(
                                      fontSize: 12,
                                      fontWeight: FontWeight.bold,
                                      color: AppColors.statusGreen)),
                            ]),
                            const SizedBox(height: 8),
                            TextField(
                              controller: pctComisionWeppaCtrl,
                              keyboardType:
                                  const TextInputType.numberWithOptions(
                                      decimal: true),
                              decoration: const InputDecoration(
                                labelText: '% de comisión sobre precio de venta',
                                hintText: 'Ej: 5',
                                prefixIcon: Icon(Icons.monetization_on_outlined),
                                border: OutlineInputBorder(),
                                isDense: true,
                              ),
                            ),
                            const SizedBox(height: 4),
                            const Text(
                                'Se aplicará al precio de venta de cada producto '
                                'vendido con esta financiadora para calcular la '
                                'comisión del vendedor.',
                                style: TextStyle(
                                    fontSize: 10,
                                    color: AppColors.textSecondary)),
                          ]),
                    ),
                  ],
                ],
                const SizedBox(height: 14),

                // Preview
                Builder(builder: (_) {
                  final count = catalogoGlobal.where((p) {
                    final catOk = categoria == "Todos" || p.categoria == categoria;
                    final marcaOk = marcaFiltro == "Todas" ||
                        p.marca.toLowerCase() == marcaFiltro.toLowerCase();
                    return catOk && marcaOk;
                  }).length;
                  return Container(
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: count > 0 ? Colors.green[50] : Colors.orange[50],
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(
                        color: count > 0 ? Colors.green : Colors.orange)),
                    child: Row(children: [
                      Icon(count > 0
                        ? Icons.check_circle_outline : Icons.warning_amber_outlined,
                        color: count > 0 ? Colors.green : Colors.orange, size: 18),
                      const SizedBox(width: 8),
                      Expanded(child: Text(
                        count > 0
                          ? "Se agregarán $count producto${count != 1 ? 's' : ''} automáticamente"
                          : "No hay productos de esta categoría/marca",
                        style: TextStyle(
                          fontSize: 12,
                          color: count > 0 ? Colors.green[800] : Colors.orange[800]))),
                    ]),
                  );
                }),
              ],
            )),
            actions: [
              TextButton(
                onPressed: () {
                  Navigator.pop(ctx);
                  nombreCtrl.dispose(); tasaCtrl.dispose();
                  pctAdicionalCtrl.dispose(); financiadoraCtrl.dispose();
                  pctInicialCtrl.dispose(); cuotasCtrl.dispose();
                  pctComisionWeppaCtrl.dispose();
                  pctRecargoCuotasCtrl.dispose();
                },
                child: const Text("CANCELAR")),
              ElevatedButton.icon(
                icon: const Icon(Icons.playlist_add),
                label: const Text("CREAR"),
                onPressed: () async {
                  if (nombreCtrl.text.trim().isEmpty) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(content: Text("Ingrese un nombre para la lista")));
                    return;
                  }
                  if (esFinanc && financiadoraCtrl.text.trim().isEmpty) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(content: Text("Ingrese el nombre de la financiadora")));
                    return;
                  }
                  final tasa = esBs
                    ? (double.tryParse(tasaCtrl.text) ?? ConfigSistema.tasaCambio)
                    : 1.0;
                  final pctAdicional = double.tryParse(pctAdicionalCtrl.text) ?? 0.0;
                  final pctInicial   = double.tryParse(pctInicialCtrl.text) ?? 0.0;
                  final cuotas       = int.tryParse(cuotasCtrl.text) ?? 12;
                  final pctComisionWeppa =
                      double.tryParse(pctComisionWeppaCtrl.text) ?? 0.0;
                  final pctRecargoCuotas =
                      double.tryParse(pctRecargoCuotasCtrl.text) ?? 0.0;

                  final nueva = ListaPrecio(
                    nombre: nombreCtrl.text.trim(),
                    fechaCreacion: obtenerFechaActual(),
                    categoria: categoria,
                    marcaFiltro: marcaFiltro,
                    esEnBolivares: esBs,
                    tasaDelDia: tasa,
                    porcentajeAdicional: pctAdicional,
                    esFinanciamiento: esFinanc,
                    financiadora: esFinanc ? financiadoraCtrl.text.trim() : null,
                    porcentajeInicial: pctInicial,
                    numeroCuotas: cuotas,
                    porcentajeComisionWeppa: pctComisionWeppa,
                    porcentajeRecargoCuotas: pctRecargoCuotas,
                    tieneCuotas: esFinanc ? tieneCuotas : true,
                    columnas: [ColumnaPrecio(nombre: "Precio")],
                  );
                  _poblarLista(nueva);
                  // ── NOTA: El % adicional YA se aplica dentro de
                  // `_poblarLista` (línea ~27935 donde se hace
                  // `precioVenta * factorAdicional`). Antes este bloque
                  // lo aplicaba OTRA VEZ encima, lo que duplicaba el
                  // recargo (50% se convertía en 125%). Eliminado.
                  // ── Persistir en backend ──
                  // Antes la lista se agregaba sólo a `listasPreciosGlobal`
                  // (memoria de la sesión) y nunca al servidor, así que
                  // ningún otro usuario la veía y se perdía al cerrar.
                  try {
                    final resp = await _Api.post('listas_precios', nueva.toMap());
                    if (resp is Map && resp['id'] != null) {
                      nueva.id = (resp['id'] is int)
                          ? resp['id']
                          : int.tryParse(resp['id'].toString());
                    }
                    if (mounted) {
                      setState(() => listasPreciosGlobal.add(nueva));
                      Navigator.pop(ctx);
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(
                          content: Text('Lista creada y guardada en el servidor'),
                          backgroundColor: AppColors.statusGreen));
                    }
                  } catch (e) {
                    if (mounted) {
                      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                        content: Text('No se pudo guardar la lista: $e'),
                        backgroundColor: AppColors.statusRed));
                    }
                    return;
                  }
                  nombreCtrl.dispose(); tasaCtrl.dispose();
                  pctAdicionalCtrl.dispose(); financiadoraCtrl.dispose();
                  pctInicialCtrl.dispose(); cuotasCtrl.dispose();
                  pctComisionWeppaCtrl.dispose();
                  pctRecargoCuotasCtrl.dispose();
                }),
            ],
          );
        },
      ),
    );
  }
  IconData _iconoCategoria(String cat) {
    switch (cat) {
      case 'Telefono':    return Icons.phone_android;
      case 'Accesorio':  return Icons.headphones;
      case 'Televisor':  return Icons.tv;
      case 'Linea':      return Icons.sim_card;
      case 'Linea Blanca': return Icons.kitchen_outlined;
      default:           return Icons.category;
    }
  }

  @override
  Widget build(BuildContext context) {
