}

// ============================================================
//  DETALLE LISTA DE PRECIOS — vista mejorada agrupada por marca
// ============================================================
// ════════════════════════════════════════════════════════════
//  INICIAL Y CUOTAS POR MARCA O POR MODELO
// ════════════════════════════════════════════════════════════
//  Una lista de financiadora tenía UN solo % de inicial y UN solo
//  número de cuotas para todos sus productos. Para trabajar 30% en
//  Samsung y 40% en Apple había que crear dos listas, duplicando
//  precios y manteniéndolas a mano.
//
//  Acá se eligen las marcas (y, si hace falta, modelos puntuales) y
//  se les fija su propio % de inicial y su propio número de cuotas.
//  Lo que no se toca sigue con las condiciones generales de la lista.
// ════════════════════════════════════════════════════════════

/// Marca de un item, normalizada para agrupar y mostrar.
String _marcaDeItem(ItemListaPrecio it) {
  final m = it.producto.marca.trim();
  return m.isEmpty ? '(Sin marca)' : m;
}

/// Etiqueta de modelo de un item. Los productos sin modelo cargado
/// (accesorios, casi siempre) se identifican por su nombre.
String _modeloDeItem(ItemListaPrecio it) {
  final m = it.producto.modelo.trim();
  return m.isEmpty ? it.producto.nombre.trim() : m;
}

/// Clave única de modelo dentro de la lista (marca + modelo).
String _claveModelo(ItemListaPrecio it) =>
    '${_marcaDeItem(it)}|${_modeloDeItem(it)}';

/// Abre el editor de condiciones por marca/modelo sobre [lista].
///
/// Devuelve true si se modificó algo, para que quien lo llame
/// persista la lista.
Future<bool> ajustarCondicionesPorMarcaModelo(
    BuildContext context, ListaPrecio lista) async {
  if (lista.items.isEmpty) {
    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
      content: Text('La lista todavía no tiene productos cargados'),
      backgroundColor: AppColors.statusOrange));
    return false;
  }

  final marcasSel = <String>{};
  final modelosSel = <String>{};
  final ctrlPct = TextEditingController();
  final ctrlCuotas = TextEditingController();

  // Marcas presentes en la lista, ordenadas alfabéticamente.
  final marcas = lista.items.map(_marcaDeItem).toSet().toList()..sort();

  final cambio = await showDialog<bool>(
    context: context,
    builder: (ctx) => StatefulBuilder(builder: (ctx, setDlg) {
      // Modelos disponibles: sólo los de las marcas elegidas.
      final modelos = lista.items
          .where((it) => marcasSel.contains(_marcaDeItem(it)))
          .map(_claveModelo)
          .toSet()
          .toList()
        ..sort();

      // Productos alcanzados por la selección actual. Sin modelos
      // marcados, entra toda la marca.
      final alcanzados = lista.items.where((it) {
        if (!marcasSel.contains(_marcaDeItem(it))) return false;
        if (modelosSel.isEmpty) return true;
        return modelosSel.contains(_claveModelo(it));
      }).toList();

      final pct = double.tryParse(ctrlPct.text.trim().replaceAll(',', '.'));
      final nCuotas = int.tryParse(ctrlCuotas.text.trim());
      final hayValor = (pct != null && pct >= 0) ||
          (nCuotas != null && nCuotas > 0);

      // Resumen de lo que ya está personalizado, para no tener que
      // recorrer la lista buscando qué se tocó antes.
      final personalizados =
          lista.items.where((it) => it.tieneCondicionesPropias).toList();

      return Dialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        insetPadding: const EdgeInsets.all(16),
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 620, maxHeight: 680),
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            // ── Encabezado ──
            Container(
              padding: const EdgeInsets.all(16),
              decoration: const BoxDecoration(
                color: AppColors.royalBlue,
                borderRadius: BorderRadius.vertical(top: Radius.circular(16)),
              ),
              child: Row(children: [
                const Icon(Icons.tune, color: Colors.white),
                const SizedBox(width: 10),
                Expanded(
                  child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text('Inicial y cuotas por marca o modelo',
                            style: TextStyle(
                                color: Colors.white,
                                fontSize: 16,
                                fontWeight: FontWeight.bold)),
                        Text(
                            'General de la lista: '
                            '${lista.porcentajeInicial.toStringAsFixed(0)}% '
                            'inicial'
                            '${lista.tieneCuotas ? " · ${lista.numeroCuotas} cuotas" : ""}',
                            style: const TextStyle(
                                color: Colors.white70, fontSize: 11)),
                      ]),
                ),
                IconButton(
                  icon: const Icon(Icons.close, color: Colors.white),
                  onPressed: () => Navigator.pop(ctx, false),
                ),
              ]),
            ),
            Expanded(
              child: ListView(
                padding: const EdgeInsets.all(14),
                children: [
                  // ── Paso 1: marcas ──
                  const Text('1 · ¿A qué marcas?',
                      style: TextStyle(
                          fontWeight: FontWeight.bold, fontSize: 13)),
                  const SizedBox(height: 6),
                  Wrap(
                    spacing: 6,
                    runSpacing: 6,
                    children: marcas.map((m) {
                      final sel = marcasSel.contains(m);
                      return FilterChip(
                        label: Text(m, style: const TextStyle(fontSize: 12)),
                        selected: sel,
                        selectedColor:
                            AppColors.royalBlue.withValues(alpha: 0.2),
                        onSelected: (v) => setDlg(() {
                          if (v) {
                            marcasSel.add(m);
                          } else {
                            marcasSel.remove(m);
                            // Al soltar una marca, se sueltan sus modelos.
                            modelosSel.removeWhere(
                                (k) => k.startsWith('$m|'));
                          }
                        }),
                      );
                    }).toList(),
                  ),
                  // ── Paso 2: modelos (opcional) ──
                  if (marcasSel.isNotEmpty) ...[
                    const SizedBox(height: 16),
                    Row(children: [
                      const Expanded(
                        child: Text('2 · ¿Sólo algunos modelos?',
                            style: TextStyle(
                                fontWeight: FontWeight.bold, fontSize: 13)),
                      ),
                      if (modelosSel.isNotEmpty)
                        TextButton(
                          onPressed: () => setDlg(modelosSel.clear),
                          child: const Text('Toda la marca',
                              style: TextStyle(fontSize: 11)),
                        ),
                    ]),
                    const Text(
                        'Si no marcás ninguno, se aplica a todos los '
                        'modelos de las marcas elegidas.',
                        style: TextStyle(
                            fontSize: 11, color: AppColors.textSecondary)),
                    const SizedBox(height: 6),
                    Wrap(
                      spacing: 6,
                      runSpacing: 6,
                      children: modelos.map((clave) {
                        final etiqueta = clave.split('|').last;
                        final sel = modelosSel.contains(clave);
                        return FilterChip(
                          label: Text(etiqueta,
                              style: const TextStyle(fontSize: 11)),
                          selected: sel,
                          selectedColor:
                              AppColors.statusGreen.withValues(alpha: 0.2),
                          onSelected: (v) => setDlg(() {
                            if (v) {
                              modelosSel.add(clave);
                            } else {
                              modelosSel.remove(clave);
                            }
                          }),
                        );
                      }).toList(),
                    ),
                  ],
                  // ── Paso 3: valores ──
                  const SizedBox(height: 16),
                  const Text('3 · Condiciones para esa selección',
                      style: TextStyle(
                          fontWeight: FontWeight.bold, fontSize: 13)),
                  const Text('Dejá un campo vacío para no tocarlo.',
                      style: TextStyle(
                          fontSize: 11, color: AppColors.textSecondary)),
                  const SizedBox(height: 8),
                  Row(children: [
                    Expanded(
                      child: TextField(
                        controller: ctrlPct,
                        keyboardType: const TextInputType.numberWithOptions(
                            decimal: true),
                        decoration: InputDecoration(
                          labelText: '% inicial',
                          hintText: lista.porcentajeInicial
                              .toStringAsFixed(0),
                          prefixIcon: const Icon(Icons.percent),
                          border: const OutlineInputBorder(),
                          isDense: true,
                        ),
                        onChanged: (_) => setDlg(() {}),
                      ),
                    ),
                    if (lista.tieneCuotas) ...[
                      const SizedBox(width: 10),
                      Expanded(
                        child: TextField(
                          controller: ctrlCuotas,
                          keyboardType: TextInputType.number,
                          decoration: InputDecoration(
                            labelText: 'N° de cuotas',
                            hintText: '${lista.numeroCuotas}',
                            prefixIcon:
                                const Icon(Icons.format_list_numbered),
                            border: const OutlineInputBorder(),
                            isDense: true,
                          ),
                          onChanged: (_) => setDlg(() {}),
                        ),
                      ),
                    ],
                  ]),
                  // ── Qué va a pasar ──
                  const SizedBox(height: 14),
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: alcanzados.isEmpty
                          ? Colors.grey[100]
                          : AppColors.royalBlue.withValues(alpha: 0.07),
                      borderRadius: BorderRadius.circular(8),
                    ),
                    child: Text(
                      alcanzados.isEmpty
                          ? 'Elegí al menos una marca para empezar.'
                          : 'Se van a modificar ${alcanzados.length} '
                            'producto${alcanzados.length == 1 ? "" : "s"}: '
                            '${alcanzados.take(4).map((it) => it.producto.nombre).join(", ")}'
                            '${alcanzados.length > 4 ? "…" : ""}',
                      style: const TextStyle(fontSize: 12),
                    ),
                  ),
                  // ── Personalizaciones ya activas ──
                  if (personalizados.isNotEmpty) ...[
                    const SizedBox(height: 16),
                    const Text('Ya personalizados',
                        style: TextStyle(
                            fontWeight: FontWeight.bold, fontSize: 12)),
                    const SizedBox(height: 4),
                    ...personalizados.take(12).map((it) => Padding(
                          padding: const EdgeInsets.symmetric(vertical: 1),
                          child: Text(
                            '· ${it.producto.nombre} → '
                            '${lista.pctInicialDe(it).toStringAsFixed(0)}% '
                            'inicial'
                            '${lista.tieneCuotas ? " · ${lista.cuotasDe(it)} cuotas" : ""}',
                            style: const TextStyle(
                                fontSize: 11,
                                color: AppColors.textSecondary),
                          ),
                        )),
                    if (personalizados.length > 12)
                      Text('… y ${personalizados.length - 12} más',
                          style: const TextStyle(
                              fontSize: 11,
                              fontStyle: FontStyle.italic,
                              color: AppColors.textSecondary)),
                  ],
                ],
              ),
            ),
            // ── Pie ──
            Container(
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                border: Border(top: BorderSide(color: Colors.grey[300]!)),
                borderRadius:
                    const BorderRadius.vertical(bottom: Radius.circular(16)),
              ),
              child: Row(children: [
                // Volver a las condiciones generales de la lista.
                TextButton.icon(
                  icon: const Icon(Icons.restart_alt, size: 16),
                  label: const Text('Quitar personalización',
                      style: TextStyle(fontSize: 12)),
                  onPressed: alcanzados.isEmpty
                      ? null
                      : () {
                          for (final it in alcanzados) {
                            it.pctInicialOverride = null;
                            it.cuotasOverride = null;
                            it.inicialManual = null;
                            it.cuotaManual = null;
                          }
                          Navigator.pop(ctx, true);
                        },
                ),
                const Spacer(),
                TextButton(
                    onPressed: () => Navigator.pop(ctx, false),
                    child: const Text('Cancelar')),
                const SizedBox(width: 6),
                ElevatedButton.icon(
                  icon: const Icon(Icons.check, size: 18),
                  label: const Text('Aplicar'),
                  style: ElevatedButton.styleFrom(
                      backgroundColor: AppColors.royalBlue,
                      foregroundColor: Colors.white),
                  onPressed: (alcanzados.isEmpty || !hayValor)
                      ? null
                      : () {
                          for (final it in alcanzados) {
                            if (pct != null && pct >= 0) {
                              it.pctInicialOverride = pct;
                            }
                            if (nCuotas != null && nCuotas > 0) {
                              it.cuotasOverride = nCuotas;
                            }
                            // Los montos que se habían fijado a mano
                            // corresponden a las condiciones viejas: se
                            // limpian para que se recalculen con las
                            // nuevas.
                            it.inicialManual = null;
                            it.cuotaManual = null;
                          }
                          Navigator.pop(ctx, true);
                        },
                ),
              ]),
            ),
          ]),
        ),
      );
    }),
  );

  ctrlPct.dispose();
  ctrlCuotas.dispose();
  return cambio == true;
}

class DetalleListaPrecio extends StatefulWidget {
  final ListaPrecio lista;
  const DetalleListaPrecio({super.key, required this.lista});
  @override State<DetalleListaPrecio> createState() => _DetalleListaPrecioState();
}

class _DetalleListaPrecioState extends State<DetalleListaPrecio> {
  String _busqueda = "";
  final _searchCtrl = TextEditingController();

  /// Indica si la lista se está sincronizando con el backend en
  /// este momento (para mostrar el spinner en la AppBar).
  bool _guardandoBackend = false;

  /// Marca de tiempo de la última edición LOCAL del usuario. Si el
  /// usuario hizo un cambio hace menos de N segundos, NO sincronizamos
  /// desde el servidor — sus cambios podrían estar en vuelo todavía.
  DateTime _ultimaEdicionLocal = DateTime(2000);

  /// Timer de sincronización periódica con el backend. Cada 15s
  /// trae la versión más reciente de ESTA lista para que el usuario
  /// vea los cambios hechos por otros dispositivos.
  Timer? _timerSyncDetalle;

  @override
  void initState() {
    super.initState();
    _iniciarSincronizacion();
    // AUTOPOBLAR si la lista entró vacía. Antes el usuario tenía que
    // hacer clic en "Poblar automáticamente" cada vez que abría una
    // lista vacía — ahora se rellena sola con los productos del
    // catálogo según la categoría y marca configuradas en la lista.
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      if (!mounted) return;
      // Reponer las funciones de columna guardadas en el dispositivo
      // por si el servidor devolvio las columnas sin su funcion.
      await _restaurarFormulasDeCache();
      if (!mounted) return;
      // Aplicar las funciones automaticas con los datos ya cargados
      if (widget.lista.items.isNotEmpty && widget.lista.tieneFormulas) {
        final n = widget.lista.aplicarFormulas();
        if (n > 0) {
          setState(() {});
          _persistirLista();
        }
      }
      if (widget.lista.items.isEmpty &&
          widget.lista.columnas.isNotEmpty) {
        _autoPoblar();
      } else if (widget.lista.esEnBolivares) {
        // ── DETECCIÓN DE TASA DESACTUALIZADA ──
        // Si la lista está en Bs y su tasaDelDia es DIFERENTE a la
        // tasa actual del sistema, recalculamos automáticamente los
        // precios automáticos (preservando los manuales) y actualizamos
        // su tasaDelDia. Esto resuelve el problema de listas viejas
        // que se quedaron con tasa antigua.
        _refrescarPreciosAutomaticosSiTasaCambio();
      }
    });
  }

  /// Detecta si la tasa guardada en la lista difiere de la tasa
  /// actual del sistema y, en ese caso, recalcula los precios que
  /// estaban siguiendo la fórmula automática. Los precios editados
  /// manualmente se preservan.
  void _refrescarPreciosAutomaticosSiTasaCambio() {
    final lista = widget.lista;
    if (!lista.esEnBolivares) return;
    final tasaSistema = ConfigSistema.tasaCambio;
    if (tasaSistema <= 0) return;
    final tasaLista = lista.tasaDelDia;
    if ((tasaLista - tasaSistema).abs() < 0.01) return; // misma tasa, nada que hacer

    debugPrint('[Lista ${lista.nombre}] Tasa desactualizada: '
        'lista=$tasaLista vs sistema=$tasaSistema. Recalculando...');

    final factorAdicional = 1 + (lista.porcentajeAdicional / 100);
    int recalculados = 0;
    int preservados = 0;

    setState(() {
      for (final item in lista.items) {
        // Cálculo EXACTO: USD con margen redondeado ANTES de convertir
        final precioUsdConMargen =
            redondearPrecio(item.producto.precioVenta * factorAdicional);
        // Precio esperado con tasa anterior (lo que está guardado si era automático)
        final esperadoAnterior = precioUsdConMargen * tasaLista;
        // Nuevo precio con tasa actual del sistema
        final esperadoNuevo = redondearPrecio(precioUsdConMargen * tasaSistema);

        for (final col in lista.columnas) {
          final actual = item.preciosPorColumna[col.nombre];
          if (actual == null) continue;
          // ¿El precio actual coincide con la fórmula vieja?
          // Tolerancia de 1 Bs para los redondeos
          final esAutomatico =
              (actual - esperadoAnterior).abs() < 1.0 ||
              (actual - redondearPrecio(esperadoAnterior)).abs() < 1.0;
          if (esAutomatico) {
            item.preciosPorColumna[col.nombre] = esperadoNuevo;
            recalculados++;
          } else {
            preservados++;
          }
        }
      }
      lista.tasaDelDia = tasaSistema;
      // Las columnas con funcion automatica se recalculan con la tasa
      // nueva (algunas multiplican por la tasa).
      recalculados += lista.aplicarFormulas();
    });

    debugPrint('[Lista ${lista.nombre}] $recalculados precios recalculados, '
        '$preservados manuales preservados');

    if (recalculados > 0) {
      _persistirLista();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text(
              '🔄 Precios actualizados con la nueva tasa ($tasaSistema Bs/\$). '
              '$recalculados precios recalculados.'),
          backgroundColor: AppColors.primaryBlue,
          duration: const Duration(seconds: 3),
        ));
      }
    }
  }

  /// Pobla automáticamente la lista con productos del catálogo que
  /// coinciden con la categoría y marca configuradas. Calcula precios
  /// según moneda (Bs o $), aplica % adicional y persiste al backend.
  ///
  /// Se llama automáticamente al abrir una lista vacía y manualmente
  /// desde el botón "Repoblar" si el admin quiere forzar refresh.
  void _autoPoblar() {
    final lista = widget.lista;
    final tasa = lista.esEnBolivares
        ? (ConfigSistema.tasaCambio > 0
            ? ConfigSistema.tasaCambio
            : lista.tasaDelDia)
        : 1.0;
    final factorAdicional = 1 + (lista.porcentajeAdicional / 100);

    // Filtrar productos del catálogo según categoría y marca
    final filtrados = catalogoGlobal.where((p) {
      if (p.esSubproducto) return false; // solo productos padre
      final catOk = lista.categoria == "Todos" ||
          p.categoria == lista.categoria;
      final marcaOk = lista.marcaFiltro == "Todas" ||
          p.marca.toLowerCase() == lista.marcaFiltro.toLowerCase();
      return catOk && marcaOk;
    }).toList();

    // Ordenar por marca → modelo
    filtrados.sort((a, b) {
      final m = a.marca.toLowerCase().compareTo(b.marca.toLowerCase());
      return m != 0
          ? m
          : a.nombre.toLowerCase().compareTo(b.nombre.toLowerCase());
    });

    setState(() {
      lista.items.clear();
      bool _debugFirst = true;
      for (final p in filtrados) {
        // Calcular stock (suma teléfonos: IMEIs; otros: stockManual)
        int stock;
        if (CategoriasProductos.usaIMEI(p.categoria)) {
          stock = stockImeiGlobal.where(
              (i) => i.producto.codigo == p.codigo && !i.vendido).length;
        } else {
          stock = p.stockManual;
        }
        // No filtramos por stock para no esconder productos agotados
        // en el editor — el admin debe poder editar precios incluso
        // de productos sin stock momentáneo.
        // ── CÁLCULO EXACTO DE PRECIO ──
        // 1) Aplicar el % adicional al precio USD y redondear a 2 dec.
        //    Esto fija el precio en USD ANTES de convertir, así no
        //    arrastramos decimales fantasma al hacer la conversión.
        // 2) Si es lista en Bs, multiplicar por la tasa y redondear
        //    nuevamente a 2 decimales.
        final precioUsdConMargen = redondearPrecio(p.precioVenta * factorAdicional);
        final precioBase = lista.esEnBolivares
            ? redondearPrecio(precioUsdConMargen * tasa)
            : precioUsdConMargen;
        // ── Debug del primer producto (para verificar conversión) ──
        if (_debugFirst) {
          debugPrint('[Lista ${lista.nombre}] Producto: ${p.nombre}');
          debugPrint('  precioVenta (USD): ${p.precioVenta}');
          debugPrint('  %adicional: ${lista.porcentajeAdicional}');
          debugPrint('  factorAdicional: $factorAdicional');
          debugPrint('  precioUsdConMargen: $precioUsdConMargen');
          debugPrint('  esEnBolivares: ${lista.esEnBolivares}, tasa: $tasa');
          debugPrint('  precioBase (final): $precioBase');
          _debugFirst = false;
        }
        lista.items.add(ItemListaPrecio(
          producto: p,
          stockDisponible: stock,
          preciosPorColumna: {
            for (var col in lista.columnas) col.nombre: precioBase
          },
        ));
      }
      // Las columnas con funcion mandan sobre el precio automatico:
      // se recalculan encima de lo que acabamos de poblar.
      lista.aplicarFormulas();
    });
    // Persistir al backend después de poblar
    _persistirLista();
  }

  /// Inicia el polling de sincronización del detalle. Cada 15 segundos
  /// trae la versión más reciente de ESTA lista desde el backend para
  /// que el usuario vea en tiempo real los cambios que hicieron otros
  /// dispositivos (admins/gerentes editando precios desde otra PC).
  void _iniciarSincronizacion() {
    _timerSyncDetalle = Timer.periodic(const Duration(seconds: 15), (_) {
      if (!mounted) {
        _timerSyncDetalle?.cancel();
        return;
      }
      _sincronizarConBackend();
    });
  }

  /// Sincroniza la lista actual con el backend para que el usuario
  /// vea cambios hechos por OTROS dispositivos en tiempo real.
  ///
  /// Reglas de seguridad para NO sobrescribir cambios del usuario:
  ///   1. Si el usuario hizo un cambio en los últimos 8 segundos, NO
  ///      sincroniza — sus ediciones podrían estar pendientes de envío.
  ///   2. Si el debounce de persistencia está activo (cambio sin
  ///      enviar), NO sincroniza.
  ///   3. Si el servidor está guardando ahora mismo, NO sincroniza.
  Future<void> _sincronizarConBackend() async {
    if (!mounted) return;
    if (_guardandoBackend) return;
    if (_debouncePersistir?.isActive ?? false) return;
    // Margen de 8s después de la última edición local
    if (DateTime.now().difference(_ultimaEdicionLocal).inSeconds < 8) {
      return;
    }
    if (widget.lista.id == null) return;
    try {
      final raw = await _Api.get('listas_precios');
      if (raw is! List) return;
      // Encontrar la versión del servidor de NUESTRA lista
      final mServidor = raw.firstWhere(
          (m) => m is Map && '${m['id']}' == '${widget.lista.id}',
          orElse: () => null);
      if (mServidor is! Map) return;
      // Comparar precios/items para ver si hay diferencias
      final hashServidor = _hashContenido(mServidor);
      final hashLocal = _hashListaLocal();
      if (hashServidor == hashLocal) return; // sin cambios
      // ¡Hay cambios! Recargar la lista desde el servidor
      final nueva = ListaPrecio.fromMap(
          Map<String, dynamic>.from(mServidor));
      if (!mounted) return;
      // ── COLUMNAS: nunca se pierden las locales ──────────────
      // Si el servidor devuelve MENOS columnas de las que hay aca (o
      // sin su funcion), es porque todavia no habia guardado la
      // columna recien creada. En ese caso conservamos las locales y
      // volvemos a mandarlas; antes el polling las borraba a los 15
      // segundos y parecia que el sistema "no dejaba" agregar columnas.
      final nombresServidor =
          nueva.columnas.map((c) => c.nombre.toLowerCase()).toSet();
      final columnasSoloLocales = widget.lista.columnas
          .where((c) => !nombresServidor.contains(c.nombre.toLowerCase()))
          .toList();
      // Funciones locales, para reponerlas si el servidor no las guardo
      final formulasLocales = {
        for (final c in widget.lista.columnas)
          c.nombre.toLowerCase(): c.formula
      };
      for (final c in nueva.columnas) {
        if (c.formula.esManual) {
          final local = formulasLocales[c.nombre.toLowerCase()];
          if (local != null && !local.esManual) c.formula = local;
        }
      }
      if (!mounted) return;
      setState(() {
        // Actualizar TODOS los campos in-place (sin reasignar
        // widget.lista que es final)
        widget.lista.nombre = nueva.nombre;
        widget.lista.porcentajeAdicional = nueva.porcentajeAdicional;
        widget.lista.porcentajeInicial = nueva.porcentajeInicial;
        widget.lista.porcentajeRecargoCuotas = nueva.porcentajeRecargoCuotas;
        widget.lista.numeroCuotas = nueva.numeroCuotas;
        widget.lista.tieneCuotas = nueva.tieneCuotas;
        widget.lista.financiadora = nueva.financiadora;
        widget.lista.tasaDelDia = nueva.tasaDelDia;
        widget.lista.esEnBolivares = nueva.esEnBolivares;
        widget.lista.esFinanciamiento = nueva.esFinanciamiento;
        widget.lista.columnas
          ..clear()
          ..addAll(nueva.columnas)
          ..addAll(columnasSoloLocales);
        widget.lista.items
          ..clear()
          ..addAll(nueva.items);
        // Las columnas que el servidor todavia no conoce necesitan su
        // precio en cada item recien traido.
        for (final col in columnasSoloLocales) {
          for (final it in widget.lista.items) {
            if (it.preciosPorColumna.containsKey(col.nombre)) continue;
            final calculado = widget.lista.calcularColumna(col, it);
            it.preciosPorColumna[col.nombre] = calculado ??
                (it.preciosPorColumna.values.isNotEmpty
                    ? it.preciosPorColumna.values.first
                    : it.producto.precioVenta);
          }
        }
        // Recalcular lo que tenga funcion automatica con los datos
        // nuevos que acaban de llegar.
        widget.lista.aplicarFormulas();
      });
      // Reponer en el servidor lo que le faltaba
      if (columnasSoloLocales.isNotEmpty) _persistirLista();
      // Notificación discreta al usuario
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
          content: Text('Lista actualizada (cambios de otro usuario)'),
          backgroundColor: AppColors.primaryBlue,
          duration: Duration(seconds: 2),
        ));
      }
    } catch (e) {
      debugPrint('[DetalleLista] Error sincronizando: $e');
    }
  }

  /// Hash del contenido de un mapa de lista (para comparar versiones)
  String _hashContenido(Map m) {
    final sb = StringBuffer();
    sb
      ..write(m['porcentaje_adicional'])..write('|')
      ..write(m['porcentaje_inicial'])..write('|')
      ..write(m['porcentaje_recargo_cuotas'])..write('|')
      ..write(m['numero_cuotas'])..write('|')
      ..write(m['tiene_cuotas'])..write('|');
    if (m['items'] is List) {
      for (final it in (m['items'] as List)) {
        if (it is! Map) continue;
        sb..write(it['producto_codigo'])..write(':');
        if (it['valores'] is List) {
          for (final v in (it['valores'] as List)) {
            if (v is! Map) continue;
            sb..write(v['columna_nombre'])..write('=')..write(v['precio'])..write(',');
          }
        }
        sb.write(';');
      }
    }
    return sb.toString();
  }

  /// Hash del contenido LOCAL (para comparar con el servidor)
  String _hashListaLocal() {
    final l = widget.lista;
    final sb = StringBuffer();
    sb
      ..write(l.porcentajeAdicional)..write('|')
      ..write(l.porcentajeInicial)..write('|')
      ..write(l.porcentajeRecargoCuotas)..write('|')
      ..write(l.numeroCuotas)..write('|')
      ..write(l.tieneCuotas ? 1 : 0)..write('|');
    for (final it in l.items) {
      sb..write(it.producto.codigo)..write(':');
      it.preciosPorColumna.forEach((k, v) {
        sb..write(k)..write('=')..write(v)..write(',');
      });
      if (it.inicialManual != null) {
        sb..write('__inicial_manual__=')..write(it.inicialManual)..write(',');
      }
      if (it.pctInicialOverride != null) {
        sb..write('__pct_inicial__=')..write(it.pctInicialOverride)..write(',');
      }
      if (it.cuotasOverride != null) {
        sb..write('__n_cuotas__=')..write(it.cuotasOverride)..write(',');
      }
      if (it.cuotaManual != null) {
        sb..write('__cuota_manual__=')..write(it.cuotaManual)..write(',');
      }
      sb.write(';');
    }
    return sb.toString();
  }

  /// Persiste TODA la lista actual al backend para que los cambios
  /// (precios editados, columnas, items) se vean en TODOS los
  /// dispositivos. Antes los cambios eran solo en memoria local —
  /// si otro usuario refrescaba, no los veía.
  ///
  /// Se debounce: si se llama varias veces seguidas, solo el último
  /// llamado realmente persiste, para no saturar el servidor cuando
  /// el usuario edita rápidamente varios precios.
  Timer? _debouncePersistir;
  Future<void> _persistirLista() async {
    // Marcar la última edición local para que el polling no
    // sobrescriba durante los próximos 8 segundos.
    _ultimaEdicionLocal = DateTime.now();
    _debouncePersistir?.cancel();
    _debouncePersistir = Timer(const Duration(milliseconds: 600), () async {
      if (!mounted) return;
      setState(() => _guardandoBackend = true);
      try {
        if (widget.lista.id == null) {
          // La lista todavia no existe en el servidor: la creamos.
          // Antes se salia sin guardar y el usuario perdia todo lo que
          // habia hecho (columnas nuevas incluidas).
          final resp = await _Api.post('listas_precios', widget.lista.toMap());
          if (resp is Map && resp['id'] != null) {
            widget.lista.id = resp['id'] is int
                ? resp['id'] as int
                : int.tryParse(resp['id'].toString());
          }
        } else {
          await _Api.put(
              'listas_precios',
              widget.lista.id.toString(),
              widget.lista.toMap());
        }
        debugPrint('[ListaPrecio] ✓ Persistida en backend '
            '(id=${widget.lista.id})');
        // Reset de la marca de edición — la persistencia ya terminó
        _ultimaEdicionLocal = DateTime.now();
      } catch (e) {
        debugPrint('[ListaPrecio] Error persistiendo: $e');
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(SnackBar(
            content: Row(children: [
              const Icon(Icons.warning, color: Colors.white, size: 18),
              const SizedBox(width: 8),
              Expanded(child: Text(
                  'No se pudo guardar en el servidor. '
                  'Verifica tu conexión. Detalle: $e')),
            ]),
            backgroundColor: Colors.orange,
            duration: const Duration(seconds: 4),
            action: SnackBarAction(
              label: 'REINTENTAR',
              textColor: Colors.white,
              onPressed: _persistirLista,
            )));
        }
      } finally {
        if (mounted) setState(() => _guardandoBackend = false);
      }
    });
  }

  @override
  void dispose() {
    _searchCtrl.dispose();
    _debouncePersistir?.cancel();
    _timerSyncDetalle?.cancel();
    super.dispose();
  }

  // Agrupa los ítems por marca
  Map<String, List<ItemListaPrecio>> _agrupadosPorMarca() {
    final mapa = <String, List<ItemListaPrecio>>{};
    final filtrados = widget.lista.items.where((it) =>
      _busqueda.isEmpty ||
      it.producto.nombre.toLowerCase().contains(_busqueda.toLowerCase()) ||
      it.producto.marca.toLowerCase().contains(_busqueda.toLowerCase()) ||
      it.producto.codigo.toLowerCase().contains(_busqueda.toLowerCase())).toList();
    for (final it in filtrados) {
      final marca = it.producto.marca.isEmpty ? "Sin marca" : it.producto.marca;
      mapa.putIfAbsent(marca, () => []).add(it);
    }
    return mapa;
  }

  // ════════════════════════════════════════════════════════════
  //  COLUMNAS: alta, función configurable, renombrar y borrar
  // ════════════════════════════════════════════════════════════

  /// Producto de muestra para la vista previa del editor de funciones.
  ItemListaPrecio? get _itemMuestra =>
      widget.lista.items.isEmpty ? null : widget.lista.items.first;

  /// Añade una columna nueva a la lista.
  ///
  /// El diálogo pide el nombre y permite configurar de una vez la
  /// FUNCIÓN de la columna (cómo se calcula su precio). Si la función
  /// queda en "Manual" los precios se heredan de la primera columna,
  /// como antes; si tiene función, se calcula para todos los productos
  /// en el momento de crearla.
  Future<void> _anadirColumna() async {
    final colCtrl = TextEditingController();
    var formula = FormulaColumna();
    String? error;

    final creada = await showDialog<bool>(
      context: context,
      builder: (c) => StatefulBuilder(builder: (c, setD) {
        final nombre = colCtrl.text.trim();
        final vistaPrevia = _vistaPreviaTexto(
            nombre.isEmpty ? 'Nueva' : nombre, formula);
        return AlertDialog(
          title: const Text("Nueva columna de precio"),
          content: SizedBox(
            width: 420,
            child: SingleChildScrollView(
              child: Column(mainAxisSize: MainAxisSize.min, children: [
                TextField(
                  controller: colCtrl,
                  autofocus: true,
                  textCapitalization: TextCapitalization.sentences,
                  onChanged: (_) => setD(() => error = null),
                  decoration: InputDecoration(
                    labelText: "Nombre de la columna",
                    hintText: "Ej: Detal, Mayorista, Contado...",
                    errorText: error,
                    prefixIcon: const Icon(Icons.view_column)),
                ),
                const SizedBox(height: 14),
                // ── Resumen de la función elegida ────────────────
                Container(
                  width: double.infinity,
                  padding: const EdgeInsets.all(10),
                  decoration: BoxDecoration(
                    color: formula.esManual
                        ? Colors.grey.withValues(alpha: 0.10)
                        : AppColors.primaryBlue.withValues(alpha: 0.08),
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: Row(children: [
                    Icon(formula.esManual ? Icons.edit_note : Icons.functions,
                        size: 18,
                        color: formula.esManual
                            ? Colors.grey
                            : AppColors.primaryBlue),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            formula.esManual
                                ? 'Sin función — precios a mano'
                                : 'Función: ${formula.descripcion}',
                            style: const TextStyle(
                                fontSize: 12, fontWeight: FontWeight.bold),
                          ),
                          if (vistaPrevia != null)
                            Text(vistaPrevia,
                                style: const TextStyle(
                                    fontSize: 11, color: Colors.black54)),
                        ],
                      ),
                    ),
                    TextButton.icon(
                      icon: const Icon(Icons.tune, size: 16),
                      label: const Text('Configurar'),
                      onPressed: () async {
                        final f = await _editarFormula(
                            nombre.isEmpty ? 'Nueva columna' : nombre,
                            formula);
                        if (f != null) setD(() => formula = f);
                      },
                    ),
                  ]),
                ),
              ]),
            ),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(c, false),
                child: const Text("Cancelar")),
            ElevatedButton(
              onPressed: () {
                final nombreCol = colCtrl.text.trim();
                if (nombreCol.isEmpty) {
                  setD(() => error = 'Escribe un nombre para la columna');
                  return;
                }
                if (FormulaColumna.esNombreVirtual(nombreCol)) {
                  setD(() => error = 'Ese nombre está reservado por el sistema');
                  return;
                }
                if (widget.lista.columnas.any((x) =>
                    x.nombre.toLowerCase() == nombreCol.toLowerCase())) {
                  setD(() => error = 'Ya existe una columna con ese nombre');
                  return;
                }
                Navigator.pop(c, true);
              },
              child: const Text("Añadir")),
          ],
        );
      }),
    );

    final nombreCol = colCtrl.text.trim();
    colCtrl.dispose();
    if (creada != true || nombreCol.isEmpty || !mounted) return;

    final col = ColumnaPrecio(nombre: nombreCol, formula: formula);
    setState(() {
      widget.lista.columnas.add(col);
      for (final item in widget.lista.items) {
        // Con función: se calcula. Sin función: hereda el precio de la
        // primera columna (o el precio de venta del catálogo).
        final calculado = widget.lista.calcularColumna(col, item);
        if (calculado != null) {
          item.preciosPorColumna[nombreCol] = calculado;
        } else if (!item.preciosPorColumna.containsKey(nombreCol)) {
          final base = item.preciosPorColumna.values.isNotEmpty
              ? item.preciosPorColumna.values.first
              : (widget.lista.esEnBolivares
                  ? item.producto.precioVenta * widget.lista.tasaEfectiva
                  : item.producto.precioVenta);
          item.preciosPorColumna[nombreCol] = base;
        }
      }
    });
    _persistirLista(); // sincronizar con backend
    _guardarFormulasEnCache();
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text('✅ Columna "$nombreCol" añadida'
          '${formula.esManual ? '' : ' con función ${formula.descripcion}'}'),
      backgroundColor: AppColors.statusGreen,
      duration: const Duration(seconds: 3),
    ));
  }

  /// Texto de vista previa: cuánto daría la función para el primer
  /// producto de la lista. Devuelve null si no se puede calcular.
  String? _vistaPreviaTexto(String nombreColumna, FormulaColumna f) {
    if (f.esManual) return null;
    final it = _itemMuestra;
    if (it == null) return null;
    final v = widget.lista
        .calcularColumna(ColumnaPrecio(nombre: nombreColumna, formula: f), it);
    final moneda = widget.lista.esEnBolivares ? 'Bs' : '\$';
    if (v == null) return 'No se pudo calcular — revisa la función';
    return 'Ej: ${it.producto.nombre} → $moneda ${v.toStringAsFixed(2)}';
  }

  /// EDITOR COMPLETO DE LA FUNCIÓN DE UNA COLUMNA.
  ///
  /// Devuelve la función configurada, o null si el usuario canceló.
  /// Todo es configurable: modo de cálculo, de dónde sale el valor de
  /// partida, el número, el redondeo, si se le aplica la tasa o el %
  /// adicional de la lista, y si se recalcula sola.
  Future<FormulaColumna?> _editarFormula(
      String nombreColumna, FormulaColumna original) async {
    final f = original.copiar();
    final valorCtrl = TextEditingController(
        text: f.valor == 0 ? '' : _numeroTexto(f.valor));
    final multiploCtrl =
        TextEditingController(text: _numeroTexto(f.multiplo));
    final exprCtrl = TextEditingController(text: f.expresion);

    // Otras columnas que pueden servir de origen (no ella misma)
    final otrasColumnas = widget.lista.columnas
        .where((c) => c.nombre.toLowerCase() != nombreColumna.toLowerCase())
        .map((c) => c.nombre)
        .toList();
    if (f.origen == 'columna' &&
        (f.columnaOrigen.isEmpty || !otrasColumnas.contains(f.columnaOrigen))) {
      f.columnaOrigen = otrasColumnas.isEmpty ? '' : otrasColumnas.first;
    }

    final resultado = await showDialog<FormulaColumna>(
      context: context,
      builder: (ctx) => StatefulBuilder(builder: (ctx, setD) {
        f.valor = double.tryParse(valorCtrl.text.replaceAll(',', '.')) ?? 0;
        f.multiplo =
            double.tryParse(multiploCtrl.text.replaceAll(',', '.')) ?? 1;
        f.expresion = exprCtrl.text;

        final esExpr = f.modo == FormulaColumna.modoExpresion;
        final usaOrigen = !f.esManual && !esExpr;
        final vistaPrevia = _vistaPreviaTexto(nombreColumna, f);
        final errorExpr = esExpr && _itemMuestra != null
            ? EvaluadorFormula.validar(
                f.expresion, widget.lista.variablesDe(_itemMuestra!))
            : null;

        String etiquetaValor() {
          switch (f.modo) {
            case FormulaColumna.modoPorcentaje:
              return 'Porcentaje (10 = +10 %, -5 = −5 %)';
            case FormulaColumna.modoMonto:
              return 'Monto a sumar (negativo para restar)';
            case FormulaColumna.modoMultiplicador:
              return 'Multiplicador (ej: 1.35)';
            default:
              return 'Valor';
          }
        }

        return AlertDialog(
          title: Row(children: [
            const Icon(Icons.functions, color: AppColors.primaryBlue),
            const SizedBox(width: 8),
            Expanded(
                child: Text('Función de "$nombreColumna"',
                    style: const TextStyle(fontSize: 16))),
          ]),
          content: SizedBox(
            width: 460,
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  // ── 1. Modo de cálculo ────────────────────────
                  DropdownButtonFormField<String>(
                    initialValue: f.modo,
                    isExpanded: true,
                    decoration: const InputDecoration(
                      labelText: 'Cómo se calcula esta columna',
                      prefixIcon: Icon(Icons.calculate),
                      isDense: true,
                    ),
                    items: const [
                      DropdownMenuItem(
                          value: FormulaColumna.modoManual,
                          child: Text('Manual — el precio se escribe a mano')),
                      DropdownMenuItem(
                          value: FormulaColumna.modoPorcentaje,
                          child: Text('Porcentaje sobre un valor (+/− %)')),
                      DropdownMenuItem(
                          value: FormulaColumna.modoMonto,
                          child: Text('Sumar o restar un monto fijo')),
                      DropdownMenuItem(
                          value: FormulaColumna.modoMultiplicador,
                          child: Text('Multiplicar por un factor')),
                      DropdownMenuItem(
                          value: FormulaColumna.modoExpresion,
                          child: Text('Fórmula libre (avanzado)')),
                    ],
                    onChanged: (v) => setD(() => f.modo = v ?? f.modo),
                  ),

                  // ── 2. Origen del valor ───────────────────────
                  if (usaOrigen) ...[
                    const SizedBox(height: 12),
                    DropdownButtonFormField<String>(
                      initialValue: f.origen,
                      isExpanded: true,
                      decoration: const InputDecoration(
                        labelText: 'Se calcula a partir de',
                        prefixIcon: Icon(Icons.input),
                        isDense: true,
                      ),
                      items: [
                        const DropdownMenuItem(
                            value: 'venta',
                            child: Text('Precio de venta del catálogo')),
                        const DropdownMenuItem(
                            value: 'costo',
                            child: Text('Precio de costo del catálogo')),
                        const DropdownMenuItem(
                            value: 'base',
                            child: Text('Precio base (primera columna)')),
                        if (otrasColumnas.isNotEmpty)
                          const DropdownMenuItem(
                              value: 'columna',
                              child: Text('Otra columna de esta lista')),
