                  // ── 4. Ajustes finales ────────────────────────
                  if (!f.esManual) ...[
                    const SizedBox(height: 12),
                    DropdownButtonFormField<String>(
                      initialValue: f.redondeo,
                      isExpanded: true,
                      decoration: const InputDecoration(
                        labelText: 'Redondeo del resultado',
                        prefixIcon: Icon(Icons.straighten),
                        isDense: true,
                      ),
                      items: const [
                        DropdownMenuItem(
