  /// Abre el editor de función para una columna existente y aplica el
  /// resultado.
  Future<void> _configurarFormula(ColumnaPrecio col) async {
    final f = await _editarFormula(col.nombre, col.formula);
    if (f == null || !mounted) return;
    setState(() => col.formula = f);
    var cambios = 0;
    if (!f.esManual) {
      final aplicar = await showDialog<bool>(
        context: context,
        builder: (ctx) => AlertDialog(
          title: const Text('Función guardada'),
          content: Text('¿Aplicarla ahora a los ${widget.lista.items.length} '
              'productos de la lista?\n\nSi eliges "Ahora no", la función '
              'queda guardada y se aplicará cuando pulses "Aplicar la '
              'función ahora"'
              '${f.auto ? ' o cuando la lista se recalcule sola' : ''}.'),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(ctx, false),
                child: const Text('Ahora no')),
            ElevatedButton(
                onPressed: () => Navigator.pop(ctx, true),
                child: const Text('Aplicar ahora')),
          ],
        ),
      );
      if (aplicar == true && mounted) {
        setState(() {
          cambios = widget.lista.aplicarFormulas(
              soloAutomaticas: false, soloColumna: col.nombre);
        });
      }
    }
    _persistirLista();
    _guardarFormulasEnCache();
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(cambios > 0
          ? '✅ Función guardada — $cambios precios recalculados en '
              '"${col.nombre}"'
          : '✅ Función de "${col.nombre}" guardada'),
      backgroundColor: AppColors.statusGreen,
      duration: const Duration(seconds: 3),
    ));
  }

  /// Recalcula UNA columna con su función en todos los productos.
  void _aplicarFormulaColumna(ColumnaPrecio col) {
    if (col.formula.esManual) return;
    final cambios = widget.lista
        .aplicarFormulas(soloAutomaticas: false, soloColumna: col.nombre);
    setState(() {});
    _persistirLista();
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(cambios > 0
          ? '✅ $cambios precios recalculados en "${col.nombre}"'
          : 'Los precios de "${col.nombre}" ya estaban al día'),
      backgroundColor:
          cambios > 0 ? AppColors.statusGreen : AppColors.primaryBlue,
      duration: const Duration(seconds: 3),
    ));
  }

  /// Recalcula TODAS las columnas que tengan función.
  void _aplicarTodasLasFormulas() {
    if (!widget.lista.tieneFormulas) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text('Ninguna columna tiene función configurada. '
            'Toca el título de una columna para configurarla.'),
        backgroundColor: AppColors.primaryBlue,
        duration: Duration(seconds: 4),
      ));
      return;
    }
    final cambios = widget.lista.aplicarFormulas(soloAutomaticas: false);
    setState(() {});
    _persistirLista();
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(cambios > 0
          ? '✅ $cambios precios recalculados con las funciones de las columnas'
          : 'Todos los precios ya estaban al día'),
      backgroundColor:
          cambios > 0 ? AppColors.statusGreen : AppColors.primaryBlue,
      duration: const Duration(seconds: 3),
    ));
  }

  /// Renombra una columna arrastrando con ella los precios guardados y
  /// las referencias de otras funciones.
  Future<void> _renombrarColumna(ColumnaPrecio col) async {
    final ctrl = TextEditingController(text: col.nombre);
    String? error;
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setD) => AlertDialog(
          title: const Text('Renombrar columna'),
          content: TextField(
            controller: ctrl,
            autofocus: true,
            onChanged: (_) => setD(() => error = null),
            decoration: InputDecoration(
                labelText: 'Nombre', errorText: error,
                prefixIcon: const Icon(Icons.view_column)),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(ctx, false),
                child: const Text('Cancelar')),
            ElevatedButton(
              onPressed: () {
                final n = ctrl.text.trim();
                if (n.isEmpty) {
                  setD(() => error = 'Escribe un nombre');
                  return;
                }
                if (FormulaColumna.esNombreVirtual(n)) {
                  setD(() => error = 'Ese nombre está reservado');
                  return;
                }
                if (n.toLowerCase() != col.nombre.toLowerCase() &&
                    widget.lista.columnas
                        .any((x) => x.nombre.toLowerCase() == n.toLowerCase())) {
                  setD(() => error = 'Ya existe una columna con ese nombre');
                  return;
                }
                Navigator.pop(ctx, true);
              },
              child: const Text('Guardar')),
          ],
        ),
      ),
    );
    final nuevo = ctrl.text.trim();
    ctrl.dispose();
    if (ok != true || nuevo.isEmpty || nuevo == col.nombre || !mounted) return;
    final viejo = col.nombre;
    setState(() {
      for (final it in widget.lista.items) {
        if (it.preciosPorColumna.containsKey(viejo)) {
          it.preciosPorColumna[nuevo] = it.preciosPorColumna.remove(viejo)!;
        }
      }
      for (final c in widget.lista.columnas) {
        if (c.formula.columnaOrigen == viejo) c.formula.columnaOrigen = nuevo;
        if (c.formula.expresion.isNotEmpty) {
          c.formula.expresion =
              c.formula.expresion.replaceAll('[$viejo]', '[$nuevo]');
        }
      }
      col.nombre = nuevo;
    });
    _persistirLista();
    _guardarFormulasEnCache();
  }

  /// Elimina una columna (y sus precios) previa confirmación.
  Future<void> _eliminarColumna(ColumnaPrecio col) async {
    final dependientes = widget.lista.columnas
        .where((c) =>
            c.nombre != col.nombre &&
            (c.formula.columnaOrigen == col.nombre ||
                c.formula.expresion
                    .toLowerCase()
                    .contains('[${col.nombre.toLowerCase()}]')))
        .map((c) => c.nombre)
        .toList();
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text('Eliminar "${col.nombre}"'),
        content: Text(
            'Se borrarán los precios de esta columna en los '
            '${widget.lista.items.length} productos de la lista.'
            '${dependientes.isEmpty ? '' : '\n\n⚠ Estas columnas usan '
                '"${col.nombre}" en su función y dejarán de calcularse: '
                '${dependientes.join(", ")}.'}'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancelar')),
          ElevatedButton(
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('Eliminar')),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    setState(() {
      widget.lista.columnas.removeWhere((c) => c.nombre == col.nombre);
      for (final it in widget.lista.items) {
        it.preciosPorColumna.remove(col.nombre);
      }
    });
    _persistirLista();
    _guardarFormulasEnCache();
  }

  // ── Copia local de las funciones ────────────────────────────
  // El backend guarda las columnas por nombre; para que la
  // configuración no se pierda aunque el servidor recorte algo,
  // también la guardamos en el dispositivo y la reponemos al abrir
  // la lista si lo que llegó del servidor viene sin función.

  String get _claveCacheFormulas => 'formulas_columnas_${widget.lista.id}';

  Future<void> _guardarFormulasEnCache() async {
    if (widget.lista.id == null) return;
    try {
      final prefs = await SharedPreferences.getInstance();
      final mapa = {
        for (final c in widget.lista.columnas)
          if (!c.formula.esManual) c.nombre: c.formula.toJson()
      };
      if (mapa.isEmpty) {
        await prefs.remove(_claveCacheFormulas);
      } else {
        await prefs.setString(_claveCacheFormulas, jsonEncode(mapa));
      }
    } catch (e) {
      debugPrint('[ListaPrecio] No se pudo cachear las funciones: $e');
    }
  }

  Future<void> _restaurarFormulasDeCache() async {
    if (widget.lista.id == null) return;
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_claveCacheFormulas);
      if (raw == null || raw.isEmpty) return;
      final mapa = jsonDecode(raw);
      if (mapa is! Map) return;
      var repuestas = 0;
      for (final col in widget.lista.columnas) {
        if (!col.formula.esManual) continue; // el servidor sí la trajo
        final j = mapa[col.nombre];
        if (j is Map) {
          col.formula =
              FormulaColumna.fromJson(Map<String, dynamic>.from(j));
          repuestas++;
        }
      }
      if (repuestas > 0 && mounted) setState(() {});
    } catch (e) {
      debugPrint('[ListaPrecio] No se pudo leer el caché de funciones: $e');
    }
  }

  /// Persiste los cambios de precios al servidor. Se llama desde el
  /// botón "Guardar" del AppBar después de editar precios inline.
  /// Hace PUT si la lista ya tiene id, o POST si es nueva.
  Future<void> _guardarCambios() async {
    // Aviso de "guardando" inmediato
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Row(children: [
          SizedBox(width: 16, height: 16, child: CircularProgressIndicator(
              strokeWidth: 2, color: Colors.white)),
          SizedBox(width: 12),
          Text('Guardando cambios en el servidor...'),
        ]),
        duration: Duration(seconds: 10)));
    try {
      if (widget.lista.id != null) {
        await _Api.put('listas_precios', widget.lista.id.toString(),
            widget.lista.toMap());
      } else {
        final resp = await _Api.post('listas_precios', widget.lista.toMap());
        if (resp is Map && resp['id'] != null) {
          widget.lista.id = resp['id'] is int
              ? resp['id']
              : int.tryParse(resp['id'].toString());
        }
      }
      if (!mounted) return;
      ScaffoldMessenger.of(context).hideCurrentSnackBar();
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Row(children: [
            const Icon(Icons.check_circle, color: Colors.white, size: 18),
            const SizedBox(width: 8),
            Expanded(child: Text(
                '✅ Lista "${widget.lista.nombre}" guardada. '
                'Visible para todos los usuarios.')),
          ]),
          backgroundColor: AppColors.statusGreen,
          duration: const Duration(seconds: 3)));
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).hideCurrentSnackBar();
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text('Error al guardar: $e'),
          backgroundColor: AppColors.statusRed,
          duration: const Duration(seconds: 5)));
    }
  }

  void _editarPrecioItem(ItemListaPrecio item, String nombreColumna) {
    final priceCtrl = TextEditingController(
      text: (item.preciosPorColumna[nombreColumna] ?? 0.0).toStringAsFixed(2));
    showDialog(context: context, builder: (c) => AlertDialog(
      title: Text("Precio: ${item.producto.nombre}"),
      content: Column(mainAxisSize: MainAxisSize.min, children: [
        Text("Columna: $nombreColumna", style: const TextStyle(color: Colors.grey)),
        const SizedBox(height: 12),
        TextField(
          controller: priceCtrl,
          autofocus: true,
          keyboardType: TextInputType.numberWithOptions(decimal: true),
          decoration: InputDecoration(
            labelText: widget.lista.esEnBolivares ? "Precio (Bs)" : "Precio (\$)",
            prefixIcon: const Icon(Icons.attach_money))),
      ]),
      actions: [
        TextButton(onPressed: () => Navigator.pop(context), child: const Text("Cancelar")),
        ElevatedButton(
          onPressed: () {
            setState(() => item.preciosPorColumna[nombreColumna] =
                double.tryParse(priceCtrl.text) ?? 0.0);
            _persistirLista(); // sincronizar con backend
            Navigator.pop(context);
          },
          child: const Text("Guardar")),
      ]));
  }

  // Editar precio de TODA una columna de una vez (ajuste por porcentaje o valor fijo)
  void _editarColumnaCompleta(ColumnaPrecio col) {
    final porcentajeCtrl = TextEditingController();
    bool esPorcentaje = true;
    showDialog(context: context, builder: (ctx) => StatefulBuilder(
      builder: (ctx, setD) => AlertDialog(
        title: Text("Ajustar columna: ${col.nombre}"),
        content: Column(mainAxisSize: MainAxisSize.min, children: [
          if (!col.formula.esManual && col.formula.auto)
            Container(
              padding: const EdgeInsets.all(8),
              margin: const EdgeInsets.only(bottom: 8),
              decoration: BoxDecoration(
                color: Colors.orange.withValues(alpha: 0.12),
                borderRadius: BorderRadius.circular(6),
              ),
              child: Text(
                  '⚠ Esta columna se calcula sola con la función '
                  '"${col.formula.descripcion}". El ajuste que hagas acá '
                  'se perderá en el próximo recálculo. Si quieres que el '
                  'cambio sea permanente, edita la función de la columna.',
                  style: const TextStyle(fontSize: 11)),
            ),
          SwitchListTile(
            title: Text(esPorcentaje ? "Ajuste por porcentaje (%)" : "Valor fijo a sumar/restar"),
            value: esPorcentaje,
            onChanged: (v) => setD(() => esPorcentaje = v),
          ),
          TextField(
            controller: porcentajeCtrl,
            autofocus: true,
            keyboardType: TextInputType.numberWithOptions(decimal: true, signed: true),
            decoration: InputDecoration(
              labelText: esPorcentaje ? "Porcentaje (ej: 10 para +10%, -5 para -5%)" : "Valor a añadir/restar",
              prefixIcon: Icon(esPorcentaje ? Icons.percent : Icons.attach_money))),
        ]),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text("Cancelar")),
          ElevatedButton(
            onPressed: () {
              final val = double.tryParse(porcentajeCtrl.text);
              if (val == null) return;
              setState(() {
                for (final item in widget.lista.items) {
                  final actual = item.preciosPorColumna[col.nombre] ?? 0.0;
                  item.preciosPorColumna[col.nombre] = esPorcentaje
                      ? (actual * (1 + val / 100))
                      : (actual + val);
                }
              });
              _persistirLista(); // sincronizar con backend
              Navigator.pop(ctx);
              ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                content: Text("✅ ${widget.lista.items.length} precios actualizados en ${col.nombre}"),
                backgroundColor: AppColors.statusGreen));
            },
            child: const Text("Aplicar a todos")),
        ])));
  }

  // ════════════════════════════════════════════════════════════
  //  EDITOR MASIVO DE PRECIOS Y PORCENTAJES
  // ════════════════════════════════════════════════════════════

  /// Abre el editor masivo que permite seleccionar uno o varios
  /// productos de la lista y aplicar cambios de precio/porcentaje.
  ///
  /// Funcionalidad completa:
  ///   1. Lista todos los productos con checkboxes para selección
  ///   2. Botones rápidos "Todos" / "Ninguno" / "Invertir"
  ///   3. Buscador por nombre
  ///   4. Tipo de operación: SUMAR % (aditivo) o REEMPLAZAR (fijar valor)
  ///   5. Campo a modificar: Precio / Inicial / Cuota / N° cuotas
  ///   6. Aplica solo a los seleccionados
  ///   7. Persiste automáticamente al backend
  Future<void> _abrirEditorMasivo() async {
    if (!mounted) return;
    final lista = widget.lista;
    final esFinanc = lista.esFinanciamiento;

    // Estado del diálogo
    final seleccionados = <int>{}; // índices de items seleccionados
    String busqueda = "";
    final busquedaCtrl = TextEditingController();
    // Tipo de operación:
    //  - 'sumar_pct': sumar un % al valor actual (153 + 10% = 168.3)
    //  - 'restar_pct': restar un % (153 - 10% = 137.7)
    //  - 'reemplazar': poner un valor fijo
    //  - 'fijar_pct': fijar el % de la financiadora (inicial/recargo)
    //  - 'fijar_cuotas': cambiar el número de cuotas
    String tipoOp = 'sumar_pct';
    // Campo objetivo cuando es financiadora:
    //  - 'precio_base'
    //  - 'inicial'   (cambia el inicialManual)
    //  - 'cuota'     (cambia la cuotaManual)
    //  - 'inicial_pct'  (cambia el %inicial de TODA la lista)
    //  - 'recargo_pct'  (cambia el %recargo de TODA la lista)
    //  - 'n_cuotas'     (cambia número de cuotas de TODA la lista)
    String campoFinanc = 'precio_base';
    final valorCtrl = TextEditingController(text: "0");

    await showDialog<void>(
      context: context,
      barrierDismissible: false,
      builder: (ctx) => StatefulBuilder(builder: (ctx, setDlg) {
        // Filtrar items por búsqueda
        final indicesVisibles = <int>[];
        for (var i = 0; i < lista.items.length; i++) {
          final it = lista.items[i];
          final q = busqueda.toLowerCase().trim();
          if (q.isEmpty) {
            indicesVisibles.add(i);
            continue;
          }
          if (it.producto.nombre.toLowerCase().contains(q) ||
              it.producto.marca.toLowerCase().contains(q) ||
              it.producto.modelo.toLowerCase().contains(q) ||
              it.producto.codigo.toLowerCase().contains(q)) {
            indicesVisibles.add(i);
          }
        }
        return Dialog(
          shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(16)),
          insetPadding: const EdgeInsets.all(20),
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 700, maxHeight: 700),
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              // ── Header del diálogo ──
              Container(
                padding: const EdgeInsets.all(16),
                decoration: const BoxDecoration(
                  color: AppColors.royalBlue,
                  borderRadius: BorderRadius.vertical(
                      top: Radius.circular(16)),
                ),
                child: Row(children: [
                  const Icon(Icons.edit_attributes, color: Colors.white),
                  const SizedBox(width: 10),
                  Expanded(child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text('Editor Masivo de Precios',
                            style: TextStyle(
                                color: Colors.white,
                                fontSize: 17,
                                fontWeight: FontWeight.bold)),
                        Text(
                            '${seleccionados.length} de '
                            '${lista.items.length} seleccionados',
                            style: const TextStyle(
                                color: Colors.white70, fontSize: 12)),
                      ])),
                  IconButton(
                    icon: const Icon(Icons.close, color: Colors.white),
                    onPressed: () => Navigator.pop(ctx),
                  ),
                ]),
              ),
              // ── Configuración del cambio ──
              Container(
                padding: const EdgeInsets.all(14),
                color: AppColors.surfaceGrey,
                child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                  if (esFinanc) ...[
                    const Text('Campo a modificar:',
                        style: TextStyle(
                            fontWeight: FontWeight.bold, fontSize: 12)),
                    const SizedBox(height: 6),
                    Wrap(spacing: 6, runSpacing: 6, children: [
                      _chipCampo(setDlg, campoFinanc, 'precio_base',
                          'Precio base', Icons.attach_money,
                          (v) => campoFinanc = v),
                      _chipCampo(setDlg, campoFinanc, 'inicial',
                          'Inicial por prod.', Icons.payments,
                          (v) => campoFinanc = v),
                      if (lista.tieneCuotas)
                        _chipCampo(setDlg, campoFinanc, 'cuota',
                            'Cuota por prod.', Icons.calendar_month,
                            (v) => campoFinanc = v),
                      _chipCampo(setDlg, campoFinanc, 'inicial_pct',
                          '% inicial (toda la lista)', Icons.percent,
                          (v) => campoFinanc = v),
                      if (lista.tieneCuotas) ...[
                        _chipCampo(setDlg, campoFinanc, 'recargo_pct',
                            '% recargo (toda la lista)', Icons.trending_up,
                            (v) => campoFinanc = v),
                        _chipCampo(setDlg, campoFinanc, 'n_cuotas',
                            'N° cuotas (toda la lista)', Icons.format_list_numbered,
                            (v) => campoFinanc = v),
                      ],
                    ]),
                    const SizedBox(height: 12),
                  ],
                  const Text('Tipo de operación:',
                      style: TextStyle(
                          fontWeight: FontWeight.bold, fontSize: 12)),
                  const SizedBox(height: 6),
                  Wrap(spacing: 6, runSpacing: 6, children: [
                    // Si el campo es "% global" o "n_cuotas" SIEMPRE es fijar
                    if (esFinanc && (campoFinanc == 'inicial_pct' ||
                        campoFinanc == 'recargo_pct' ||
                        campoFinanc == 'n_cuotas')) ...[
                      _chipOp(setDlg, tipoOp, 'reemplazar',
                          'Establecer valor', Icons.swap_horiz,
                          (v) => tipoOp = v),
                    ] else ...[
                      _chipOp(setDlg, tipoOp, 'sumar_pct',
                          'Aumentar %', Icons.add_circle,
                          (v) => tipoOp = v),
                      _chipOp(setDlg, tipoOp, 'restar_pct',
                          'Disminuir %', Icons.remove_circle,
                          (v) => tipoOp = v),
                      _chipOp(setDlg, tipoOp, 'reemplazar',
                          'Reemplazar valor', Icons.swap_horiz,
                          (v) => tipoOp = v),
                    ],
                  ]),
                  const SizedBox(height: 10),
                  TextField(
                    controller: valorCtrl,
                    keyboardType: const TextInputType.numberWithOptions(
                        decimal: true),
                    decoration: InputDecoration(
                      labelText: _labelDelValor(tipoOp, campoFinanc, esFinanc),
                      hintText: _hintDelValor(tipoOp, campoFinanc),
                      prefixIcon: Icon(_iconoDelValor(tipoOp)),
                      border: const OutlineInputBorder(),
                      isDense: true,
                      filled: true,
                      fillColor: Colors.white,
                    ),
                  ),
                ]),
              ),
              // ── Solo para campos POR PRODUCTO mostramos la
              //    selección de productos. Si es % global / N° cuotas
              //    aplica a TODA la lista automáticamente.
              if (!esFinanc ||
                  (campoFinanc != 'inicial_pct' &&
                   campoFinanc != 'recargo_pct' &&
                   campoFinanc != 'n_cuotas'))
                Container(
                  padding: const EdgeInsets.symmetric(
                      horizontal: 14, vertical: 8),
                  color: AppColors.surfaceGrey,
                  child: Row(children: [
                    Expanded(child: TextField(
                      controller: busquedaCtrl,
                      decoration: const InputDecoration(
                        hintText: 'Buscar producto…',
                        prefixIcon: Icon(Icons.search, size: 20),
                        border: OutlineInputBorder(),
                        isDense: true,
                        filled: true,
                        fillColor: Colors.white,
                      ),
                      onChanged: (v) => setDlg(() => busqueda = v),
                    )),
                    const SizedBox(width: 8),
                    OutlinedButton.icon(
                      icon: const Icon(Icons.select_all, size: 16),
                      label: const Text('Todos', style: TextStyle(fontSize: 11)),
                      style: OutlinedButton.styleFrom(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 8, vertical: 4)),
                      onPressed: () => setDlg(() {
                        seleccionados.clear();
                        seleccionados.addAll(indicesVisibles);
                      }),
                    ),
                    const SizedBox(width: 4),
                    OutlinedButton.icon(
                      icon: const Icon(Icons.deselect, size: 16),
                      label: const Text('Ninguno', style: TextStyle(fontSize: 11)),
                      style: OutlinedButton.styleFrom(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 8, vertical: 4)),
                      onPressed: () => setDlg(() => seleccionados.clear()),
                    ),
                  ]),
                ),
              // ── Lista de productos con checkboxes ──
              if (!esFinanc ||
                  (campoFinanc != 'inicial_pct' &&
                   campoFinanc != 'recargo_pct' &&
                   campoFinanc != 'n_cuotas'))
                Expanded(child: ListView.builder(
                  itemCount: indicesVisibles.length,
                  itemBuilder: (c, i) {
                    final idx = indicesVisibles[i];
                    final item = lista.items[idx];
                    final marcado = seleccionados.contains(idx);
                    final colKey = lista.columnas.isNotEmpty
                        ? lista.columnas.first.nombre
                        : '';
                    final precio = item.preciosPorColumna[colKey] ?? 0.0;
                    return CheckboxListTile(
                      dense: true,
                      controlAffinity: ListTileControlAffinity.leading,
                      title: Text(item.producto.nombre,
                          style: const TextStyle(fontSize: 13)),
                      subtitle: Text(
                          '${item.producto.marca} · '
                          '${item.producto.modelo}'
                          '${esFinanc && item.inicialManual != null ? " · ✏️ inicial manual" : ""}'
                          '${esFinanc && item.cuotaManual != null ? " · ✏️ cuota manual" : ""}',
                          style: const TextStyle(fontSize: 11)),
                      secondary: Text(
                          '${lista.esEnBolivares ? "Bs " : "\$"}'
                          '${precio.toStringAsFixed(0)}',
                          style: const TextStyle(
                              fontWeight: FontWeight.bold,
                              fontSize: 13)),
                      value: marcado,
                      onChanged: (v) => setDlg(() {
                        if (v == true) {
                          seleccionados.add(idx);
                        } else {
                          seleccionados.remove(idx);
                        }
                      }),
                    );
                  },
                )),
              // ── Pie con botones de acción ──
              Container(
                padding: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: Colors.white,
                  border: Border(
                      top: BorderSide(color: Colors.grey[300]!)),
                  borderRadius: const BorderRadius.vertical(
                      bottom: Radius.circular(16)),
                ),
                child: Row(children: [
                  // Atajo "aplicar a TODOS sin necesidad de seleccionar"
                  if (!esFinanc ||
                      (campoFinanc != 'inicial_pct' &&
                       campoFinanc != 'recargo_pct' &&
                       campoFinanc != 'n_cuotas'))
                    TextButton.icon(
                      icon: const Icon(Icons.all_inclusive),
                      label: const Text('Aplicar a TODA la lista'),
                      onPressed: () => _ejecutarCambioMasivo(
                          ctx, null, tipoOp, campoFinanc,
                          valorCtrl.text),
                    ),
                  const Spacer(),
                  TextButton(
                      onPressed: () => Navigator.pop(ctx),
                      child: const Text('Cancelar')),
                  const SizedBox(width: 8),
                  ElevatedButton.icon(
                    icon: const Icon(Icons.check),
                    label: Text(
                        esFinanc && (campoFinanc == 'inicial_pct' ||
                            campoFinanc == 'recargo_pct' ||
                            campoFinanc == 'n_cuotas')
                            ? 'Aplicar'
                            : 'Aplicar a ${seleccionados.length} seleccionados'),
                    style: ElevatedButton.styleFrom(
                        backgroundColor: AppColors.royalBlue,
                        foregroundColor: Colors.white),
                    onPressed: (esFinanc && (campoFinanc == 'inicial_pct' ||
                            campoFinanc == 'recargo_pct' ||
                            campoFinanc == 'n_cuotas')) ||
                        seleccionados.isNotEmpty
                        ? () => _ejecutarCambioMasivo(
                            ctx, seleccionados.toList(), tipoOp,
                            campoFinanc, valorCtrl.text)
                        : null,
                  ),
                ]),
              ),
            ]),
          ),
        );
      }),
    );
    busquedaCtrl.dispose();
    valorCtrl.dispose();
  }

  /// Chip de selección de campo a editar (precio_base, inicial, etc.)
  Widget _chipCampo(
      void Function(void Function()) setDlg,
      String actual, String value, String label, IconData icono,
      void Function(String) onTap) {
    final activo = actual == value;
    return InkWell(
      onTap: () => setDlg(() => onTap(value)),
      borderRadius: BorderRadius.circular(20),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
        decoration: BoxDecoration(
          color: activo ? AppColors.royalBlue : Colors.white,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
              color: activo ? AppColors.royalBlue : Colors.grey[400]!),
        ),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          Icon(icono, size: 14,
              color: activo ? Colors.white : AppColors.textSecondary),
          const SizedBox(width: 5),
          Text(label,
              style: TextStyle(
                  fontSize: 11,
                  color: activo ? Colors.white : AppColors.textPrimary,
                  fontWeight: activo
                      ? FontWeight.bold
                      : FontWeight.normal)),
        ]),
      ),
    );
  }

  /// Chip de selección de tipo de operación
  Widget _chipOp(
      void Function(void Function()) setDlg,
      String actual, String value, String label, IconData icono,
      void Function(String) onTap) {
    final activo = actual == value;
    return InkWell(
      onTap: () => setDlg(() => onTap(value)),
      borderRadius: BorderRadius.circular(20),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
        decoration: BoxDecoration(
          color: activo ? AppColors.statusGreen : Colors.white,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
              color: activo ? AppColors.statusGreen : Colors.grey[400]!),
        ),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          Icon(icono, size: 14,
              color: activo ? Colors.white : AppColors.textSecondary),
          const SizedBox(width: 5),
          Text(label,
              style: TextStyle(
                  fontSize: 11,
                  color: activo ? Colors.white : AppColors.textPrimary,
                  fontWeight: activo
                      ? FontWeight.bold
                      : FontWeight.normal)),
        ]),
      ),
    );
  }

  /// Label dinámico del campo de valor según el tipo de operación
  String _labelDelValor(String tipoOp, String campo, bool esFinanc) {
    if (esFinanc && campo == 'n_cuotas') return 'Número de cuotas';
    if (esFinanc && campo == 'inicial_pct') return 'Nuevo % inicial';
    if (esFinanc && campo == 'recargo_pct') return 'Nuevo % recargo';
    if (tipoOp == 'sumar_pct') return 'Porcentaje a sumar (%)';
    if (tipoOp == 'restar_pct') return 'Porcentaje a restar (%)';
    return 'Nuevo valor';
  }

  /// Hint dinámico
  String _hintDelValor(String tipoOp, String campo) {
    if (campo == 'n_cuotas') return 'Ej: 6, 12';
    if (tipoOp == 'sumar_pct' || tipoOp == 'restar_pct') return 'Ej: 10';
    return 'Ej: 150';
  }

  IconData _iconoDelValor(String tipoOp) {
    if (tipoOp == 'sumar_pct') return Icons.percent;
    if (tipoOp == 'restar_pct') return Icons.percent;
    return Icons.numbers;
  }

  /// Ejecuta el cambio masivo en los productos.
  ///
  /// Si `indices == null` → aplica a TODOS los items de la lista.
  /// Si `indices` es una lista → aplica solo a esos índices.
  ///
  /// Maneja también los casos especiales de financiadora donde el
  /// cambio es a NIVEL DE LISTA (inicial_pct, recargo_pct, n_cuotas).
  void _ejecutarCambioMasivo(BuildContext ctx, List<int>? indices,
      String tipoOp, String campoFinanc, String valorStr) {
    final valor = double.tryParse(valorStr.replaceAll(',', '.')) ?? 0;
    if (valor == 0 &&
        !(tipoOp == 'reemplazar' && campoFinanc != 'n_cuotas')) {
      ScaffoldMessenger.of(ctx).showSnackBar(const SnackBar(
        content: Text('Ingresa un valor mayor a 0'),
        backgroundColor: Colors.orange));
      return;
    }
    final lista = widget.lista;
    final esFinanc = lista.esFinanciamiento;

    setState(() {
      // ─── CASO 1: cambio a nivel de LISTA (financ. solo) ───
      if (esFinanc) {
        if (campoFinanc == 'inicial_pct') {
          lista.porcentajeInicial = valor;
          Navigator.pop(ctx);
          _persistirLista();
          ScaffoldMessenger.of(context).showSnackBar(SnackBar(
            content: Text('✓ % inicial actualizado a $valor%'),
            backgroundColor: AppColors.statusGreen));
          return;
        }
        if (campoFinanc == 'recargo_pct') {
          lista.porcentajeRecargoCuotas = valor;
          Navigator.pop(ctx);
          _persistirLista();
          ScaffoldMessenger.of(context).showSnackBar(SnackBar(
            content: Text('✓ % recargo actualizado a $valor%'),
            backgroundColor: AppColors.statusGreen));
          return;
        }
        if (campoFinanc == 'n_cuotas') {
          lista.numeroCuotas = valor.toInt();
          Navigator.pop(ctx);
          _persistirLista();
          ScaffoldMessenger.of(context).showSnackBar(SnackBar(
            content: Text('✓ Número de cuotas actualizado a ${valor.toInt()}'),
            backgroundColor: AppColors.statusGreen));
          return;
        }
      }

      // ─── CASO 2: cambio POR PRODUCTO ───
      // Determinar la lista de items a modificar
      final itemsAModificar = indices == null
          ? List<int>.generate(lista.items.length, (i) => i)
          : indices;
      int modificados = 0;

      for (final idx in itemsAModificar) {
        if (idx < 0 || idx >= lista.items.length) continue;
        final item = lista.items[idx];
        final colKey = lista.columnas.isNotEmpty
            ? lista.columnas.first.nombre
            : '';
        final precioActual = item.preciosPorColumna[colKey] ?? 0.0;

        if (esFinanc && campoFinanc == 'inicial') {
          // Modificar inicial manual del item
          final actualInicial = lista.inicialDe(item, precioActual);
          double nuevo;
          if (tipoOp == 'sumar_pct') {
            nuevo = actualInicial * (1 + valor / 100);
          } else if (tipoOp == 'restar_pct') {
            nuevo = actualInicial * (1 - valor / 100);
          } else {
            nuevo = valor;
          }
          item.inicialManual = redondearPrecio(nuevo);
          modificados++;
        } else if (esFinanc && campoFinanc == 'cuota') {
          // Modificar cuota manual del item
          final actualCuota = lista.cuotaDe(item, precioActual);
          double nuevo;
          if (tipoOp == 'sumar_pct') {
            nuevo = actualCuota * (1 + valor / 100);
          } else if (tipoOp == 'restar_pct') {
            nuevo = actualCuota * (1 - valor / 100);
          } else {
            nuevo = valor;
          }
          item.cuotaManual = redondearPrecio(nuevo);
          modificados++;
        } else {
          // Cambio en precio base (caso general — listas normales y
          // financiadora con campo 'precio_base')
          for (final col in lista.columnas) {
            final actual = item.preciosPorColumna[col.nombre] ?? 0.0;
            double nuevo;
            if (tipoOp == 'sumar_pct') {
              nuevo = actual * (1 + valor / 100);
            } else if (tipoOp == 'restar_pct') {
              nuevo = actual * (1 - valor / 100);
            } else {
              nuevo = valor;
            }
            item.preciosPorColumna[col.nombre] = redondearPrecio(nuevo);
          }
          modificados++;
        }
      }
      Navigator.pop(ctx);
      _persistirLista();
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text('✓ $modificados producto'
            '${modificados == 1 ? '' : 's'} actualizado'
            '${modificados == 1 ? '' : 's'}'),
        backgroundColor: AppColors.statusGreen));
    });
  }

  /// Exporta la lista completa como una IMAGEN PNG compacta, en una
  /// sola "hoja larga" ideal para compartir por WhatsApp, Instagram
  /// o cualquier red social. La imagen agrupa todos los productos
  /// en filas compactas con encabezado de la tienda en la parte
  /// superior y precios en columnas.
  Future<void> _exportarImagen() async {
    if (!mounted) return;
    final lista = widget.lista;
    const anchoImg = 800.0;
    final filaAlto = 28.0;
    final headerAlto = 140.0;
    final altoImg = headerAlto +
        (lista.items.length * filaAlto) + 80;

    final boundaryKey = GlobalKey();

    // Mostrar overlay con vista a renderizar
    showDialog<void>(
      context: context,
      barrierDismissible: false,
      builder: (ctx) => Dialog(
        backgroundColor: Colors.transparent,
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          const Card(
            child: Padding(
              padding: EdgeInsets.all(20),
              child: Column(mainAxisSize: MainAxisSize.min, children: [
                CircularProgressIndicator(),
                SizedBox(height: 12),
                Text("Generando imagen…"),
              ]),
            ),
          ),
          Offstage(
            offstage: false,
            child: RepaintBoundary(
              key: boundaryKey,
              child: _construirWidgetParaImagen(lista, anchoImg, altoImg),
            ),
          ),
        ]),
      ),
    );

    await Future.delayed(const Duration(milliseconds: 500));

    try {
      final boundary = boundaryKey.currentContext?.findRenderObject()
          as RenderRepaintBoundary?;
      if (boundary == null) throw Exception("No se pudo renderizar");
      final image = await boundary.toImage(pixelRatio: 3.0);
      final byteData = await image.toByteData(format: ImageByteFormat.png);
      if (byteData == null) throw Exception("No se pudo convertir a PNG");
      final pngBytes = byteData.buffer.asUint8List();

      if (mounted) Navigator.of(context, rootNavigator: true).pop();

      final dir = await getTemporaryDirectory();
      final ts = DateTime.now().millisecondsSinceEpoch;
      final fileName = 'lista_${lista.nombre.replaceAll(RegExp(r"[^a-zA-Z0-9]"), "_")}_$ts.png';
      final file = File('${dir.path}/$fileName');
      await file.writeAsBytes(pngBytes);

      if (mounted) {
        await SharePlus.instance.share(ShareParams(
          files: [XFile(file.path)],
          text: 'Lista de Precios: ${lista.nombre}',
        ));
      }
    } catch (e) {
      debugPrint('[ListaPrecios._exportarImagen] error: $e');
      if (mounted) {
        Navigator.of(context, rootNavigator: true).pop();
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text('Error generando imagen: $e'),
          backgroundColor: Colors.red));
      }
    }
  }

  /// Construye el widget que se renderiza a imagen.
  Widget _construirWidgetParaImagen(
      ListaPrecio lista, double ancho, double alto) {
    final tienda = usuarioSesion?.tienda ?? '';
    final enc = ConfigSistema.encabezadoDe(tienda);
    final moneda = lista.esEnBolivares ? 'Bs' : '\$';
    final esFinanc = lista.esFinanciamiento;

    return Material(
      color: Colors.white,
      child: Container(
        width: ancho,
        color: Colors.white,
        child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          // Encabezado
          Container(
            padding: const EdgeInsets.all(16),
            decoration: const BoxDecoration(
              gradient: LinearGradient(
                colors: [AppColors.royalBlue, AppColors.primaryBlue],
                begin: Alignment.topLeft, end: Alignment.bottomRight),
            ),
            child: Row(children: [
              if (enc.logoBytes != null)
                Container(
                  width: 60, height: 60,
                  margin: const EdgeInsets.only(right: 12),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(10)),
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(9),
                    child: Image.memory(enc.logoBytes!, fit: BoxFit.contain),
                  ),
                ),
              Expanded(child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      ConfigSistema.nombreEmpresa.isEmpty
                          ? tienda
                          : ConfigSistema.nombreEmpresa,
                      style: const TextStyle(
                          color: Colors.white, fontSize: 20,
                          fontWeight: FontWeight.bold)),
                    if (enc.telefono.isNotEmpty)
                      Text("Tel: ${enc.telefono}",
                          style: const TextStyle(
                              color: Colors.white70, fontSize: 12)),
                    const SizedBox(height: 4),
                    Text(lista.nombre,
                        style: const TextStyle(
                            color: Colors.white, fontSize: 14,
                            fontWeight: FontWeight.w600)),
                    Text(
                        "${lista.categoria} · "
                        "${lista.items.length} productos · "
                        "${DateTime.now().toString().substring(0, 10)}",
                        style: const TextStyle(
                            color: Colors.white70, fontSize: 11)),
                  ])),
            ]),
          ),
          // Encabezado de columnas
          Container(
            color: AppColors.surfaceGrey,
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
            child: Row(children: [
              const Expanded(flex: 5, child: Text("Producto",
                  style: TextStyle(fontWeight: FontWeight.bold, fontSize: 12))),
              if (esFinanc) ...[
                Expanded(flex: 2, child: Text("Base",
                    textAlign: TextAlign.right,
                    style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 12))),
                Expanded(flex: 2, child: Text("Inicial",
                    textAlign: TextAlign.right,
                    style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 12))),
                if (lista.tieneCuotas)
                  Expanded(flex: 2, child: Text("Cuota",
                      textAlign: TextAlign.right,
                      style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 12))),
              ] else
                ...lista.columnas.map((col) => Expanded(flex: 2,
                    child: Text(col.nombre,
                        textAlign: TextAlign.right,
                        style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 12)))),
            ]),
          ),
          // Filas de productos
          ...lista.items.asMap().entries.map((entry) {
            final idx = entry.key;
            final item = entry.value;
            final esPar = idx % 2 == 0;
            final precioBase = lista.columnas.isNotEmpty
                ? (item.preciosPorColumna[lista.columnas.first.nombre] ?? 0.0)
                : 0.0;
            double inicial = 0;
            double cuota = 0;
            if (esFinanc) {
              inicial = lista.inicialDe(item, precioBase);
              if (lista.tieneCuotas) {
                cuota = lista.cuotaDe(item, precioBase);
              }
            }
            return Container(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 5),
              color: esPar ? Colors.white : Colors.grey[50],
              child: Row(children: [
                Expanded(flex: 5, child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(item.producto.nombre,
                          style: const TextStyle(
                              fontWeight: FontWeight.w600, fontSize: 12),
                          maxLines: 1, overflow: TextOverflow.ellipsis),
                      if (item.producto.modelo.isNotEmpty &&
                          item.producto.modelo != item.producto.nombre)
                        Text(item.producto.modelo,
                            style: const TextStyle(
                                fontSize: 10,
                                color: AppColors.textSecondary),
                            maxLines: 1, overflow: TextOverflow.ellipsis),
                    ])),
                if (esFinanc) ...[
                  Expanded(flex: 2, child: Text(
                      "$moneda${precioBase.toStringAsFixed(0)}",
                      textAlign: TextAlign.right,
                      style: const TextStyle(fontSize: 11))),
                  Expanded(flex: 2, child: Text(
                      "$moneda${inicial.toStringAsFixed(0)}",
                      textAlign: TextAlign.right,
                      style: const TextStyle(
                          fontSize: 11, fontWeight: FontWeight.bold,
                          color: AppColors.royalBlue))),
                  if (lista.tieneCuotas)
                    Expanded(flex: 2, child: Text(
                        "$moneda${cuota.toStringAsFixed(0)}",
                        textAlign: TextAlign.right,
                        style: const TextStyle(
                            fontSize: 11, color: Colors.green))),
                ] else
                  ...lista.columnas.map((col) {
                    final precio = item.preciosPorColumna[col.nombre] ?? 0.0;
                    return Expanded(flex: 2, child: Text(
                        "$moneda${precio.toStringAsFixed(0)}",
                        textAlign: TextAlign.right,
                        style: const TextStyle(
                            fontSize: 11, fontWeight: FontWeight.bold)));
                  }),
              ]),
            );
          }),
          // Pie
          Container(
            padding: const EdgeInsets.all(10),
            color: AppColors.surfaceGrey,
            child: Center(child: Text(
              "Precios sujetos a cambios sin previo aviso · "
              "Garantía: ${ConfigSistema.diasGarantia} días",
              style: const TextStyle(
                  fontSize: 10, fontStyle: FontStyle.italic,
                  color: AppColors.textSecondary))),
          ),
        ]),
      ),
    );
  }

  /// Genera y comparte un PDF de la lista de precios.
  ///
  /// REGLAS DE NEGOCIO IMPORTANTES:
  ///   1. **NUNCA** se muestra el stock disponible. Es info interna
  ///      del negocio que no debe llegar al cliente / financiadora.
  ///   2. Si la lista es de **financiamiento** (esFinanciamiento=true):
  ///      - NO se muestra el precio base del producto (la columna
  ///        principal de precio). Solo Inicial + Cuotas.
  ///      - La financiadora solo necesita saber "cuánto cuesta el
  ///        plan", no el desglose interno.
  ///   3. Si es lista **normal** (Detal / Mayorista / etc):
  ///      - Se muestran todas las columnas de precios configuradas.
  ///
  /// Después de generar el PDF, se muestra el diálogo nativo de
  /// compartir (`share_plus`) para que el usuario elija destino:
  /// WhatsApp, correo, descargar al disco, etc.
  Future<void> _exportarPdf() async {
    if (!mounted) return;

    // ── PUNTO 5: Preguntar si desea redondear los montos ──
    // Al aplicar un % los precios quedan con "picos" (ej 153.47).
    // Ofrecemos redondear para que las listas se vean limpias.
    int modoRedondeo = 0; // 0=sin redondeo, 1=entero, 2=decena, 3=centena
    final continuar = await showDialog<bool>(
      context: context,
      builder: (ctx) => StatefulBuilder(builder: (ctx, setD) {
        return AlertDialog(
          shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(14)),
          title: const Row(children: [
            Icon(Icons.tune, color: AppColors.royalBlue),
            SizedBox(width: 8),
            Text('Redondear montos'),
          ]),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text(
                'Al aplicar un porcentaje, los precios pueden quedar '
                'con cifras irregulares. Elige cómo redondear:',
                style: TextStyle(fontSize: 13),
              ),
              const SizedBox(height: 10),
              RadioListTile<int>(
                value: 0, groupValue: modoRedondeo,
                onChanged: (v) => setD(() => modoRedondeo = v!),
                title: const Text('Sin redondeo', style: TextStyle(fontSize: 13)),
                subtitle: const Text('Ej: 153.47', style: TextStyle(fontSize: 11)),
                dense: true, contentPadding: EdgeInsets.zero,
              ),
              RadioListTile<int>(
                value: 1, groupValue: modoRedondeo,
                onChanged: (v) => setD(() => modoRedondeo = v!),
                title: const Text('Al entero', style: TextStyle(fontSize: 13)),
                subtitle: const Text('Ej: 153', style: TextStyle(fontSize: 11)),
                dense: true, contentPadding: EdgeInsets.zero,
              ),
              RadioListTile<int>(
                value: 2, groupValue: modoRedondeo,
                onChanged: (v) => setD(() => modoRedondeo = v!),
                title: const Text('A la decena', style: TextStyle(fontSize: 13)),
                subtitle: const Text('Ej: 150', style: TextStyle(fontSize: 11)),
                dense: true, contentPadding: EdgeInsets.zero,
              ),
              RadioListTile<int>(
                value: 3, groupValue: modoRedondeo,
                onChanged: (v) => setD(() => modoRedondeo = v!),
                title: const Text('A la centena', style: TextStyle(fontSize: 13)),
                subtitle: const Text('Ej: 200', style: TextStyle(fontSize: 11)),
                dense: true, contentPadding: EdgeInsets.zero,
              ),
            ],
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(ctx, false),
                child: const Text('Cancelar')),
            ElevatedButton.icon(
              icon: const Icon(Icons.picture_as_pdf, size: 18),
              label: const Text('Generar PDF'),
              style: ElevatedButton.styleFrom(
                  backgroundColor: AppColors.royalBlue,
                  foregroundColor: Colors.white),
              onPressed: () => Navigator.pop(ctx, true),
            ),
          ],
        );
      }),
    );
    if (continuar != true) return;

    // Helper de redondeo según el modo elegido
    double redondear(double v) {
      switch (modoRedondeo) {
        case 1: return v.roundToDouble();
        case 2: return (v / 10).round() * 10.0;
        case 3: return (v / 100).round() * 100.0;
        default: return v;
      }
    }

    // 1) Mostrar indicador de carga
    if (!mounted) return;
    showDialog(
      context: context,
      barrierDismissible: false,
      builder: (_) => const Center(child: CircularProgressIndicator()),
    );

    try {
      final lista = widget.lista;
      final moneda = lista.esEnBolivares ? "Bs" : "\$";
      final esFinanc = lista.esFinanciamiento;
      final agrupados = _agrupadosPorMarca();

      // 2) Construir documento PDF
      final pdf = pw.Document();

      // Definir columnas según el tipo de lista:
      //   · Financiamiento: Producto | Inicial | Cuota
      //   · Normal:         Producto | Col1 | Col2 | ...
      // NUNCA aparece "Stock" — ni siquiera como columna.
      final List<String> headers = ['Producto'];
      if (esFinanc) {
        headers.add('Inicial');
        // Si hay condiciones por marca/modelo el número de cuotas ya
        // no es único, así que el encabezado no lo puede anunciar.
        final nUnif = lista.cuotasUniformes;
        headers.add(nUnif == null ? 'Cuota' : 'Cuota x$nUnif');
      } else {
        // Para listas normales, usar todas las columnas configuradas.
        // Filtramos las columnas virtuales (__inicial_manual__, etc.)
        // que se usan internamente para persistir overrides — no son
        // columnas reales para el cliente.
        for (final col in lista.columnas) {
          if (col.nombre.startsWith('__')) continue;
          headers.add(col.nombre);
        }
      }

      // 3) Página principal
      pdf.addPage(
        pw.MultiPage(
          pageFormat: PdfPageFormat.a4,
          margin: const pw.EdgeInsets.all(24),
          build: (ctx) {
            final widgets = <pw.Widget>[];

            // ── Encabezado con info de la tienda ──
            // Identifica el PDF cuando se comparte en redes. Combina:
            //   · Nombre de la empresa (si está configurado)
            //   · Tienda específica del usuario (Principal/Sucursal)
            //   · Teléfono / WhatsApp para que clientes contacten
            //
            // Siempre se muestra el bloque — aunque no haya empresa
            // configurada, usamos un nombre genérico de TecnoLider.
            final nombreTienda = ConfigSistema.nombreEmpresa.trim().isNotEmpty
                ? ConfigSistema.nombreEmpresa.trim()
                : 'TECNO LÍDER';
            final tiendaUsuario = (usuarioSesion?.tienda ?? '').trim();
            final telTienda = ConfigBDV.telefonoComercio.trim();
            final vendedor = (usuarioSesion?.nombre ?? '').trim();

            widgets.add(pw.Container(
              width: double.infinity,
              padding: const pw.EdgeInsets.symmetric(
                  horizontal: 14, vertical: 12),
              decoration: pw.BoxDecoration(
                gradient: const pw.LinearGradient(
                  colors: [
                    PdfColor.fromInt(0xFF1F2270),
                    PdfColor.fromInt(0xFF3949AB),
                  ],
                  begin: pw.Alignment.centerLeft,
                  end: pw.Alignment.centerRight,
                ),
                borderRadius: pw.BorderRadius.circular(8),
              ),
              child: pw.Row(
                crossAxisAlignment: pw.CrossAxisAlignment.center,
                children: [
                  // "Logo" textual (un círculo con la inicial)
                  pw.Container(
                    width: 48,
                    height: 48,
                    decoration: pw.BoxDecoration(
                      color: const PdfColor.fromInt(0xFFFFC20E),
                      shape: pw.BoxShape.circle,
                    ),
                    alignment: pw.Alignment.center,
                    child: pw.Text(
                      nombreTienda.substring(0, 1).toUpperCase(),
                      style: pw.TextStyle(
                        fontSize: 26,
                        fontWeight: pw.FontWeight.bold,
                        color: const PdfColor.fromInt(0xFF1F2270),
                      ),
                    ),
                  ),
                  pw.SizedBox(width: 14),
                  // Info de la tienda
                  pw.Expanded(
                    child: pw.Column(
                      crossAxisAlignment: pw.CrossAxisAlignment.start,
                      children: [
                        pw.Text(
                          nombreTienda,
                          style: pw.TextStyle(
                            fontSize: 20,
                            fontWeight: pw.FontWeight.bold,
                            color: PdfColors.white,
                            letterSpacing: 1,
                          ),
                        ),
                        if (tiendaUsuario.isNotEmpty) ...[
                          pw.SizedBox(height: 2),
                          pw.Text(
                            tiendaUsuario,
                            style: const pw.TextStyle(
                              fontSize: 11,
                              color: PdfColors.white,
                            ),
                          ),
                        ],
                        if (telTienda.isNotEmpty) ...[
                          pw.SizedBox(height: 2),
                          pw.Text(
                            'Tel / WhatsApp: $telTienda',
                            style: const pw.TextStyle(
                              fontSize: 10,
                              color: PdfColors.white,
                            ),
                          ),
                        ],
                      ],
                    ),
                  ),
                  // Asesor / vendedor que generó la lista
                  if (vendedor.isNotEmpty)
                    pw.Container(
                      padding: const pw.EdgeInsets.symmetric(
                          horizontal: 8, vertical: 4),
                      decoration: pw.BoxDecoration(
                        color: PdfColors.white.shade(0.15),
                        borderRadius: pw.BorderRadius.circular(4),
                      ),
                      child: pw.Column(
                        crossAxisAlignment: pw.CrossAxisAlignment.end,
                        children: [
                          pw.Text(
                            'Asesor',
                            style: const pw.TextStyle(
                              fontSize: 8,
                              color: PdfColors.white,
                            ),
                          ),
                          pw.Text(
                            vendedor,
                            style: pw.TextStyle(
                              fontSize: 10,
                              fontWeight: pw.FontWeight.bold,
                              color: PdfColors.white,
                            ),
                          ),
                        ],
                      ),
                    ),
                ],
              ),
            ));
            widgets.add(pw.SizedBox(height: 14));

            // ── Encabezado ──
            widgets.add(pw.Center(
              child: pw.Text(
                lista.nombre,
                style: pw.TextStyle(
                    fontSize: 20, fontWeight: pw.FontWeight.bold),
              ),
            ));
            widgets.add(pw.SizedBox(height: 4));
            widgets.add(pw.Center(
              child: pw.Text(
                '${lista.categoria} · '
                '${lista.marcaFiltro == "Todas" ? "Todas las marcas" : lista.marcaFiltro} · '
                '$moneda'
                '${esFinanc ? " · ${lista.financiadora ?? "Financiamiento"}" : ""}',
                style: const pw.TextStyle(
                    fontSize: 11, color: PdfColors.grey700),
              ),
            ));
            widgets.add(pw.SizedBox(height: 2));
            widgets.add(pw.Center(
              child: pw.Text(
                'Generada: ${DateTime.now().toString().substring(0, 16)}',
                style: const pw.TextStyle(
                    fontSize: 9, color: PdfColors.grey600),
              ),
            ));
            widgets.add(pw.SizedBox(height: 16));

            // ── Tabla por marca ──
            for (final entry in agrupados.entries) {
              final marca = entry.key;
              final items = entry.value;

              // Título de la sección (marca)
              widgets.add(pw.Container(
                width: double.infinity,
                color: PdfColors.blue50,
                padding: const pw.EdgeInsets.symmetric(
                    horizontal: 6, vertical: 4),
                child: pw.Text(
                  marca,
                  style: pw.TextStyle(
                      fontSize: 12,
                      fontWeight: pw.FontWeight.bold,
                      color: PdfColors.blue900),
                ),
              ));

              // Construir filas de la tabla
              final filas = <List<String>>[];
              for (final item in items) {
                final fila = <String>[];

                // Columna 1: nombre del producto (con modelo si aplica)
                // PUNTO 3: evitar que salga "nombre modelo" repetido.
                // Si el nombre del producto YA contiene el modelo (caso
                // muy común: nombre="TECNO SPARK 20" modelo="SPARK 20"),
                // no lo concatenamos otra vez.
                final nombreProd = item.producto.nombre.trim();
                final modeloProd = item.producto.modelo.trim();
                final String nombreCompleto;
                if (modeloProd.isEmpty ||
                    nombreProd.toLowerCase().contains(modeloProd.toLowerCase())) {
                  // El nombre ya incluye el modelo (o no hay modelo)
                  nombreCompleto = nombreProd;
                } else {
                  nombreCompleto = '$nombreProd $modeloProd';
                }
                fila.add(nombreCompleto);

                // Columnas de precios según tipo de lista
                if (esFinanc) {
                  // Cálculo de inicial + cuota.
                  // Tomamos el primer precio definido (la columna
                  // principal de la financiadora) como base.
                  double precioBase = 0;
                  for (final col in lista.columnas) {
                    if (col.nombre.startsWith('__')) continue;
                    precioBase = item.preciosPorColumna[col.nombre] ?? 0;
                    if (precioBase > 0) break;
                  }

                  // Inicial y cuota salen de los mismos helpers que
                  // usa la pantalla, así que respetan tanto los montos
                  // fijados a mano como el % y las cuotas propias de
                  // esa marca o ese modelo.
                  final inicial = lista.inicialDe(item, precioBase);
                  final cuota = lista.cuotaDe(item, precioBase);

                  // NO mostramos el precio base — solo inicial + cuota
                  fila.add('$moneda ${redondear(inicial).toStringAsFixed(2)}');
                  fila.add('$moneda ${redondear(cuota).toStringAsFixed(2)}');
                } else {
                  // Lista normal: una celda por columna real
                  for (final col in lista.columnas) {
                    if (col.nombre.startsWith('__')) continue;
                    final precio = item.preciosPorColumna[col.nombre] ?? 0;
                    fila.add('$moneda ${redondear(precio).toStringAsFixed(2)}');
                  }
                }

                filas.add(fila);
              }

              // Tabla con encabezado + filas
              widgets.add(pw.Table.fromTextArray(
                headers: headers,
                data: filas,
                cellAlignment: pw.Alignment.centerLeft,
                cellAlignments: {
                  for (var i = 1; i < headers.length; i++)
                    i: pw.Alignment.centerRight,
                },
                headerStyle: pw.TextStyle(
                    fontWeight: pw.FontWeight.bold,
                    fontSize: 10,
                    color: PdfColors.white),
                headerDecoration: const pw.BoxDecoration(
                    color: PdfColors.blueGrey700),
                cellStyle: const pw.TextStyle(fontSize: 9),
                cellPadding: const pw.EdgeInsets.symmetric(
                    horizontal: 5, vertical: 3),
                border: pw.TableBorder.all(
                    color: PdfColors.grey400, width: 0.5),
              ));

              widgets.add(pw.SizedBox(height: 10));
            }

            return widgets;
          },
        ),
      );

      // 4) Generar bytes y compartir
      final bytes = await pdf.save();

      // Cerrar el indicador de carga ANTES de compartir
      if (mounted) Navigator.of(context).pop();

      // Nombre de archivo amigable
      final nombreArch = 'lista_precios_${lista.nombre}_'
          '${DateTime.now().toString().substring(0, 10)}.pdf'
          .replaceAll(RegExp(r'[^a-zA-Z0-9._-]+'), '_');

      // Diálogo nativo de compartir → WhatsApp, correo, descargar...
      await Printing.sharePdf(bytes: bytes, filename: nombreArch);
    } catch (e) {
      // Cerrar el indicador si quedó abierto
      if (mounted) Navigator.of(context).pop();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text('Error al generar PDF: $e'),
          backgroundColor: AppColors.statusRed,
        ));
      }
      debugPrint('[ListaPrecios._exportarPdf] error: $e');
    }
  }

  @override
  Widget build(BuildContext context) {
    final agrupados = _agrupadosPorMarca();
    final moneda = widget.lista.esEnBolivares ? "Bs" : "\$";
    // Administrador, Dueño y Maestro pueden crear/editar listas de precios.
    // Otros roles las ven en modo lectura.
    final esAdmin = (usuarioSesion?.rol == "Administrador" ||
                     usuarioSesion?.rol == "Dueño" ||
                     usuarioSesion?.rol == "Maestro");
    // Editor masivo de precios — Admin, Dueño, Maestro Y Gerente
    final puedeEditarPorcentajes = esAdmin ||
        usuarioSesion?.rol == "Gerente";

    return Scaffold(
      appBar: AppBar(
        title: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text(widget.lista.nombre, style: const TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
          Row(children: [
            Expanded(child: Text(
              "${widget.lista.categoria} · ${widget.lista.marcaFiltro == 'Todas' ? 'Todas las marcas' : widget.lista.marcaFiltro} · $moneda"
              "${widget.lista.esFinanciamiento ? ' · ${widget.lista.financiadora ?? 'Financiamiento'}${widget.lista.tieneCuotas ? ' · ${widget.lista.numeroCuotas} cuotas' : ' · sin cuotas'}' : ''}",
              style: const TextStyle(fontSize: 11, color: Colors.white70))),
            if (_guardandoBackend) ...[
              const SizedBox(width: 6),
              const SizedBox(
                width: 10, height: 10,
                child: CircularProgressIndicator(
                  strokeWidth: 1.5,
                  valueColor: AlwaysStoppedAnimation<Color>(Colors.white70),
                ),
              ),
              const SizedBox(width: 4),
              const Text('Guardando…',
                  style: TextStyle(fontSize: 10, color: Colors.white70,
                    fontStyle: FontStyle.italic)),
            ],
          ]),
        ]),
        backgroundColor: AppColors.royalBlue,
        actions: [
          if (esAdmin) ...[
            // ── Guardar cambios en el servidor ────────────────
            // Botón prominente para persistir los precios editados
            // inline. Sin este botón, los cambios solo quedan en
            // memoria y se pierden al cerrar la pantalla.
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 8),
              child: ElevatedButton.icon(
                style: ElevatedButton.styleFrom(
                  backgroundColor: AppColors.statusGreen,
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(horizontal: 12),
                ),
                icon: const Icon(Icons.save, size: 16),
                label: const Text('Guardar',
                    style: TextStyle(fontSize: 13, fontWeight: FontWeight.bold)),
                onPressed: () => _guardarCambios(),
              ),
            ),
            // ── Columnas ──────────────────────────────────────
            // Un solo boton para no saturar la barra en pantallas
            // chicas: crear una columna nueva (con su funcion) y
            // recalcular las que ya tienen funcion.
            PopupMenuButton<String>(
              icon: const Icon(Icons.view_column),
              tooltip: "Columnas de precio",
              onSelected: (v) {
                if (v == 'nueva') {
                  _anadirColumna();
                } else if (v == 'aplicar') {
                  _aplicarTodasLasFormulas();
                }
              },
              itemBuilder: (_) => const [
                PopupMenuItem(
                  value: 'nueva',
                  child: ListTile(
                    dense: true,
                    contentPadding: EdgeInsets.zero,
                    leading: Icon(Icons.add),
                    title: Text('Nueva columna'),
                    subtitle: Text('Con función configurable'),
                  ),
                ),
                PopupMenuItem(
                  value: 'aplicar',
                  child: ListTile(
                    dense: true,
                    contentPadding: EdgeInsets.zero,
                    leading: Icon(Icons.functions),
                    title: Text('Aplicar funciones'),
                    subtitle: Text('Recalcula las columnas con función'),
                  ),
                ),
              ],
            ),
            IconButton(
              icon: const Icon(Icons.add_shopping_cart),
              tooltip: "Agregar productos manualmente",
              onPressed: () => Navigator.push(context,
                MaterialPageRoute(builder: (_) => SelectorProductosLista(lista: widget.lista)))
                .then((_) => setState(() {}))),
            IconButton(
              icon: const Icon(Icons.sync),
              tooltip: "Re-poblar automáticamente",
              onPressed: () => showDialog(context: context, builder: (ctx) => AlertDialog(
                title: const Text("Re-poblar lista"),
                content: const Text("¿Actualizar todos los productos automáticamente desde el catálogo?\n\nLos precios editados manualmente se resetearán."),
                actions: [
                  TextButton(onPressed: () => Navigator.pop(ctx), child: const Text("Cancelar")),
                  ElevatedButton.icon(
                    icon: const Icon(Icons.sync),
                    label: const Text("Actualizar"),
                    onPressed: () {
                      // Actualizar la tasa si usa BCV
                      if (widget.lista.esEnBolivares && TasaBCVScheduler.ultimaTasa != null) {
                        widget.lista.tasaDelDia = ConfigSistema.tasaCambio;
                      }
                      setState(() {
                        // Re-poblar usando la lógica de VentanaListasPrecios
                        final tasa = widget.lista.esEnBolivares ? ConfigSistema.tasaCambio : 1.0;
                        final filtrados = catalogoGlobal.where((p) {
                          final catOk = widget.lista.categoria == "Todos" || p.categoria == widget.lista.categoria;
                          final marcaOk = widget.lista.marcaFiltro == "Todas" ||
                              p.marca.toLowerCase() == widget.lista.marcaFiltro.toLowerCase();
                          return catOk && marcaOk;
                        }).toList()
                          ..sort((a, b) {
                            final mc = a.marca.toLowerCase().compareTo(b.marca.toLowerCase());
                            return mc != 0 ? mc : a.nombre.toLowerCase().compareTo(b.nombre.toLowerCase());
                          });
                        widget.lista.items.clear();
                        for (final p in filtrados) {
                          final stock = CategoriasProductos.usaIMEI(p.categoria)
                              ? stockImeiGlobal.where((i) => i.producto.codigo == p.codigo && !i.vendido).length
                              : p.stockManual;
                          final precioBase = widget.lista.esEnBolivares ? (p.precioVenta * tasa) : p.precioVenta;
                          widget.lista.items.add(ItemListaPrecio(
                            producto: p,
                            stockDisponible: stock,
                            preciosPorColumna: { for (var col in widget.lista.columnas) col.nombre: precioBase },
                          ));
                        }
                        // Las columnas con funcion mandan sobre el
                        // precio heredado del catalogo.
                        widget.lista.aplicarFormulas();
                      });
                      Navigator.pop(ctx);
                      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                        content: Text("✅ ${widget.lista.items.length} productos actualizados"),
                        backgroundColor: AppColors.statusGreen));
                    }),
                ],
              ))),
          ],
          // ── Botón "Descargar PDF" — para TODOS los roles ──
          // Genera un PDF de la lista que el usuario puede compartir/
          // descargar (WhatsApp, correo, guardar). Reglas:
          //   · NUNCA muestra el stock de los productos (info interna).
          //   · Si es lista de financiadora: NO muestra el precio base
          //     del producto, solo inicial + cuotas (las financiadoras
          //     no deben ver el precio base, solo lo que pagan).
          //   · Si es lista normal: muestra todas las columnas de precios.
          IconButton(
            icon: const Icon(Icons.picture_as_pdf),
            tooltip: 'Descargar como PDF',
            onPressed: _exportarPdf,
          ),
          // ── Exportar como IMAGEN compacta ──
          // Genera un PNG todo en una sola "hoja" para compartir
          // por WhatsApp/redes sociales. Lista agrupada compacta.
          IconButton(
            icon: const Icon(Icons.image),
            tooltip: 'Descargar como Imagen (compacta para compartir)',
            onPressed: _exportarImagen,
          ),
          // ── EDITOR MASIVO DE PRECIOS Y PORCENTAJES ──
          // Solo Admin/Dueño/Gerente/Maestro pueden editar precios y
          // porcentajes masivamente. Abre un diálogo con la lista de
          // productos y permite:
          //   · Editar UN solo producto (precio individual)
          //   · Editar VARIOS productos seleccionados con checkbox
          //   · Aplicar el cambio a TODOS los productos
          //   · Modo aditivo (sumar/multiplicar) o de reemplazo
          // En listas de financiadora también permite editar el %
          // inicial, % de recargo y número de cuotas.
          // ── Condiciones por marca / modelo ──
          // El % de inicial y el número de cuotas de arriba valen
          // para toda la lista; acá se le fijan condiciones propias a
          // marcas o modelos puntuales.
          if (puedeEditarPorcentajes && widget.lista.esFinanciamiento)
            IconButton(
              icon: const Icon(Icons.tune),
              tooltip: 'Inicial y cuotas por marca o modelo',
              onPressed: () async {
                final cambio = await ajustarCondicionesPorMarcaModelo(
                    context, widget.lista);
                if (!cambio || !mounted) return;
                setState(() {});
                _persistirLista();
                ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
                  content: Text('✓ Condiciones actualizadas'),
                  backgroundColor: AppColors.statusGreen));
              },
            ),
          if (puedeEditarPorcentajes)
            IconButton(
              icon: const Icon(Icons.edit_attributes),
              tooltip: 'Editor masivo de precios y porcentajes',
              onPressed: _abrirEditorMasivo,
            ),
        ],
      ),
      body: widget.lista.items.isEmpty
          ? Center(child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
              const CircularProgressIndicator(),
              const SizedBox(height: 16),
              const Text("Cargando productos...",
                  style: TextStyle(fontSize: 14, color: Colors.grey)),
              const SizedBox(height: 4),
              Text(
                  "Categoría: ${widget.lista.categoria} · Marca: ${widget.lista.marcaFiltro}",
                  style: const TextStyle(fontSize: 11, color: Colors.grey)),
              const SizedBox(height: 16),
              if (esAdmin) TextButton.icon(
                icon: const Icon(Icons.refresh, size: 18),
                label: const Text("Recargar manualmente"),
                onPressed: _autoPoblar,
              ),
            ]))
          : Column(children: [
              // Barra de búsqueda
              Padding(
                padding: const EdgeInsets.fromLTRB(12, 10, 12, 4),
                child: TextField(
                  controller: _searchCtrl,
                  decoration: InputDecoration(
                    hintText: "Buscar producto o marca...",
                    prefixIcon: const Icon(Icons.search),
                    suffixIcon: _busqueda.isNotEmpty
                        ? IconButton(icon: const Icon(Icons.clear), onPressed: () => setState(() { _busqueda = ""; _searchCtrl.clear(); }))
                        : null, isDense: true,
                    contentPadding: const EdgeInsets.symmetric(vertical: 10)),
                  onChanged: (v) => setState(() => _busqueda = v)),
              ),

              // Encabezado de columnas (sticky)
              if (widget.lista.columnas.isNotEmpty)
                Container(
                  color: AppColors.royalBlue.withValues(alpha: 0.08),
                  padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                  child: Row(children: [
                    const Expanded(flex: 3, child: Text("PRODUCTO", style: TextStyle(fontSize: 10, fontWeight: FontWeight.bold, color: Colors.grey))),
                    const SizedBox(width: 4),
                    const Text("STOCK", style: TextStyle(fontSize: 10, fontWeight: FontWeight.bold, color: Colors.grey)),
                    if (widget.lista.esFinanciamiento) ...[
                      const Expanded(flex: 2, child: Text("BASE", textAlign: TextAlign.right,
                        style: TextStyle(fontSize: 10, fontWeight: FontWeight.bold, color: AppColors.primaryBlue))),
                      const Expanded(flex: 2, child: Text("INICIAL", textAlign: TextAlign.right,
                        style: TextStyle(fontSize: 10, fontWeight: FontWeight.bold, color: Colors.orange))),
                      const Expanded(flex: 2, child: Text("CUOTA", textAlign: TextAlign.right,
                        style: TextStyle(fontSize: 10, fontWeight: FontWeight.bold, color: AppColors.royalBlue))),
                      // Columnas EXTRA de una lista de financiamiento.
                      // La primera columna es el precio base (ya sale
                      // arriba como BASE); de la segunda en adelante son
                      // columnas que agrego el usuario y antes no se
                      // veian en ningun lado — parecia que el sistema no
                      // dejaba agregarlas.
                      ..._encabezadosColumnas(
                          widget.lista.columnas.skip(1), esAdmin),
                    ] else
                      ..._encabezadosColumnas(widget.lista.columnas, esAdmin),
                    if (esAdmin) const SizedBox(width: 32),
                  ]),
                ),

              // Lista agrupada por marca
              Expanded(
                child: ListView.builder(
                  padding: const EdgeInsets.only(bottom: 20),
                  itemCount: agrupados.length,
                  itemBuilder: (ctx, marcaIdx) {
                    final marca = agrupados.keys.elementAt(marcaIdx);
                    final items = agrupados[marca]!;
                    return Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        // Cabecera de marca
                        Container(
                          width: double.infinity,
                          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
                          color: AppColors.royalBlue.withValues(alpha: 0.06),
                          child: Row(children: [
                            const Icon(Icons.business, size: 14, color: AppColors.royalBlue),
                            const SizedBox(width: 6),
                            Text(marca, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 13, color: AppColors.royalBlue)),
                            const SizedBox(width: 8),
                            Text("(${items.length} modelos)", style: const TextStyle(fontSize: 11, color: Colors.grey)),
                          ]),
                        ),
                        // Ítems de esa marca
                        ...items.map((item) => _buildItemRow(item, esAdmin, moneda)),
                      ],
                    );
                  },
                ),
              ),
            ]),
    );
  }

  /// Encabezados de las columnas de precio. Al tocarlos (si es admin)
  /// se abre el menu de la columna: configurar su funcion, aplicarla,
  /// ajustar precios, renombrar o eliminar.
  List<Widget> _encabezadosColumnas(
      Iterable<ColumnaPrecio> columnas, bool esAdmin) {
    return columnas
        .map((col) => Expanded(
              flex: 2,
              child: GestureDetector(
                onTap: esAdmin ? () => _menuColumna(col) : null,
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.end,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Row(mainAxisAlignment: MainAxisAlignment.end, children: [
                      Flexible(
                          child: Text(col.nombre.toUpperCase(),
                              style: const TextStyle(
                                  fontSize: 10,
                                  fontWeight: FontWeight.bold,
                                  color: AppColors.primaryBlue),
                              overflow: TextOverflow.ellipsis,
                              textAlign: TextAlign.right)),
                      if (!col.formula.esManual)
                        const Icon(Icons.functions,
                            size: 10, color: AppColors.statusGreen),
                      if (esAdmin)
                        const Icon(Icons.more_vert,
                            size: 10, color: AppColors.primaryBlue),
                    ]),
                    if (!col.formula.esManual)
                      Text(col.formula.descripcion,
                          style: const TextStyle(
                              fontSize: 8, color: Colors.black54),
                          overflow: TextOverflow.ellipsis,
                          textAlign: TextAlign.right),
                  ],
                ),
              ),
            ))
        .toList();
  }

  /// Celdas de precio de [item] para las [columnas] indicadas.
  ///
  /// Si la columna tiene una funcion AUTOMATICA el precio no se edita
  /// a mano (se recalcularia solo): la celda se muestra en modo lectura
  /// con el icono de funcion y al tocarla se abre su configuracion.
  List<Widget> _celdasColumnas(ItemListaPrecio item, bool esAdmin,
      String moneda, Iterable<ColumnaPrecio> columnas) {
    return columnas.map((col) {
      final valor = item.preciosPorColumna[col.nombre] ?? 0.0;
      final calculada = !col.formula.esManual && col.formula.auto;
      return Padding(
        padding: const EdgeInsets.symmetric(horizontal: 3),
        child: SizedBox(
          width: 90,
          child: _CeldaConEtiqueta(
            etiqueta: calculada ? 'ƒ ${col.nombre}' : col.nombre,
            colorEtiqueta:
                calculada ? AppColors.statusGreen : AppColors.primaryBlue,
            child: esAdmin && !calculada
                ? _CeldaPrecioInline(
                    key: ValueKey('${item.producto.codigo}-${col.nombre}'),
                    valor: valor,
                    moneda: moneda,
                    onCambio: (v) {
                      setState(() {
                        item.preciosPorColumna[col.nombre] = v;
                        // Si otras columnas se calculan a partir de
                        // esta, se actualizan al instante.
                        widget.lista.aplicarFormulas();
                      });
                      _persistirLista(); // sincronizar con backend
                    },
                  )
                : GestureDetector(
                    onTap: esAdmin && calculada
                        ? () => _menuColumna(col)
                        : null,
                    child: Text(
                      "$moneda ${valor.toStringAsFixed(2)}",
                      textAlign: TextAlign.right,
                      style: TextStyle(
                          fontSize: 13,
                          fontWeight: FontWeight.bold,
                          color: calculada
                              ? AppColors.statusGreen
                              : AppColors.primaryBlue),
                    ),
                  ),
          ),
        ),
      );
    }).toList();
  }

  Widget _buildItemRow(ItemListaPrecio item, bool esAdmin, String moneda) {
    final stockOk = item.stockDisponible > 0;
    final esFinanc = widget.lista.esFinanciamiento;

    // ── Cálculo de valores de financiamiento ─────────────────
    // Si el item tiene `inicialManual` o `cuotaManual` con valor, usamos
    // ese override; si no, calculamos automáticamente desde el precio
    // base y los % de la lista.
    double precioBase = 0;
    double inicialCalculada = 0;
    double cuotaCalculada = 0;
    if (esFinanc && widget.lista.columnas.isNotEmpty) {
      precioBase = item.preciosPorColumna[widget.lista.columnas.first.nombre] ?? 0.0;
      // Redondeo EXACTO a 2 decimales (no hacia arriba) para que la
      // conversión Bs sea precisa sin sumar centavos de más.
      // El % de inicial y el número de cuotas salen de las
      // condiciones de ESTE producto: pueden ser propias de su marca
      // o de su modelo, no necesariamente las generales de la lista.
      inicialCalculada = redondearPrecio(
          precioBase * (widget.lista.pctInicialDe(item) / 100));
      // Cuota solo si la financiadora maneja cuotas
      if (widget.lista.tieneCuotas) {
        final resto = precioBase - inicialCalculada;
        final totalConRecargo =
            resto * (1 + widget.lista.porcentajeRecargoCuotas / 100);
        final nCuotasItem = widget.lista.cuotasDe(item);
        final nCuotas = nCuotasItem > 0 ? nCuotasItem : 1;
        cuotaCalculada = redondearPrecio(totalConRecargo / nCuotas);
      }
    }
    // Valores efectivos a mostrar (manual si existe, sino calculado)
    final inicial = item.inicialManual ?? inicialCalculada;
    final cuota = item.cuotaManual ?? cuotaCalculada;
    final inicialEsManual = item.inicialManual != null;
    final cuotaEsManual = item.cuotaManual != null;

    return Container(
      decoration: BoxDecoration(
        color: Colors.white,
        border: Border(bottom: BorderSide(color: Colors.grey[200]!, width: 0.5))),
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
      child: Row(crossAxisAlignment: CrossAxisAlignment.center, children: [
        // ── Nombre y código del producto ─────────────────────
        // En modo solo lectura — el nombre y SKU del producto se
        // editan en el módulo de Catálogo, no acá.
        Expanded(flex: 3, child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text(item.producto.nombre,
              style: const TextStyle(
                  fontSize: 13, fontWeight: FontWeight.w600,
                  color: AppColors.textPrimary, height: 1.2),
              overflow: TextOverflow.ellipsis,
              maxLines: 2),
          const SizedBox(height: 2),
          Text(item.producto.codigo,
              style: const TextStyle(
                  fontSize: 10, color: AppColors.textSecondary,
                  fontFamily: 'monospace')),
        ])),
        const SizedBox(width: 8),
        // ── Columnas de financiamiento ──────────────────────────
        if (esFinanc) ...[
          // ── Precio base — EDITABLE ──
          Expanded(flex: 2, child: _CeldaConEtiqueta(
            etiqueta: 'Precio',
            colorEtiqueta: AppColors.primaryBlue,
            child: esAdmin
                ? _CeldaPrecioInline(
                    key: ValueKey('financ-base-${item.producto.codigo}'),
                    valor: precioBase,
                    moneda: moneda,
                    onCambio: (v) {
                      setState(() {
                        item.preciosPorColumna[
                            widget.lista.columnas.first.nombre] = v;
                        // Las columnas que dependen del precio base se
                        // recalculan al momento.
                        widget.lista.aplicarFormulas();
                      });
                      _persistirLista(); // sincronizar con backend
                    },
                  )
                : Text("$moneda ${precioBase.toStringAsFixed(2)}",
                    textAlign: TextAlign.right,
                    style: const TextStyle(
                        fontSize: 13, fontWeight: FontWeight.bold,
                        color: AppColors.primaryBlue)),
          )),
          const SizedBox(width: 4),
          // ── Inicial — EDITABLE (override manual) ──
          Expanded(flex: 2, child: _CeldaConEtiqueta(
            etiqueta: inicialEsManual
                ? '✎ Inicial'
                : 'Inicial '
                  '${widget.lista.pctInicialDe(item).toStringAsFixed(0)}%'
                  '${item.pctInicialOverride != null ? " ●" : ""}',
            colorEtiqueta: inicialEsManual
                ? AppColors.statusOrange
                : Colors.orange.shade700,
            child: esAdmin
                ? Row(children: [
                    Expanded(child: _CeldaPrecioInline(
                      key: ValueKey('financ-inicial-${item.producto.codigo}'),
                      valor: inicial,
                      moneda: moneda,
                      onCambio: (v) {
                        setState(() {
                          // Si el valor coincide con el calculado, quitamos el
                          // override (vuelve a ser automático).
                          if ((v - inicialCalculada).abs() < 0.01) {
                            item.inicialManual = null;
                          } else {
                            item.inicialManual = v;
                          }
                        });
                        _persistirLista(); // sincronizar con backend
                      },
                    )),
                    if (inicialEsManual)
                      InkWell(
                        onTap: () {
                          setState(() => item.inicialManual = null);
                          _persistirLista();
                        },
                        child: const Padding(
                          padding: EdgeInsets.symmetric(horizontal: 2),
                          child: Icon(Icons.refresh, size: 14, color: Colors.grey),
                        ),
                      ),
                  ])
                : Text("$moneda ${inicial.toStringAsFixed(2)}",
                    textAlign: TextAlign.right,
                    style: TextStyle(
                        fontSize: 13, fontWeight: FontWeight.bold,
                        color: inicialEsManual
                            ? AppColors.statusOrange
                            : Colors.orange.shade700)),
          )),
          const SizedBox(width: 4),
          // ── Cuota — solo si la financiadora maneja cuotas ──
          if (widget.lista.tieneCuotas)
          Expanded(flex: 2, child: _CeldaConEtiqueta(
            etiqueta: cuotaEsManual
                ? '✎ Cuota'
                : 'Cuota x${widget.lista.cuotasDe(item)}'
                  '${item.cuotasOverride != null ? " ●" : ""}'
                  '${widget.lista.porcentajeRecargoCuotas > 0
                      ? " (+${widget.lista.porcentajeRecargoCuotas.toStringAsFixed(0)}%)"
                      : ""}',
            colorEtiqueta: cuotaEsManual
                ? AppColors.statusOrange
                : AppColors.royalBlue,
            child: esAdmin
                ? Row(children: [
                    Expanded(child: _CeldaPrecioInline(
                      key: ValueKey('financ-cuota-${item.producto.codigo}'),
                      valor: cuota,
                      moneda: moneda,
                      onCambio: (v) {
                        setState(() {
                          if ((v - cuotaCalculada).abs() < 0.01) {
                            item.cuotaManual = null;
                          } else {
                            item.cuotaManual = v;
                          }
                        });
                        _persistirLista(); // sincronizar con backend
                      },
                    )),
                    if (cuotaEsManual)
                      InkWell(
                        onTap: () {
                          setState(() => item.cuotaManual = null);
                          _persistirLista();
                        },
                        child: const Padding(
                          padding: EdgeInsets.symmetric(horizontal: 2),
                          child: Icon(Icons.refresh, size: 14, color: Colors.grey),
                        ),
                      ),
                  ])
                : Text("$moneda ${cuota.toStringAsFixed(2)}",
                    textAlign: TextAlign.right,
                    style: TextStyle(
                        fontSize: 13, fontWeight: FontWeight.bold,
                        color: cuotaEsManual
                            ? AppColors.statusOrange
                            : AppColors.royalBlue)),
          )),
          // ── Columnas EXTRA de la lista de financiamiento ──
          // (la primera columna es el precio base, ya mostrado arriba)
          ..._celdasColumnas(
              item, esAdmin, moneda, widget.lista.columnas.skip(1)),
        ] else
          // ── Columnas normales (modo no-financiamiento) ──
          ..._celdasColumnas(item, esAdmin, moneda, widget.lista.columnas),
        const SizedBox(width: 8),
        // ── Stock disponible (DESPUÉS de los precios) ────────
        SizedBox(width: 56, child: _CeldaConEtiqueta(
          etiqueta: 'Stock',
          colorEtiqueta: stockOk ? AppColors.statusGreen : AppColors.statusRed,
          child: esAdmin
              ? _CeldaPrecioInline(
                  key: ValueKey('stock-${item.producto.codigo}'),
                  valor: item.stockDisponible.toDouble(),
                  moneda: '',
                  onCambio: (v) =>
                      setState(() => item.stockDisponible = v.toInt()),
                )
              : Container(
                  alignment: Alignment.center,
                  padding: const EdgeInsets.symmetric(vertical: 4),
                  decoration: BoxDecoration(
                      color: stockOk
                          ? Colors.green.withValues(alpha: 0.1)
                          : Colors.red.withValues(alpha: 0.1),
                      borderRadius: BorderRadius.circular(6)),
                  child: Text("${item.stockDisponible}",
                      style: TextStyle(
                          fontSize: 13, fontWeight: FontWeight.bold,
                          color: stockOk ? Colors.green[700] : Colors.red[700])),
                ),
        )),
        const SizedBox(width: 4),
        // ── Botón eliminar ───────────────────────────────────
        if (esAdmin)
          SizedBox(width: 32, child: IconButton(
            icon: const Icon(Icons.remove_circle_outline, size: 20, color: Colors.red),
            padding: EdgeInsets.zero,
            tooltip: 'Eliminar producto de la lista',
            onPressed: () => setState(() => widget.lista.items.remove(item)),
          )),
      ]),
    );
  }
}

/// Estilo de los ejemplos de fórmula del panel de ayuda.
const TextStyle _estiloEjemploFormula = TextStyle(
    fontSize: 11, fontFamily: 'monospace', color: Colors.black54);

/// Panel de ayuda del editor de funciones: lista las variables, las
/// funciones y algunos ejemplos listos para copiar. Se muestra dentro
/// del editor cuando el modo es "Fórmula libre".
class _AyudaFormula extends StatelessWidget {
  final List<String> columnas;
  const _AyudaFormula({required this.columnas});

  @override
  Widget build(BuildContext context) {
    Widget fila(String titulo, String cuerpo) => Padding(
          padding: const EdgeInsets.only(bottom: 6),
          child: RichText(
            text: TextSpan(
              style: const TextStyle(fontSize: 11, color: Colors.black87),
              children: [
                TextSpan(
                    text: '$titulo: ',
                    style: const TextStyle(fontWeight: FontWeight.bold)),
                TextSpan(
                    text: cuerpo,
                    style: const TextStyle(fontFamily: 'monospace')),
              ],
            ),
          ),
        );

    return Theme(
      data: Theme.of(context).copyWith(dividerColor: Colors.transparent),
      child: ExpansionTile(
        tilePadding: EdgeInsets.zero,
        childrenPadding: const EdgeInsets.only(bottom: 8),
        leading: const Icon(Icons.help_outline, size: 18),
        title: const Text('¿Qué puedo escribir en la fórmula?',
            style: TextStyle(fontSize: 12, fontWeight: FontWeight.bold)),
        children: [
          fila('Valores del producto',
              'costo, venta, base, stock'),
          fila('Valores de la lista',
              'tasa, adicional, inicial, cuotas, recargo'),
          if (columnas.isNotEmpty)
            fila('Otras columnas',
                columnas.map((c) => '[$c]').join('  ')),
          fila('Operaciones', '+  -  *  /  ^  mod  ( )'),
          fila('Funciones',
              'redondear(x;dec)  techo(x)  piso(x)  abs(x)  min(a;b)  '
              'max(a;b)  pot(a;b)  raiz(x)  si(cond;a;b)'),
          fila('Comparaciones', '>  <  >=  <=  =  <>   y / o'),
          const SizedBox(height: 4),
          const Text('Ejemplos',
              style: TextStyle(fontSize: 11, fontWeight: FontWeight.bold)),
          const Padding(
            padding: EdgeInsets.only(top: 2),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text('costo * 1.25 + 10', style: _estiloEjemploFormula),
                Text('techo(venta * 1.4)', style: _estiloEjemploFormula),
                Text('si(costo > 200; costo * 1.15; costo * 1.30)',
                    style: _estiloEjemploFormula),
                Text('base * tasa', style: _estiloEjemploFormula),
                Text('redondear(costo * (1 + adicional / 100); 0)',
                    style: _estiloEjemploFormula),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

/// Widget auxiliar: una celda con su etiqueta arriba en chiquito y el
/// contenido (texto o TextField) abajo. Hace que la lista de precios
/// se vea más limpia y prolija — el usuario sabe qué representa cada
/// número sin necesitar header de tabla.
class _CeldaConEtiqueta extends StatelessWidget {
  final String etiqueta;
  final Color colorEtiqueta;
  final Widget child;
  const _CeldaConEtiqueta({
    required this.etiqueta,
    required this.colorEtiqueta,
    required this.child,
  });

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(etiqueta,
            textAlign: TextAlign.right,
            overflow: TextOverflow.ellipsis,
            style: TextStyle(
                fontSize: 9, color: colorEtiqueta,
                fontWeight: FontWeight.w600,
                letterSpacing: 0.2)),
        const SizedBox(height: 2),
        child,
      ],
    );
  }
}

// ============================================================
//  SELECTOR MANUAL DE PRODUCTOS PARA LISTA
// ============================================================
class SelectorProductosLista extends StatefulWidget {
  final ListaPrecio lista;
  const SelectorProductosLista({super.key, required this.lista});
  @override State<SelectorProductosLista> createState() => _SelectorProductosListaState();
}

class _SelectorProductosListaState extends State<SelectorProductosLista> {
  String _busqueda = "";
  final _searchCtrl = TextEditingController();
  String _categoriaFiltro = "Todos";

  @override
  void dispose() { _searchCtrl.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) {
    final filtrados = catalogoGlobal.where((p) {
      final catOk = _categoriaFiltro == "Todos" || p.categoria == _categoriaFiltro;
      final busqOk = _busqueda.isEmpty ||
          p.nombre.toLowerCase().contains(_busqueda.toLowerCase()) ||
          p.codigo.toLowerCase().contains(_busqueda.toLowerCase()) ||
          p.marca.toLowerCase().contains(_busqueda.toLowerCase());
      return catOk && busqOk;
    }).toList();

    return Scaffold(
      appBar: AppBar(
        title: const Text("Agregar productos"),
      ),
      body: Column(children: [
        Padding(
          padding: const EdgeInsets.all(10),
          child: Column(children: [
            TextField(
              controller: _searchCtrl,
              decoration: const InputDecoration(
                hintText: "Buscar por nombre, código o marca...",
                prefixIcon: Icon(Icons.search), isDense: true),
              onChanged: (v) => setState(() => _busqueda = v)),
            const SizedBox(height: 8),
            SingleChildScrollView(scrollDirection: Axis.horizontal,
              child: Row(children: ["Todos","Telefono","Accesorio","Televisor","Linea Blanca","Linea"].map((cat) =>
                Padding(padding: const EdgeInsets.only(right: 6),
                  child: ChoiceChip(
                    label: Text(cat),
                    selected: _categoriaFiltro == cat,
                    selectedColor: AppColors.primaryBlue,
                    labelStyle: TextStyle(color: _categoriaFiltro == cat ? Colors.white : Colors.black87),
                    onSelected: (_) => setState(() => _categoriaFiltro = cat)))).toList())),
          ]),
        ),
        Expanded(child: ListView.builder(
          itemCount: filtrados.length,
          itemBuilder: (ctx, i) {
            final p = filtrados[i];
            final yaEsta = widget.lista.items.any((it) => it.producto.codigo == p.codigo);
            final stock = CategoriasProductos.usaIMEI(p.categoria)
                ? stockImeiGlobal.where((im) => im.producto.codigo == p.codigo && !im.vendido).length
                : p.stockManual;
            return ListTile(
              leading: CircleAvatar(
                backgroundColor: yaEsta ? Colors.green.withValues(alpha: 0.15) : Colors.grey[100],
                child: Icon(
                  yaEsta ? Icons.check : Icons.add,
                  color: yaEsta ? Colors.green : Colors.grey)),
              title: Text(p.nombre, style: const TextStyle(fontWeight: FontWeight.w500)),
              subtitle: Text("${p.marca} · ${p.codigo} · Stock: $stock"),
              trailing: Text(
                "${formatCurrency(p.precioVenta)}",
                style: const TextStyle(fontWeight: FontWeight.bold, color: AppColors.primaryBlue)),
              onTap: yaEsta ? null : () {
                final precioBase = widget.lista.esEnBolivares
                    ? (p.precioVenta * widget.lista.tasaDelDia)
                    : p.precioVenta;
                setState(() {
                  widget.lista.items.add(ItemListaPrecio(
                    producto: p,
                    stockDisponible: stock,
                    preciosPorColumna: { for (var col in widget.lista.columnas) col.nombre: precioBase }));
                  widget.lista.aplicarFormulas();
                });
                ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                  content: Text("✅ ${p.nombre} agregado"),
                  backgroundColor: AppColors.statusGreen,
                  duration: const Duration(seconds: 1)));
              },
            );
          },
        )),
      ]),
    );
  }
}

// ============================================================
//  COMISIONES — carga y guarda en la API
// ============================================================
/// Parsea fechas en formato "dd/MM/yyyy" o "yyyy-MM-dd". Retorna DateTime.now() si falla.
DateTime parseFecha(String fecha) {
  final s = fecha.trim();
  // FECHA SENTINELA: si la fecha está vacía o no se puede parsear,
  // devolvemos el año 1900. Esto garantiza que la factura quede
  // FUERA de cualquier rango razonable y no contamine los reportes.
  // Antes devolvíamos DateTime.now(), pero eso hacía que TODAS las
  // facturas con fechas malformadas o vacías aparecieran como si
  // fueran de hoy, agregándolas a cualquier reporte que incluyera
  // el día actual.
  final fechaSentinela = DateTime(1900, 1, 1);
  if (s.isEmpty) return fechaSentinela;
  try {
    // Caso 1: ISO con T (ej: "2026-06-08T14:30:00" o con Z)
    if (s.contains('T')) {
      return DateTime.parse(s);
    }
    // Caso 2: ISO con espacio (ej: "2026-06-08 14:30:00")
    if (s.contains('-') && s.contains(' ')) {
      // Reemplazar espacio por T para que DateTime.parse lo acepte
      return DateTime.parse(s.replaceFirst(' ', 'T'));
    }
    // Caso 3: ISO solo fecha (ej: "2026-06-08")
    if (s.contains('-') && !s.contains('/')) {
      return DateTime.parse(s);
    }
    // Caso 4: Formato dd/MM/yyyy o dd/MM/yyyy HH:mm:ss
    if (s.contains('/')) {
      // Separar fecha de hora si existe
      final partesEspacio = s.split(' ');
      final partesFecha = partesEspacio[0].split('/');
      if (partesFecha.length == 3) {
        final d = int.parse(partesFecha[0]);
        final m = int.parse(partesFecha[1]);
        final y = int.parse(partesFecha[2]);
        // Si hay hora, parsearla también
        if (partesEspacio.length > 1) {
          final partesHora = partesEspacio[1].split(':');
          final h  = partesHora.length > 0 ? int.tryParse(partesHora[0]) ?? 0 : 0;
          final mi = partesHora.length > 1 ? int.tryParse(partesHora[1]) ?? 0 : 0;
          final se = partesHora.length > 2 ? int.tryParse(partesHora[2]) ?? 0 : 0;
          return DateTime(y, m, d, h, mi, se);
        }
        return DateTime(y, m, d);
      }
    }
  } catch (e) {
    debugPrint('parseFecha("$s"): $e');
  }
  return fechaSentinela;
}

class VentanaComisiones extends StatefulWidget {
  const VentanaComisiones({super.key});
  @override State<VentanaComisiones> createState() => _VentanaComisionesState();
}

class _VentanaComisionesState extends State<VentanaComisiones> {
  // Inicializar con la tasa BCV actual si está disponible
  double get tasa => ConfigSistema.tasaCambio;
  double _tasaManual = 0;
  bool _usarTasaBCV = true;
  bool _cargando = false; // ← controla el spinner de generarYGuardar
  DateTime? fechaInicio, fechaFin;
  List<HistorialComision> _historial = [];

  @override
  void initState() {
    super.initState();
    _tasaManual = ConfigSistema.tasaCambio;
    _cargarHistorial();
    TasaBCVScheduler.addListener(_onTasaActualizada);
  }

  @override
  void dispose() {
    TasaBCVScheduler.removeListener(_onTasaActualizada);
    super.dispose();
  }

  void _onTasaActualizada() {
    if (mounted && _usarTasaBCV) setState(() {});
  }

  Future<void> _cargarHistorial() async {
    try {
      final raw = await _Api.get('comisiones_historial');
      if (!mounted) return;
      setState(() {
        _historial = ((raw as List?) ?? [])
            .map((m) => HistorialComision.fromMap(m)).toList()
          ..sort((a, b) => b.fechaInicio.compareTo(a.fechaInicio));
        historialComisiones = _historial;
      });
    } catch (e) {
      debugPrint('Error cargando historial comisiones: $e');
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text("Error al cargar historial: $e"),
        backgroundColor: AppColors.statusRed,
        duration: const Duration(seconds: 3)));
    }
  }

  Future<void> seleccionarFechas() async {
    final rango = await showDateRangePicker(
      context: context,
      firstDate: DateTime(2020),
      lastDate: DateTime.now(),
      helpText: 'Seleccione el rango de fechas para las comisiones',
    );
    if (rango != null && mounted) {
      setState(() { fechaInicio = rango.start; fechaFin = rango.end; });
    }
  }

  Future<List<FacturaModel>> _cargarVentasApi() async {
    try {
      // Asegurar que tenemos el catálogo en memoria para poder
      // resolver los códigos de items a sus Productos.
      if (catalogoGlobal.isEmpty) {
        try {
          final rawP = await _Api.get('productos');
          catalogoGlobal = ((rawP as List?) ?? [])
              .map((m) => Producto.fromMap(m)).toList();
        } catch (_) {}
      }
      // Necesitamos stockImeiGlobal para mapear IMEI → Producto real
      if (stockImeiGlobal.isEmpty) {
        try {
          final rawI = await _Api.get('stock_imei');
          stockImeiGlobal = ((rawI as List?) ?? [])
              .map((m) => ImeiRegistro.fromMap(m)).toList();
        } catch (_) {}
      }

      final raw = await _Api.get('facturas');
      // CAMBIO FASE 3: usamos el parser global que captura los maps
      // vendedorPorImei / vendedorPorCodigo / creadorRol. El parser local
      // que estaba antes los perdía y el cálculo nuevo de comisiones
      // necesita esos datos para atribuir cada producto a su vendedor
      // (no al creador) y aplicar el split cajero 35/65.
      final List<FacturaModel> ventas = ((raw as List?) ?? [])
          .map((m) => construirFacturaModelDesdeJson(m as Map<String, dynamic>))
          .toList();
      return ventas;
    } catch (e) {
      debugPrint("Error API comisiones: $e");
      return [];
    }
  }

  /// Genera los resúmenes de comisión por vendedor para el rango de
  /// fechas seleccionado.
  ///
  /// El cálculo recorre cada categoría definida en
  /// `ConfigSistema.categoriasComision` y aplica su `tipoConteo`:
  ///
  /// - **categoriaProducto**: cuenta cada producto vendido cuya
  ///   categoría coincida con `valorConteo`.
  /// - **lineaTelefonica**: cuenta cada línea activada en la venta.
  /// - **ventaFinanciada**: cuenta cada pago financiado, atribuido al
  ///   "vendedor financiador" registrado en el pago.
  /// - **servicioTecnico**: cuenta cada servicio técnico ENTREGADO
  ///   (estado=Entregado o pagado=true) en el rango, atribuido al
  ///   técnico de la ficha.
  /// - **porcentajeWeppa**: aplica el % configurado en la lista Weppa
  ///   sobre el precio de venta de los productos financiados con Weppa.
  ///
  /// El resumen guarda un snapshot de las tarifas y nombres usados
  /// para que el historial muestre datos correctos aunque luego se
  /// modifique la configuración.
  List<ResumenComision> generarComisiones(List<FacturaModel> ventas) {
    final Map<String, ResumenComision> mapa = {};

    // Snapshot de las categorías al momento de generar — todas las
    // operaciones siguientes leen de aquí.
    final categorias = List<CategoriaComision>.from(
        ConfigSistema.categoriasComision);

    /// Helper: garantiza que un ResumenComision exista para el vendedor,
    /// y que tenga inicializadas las tarifas y nombres de TODAS las
    /// categorías activas (aunque sus conteos sean 0).
    ResumenComision obtenerResumen(String vendedor) {
      return mapa.putIfAbsent(vendedor, () {
        final r = ResumenComision(vendedor: vendedor);
        for (final c in categorias) {
          r.conteos[c.id]            = 0;
          r.tarifasUsadas[c.id]      = c.tarifaUSD;
          r.nombresCategorias[c.id]  = c.nombre;
        }
        return r;
      });
    }

    // Determinar el % de comisión Weppa activo: se toma de la lista
    // de financiamiento cuya `financiadora` contenga "weppa".
    double pctComisionWeppa = 0;
    try {
      final listaWeppa = listasPreciosGlobal.firstWhere(
        (l) => l.esFinanciamiento &&
            (l.financiadora ?? '').toLowerCase().contains('weppa'),
      );
      pctComisionWeppa = listaWeppa.porcentajeComisionWeppa;
    } catch (_) {
      pctComisionWeppa = 0;
    }

    // ── Helpers ───────────────────────────────────────────────
    // Lista de usuarios indexada por nombre (case-insensitive) para
    // resolver rol/sueldoBase/ganaComisiones rápido.
    final Map<String, Usuario> usuariosPorNombre = {
      for (final u in usuariosSistema)
        u.nombre.trim().toLowerCase(): u,
    };

    /// Devuelve el Usuario que vendió este producto (por nombre),
    /// o null si no existe en el sistema o no gana comisiones.
    /// Se usa para decidir si atribuir el producto a alguien o saltarlo.
    Usuario? usuarioDe(String nombreVendedor) {
      final clave = nombreVendedor.trim().toLowerCase();
      if (clave.isEmpty) return null;
      final u = usuariosPorNombre[clave];
      if (u == null) return null;
      if (!u.ganaComisiones) return null;
      return u;
    }

    /// Devuelve true si el usuario tiene rol "Cajero" (case-insensitive).
    bool esCajero(Usuario? u) {
      if (u == null) return false;
      return u.rol.trim().toLowerCase() == 'cajero';
    }

    final pctCajero = ConfigSistema.porcentajeCajeroDivision;

    // ── Recorrer las ventas y aplicar los tipos de conteo
    //    relacionados con productos vendidos ──
    //
    // FASE 3: cada producto se atribuye a SU vendedor (no al creador).
    // Si el creador es Cajero y el vendedor del producto es DISTINTO,
    // se aplica el split 35/65: el cajero recibe % de la tarifa y el
    // vendedor pierde ese mismo monto (balance exacto).
    // Importante: aunque el creador NO gane comisiones, la factura se
    // procesa igual — los productos van a sus vendedores asignados.
    for (final venta in ventas) {
      // Resumen del creador (cajero/vendedor que facturó). Puede ser
      // null si no está registrado o no gana comisiones.
      final usuarioCreador = usuarioDe(venta.vendedor);
      // NO creamos resumen del creador con obtenerResumen(): eso lo
      // registraba en el mapa y al final le asignaba sueldo base,
      // apareciendo en el reporte cobrando por facturas donde no
      // vendió NADA. Ahora solo incrementamos el contador
      // `facturasCajero` SI el creador ya tiene un resumen (porque
      // vendió algún producto). Si no, no aparece en el reporte.
      // Se pierde el contador cuando no hay resumen previo, pero
      // era solo informativo (facturas hechas actuando como cajero).

      // Determinar si el creador actúa como cajero. Preferimos el
      // `creadorRol` guardado en la factura (snapshot al momento de
      // facturar) — si está vacío, usamos el rol actual del usuario.
      final rolCreador = venta.creadorRol.trim().isNotEmpty
          ? venta.creadorRol.trim().toLowerCase()
          : (usuarioCreador?.rol.trim().toLowerCase() ?? '');
      final creadorEsCajero = rolCreador == 'cajero';

      if (creadorEsCajero && usuarioCreador != null) {
        final existente = mapa[venta.vendedor];
        if (existente != null) {
          existente.facturasCajero += 1;
        }
      }

      // ¿Es una venta financiada con Weppa?
      bool esVentaWeppa = false;
      for (final pago in venta.pagos) {
        final fin = (pago.financiador ?? '').toLowerCase();
        if (pago.tipo == 'Financiado' && fin.contains('weppa')) {
          esVentaWeppa = true;
          break;
        }
      }

      /// Procesa UN producto (equipo o item) atribuyéndolo al vendedor
      /// correcto, aplicando conteos, comisión Weppa y split cajero.
      void procesarProducto({
        required String categoriaProd,
        required double precioVenta,
        required String nombreVendedor,
      }) {
        final usuarioProd = usuarioDe(nombreVendedor);
        // REGLA DE ORO:
        //   · La comisión SIEMPRE va al vendedor asignado al producto.
        //   · El creador NO recibe comisión "por ser creador" — solo la
        //     recibe si él mismo aparece asignado como vendedor de algún
        //     producto (usando el selector "Vendedor del producto").
        //   · Si el producto no tiene vendedor asignado explícitamente,
        //     la comisión no se paga a nadie (ya está garantizado porque
        //     `vendedorDeEquipo` y `vendedorDeItem` devuelven '' cuando
        //     no hay asignación, y `usuarioDe('')` devuelve null).
        if (usuarioProd == null) return;
        final rDestino = obtenerResumen(usuarioProd.nombre);

        // 1) Incrementar conteos por categoría
        for (final cat in categorias) {
          if (cat.tipoConteo == TipoConteoComision.categoriaProducto &&
              cat.valorConteo == categoriaProd) {
            rDestino.conteos[cat.id] =
                (rDestino.conteos[cat.id] ?? 0) + 1;
          }
        }

        // 2) Comisión Weppa sobre precio de venta (si aplica)
        if (esVentaWeppa && pctComisionWeppa > 0 && precioVenta > 0) {
          rDestino.comisionWeppa +=
              precioVenta * pctComisionWeppa / 100;
        }

        // 3) SPLIT CAJERO DESACTIVADO:
        //    Por la regla de oro anterior, el creador de la factura no
        //    recibe comisión. Antes acá había un bloque que hacía un
        //    "split 35/65" transfiriendo parte de la comisión del
        //    vendedor del producto al cajero que facturó. Eso violaba
        //    la regla y quedó eliminado. La comisión del producto queda
        //    ENTERA para el vendedor del producto.
      }

      // Recorrer equipos
      for (final eq in venta.equipos) {
        final vendedorEq = venta.vendedorDeEquipo(eq.imei);
        procesarProducto(
          categoriaProd: eq.producto.categoria,
          precioVenta: eq.producto.precioVenta,
          nombreVendedor: vendedorEq,
        );
      }

      // Recorrer items sin IMEI
      for (final p in venta.itemsSinImei) {
        final vendedorIt = venta.vendedorDeItem(p.codigo);
        procesarProducto(
          categoriaProd: p.categoria,
          precioVenta: p.precioVenta,
          nombreVendedor: vendedorIt,
        );
      }

      // Ventas financiadas: contabilizar para el "vendedor financiador"
      // (que se registra como su propio vendedor en el resumen).
      //
      // El campo `financiador` puede venir en dos formatos:
      //   · "Cashea|Juan"  → financiadora=Cashea, vendedor humano=Juan
      //   · "Juan"         → vendedor humano directamente (la financiadora
      //                       ya está en el campo `financiadora` aparte).
      // Para que la comisión funcione SIEMPRE, aceptamos ambos formatos:
      //   1. Si hay "|", parseamos.
      //   2. Si no hay "|", interpretamos como el vendedor humano.
      // En ambos casos, si el nombre coincide con un usuario que gana
      // comisiones, le sumamos el conteo de cada categoría ventaFinanciada
      // cuyo filtro matchee con la financiadora del pago.
      for (final pago in venta.pagos) {
        if (pago.tipo != 'Financiado') continue;
        final raw = (pago.financiador ?? '').trim();
        final financiadora = (pago.financiadora ?? '').trim();
        if (raw.isEmpty && financiadora.isEmpty) continue;

        // Extraer vendedor humano y financiadora
        String? vendedorHumano;
        String filtroFinanciador = financiadora;
        if (raw.contains('|')) {
          final partes = raw.split('|');
          if (filtroFinanciador.isEmpty) filtroFinanciador = partes[0].trim();
          if (partes.length > 1 && partes[1].trim().isNotEmpty) {
            vendedorHumano = partes[1].trim();
          }
        } else if (raw.isNotEmpty) {
          // Sin pipe: el campo es el vendedor humano directamente
          vendedorHumano = raw;
        }
        if (vendedorHumano == null) continue;

        final usuarioFin = usuarioDe(vendedorHumano);
        if (usuarioFin == null) continue;
        final rFin = obtenerResumen(usuarioFin.nombre);

        for (final cat in categorias) {
          // El financiador NO gana comisión (decisión del dueño). Aunque
          // la categoría llegue desde un equipo viejo o del backend, acá
          // se ignora — este es el único punto donde se generaba.
          if (cat.id == kCategoriaComisionEliminada) continue;
          if (cat.tipoConteo == TipoConteoComision.ventaFinanciada) {
            final filtroCat = cat.valorConteo.trim().toLowerCase();
            final fAct = filtroFinanciador.toLowerCase();
            // Si la categoría no tiene filtro, cuenta cualquier financ.
            // Si tiene filtro, debe estar contenido en la financiadora.
            if (filtroCat.isEmpty || fAct.contains(filtroCat)) {
              rFin.conteos[cat.id] = (rFin.conteos[cat.id] ?? 0) + 1;
            }
          }
        }
      }
    }

    // ── Líneas telefónicas activadas en el rango ──
    // Se cuentan directamente desde `lineasGlobal` filtrando por
    // fecha y por el flag `activada` — atribuyendo cada línea al
    // vendedor que la registró. Esto es independiente de las facturas
    // (una activación es un evento distinto a una venta).
    if (categorias.any(
        (c) => c.tipoConteo == TipoConteoComision.lineaTelefonica)) {
      for (final ln in lineasGlobal) {
        if (!ln.activada) continue;
        final vendedor = ln.vendedor.trim();
        if (vendedor.isEmpty) continue;
        // Filtrar por rango de fechas
        DateTime? fln;
        try {
          fln = DateTime.tryParse(ln.fecha);
        } catch (_) {
          fln = null;
        }
        if (fln == null) continue;
        if (fechaInicio != null && fln.isBefore(fechaInicio!)) continue;
        if (fechaFin != null &&
            fln.isAfter(fechaFin!.add(const Duration(days: 1)))) continue;

        final rVend = obtenerResumen(vendedor);
        for (final cat in categorias) {
          if (cat.tipoConteo == TipoConteoComision.lineaTelefonica) {
            rVend.conteos[cat.id] = (rVend.conteos[cat.id] ?? 0) + 1;
          }
        }
      }
    }

    // ── Servicios técnicos ENTREGADOS en el rango ──
    // Cuentan al técnico (campo `tecnico`). Solo se consideran los
    // que estén pagados o entregados — no los pendientes.
    if (categorias.any((c) =>
        c.tipoConteo == TipoConteoComision.servicioTecnico)) {
      for (final st in serviciosGlobal) {
        final tecnico = st.tecnico.trim();
        if (tecnico.isEmpty) continue;
        // Filtrar por rango de fechas (usa `fecha` de recepción).
        if (fechaInicio != null && st.fecha.isBefore(fechaInicio!)) continue;
        if (fechaFin != null &&
            st.fecha.isAfter(fechaFin!.add(const Duration(days: 1)))) {
          continue;
        }
        // Solo servicios efectivamente cobrados.
        final cobrado = st.pagado ||
            st.estado.toLowerCase() == 'entregado';
        if (!cobrado) continue;

        final rTec = obtenerResumen(tecnico);
        for (final cat in categorias) {
          if (cat.tipoConteo == TipoConteoComision.servicioTecnico) {
            rTec.conteos[cat.id] = (rTec.conteos[cat.id] ?? 0) + 1;
          }
        }
      }
    }

    // ── Asignar sueldo base del usuario (igual que antes) ──
    // También filtramos usuarios cuya `ganaComisiones = false` (por
    // si por alguna razón llegaron al mapa — ej. el creador era cajero
    // que no gana, pero quedó registrado al hacer facturasCajero++).
    final List<String> aDescartar = [];
    for (final r in mapa.values) {
      final nombreBuscado = r.vendedor.trim().toLowerCase();
      final usuario = usuariosPorNombre[nombreBuscado];
      if (usuario != null && !usuario.ganaComisiones) {
        aDescartar.add(r.vendedor);
        continue;
      }
      r.base = (usuario != null && usuario.sueldoBase > 0)
          ? usuario.sueldoBase
          : ConfigSistema.comisionBaseDefault;
    }
    for (final v in aDescartar) {
      mapa.remove(v);
    }
    return mapa.values.toList();
  }

  Future<void> generarYGuardar() async {
    if (fechaInicio == null || fechaFin == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text("⚠️ Debes seleccionar un rango de fechas"),
          backgroundColor: AppColors.statusOrange));
      return;
    }

    // Mostrar loading
    setState(() => _cargando = true);
    try {
      // ── Refrescar usuarios desde el backend ANTES de generar ──
      // Así, cualquier usuario creado recientemente en VentanaUsuarios
      // con su sueldoBase queda disponible para el cálculo de comisiones.
      try {
        final rawU = await _Api.get('usuarios');
        usuariosSistema = ((rawU as List?) ?? [])
            .map((m) => Usuario.fromMap(m)).toList();
      } catch (e) {
        debugPrint('[Comisiones] No se pudo refrescar usuarios: $e');
      }

      final todasVentas = await _cargarVentasApi();
      final ventasFiltradas = todasVentas.where((v) {
        try {
          final fv = parseFecha(v.fecha);
          return !fv.isBefore(fechaInicio!) &&
                 !fv.isAfter(fechaFin!.add(const Duration(days: 1)));
        } catch (_) { return false; }
      }).toList();

      if (ventasFiltradas.isEmpty) {
        if (mounted) ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text("No hay ventas en ese rango de fechas"),
            backgroundColor: AppColors.statusOrange));
        setState(() => _cargando = false);
        return;
      }

      final resultado = generarComisiones(ventasFiltradas);
      final tasaUsada = _usarTasaBCV ? ConfigSistema.tasaCambio : _tasaManual;

      // Guardar en BD
      await _Api.post('comisiones_historial', {
        'fecha_inicio': "${fechaInicio!.year}-${fechaInicio!.month.toString().padLeft(2,'0')}-${fechaInicio!.day.toString().padLeft(2,'0')}",
        'fecha_fin'   : "${fechaFin!.year}-${fechaFin!.month.toString().padLeft(2,'0')}-${fechaFin!.day.toString().padLeft(2,'0')}",
        'tasa_bcv'    : tasaUsada,
        'data'        : resultado.map((r) => r.toMap()).toList(),
      });

      if (!mounted) return;
      setState(() => _cargando = false);
      await _cargarHistorial();

      if (!mounted) return;
      _mostrarTablaComisiones(resultado, tasaUsada,
        "${formatearFecha(fechaInicio!)} — ${formatearFecha(fechaFin!)}");

      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text("✅ Comisiones guardadas correctamente"),
        backgroundColor: AppColors.statusGreen));

    } catch (e) {
      debugPrint('[generarYGuardar] Error: $e');
      if (mounted) {
        setState(() => _cargando = false);
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text("Error al guardar comisiones: $e"),
          backgroundColor: AppColors.statusRed));
      }
    }
  }

  void mostrarVentana(List<ResumenComision> lista) {
    _mostrarTablaComisiones(lista, _usarTasaBCV ? ConfigSistema.tasaCambio : _tasaManual,
      "Historial");
  }

  void _mostrarTablaComisiones(List<ResumenComision> lista, double tasaUsada, String titulo) {
    showDialog(context: context, builder: (context) {
      return Dialog(
        insetPadding: const EdgeInsets.all(10),
        child: Container(
          padding: const EdgeInsets.all(15),
          height: MediaQuery.of(context).size.height * 0.85,
          child: Column(children: [
            Row(children: [
              Expanded(child: Text("COMISIONES — $titulo",
                style: const TextStyle(fontSize: 16, fontWeight: FontWeight.bold))),
              Text("Tasa: Bs ${tasaUsada.toStringAsFixed(2)}",
                style: const TextStyle(color: AppColors.textSecondary, fontSize: 12)),
              const SizedBox(width: 8),
              IconButton(onPressed: () => Navigator.pop(context),
                icon: const Icon(Icons.close)),
            ]),
            const SizedBox(height: 10),
            Expanded(child: tabla(lista)),
            ElevatedButton(
              onPressed: () => Navigator.pop(context),
              child: const Text("Cerrar")),
          ]),
        ));
    });
  }

  Widget tabla(List<ResumenComision> lista) {
    // ── Decidir qué categorías mostrar como columnas ──
    // Tomamos como referencia las categorías "vivas" del primer
    // resumen del histórico — así el histórico se ve con los nombres
    // de cuando se generó, y los actuales con la config actual.
    // Si el resumen no tiene snapshot (datos viejos), caemos a la
    // configuración global.
    List<String> categoriaIds;
    Map<String, String> nombresCol = {};
    if (lista.isNotEmpty && lista.first.nombresCategorias.isNotEmpty) {
      categoriaIds = lista.first.nombresCategorias.keys.toList();
      nombresCol = Map<String, String>.from(lista.first.nombresCategorias);
    } else {
      categoriaIds =
          ConfigSistema.categoriasComision.map((c) => c.id).toList();
      for (final c in ConfigSistema.categoriasComision) {
        nombresCol[c.id] = c.nombre;
      }
    }

    // Solo mostrar columna Weppa si al menos un vendedor tiene comisión
    final hayWeppa = lista.any((r) => r.comisionWeppa > 0);
    // Mostrar columna de ajuste cajero solo si hay algún ajuste
    // (positivo o negativo). Si nadie aplica split 35/65, no se ve.
    final hayAjusteCajero = lista.any((r) => r.ajusteComisionUSD.abs() > 0.001);
    final tasaActual =
        _usarTasaBCV ? ConfigSistema.tasaCambio : _tasaManual;

    return SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      child: DataTable(
        columnSpacing: 18,
        headingRowColor: WidgetStateProperty.all(Colors.grey[300]),
        columns: [
          const DataColumn(label: Text("Vendedor")),
          // Una columna por cada categoría dinámica
          ...categoriaIds.map((id) => DataColumn(
              label: Text(nombresCol[id] ?? id,
                  style: const TextStyle(fontWeight: FontWeight.w600)))),
          if (hayWeppa)
            const DataColumn(
                label: Text("Com. Weppa",
                    style: TextStyle(color: AppColors.statusGreen))),
          if (hayAjusteCajero)
            const DataColumn(
                label: Tooltip(
                  message: 'Ajuste por split cajero 35/65.\n'
                           'Positivo: cajero recibe % por facturar venta ajena.\n'
                           'Negativo: vendedor pierde % porque un cajero facturó su venta.',
                  child: Text("Ajuste Cajero",
                      style: TextStyle(color: AppColors.primaryBlue)))),
          const DataColumn(label: Text("Total Comisión")),
          const DataColumn(label: Text("Base")),
          const DataColumn(label: Text("Domingo")),
          const DataColumn(label: Text("Descuento Bs")),
          const DataColumn(label: Text("Total a pagar")),
          const DataColumn(label: Text("Total Bs")),
        ],
        rows: List.generate(lista.length, (index) {
          final r = lista[index];
          return DataRow(
            color: WidgetStateProperty.all(
                index % 2 == 0 ? Colors.white : Colors.grey[100]),
            cells: [
              DataCell(Text(r.vendedor)),
              // Conteos dinámicos por categoría — destacamos los > 0
              ...categoriaIds.map((id) {
                final n = r.conteoDe(id);
                return DataCell(Text("$n",
                    style: TextStyle(
                        color: n > 0 ? AppColors.primaryBlue : null,
                        fontWeight: n > 0 ? FontWeight.bold : null)));
              }),
              if (hayWeppa)
                DataCell(Text(formatCurrency(r.comisionWeppa),
                    style: TextStyle(
                        color: r.comisionWeppa > 0
                            ? AppColors.statusGreen
                            : null,
                        fontWeight: r.comisionWeppa > 0
                            ? FontWeight.bold
                            : null))),
              if (hayAjusteCajero)
                DataCell(Text(
                    (r.ajusteComisionUSD >= 0 ? '+' : '') +
                        formatCurrency(r.ajusteComisionUSD),
                    style: TextStyle(
                        color: r.ajusteComisionUSD > 0
                            ? AppColors.statusGreen
                            : r.ajusteComisionUSD < 0
                                ? AppColors.statusRed
                                : null,
                        fontWeight: r.ajusteComisionUSD.abs() > 0.001
                            ? FontWeight.bold
                            : null))),
              DataCell(Text(formatCurrency(r.totalComision))),
              // Base: NO editable. Viene del sueldoBase del Usuario.
              DataCell(Tooltip(
                message: 'Base del usuario (editar en Usuarios)',
                child: Container(
                  padding: const EdgeInsets.symmetric(
                      horizontal: 6, vertical: 4),
                  decoration: BoxDecoration(
                    color: AppColors.surfaceGrey,
                    borderRadius: BorderRadius.circular(4),
                  ),
                  child: Text(formatCurrency(r.base),
                      style: const TextStyle(
                          fontSize: 13,
                          color: AppColors.textSecondary,
                          fontWeight: FontWeight.w600)),
                ),
              )),
              DataCell(SizedBox(
                  width: 70,
                  child: TextField(
                      controller:
                          TextEditingController(text: r.domingo.toString()),
                      keyboardType: TextInputType.number,
                      onChanged: (v) {
                        r.domingo = double.tryParse(v) ?? 0;
                        setState(() {});
                      },
                      decoration:
                          const InputDecoration(border: InputBorder.none)))),
              DataCell(SizedBox(
                  width: 80,
                  child: TextField(
                      controller:
                          TextEditingController(text: r.descuentoBs.toString()),
                      keyboardType: TextInputType.number,
                      onChanged: (v) {
                        r.descuentoBs = double.tryParse(v) ?? 0;
                        setState(() {});
                      },
                      decoration:
                          const InputDecoration(border: InputBorder.none)))),
              DataCell(Text(formatCurrency(r.totalPagar()))),
              // Total Bs: conversión USD→Bs según la tasa actual
              DataCell(Text(
                  "Bs ${r.totalBs(tasaActual).toStringAsFixed(2)}",
                  style: const TextStyle(fontWeight: FontWeight.w600))),
            ]);
        })));
  }

  String formatearFecha(DateTime f) => "${f.day}/${f.month}/${f.year}";

  @override
  Widget build(BuildContext context) {
    final tasaActual = _usarTasaBCV ? ConfigSistema.tasaCambio : _tasaManual;
    return Scaffold(
      appBar: AppBar(
        title: const Text("Comisiones"),
        actions: const [TasaBCVBadge(), SizedBox(width: 8)],
      ),
      body: Padding(padding: const EdgeInsets.all(20), child: Column(children: [
        ElevatedButton.icon(
          icon: const Icon(Icons.date_range),
          label: Text(fechaInicio==null ? "Seleccionar Fechas"
            : "${formatearFecha(fechaInicio!)} - ${formatearFecha(fechaFin!)}"),
          onPressed: seleccionarFechas),
        const SizedBox(height: 12),
        // ── Selector de tasa con opción BCV automático ──
        Card(
          child: Padding(padding: const EdgeInsets.all(12), child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
                const Text("Tasa de cambio", style: TextStyle(fontWeight: FontWeight.bold)),
                Row(children: [
                  const Text("BCV auto", style: TextStyle(fontSize: 12)),
                  const SizedBox(width: 4),
                  Switch(
