// ============================================================
//  REPORTES
// ============================================================
// ── Modelo estructurado de un reporte ─────────────────────────
//
//  En lugar de guardar el reporte como archivo XLSX/PDF en disco
//  y abrirlo con una app externa, ahora cada reporte se guarda
//  como datos estructurados en el historial. Al tocarlo se
//  muestra dentro de la aplicación con un visor especializado
//  según la categoría. Desde ese visor el usuario puede
//  descargar el Excel (con todo el detalle) cuando lo necesite.
//
//  Estructura:
//   - tipoReporte: identificador interno (ventas, inventario, etc.)
//   - encabezados: títulos de columna (para tablas tabulares)
//   - filas: List<List<dynamic>>  (datos planos)
//   - detalles: List<Map<String,dynamic>>  (datos enriquecidos
//     con sub-listas — usado p.ej. para incluir productos y pagos
//     dentro de cada factura del reporte de ventas)
//   - resumen: Map<String,dynamic>  (totales, contadores, etc.)
// ──────────────────────────────────────────────────────────────
class HistorialReporteEntry {
  final String nombreArchivo;       // nombre amigable del reporte
  final String tipoReporte;         // ventas, inventario, cuentas_cobrar, etc.
  final String categoria;           // "Ventas", "Inventario", etc. (UI)
  final DateTime fecha;             // momento en que se generó
  final String generadoPor;
  final String? desdeIso;           // rango de fechas (texto ISO)
  final String? hastaIso;
  final List<String> encabezados;
  final List<List<dynamic>> filas;
  final List<Map<String, dynamic>> detalles;
  final Map<String, dynamic> resumen;

  HistorialReporteEntry({
    required this.nombreArchivo,
    required this.tipoReporte,
    required this.categoria,
    required this.fecha,
    required this.generadoPor,
    this.desdeIso,
    this.hastaIso,
    this.encabezados = const [],
    this.filas = const [],
    this.detalles = const [],
    this.resumen = const {},
  });

  /// Tamaño aproximado del payload (para mostrarlo en el historial).
  int get tamanoBytes {
    try {
      return jsonEncode(toMap()).length;
    } catch (_) { return 0; }
  }

  /// Cantidad total de registros que contiene el reporte.
  int get totalRegistros {
    if (detalles.isNotEmpty) return detalles.length;
    return filas.length;
  }

  /// Nombre del reporte legible para mostrar en encabezados/AppBar.
  String nombreReporteLegible() {
    switch (tipoReporte) {
      case 'ventas':         return 'Reporte de Ventas';
      case 'inventario':     return 'Reporte de Inventario';
      case 'cuentas_cobrar': return 'Cuentas por Cobrar';
      case 'cuentas_pagar':  return 'Cuentas por Pagar';
      case 'lineas':         return 'Reporte de Líneas';
      case 'imei':           return 'Inventario IMEI';
      case 'cierres':        return 'Cierres de Caja';
      case 'comisiones':     return 'Comisiones';
      case 'servicios':      return 'Órdenes de Servicio';
    }
    return categoria.isNotEmpty ? categoria : 'Reporte';
  }

  Map<String, dynamic> toMap() => {
    'nombre': nombreArchivo,
    'tipo_reporte': tipoReporte,
    'categoria': categoria,
    'fecha': fecha.toIso8601String(),
    'usuario': generadoPor,
    'desde': desdeIso,
    'hasta': hastaIso,
    'encabezados': encabezados,
    'filas': filas,
    'detalles': detalles,
    'resumen': resumen,
  };

  factory HistorialReporteEntry.fromMap(Map<String, dynamic> m) =>
      HistorialReporteEntry(
        nombreArchivo: m['nombre'] ?? '',
        tipoReporte:   m['tipo_reporte'] ?? '',
        categoria:     m['categoria'] ?? 'Otros',
        fecha:  DateTime.tryParse(m['fecha'] ?? '') ?? DateTime.now(),
        generadoPor: m['usuario'] ?? '',
        desdeIso: m['desde'] as String?,
        hastaIso: m['hasta'] as String?,
        encabezados: ((m['encabezados'] as List?) ?? [])
            .map((e) => e.toString()).toList(),
        filas: ((m['filas'] as List?) ?? [])
            .map<List<dynamic>>((row) =>
              (row as List?)?.toList() ?? <dynamic>[]).toList(),
        detalles: ((m['detalles'] as List?) ?? [])
            .map<Map<String,dynamic>>((d) =>
              Map<String,dynamic>.from(d as Map)).toList(),
        resumen: Map<String,dynamic>.from(m['resumen'] as Map? ?? {}),
      );
}

class HistorialReportes {
  static const _kKey = 'historial_reportes';
  static List<HistorialReporteEntry> entradas = [];

  /// Carga el historial desde SharedPreferences. Llamar al inicio de
  /// VentanaReportes.
  static Future<void> cargar() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kKey);
      if (raw == null || raw.isEmpty) return;
      final list = jsonDecode(raw) as List;
      entradas = list
          .map((m) => HistorialReporteEntry.fromMap(m as Map<String, dynamic>))
          .toList();
    } catch (e) {
      debugPrint('[HistorialReportes] cargar: $e');
    }
  }

  /// Guarda el historial actual a disco. Llamar después de cada cambio.
  static Future<void> _persistir() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(_kKey,
          jsonEncode(entradas.map((e) => e.toMap()).toList()));
    } catch (e) {
      debugPrint('[HistorialReportes] persistir: $e');
    }
  }

  /// Agrega una entrada al historial.
  static Future<void> agregar(HistorialReporteEntry e) async {
    entradas.insert(0, e); // más recientes primero
    // Limitar a 100 últimas para no crecer indefinido
    if (entradas.length > 100) {
      entradas = entradas.sublist(0, 100);
    }
    await _persistir();
  }

  /// Elimina del historial (NO borra el archivo físico).
  static Future<void> eliminar(int indice) async {
    if (indice < 0 || indice >= entradas.length) return;
    entradas.removeAt(indice);
    await _persistir();
  }

  static Future<void> limpiarTodo() async {
    entradas.clear();
    await _persistir();
  }

  /// Categoriza un nombre de archivo en una de las secciones conocidas.
  static String categoriaPorNombre(String nombre) {
    final n = nombre.toLowerCase();
    if (n.contains('venta') || n.contains('factura')) return 'Ventas';
    if (n.contains('inventario') || n.contains('stock') || n.contains('imei')) return 'Inventario';
    if (n.contains('cuenta') || n.contains('cobrar') || n.contains('pagar')) return 'Cuentas';
    if (n.contains('linea') || n.contains('activacion')) return 'Líneas';
    if (n.contains('cierre')) return 'Cierres';
    if (n.contains('comision')) return 'Comisiones';
    if (n.contains('servicio') || n.contains('tecnico')) return 'Servicio Técnico';
    return 'Otros';
  }
}

// ════════════════════════════════════════════════════════════
//  GENERADORES DE REPORTES
//  Cada función ahora construye un objeto HistorialReporteEntry
//  con los datos completos y lo agrega al historial. NO genera
//  archivos en disco — el usuario abre el reporte dentro de la
//  app desde la pestaña de historial. Si lo necesita, puede
//  descargar el Excel desde el visor.
// ════════════════════════════════════════════════════════════

// ── Helper para registrar un reporte recién generado ─────────
Future<void> _registrarReporte(HistorialReporteEntry e) async {
  await HistorialReportes.agregar(e);
}

String _nombreReporte(String base, DateTime? d, DateTime? h) =>
    '$base — ${_etiquetaRango(d, h)}';

String _etiquetaRango(DateTime? d, DateTime? h) {
  if (d == null && h == null) return 'Histórico completo';
  String f(DateTime x) =>
      '${x.day.toString().padLeft(2, '0')}/${x.month.toString().padLeft(2, '0')}/${x.year}';
  final ds = d != null ? f(d) : 'inicio';
  final hs = h != null ? f(h) : 'hoy';
  return '$ds al $hs';
}

// ════════════════════════════════════════════════════════════
//  VENTAS — incluye TODO el detalle de cada factura:
//  cliente, número, productos (equipos por IMEI + items sin IMEI)
//  y desglose de pagos.
// ════════════════════════════════════════════════════════════
/// true si la factura (por sus pagos) es una venta financiada
/// (Cashea / Weppa / Krece). Mismo criterio que el Excel de ventas.
bool _facturaEsFinanciadaPorPagos(List pagos) {
  for (final p in pagos) {
    if (p is! Map) continue;
    final tipo = (p['tipo'] ?? '').toString().toLowerCase();
    final fin = (p['financiadora'] ?? '').toString();
    if (tipo == 'financiado' && fin.isNotEmpty) return true;
    final met = (p['metodo'] ?? '').toString().toLowerCase();
    if (['cashea', 'weppa', 'krece'].contains(met)) return true;
  }
  return false;
}

/// Calcula el monto cobrado de CADA renglón de una factura del reporte de
/// ventas y lo deja en `monto_renglon_usd` (más `financiado`: bool).
///
/// La BD no guarda el precio ni el F/D de cada renglón, así que:
///  · Si la venta es financiada, los equipos con IMEI son los financiados
///    (llevan la inicial cobrada) y los items sin IMEI son de contado
///    (llevan su precio). Si no hay equipos con IMEI, todos los items se
///    consideran financiados.
///  · Si es de contado, lo cobrado se reparte según el precio de cada uno.
/// La suma de los renglones = total cobrado de la factura (sin duplicar).
void _asignarMontoRenglones(
    List<Map<String, dynamic>> productos, List pagos, double cobradoUsd) {
  if (productos.isEmpty) return;
  final esFin = _facturaEsFinanciadaPorPagos(pagos);
  final hayImei = productos.any(
      (p) => (p['imei'] ?? '').toString().trim().isNotEmpty);
  final financiados = productos.map((p) {
    if (!esFin) return false;
    if (!hayImei) return true;
    return (p['imei'] ?? '').toString().trim().isNotEmpty;
  }).toList();
  final precios = productos
      .map((p) => double.tryParse(p['precio_venta']?.toString() ?? '') ?? 0.0)
      .toList();
  final montos = repartirCobroEntreRenglones(
      precios: precios, financiados: financiados, cobradoUsd: cobradoUsd);
  for (var i = 0; i < productos.length; i++) {
    productos[i]['financiado'] = financiados[i];
    productos[i]['monto_renglon_usd'] = montos[i];
  }
}

Future<void> generarReporteVentas(
    {DateTime? desde, DateTime? hasta, String? tienda}) async {
  final detalles = <Map<String, dynamic>>[];
  final filas = <List<dynamic>>[];
  // Totales SEPARADOS por moneda: el `total` de la factura es la suma
  // cruda de sus pagos y mezcla Bs con $ (salía "$100.000" en vez de
  // "100.000 Bs"). Se lleva el total en Bs, en $ y el equivalente en $.
  double granTotalUsdEquiv = 0, granTotalBs = 0, granTotalUsd = 0;
  final Map<String, double> totalPorMetodo = {};
  // ── Filtro por tienda (igual que el cierre de caja) ──
  // Dueño/Admin/Gerente eligen la tienda ('Todas' o null = todas); el
  // resto queda forzado a SU tienda aunque se pase otra.
  final String? tiendaEfectiva = puedeVerTodasLasTiendas()
      ? ((tienda == null || tienda.isEmpty || tienda == 'Todas')
          ? null : tienda)
      : (tiendaUsuarioActual().isEmpty ? null : tiendaUsuarioActual());

  try {
    // Cargar facturas
    final raw = await _Api.get('facturas');
    final lista = (raw as List?) ?? [];

    // Cargar productos y stock IMEI para enriquecer descripciones
    List productosRaw = [];
    List stockImeiRaw = [];
    try {
      productosRaw = (await _Api.get('productos') as List?) ?? [];
    } catch (_) {}
    try {
      stockImeiRaw = (await _Api.get('stock_imei') as List?) ?? [];
    } catch (_) {}

    // Indexar por código / IMEI para búsquedas rápidas
    final prodPorCodigo = <String, Map>{};
    for (final p in productosRaw) {
      final c = (p['codigo'] ?? '').toString();
      if (c.isNotEmpty) prodPorCodigo[c] = p as Map;
    }
    final imeiInfo = <String, Map>{};
    for (final i in stockImeiRaw) {
      final imei = (i['imei'] ?? '').toString();
      if (imei.isNotEmpty) imeiInfo[imei] = i as Map;
    }

    for (var v in lista) {
      if (!_enRango(v['fecha'], desde, hasta)) continue;
      if (tiendaEfectiva != null &&
          (v['tienda'] ?? '').toString() != tiendaEfectiva) {
        continue;
      }

      final totales = totalesPagosPorMoneda((v['pagos'] as List?) ?? []);
      // Total de la factura en $ (pagos en Bs convertidos con la tasa
      // histórica de cada pago). Si no hay pagos, se usa el total crudo.
      final total = ((v['pagos'] as List?) ?? []).isEmpty
          ? (double.tryParse(v['total']?.toString() ?? '0') ?? 0)
          : redondearPrecio(totales.equivUsd);
      granTotalUsdEquiv += total;
      granTotalBs += totales.bs;
      granTotalUsd += ((v['pagos'] as List?) ?? []).isEmpty ? total : totales.usd;

      // Construir lista de productos enriquecidos
      final productosDetalle = <Map<String, dynamic>>[];

      // Equipos con IMEI
      final rawEquipos = (v['equipos'] as List?) ?? [];
      for (final e in rawEquipos) {
        String imei = '';
        String vendedorEq = '';
        if (e is String) {
          imei = e;
        } else if (e is Map) {
          imei = (e['imei'] ?? '').toString();
          vendedorEq = (e['vendedor'] ?? '').toString().trim();
        }
        // Buscar info del IMEI
        final info = imeiInfo[imei];
        final codigoProd = (info?['producto_codigo'] ?? '').toString();
        final prodInfo = prodPorCodigo[codigoProd];
        productosDetalle.add({
          'tipo': 'Equipo (IMEI)',
          'codigo': codigoProd,
          'nombre': prodInfo?['nombre']?.toString() ??
                    info?['modelo']?.toString() ?? 'Equipo',
          'marca':  prodInfo?['marca']?.toString() ?? info?['marca']?.toString() ?? '',
          'modelo': prodInfo?['modelo']?.toString() ?? info?['modelo']?.toString() ?? '',
          'imei': imei,
          'precio_venta': prodInfo?['precio_venta']?.toString() ?? '',
          'precio_costo': prodInfo?['precio_costo']?.toString() ?? '',
          // Vendedor asignado a este equipo (vacío → cae al creador)
          'vendedor': vendedorEq,
        });
      }

      // Items sin IMEI (accesorios, líneas, etc.)
      final rawItems = (v['items'] as List?) ?? [];
      for (final it in rawItems) {
        String codigo = '';
        String vendedorIt = '';
        if (it is String) {
          codigo = it;
        } else if (it is Map) {
          codigo = (it['producto_codigo'] ?? it['codigo'] ?? '').toString();
          vendedorIt = (it['vendedor'] ?? '').toString().trim();
        }
        final prodInfo = prodPorCodigo[codigo];
        productosDetalle.add({
          'tipo': prodInfo?['categoria']?.toString() ?? 'Producto',
          'codigo': codigo,
          'nombre': prodInfo?['nombre']?.toString() ?? codigo,
          'marca':  prodInfo?['marca']?.toString() ?? '',
          'modelo': prodInfo?['modelo']?.toString() ?? '',
          'imei': '',
          'precio_venta': prodInfo?['precio_venta']?.toString() ?? '',
          'precio_costo': prodInfo?['precio_costo']?.toString() ?? '',
          'vendedor': vendedorIt,
        });
      }

      // Pagos de la factura
      // BUG CORREGIDO: antes solo guardábamos `financiador` (persona),
      // faltaba el campo `financiadora` (Cashea/Weppa/Krece) que es lo
      // que el reporte usa para detectar si la venta es financiada.
      // También guardamos cuotas, tasa, nombre_lista y es_inicial para
      // que el Excel pueda calcular correctamente.
      final pagosDetalle = <Map<String, dynamic>>[];
      final rawPagos = (v['pagos'] as List?) ?? [];
      for (final p in rawPagos) {
        if (p is Map) {
          final monto = double.tryParse(p['monto']?.toString() ?? '0') ?? 0;
          final met = (p['metodo'] ?? '').toString();
          pagosDetalle.add({
            'metodo': met,
            'tipo': (p['tipo'] ?? '').toString(),
            'financiador':  (p['financiador']  ?? '').toString(),
            'financiadora': (p['financiadora'] ?? '').toString(),
            'monto': monto,
            'numero_cuotas': p['numero_cuotas'],
            'monto_cuota':   p['monto_cuota'],
            'tasa_cambio':   p['tasa_cambio'],
            'nombre_lista': (p['nombre_lista'] ?? '').toString(),
            'es_inicial':    p['es_inicial'],
            // ── Auditoría de pago móvil ──
            'referencia':       (p['referencia'] ?? '').toString(),
            'cedula_pagador':   (p['cedula_pagador'] ?? '').toString(),
            'telefono_pagador': (p['telefono_pagador'] ?? '').toString(),
            'banco_origen':     (p['banco_origen'] ?? '').toString(),
            'banco_destino':    (p['banco_destino'] ?? '').toString(),
            'fecha_pago':       (p['fecha_pago'] ?? '').toString(),
          });
          totalPorMetodo[met] = (totalPorMetodo[met] ?? 0) + monto;
        }
      }

      // ── Monto de CADA renglón (producto) ──
      // Antes cada renglón repetía el total de la factura (teléfono con
      // inicial $50 + vidrio $4 → "$54" en los dos). Ahora se reparte lo
      // cobrado: el accesorio lleva su precio y el equipo financiado la
      // inicial que realmente se cobró.
      _asignarMontoRenglones(productosDetalle, pagosDetalle, total);

      detalles.add({
        'nro_factura': (v['nro_factura'] ?? '').toString(),
        'cliente':     (v['cliente'] ?? '').toString(),
        'cedula':      (v['cedula'] ?? '').toString(),
        'telefono':    (v['telefono'] ?? '').toString(),
        'vendedor':    (v['vendedor'] ?? '').toString(),
        'tienda':      (v['tienda'] ?? '').toString(),
        'fecha':       (v['fecha'] ?? '').toString(),
        'tipo_venta':  (v['tipo_venta'] ?? '').toString(),
        'total': total,
        'total_bs':  totales.bs,
        'total_usd': ((v['pagos'] as List?) ?? []).isEmpty ? total : totales.usd,
        'productos': productosDetalle,
        'pagos': pagosDetalle,
      });

      filas.add([
        v['nro_factura'] ?? '',
        v['cliente']     ?? '',
        v['cedula']      ?? '',
        v['telefono']    ?? '',
        v['vendedor']    ?? '',
        v['tienda']      ?? '',
        v['fecha']       ?? '',
        total,
        totales.bs,
        ((v['pagos'] as List?) ?? []).isEmpty ? total : totales.usd,
        v['tipo_venta']  ?? '',
      ]);
    }
  } catch (e) {
    debugPrint('generarReporteVentas: $e');
  }

  await _registrarReporte(HistorialReporteEntry(
    nombreArchivo: _nombreReporte(
        tiendaEfectiva == null
            ? 'Reporte de Ventas'
            : 'Reporte de Ventas ($tiendaEfectiva)',
        desde, hasta),
    tipoReporte: 'ventas',
    categoria: 'Ventas',
    fecha: DateTime.now(),
    generadoPor: usuarioSesion?.nombre ?? '—',
    desdeIso: desde?.toIso8601String(),
    hastaIso: hasta?.toIso8601String(),
    encabezados: const [
      'Nro Factura','Cliente','Cédula','Teléfono','Vendedor',
      'Tienda','Fecha','Total equiv. USD','Cobrado Bs','Cobrado USD','F/D'],
    filas: filas,
    detalles: detalles,
    resumen: {
      'tienda': tiendaEfectiva ?? 'Todas',
      'total_facturas': detalles.length,
      // Montos ya formateados con su moneda (el visor los muestra tal cual).
      'total_equivalente_usd': formatCurrency(granTotalUsdEquiv),
      'total_cobrado_en_bs': formatBolivares(granTotalBs),
      'total_cobrado_en_divisas': formatCurrency(granTotalUsd),
      'total_por_metodo': totalPorMetodo.map(
          (k, val) => MapEntry(k, formatMontoPorMetodo(val, k))),
    },
  ));
}

// ════════════════════════════════════════════════════════════
//  INVENTARIO
// ════════════════════════════════════════════════════════════
Future<void> generarReporteInventario({DateTime? desde, DateTime? hasta}) async {
  final filas = <List<dynamic>>[];
  final detalles = <Map<String, dynamic>>[];
  double valorTotalCosto = 0, valorTotalVenta = 0;

  try {
    final rawP = await _Api.get('productos');
    final rawI = await _Api.get('stock_imei');
    final imeis = (rawI as List?) ?? [];
    for (var p in ((rawP as List?) ?? [])) {
      final stockReal = p['categoria'] == 'Telefono'
          ? imeis.where((i) =>
              i['producto_codigo'] == p['codigo'] && (i['vendido'] ?? 0) == 0).length
          : (int.tryParse(p['stock_manual'].toString()) ?? 0);
      final pCosto = double.tryParse(p['precio_costo']?.toString() ?? '0') ?? 0;
      final pVenta = double.tryParse(p['precio_venta']?.toString() ?? '0') ?? 0;
      valorTotalCosto += pCosto * stockReal;
      valorTotalVenta += pVenta * stockReal;

      filas.add([
        p['codigo'] ?? '',
        p['nombre'] ?? '',
        p['categoria'] ?? '',
        p['marca'] ?? '',
        p['modelo'] ?? '',
        stockReal,
        pCosto,
        pVenta,
      ]);
      detalles.add({
        'codigo': (p['codigo'] ?? '').toString(),
        'nombre': (p['nombre'] ?? '').toString(),
        'categoria': (p['categoria'] ?? '').toString(),
        'marca': (p['marca'] ?? '').toString(),
        'modelo': (p['modelo'] ?? '').toString(),
        'stock': stockReal,
        'precio_costo': pCosto,
        'precio_venta': pVenta,
      });
    }
  } catch (e) {
    debugPrint('generarReporteInventario: $e');
  }

  await _registrarReporte(HistorialReporteEntry(
    nombreArchivo: _nombreReporte('Inventario General', desde, hasta),
    tipoReporte: 'inventario',
    categoria: 'Inventario',
    fecha: DateTime.now(),
    generadoPor: usuarioSesion?.nombre ?? '—',
    desdeIso: desde?.toIso8601String(),
    hastaIso: hasta?.toIso8601String(),
    encabezados: const [
      'Código','Nombre','Categoría','Marca','Modelo',
      'Stock','Precio Costo','Precio Venta'],
    filas: filas,
    detalles: detalles,
    resumen: {
      'total_productos': filas.length,
      'valor_total_costo': valorTotalCosto,
      'valor_total_venta': valorTotalVenta,
    },
  ));
}

// ════════════════════════════════════════════════════════════
//  CUENTAS POR COBRAR — incluye los pagos efectuados a cada cuenta
// ════════════════════════════════════════════════════════════
Future<void> generarReporteCuentas({DateTime? desde, DateTime? hasta}) async {
  final filas = <List<dynamic>>[];
  final detalles = <Map<String, dynamic>>[];
  double sumaTotal = 0, sumaSaldo = 0;

  try {
    final raw = await _Api.get('cuentas_cobrar');
    for (var c in ((raw as List?) ?? [])) {
      final total = double.tryParse(c['monto_total']?.toString() ?? '0') ?? 0;
      final pagosLista = (c['pagos'] as List?) ?? [];
      final pagado = pagosLista.fold<double>(
          0, (s, p) => s + (double.tryParse(p['monto']?.toString() ?? '0') ?? 0));
      final saldo = (total - pagado).clamp(0.0, double.infinity);
      final estado = saldo <= 0 ? 'Pagado' : 'Pendiente';

      sumaTotal += total;
      sumaSaldo += saldo;

      filas.add([
        c['nombre'] ?? '',
        c['cedula'] ?? '',
        c['telefono'] ?? '',
        total,
        saldo,
        estado,
      ]);
      detalles.add({
        'nombre': (c['nombre'] ?? '').toString(),
        'cedula': (c['cedula'] ?? '').toString(),
        'telefono': (c['telefono'] ?? '').toString(),
        'monto_total': total,
        'pagado': pagado,
        'saldo': saldo,
        'estado': estado,
        'pagos': pagosLista.map((p) => {
          'metodo': (p['metodo'] ?? '').toString(),
          'monto': double.tryParse(p['monto']?.toString() ?? '0') ?? 0,
          'fecha': (p['fecha'] ?? '').toString(),
        }).toList(),
      });
    }
  } catch (e) {
    debugPrint('generarReporteCuentas: $e');
  }

  await _registrarReporte(HistorialReporteEntry(
    nombreArchivo: _nombreReporte('Cuentas por Cobrar', desde, hasta),
    tipoReporte: 'cuentas_cobrar',
    categoria: 'Cuentas',
    fecha: DateTime.now(),
    generadoPor: usuarioSesion?.nombre ?? '—',
    desdeIso: desde?.toIso8601String(),
    hastaIso: hasta?.toIso8601String(),
    encabezados: const [
      'Cliente','Cédula','Teléfono','Monto Total','Saldo Pendiente','Estado'],
    filas: filas,
    detalles: detalles,
    resumen: {
      'total_cuentas': filas.length,
      'monto_total': sumaTotal,
      'saldo_total': sumaSaldo,
    },
  ));
}

// ════════════════════════════════════════════════════════════
//  CUENTAS POR PAGAR
// ════════════════════════════════════════════════════════════
Future<void> generarReporteCxPagar({DateTime? desde, DateTime? hasta}) async {
  final filas = <List<dynamic>>[];
  final detalles = <Map<String, dynamic>>[];
  double sumaTotal = 0, sumaSaldo = 0;

  try {
    final raw = await _Api.get('cuentas_pagar');
    for (var c in ((raw as List?) ?? [])) {
      final total = double.tryParse(c['monto_total']?.toString() ?? '0') ?? 0;
      final pagosLista = (c['pagos'] as List?) ?? [];
      final pagado = pagosLista.fold<double>(
          0, (s, p) => s + (double.tryParse(p['monto']?.toString() ?? '0') ?? 0));
      final saldo = (total - pagado).clamp(0.0, double.infinity);
      final ident = (c['cedula'] ?? c['rif'] ?? '').toString();

      sumaTotal += total;
      sumaSaldo += saldo;

      filas.add([
        c['nombre'] ?? '',
        ident,
        total,
        saldo,
        saldo <= 0 ? 'Pagado' : 'Pendiente',
      ]);
      detalles.add({
        'nombre': (c['nombre'] ?? '').toString(),
        'identificacion': ident,
        'monto_total': total,
        'pagado': pagado,
        'saldo': saldo,
        'estado': saldo <= 0 ? 'Pagado' : 'Pendiente',
        'pagos': pagosLista.map((p) => {
          'metodo': (p['metodo'] ?? '').toString(),
          'monto': double.tryParse(p['monto']?.toString() ?? '0') ?? 0,
          'fecha': (p['fecha'] ?? '').toString(),
        }).toList(),
      });
    }
  } catch (e) {
    debugPrint('generarReporteCxPagar: $e');
  }

  await _registrarReporte(HistorialReporteEntry(
    nombreArchivo: _nombreReporte('Cuentas por Pagar', desde, hasta),
    tipoReporte: 'cuentas_pagar',
    categoria: 'Cuentas',
    fecha: DateTime.now(),
    generadoPor: usuarioSesion?.nombre ?? '—',
    desdeIso: desde?.toIso8601String(),
    hastaIso: hasta?.toIso8601String(),
    encabezados: const [
      'Proveedor/Acreedor','Cédula/RIF','Monto Total','Saldo','Estado'],
    filas: filas,
    detalles: detalles,
    resumen: {
      'total_cuentas': filas.length,
      'monto_total': sumaTotal,
      'saldo_total': sumaSaldo,
    },
  ));
}

// ════════════════════════════════════════════════════════════
//  LÍNEAS / ACTIVACIONES
// ════════════════════════════════════════════════════════════
Future<void> generarReporteLineas({DateTime? desde, DateTime? hasta}) async {
  final filas = <List<dynamic>>[];
  final detalles = <Map<String, dynamic>>[];
  int activadas = 0, pendientes = 0;

  try {
    final raw = await _Api.get('lineas');
    for (var l in ((raw as List?) ?? [])) {
      if (!_enRango(l['fecha'], desde, hasta)) continue;
      final activa = (l['activada'] == 1 || l['activada'] == '1');
      if (activa) activadas++; else pendientes++;

      filas.add([
        l['nombre'] ?? '',
        l['cedula'] ?? '',
        l['telefono'] ?? '',
        l['tipo'] ?? '',
        l['plan'] ?? '',
        l['imei1'] ?? '',
        l['imei2'] ?? '',
        l['chip'] ?? '',
        l['patc'] ?? '',
        l['asignado'] ?? '',
        l['esim'] ?? '',
        activa ? 'Sí' : 'No',
        (l['recargada'] == 1 || l['recargada'] == '1') ? 'Sí' : 'No',
        l['vendedor'] ?? '',
        l['fecha'] ?? '',
      ]);
      detalles.add({
        'nombre': (l['nombre'] ?? '').toString(),
        'cedula': (l['cedula'] ?? '').toString(),
        'telefono': (l['telefono'] ?? '').toString(),
        'tipo': (l['tipo'] ?? '').toString(),
        'plan': (l['plan'] ?? '').toString(),
        'imei1': (l['imei1'] ?? '').toString(),
        'imei2': (l['imei2'] ?? '').toString(),
        'chip':  (l['chip'] ?? '').toString(),
        'patc':  (l['patc'] ?? '').toString(),
        'asignado': (l['asignado'] ?? '').toString(),
        'esim': (l['esim'] ?? '').toString(),
        'activada': activa,
        'recargada': (l['recargada'] == 1 || l['recargada'] == '1'),
        'vendedor': (l['vendedor'] ?? '').toString(),
        'fecha': (l['fecha'] ?? '').toString(),
      });
    }
  } catch (e) {
    debugPrint('generarReporteLineas: $e');
  }

  await _registrarReporte(HistorialReporteEntry(
    nombreArchivo: _nombreReporte('Gestión de Líneas', desde, hasta),
    tipoReporte: 'lineas',
    categoria: 'Líneas',
    fecha: DateTime.now(),
    generadoPor: usuarioSesion?.nombre ?? '—',
    desdeIso: desde?.toIso8601String(),
    hastaIso: hasta?.toIso8601String(),
    encabezados: const [
      'Nombre','Cédula','Teléfono','Tipo','Plan','IMEI 1','IMEI 2',
      'Chip','Patc','Nro Asignado','eSIM','Activada','Recargada',
      'Vendedor','Fecha'],
    filas: filas,
    detalles: detalles,
    resumen: {
      'total_lineas': filas.length,
      'activadas': activadas,
      'pendientes': pendientes,
    },
  ));
}

// ════════════════════════════════════════════════════════════
//  IMEI
// ════════════════════════════════════════════════════════════
Future<void> generarReporteIMEI({DateTime? desde, DateTime? hasta}) async {
  final filas = <List<dynamic>>[];
  final detalles = <Map<String, dynamic>>[];
  int vendidos = 0, disponibles = 0;
  int ingresadosPeriodo = 0, vendidosPeriodo = 0;
  // Conteos por marca, modelo y ubicación para el resumen
  final Map<String, int> porMarca = {};
  final Map<String, int> porModelo = {};
  final Map<String, int> disponiblesPorUbicacion = {};
  final hayRango = desde != null || hasta != null;

  // Sin el listado de IMEIs no hay reporte: antes el error se tragaba
  // y se guardaba un reporte vacío que parecía "no hay equipos". Ahora
  // el error sube y la pantalla lo muestra.
  final rawI = (await _Api.get('stock_imei') as List?) ?? [];
  // Productos solo completan marca/modelo; si fallan, el reporte sigue.
  List productosRaw = [];
  try {
    productosRaw = (await _Api.get('productos') as List?) ?? [];
  } catch (e) {
    debugPrint('generarReporteIMEI productos: $e');
  }

  final prodPorCodigo = <String, Map>{};
  for (final p in productosRaw) {
    if (p is! Map) continue;
    final c = (p['codigo'] ?? '').toString();
    if (c.isNotEmpty) prodPorCodigo[c] = p;
  }

  for (var i in rawI) {
    if (i is! Map) continue;
    try {
      final v = (i['vendido'] == 1 || i['vendido'] == '1' || i['vendido'] == true);
      // Antes se filtraba SOLO por fecha_ingreso: con cualquier rango
      // de fechas quedaban fuera todos los equipos que entraron antes
      // (casi todo el stock) y los que tienen fecha_ingreso vacía o en
      // formato raro, y el reporte salía vacío. Ahora, con rango, entra:
      //   · todo equipo disponible hoy (es el stock actual),
      //   · lo que ingresó en el período,
      //   · lo que se vendió en el período.
      final ingresoEnRango = hayRango && _enRango(i['fecha_ingreso'], desde, hasta);
      final ventaEnRango = hayRango && v && _enRango(i['fecha_venta'], desde, hasta);
      if (hayRango && v && !ingresoEnRango && !ventaEnRango) continue;
      if (ingresoEnRango) ingresadosPeriodo++;
      if (ventaEnRango) vendidosPeriodo++;
      if (v) vendidos++; else disponibles++;
      final movimiento = !hayRango
          ? (v ? 'Vendido' : 'En stock')
          : ventaEnRango
              ? 'Vendido en el período'
              : ingresoEnRango
                  ? 'Ingresó en el período'
                  : 'En stock';

      // Resolver marca/modelo/nombre cruzando con productos.
      final codigoProd = (i['producto_codigo'] ?? i['codigo'] ?? '').toString();
      final prodInfo = prodPorCodigo[codigoProd];

      String marca = (i['marca'] ?? '').toString().trim();
      if (marca.isEmpty) {
        marca = (prodInfo?['marca'] ?? '').toString().trim();
      }
      String modelo = (i['modelo'] ?? '').toString().trim();
      if (modelo.isEmpty) {
        modelo = (prodInfo?['modelo'] ?? '').toString().trim();
      }
      // Nombre comercial del equipo (lo añadimos como columna extra).
      String nombreEquipo = (i['producto_nombre'] ?? i['nombre'] ?? '').toString().trim();
      if (nombreEquipo.isEmpty) {
        nombreEquipo = (prodInfo?['nombre'] ?? '').toString().trim();
      }
      // Si después de todo siguen vacíos, los marcamos como 'N/D' para
      // que en el reporte sea evidente que falta el dato en la BD.
      if (marca.isEmpty)  marca  = 'N/D';
      if (modelo.isEmpty) modelo = 'N/D';

      // Conteos
      porMarca[marca]   = (porMarca[marca]   ?? 0) + 1;
      porModelo[modelo] = (porModelo[modelo] ?? 0) + 1;
      final ubicacion = (i['ubicacion'] ?? '').toString().trim();
      if (!v) {
        final u = ubicacion.isEmpty ? 'Sin asignar' : ubicacion;
        disponiblesPorUbicacion[u] = (disponiblesPorUbicacion[u] ?? 0) + 1;
      }

      filas.add([
        (i['imei'] ?? '').toString(),
        codigoProd,
        nombreEquipo,
        marca,
        modelo,
        (i['proveedor'] ?? '').toString(),
        (i['color'] ?? '').toString(),
        (i['porcentaje_bateria'] ?? '').toString(),
        ubicacion,
        v ? 'Sí' : 'No',
        (i['fecha_ingreso'] ?? '').toString(),
        (i['fecha_venta'] ?? '').toString(),
        movimiento,
      ]);
      detalles.add({
        'imei': (i['imei'] ?? '').toString(),
        'codigo': codigoProd,
        'nombre': nombreEquipo,
        'marca': marca,
        'modelo': modelo,
        'proveedor': (i['proveedor'] ?? '').toString(),
        'color': (i['color'] ?? '').toString(),
        'porcentaje_bateria': (i['porcentaje_bateria'] ?? '').toString(),
        'ubicacion': ubicacion,
        'vendido': v,
        'fecha_ingreso': (i['fecha_ingreso'] ?? '').toString(),
        'fecha_venta': (i['fecha_venta'] ?? '').toString(),
        'movimiento': movimiento,
      });
    } catch (e) {
      // Una fila con datos raros no debe tumbar el reporte entero.
      debugPrint('generarReporteIMEI fila ${i['imei']}: $e');
    }
  }

  // Función helper para obtener el top N de un mapa por valor descendente.
  Map<String, int> topN(Map<String, int> m, int n) {
    final entries = m.entries.toList()
      ..sort((a, b) => b.value.compareTo(a.value));
    return Map.fromEntries(entries.take(n));
  }

  await _registrarReporte(HistorialReporteEntry(
    nombreArchivo: _nombreReporte('Gestión de IMEIs', desde, hasta),
    tipoReporte: 'imei',
    categoria: 'Inventario',
    fecha: DateTime.now(),
    generadoPor: usuarioSesion?.nombre ?? '—',
    desdeIso: desde?.toIso8601String(),
    hastaIso: hasta?.toIso8601String(),
    encabezados: const [
      'IMEI','Código','Equipo','Marca','Modelo','Proveedor','Color',
      '% Batería','Ubicación','Vendido','Fecha Ingreso','Fecha Venta',
      'Movimiento'],
    filas: filas,
    detalles: detalles,
    resumen: {
      'total_imeis': filas.length,
      'vendidos': vendidos,
      'disponibles': disponibles,
      if (hayRango) 'ingresados_en_periodo': ingresadosPeriodo,
      if (hayRango) 'vendidos_en_periodo': vendidosPeriodo,
      'disponibles_por_ubicacion': disponiblesPorUbicacion,
      'por_marca':  topN(porMarca, 10),
      'por_modelo': topN(porModelo, 10),
    },
  ));
}

// ════════════════════════════════════════════════════════════
//  CIERRES DE CAJA — incluye desglose por método de pago
// ════════════════════════════════════════════════════════════
Future<void> generarReporteCierres({DateTime? desde, DateTime? hasta}) async {
  final filas = <List<dynamic>>[];
  final detalles = <Map<String, dynamic>>[];
  double granTotal = 0;
  // Totales por moneda real (el monto_total de cierres viejos mezcla Bs y $).
  final Map<String, double> granPorMetodo = {};

  try {
    final raw = await _Api.get('cierres');
    // Cada quien ve sólo los cierres de su tienda (Dueño/Admin: todas).
    final cierresVisibles = filtrarPorTienda(
        ((raw as List?) ?? []).whereType<Map>()
            .map((m) => Map<String, dynamic>.from(m)).toList());
    for (var c in cierresVisibles) {
      if (!_enRango(c['fecha_cierre'], desde, hasta)) continue;
      final total = double.tryParse(c['monto_total']?.toString() ?? '0') ?? 0;
      granTotal += total;
      final porMetodo = <String, double>{};
      for (final m in (c['metodos'] as List? ?? [])) {
        final met = (m['metodo'] ?? '').toString();
        final monto = double.tryParse(m['monto']?.toString() ?? '0') ?? 0;
        porMetodo[met] = (porMetodo[met] ?? 0) + monto;
        granPorMetodo[met] = (granPorMetodo[met] ?? 0) + monto;
      }
      // Cada método con su moneda: "Pago Móvil: Bs 1.000,00 | Zelle: $20.00"
      final metodos = porMetodo.entries
          .map((m) => "${m.key}: ${formatMontoPorMetodo(m.value, m.key)}")
          .join(' | ');
      final metodosDetalle = (c['metodos'] as List? ?? [])
          .map((m) => {
            'metodo': (m['metodo'] ?? '').toString(),
            'monto': double.tryParse(m['monto']?.toString() ?? '0') ?? 0,
          }).toList();

      filas.add([
        c['uid'] ?? '',
        c['tienda'] ?? '',
        c['fecha_cierre'] ?? '',
        porMetodo.isEmpty ? total : formatTotalesPorMetodos(porMetodo),
        c['usuario_cierre'] ?? '',
        metodos,
      ]);
      detalles.add({
        'uid': (c['uid'] ?? '').toString(),
        'tienda': (c['tienda'] ?? '').toString(),
        'fecha_cierre': (c['fecha_cierre'] ?? '').toString(),
        'monto_total': total,
        'usuario_cierre': (c['usuario_cierre'] ?? '').toString(),
        'metodos': metodosDetalle,
      });
    }
  } catch (e) {
    debugPrint('generarReporteCierres: $e');
  }

  await _registrarReporte(HistorialReporteEntry(
    nombreArchivo: _nombreReporte('Cierres de Caja', desde, hasta),
    tipoReporte: 'cierres',
    categoria: 'Cierres',
    fecha: DateTime.now(),
    generadoPor: usuarioSesion?.nombre ?? '—',
    desdeIso: desde?.toIso8601String(),
    hastaIso: hasta?.toIso8601String(),
    encabezados: const [
      'UID','Tienda','Fecha','Total','Responsable','Métodos de Pago'],
    filas: filas,
    detalles: detalles,
    resumen: {
      'total_cierres': filas.length,
      'monto_total': granPorMetodo.isEmpty
          ? granTotal
          : formatTotalesPorMetodos(granPorMetodo),
    },
  ));
}

// ════════════════════════════════════════════════════════════
//  COMISIONES
// ════════════════════════════════════════════════════════════
Future<void> generarReporteComisiones({DateTime? desde, DateTime? hasta}) async {
  final filas = <List<dynamic>>[];
  final detalles = <Map<String, dynamic>>[];

  try {
    final raw = await _Api.get('comisiones_historial');
    for (var h in ((raw as List?) ?? [])) {
      final tasa = double.tryParse(h['tasa']?.toString() ?? '1') ?? 1;
      final periodo = "${h['fecha_inicio']} — ${h['fecha_fin']}";
      // filtrar por rango si aplica
      if (!_enRango(h['fecha_inicio'], desde, hasta) &&
          !_enRango(h['fecha_fin'], desde, hasta)) {
        // si ningún extremo cae en rango, omitir
        if (desde != null || hasta != null) continue;
      }
      for (var d in ((h['detalle'] as List?) ?? [])) {
        final r = ResumenComision.fromMap(d);
        // Usamos los IDs originales para mantener compatibilidad con
        // reportes históricos que esperan estas mismas columnas.
        filas.add([
          r.vendedor,
          r.conteoDe('telefono'),
          r.conteoDe('accesorio'),
          r.conteoDe('televisor'),
          r.conteoDe('linea'),
          r.conteoDe('linea_blanca'),
          r.conteoDe('financiador'),
          r.comisionWeppa,
          r.base,
          r.totalComision,
          r.totalPagar() * tasa,
          periodo,
        ]);
        detalles.add({
          'vendedor': r.vendedor,
          'telefonos': r.conteoDe('telefono'),
          'accesorios': r.conteoDe('accesorio'),
          'televisores': r.conteoDe('televisor'),
          'lineas': r.conteoDe('linea'),
          'linea_blanca': r.conteoDe('linea_blanca'),
          'financiador': r.conteoDe('financiador'),
          'comision_weppa': r.comisionWeppa,
          'base': r.base,
          'total_comision': r.totalComision,
          'total_bs': r.totalPagar() * tasa,
          'tasa': tasa,
          'periodo': periodo,
          // Categorías personalizadas extra (las que no están en el mapeo
          // estándar). Útil para que el reporte muestre Servicio Técnico,
          // etc. cuando existan en los datos.
          'conteos_extra': Map.fromEntries(r.conteos.entries.where((e) =>
              !{'telefono', 'accesorio', 'televisor', 'linea',
                'linea_blanca', 'financiador'}.contains(e.key))),
        });
      }
    }
  } catch (e) {
    debugPrint('generarReporteComisiones: $e');
  }

  await _registrarReporte(HistorialReporteEntry(
    nombreArchivo: _nombreReporte('Comisiones', desde, hasta),
    tipoReporte: 'comisiones',
    categoria: 'Comisiones',
    fecha: DateTime.now(),
    generadoPor: usuarioSesion?.nombre ?? '—',
    desdeIso: desde?.toIso8601String(),
    hastaIso: hasta?.toIso8601String(),
    encabezados: const [
      'Vendedor','Teléfonos','Accesorios','Televisores','Líneas',
      'L. Blanca','Financiador','Com. Weppa','Sueldo Base',
      'Total Comisión','Total Bs','Período'],
    filas: filas,
    detalles: detalles,
    resumen: {
      'total_registros': filas.length,
    },
  ));
}

// ════════════════════════════════════════════════════════════
//  SERVICIO TÉCNICO
// ════════════════════════════════════════════════════════════
Future<void> generarReporteServicios({DateTime? desde, DateTime? hasta}) async {
  final filas = <List<dynamic>>[];
  final detalles = <Map<String, dynamic>>[];
  double granTotal = 0;
  final Map<String, int> porEstado = {};

  try {
    final raw = await _Api.get('servicios');
    for (var sv in ((raw as List?) ?? [])) {
      if (!_enRango(sv['fecha'], desde, hasta)) continue;
      final monto = double.tryParse(sv['monto']?.toString() ?? '0') ?? 0;
      granTotal += monto;
      final est = (sv['estado'] ?? '').toString();
      porEstado[est] = (porEstado[est] ?? 0) + 1;

      filas.add([
        sv['id'] ?? '',
        sv['cliente'] ?? '',
        sv['telefono'] ?? '',
        sv['dispositivo'] ?? '',
        sv['falla'] ?? '',
        sv['tecnico'] ?? '',
        monto,
        est,
        sv['fecha'] ?? '',
      ]);
      detalles.add({
        'id': (sv['id'] ?? '').toString(),
        'cliente': (sv['cliente'] ?? '').toString(),
        'telefono': (sv['telefono'] ?? '').toString(),
        'dispositivo': (sv['dispositivo'] ?? '').toString(),
        'falla': (sv['falla'] ?? '').toString(),
        'tecnico': (sv['tecnico'] ?? '').toString(),
        'monto': monto,
        'estado': est,
        'fecha': (sv['fecha'] ?? '').toString(),
      });
    }
  } catch (e) {
    debugPrint('generarReporteServicios: $e');
  }

  await _registrarReporte(HistorialReporteEntry(
    nombreArchivo: _nombreReporte('Servicio Técnico', desde, hasta),
    tipoReporte: 'servicios',
    categoria: 'Servicio Técnico',
    fecha: DateTime.now(),
    generadoPor: usuarioSesion?.nombre ?? '—',
    desdeIso: desde?.toIso8601String(),
    hastaIso: hasta?.toIso8601String(),
    encabezados: const [
      'ID','Cliente','Teléfono','Dispositivo','Falla','Técnico',
      'Monto','Estado','Fecha'],
    filas: filas,
    detalles: detalles,
    resumen: {
      'total_servicios': filas.length,
      'monto_total': granTotal,
      'por_estado': porEstado,
    },
  ));
}

// ════════════════════════════════════════════════════════════
//  EXPORTACIÓN A EXCEL — bajo demanda desde el visor
//  Recibe una entrada del historial y genera el archivo XLSX
//  con TODA la información disponible (incluyendo sub-tablas
//  de productos y pagos en el caso de ventas).
// ════════════════════════════════════════════════════════════
Future<Uint8List> exportarHistorialAExcel(HistorialReporteEntry e) async {
  final excel = Excel.createExcel();
  // Eliminar la hoja por defecto si existe
  excel.delete('Sheet1');

  // ─────────────────────────────────────────────────────────────
  //  CASO ESPECIAL: REPORTE DE VENTAS
  //  UNA sola hoja con UNA fila por equipo (lo que pediste). No
  //  generamos las hojas separadas de "Productos vendidos" ni
  //  "Pagos" — todo va en una sola tabla con 22 columnas.
  // ─────────────────────────────────────────────────────────────
  if (e.tipoReporte == 'ventas') {
    final s2 = excel['Reporte de Ventas'];

    // Encabezado informativo
    s2.appendRow(_filaCeldas(['REPORTE DE VENTAS — TECNO LÍDER']));
    s2.appendRow(_filaCeldas([
      'Rango: ${_etiquetaRango(
        e.desdeIso != null ? DateTime.tryParse(e.desdeIso!) : null,
        e.hastaIso != null ? DateTime.tryParse(e.hastaIso!) : null)}',
    ]));
    s2.appendRow(_filaCeldas([
      'Generado por: ${e.generadoPor}',
    ]));
    s2.appendRow(_filaCeldas([
      'Tienda: ${e.resumen['tienda'] ?? 'Todas'}',
    ]));
    s2.appendRow(_filaCeldas([
      'Fecha de generación: ${_formatoFechaCompleta(e.fecha)}',
    ]));
    s2.appendRow(<CellValue?>[]);

    // Resumen rápido
    int totalEquipos = 0;
    for (final f in e.detalles) {
      final productos = (f['productos'] as List?) ?? [];
      totalEquipos += productos.length;
    }
    s2.appendRow(_filaCeldas([
      'Total Facturas', 'Total Equipos Vendidos',
    ]));
    s2.appendRow(_filaCeldas([
      e.detalles.length,
      totalEquipos,
    ]));
    s2.appendRow(<CellValue?>[]);

    // Encabezados de la tabla — UNA fila por equipo con todo
    s2.appendRow(_filaCeldas([
      'Fecha',                // 1
      'Nro Factura',          // 2
      'Vendedor',             // 3
      'Tienda',               // 4
      'Cliente',              // 5
      'Cédula',               // 6
      'Teléfono',             // 7
      'Marca',                // 8
      'Modelo',               // 9
      'IMEI',                 // 10
      'Código',               // 11
      'Tipo Venta',           // 12 (Contado / Financiado)
      'Financiadora',         // 13 (Cashea / Weppa / Krece)
      'Lista Aplicada',       // 14 (nombre exacto: normal o promoción)
      'Precio Equipo USD',    // 15
      'Costo USD',            // 16
      'Ganancia USD',         // 17
      'Inicial Lista USD',    // 18 (calculada por la financiadora)
      'Inicial Pagada USD',   // 19 (lo que el cliente entregó)
      'N° Cuotas',            // 20
      'Cuota USD',            // 21
      'Métodos de Pago',      // 22
      'Pagado en Bs',         // 23 (suma de pagos en métodos Bs)
      'Equivale en USD',      // 24 (Pagado en Bs / tasa)
      'Pagado en USD',        // 25 (suma de pagos en métodos USD)
      'Tasa Bs/USD',          // 26 (tasa usada en el cálculo)
      'Monto Renglón USD',    // 27 (lo cobrado por ESTE producto)
      'Pago Móvil (Ref / C.I. / Tel)', // 28 (auditoría)
    ]));
    // NOTA: las columnas 22-26 y 28 son datos de la FACTURA (pagos); se
    // escriben sólo en el PRIMER renglón de cada factura para que al
    // sumar la columna no se dupliquen los montos. La columna 27 es el
    // monto de cada producto (la suma de la factura = total cobrado).

    // Una fila por cada equipo vendido en cada factura
    for (final f in e.detalles) {
      final productos = (f['productos'] as List?) ?? [];
      final pagos = (f['pagos'] as List?) ?? [];

      // ── Datos derivados a nivel FACTURA ──
      // CORRECCIÓN: el campo correcto es `financiadora` (Cashea/Weppa/Krece),
      // NO `financiador` (que es la persona que entregó el equipo).
      // También capturamos nombre_lista para saber si fue venta normal
      // o por lista de promoción.
      String financiadora = '';
      String nombreLista = '';
      bool esFinanciada = false;
      for (final p in pagos) {
        final tipo = (p['tipo'] ?? '').toString();
        final fin  = (p['financiadora'] ?? '').toString();
        if (tipo.toLowerCase() == 'financiado' && fin.isNotEmpty) {
          financiadora = fin;
          nombreLista = (p['nombre_lista'] ?? '').toString();
          esFinanciada = true;
          break;
        }
        // Fallback: si el método de pago se llama Cashea/Weppa/Krece
        final met = (p['metodo'] ?? '').toString();
        if (['cashea','weppa','krece'].contains(met.toLowerCase())) {
          financiadora = met;
          nombreLista = (p['nombre_lista'] ?? '').toString();
          esFinanciada = true;
        }
      }
      final tipoVenta = esFinanciada ? 'Financiado' : 'Contado';

      // ── Cuotas y montoCuota (a nivel factura) ──
      // Vienen del PRIMER pago financiado de la factura. Si la factura
      // tiene varios pagos financiados con distintas cuotas, se toma
      // el primero (el caso real es 1 financiamiento por factura).
      int nCuotasFactura = 0;
      double cuotaFactura = 0;
      for (final p in pagos) {
        final tipo = (p['tipo'] ?? '').toString().toLowerCase();
        if (tipo != 'financiado') continue;
        final nc = int.tryParse(p['numero_cuotas']?.toString() ?? '0') ?? 0;
        final mc = double.tryParse(p['monto_cuota']?.toString() ?? '0') ?? 0;
        if (nc > 0 || mc > 0) {
          nCuotasFactura = nc;
          cuotaFactura = mc;
          break;
        }
      }

      // ── Métodos de pago concatenados + separación Bs/USD + inicial ──
      // INICIAL PAGADA: TODOS los pagos en factura_pagos son inicial del
      // cliente (incluso si tipo=Financiado, porque el método es POS/Pago
      // Móvil, no es plata que la financiadora puso). Convertir Bs→USD
      // con la tasa histórica del pago si está guardada, si no la actual.
      final metodosSet = <String>{};
      double inicialPagada = 0;
      double pagadoEnBs = 0;     // suma de pagos en métodos Bs
      double pagadoEnUsd = 0;    // suma de pagos en métodos USD
      final tasaActual = ConfigSistema.tasaCambio;
      // Tasa que se mostrará en la columna "Tasa Bs/USD": preferimos la
      // histórica del primer pago en Bs (si existe), si no la actual.
      double tasaParaMostrar = tasaActual;
      bool tasaEncontrada = false;
      for (final p in pagos) {
        final met = (p['metodo'] ?? '').toString();
        if (met.isNotEmpty) metodosSet.add(met);
        final monto = double.tryParse(p['monto']?.toString() ?? '0') ?? 0;
        // Clasificar pago como Bs o USD según el método
        final metLow = met.toLowerCase();
        final esEnBs = metLow.contains('pago móvil') ||
            metLow.contains('pago movil') ||
            metLow.contains('punto') ||
            metLow.contains('efectivo bs') ||
            metLow.contains('transferencia');
        if (esEnBs) {
          pagadoEnBs += monto;
          // Tasa histórica del primer pago en Bs si está guardada
          if (!tasaEncontrada) {
            final tH = double.tryParse(p['tasa_cambio']?.toString() ?? '0') ?? 0;
            if (tH > 0) {
              tasaParaMostrar = tH;
              tasaEncontrada = true;
            }
          }
          // Inicial: convertir el monto Bs a USD usando la tasa histórica
          final tPago = double.tryParse(p['tasa_cambio']?.toString() ?? '0') ?? 0;
          final tConv = tPago > 0 ? tPago : tasaActual;
          if (tConv > 0) inicialPagada += monto / tConv;
        } else {
          pagadoEnUsd += monto;
          inicialPagada += monto;
        }
      }
      final metodos = metodosSet.join(', ');
      final equivalenteUsd = (pagadoEnBs > 0 && tasaParaMostrar > 0)
          ? redondearPrecio(pagadoEnBs / tasaParaMostrar)
          : 0.0;
      // Total cobrado en USD (Bs convertidos con la tasa de cada pago).
      // (Antes se exportaba la suma cruda de pagos, que mezclaba Bs con $.)
      final cobradoUsdFactura = redondearPrecio(inicialPagada);
      // Datos de auditoría de los pagos móviles de la factura.
      final datosPM = pagos
          .whereType<Map>()
          .map(datosPagoMovilTexto)
          .where((t) => t.isNotEmpty)
          .join(' | ');
      // Si la venta es Contado, no tiene sentido mostrar inicial pagada
      final inicialPagadaCelda = esFinanciada
          ? redondearPrecio(inicialPagada)
          : null;

      // Si no hay productos pero sí pagos, escribir una fila genérica
      if (productos.isEmpty) {
        s2.appendRow(_filaCeldas([
          (f['fecha'] ?? '').toString(),
          (f['nro_factura'] ?? '').toString(),
          (f['vendedor'] ?? '').toString(),
          (f['tienda'] ?? '').toString(),
          (f['cliente'] ?? '').toString(),
          (f['cedula'] ?? '').toString(),
          (f['telefono'] ?? '').toString(),
          '', '', '', '',
          tipoVenta,
          financiadora,
          nombreLista,
          '', '', '', '',
          inicialPagadaCelda ?? '',
          nCuotasFactura == 0 ? '' : nCuotasFactura,
          cuotaFactura == 0 ? '' : cuotaFactura,
          metodos,
          pagadoEnBs == 0 ? '' : pagadoEnBs,
          equivalenteUsd == 0 ? '' : equivalenteUsd,
          pagadoEnUsd == 0 ? '' : pagadoEnUsd,
          pagadoEnBs > 0 ? tasaParaMostrar : '',
          cobradoUsdFactura,
          datosPM,
        ]));
        continue;
      }

      // Monto de cada renglón. Los reportes nuevos ya lo traen calculado;
      // para los del historial viejo se calcula aquí con el mismo criterio.
      final prodsMap = productos
          .whereType<Map>()
          .map((m) => Map<String, dynamic>.from(m))
          .toList();
      if (prodsMap.any((m) => m['monto_renglon_usd'] == null)) {
        _asignarMontoRenglones(prodsMap, pagos, cobradoUsdFactura);
      }

      // Una fila por equipo
      var esPrimerRenglon = true;
      for (final p in prodsMap) {
        // Los campos pueden venir como String o num desde el backend.
        // double.tryParse(value.toString()) maneja ambos casos sin error.
        final precioVentaBase = double.tryParse(p['precio_venta']?.toString() ?? '0') ?? 0;
        final precioCosto = double.tryParse(p['precio_costo']?.toString() ?? '0') ?? 0;

        // ── Precio según lista de la financiadora ──
        // Si la venta es financiada, intentamos resolver el precio en
        // la lista de la financiadora con el nombre exacto guardado
        // en `nombreLista`. Si no se encuentra, fallback al precio base.
        double precioVenta = precioVentaBase;
        if (esFinanciada && financiadora.isNotEmpty) {
          final codigo = (p['codigo'] ?? '').toString();
          final normFin = financiadora.toLowerCase().trim();
          final normLista = nombreLista.toLowerCase().trim();
          double? precioListaEncontrado;
          // Primero buscar la lista EXACTA por nombre
          if (normLista.isNotEmpty) {
            for (final lp in listasPreciosGlobal) {
              if (lp.nombre.toLowerCase().trim() != normLista) continue;
              final item = lp.items.where((i) =>
                  i.producto.codigo.toLowerCase().trim() == codigo.toLowerCase().trim()
              ).firstOrNull;
              if (item != null && item.preciosPorColumna.isNotEmpty) {
                final entry = item.preciosPorColumna.entries
                    .where((e) => !e.key.startsWith('__'))
                    .firstOrNull;
                if (entry != null) {
                  precioListaEncontrado = entry.value;
                  break;
                }
              }
            }
          }
          // Fallback: primera lista que coincida en financiadora
          if (precioListaEncontrado == null) {
            for (final lp in listasPreciosGlobal) {
              final lpFin = (lp.financiadora ?? '').toLowerCase().trim();
              if (!lpFin.contains(normFin) && !normFin.contains(lpFin)) continue;
              final item = lp.items.where((i) =>
                  i.producto.codigo.toLowerCase().trim() == codigo.toLowerCase().trim()
              ).firstOrNull;
              if (item != null && item.preciosPorColumna.isNotEmpty) {
                final entry = item.preciosPorColumna.entries
                    .where((e) => !e.key.startsWith('__'))
                    .firstOrNull;
                if (entry != null) {
                  precioListaEncontrado = entry.value;
                  break;
                }
              }
            }
          }
          if (precioListaEncontrado != null) {
            precioVenta = precioListaEncontrado;
          }
        }
        final ganancia = precioVenta - precioCosto;

        // ── Inicial Lista USD: cuota × n° cuotas restada del precio
        // (es lo que la financiadora pide al cliente como inicial).
        // Si tenemos cuotas, lo calculamos como precio − (cuota × nCuotas).
        // Si no, queda en 0.
        double inicialLista = 0;
        if (cuotaFactura > 0 && nCuotasFactura > 0) {
          inicialLista = precioVenta - (cuotaFactura * nCuotasFactura);
          if (inicialLista < 0) inicialLista = 0;
        }

        // Vendedor del producto (si viene vacío, cae al vendedor de la
        // factura — campo `vendedor` de la cabecera).
        final vendedorProducto = (p['vendedor'] ?? '').toString().trim();
        final vendedorCelda = vendedorProducto.isNotEmpty
            ? vendedorProducto
            : (f['vendedor'] ?? '').toString();

        // Monto de ESTE renglón (no el total de la factura).
        final montoRenglon =
            double.tryParse(p['monto_renglon_usd']?.toString() ?? '') ?? 0.0;
        final renglonFinanciado = p['financiado'] == true;
        final primero = esPrimerRenglon;
        esPrimerRenglon = false;

        s2.appendRow(_filaCeldas([
          (f['fecha'] ?? '').toString(),
          (f['nro_factura'] ?? '').toString(),
          vendedorCelda,
          (f['tienda'] ?? '').toString(),
          (f['cliente'] ?? '').toString(),
          (f['cedula'] ?? '').toString(),
          (f['telefono'] ?? '').toString(),
          (p['marca'] ?? '').toString(),
          (p['modelo'] ?? '').toString(),
          (p['imei'] ?? '').toString(),
          (p['codigo'] ?? '').toString(),
          tipoVenta,
          financiadora,
          nombreLista,
          precioVenta,
          precioCosto,
          ganancia,
          inicialLista == 0 ? '' : inicialLista,
          // Inicial pagada: sólo en el renglón financiado y sólo la
          // parte que le corresponde (sin el precio de los accesorios).
          (esFinanciada && renglonFinanciado) ? montoRenglon : '',
          nCuotasFactura == 0 ? '' : nCuotasFactura,
          cuotaFactura == 0 ? '' : cuotaFactura,
          primero ? metodos : '',
          (primero && pagadoEnBs != 0) ? pagadoEnBs : '',
          (primero && equivalenteUsd != 0) ? equivalenteUsd : '',
          (primero && pagadoEnUsd != 0) ? pagadoEnUsd : '',
          (primero && pagadoEnBs > 0) ? tasaParaMostrar : '',
          montoRenglon,
          primero ? datosPM : '',
        ]));
      }
    }

    // Codificar y devolver
    final bytes = excel.encode();
    return Uint8List.fromList(bytes ?? <int>[]);
  }

  // ─────────────────────────────────────────────────────────────
  //  REPORTES NORMALES (no-ventas): hoja única con tabla plana
  //  Mantengo el comportamiento original para los demás tipos
  //  (inventario, cuentas por cobrar, etc.) que no han pedido
  //  cambiar.
  // ─────────────────────────────────────────────────────────────
  final nombreHoja = _nombreHojaSeguro(e.categoria);
  final s = excel[nombreHoja];

  // Encabezado del reporte (metadatos)
  s.appendRow(_filaCeldas(['REPORTE: ${e.nombreArchivo}']));
  s.appendRow(_filaCeldas(['Generado por: ${e.generadoPor}']));
  s.appendRow(_filaCeldas(['Fecha de generación: ${_formatoFechaCompleta(e.fecha)}']));
  s.appendRow(_filaCeldas(['Rango: ${_etiquetaRango(
    e.desdeIso != null ? DateTime.tryParse(e.desdeIso!) : null,
    e.hastaIso != null ? DateTime.tryParse(e.hastaIso!) : null)}']));
  s.appendRow(_filaCeldas(['Total de registros: ${e.totalRegistros}']));
  s.appendRow(<CellValue?>[]);

  // Encabezados de columnas
  s.appendRow(_filaCeldas(e.encabezados.cast<dynamic>().toList()));
  // Filas
  for (final fila in e.filas) {
    s.appendRow(_filaCeldas(fila));
  }

  // Resumen al final
  if (e.resumen.isNotEmpty) {
    s.appendRow(<CellValue?>[]);
    s.appendRow(_filaCeldas(['RESUMEN']));
    e.resumen.forEach((k, v) {
      if (v is Map) {
        s.appendRow(_filaCeldas([k]));
        v.forEach((kk, vv) {
          s.appendRow(_filaCeldas(['  $kk', vv]));
        });
      } else {
        s.appendRow(_filaCeldas([k, v]));
      }
    });
  }

  // ── (eliminado el bloque viejo de tipoReporte == 'ventas') ──

  if (e.tipoReporte == 'cuentas_cobrar' || e.tipoReporte == 'cuentas_pagar') {
    // Hoja de pagos efectuados a cada cuenta
    final sPg = excel['Pagos'];
    sPg.appendRow(_filaCeldas([
      e.tipoReporte == 'cuentas_cobrar' ? 'Cliente' : 'Proveedor',
      'Identificación', 'Método', 'Monto', 'Fecha',
    ]));
    for (final c in e.detalles) {
      final id = (c['cedula'] ?? c['identificacion'] ?? '').toString();
      final pagos = (c['pagos'] as List?) ?? [];
      for (final p in pagos) {
        sPg.appendRow(_filaCeldas([
          (c['nombre'] ?? '').toString(),
          id,
          (p['metodo'] ?? '').toString(),
          p['monto'],
          (p['fecha'] ?? '').toString(),
        ]));
      }
    }
  }

  if (e.tipoReporte == 'cierres') {
    // Hoja con desglose de métodos por cierre
    final sM = excel['Métodos por cierre'];
    sM.appendRow(_filaCeldas(['UID', 'Tienda', 'Fecha', 'Método', 'Monto']));
    for (final c in e.detalles) {
      final metodos = (c['metodos'] as List?) ?? [];
      for (final m in metodos) {
        sM.appendRow(_filaCeldas([
          (c['uid'] ?? '').toString(),
          (c['tienda'] ?? '').toString(),
          (c['fecha_cierre'] ?? '').toString(),
          (m['metodo'] ?? '').toString(),
          m['monto'],
        ]));
      }
    }
  }

  final bytes = excel.encode()!;
  return Uint8List.fromList(bytes);
}

// Helpers para construir Excel ────────────────────────────────
String _nombreHojaSeguro(String s) {
  // Excel limita los nombres de hoja a 31 chars, sin / \ ? * [ ]
  var n = s.replaceAll(RegExp(r'[\/\\\?\*\[\]]'), '_');
  if (n.length > 31) n = n.substring(0, 31);
  if (n.isEmpty) n = 'Reporte';
  return n;
}

String _slug(String s) {
  var n = s.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), '_');
  n = n.replaceAll(RegExp(r'_+'), '_').replaceAll(RegExp(r'^_|_$'), '');
  if (n.isEmpty) n = 'reporte';
  if (n.length > 60) n = n.substring(0, 60);
  return n;
}

/// Normaliza un valor a un tipo primitivo apto para `appendRow` del paquete
/// `excel` (versiones antiguas: aceptan `String`, `int`, `double`, `bool` o
/// `null` directamente, no envoltorios `CellValue`).
/// Normaliza un valor cualquiera a un `CellValue?` que el paquete `excel`
/// (versiones 4.0+) acepta en `appendRow`. En versiones anteriores
/// `appendRow` aceptaba `List<dynamic>` directamente; ahora exige
/// `List<CellValue?>`. Esta función centraliza la conversión.
CellValue? _normalizarCelda(dynamic v) {
  if (v == null) return null;
  if (v is CellValue) return v;
  if (v is bool) return BoolCellValue(v);
  if (v is int) return IntCellValue(v);
  if (v is double) return DoubleCellValue(v);
  if (v is num) return DoubleCellValue(v.toDouble());
  if (v is DateTime) {
    return DateTimeCellValue(
      year: v.year, month: v.month, day: v.day,
      hour: v.hour, minute: v.minute, second: v.second);
  }
  return TextCellValue(v.toString());
}

/// Atajo para convertir una lista de cualquier cosa a `List<CellValue?>`
/// (formato que requiere `appendRow` en excel 4.0+).
List<CellValue?> _filaCeldas(List<dynamic> valores) =>
    valores.map(_normalizarCelda).toList();

String _formatoFechaCompleta(DateTime d) =>
    '${d.day.toString().padLeft(2,'0')}/'
    '${d.month.toString().padLeft(2,'0')}/'
    '${d.year} '
    '${d.hour.toString().padLeft(2,'0')}:'
    '${d.minute.toString().padLeft(2,'0')}';

// ── Helpers de fecha ──────────────────────────────────────────
bool _enRango(dynamic fechaRaw, DateTime? desde, DateTime? hasta) {
  if (desde == null && hasta == null) return true;
  try {
    final s = fechaRaw?.toString() ?? '';
    if (s.isEmpty) return false; // sin fecha → rechazar
    final f = parseFecha(s);
    // Si parseFecha devolvió la fecha sentinela (1900), es inválida
    if (f.year < 1950) return false;
    // Comparar solo la parte de fecha (sin horas) para evitar problemas
    // cuando el backend trae fechas con hora (ej: "2026-06-12 14:30")
    // y el filtro tiene hora 00:00.
    final fSolo = DateTime(f.year, f.month, f.day);
    if (desde != null) {
      final desdeSolo = DateTime(desde.year, desde.month, desde.day);
      if (fSolo.isBefore(desdeSolo)) return false;
    }
    if (hasta != null) {
      final hastaSolo = DateTime(hasta.year, hasta.month, hasta.day);
      if (fSolo.isAfter(hastaSolo)) return false;
    }
    return true;
  } catch (e) {
    debugPrint('_enRango error: $e (fecha="$fechaRaw")');
    // En caso de error de parseo, RECHAZAR (false). Antes devolvía
    // true, lo que causaba que facturas con fechas mal formateadas
    // aparecieran en cualquier rango.
    return false;
  }
}

String _sufFecha(DateTime? desde, DateTime? hasta) {
  if (desde == null && hasta == null) return 'todo';
  final d = desde != null ? '${desde.day}-${desde.month}-${desde.year}' : 'inicio';
  final h = hasta != null ? '${hasta.day}-${hasta.month}-${hasta.year}' : 'hoy';
  return '${d}_al_$h';
}

String _rangoStr(DateTime? desde, DateTime? hasta) {
  if (desde == null && hasta == null) return '';
  return ' (${desde != null ? "${desde.day}/${desde.month}/${desde.year}" : "inicio"}'
      ' — ${hasta != null ? "${hasta.day}/${hasta.month}/${hasta.year}" : "hoy"})';
}

// ============================================================
//  VENTANA REPORTES — con rango de fechas por módulo
// ============================================================
class VentanaReportes extends StatefulWidget {
  const VentanaReportes({super.key});
  @override State<VentanaReportes> createState() => _VentanaReportesState();
}

class _VentanaReportesState extends State<VentanaReportes>
    with SingleTickerProviderStateMixin {
  late final TabController _tabController;
  final Set<String> _descargando = {};
  // Fechas por id de reporte
  final Map<String, DateTime?> _desde = {};
  final Map<String, DateTime?> _hasta = {};

  // Búsqueda en historial
  final TextEditingController _busquedaHistorial = TextEditingController();
  String _filtroCategoria = 'Todas';
  bool _cargandoHistorial = true;

  /// Tienda del reporte de ventas. Dueño/Admin/Gerente eligen ('Todas'
  /// o una tienda); el resto queda fijo en su tienda (igual que el
  /// cierre de caja).
  String _tiendaVentas = 'Todas';

  @override
  void initState() {
    super.initState();
    _tabController = TabController(length: 2, vsync: this);
    if (!puedeVerTodasLasTiendas() && tiendaUsuarioActual().isNotEmpty) {
      _tiendaVentas = tiendaUsuarioActual();
    }
    _cargarHistorial();
  }

  @override
  void dispose() {
    _tabController.dispose();
    _busquedaHistorial.dispose();
    super.dispose();
  }

  Future<void> _cargarHistorial() async {
    setState(() => _cargandoHistorial = true);
    await HistorialReportes.cargar();
    if (mounted) setState(() => _cargandoHistorial = false);
  }

  Future<void> _ejecutar(String id, Future<void> Function(DateTime? d, DateTime? h) fn) async {
    setState(() => _descargando.add(id));
    try {
      await fn(_desde[id], _hasta[id]);
      if (mounted) {
        // Refrescar el historial para que la nueva entrada aparezca
        // inmediatamente al cambiar de tab.
        setState(() {});
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: const Text("✅ Reporte generado y agregado al historial"),
            backgroundColor: AppColors.statusGreen,
            action: SnackBarAction(
              label: 'Ver historial',
              textColor: Colors.white,
              onPressed: () => _tabController.animateTo(1),
            ),
          ));
      }
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text("Error: $e"), backgroundColor: AppColors.statusRed));
    } finally {
      if (mounted) setState(() => _descargando.remove(id));
    }
  }

  Future<void> _seleccionarFecha(String id, bool esDe) async {
    final inicial = esDe ? (_desde[id] ?? DateTime.now().subtract(const Duration(days: 30)))
                         : (_hasta[id] ?? DateTime.now());
    final picked = await showDatePicker(
      context: context,
      initialDate: inicial,
      firstDate: DateTime(2020),
      lastDate: DateTime(2030));
    if (picked != null && mounted) {
      setState(() {
        if (esDe) _desde[id] = picked;
        else _hasta[id] = picked;
      });
    }
  }

  String _labelFecha(String id) {
    final d = _desde[id];
    final h = _hasta[id];
    if (d == null && h == null) return "Todo el historial";
    final ds = d != null ? "${d.day}/${d.month}/${d.year}" : "inicio";
    final hs = h != null ? "${h.day}/${h.month}/${h.year}" : "hoy";
    return "$ds — $hs";
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text("Reportes"),
        bottom: TabBar(
          controller: _tabController,
          indicatorColor: Colors.white,
          tabs: const [
            Tab(icon: Icon(Icons.add_chart), text: "GENERAR"),
            Tab(icon: Icon(Icons.history), text: "HISTORIAL"),
          ],
        ),
      ),
      body: TabBarView(
        controller: _tabController,
        children: [
          _tabGenerar(),
          _tabHistorial(),
        ],
      ),
    );
  }

  // ════════════════════════════════════════════════════════════
  //  TAB 1 — Generar reportes (lista de cards profesionales)
  // ════════════════════════════════════════════════════════════
  Widget _tabGenerar() {
    return ListView(
      padding: const EdgeInsets.all(16),
      children: [
        // ── Banner informativo profesional ──
        Container(
          padding: const EdgeInsets.all(14),
          margin: const EdgeInsets.only(bottom: 18),
          decoration: BoxDecoration(
            gradient: LinearGradient(colors: [
              AppColors.primaryBlue.withValues(alpha: 0.10),
              AppColors.royalBlue.withValues(alpha: 0.06),
            ]),
