  // ---------- Vista para ventas (con detalle expandible por factura) -----
  Widget _buildVistaVentas() {
    var detalles = e.detalles;
    if (_filtro.trim().isNotEmpty) {
      final f = _filtro.toLowerCase();
      detalles = detalles.where((d) {
        final cliente = (d['cliente'] ?? '').toString().toLowerCase();
        final cedula = (d['cedula'] ?? '').toString().toLowerCase();
        final nro = (d['nro_factura'] ?? '').toString().toLowerCase();
        final vend = (d['vendedor'] ?? '').toString().toLowerCase();
        // También por datos del pago móvil (referencia, cédula o
        // teléfono del pagador) para auditoría.
        final pm = ((d['pagos'] as List?) ?? [])
            .whereType<Map>()
            .map(datosPagoMovilTexto)
            .join(' ')
            .toLowerCase();
        return cliente.contains(f) ||
            cedula.contains(f) ||
            nro.contains(f) ||
            vend.contains(f) ||
            pm.contains(f);
      }).toList();
    }
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.all(10),
          child: TextField(
            decoration: InputDecoration(
              hintText: 'Buscar por cliente, cédula, factura, vendedor o referencia',
              prefixIcon: const Icon(Icons.search, size: 18),
              isDense: true,
              filled: true,
              fillColor: Colors.white,
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(8),
                borderSide: const BorderSide(color: AppColors.cardBorder)),
              enabledBorder: OutlineInputBorder(
                borderRadius: BorderRadius.circular(8),
                borderSide: const BorderSide(color: AppColors.cardBorder)),
            ),
            onChanged: (v) => setState(() => _filtro = v),
          ),
        ),
        Expanded(
          child: ListView.builder(
            padding: const EdgeInsets.symmetric(horizontal: 10),
            itemCount: detalles.length,
            itemBuilder: (_, i) => _cardFactura(detalles[i]),
          ),
        ),
      ],
    );
