  Widget _cardFactura(Map<String, dynamic> f) {
    final productos =
        (f['productos'] as List?)?.cast<Map<String, dynamic>>() ?? [];
    final pagos =
        (f['pagos'] as List?)?.cast<Map<String, dynamic>>() ?? [];
    // Total con la moneda REAL de cada pago ("$50.00 + Bs 1.200,00").
    // Antes se ponía "$" al total crudo, que suma Bs con $.
    final totales = totalesPagosPorMoneda(pagos);
    final totalTexto = pagos.isEmpty
        ? _fmtMoneda(_aDouble(f['total']) ?? 0.0)
        : formatTotalesPorMoneda(totales.usd, totales.bs);
    return Card(
      margin: const EdgeInsets.only(bottom: 8),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(10),
        side: const BorderSide(color: AppColors.cardBorder)),
      elevation: 0,
      child: ExpansionTile(
        tilePadding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
        childrenPadding:
            const EdgeInsets.fromLTRB(12, 0, 12, 12),
        leading: Container(
          width: 40, height: 40,
          decoration: BoxDecoration(
            color: AppColors.primaryBlue.withValues(alpha: 0.1),
            borderRadius: BorderRadius.circular(8),
          ),
          alignment: Alignment.center,
          child: const Icon(Icons.receipt,
              color: AppColors.primaryBlue, size: 20),
        ),
        title: Row(
          children: [
            Expanded(
              child: Text('Fact. ${f['nro_factura'] ?? '—'}',
                style: const TextStyle(
                  fontSize: 13.5, fontWeight: FontWeight.bold,
                  color: AppColors.textPrimary)),
            ),
            Flexible(child: Text(totalTexto,
              textAlign: TextAlign.right,
              style: const TextStyle(
                fontSize: 14, fontWeight: FontWeight.bold,
                color: AppColors.statusGreen))),
          ],
        ),
        subtitle: Padding(
          padding: const EdgeInsets.only(top: 4),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                  '${f['cliente'] ?? '—'}'
                  '${(f['cedula']?.toString().isNotEmpty ?? false) ? ' · ${f['cedula']}' : ''}',
                style: const TextStyle(
                    fontSize: 12, color: AppColors.textPrimary)),
              const SizedBox(height: 2),
              Wrap(
                spacing: 8, runSpacing: 2,
                children: [
                  if ((f['telefono']?.toString().isNotEmpty ?? false))
                    _miniInfo(Icons.phone, f['telefono'].toString()),
