  Widget _filaProducto(Map<String, dynamic> p) {
    final tipo = p['tipo']?.toString() ?? '';
    // El tipo se guarda como "Equipo (IMEI)"; antes se comparaba exacto
    // con "equipo" y nunca coincidía.
    final esEquipo = tipo.toLowerCase().startsWith('equipo') ||
        (p['imei']?.toString().isNotEmpty ?? false);
    // Monto cobrado por ESTE renglón (reportes nuevos). Si no existe
    // (reporte viejo), se muestra el precio de lista del producto.
    final montoRenglon = _aDouble(p['monto_renglon_usd']);
    final precio = montoRenglon ?? _aDouble(p['precio_venta']);
    return Container(
      margin: const EdgeInsets.only(bottom: 6),
      padding: const EdgeInsets.all(8),
      decoration: BoxDecoration(
        color: AppColors.surfaceGrey,
        borderRadius: BorderRadius.circular(6),
        border: Border.all(color: AppColors.cardBorder),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Icon(
            esEquipo ? Icons.smartphone : Icons.shopping_bag,
            size: 16,
            color: esEquipo
                ? AppColors.primaryBlue
                : AppColors.statusGreen,
          ),
          const SizedBox(width: 8),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  (p['nombre']?.toString().isNotEmpty ?? false)
                      ? p['nombre'].toString()
                      : (p['codigo']?.toString() ?? '—'),
                  style: const TextStyle(
                    fontSize: 12.5, fontWeight: FontWeight.w600,
                    color: AppColors.textPrimary)),
                const SizedBox(height: 2),
                Wrap(
                  spacing: 8, runSpacing: 2,
                  children: [
                    if (esEquipo &&
                        (p['imei']?.toString().isNotEmpty ?? false))
                      _miniInfo(Icons.qr_code, p['imei'].toString()),
                    if ((p['marca']?.toString().isNotEmpty ?? false))
                      _miniInfo(Icons.business, p['marca'].toString()),
                    if ((p['modelo']?.toString().isNotEmpty ?? false))
                      _miniInfo(Icons.devices, p['modelo'].toString()),
                    if (!esEquipo &&
                        (p['codigo']?.toString().isNotEmpty ?? false))
                      _miniInfo(Icons.tag, p['codigo'].toString()),
                  ],
                ),
              ],
            ),
          ),
          if (precio != null)
            Column(
              crossAxisAlignment: CrossAxisAlignment.end,
              children: [
                Text(_fmtMoneda(precio),
                  style: const TextStyle(
                    fontSize: 12.5, fontWeight: FontWeight.bold,
                    color: AppColors.statusGreen)),
                if (montoRenglon != null && p['financiado'] == true)
                  const Text('Inicial',
                    style: TextStyle(
                      fontSize: 10, color: AppColors.textSecondary)),
              ]),
        ],
      ),
    );
  }

  Widget _filaPago(Map<String, dynamic> p) {
    final monto = _aDouble(p['monto']) ?? 0.0;
    final metodo = p['metodo']?.toString() ?? '—';
    final tipo = p['tipo']?.toString() ?? '';
    final fin = p['financiador']?.toString() ?? '';
    // Referencia / cédula / teléfono del pagador (pago móvil).
    final datosPM = datosPagoMovilTexto(p);
    return Container(
      margin: const EdgeInsets.only(bottom: 6),
      padding: const EdgeInsets.all(8),
      decoration: BoxDecoration(
        color: AppColors.statusGreen.withValues(alpha: 0.05),
        borderRadius: BorderRadius.circular(6),
        border: Border.all(
            color: AppColors.statusGreen.withValues(alpha: 0.2)),
      ),
      child: Row(
        children: [
          const Icon(Icons.payments_outlined,
              size: 16, color: AppColors.statusGreen),
          const SizedBox(width: 8),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(metodo,
                  style: const TextStyle(
                    fontSize: 12.5, fontWeight: FontWeight.w600,
                    color: AppColors.textPrimary)),
                if (tipo.isNotEmpty || fin.isNotEmpty)
                  Padding(
                    padding: const EdgeInsets.only(top: 2),
                    child: Text(
                      [tipo, fin].where((s) => s.isNotEmpty).join(' · '),
                      style: const TextStyle(
                        fontSize: 11, color: AppColors.textSecondary)),
                  ),
                if (datosPM.isNotEmpty)
                  Padding(
                    padding: const EdgeInsets.only(top: 2),
                    child: SelectableText(datosPM,
                      style: const TextStyle(
                        fontSize: 11, color: AppColors.textPrimary)),
