// ── Pantalla de notificaciones ────────────────────────────────
class VentanaNotificaciones extends StatefulWidget {
  const VentanaNotificaciones({super.key});
  @override State<VentanaNotificaciones> createState() => _VentanaNotificacionesState();
}

class _VentanaNotificacionesState extends State<VentanaNotificaciones> {
  bool _cargando = false;

  @override
  void initState() {
    super.initState();
    NotificacionesService.addListener(_onCambio);
  }
  @override
  void dispose() {
    NotificacionesService.removeListener(_onCambio);
    super.dispose();
  }
  void _onCambio() { if (mounted) setState(() {}); }

  Future<void> _refresh() async {
    setState(() => _cargando = true);
    try {
      final raw = await _Api.get('notificaciones',
        {'usuario': usuarioSesion?.correo ?? ''});
      notificacionesGlobal = ((raw as List?) ?? [])
          .map((m) => NotificacionSistema.fromMap(m))
          // Defensa: descartar notificaciones vacías heredadas que
          // pudieran haber quedado en la BD antes del fix.
          .where((n) =>
              n.titulo.trim().isNotEmpty || n.mensaje.trim().isNotEmpty)
          .toList();
      NotificacionesService.notificarCambio();
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Error: $e'),
          backgroundColor: AppColors.statusRed));
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    // Filtro UI: aunque la BD tenga vacías, la pantalla sólo muestra
    // las que tienen al menos título O mensaje con contenido.
    final notifs = notificacionesGlobal.where((n) =>
        n.titulo.trim().isNotEmpty || n.mensaje.trim().isNotEmpty).toList();
    final noLeidas = notifs.where((n) => !n.leida).length;
    return Scaffold(
      appBar: AppBar(
        title: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          const Text("Notificaciones"),
          if (noLeidas > 0)
            Text("$noLeidas sin leer",
              style: const TextStyle(fontSize: 12, color: Colors.white70)),
        ]),
        actions: [
          if (noLeidas > 0)
            TextButton.icon(
              icon: const Icon(Icons.done_all, color: Colors.white, size: 18),
              label: const Text("Leer todas",
                style: TextStyle(color: Colors.white, fontSize: 12)),
              onPressed: () async {
                await NotificacionesService.marcarTodasLeidas();
                if (mounted) setState(() {});
              },
            ),
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: "Actualizar",
            onPressed: _refresh,
          ),
        ],
      ),
      body: _cargando
        ? const Center(child: CircularProgressIndicator())
        : notifs.isEmpty
          ? Center(child: Column(mainAxisSize: MainAxisSize.min, children: [
              Icon(Icons.notifications_off_outlined, size: 72, color: Colors.grey[300]),
              const SizedBox(height: 12),
              Text("No hay notificaciones",
                style: TextStyle(color: Colors.grey[500], fontSize: 16)),
              const SizedBox(height: 8),
              TextButton.icon(
                icon: const Icon(Icons.refresh),
                label: const Text("Actualizar"),
                onPressed: _refresh),
            ]))
          : RefreshIndicator(
              onRefresh: _refresh,
              child: ListView.separated(
                padding: const EdgeInsets.symmetric(vertical: 8),
                itemCount: notifs.length,
                separatorBuilder: (_, __) =>
                  const Divider(height: 1, indent: 72),
                itemBuilder: (context, i) {
                  final n = notifs[i];
                  final esLeida = n.leida;
                  return Dismissible(
                    key: Key('notif_${n.id ?? i}'),
                    direction: DismissDirection.endToStart,
                    background: Container(
                      alignment: Alignment.centerRight,
                      padding: const EdgeInsets.only(right: 20),
                      color: AppColors.statusRed,
                      child: const Icon(Icons.delete_outline,
                        color: Colors.white, size: 28)),
                    confirmDismiss: (_) async {
                      return await showDialog<bool>(
                        context: context,
                        builder: (ctx) => AlertDialog(
                          title: const Text("Eliminar notificación"),
                          content: const Text(
                            "¿Eliminar esta notificación permanentemente?"),
                          actions: [
                            TextButton(
                              onPressed: () => Navigator.pop(ctx, false),
                              child: const Text("Cancelar")),
                            ElevatedButton(
                              style: ElevatedButton.styleFrom(
                                backgroundColor: AppColors.statusRed),
                              onPressed: () => Navigator.pop(ctx, true),
                              child: const Text("Eliminar",
                                style: TextStyle(color: Colors.white))),
                          ],
                        ),
                      ) ?? false;
                    },
                    onDismissed: (_) async {
                      if (n.id != null) {
                        await NotificacionesService.eliminar(n.id!);
                      } else {
                        notificacionesGlobal.remove(n);
                        NotificacionesService.notificarCambio();
                      }
                    },
                    child: InkWell(
                      onTap: () async {
                        if (!esLeida && n.id != null) {
                          await NotificacionesService.marcarLeida(n.id!);
                        }
                        if (!mounted) return;
                        showDialog(
                          context: context,
                          builder: (ctx) => AlertDialog(
                            title: Row(children: [
                              Icon(_iconoPorTitulo(n.titulo),
                                color: AppColors.royalBlue, size: 22),
                              const SizedBox(width: 8),
                              Expanded(child: Text(n.titulo,
                                style: const TextStyle(fontSize: 16))),
                            ]),
                            content: Column(
                              mainAxisSize: MainAxisSize.min,
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(n.mensaje),
                                const SizedBox(height: 12),
                                Row(children: [
                                  const Icon(Icons.access_time, size: 14,
                                    color: AppColors.textSecondary),
                                  const SizedBox(width: 4),
                                  Text(n.fecha, style: const TextStyle(
                                    fontSize: 12, color: AppColors.textSecondary)),
                                ]),
                              ],
                            ),
                            actions: [
                              TextButton(
                                onPressed: () => Navigator.pop(ctx),
                                child: const Text("Cerrar")),
                            ],
                          ),
                        );
                      },
                      child: Container(
                        color: esLeida ? null
                          : AppColors.primaryBlue.withValues(alpha: 0.04),
                        padding: const EdgeInsets.symmetric(
                          horizontal: 16, vertical: 12),
                        child: Row(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                          Container(
                            width: 44, height: 44,
                            decoration: BoxDecoration(
                              color: (esLeida
                                ? AppColors.textSecondary
                                : AppColors.primaryBlue)
                                  .withValues(alpha: 0.1),
                              borderRadius: BorderRadius.circular(12)),
                            child: Icon(_iconoPorTitulo(n.titulo), size: 22,
                              color: esLeida
                                ? AppColors.textSecondary
                                : AppColors.primaryBlue),
                          ),
                          const SizedBox(width: 12),
                          Expanded(child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Row(children: [
                                Expanded(child: Text(n.titulo,
                                  style: TextStyle(
                                    fontWeight: esLeida
                                      ? FontWeight.w500 : FontWeight.bold,
                                    color: esLeida
                                      ? AppColors.textSecondary
                                      : AppColors.textPrimary,
                                    fontSize: 14))),
                                if (!esLeida)
                                  Container(width: 8, height: 8,
                                    decoration: const BoxDecoration(
                                      color: AppColors.primaryBlue,
                                      shape: BoxShape.circle)),
                              ]),
                              const SizedBox(height: 3),
                              Text(n.mensaje,
                                maxLines: 2,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(fontSize: 13,
                                  color: AppColors.textSecondary)),
                              const SizedBox(height: 4),
                              Text(n.fecha, style: const TextStyle(
                                fontSize: 11, color: AppColors.textSecondary)),
                            ],
                          )),
                        ]),
                      ),
                    ),
                  );
                },
              ),
            ),
    );
  }

  IconData _iconoPorTitulo(String titulo) {
    final t = titulo.toLowerCase();
    // Mensajes internos
    if (t.contains('mensaje') || t.contains('💬'))
      return Icons.chat_bubble_outline;
    // Código solicitado / recibido
    if (t.contains('código') || t.contains('codigo') || t.contains('🔑') || t.contains('⚠️'))
      return Icons.key_outlined;
    // Nueva línea registrada
    if (t.contains('nueva línea') || t.contains('nueva linea') || t.contains('📱'))
      return Icons.sim_card_outlined;
    // Línea activada
    if (t.contains('activada') || t.contains('✅'))
      return Icons.check_circle_outline;
    // Ventas / facturas
    if (t.contains('venta') || t.contains('factura'))
      return Icons.receipt_long_outlined;
    // Inventario / stock
    if (t.contains('stock') || t.contains('inventario'))
      return Icons.inventory_2_outlined;
    // Pagos / cuentas
    if (t.contains('pago') || t.contains('cobr') || t.contains('pagar'))
      return Icons.payments_outlined;
    // Líneas / activaciones genérico
    if (t.contains('línea') || t.contains('linea') || t.contains('activ'))
      return Icons.sim_card_outlined;
    if (t.contains('usuario')) return Icons.person_outline;
    if (t.contains('error') || t.contains('alerta'))
      return Icons.warning_amber_outlined;
    return Icons.notifications_outlined;
  }

  Color _colorPorTitulo(String titulo) {
    final t = titulo.toLowerCase();
    if (t.contains('mensaje') || t.contains('💬'))    return AppColors.primaryBlue;
    if (t.contains('código') || t.contains('codigo') || t.contains('🔑')) return AppColors.statusOrange;
    if (t.contains('⚠️'))                              return AppColors.statusOrange;
    if (t.contains('nueva línea') || t.contains('nueva linea') || t.contains('📱')) return AppColors.royalBlue;
    if (t.contains('activada') || t.contains('✅'))   return AppColors.statusGreen;
    if (t.contains('error') || t.contains('alerta'))  return AppColors.statusRed;
    return AppColors.primaryBlue;
  }
}

// ============================================================
//  MODELO CONFIGURACIÓN GLOBAL DEL SISTEMA
// ============================================================
// ============================================================
//  ENCABEZADO DE SEDE — datos que aparecen en la factura PDF
// ============================================================
class EncabezadoSede {
  String nombreSede;      // nombre del punto de venta (ej. "Tecno Líder Principal")
  String rif;             // RIF de la empresa (ej. "J-12345678-9")
  String direccion;       // dirección física de la sede
  String telefono;        // teléfono de contacto
  String correo;          // correo de la sede (opcional)
  Uint8List? logoBytes;   // bytes de la imagen del logo (PNG/JPG)

  EncabezadoSede({
    required this.nombreSede,
    this.rif = '',
    this.direccion = '',
    this.telefono = '',
    this.correo = '',
    this.logoBytes,
  });

  /// Copia con valores actualizados
  /// Usa [clearLogo] = true para quitar el logo explícitamente.
  EncabezadoSede copyWith({
    String? nombreSede,
    String? rif,
    String? direccion,
    String? telefono,
    String? correo,
    Uint8List? logoBytes,
    bool clearLogo = false,
  }) => EncabezadoSede(
    nombreSede: nombreSede ?? this.nombreSede,
    rif: rif ?? this.rif,
    direccion: direccion ?? this.direccion,
    telefono: telefono ?? this.telefono,
    correo: correo ?? this.correo,
    logoBytes: clearLogo ? null : (logoBytes ?? this.logoBytes),
  );

  bool get tieneInformacion =>
      rif.isNotEmpty || direccion.isNotEmpty || telefono.isNotEmpty;
}

class ConfigSistema {
  // Vacío por defecto: si el usuario no configura un nombre de empresa,
  // las impresiones NO mostrarán "Tecno Líder App". Los layouts PDF detectan
  // cadena vacía y omiten la línea completamente.
  static String nombreEmpresa = "";
  static String moneda = "\$";
  static double tasaCambio = 100.0;
  /// Tasa Binance del día — usada para convertir montos en Bs a divisas
  /// en los reportes (vendedor, ganancia, etc.). El dueño la actualiza
  /// manualmente desde Configuración. Si está en 0, se usa tasaCambio.
  static double tasaBinance = 0.0;
  static bool permitirVentaSinStock = false;
  static bool requiereAprobacionDescuento = true;
  static double maxDescuentoPorcentaje = 10.0;
  static bool mostrarCostoEnFactura = false;
  static List<String> tiendas = ["Tecno Líder Principal", "Tecno Líder Sucursal"];
  /// Mapa nombre_tienda → id_backend. Se llena al sincronizar con el
  /// endpoint `tiendas` y se usa para poder ELIMINAR una tienda del
  /// servidor (que requiere el id, no el nombre).
  static Map<String, int> tiendasIds = {};
  static List<String> metodossPago = ["Punto de venta","Zelle","Divisas","Pago Móvil","Efectivo Bs","Efectivo \$","Transferencia","Cashea"];
  // ── Ubicaciones de almacén / tiendas ──
  // Lista vacía por defecto. Se llena dinámicamente desde la tabla
  // `tiendas` del servidor al cargar el sistema o al abrir cualquier
  // ventana que use ubicaciones (Buscador IMEI, Inventario, Traslados).
  // No usamos defaults como "Almacen", "Tienda 1" porque generaban
  // ubicaciones fantasma que no existían en la BD del cliente.
  static List<String> ubicacionesAlmacen = [];
  // ── Listas visibles en la Consulta Rápida de Precios ─────
  // Qué listas de precios se le pueden cantar a un cliente lo decide
  // el DUEÑO, no el código: antes las cuatro listas comerciales
  // estaban fijas en el programa y cambiarlas exigía recompilar.
  //
  // Se guardan los nombres NORMALIZADOS (ver [normalizarNombreLista])
  // para que un cambio de mayúsculas o de acentos en el nombre de la
  // lista no rompa la selección. Viaja al backend con el resto de la
  // configuración general, así que el dueño lo configura una vez y
  // vale para todos los equipos.
  //
  // Lista vacía = todavía no se configuró nada: se usan las cuatro de
  // siempre, así que el comportamiento no cambia hasta que el dueño
  // entre a elegir.
  static List<String> listasConsultaRapida = [];

  /// Las cuatro listas comerciales que se usaban antes de que esto
  /// fuera configurable. Sirven de valor por defecto.
  static const List<String> listasConsultaRapidaPorDefecto = [
    'divisas', 'decontado', 'krece', 'cashea',
  ];

  /// Deja el nombre de una lista en una forma comparable: sin
  /// mayúsculas, sin acentos y sin espacios ni signos.
  /// "De Contado", "de contado" y "DECONTADO" dan todas "decontado".
  static String normalizarNombreLista(String nombre) {
    var n = nombre.toLowerCase().trim();
    const acentos = {
      'á': 'a', 'é': 'e', 'í': 'i', 'ó': 'o', 'ú': 'u', 'ü': 'u', 'ñ': 'n',
    };
    acentos.forEach((k, v) => n = n.replaceAll(k, v));
    return n.replaceAll(RegExp(r'[^a-z0-9]'), '');
  }

  /// Claves que efectivamente se muestran.
  static List<String> get listasConsultaRapidaEfectivas =>
      listasConsultaRapida.isEmpty
          ? listasConsultaRapidaPorDefecto
          : listasConsultaRapida;

  /// Prefijo de las entradas que apuntan a una lista por su id.
  static const String prefijoIdLista = 'id:';

  /// Con qué clave se guarda una lista en la selección del dueño.
  ///
  /// Es el ID, no el nombre. El nombre no sirve como clave porque
  /// [normalizarNombreLista] borra los signos: "KRECE" y "KRECE."
  /// daban las dos `krece`, y entonces destildar una no ocultaba
  /// nada — la otra seguía metiendo la misma clave en la selección.
  /// Con el id cada lista se prende y se apaga sola, aunque dos se
  /// llamen exactamente igual.
  ///
  /// Una lista sin id (recién creada, todavía sin guardar en el
  /// servidor) cae al nombre normalizado, que es lo único que hay.
  static String claveConsultaRapida(ListaPrecio l) =>
      l.id != null ? '$prefijoIdLista${l.id}' : normalizarNombreLista(l.nombre);

  /// true si los precios de esa lista salen en la Consulta Rápida.
  ///
  /// La selección guardada lleva las dos formas de clave a la vez
  /// (ver [guardarListasConsultaRapida]). Acá el id MANDA: si hay
  /// aunque sea una clave por id, se decide sólo por id y los
  /// nombres se ignoran. Si no se hiciera así, una lista llamada
  /// igual que otra elegida se colaría por nombre y volveríamos al
  /// problema de no poder ocultarla.
  ///
  /// Una lista sin id todavía (recién creada, sin guardar) no tiene
  /// con qué compararse, así que cae al nombre.
  static bool listaVisibleEnConsultaRapida(ListaPrecio l) {
    final efectivas = listasConsultaRapidaEfectivas;
    if (l.id != null &&
        efectivas.any((c) => c.startsWith(prefijoIdLista))) {
      return efectivas.contains('$prefijoIdLista${l.id}');
    }
    return efectivas.contains(normalizarNombreLista(l.nombre));
  }

  /// true si la selección es la de fábrica (nadie la tocó todavía).
  static bool get listasConsultaRapidaSonPorDefecto =>
      listasConsultaRapida.isEmpty;

  /// Guarda la selección del dueño (en disco y en el backend).
  ///
  /// Guarda DOS claves por lista: el id (`id:80`) y el nombre
  /// normalizado (`krece`). El id es el que vale de acá en adelante;
  /// el nombre está para los equipos que todavía tienen una versión
  /// vieja de la app, que sólo saben comparar por nombre. Sin él,
  /// apenas un equipo actualizado guardara la selección, los demás
  /// no encontrarían ninguna coincidencia y la Consulta Rápida les
  /// quedaría sin un solo precio hasta que actualicen.
  ///
  /// Una selección vacía vuelve a las cuatro por defecto.
  static Future<void> guardarListasConsultaRapida(
      List<ListaPrecio> listas) async {
    final claves = <String>{};
    for (final l in listas) {
      claves.add(claveConsultaRapida(l));
      claves.add(normalizarNombreLista(l.nombre));  // compatibilidad
    }
    claves.removeWhere((c) => c.isEmpty);
    listasConsultaRapida = claves.toList();
    await guardarConfigGeneral();
  }

  /// Pasa una selección vieja (guardada por nombre) a una por id.
  ///
  /// Se llama cuando la Consulta Rápida ya tiene las listas del
  /// servidor cargadas, que es el único momento en que se puede
  /// saber a qué id corresponde cada nombre guardado.
  ///
  /// Cada nombre guardado se expande a TODAS las listas que hoy
  /// normalizan igual: si había dos KRECE quedan las dos marcadas,
  /// que es exactamente lo que el dueño venía viendo. Recién a
  /// partir de ahí puede destildar una sola y que surta efecto.
  ///
  /// Los nombres NO se borran, se les suman los ids: así los equipos
  /// que todavía no actualizaron siguen resolviendo por nombre.
  ///
  /// Devuelve true si hubo migración (para refrescar la pantalla).
  static Future<bool> migrarSeleccionConsultaRapidaAIds(
      List<ListaPrecio> listasCargadas) async {
    // Selección vacía = fábrica, no hay nada que migrar.
    if (listasConsultaRapida.isEmpty || listasCargadas.isEmpty) return false;

    // Si ya hay claves por id, esta selección ya pasó por acá.
    if (listasConsultaRapida.any((c) => c.startsWith(prefijoIdLista))) {
      return false;
    }

    final legado = listasConsultaRapida.toSet();
    final claves = {...listasConsultaRapida};
    for (final l in listasCargadas) {
      if (legado.contains(normalizarNombreLista(l.nombre))) {
        claves.add(claveConsultaRapida(l));
      }
    }

    // Ningún nombre guardado corresponde a una lista de hoy (las
    // renombraron o las borraron). Agregar cero ids y dejar sólo
    // nombres que ya no existen apagaría toda la consulta: mejor no
    // tocar nada y que el dueño elija de nuevo cuando quiera.
    if (claves.length == listasConsultaRapida.length) return false;

    listasConsultaRapida = claves.toList();
    await guardarConfigGeneral();
    debugPrint('[ConfigSistema] ✓ Selección de Consulta Rápida migrada '
        'a ids: ${listasConsultaRapida.join("|")}');
    return true;
  }

  static String textoFacturaPie = "Gracias por su compra. No se aceptan devoluciones sin factura.";
  static int diasGarantia = 30;
  /// Texto adicional/extendido de garantía. Si está vacío, en la factura
  /// solo se muestra "GARANTÍA · X DÍAS". Si tiene contenido, se muestra
  /// este texto debajo del badge (varias líneas si es necesario).
  /// Ejemplo: "Solo aplica para defectos de fábrica. No cubre daños por
  /// agua, caídas o manipulación indebida. Necesario presentar factura
  /// y producto en empaque original."
  static String textoGarantia = "";

  // ── Sistema de comisiones (DINÁMICO) ─────────────────────
  // La lista `categoriasComision` es la fuente de verdad. El admin
  // puede agregar/editar/eliminar categorías desde el panel.
  // Las 6 originales (accesorio, teléfono, línea, televisor, línea
  // blanca, financiador) están protegidas y no se pueden eliminar.
  // Los getters de abajo (comisionAccesorio, etc.) son por
  // retrocompatibilidad — leen de la lista dinámica.
  static List<CategoriaComision> categoriasComision =
      CategoriaComision.defaults();

  /// Helper: devuelve la categoría con el ID dado, o null si no existe.
  static CategoriaComision? categoriaComisionPorId(String id) {
    try {
      return categoriasComision.firstWhere((c) => c.id == id);
    } catch (_) {
      return null;
    }
  }

  // ── Getters de retrocompatibilidad ───────────────────────
  // Permiten que el código antiguo que aún use estos nombres siga
  // funcionando. Leen del sistema dinámico de categorías.
  static double get comisionAccesorio   => categoriaComisionPorId('accesorio')?.tarifaUSD   ?? 0.50;
  static double get comisionTelefono    => categoriaComisionPorId('telefono')?.tarifaUSD    ?? 1.00;
  static double get comisionLinea       => categoriaComisionPorId('linea')?.tarifaUSD       ?? 0.50;
  static double get comisionTelevisor   => categoriaComisionPorId('televisor')?.tarifaUSD   ?? 2.00;
  /// Retirada del sistema: el financiador ya no gana comisión.
  /// Se conserva el getter (en 0) para no romper el código antiguo
  /// que aún lo consulte. Ver [kCategoriaComisionEliminada].
  static double get comisionFinanciador => 0.0;
  static double get comisionLineaBlanca => categoriaComisionPorId('linea_blanca')?.tarifaUSD ?? 1.00;

  static double comisionBaseDefault = 40.00; // sueldo base semanal por defecto
  /// Porcentaje que se lleva el cajero cuando factura la venta de
  /// otro vendedor. Si es 35: el cajero recibe el 35% de la tarifa de
  /// comisión y el vendedor del producto solo el 65%. Balance exacto.
  /// Si vale 0, no hay split (el cajero no se lleva nada de las ventas
  /// que factura para otros).
  static double porcentajeCajeroDivision = 35.0;

  // ── Configuración SMTP para envío de correos ─────────────
