  // ── Encabezados por sede ─────────────────────────────────
  /// Mapa: nombreTienda → EncabezadoSede
  static Map<String, EncabezadoSede> encabezadosSede = {};

  /// Obtiene el encabezado de una sede. Si no existe, crea uno vacío.
  static EncabezadoSede encabezadoDe(String nombreSede) {
    return encabezadosSede.putIfAbsent(
      nombreSede,
      () => EncabezadoSede(nombreSede: nombreSede),
    );
  }

  /// Guarda o actualiza el encabezado de una sede.
  /// Guarda un encabezado de sede en memoria Y persiste todos los
  /// encabezados a SharedPreferences para que sobrevivan al cierre.
  /// TAMBIÉN sincroniza al backend para que otras PCs vean los mismos
  /// datos al iniciar sesión (antes solo se guardaba local, por eso
  /// al abrir sesión en otra máquina el logo, RIF, dirección, etc.
  /// no aparecían).
  static void guardarEncabezado(EncabezadoSede encabezado) {
    encabezadosSede[encabezado.nombreSede] = encabezado;
    // Persistir inmediatamente al disco (cache local)
    _persistirEncabezados();
    // Persistir al backend en segundo plano (multi-PC).
    // Sin await para no bloquear la UI — si falla la red, el disco
    // local sigue con los datos y la próxima sync reintentará.
    _persistirEncabezadoBackend(encabezado);
  }

  /// Envía un encabezado al backend usando el PUT de la tabla
  /// `tiendas`. Necesita saber el id de la tienda, que ya se guarda
  /// en `tiendasIds` (poblado por sincronizarTiendasBackend).
  /// Si el id no está disponible (tienda no sincronizada), se ignora
  /// y quedará solo local hasta la próxima sync.
  static Future<void> _persistirEncabezadoBackend(EncabezadoSede enc) async {
    try {
      final id = tiendasIds[enc.nombreSede];
      if (id == null) {
        debugPrint('[ConfigSistema] Encabezado no sincronizado al backend: '
            'no tenemos id de "${enc.nombreSede}"');
        return;
      }
      await _Api.put('tiendas', id.toString(), {
        'nombre':      enc.nombreSede,
        'direccion':   enc.direccion,
        'telefono':    enc.telefono,
        'rif':         enc.rif,
        'correo':      enc.correo,
        'logo_base64': enc.logoBytes != null
            ? base64Encode(enc.logoBytes!)
            : '',
        'activa':      1,
      });
      debugPrint('[ConfigSistema] ✓ Encabezado sincronizado al backend: '
          '${enc.nombreSede}');
    } catch (e) {
      debugPrint('[ConfigSistema] Error sincronizando encabezado al backend: $e');
    }
  }

  /// Wrapper público del persistir (para llamarlo desde fuera de la clase).
  static Future<void> persistirEncabezadosPublico() => _persistirEncabezados();

  /// Wrapper público del push al backend (para el auto-sync de arranque).
  /// Sube UN encabezado local al backend si el backend estaba vacío.
  static Future<void> pushEncabezadoPublico(EncabezadoSede enc)
      => _persistirEncabezadoBackend(enc);

  /// Persiste TODOS los encabezados de sede a SharedPreferences.
  /// Cada encabezado se serializa a JSON incluyendo el logo (en base64
  /// para que se pueda almacenar como string).
  static Future<void> _persistirEncabezados() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final mapaJson = <String, dynamic>{};
      encabezadosSede.forEach((nombre, enc) {
        mapaJson[nombre] = {
          'nombre_sede': enc.nombreSede,
          'rif': enc.rif,
          'direccion': enc.direccion,
          'telefono': enc.telefono,
          'correo': enc.correo,
          'logo_base64': enc.logoBytes != null
              ? base64Encode(enc.logoBytes!)
              : null,
        };
      });
      await prefs.setString('encabezados_sede', jsonEncode(mapaJson));
      debugPrint('[ConfigSistema] ✓ Encabezados persistidos '
          '(${encabezadosSede.length} sedes)');
    } catch (e) {
      debugPrint('[ConfigSistema] Error persistiendo encabezados: $e');
    }
  }

  /// Carga los encabezados de sede desde SharedPreferences. Se llama
  /// al iniciar la app para restaurar los logos y datos guardados.
  static Future<void> cargarEncabezados() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString('encabezados_sede');
      if (raw == null || raw.isEmpty) return;
      final decoded = jsonDecode(raw);
      if (decoded is! Map) return;
      encabezadosSede.clear();
      decoded.forEach((nombre, datos) {
        if (datos is Map) {
          Uint8List? logo;
          final logoB64 = datos['logo_base64'];
          if (logoB64 is String && logoB64.isNotEmpty) {
            try {
              logo = base64Decode(logoB64);
            } catch (_) {}
          }
          encabezadosSede[nombre.toString()] = EncabezadoSede(
            nombreSede: '${datos['nombre_sede'] ?? nombre}',
            rif: '${datos['rif'] ?? ''}',
            direccion: '${datos['direccion'] ?? ''}',
            telefono: '${datos['telefono'] ?? ''}',
            correo: '${datos['correo'] ?? ''}',
            logoBytes: logo,
          );
        }
      });
      debugPrint('[ConfigSistema] ✓ Encabezados cargados '
          '(${encabezadosSede.length} sedes)');
    } catch (e) {
      debugPrint('[ConfigSistema] Error cargando encabezados: $e');
    }
  }

  /// Guarda la configuración general (nombre empresa, garantía,
  /// texto pie, etc.) en SharedPreferences Y también al backend
  /// (tabla `configuracion`), para que se sincronice entre PCs.
  static Future<void> guardarConfigGeneral() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('cfg_nombre_empresa', nombreEmpresa);
      await prefs.setString('cfg_moneda', moneda);
      await prefs.setDouble('cfg_tasa_cambio', tasaCambio);
      await prefs.setInt('cfg_dias_garantia', diasGarantia);
      await prefs.setString('cfg_texto_pie', textoFacturaPie);
      await prefs.setString('cfg_texto_garantia', textoGarantia);
      await prefs.setDouble('cfg_max_descuento', maxDescuentoPorcentaje);
      await prefs.setBool('cfg_permitir_sin_stock', permitirVentaSinStock);
      await prefs.setBool('cfg_aprobacion_descuento',
          requiereAprobacionDescuento);
      await prefs.setBool('cfg_mostrar_costo', mostrarCostoEnFactura);
      await prefs.setDouble(
          'cfg_comision_base', comisionBaseDefault);
      await prefs.setString(
          'cfg_listas_consulta_rapida', listasConsultaRapida.join('|'));
      debugPrint('[ConfigSistema] ✓ Configuración general persistida en disco');
    } catch (e) {
      debugPrint('[ConfigSistema] Error persistiendo config general: $e');
    }
    // Sync al backend en segundo plano — si falla, el disco local
    // sigue con los datos y la próxima sync reintentará.
    _persistirConfigGeneralBackend();
  }

  /// Envía toda la configuración general al backend usando POST al
  /// endpoint `configuracion` (upsert por clave). Se llama después
  /// de guardar en disco. No bloquea la UI si falla.
  static Future<void> _persistirConfigGeneralBackend() async {
    try {
      await _Api.post('configuracion', {
        'cfg_nombre_empresa':          nombreEmpresa,
        'cfg_moneda':                  moneda,
        'cfg_tasa_cambio':             tasaCambio.toString(),
        'cfg_dias_garantia':           diasGarantia.toString(),
        'cfg_texto_pie':               textoFacturaPie,
        'cfg_texto_garantia':          textoGarantia,
        'cfg_max_descuento':           maxDescuentoPorcentaje.toString(),
        'cfg_permitir_sin_stock':      permitirVentaSinStock ? '1' : '0',
        'cfg_aprobacion_descuento':    requiereAprobacionDescuento ? '1' : '0',
        'cfg_mostrar_costo':           mostrarCostoEnFactura ? '1' : '0',
        'cfg_comision_base':           comisionBaseDefault.toString(),
        'cfg_listas_consulta_rapida':  listasConsultaRapida.join('|'),
      });
      debugPrint('[ConfigSistema] ✓ Configuración general enviada al backend');
    } catch (e) {
      debugPrint('[ConfigSistema] Error enviando config al backend: $e');
    }
  }

  /// Descarga la configuración general del backend y actualiza los
  /// valores en memoria. Se llama al iniciar sesión (después del login).
  /// Si el backend está vacío pero el disco local tiene datos, hace
  /// un push automático — así una PC con datos configurados sube todo
  /// al backend la primera vez que abre la app.
  static Future<void> sincronizarConfigBackend() async {
    try {
      final raw = await _Api.get('configuracion');
      if (raw is Map && raw.isNotEmpty) {
        // Hidratar valores desde el backend
        if (raw.containsKey('cfg_nombre_empresa'))
          nombreEmpresa = (raw['cfg_nombre_empresa'] ?? '').toString();
        if (raw.containsKey('cfg_moneda'))
          moneda = (raw['cfg_moneda'] ?? 'USD').toString();
        if (raw.containsKey('cfg_tasa_cambio'))
          tasaCambio = double.tryParse(raw['cfg_tasa_cambio'].toString()) ?? tasaCambio;
        if (raw.containsKey('cfg_dias_garantia'))
          diasGarantia = int.tryParse(raw['cfg_dias_garantia'].toString()) ?? diasGarantia;
        if (raw.containsKey('cfg_texto_pie'))
          textoFacturaPie = (raw['cfg_texto_pie'] ?? '').toString();
        if (raw.containsKey('cfg_texto_garantia'))
          textoGarantia = (raw['cfg_texto_garantia'] ?? '').toString();
        if (raw.containsKey('cfg_max_descuento'))
          maxDescuentoPorcentaje = double.tryParse(raw['cfg_max_descuento'].toString()) ?? maxDescuentoPorcentaje;
        if (raw.containsKey('cfg_permitir_sin_stock'))
          permitirVentaSinStock = raw['cfg_permitir_sin_stock'].toString() == '1';
        if (raw.containsKey('cfg_aprobacion_descuento'))
          requiereAprobacionDescuento = raw['cfg_aprobacion_descuento'].toString() == '1';
        if (raw.containsKey('cfg_mostrar_costo'))
          mostrarCostoEnFactura = raw['cfg_mostrar_costo'].toString() == '1';
        if (raw.containsKey('cfg_comision_base'))
          comisionBaseDefault = double.tryParse(raw['cfg_comision_base'].toString()) ?? comisionBaseDefault;
        if (raw.containsKey('cfg_listas_consulta_rapida')) {
          listasConsultaRapida = (raw['cfg_listas_consulta_rapida'] ?? '')
              .toString()
              .split('|')
              .map((e) => e.trim())
              .where((e) => e.isNotEmpty)
              .toList();
        }
        // Persistir a disco lo que vino del backend
        final prefs = await SharedPreferences.getInstance();
        await prefs.setInt('cfg_dias_garantia', diasGarantia);
        await prefs.setString('cfg_texto_garantia', textoGarantia);
        await prefs.setString('cfg_nombre_empresa', nombreEmpresa);
        await prefs.setString(
            'cfg_listas_consulta_rapida', listasConsultaRapida.join('|'));
        debugPrint('[ConfigSistema] ✓ Config hidratada desde backend');
      } else {
        // Backend vacío — subir lo que tenemos local (caso: primera
        // PC que arranca con el fix, todavía nada está en la BD).
        debugPrint('[ConfigSistema] Backend vacío, subiendo config local...');
        await _persistirConfigGeneralBackend();
      }
    } catch (e) {
      debugPrint('[ConfigSistema] Error sincronizando config con backend: $e');
    }
  }

  /// Carga la configuración general desde SharedPreferences.
  static Future<void> cargarConfigGeneral() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      nombreEmpresa = prefs.getString('cfg_nombre_empresa') ?? nombreEmpresa;
      moneda = prefs.getString('cfg_moneda') ?? moneda;
      tasaCambio = prefs.getDouble('cfg_tasa_cambio') ?? tasaCambio;
      diasGarantia = prefs.getInt('cfg_dias_garantia') ?? diasGarantia;
      textoFacturaPie =
          prefs.getString('cfg_texto_pie') ?? textoFacturaPie;
      textoGarantia =
          prefs.getString('cfg_texto_garantia') ?? textoGarantia;
      maxDescuentoPorcentaje =
          prefs.getDouble('cfg_max_descuento') ?? maxDescuentoPorcentaje;
      permitirVentaSinStock =
          prefs.getBool('cfg_permitir_sin_stock') ?? permitirVentaSinStock;
      requiereAprobacionDescuento =
          prefs.getBool('cfg_aprobacion_descuento') ??
              requiereAprobacionDescuento;
      mostrarCostoEnFactura =
          prefs.getBool('cfg_mostrar_costo') ?? mostrarCostoEnFactura;
      comisionBaseDefault =
          prefs.getDouble('cfg_comision_base') ?? comisionBaseDefault;
      listasConsultaRapida =
          (prefs.getString('cfg_listas_consulta_rapida') ?? '')
              .split('|')
              .map((e) => e.trim())
              .where((e) => e.isNotEmpty)
              .toList();
      debugPrint('[ConfigSistema] ✓ Configuración general cargada');
    } catch (e) {
      debugPrint('[ConfigSistema] Error cargando config general: $e');
    }
  }

  // ── Persistencia de categorías de comisión ──────────────
  // Guardamos el JSON completo de la lista en SharedPreferences
  // bajo la clave 'categorias_comision'. El admin puede modificar,
  // agregar y eliminar categorías; el cambio sobrevive reinicios.

  /// Carga la tasa Binance manual desde SharedPreferences.
  /// Es la tasa que usa el dueño para convertir Bs → $ en reportes.
  /// Si no hay nada guardado, queda en 0 (se usará tasa BCV).
  static Future<void> cargarTasaBinance() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      tasaBinance = prefs.getDouble('tasa_binance') ?? 0.0;
    } catch (e) {
      debugPrint('[ConfigSistema] cargarTasaBinance error: $e');
      tasaBinance = 0.0;
    }
  }

  /// Persiste el valor actual de tasaBinance.
  static Future<void> guardarTasaBinance(double valor) async {
    try {
      tasaBinance = valor;
      final prefs = await SharedPreferences.getInstance();
      await prefs.setDouble('tasa_binance', valor);
    } catch (e) {
      debugPrint('[ConfigSistema] guardarTasaBinance error: $e');
    }
  }

  /// Carga las categorías de comisión desde SharedPreferences.
  /// Si no hay nada guardado o el JSON es inválido, restaura las 6
  /// categorías por defecto. Las categorías protegidas (los IDs de
  /// las 6 originales) siempre quedan presentes — si alguien borró
  /// el archivo o el JSON está corrupto, se reinyectan.
  static Future<void> cargarCategoriasComision() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString('categorias_comision');
      if (raw == null || raw.trim().isEmpty) {
        categoriasComision = CategoriaComision.defaults();
        return;
      }
      final lista = (jsonDecode(raw) as List)
          .map((m) => CategoriaComision.fromMap(Map<String, dynamic>.from(m)))
          .toList();
      // Descartar la categoría "Financiador": el dueño decidió que el
      // financiador no gane comisión. Está persistida en los equipos
      // que ya venían usando el sistema, así que hay que sacarla acá
      // además de haberla quitado de defaults().
      lista.removeWhere((c) => c.id == kCategoriaComisionEliminada);
      // Garantizar que las protegidas existan siempre. Si falta
      // alguna (por ejemplo, datos viejos pre-refactor), la añadimos.
      final defaults = CategoriaComision.defaults();
      for (final def in defaults) {
        if (!lista.any((c) => c.id == def.id)) lista.add(def);
      }
      categoriasComision = lista;
    } catch (e) {
      debugPrint('[ConfigSistema] cargarCategoriasComision error: $e');
      categoriasComision = CategoriaComision.defaults();
    }
  }

  /// Persiste la lista actual de categorías de comisión.
  static Future<void> guardarCategoriasComision() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = jsonEncode(
          categoriasComision.map((c) => c.toMap()).toList());
      await prefs.setString('categorias_comision', raw);
    } catch (e) {
      debugPrint('[ConfigSistema] guardarCategoriasComision error: $e');
    }
  }

  /// Restaura las 6 categorías por defecto, descartando las
  /// personalizadas que el admin haya agregado. Llamado desde el
  /// botón "Restaurar valores originales" del panel.
  static Future<void> restaurarCategoriasComisionPorDefecto() async {
    categoriasComision = CategoriaComision.defaults();
    await guardarCategoriasComision();
  }
}

// ============================================================
//  SERVICIO DE CORREO SMTP
//  Envía correos con adjuntos usando la configuración SMTP de
//  ConfigSistema. Soporta Gmail, Outlook, Yahoo, y cualquier
//  servidor SMTP estándar.
//
//  Para Gmail: activa verificación en 2 pasos y genera una
//  contraseña de aplicación en https://myaccount.google.com/apppasswords
// ============================================================
class ServicioCorreo {
  /// Resultado del envío con detalles para depuración.
  static Future<ResultadoEnvioCorreo> enviar({
    required String destinatario,
    required String asunto,
    required String cuerpo,
    List<AdjuntoCorreo> adjuntos = const [],
    List<String> copia = const [],
    List<String> copiaOculta = const [],
    String? htmlCuerpo,
  }) async {
    // Validar configuración
    if (ConfigSistema.smtpUsername.isEmpty ||
        ConfigSistema.smtpPassword.isEmpty) {
      return ResultadoEnvioCorreo(
        exitoso: false,
        mensaje:
            'SMTP no configurado. Configure usuario y contraseña en el Panel de Configuración → Correos SMTP.',
      );
    }

    try {
      // Construir servidor SMTP
      final servidor = smtp.SmtpServer(
        ConfigSistema.smtpHost,
        port: ConfigSistema.smtpPort,
        ssl: ConfigSistema.smtpSsl,
        username: ConfigSistema.smtpUsername,
        password: ConfigSistema.smtpPassword,
        allowInsecure: false,
      );

      final remitente = ConfigSistema.smtpCorreoRemitente.isNotEmpty
          ? ConfigSistema.smtpCorreoRemitente
          : ConfigSistema.smtpUsername;

      final mensaje = mailer.Message()
        ..from = mailer.Address(remitente, ConfigSistema.smtpNombreRemitente)
        ..recipients.add(destinatario)
        ..ccRecipients.addAll(copia)
        ..bccRecipients.addAll(copiaOculta)
        ..subject = asunto
        ..text = cuerpo;

      if (htmlCuerpo != null && htmlCuerpo.isNotEmpty) {
        mensaje.html = htmlCuerpo;
      }

      // Adjuntos
      for (final adj in adjuntos) {
        mensaje.attachments.add(mailer.StreamAttachment(
          Stream.value(adj.bytes),
          adj.mimeType,
          fileName: adj.nombreArchivo,
        ));
      }

      final resultado = await mailer.send(mensaje, servidor);
      debugPrint('[SMTP] Correo enviado: ${resultado.toString()}');
      return ResultadoEnvioCorreo(
        exitoso: true,
        mensaje: 'Correo enviado correctamente a $destinatario',
      );
    } on mailer.MailerException catch (e) {
      final errores = e.problems.map((p) => p.msg).join('; ');
      debugPrint('[SMTP] Error del servidor: $errores');
      return ResultadoEnvioCorreo(
        exitoso: false,
        mensaje: 'Error al enviar: $errores',
      );
    } catch (e) {
      debugPrint('[SMTP] Error inesperado: $e');
      return ResultadoEnvioCorreo(
        exitoso: false,
        mensaje: 'Error inesperado: $e',
      );
    }
  }

  /// Prueba rápida de conexión SMTP enviándose un correo a sí mismo.
  static Future<ResultadoEnvioCorreo> probarConexion() async {
    final correo = ConfigSistema.smtpCorreoRemitente.isNotEmpty
        ? ConfigSistema.smtpCorreoRemitente
        : ConfigSistema.smtpUsername;
    if (correo.isEmpty) {
      return ResultadoEnvioCorreo(
        exitoso: false,
        mensaje: 'Configure primero los datos SMTP.',
      );
    }
    return enviar(
      destinatario: correo,
      asunto: '✅ Prueba de conexión SMTP - Weppa App',
      cuerpo:
          'Si recibe este correo, la configuración SMTP está funcionando correctamente.\n\n'
          'Servidor: ${ConfigSistema.smtpHost}:${ConfigSistema.smtpPort}\n'
          'SSL: ${ConfigSistema.smtpSsl ? "Sí" : "No (STARTTLS)"}',
    );
  }
}

class ResultadoEnvioCorreo {
  final bool exitoso;
  final String mensaje;
  ResultadoEnvioCorreo({required this.exitoso, required this.mensaje});
}

class AdjuntoCorreo {
  final Uint8List bytes;
  final String nombreArchivo;
  final String mimeType;
  AdjuntoCorreo({
    required this.bytes,
    required this.nombreArchivo,
    this.mimeType = 'application/pdf',
  });
}

// ============================================================
//  PANEL ADMINISTRATIVO
// ============================================================
class VentanaPanelAdmin extends StatefulWidget {
  const VentanaPanelAdmin({super.key});
  @override State<VentanaPanelAdmin> createState() => _VentanaPanelAdminState();
}

class _VentanaPanelAdminState extends State<VentanaPanelAdmin>
    with SingleTickerProviderStateMixin {
  late TabController _tabs;

  double _totalVentasMes = 0, _totalCostoInventario = 0, _totalVentaInventario = 0;
  double _totalCxCobrar = 0, _totalCxPagar = 0, _totalComisionesMes = 0;
  int _totalProductos = 0, _totalImeis = 0, _totalImeisVendidos = 0;
  int _totalLineas = 0, _totalLineasActivadas = 0, _totalServicios = 0;
  List<Map<String,dynamic>> _topVendedores = [];
  List<Map<String,dynamic>> _ventasRecientes = [];
  List<Map<String,dynamic>> _financiadoras = [];
  bool _cargando = true;
  String? _error;

  @override
  void initState() {
    super.initState();
    _tabs = TabController(length: 6, vsync: this);
    TasaBCVScheduler.addListener(_onTasaActualizada);
    _cargar();
  }

  void _onTasaActualizada() { if (mounted) setState(() {}); }

  @override
  void dispose() {
    _tabs.dispose();
    TasaBCVScheduler.removeListener(_onTasaActualizada);
    super.dispose();
  }

  Future<void> _cargar() async {
    setState(() { _cargando = true; _error = null; });
    try {
      final now = DateTime.now();

      // ── Cargar TODOS los recursos en paralelo ──────────────
      final results = await Future.wait([
        _Api.get('facturas').catchError((e) { debugPrint('facturas: $e'); return null; }),       // 0
        _Api.get('productos').catchError((e) { debugPrint('productos: $e'); return null; }),      // 1
        _Api.get('stock_imei').catchError((e) { debugPrint('stock_imei: $e'); return null; }),    // 2
        _Api.get('cuentas_cobrar').catchError((e) { debugPrint('cxc: $e'); return null; }),       // 3
        _Api.get('cuentas_pagar').catchError((e) { debugPrint('cxp: $e'); return null; }),        // 4
        _Api.get('lineas').catchError((e) { debugPrint('lineas: $e'); return null; }),             // 5
        _Api.get('servicios').catchError((e) { debugPrint('servicios: $e'); return null; }),      // 6
        _Api.get('comisiones_historial').catchError((e) { debugPrint('comisiones: $e'); return null; }),    // 7
      ]);

      final rawFacturas = ((results[0] as List?) ?? []);
      final rawProds    = ((results[1] as List?) ?? []);
      final rawImeis    = ((results[2] as List?) ?? []);
      final rawCxC      = ((results[3] as List?) ?? []);
      final rawCxP      = ((results[4] as List?) ?? []);
      final rawLineas   = ((results[5] as List?) ?? []);
      final rawServ     = ((results[6] as List?) ?? []);
      final rawComis    = ((results[7] as List?) ?? []);

      // ── Ventas ────────────────────────────────────────────
      _totalVentasMes = 0;
      final Map<String,double> porVendedor = {};
      final Map<String,int>    cantPorVendedor = {};
      for (var f in rawFacturas) {
        final total = double.tryParse(f['total'].toString()) ?? 0;
        try {
          final fecha = parseFecha(f['fecha'] ?? '');
          if (fecha.month == now.month && fecha.year == now.year) _totalVentasMes += total;
        } catch (_) {}
        final vend = f['vendedor']?.toString() ?? 'Sin vendedor';
        porVendedor[vend] = (porVendedor[vend] ?? 0) + total;
        cantPorVendedor[vend] = (cantPorVendedor[vend] ?? 0) + 1;
      }
      final entries = porVendedor.entries.toList()..sort((a,b) => b.value.compareTo(a.value));
      _topVendedores = entries.take(5).map((e) {
        final u = usuariosSistema.where((u) => u.nombre == e.key).firstOrNull;
        return {'nombre': e.key, 'total': e.value,
          'cantidad': cantPorVendedor[e.key] ?? 0,
          'sueldo_base': u?.sueldoBase ?? 0.0, 'rol': u?.rol ?? ''};
      }).toList();
      _ventasRecientes = rawFacturas.reversed.take(10).map((f) => Map<String,dynamic>.from(f)).toList();

      // ── Inventario ────────────────────────────────────────
      _totalProductos = rawProds.length;
      _totalImeis = rawImeis.length;
      _totalImeisVendidos = rawImeis.where((i) => (i['vendido'] ?? 0) == 1).length;
      _totalCostoInventario = 0; _totalVentaInventario = 0;
      for (var p in rawProds) {
        final costo = double.tryParse(p['precio_costo'].toString()) ?? 0;
        final venta = double.tryParse(p['precio_venta'].toString()) ?? 0;
        final stockReal = p['categoria'] == 'Telefono'
            ? rawImeis.where((i) => i['producto_codigo'] == p['codigo'] && (i['vendido']??0)==0).length
            : (int.tryParse(p['stock_manual'].toString()) ?? 0);
        _totalCostoInventario += costo * stockReal;
        _totalVentaInventario += venta * stockReal;
      }

      // ── Cuentas por cobrar ────────────────────────────────
      _totalCxCobrar = rawCxC.fold(0.0, (s, c) {
        final total = double.tryParse(c['monto_total'].toString()) ?? 0;
        final pagos = (c['pagos'] as List? ?? []).fold(0.0, (sp, p) => sp + (double.tryParse(p['monto'].toString()) ?? 0));
        return s + (total - pagos).clamp(0, double.infinity);
      });

      // ── Cuentas por pagar ─────────────────────────────────
      _totalCxPagar = rawCxP.fold(0.0, (s, c) {
        final total = double.tryParse(c['monto_total'].toString()) ?? 0;
        final pagos = (c['pagos'] as List? ?? []).fold(0.0, (sp, p) => sp + (double.tryParse(p['monto'].toString()) ?? 0));
        return s + (total - pagos).clamp(0, double.infinity);
      });

      // ── Líneas ────────────────────────────────────────────
      _totalLineas = rawLineas.length;
      _totalLineasActivadas = rawLineas.where((l) => (l['activada']??0)==1).length;

      // ── Servicios ─────────────────────────────────────────
      _totalServicios = rawServ.length;

      // ── Comisiones del mes ────────────────────────────────
      _totalComisionesMes = 0;
      for (var h in rawComis) {
        try {
          // Usar tryParse para evitar crash en fecha_inicio vacía
          final fi = DateTime.tryParse(h['fecha_inicio']?.toString() ?? '') ?? DateTime(2000);
          if (fi.month == now.month && fi.year == now.year) {
            final tasa = double.tryParse(h['tasa'].toString()) ?? 1;
            for (var d in ((h['detalle'] as List?) ?? [])) {
              final r = ResumenComision.fromMap(d);
              _totalComisionesMes += r.totalPagar() * tasa;
            }
          }
        } catch (_) {}
      }

      // ── Financiadoras ─────────────────────────────────────
      _financiadoras = listasPreciosGlobal
          .where((l) => l.esFinanciamiento && l.financiadora != null)
          .fold(<Map<String,dynamic>>[], (acc, l) {
            if (!acc.any((f) => f['nombre'] == l.financiadora)) {
              acc.add({'nombre': l.financiadora!, 'lista': l.nombre,
                'pct_adicional': l.porcentajeAdicional,
                'pct_inicial': l.porcentajeInicial, 'cuotas': l.numeroCuotas});
            }
            return acc;
          });

      if (mounted) setState(() => _cargando = false);
    } catch (e) {
      debugPrint('PanelAdmin error: $e');
      if (mounted) setState(() { _cargando = false; _error = e.toString(); });
    }
  }


  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.surfaceTintBlue,
      appBar: AppBar(
        title: const Text("Panel Administrativo"),
        backgroundColor: AppColors.royalBlue,
        foregroundColor: Colors.white,
        actions: [
          const TasaBCVBadge(),
          const SizedBox(width: 4),
          IconButton(icon: const Icon(Icons.refresh), onPressed: _cargar),
        ],
        bottom: TabBar(
          controller: _tabs,
          labelColor: Colors.white,
          unselectedLabelColor: Colors.white60,
          indicatorColor: AppColors.primaryBlue,
          isScrollable: true,
          tabs: const [
            Tab(icon: Icon(Icons.dashboard), text: "Resumen"),
            Tab(icon: Icon(Icons.trending_up), text: "Ventas"),
            Tab(icon: Icon(Icons.inventory_2), text: "Inventario"),
            Tab(icon: Icon(Icons.people_alt), text: "Equipo"),
            Tab(icon: Icon(Icons.account_balance_outlined), text: "Financ."),
            Tab(icon: Icon(Icons.calculate_outlined), text: "Costos"),
          ],
        ),
      ),
      body: _cargando
          ? const Center(child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
              CircularProgressIndicator(),
              SizedBox(height: 16),
              Text("Cargando datos administrativos..."),
            ]))
          : _error != null
              ? Center(child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
                  const Icon(Icons.error_outline, size: 60, color: Colors.red),
                  const SizedBox(height: 12),
                  const Text("Error al cargar datos", style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
                  const SizedBox(height: 8),
                  Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 32),
                    child: Text(_error!, textAlign: TextAlign.center, style: const TextStyle(color: Colors.grey))),
                  const SizedBox(height: 20),
                  ElevatedButton.icon(icon: const Icon(Icons.refresh), label: const Text("Reintentar"), onPressed: _cargar),
                ]))
              : TabBarView(controller: _tabs, children: [
                  _tabResumen(),
                  _tabVentas(),
                  _tabInventario(),
                  _tabEquipo(),
                  _tabFinanciadoras(),
                  const VentanaCostosFinanzas(),
                ]),
    );
  }

