    return InkWell(onTap: onTap, child: Container(
      width: 140, padding: const EdgeInsets.symmetric(vertical: 14, horizontal: 12),
      decoration: BoxDecoration(color: color.withValues(alpha: 0.1), borderRadius: BorderRadius.circular(10), border: Border.all(color: color.withValues(alpha: 0.3))),
      child: Row(children: [
        Icon(icon, color: color, size: 20),
        const SizedBox(width: 8),
        Expanded(child: Text(label, style: TextStyle(color: color, fontWeight: FontWeight.w600, fontSize: 12))),
      ]),
    ));
  }

  // ── TAB 2: VENTAS ─────────────────────────────────────────
  Widget _tabVentas() {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(16),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        const Text("Últimas Ventas", style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
        const SizedBox(height: 12),
        if (_ventasRecientes.isEmpty)
          const Center(child: Text("No hay ventas registradas"))
        else
          ..._ventasRecientes.map((f) {
