// ============================================================
//  VENTANA CONECTAR IMPRESORA (accesible para TODOS los roles)
//  Versión reducida que sólo muestra la sección de impresora,
//  sin tabs ni el resto de la configuración del sistema.
// ============================================================
class VentanaConectarImpresora extends StatefulWidget {
  const VentanaConectarImpresora({super.key});
  @override
  State<VentanaConectarImpresora> createState() => _VentanaConectarImpresoraState();
}

class _VentanaConectarImpresoraState extends State<VentanaConectarImpresora> {
  /// Diálogo para elegir una impresora del sistema operativo (USB, red,
  /// AirPrint, etc.) y guardarla como preferida. Funciona en Windows,
  /// macOS, Linux, Android e iOS.
  Future<void> _seleccionarImpresoraSistema() async {
    // Mostrar progreso mientras se escanea
    showDialog(
      context: context,
      barrierDismissible: false,
      builder: (_) => const AlertDialog(
        content: Row(children: [
          CircularProgressIndicator(),
          SizedBox(width: 16),
          Expanded(child: Text("Buscando impresoras del sistema...")),
        ]),
      ),
    );
    List<Printer> printers = [];
    try {
      printers = await ImpresoraSistema.listarImpresoras();
    } catch (e) {
      debugPrint('[Impresora sistema] error: $e');
    }
    if (!mounted) return;
    Navigator.pop(context); // cerrar el progreso

    if (printers.isEmpty) {
      if (!mounted) return;
      showDialog(
        context: context,
        builder: (_) => AlertDialog(
          shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(14)),
          icon: const Icon(Icons.print_disabled,
              color: AppColors.statusOrange, size: 40),
          title: const Text("Sin impresoras"),
          content: const Text(
            "No se detectaron impresoras del sistema.\n\n"
            "Verifique que:\n"
            "• La impresora esté encendida y conectada\n"
            "• En PC: que esté instalada en el panel de control\n"
            "• En móvil: que esté en la misma red WiFi\n"
            "• Si es USB en PC, que el cable esté firme",
            style: TextStyle(fontSize: 13)),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context),
              child: const Text("Entendido")),
          ],
        ),
      );
      return;
    }

    // Mostrar lista de impresoras
    final elegida = await showDialog<Printer>(
      context: context,
      builder: (c) => AlertDialog(
        shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(14)),
        title: const Row(children: [
          Icon(Icons.print, color: AppColors.royalBlue),
          SizedBox(width: 8),
          Text("Seleccionar impresora"),
        ]),
        content: SizedBox(
          width: double.maxFinite,
          child: ListView.builder(
            shrinkWrap: true,
            itemCount: printers.length,
            itemBuilder: (_, i) {
              final p = printers[i];
              final esPreferida =
                  p.url == ImpresoraSistema.urlImpresoraPreferida;
              return Card(
                elevation: 0,
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(8),
                  side: BorderSide(color: esPreferida
                      ? AppColors.statusGreen
                      : Colors.grey.shade300, width: esPreferida ? 2 : 1)),
                child: ListTile(
                  leading: Icon(
                    p.isDefault ? Icons.star : Icons.print,
                    color: esPreferida
                        ? AppColors.statusGreen
                        : AppColors.royalBlue),
                  title: Text(p.name,
                      style: const TextStyle(fontSize: 13.5,
                          fontWeight: FontWeight.w600)),
                  subtitle: Text(p.url,
                      maxLines: 1, overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                          fontSize: 11, fontFamily: 'monospace')),
                  trailing: esPreferida
                      ? const Icon(Icons.check_circle,
                          color: AppColors.statusGreen)
                      : null,
                  onTap: () => Navigator.pop(c, p),
                ),
              );
            },
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(c),
              child: const Text("Cancelar")),
        ],
      ),
    );

    if (elegida != null) {
      await ImpresoraSistema.guardarPreferida(elegida);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text("✓ Impresora configurada: ${elegida.name}"),
          backgroundColor: AppColors.statusGreen,
          duration: const Duration(seconds: 2)));
      }
    }
  }

  Widget _seccion(String titulo, IconData icon, List<Widget> hijos) {
    return Card(
      elevation: 0,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(12),
        side: BorderSide(color: Colors.grey.shade300)),
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            Icon(icon, size: 20, color: AppColors.royalBlue),
            const SizedBox(width: 8),
            Text(titulo, style: const TextStyle(
              fontSize: 15, fontWeight: FontWeight.bold)),
          ]),
          const SizedBox(height: 14),
          ...hijos,
        ]),
      ),
    );
  }

  Widget _pasoGuia(String numero, String texto) => Padding(
    padding: const EdgeInsets.symmetric(vertical: 5),
    child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Container(
        width: 24, height: 24,
        decoration: const BoxDecoration(
          color: AppColors.primaryBlue,
          shape: BoxShape.circle),
        child: Center(child: Text(numero,
          style: const TextStyle(
            color: Colors.white,
            fontWeight: FontWeight.bold, fontSize: 12))),
      ),
      const SizedBox(width: 10),
      Expanded(child: Padding(
        padding: const EdgeInsets.only(top: 3),
        child: Text(texto, style: const TextStyle(fontSize: 12)))),
    ]));

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.surfaceTintBlue,
      appBar: AppBar(
        title: const Text("Conectar Impresora"),
        backgroundColor: AppColors.royalBlue,
        foregroundColor: Colors.white,
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Column(children: [
          // ── Aviso informativo ──
          Container(
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: AppColors.primaryBlue.withValues(alpha: 0.08),
              borderRadius: BorderRadius.circular(10),
              border: Border.all(color: AppColors.primaryBlue.withValues(alpha: 0.2))),
            child: Row(children: [
              const Icon(Icons.info_outline, color: AppColors.primaryBlue, size: 20),
              const SizedBox(width: 10),
              Expanded(child: Text(
                "Conecte su impresora térmica por Bluetooth para imprimir "
                "directamente sin necesidad de instalar drivers.",
                style: TextStyle(fontSize: 12,
                  color: AppColors.primaryBlue.withValues(alpha: 0.85)))),
            ]),
          ),
          const SizedBox(height: 16),

          // ── Estado de la impresora configurada ──
          _seccion("Impresora configurada", Icons.print_outlined, [
            if (ImpresoraBT.macImpresoraPreferida != null) ...[
              Container(
                padding: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: AppColors.statusGreen.withValues(alpha: 0.08),
                  borderRadius: BorderRadius.circular(10),
                  border: Border.all(color: AppColors.statusGreen.withValues(alpha: 0.3))),
                child: Row(children: [
                  Container(
                    width: 42, height: 42,
                    decoration: BoxDecoration(
                      color: AppColors.statusGreen.withValues(alpha: 0.15),
                      borderRadius: BorderRadius.circular(10)),
                    child: const Icon(Icons.bluetooth_connected,
                      color: AppColors.statusGreen, size: 22),
                  ),
                  const SizedBox(width: 12),
                  Expanded(child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(ImpresoraBT.nombreImpresoraPreferida ?? 'Impresora',
                        style: const TextStyle(
                          fontSize: 14, fontWeight: FontWeight.bold)),
                      const SizedBox(height: 2),
                      Text(ImpresoraBT.macImpresoraPreferida!,
                        style: const TextStyle(
                          fontSize: 11,
                          color: AppColors.textSecondary,
                          fontFamily: 'monospace')),
                    ])),
                  IconButton(
                    icon: const Icon(Icons.close, color: Colors.red, size: 20),
                    tooltip: "Quitar",
                    onPressed: () async {
                      await ImpresoraBT.limpiarPreferida();
                      ImpresoraBT.desconectar();
                      if (mounted) setState(() {});
                    }),
                ]),
              ),
            ] else ...[
              Container(
                padding: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: Colors.grey[100],
                  borderRadius: BorderRadius.circular(10)),
                child: Row(children: [
                  Icon(Icons.bluetooth_disabled,
                    size: 22, color: Colors.grey[600]),
                  const SizedBox(width: 10),
                  Expanded(child: Text(
                    "No hay impresora Bluetooth seleccionada.",
                    style: TextStyle(
                      fontSize: 13, color: Colors.grey[700]))),
                ]),
              ),
            ],
            const SizedBox(height: 12),

            // Botón seleccionar/cambiar impresora
            SizedBox(
              width: double.infinity,
              child: ElevatedButton.icon(
                icon: const Icon(Icons.bluetooth_searching),
                label: Text(ImpresoraBT.macImpresoraPreferida != null
                  ? "Cambiar impresora" : "Buscar impresoras"),
                style: ElevatedButton.styleFrom(
                  backgroundColor: AppColors.primaryBlue,
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(vertical: 13),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(10))),
                onPressed: () async {
                  final ok = await ImpresoraBT.seleccionarImpresoraDialog(context);
                  if (ok && mounted) setState(() {});
                },
              ),
            ),

            // Botón prueba de impresión
            if (ImpresoraBT.macImpresoraPreferida != null) ...[
              const SizedBox(height: 8),
              SizedBox(
                width: double.infinity,
                child: OutlinedButton.icon(
                  icon: const Icon(Icons.print_outlined),
                  label: const Text("Imprimir página de prueba"),
                  style: OutlinedButton.styleFrom(
                    padding: const EdgeInsets.symmetric(vertical: 13),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(10))),
                  onPressed: () async {
                    final pdf = pw.Document();
                    pdf.addPage(pw.Page(
                      pageFormat: ImpresionHelper.formatoPdf(
                        FormatoImpresion.termica80),
                      margin: const pw.EdgeInsets.all(4),
                      build: (_) => pw.Column(
                        crossAxisAlignment: pw.CrossAxisAlignment.center,
                        children: [
                          pw.SizedBox(height: 10),
                          pw.Text("PRUEBA DE IMPRESIÓN",
                            style: pw.TextStyle(
                              fontSize: 14,
                              fontWeight: pw.FontWeight.bold)),
                          pw.SizedBox(height: 8),
                          if (ConfigSistema.nombreEmpresa.trim().isNotEmpty) ...[
                            pw.Text(ConfigSistema.nombreEmpresa,
                              style: pw.TextStyle(
                                fontSize: 11,
                                fontWeight: pw.FontWeight.bold)),
                            pw.SizedBox(height: 4),
                          ],
                          pw.Text("Si puede leer esto, la impresora",
                            style: const pw.TextStyle(fontSize: 9)),
                          pw.Text("está funcionando correctamente.",
                            style: const pw.TextStyle(fontSize: 9)),
                          pw.SizedBox(height: 8),
                          pw.Text(DateTime.now().toString().substring(0, 19),
                            style: const pw.TextStyle(fontSize: 9)),
                          pw.SizedBox(height: 6),
                          pw.Text("¡GRACIAS!",
                            style: pw.TextStyle(
                              fontSize: 13,
                              fontWeight: pw.FontWeight.bold)),
                        ]),
                    ));
                    final bytes = await pdf.save();
                    final ok = await ImpresoraBT.imprimirPdf(bytes);
                    if (context.mounted) {
                      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                        content: Text(ok
                          ? "✓ Prueba enviada correctamente"
                          : "⚠ No se pudo imprimir. Verifique la conexión"),
                        backgroundColor: ok
                          ? AppColors.statusGreen : AppColors.statusRed));
                    }
                  },
                ),
              ),
            ],
          ]),
