            onTap: () async {
              showDialog(context: context, barrierDismissible: false, builder: (_) =>
                const AlertDialog(content: Row(children: [CircularProgressIndicator(), SizedBox(width: 16), Text("Sincronizando...")])));
              await cargarTodosLosDatos();
              if (!mounted) return;
              Navigator.pop(context);
              ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text("Datos sincronizados correctamente"), backgroundColor: AppColors.statusGreen));
            },
          ),
          const Divider(),
          ListTile(
            leading: const Icon(Icons.logout, color: Colors.red),
            title: const Text("Cerrar todas las sesiones"),
