  void _agregarFilaSegunTab() {
    switch (_tabs.index) {
      case 0:
        setState(() => _inventario.add(ItemInventarioCF()));
        break;
      case 1:
        // Compras: crear en BD, después agregar a la UI con su id.
        _crearCompraEnBD();
        break;
      case 2:
        setState(() => _ventas.add(ItemVentasCF(
            fecha: DateTime.now(), tasaDia: _tasaBinanceVentas)));
        break;
      case 3: setState(() => _nomina.add(ItemNominaCF())); break;
      case 4: setState(() => _gastosAdmin.add(ItemGastoCF())); break;
      case 7: break;
      default: break;
    }
  }

  /// Crea una compra nueva en la BD y la agrega a la lista local.
  /// Si la creación falla, no se agrega (evita que aparezca una fila
  /// fantasma que no está persistida).
  Future<void> _crearCompraEnBD() async {
    final hoy = DateTime.now();
    final compra = ItemComprasCF(
      fecha: hoy,
      tasaDia: _tasaBinanceCompras,
    );
    try {
      final resp = await _Api.post('compras', compra.toMap());
      if (resp is Map && resp['id'] != null) {
        compra.id = resp['id'] is int
            ? resp['id']
            : int.tryParse(resp['id'].toString());
      }
      setState(() {
        _compras.add(compra);
        _recalcularInventarioConCompras();
      });
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text('Error creando compra: $e'),
          backgroundColor: AppColors.statusRed));
    }
  }

  /// Actualiza una compra en BD (debounced para no spammear la API
  /// mientras el usuario escribe). Mantiene un timer por id.
  final Map<int, Timer> _timersCompras = {};

  void _actualizarCompraEnBD(ItemComprasCF c) {
    if (c.id == null) return;
    _timersCompras[c.id!]?.cancel();
    _timersCompras[c.id!] = Timer(
        const Duration(milliseconds: 600), () async {
      try {
        await _Api.put('compras', c.id!.toString(), c.toMap());
      } catch (e) {
        debugPrint('Error actualizando compra ${c.id}: $e');
      }
    });
  }

  /// Borra una compra de la BD y de la lista local.
  Future<void> _eliminarCompraEnBD(int idx) async {
    final c = _compras[idx];
    if (c.id != null) {
      try {
        await _Api.delete('compras', c.id!.toString());
      } catch (e) {
        if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(
            content: Text('Error eliminando: $e'),
            backgroundColor: AppColors.statusRed));
        return;
      }
    }
    setState(() {
      _compras.removeAt(idx);
      _recalcularInventarioConCompras();
    });
  }

