// ════════════════════════════════════════════════════════════════════
//                                                                  
//  VENTANA: REPORTE POR VENDEDOR                                   
//                                                                  
// ════════════════════════════════════════════════════════════════════
//  Genera un reporte detallado de ventas filtrable por:           
//    · Rango de fechas                                             
//    · Vendedor específico (o todos)                               
//    · Tienda (o todas)                                            
//    · Método de pago (o todos)                                    
//                                                                  
//  Vista en 2 pestañas:                                           
//    · RESUMEN: agrupado por vendedor con totales                  
//    · DETALLE: tabla plana con TODO lo que vendió cada uno,       
//      incluyendo marca y modelo de cada producto                  
//                                                                  
//  Exportable a Excel y PDF.                                       
// ════════════════════════════════════════════════════════════════════
class VentanaReporteVendedor extends StatefulWidget {
  const VentanaReporteVendedor({super.key});
  @override
  State<VentanaReporteVendedor> createState() => _VentanaReporteVendedorState();
}

class _VentanaReporteVendedorState extends State<VentanaReporteVendedor>
    with SingleTickerProviderStateMixin {
  // ── Filtros ──────────────────────────────────────────────────
  DateTime? _desde;
  DateTime? _hasta;
  String? _vendedorFiltro;   // null = todos
  String? _tiendaFiltro;     // null = todas
  String? _metodoPagoFiltro; // null = todos
  String? _marcaFiltro;      // null = todas
  String? _modeloFiltro;     // null = todos

  late TabController _tabCtrl;
  bool _cargando = false;

  @override
  void initState() {
    super.initState();
    _tabCtrl = TabController(length: 2, vsync: this);
    // Por defecto: mes actual
    final now = DateTime.now();
    _desde = DateTime(now.year, now.month, 1);
    _hasta = now;
    // Cargar facturas del backend si la lista global está vacía
    // (esto pasa cuando el usuario abre el reporte sin haber ido
    // antes a la pantalla de Facturas).
    if (ventasGlobal.isEmpty) _cargarFacturas();
  }

  Future<void> _cargarFacturas() async {
    setState(() => _cargando = true);
    try {
      final raw = await _Api.get('facturas');
      final lista = ((raw as List?) ?? [])
          .map((m) => _construirFactura(m as Map<String, dynamic>))
          .toList();
      ventasGlobal = lista;
    } catch (e) {
      debugPrint('[ReporteVendedor] error cargando facturas: $e');
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  /// Construye un FacturaModel desde el Map del backend.
  /// El backend devuelve equipos como List<String> (IMEIs) e items como
  /// List<String> (códigos). Los resolvemos contra catalogoGlobal /
  /// stockImeiGlobal para tener objetos completos.
  FacturaModel _construirFactura(Map<String, dynamic> m) {
    // Usamos el parser global. Garantiza misma lógica que el resto de
    // los reportes (Comisiones, Estadísticas) y que los maps de
    // vendedor por producto y `creador_rol` se lean correctamente.
    return construirFacturaModelDesdeJson(m);
  }

  @override
  void dispose() {
    _tabCtrl.dispose();
    super.dispose();
  }

  // ─────────────────────────────────────────────────────────────
  //  CÁLCULOS
  // ─────────────────────────────────────────────────────────────

  /// Facturas filtradas según los selectores actuales.
  List<FacturaModel> get _facturasFiltradas {
    return ventasGlobal.where((f) {
      // Filtro fecha (parsea f.fecha que es String yyyy-MM-dd...)
      final fecha = parseFechaFlexible(f.fecha);
      if (fecha != null) {
        if (_desde != null && fecha.isBefore(_desde!)) return false;
        if (_hasta != null) {
          // Incluir el día completo
          final fin = DateTime(_hasta!.year, _hasta!.month, _hasta!.day, 23, 59, 59);
          if (fecha.isAfter(fin)) return false;
        }
      }
      // Filtro vendedor
      // Filtro vendedor: incluir la factura si el filtro es el creador
      // O si CUALQUIER producto de la factura está asignado a ese vendedor.
      // Esto evita perder ventas donde un cajero facturó pero el vendedor
      // real era otra persona.
      if (_vendedorFiltro != null) {
        final esCoincidencia = f.vendedor == _vendedorFiltro
            || f.equipos.any((e) => f.vendedorDeEquipo(e.imei) == _vendedorFiltro)
            || f.itemsSinImei.any((p) => f.vendedorDeItem(p.codigo) == _vendedorFiltro);
        if (!esCoincidencia) return false;
      }
      // Filtro tienda
      if (_tiendaFiltro != null && f.tienda != _tiendaFiltro) return false;
      // Filtro método de pago: la factura cuenta si AL MENOS un pago
      // coincide con el método elegido.
      if (_metodoPagoFiltro != null) {
        final tieneMetodo = f.pagos.any((p) => p.metodo == _metodoPagoFiltro);
        if (!tieneMetodo) return false;
      }
      // Filtro marca: la factura cuenta si AL MENOS un producto/equipo
      // es de la marca elegida.
      if (_marcaFiltro != null) {
        final tieneMarca = f.equipos.any((e) => e.producto.marca == _marcaFiltro)
            || f.itemsSinImei.any((p) => p.marca == _marcaFiltro);
        if (!tieneMarca) return false;
      }
      // Filtro modelo: igual pero por modelo específico.
      if (_modeloFiltro != null) {
        final tieneModelo = f.equipos.any((e) => e.producto.modelo == _modeloFiltro)
            || f.itemsSinImei.any((p) => p.modelo == _modeloFiltro);
        if (!tieneModelo) return false;
      }
      return true;
    }).toList();
  }

  /// Marcas únicas en el catálogo global (ordenadas).
  List<String> get _marcasDisponibles {
    final set = catalogoGlobal
        .map((p) => p.marca)
        .where((m) => m.isNotEmpty && m != 'Genérico')
        .toSet();
    return set.toList()..sort();
  }

  /// Modelos disponibles. Si hay marca elegida, filtra por esa marca.
  List<String> get _modelosDisponibles {
    final filtrados = _marcaFiltro == null
        ? catalogoGlobal
        : catalogoGlobal.where((p) => p.marca == _marcaFiltro);
    final set = filtrados
        .map((p) => p.modelo)
        .where((m) => m.isNotEmpty && m != 'N/A')
        .toSet();
    return set.toList()..sort();
  }

  /// Lista única de vendedores conocidos en ventasGlobal (para el dropdown).
  List<String> get _vendedoresDisponibles {
    final set = ventasGlobal.map((f) => f.vendedor).toSet();
    final lista = set.toList()..sort();
    return lista;
  }

  /// Lista única de métodos de pago.
  List<String> get _metodosPagoDisponibles {
    final set = <String>{};
    for (final f in ventasGlobal) {
      for (final p in f.pagos) { set.add(p.metodo); }
    }
    final lista = set.toList()..sort();
    return lista;
  }

  /// Devuelve el precio al que se VENDIÓ realmente el producto en una
  /// factura, según el método/financiadora con el que se pagó.
  ///
  /// Cómo funciona:
  ///  · Si la factura tiene un pago con financiadora (Cashea/Weppa/Krece),
  ///    busca el producto en `listasPreciosGlobal` filtrando por esa
  ///    financiadora y devuelve el precio de esa lista (que ya incluye
  ///    el % adicional configurado por el dueño).
  ///  · Si NO hay financiadora (venta de contado normal en divisas/Bs),
  ///    devuelve el `precioVenta` estándar del producto.
  ///
  /// Esto hace que la ganancia del vendedor refleje el dinero real que
  /// entró a la tienda — un teléfono vendido por Cashea tiene un precio
  /// distinto al mismo teléfono vendido en divisas.
  double _precioRealVenta(FacturaModel factura, Producto producto) {
    // ¿Tiene la factura un pago con financiadora?
    String? finUsada;
    for (final p in factura.pagos) {
      final f = (p.financiadora ?? '').trim();
      if (f.isNotEmpty) { finUsada = f; break; }
    }
    if (finUsada != null) {
      // Buscar en las listas globales el precio para esa financiadora
      final normFin = finUsada.toLowerCase().trim();
      final codNorm = producto.codigo.toLowerCase().trim();
      for (final lp in listasPreciosGlobal) {
        final lpFin = (lp.financiadora ?? '').toLowerCase().trim();
        if (lpFin.isEmpty) continue;
        if (!lpFin.contains(normFin) && !normFin.contains(lpFin)) continue;
        for (final item in lp.items) {
          if (item.producto.codigo.toLowerCase().trim() != codNorm) continue;
          if (item.preciosPorColumna.isEmpty) continue;
          // Tomamos el primer precio que no sea un override interno
          for (final entry in item.preciosPorColumna.entries) {
            if (entry.key.startsWith('__')) continue;
            return entry.value;
          }
        }
      }
    }
    // Sin financiadora → precio de venta estándar del producto
    return producto.precioVenta;
  }

  /// Resumen por vendedor con desglose completo de cobros.
  ///
  /// Para cada vendedor calcula:
  ///   · facturas:        número de facturas emitidas
  ///   · productos:       unidades vendidas (equipos + items)
  ///   · total:           total facturado en USD (suma de los totales)
  ///   · ganancia:        ganancia bruta (precio venta − precio costo) en USD
  ///   · cobradoEnBs:     monto que se cobró en pago móvil / punto de venta /
  ///                      efectivo Bs / transferencia (en bolívares, sumando
  ///                      sólo los pagos cuyo método está en _metodosEnBolivares)
  ///   · cobradoEnDivisas:monto cobrado en divisas (Zelle, Binance, Cash $, etc)
  ///   · cobradoBsEnUsd:  cobradoEnBs convertido a divisas usando la
  ///                      tasa Binance del día. Si el dueño no ha
  ///                      configurado tasaBinance, se usa tasaCambio (BCV).
  ///   · ingresoTotalUsd: cobradoEnDivisas + cobradoBsEnUsd
  ///                      → cuánto representa REALMENTE el vendedor en $
  Map<String, Map<String, dynamic>> get _resumenPorVendedor {
    // Tasa a usar para convertir Bs → $. Prioridad:
    //   1. Tasa Binance configurada por el dueño (valor real de mercado)
    //   2. Tasa BCV oficial (si Binance no está configurada)
    final tasaConversion = ConfigSistema.tasaBinance > 0
        ? ConfigSistema.tasaBinance
        : (ConfigSistema.tasaCambio > 0 ? ConfigSistema.tasaCambio : 1.0);

    final r = <String, Map<String, dynamic>>{};
    // Cache de números de factura por vendedor (Set para no duplicar)
    final Map<String, Set<String>> facturasPorVendedor = {};

    for (final f in _facturasFiltradas) {
      // ── Helper: garantizar entrada para un vendedor ──
      Map<String, dynamic> entradaVendedor(String nombre) {
        return r.putIfAbsent(nombre, () => {
          'facturas': 0,
          'total': 0.0,
          'productos': 0,
          'ganancia': 0.0,
          'costo': 0.0,
          'ventaReal': 0.0,
          'cobradoEnBs': 0.0,
          'cobradoEnDivisas': 0.0,
          'cobradoBsEnUsd': 0.0,
          'ingresoTotalUsd': 0.0,
        });
      }

      // ── Recorrer cada equipo atribuyendo al vendedor del producto ──
      // Si vendedorPorImei[imei] está vacío, cae al creador (f.vendedor).
      for (final eq in f.equipos) {
        final vendedorProd = f.vendedorDeEquipo(eq.imei);
        final v = entradaVendedor(vendedorProd);
        v['productos'] = (v['productos'] as int) + 1;
        final precioReal = _precioRealVenta(f, eq.producto);
        v['ganancia']  = (v['ganancia']  as double)
            + (precioReal - eq.producto.precioCosto);
        v['costo']     = (v['costo']     as double) + eq.producto.precioCosto;
        v['ventaReal'] = (v['ventaReal'] as double) + precioReal;
        // Esta factura cuenta para este vendedor
        facturasPorVendedor
            .putIfAbsent(vendedorProd, () => {})
            .add(f.nroFactura);
      }
      for (final p in f.itemsSinImei) {
        final vendedorProd = f.vendedorDeItem(p.codigo);
        final v = entradaVendedor(vendedorProd);
        v['productos'] = (v['productos'] as int) + 1;
        final precioReal = _precioRealVenta(f, p);
        v['ganancia']  = (v['ganancia']  as double)
            + (precioReal - p.precioCosto);
        v['costo']     = (v['costo']     as double) + p.precioCosto;
        v['ventaReal'] = (v['ventaReal'] as double) + precioReal;
        facturasPorVendedor
            .putIfAbsent(vendedorProd, () => {})
            .add(f.nroFactura);
      }

      // ── Cobros por moneda: se atribuyen al CREADOR de la factura ──
      // porque el cobro lo recibe quien factura (caja). Si una factura no
      // tiene equipos pero sí pagos, igualmente queda el creador asociado.
      final vCreador = entradaVendedor(f.vendedor);
      // Total en $ equivalentes (Bs convertidos con la tasa del pago).
      // `f.total` suma Bs con $ y daba montos como "$100.000".
      vCreador['total'] = (vCreador['total'] as double) + _totalFacturaUsd(f);
      facturasPorVendedor
          .putIfAbsent(f.vendedor, () => {})
          .add(f.nroFactura);

      // Desglose de cobros por moneda real del pago.
      // Si el método está en _metodosEnBolivares (Pago Móvil, Punto de venta,
      // Efectivo Bs, Transferencia), el monto está en bolívares.
      // Si no, está en divisas.
      for (final pago in f.pagos) {
        if (esMetodoEnBolivares(pago.metodo)) {
          vCreador['cobradoEnBs'] = (vCreador['cobradoEnBs'] as double) + pago.monto;
        } else {
          vCreador['cobradoEnDivisas'] = (vCreador['cobradoEnDivisas'] as double) + pago.monto;
        }
      }
    }

    // ── Asignar conteo de facturas únicas por vendedor ──
    facturasPorVendedor.forEach((vendedor, setFacturas) {
      final datos = r[vendedor];
      if (datos != null) datos['facturas'] = setFacturas.length;
    });

    // Calcular las conversiones después del loop (más eficiente)
    r.forEach((vendedor, datos) {
      final bs = datos['cobradoEnBs'] as double;
      final usd = datos['cobradoEnDivisas'] as double;
      final bsEnUsd = tasaConversion > 0 ? bs / tasaConversion : 0.0;
      datos['cobradoBsEnUsd'] = bsEnUsd;
      datos['ingresoTotalUsd'] = usd + bsEnUsd;
    });

    return r;
  }

  /// Total general (todas las ventas filtradas).
  double get _totalGeneral =>
      _facturasFiltradas.fold(0.0, (s, f) => s + _totalFacturaUsd(f));

  /// Total cobrado de una factura en $ (pagos en Bs convertidos con la
  /// tasa histórica de cada pago, o la actual si no la tienen).
  double _totalFacturaUsd(FacturaModel f) =>
      totalesPagosPorMoneda(f.pagos.map((p) => p.toMap())).equivUsd;

  /// Ganancia general usando el precio REAL al que se vendió cada
  /// producto (según financiadora si aplica). Refleja el dinero real
  /// que entra a la tienda.
  double get _gananciaGeneral {
    double total = 0.0;
    for (final f in _facturasFiltradas) {
      for (final eq in f.equipos) {
        final precioReal = _precioRealVenta(f, eq.producto);
        total += (precioReal - eq.producto.precioCosto);
      }
      for (final p in f.itemsSinImei) {
        final precioReal = _precioRealVenta(f, p);
        total += (precioReal - p.precioCosto);
      }
    }
    return total;
  }

  /// Cada producto vendido con su factura/vendedor (para la pestaña de detalle).
  /// Estructura plana: una fila por producto vendido.
  List<Map<String, dynamic>> get _detallePlano {
    final filas = <Map<String, dynamic>>[];
    for (final f in _facturasFiltradas) {
      // Equipos con IMEI - atribuir al vendedor del equipo
      for (final eq in f.equipos) {
        filas.add({
          'vendedor' : f.vendedorDeEquipo(eq.imei),
          'creador'  : f.vendedor,
          'tienda'   : f.tienda,
          'fecha'    : f.fecha,
          'cliente'  : f.cliente,
          'cedula'   : f.cedula,
          'nroFact'  : f.nroFactura,
          'tipo'     : 'IMEI',
          'codigo'   : eq.producto.codigo,
          'nombre'   : eq.producto.nombre,
          'marca'    : eq.producto.marca,
          'modelo'   : eq.producto.modelo,
          'imei'     : eq.imei,
          'precio'   : eq.producto.precioVenta,
          'costo'    : eq.producto.precioCosto,
        });
      }
      // Items sin IMEI - atribuir al vendedor del item
      for (final p in f.itemsSinImei) {
        filas.add({
          'vendedor' : f.vendedorDeItem(p.codigo),
          'creador'  : f.vendedor,
          'tienda'   : f.tienda,
          'fecha'    : f.fecha,
          'cliente'  : f.cliente,
          'cedula'   : f.cedula,
          'nroFact'  : f.nroFactura,
          'tipo'     : 'SIN-IMEI',
          'codigo'   : p.codigo,
          'nombre'   : p.nombre,
          'marca'    : p.marca,
          'modelo'   : p.modelo,
          'imei'     : '',
          'precio'   : p.precioVenta,
          'costo'    : p.precioCosto,
        });
      }
    }
    // Ordenar: vendedor → fecha desc → nro factura
    filas.sort((a, b) {
      final c1 = (a['vendedor'] as String).compareTo(b['vendedor'] as String);
      if (c1 != 0) return c1;
      return (b['fecha'] as String).compareTo(a['fecha'] as String);
    });
    return filas;
  }

  // ─────────────────────────────────────────────────────────────
  //  EXPORTACIÓN
  // ─────────────────────────────────────────────────────────────

  /// Exporta el reporte completo como una IMAGEN PNG compacta y
  /// agrupada, lista para compartir por WhatsApp / redes sociales.
  ///
  /// Estructura de la imagen:
  ///   1) Encabezado con logo, nombre de empresa y rango de fechas
  ///   2) Tarjetas de totales (Ventas, Ganancia, Facturas, Productos)
  ///   3) Tabla resumen por vendedor con medallas para top 3
  ///   4) Footer con marca de generación
  Future<void> _exportarImagen() async {
    if (!mounted) return;
    final resumen = _resumenPorVendedor;
    if (resumen.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text('No hay datos para exportar'),
        backgroundColor: Colors.orange));
      return;
    }

    final boundaryKey = GlobalKey();
    const anchoImg = 900.0;

    // Mostrar overlay
    showDialog<void>(
      context: context,
      barrierDismissible: false,
      builder: (ctx) => Dialog(
        backgroundColor: Colors.transparent,
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          const Card(
            child: Padding(
              padding: EdgeInsets.all(20),
              child: Column(mainAxisSize: MainAxisSize.min, children: [
                CircularProgressIndicator(),
                SizedBox(height: 12),
                Text("Generando imagen…"),
              ]),
            ),
          ),
          // Widget que se renderiza off-screen
          Offstage(
            offstage: false,
            child: RepaintBoundary(
              key: boundaryKey,
              child: _buildWidgetReporteImagen(anchoImg),
            ),
          ),
        ]),
      ),
    );

    await Future.delayed(const Duration(milliseconds: 500));

    try {
      final boundary = boundaryKey.currentContext?.findRenderObject()
          as RenderRepaintBoundary?;
      if (boundary == null) throw Exception("No se pudo renderizar");
      final image = await boundary.toImage(pixelRatio: 3.0);
      final byteData =
          await image.toByteData(format: ImageByteFormat.png);
      if (byteData == null) throw Exception("No se pudo convertir a PNG");
      final pngBytes = byteData.buffer.asUint8List();

      if (mounted) Navigator.of(context, rootNavigator: true).pop();

      final dir = await getTemporaryDirectory();
      final ts = DateTime.now().millisecondsSinceEpoch;
      final fileName = 'reporte_vendedor_$ts.png';
      final file = File('${dir.path}/$fileName');
      await file.writeAsBytes(pngBytes);

      if (mounted) {
        await SharePlus.instance.share(ShareParams(
          files: [XFile(file.path)],
          text: 'Reporte de Ventas',
        ));
      }
    } catch (e) {
      debugPrint('[Reporte._exportarImagen] error: $e');
      if (mounted) {
        Navigator.of(context, rootNavigator: true).pop();
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text('Error generando imagen: $e'),
          backgroundColor: Colors.red));
      }
    }
  }

  /// Construye el widget compacto del reporte para imagen.
  Widget _buildWidgetReporteImagen(double ancho) {
    final resumen = _resumenPorVendedor;
    // Ordenar vendedores por total de ventas descendente
    final vendedoresOrdenados = resumen.entries.toList()
      ..sort((a, b) => ((b.value['total'] as num?) ?? 0)
          .compareTo((a.value['total'] as num?) ?? 0));
    final tienda = usuarioSesion?.tienda ?? '';
    final enc = ConfigSistema.encabezadoDe(tienda);

    String fmtMoneda(double v) =>
        '\$${v.toStringAsFixed(2).replaceAllMapped(
          RegExp(r'(\d)(?=(\d{3})+\.)'),
          (m) => '${m[1]},')}';

    return Material(
      color: Colors.white,
      child: Container(
        width: ancho,
        color: Colors.white,
        child: Column(crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
          // ── Encabezado ──
          Container(
            padding: const EdgeInsets.all(20),
            decoration: const BoxDecoration(
              gradient: LinearGradient(
                colors: [AppColors.royalBlue, AppColors.primaryBlue],
                begin: Alignment.topLeft,
                end: Alignment.bottomRight),
            ),
            child: Row(children: [
              if (enc.logoBytes != null)
                Container(
                  width: 70, height: 70,
                  margin: const EdgeInsets.only(right: 14),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(12)),
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(11),
                    child: Image.memory(enc.logoBytes!, fit: BoxFit.contain),
                  ),
                ),
              Expanded(child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      ConfigSistema.nombreEmpresa.isEmpty
                          ? tienda
                          : ConfigSistema.nombreEmpresa,
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 22,
                          fontWeight: FontWeight.bold)),
                    const SizedBox(height: 2),
                    const Text('REPORTE DE VENTAS POR VENDEDOR',
                        style: TextStyle(
                            color: Colors.white,
                            fontSize: 13,
                            letterSpacing: 1.5,
                            fontWeight: FontWeight.w600)),
                    const SizedBox(height: 6),
                    Text(
                        'Periodo: '
                        '${_desde != null ? _ymd(_desde!) : "—"} '
                        ' a  '
                        '${_hasta != null ? _ymd(_hasta!) : "—"}',
                        style: const TextStyle(
                            color: Colors.white70, fontSize: 12)),
                  ])),
            ]),
          ),

          // ── Tarjetas de totales ──
          Padding(
            padding: const EdgeInsets.all(16),
            child: Row(children: [
              Expanded(child: _tarjetaTotalImg(
                  'Ventas Totales',
                  fmtMoneda(_totalGeneral),
                  Icons.attach_money,
                  AppColors.statusGreen)),
              const SizedBox(width: 10),
              Expanded(child: _tarjetaTotalImg(
                  'Ganancia',
                  fmtMoneda(_gananciaGeneral),
                  Icons.trending_up,
                  AppColors.royalBlue)),
              const SizedBox(width: 10),
              Expanded(child: _tarjetaTotalImg(
                  'Facturas',
                  '${_facturasFiltradas.length}',
                  Icons.receipt_long,
                  AppColors.statusOrange)),
              const SizedBox(width: 10),
              Expanded(child: _tarjetaTotalImg(
                  'Productos',
                  '${_detallePlano.length}',
                  Icons.inventory_2,
                  Colors.purple)),
            ]),
          ),

          // ── Tabla por vendedor ──
          Container(
            margin: const EdgeInsets.symmetric(horizontal: 16),
            decoration: BoxDecoration(
              border: Border.all(color: AppColors.cardBorder),
              borderRadius: BorderRadius.circular(10)),
            child: Column(children: [
              // Encabezado de tabla
              Container(
                padding: const EdgeInsets.symmetric(
                    horizontal: 14, vertical: 10),
                decoration: const BoxDecoration(
                  color: AppColors.surfaceGrey,
                  borderRadius: BorderRadius.vertical(
                      top: Radius.circular(10))),
                child: Row(children: const [
                  SizedBox(width: 30),
                  Expanded(flex: 4, child: Text('Vendedor',
                      style: TextStyle(
                          fontWeight: FontWeight.bold, fontSize: 12))),
                  Expanded(flex: 2, child: Text('Facturas',
                      textAlign: TextAlign.center,
                      style: TextStyle(
                          fontWeight: FontWeight.bold, fontSize: 12))),
                  Expanded(flex: 2, child: Text('Productos',
                      textAlign: TextAlign.center,
                      style: TextStyle(
                          fontWeight: FontWeight.bold, fontSize: 12))),
                  Expanded(flex: 3, child: Text('Ventas',
                      textAlign: TextAlign.right,
                      style: TextStyle(
                          fontWeight: FontWeight.bold, fontSize: 12))),
                  Expanded(flex: 3, child: Text('Ganancia',
                      textAlign: TextAlign.right,
                      style: TextStyle(
                          fontWeight: FontWeight.bold, fontSize: 12))),
                ]),
              ),
              // Filas de vendedores
              ...vendedoresOrdenados.asMap().entries.map((entry) {
                final idx = entry.key;
                final vendedor = entry.value.key;
                final datos = entry.value.value;
                final esPar = idx % 2 == 0;
                final medalla = idx == 0 ? '🥇'
                    : idx == 1 ? '🥈'
                    : idx == 2 ? '🥉'
                    : '';
                return Container(
                  padding: const EdgeInsets.symmetric(
                      horizontal: 14, vertical: 8),
                  decoration: BoxDecoration(
                    color: esPar ? Colors.white : Colors.grey[50],
                    border: const Border(
                        top: BorderSide(color: Color(0xFFEEEEEE))),
                  ),
                  child: Row(children: [
                    SizedBox(width: 30,
                        child: Text(medalla,
                            style: const TextStyle(fontSize: 18))),
                    Expanded(flex: 4, child: Text(vendedor,
                        style: const TextStyle(
                            fontWeight: FontWeight.w600, fontSize: 12),
                        maxLines: 1, overflow: TextOverflow.ellipsis)),
                    Expanded(flex: 2, child: Text(
                        '${datos['facturas'] ?? 0}',
                        textAlign: TextAlign.center,
                        style: const TextStyle(fontSize: 12))),
                    Expanded(flex: 2, child: Text(
                        '${datos['productos'] ?? 0}',
                        textAlign: TextAlign.center,
                        style: const TextStyle(fontSize: 12))),
                    Expanded(flex: 3, child: Text(
                        fmtMoneda(((datos['total'] as num?) ?? 0).toDouble()),
                        textAlign: TextAlign.right,
                        style: const TextStyle(
                            fontSize: 12, fontWeight: FontWeight.bold))),
                    Expanded(flex: 3, child: Text(
                        fmtMoneda(((datos['ganancia'] as num?) ?? 0).toDouble()),
                        textAlign: TextAlign.right,
                        style: const TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.bold,
                            color: AppColors.statusGreen))),
                  ]),
                );
              }),
              // Fila TOTAL
              Container(
                padding: const EdgeInsets.symmetric(
                    horizontal: 14, vertical: 10),
                decoration: BoxDecoration(
                  color: AppColors.royalBlue.withValues(alpha: 0.08),
                  borderRadius: const BorderRadius.vertical(
                      bottom: Radius.circular(10)),
                  border: const Border(
                      top: BorderSide(color: AppColors.royalBlue, width: 1.5)),
                ),
                child: Row(children: [
                  const SizedBox(width: 30),
                  const Expanded(flex: 4, child: Text('TOTAL GENERAL',
                      style: TextStyle(
                          fontWeight: FontWeight.bold,
                          fontSize: 13,
                          color: AppColors.royalBlue))),
                  const Expanded(flex: 2, child: SizedBox()),
                  const Expanded(flex: 2, child: SizedBox()),
                  Expanded(flex: 3, child: Text(
                      fmtMoneda(_totalGeneral),
                      textAlign: TextAlign.right,
                      style: const TextStyle(
                          fontSize: 13,
                          fontWeight: FontWeight.bold,
                          color: AppColors.royalBlue))),
                  Expanded(flex: 3, child: Text(
                      fmtMoneda(_gananciaGeneral),
                      textAlign: TextAlign.right,
                      style: const TextStyle(
                          fontSize: 13,
                          fontWeight: FontWeight.bold,
                          color: AppColors.statusGreen))),
                ]),
              ),
            ]),
          ),
          // ── Pie ──
          Padding(
            padding: const EdgeInsets.all(16),
            child: Center(child: Text(
              'Generado el ${_formatoFechaCompleta(DateTime.now())}',
              style: const TextStyle(
                  fontSize: 10,
                  fontStyle: FontStyle.italic,
                  color: AppColors.textSecondary))),
          ),
        ]),
      ),
    );
  }

