  Future<void> _exportarExcel() async {
    try {
      final excel = Excel.createExcel();
      excel.delete('Sheet1');

      // ════════════════════════════════════════════════════════════
      //  HOJA ÚNICA: una fila por EQUIPO vendido
      //  Cada fila tiene TODOS los datos en columnas alineadas:
      //  factura, vendedor, cliente, equipo, tipo de venta,
      //  financiadora, precios de lista, inicial, cuotas, comisión,
      //  total pagado, métodos, ganancia.
      // ════════════════════════════════════════════════════════════
      final s = excel['Reporte de Ventas'];

      // ── Encabezado superior (3 filas informativas) ──
      s.appendRow(_filaCeldas(['REPORTE DE VENTAS — TECNO LÍDER']));
      s.appendRow(_filaCeldas([
        'Periodo: ${_desde != null ? _ymd(_desde!) : "-"} a '
        '${_hasta != null ? _ymd(_hasta!) : "-"}',
      ]));
      s.appendRow(_filaCeldas([
        'Generado: ${_formatoFechaCompleta(DateTime.now())}',
      ]));
      s.appendRow(_filaCeldas([])); // separador

      // ── Resumen rápido (KPIs en una sola fila) ──
      s.appendRow(_filaCeldas([
        'Total Facturas', 'Total Equipos',
        'Total Ventas USD', 'Ganancia Total USD',
      ]));
      s.appendRow(_filaCeldas([
        _facturasFiltradas.length,
        _detallePlano.length,
        _totalGeneral,
        _gananciaGeneral,
      ]));
      s.appendRow(_filaCeldas([])); // separador

      // ── Encabezados de la tabla principal ──
      // ÉSTAS son las 21 columnas que pediste, una por una.
      s.appendRow(_filaCeldas([
        'Fecha',              // 1
        'Nro Factura',        // 2
        'Vendedor',           // 3
        'Tienda',             // 4
        'Cliente',            // 5
        'Cédula',             // 6
        'Marca',              // 7
        'Modelo',             // 8
        'IMEI',               // 9
        'Código',             // 10
        'Tipo Venta',         // 11
        'Financiadora',       // 12
        'Precio Lista USD',   // 13
        'Inicial Lista USD',  // 14
        'Inicial Pagada USD', // 15
        'N° Cuotas',          // 16
        'Cuota USD',          // 17
        'Métodos de Pago',    // 18
        'Monto Renglón USD',  // 19 (lo cobrado por este producto)
        'Costo USD',          // 20
        'Ganancia USD',       // 21
      ]));

      // ── Una fila por equipo vendido ──
      // Recorremos todas las facturas filtradas. Por cada equipo
      // (con o sin IMEI) creamos UNA fila con todos los datos.
      double totalVentas = 0;
      double totalGanancia = 0;
      int totalEquipos = 0;

      for (final f in _facturasFiltradas) {
        // Determinar tipo de venta y financiadora a nivel factura
        // Una factura es "Financiada" si alguno de sus pagos tiene
        // un nombre de financiadora asociado (Cashea/Weppa/Krece/etc.)
        String? financiadora;
        for (final p in f.pagos) {
          if (p.financiadora != null && p.financiadora!.isNotEmpty) {
            financiadora = p.financiadora;
            break;
          }
        }
        final esFinanciada = financiadora != null;
        final tipoVenta = esFinanciada ? 'Financiado' : 'Contado';

        // Buscar la lista de precios que corresponde a la financiadora
        // (si la venta fue financiada) para obtener % inicial, n° cuotas
        ListaPrecio? listaFinanc;
        if (esFinanciada) {
          try {
            listaFinanc = listasPreciosGlobal.firstWhere((l) =>
                l.esFinanciamiento &&
                (l.financiadora ?? '').toLowerCase() ==
                    financiadora!.toLowerCase());
          } catch (_) {
            listaFinanc = null;
          }
        }

        // Métodos de pago concatenados (ej: "Efectivo, Pago Móvil")
        final metodos = f.pagos.map((p) => p.metodo).toSet().join(', ');
        // Inicial pagada = suma de pagos al contado (no financiados)
        // En facturas financiadas, la "inicial pagada" es lo que el
        // cliente entregó por adelantado.
        // CORRECCIÓN: antes cada renglón repetía la inicial y el total de
        // TODA la factura (teléfono con inicial $50 + vidrio $4 → $54 en
        // los dos renglones) y además sumaba Bs con $. Ahora lo cobrado
        // (en $) se reparte entre los renglones: el accesorio lleva su
        // precio y el equipo financiado la inicial que le corresponde.
        final renglonesFin = <bool>[
          for (final _ in f.equipos) esFinanciada,
          for (final _ in f.itemsSinImei) esFinanciada && f.equipos.isEmpty,
        ];
        final montosRenglon = repartirCobroEntreRenglones(
          precios: [
            for (final eq in f.equipos) eq.producto.precioVenta,
            for (final p in f.itemsSinImei) p.precioVenta,
          ],
          financiados: renglonesFin,
          cobradoUsd: _totalFacturaUsd(f),
        );
        var idxRenglon = 0;

        // ── EQUIPOS CON IMEI ──
        for (final eq in f.equipos) {
          final p = eq.producto;
          // Buscar precio en la lista de financiadora (si aplica)
          double precioLista = p.precioVenta;
          double inicialLista = 0;
          double cuotaLista = 0;
          int nCuotas = 0;
          if (listaFinanc != null) {
            try {
              final item = listaFinanc.items.firstWhere(
                  (it) => it.producto.codigo == p.codigo);
              final colKey = listaFinanc.columnas.isNotEmpty
                  ? listaFinanc.columnas.first.nombre : '';
              precioLista = item.preciosPorColumna[colKey] ?? p.precioVenta;
              // Condiciones del producto (pueden ser propias de su
              // marca o modelo dentro de la misma lista).
              inicialLista = listaFinanc.inicialDe(item, precioLista);
              nCuotas = listaFinanc.cuotasDe(item);
              if (listaFinanc.tieneCuotas && nCuotas > 0) {
                cuotaLista = listaFinanc.cuotaDe(item, precioLista);
              }
            } catch (_) {}
          }
          final ganancia = precioLista - p.precioCosto;
          totalVentas += precioLista;
          totalGanancia += ganancia;
          totalEquipos++;
          s.appendRow(_filaCeldas([
            f.fecha,
            f.nroFactura,
            f.vendedor,
            f.tienda,
            f.cliente,
            f.cedula,
            p.marca,
            p.modelo,
            eq.imei,
            p.codigo,
            tipoVenta,
            financiadora ?? '',
            precioLista,
            inicialLista,
            // Inicial de ESTE renglón (sólo si es el financiado).
            renglonesFin[idxRenglon] ? montosRenglon[idxRenglon] : '',
            nCuotas == 0 ? '' : nCuotas,
            cuotaLista == 0 ? '' : cuotaLista,
            metodos,
            // Monto cobrado por ESTE renglón, no el total de la factura.
            montosRenglon[idxRenglon++],
            p.precioCosto,
            ganancia,
          ]));
        }

        // ── ITEMS SIN IMEI (accesorios, servicios) ──
        for (final p in f.itemsSinImei) {
          double precioLista = p.precioVenta;
          double inicialLista = 0;
          double cuotaLista = 0;
          int nCuotas = 0;
          if (listaFinanc != null) {
            try {
              final item = listaFinanc.items.firstWhere(
                  (it) => it.producto.codigo == p.codigo);
              final colKey = listaFinanc.columnas.isNotEmpty
                  ? listaFinanc.columnas.first.nombre : '';
              precioLista = item.preciosPorColumna[colKey] ?? p.precioVenta;
              // Condiciones del producto (pueden ser propias de su
              // marca o modelo dentro de la misma lista).
              inicialLista = listaFinanc.inicialDe(item, precioLista);
              nCuotas = listaFinanc.cuotasDe(item);
              if (listaFinanc.tieneCuotas && nCuotas > 0) {
                cuotaLista = listaFinanc.cuotaDe(item, precioLista);
              }
            } catch (_) {}
          }
          final ganancia = precioLista - p.precioCosto;
          totalVentas += precioLista;
          totalGanancia += ganancia;
          totalEquipos++;
          s.appendRow(_filaCeldas([
            f.fecha,
            f.nroFactura,
            f.vendedor,
            f.tienda,
            f.cliente,
            f.cedula,
            p.marca,
            p.modelo,
            '', // sin IMEI
            p.codigo,
            tipoVenta,
            financiadora ?? '',
            precioLista,
            inicialLista,
            // Inicial de ESTE renglón (sólo si es el financiado).
            renglonesFin[idxRenglon] ? montosRenglon[idxRenglon] : '',
            nCuotas == 0 ? '' : nCuotas,
            cuotaLista == 0 ? '' : cuotaLista,
            metodos,
            // Monto cobrado por ESTE renglón, no el total de la factura.
            montosRenglon[idxRenglon++],
            p.precioCosto,
            ganancia,
          ]));
        }
      }

      // ── Fila final de totales (alineada con las columnas) ──
      s.appendRow(_filaCeldas([])); // separador
      s.appendRow(_filaCeldas([
        'TOTAL', '', '', '', '', '', '', '', '', '',
        '$totalEquipos equipos', '',
        totalVentas, '', '', '', '',
        '', '', '', totalGanancia,
      ]));

      // ── Generar y descargar ──
      final bytes = excel.encode();
      if (bytes == null) throw 'No se pudo generar el archivo';
      final ts = DateTime.now().millisecondsSinceEpoch;
      await descargarArchivo(
        Uint8List.fromList(bytes),
        'reporte_vendedor_$ts.xlsx',
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      );
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text('✅ Excel generado correctamente'),
        backgroundColor: AppColors.statusGreen));
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Error al exportar Excel: $e'),
          backgroundColor: AppColors.statusRed));
    }
  }

  Future<void> _exportarPDF() async {
    try {
      final pdf = pw.Document();
      final fmt = pw.TextStyle(fontSize: 9);
      final bold = pw.TextStyle(fontSize: 9, fontWeight: pw.FontWeight.bold);

      pdf.addPage(pw.MultiPage(
        pageFormat: PdfPageFormat.a4,
        margin: const pw.EdgeInsets.all(28),
        build: (ctx) => [
          // ── Encabezado ──
          pw.Container(
            padding: const pw.EdgeInsets.all(10),
            decoration: pw.BoxDecoration(
              color: PdfColor.fromInt(0xFF2E3192),
              borderRadius: pw.BorderRadius.circular(6),
            ),
            child: pw.Column(crossAxisAlignment: pw.CrossAxisAlignment.start, children: [
              pw.Text('REPORTE POR VENDEDOR — TECNO LÍDER',
                style: pw.TextStyle(fontSize: 14, fontWeight: pw.FontWeight.bold, color: PdfColors.white)),
              pw.SizedBox(height: 4),
              pw.Text(
                'Periodo: ${_desde != null ? _ymd(_desde!) : "-"} a ${_hasta != null ? _ymd(_hasta!) : "-"}',
                style: const pw.TextStyle(fontSize: 10, color: PdfColors.white)),
              if (_vendedorFiltro != null) pw.Text('Vendedor: $_vendedorFiltro',
                style: const pw.TextStyle(fontSize: 10, color: PdfColors.white)),
              if (_tiendaFiltro != null) pw.Text('Tienda: $_tiendaFiltro',
                style: const pw.TextStyle(fontSize: 10, color: PdfColors.white)),
              if (_metodoPagoFiltro != null) pw.Text('Método de pago: $_metodoPagoFiltro',
                style: const pw.TextStyle(fontSize: 10, color: PdfColors.white)),
            ]),
          ),
          pw.SizedBox(height: 16),

          // ── Resumen por vendedor ──
          pw.Text('Resumen por Vendedor',
            style: pw.TextStyle(fontSize: 12, fontWeight: pw.FontWeight.bold)),
          pw.SizedBox(height: 6),
          pw.Table.fromTextArray(
            headerStyle: pw.TextStyle(
                fontSize: 9, fontWeight: pw.FontWeight.bold, color: PdfColors.white),
            headerDecoration: const pw.BoxDecoration(color: PdfColor.fromInt(0xFF1F2270)),
            cellStyle: fmt,
            cellAlignment: pw.Alignment.centerLeft,
            cellAlignments: {
              1: pw.Alignment.centerRight,
              2: pw.Alignment.centerRight,
              3: pw.Alignment.centerRight,
              4: pw.Alignment.centerRight,
            },
            data: [
              ['Vendedor', 'Facturas', 'Productos', 'Total', 'Ganancia'],
              ..._resumenPorVendedor.entries.map((e) => [
                e.key,
                '${e.value['facturas']}',
                '${e.value['productos']}',
                formatCurrency(e.value['total']),
                formatCurrency(e.value['ganancia']),
              ]),
              [
                'TOTAL GENERAL', '', '',
                formatCurrency(_totalGeneral),
                formatCurrency(_gananciaGeneral),
              ],
            ],
          ),
          pw.SizedBox(height: 16),

          // ── Detalle agrupado por vendedor ──
          pw.Text('Detalle de productos vendidos por cada vendedor',
            style: pw.TextStyle(fontSize: 12, fontWeight: pw.FontWeight.bold)),
          pw.SizedBox(height: 6),
          ..._resumenPorVendedor.keys.expand((vendedor) {
            final filas = _detallePlano.where((f) => f['vendedor'] == vendedor).toList();
            return [
              pw.SizedBox(height: 8),
              pw.Container(
                padding: const pw.EdgeInsets.symmetric(horizontal: 6, vertical: 3),
                color: PdfColor.fromInt(0xFFFFC20E),
                child: pw.Text(vendedor.toUpperCase(),
                    style: pw.TextStyle(fontSize: 10, fontWeight: pw.FontWeight.bold)),
              ),
              pw.SizedBox(height: 4),
              pw.Table.fromTextArray(
                headerStyle: pw.TextStyle(fontSize: 8, fontWeight: pw.FontWeight.bold),
                cellStyle: pw.TextStyle(fontSize: 8),
                cellAlignment: pw.Alignment.centerLeft,
                cellAlignments: {6: pw.Alignment.centerRight},
                data: [
                  ['Fecha', 'Factura', 'Marca', 'Modelo', 'IMEI', 'Cliente', 'Precio'],
                  ...filas.map((f) => [
                    f['fecha'].toString().split(' ').first,
                    f['nroFact'].toString(),
                    f['marca'].toString(),
                    f['modelo'].toString(),
                    f['imei'].toString(),
                    f['cliente'].toString(),
                    formatCurrency((f['precio'] as num).toDouble()),
                  ]),
                ],
              ),
            ];
          }),
        ],
      ));

      final bytes = await pdf.save();
      final ts = DateTime.now().millisecondsSinceEpoch;
      await Printing.sharePdf(
        bytes: bytes,
        filename: 'reporte_vendedor_$ts.pdf',
      );
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text('✅ PDF generado'),
        backgroundColor: AppColors.statusGreen));
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Error al exportar PDF: $e'),
          backgroundColor: AppColors.statusRed));
    }
  }

  String _ymd(DateTime d) =>
    '${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';

  // ─────────────────────────────────────────────────────────────
  //  UI
  // ─────────────────────────────────────────────────────────────

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.surfaceTintBlue,
      appBar: AppBar(
        title: const Text('Reporte por Vendedor'),
        bottom: TabBar(
          controller: _tabCtrl,
          tabs: const [
            Tab(icon: Icon(Icons.insights_outlined), text: 'Resumen'),
            Tab(icon: Icon(Icons.list_alt_outlined), text: 'Detalle'),
          ],
        ),
        actions: [
          IconButton(
            icon: const Icon(Icons.table_chart_outlined),
            tooltip: 'Exportar Excel',
            onPressed: _facturasFiltradas.isEmpty ? null : _exportarExcel),
          // ── Exportar como IMAGEN compacta ──
          // Genera un PNG con todo el resumen agrupado para
          // compartir directamente por WhatsApp / redes.
          IconButton(
            icon: const Icon(Icons.image_outlined),
            tooltip: 'Exportar como Imagen (compacta para compartir)',
            onPressed: _facturasFiltradas.isEmpty ? null : _exportarImagen),
