        _buildFiltros(),

        // ── Contenido de las pestañas ───────────────────────────
        Expanded(child: TabBarView(
          controller: _tabCtrl,
          children: [
            _buildVistaResumen(),
            _buildVistaDetalle(),
          ],
        )),
