  Widget _buildFiltros() {
    return Container(
      padding: const EdgeInsets.all(12),
      color: Colors.white,
      child: Column(children: [
        // Fila 1: rango de fechas
        Row(children: [
          Expanded(child: _campoFecha(
            label: 'Desde',
            valor: _desde,
            onChanged: (d) => setState(() => _desde = d),
          )),
          const SizedBox(width: 10),
          Expanded(child: _campoFecha(
            label: 'Hasta',
            valor: _hasta,
            onChanged: (d) => setState(() => _hasta = d),
          )),
        ]),
        const SizedBox(height: 10),
        // Fila 2: vendedor + tienda
        Row(children: [
          Expanded(child: _dropdownFiltro(
            label: 'Vendedor',
            valor: _vendedorFiltro,
            opciones: _vendedoresDisponibles,
            onChanged: (v) => setState(() => _vendedorFiltro = v),
          )),
          const SizedBox(width: 10),
          Expanded(child: _dropdownFiltro(
            label: 'Tienda',
            valor: _tiendaFiltro,
            opciones: ConfigSistema.tiendas,
            onChanged: (v) => setState(() => _tiendaFiltro = v),
          )),
        ]),
        const SizedBox(height: 10),
        // Fila 3: método de pago
        Row(children: [
          Expanded(child: _dropdownFiltro(
            label: 'Método de pago',
            valor: _metodoPagoFiltro,
            opciones: _metodosPagoDisponibles,
            onChanged: (v) => setState(() => _metodoPagoFiltro = v),
          )),
        ]),
        const SizedBox(height: 10),
        // Fila 4: marca + modelo
        Row(children: [
          Expanded(child: _dropdownFiltro(
            label: 'Marca',
            valor: _marcaFiltro,
            opciones: _marcasDisponibles,
            onChanged: (v) => setState(() {
              _marcaFiltro = v;
              // Si cambia la marca, el modelo deja de ser válido
              if (v != null && _modeloFiltro != null
                  && !_modelosDisponibles.contains(_modeloFiltro)) {
                _modeloFiltro = null;
              }
            }),
          )),
          const SizedBox(width: 10),
          Expanded(child: _dropdownFiltro(
            label: 'Modelo',
            valor: _modeloFiltro,
            opciones: _modelosDisponibles,
            onChanged: (v) => setState(() => _modeloFiltro = v),
          )),
        ]),
        const SizedBox(height: 10),
        // Fila 5: botón limpiar
        Row(children: [
          OutlinedButton.icon(
            icon: const Icon(Icons.restart_alt, size: 16),
            label: const Text('Limpiar todos los filtros'),
            onPressed: () {
              setState(() {
                _vendedorFiltro = null;
                _tiendaFiltro = null;
                _metodoPagoFiltro = null;
                _marcaFiltro = null;
                _modeloFiltro = null;
                final now = DateTime.now();
                _desde = DateTime(now.year, now.month, 1);
                _hasta = now;
              });
            },
          ),
        ]),
        const SizedBox(height: 8),
        // Indicador de resultados
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
          decoration: BoxDecoration(
            color: AppColors.brandBlue.withValues(alpha: 0.08),
            borderRadius: BorderRadius.circular(8),
          ),
          child: Row(children: [
            const Icon(Icons.filter_alt_outlined,
                size: 16, color: AppColors.brandBlue),
            const SizedBox(width: 6),
            Text('${_facturasFiltradas.length} facturas · ${_detallePlano.length} productos',
                style: const TextStyle(
                  color: AppColors.brandBlue,
                  fontWeight: FontWeight.w600, fontSize: 12)),
            const Spacer(),
            Text(formatCurrency(_totalGeneral),
                style: const TextStyle(
                  color: AppColors.brandBlueDeeper,
                  fontWeight: FontWeight.w800, fontSize: 14)),
          ]),
        ),
      ]),
    );
  }

  Widget _campoFecha({
    required String label,
    required DateTime? valor,
    required ValueChanged<DateTime?> onChanged,
  }) {
    return InkWell(
      onTap: () async {
        final d = await showDatePicker(
          context: context,
          initialDate: valor ?? DateTime.now(),
          firstDate: DateTime(2020),
          lastDate: DateTime.now().add(const Duration(days: 1)),
        );
        if (d != null) onChanged(d);
      },
      child: InputDecorator(
        decoration: InputDecoration(
          labelText: label,
          prefixIcon: const Icon(Icons.calendar_today_outlined, size: 18),
          isDense: true,
        ),
        child: Text(valor != null ? _ymd(valor) : '—',
            style: TextStyle(
              color: valor != null ? AppColors.textPrimary : AppColors.textSecondary,
              fontWeight: FontWeight.w500,
            )),
      ),
    );
  }

  Widget _dropdownFiltro({
    required String label,
    required String? valor,
    required List<String> opciones,
    required ValueChanged<String?> onChanged,
  }) {
    return DropdownButtonFormField<String?>(
      initialValue: valor,
      decoration: InputDecoration(labelText: label, isDense: true),
      isExpanded: true,
      items: [
        const DropdownMenuItem<String?>(value: null, child: Text('Todos')),
        ...opciones.map((o) => DropdownMenuItem<String?>(
              value: o,
              child: Text(o, overflow: TextOverflow.ellipsis),
            )),
      ],
      onChanged: onChanged,
    );
  }

  Widget _buildVistaResumen() {
    final resumen = _resumenPorVendedor;
    if (resumen.isEmpty) {
      return const Center(child: Padding(
        padding: EdgeInsets.all(40),
        child: Text('Sin datos para los filtros seleccionados.',
          style: TextStyle(color: AppColors.textSecondary)),
      ));
    }
    // Tasa usada para mostrar la conversión Bs→$ (Binance preferida)
    final tasaConv = ConfigSistema.tasaBinance > 0
        ? ConfigSistema.tasaBinance
        : ConfigSistema.tasaCambio;
    final etiquetaTasa = ConfigSistema.tasaBinance > 0
        ? 'Binance'
        : 'BCV';

    // Ordenar por total descendente
    final sorted = resumen.entries.toList()
      ..sort((a, b) =>
          (b.value['total'] as double).compareTo(a.value['total'] as double));

    // Totales agregados de TODOS los vendedores filtrados
    double totalBs = 0, totalUsdDirecto = 0;
    for (final v in resumen.values) {
      totalBs += (v['cobradoEnBs'] as double);
      totalUsdDirecto += (v['cobradoEnDivisas'] as double);
    }
    final totalBsEnUsd = tasaConv > 0 ? totalBs / tasaConv : 0.0;
    final ingresoRealUsd = totalUsdDirecto + totalBsEnUsd;

    return ListView.builder(
      padding: const EdgeInsets.all(12),
      itemCount: sorted.length + 2, // +1 banner tasa, +1 card total
      itemBuilder: (ctx, i) {
        // ── Banner superior: tasa Binance editable ───────────────
        if (i == 0) {
          return Container(
            margin: const EdgeInsets.only(bottom: 12),
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              gradient: const LinearGradient(
                colors: [Color(0xFFFFF8E1), Color(0xFFFFE082)],
                begin: Alignment.centerLeft,
                end: Alignment.centerRight,
              ),
              borderRadius: BorderRadius.circular(10),
              border: Border.all(color: AppColors.brandYellowDark, width: 1),
            ),
            child: Row(children: [
              const Icon(Icons.currency_bitcoin,
                  color: Color(0xFFF7931A), size: 26),
              const SizedBox(width: 10),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Tasa $etiquetaTasa: Bs ${tasaConv.toStringAsFixed(2)} / \$',
                      style: const TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.w800,
                        color: AppColors.textPrimary,
                      ),
                    ),
                    const SizedBox(height: 2),
                    const Text(
                      'Pagos en Bs se convierten a USD por esta tasa',
                      style: TextStyle(
                        fontSize: 11,
                        color: AppColors.textSecondary,
                      ),
                    ),
                  ],
                ),
              ),
              TextButton.icon(
                onPressed: _editarTasaBinance,
                icon: const Icon(Icons.edit, size: 16),
                label: const Text('Cambiar', style: TextStyle(fontSize: 12)),
                style: TextButton.styleFrom(
                    foregroundColor: AppColors.brandBlueDark),
              ),
            ]),
          );
        }
        // ── Card del total general ───────────────────────────────
        if (i == sorted.length + 1) {
          return Card(
            color: AppColors.brandBlueDark,
            elevation: 4,
            shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(14)),
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(children: const [
                    Icon(Icons.workspace_premium,
                        color: AppColors.brandYellow, size: 28),
                    SizedBox(width: 10),
                    Text('TOTAL GENERAL',
                        style: TextStyle(
                            color: Colors.white,
                            fontWeight: FontWeight.w900,
                            fontSize: 15, letterSpacing: 1)),
                  ]),
                  const SizedBox(height: 14),
                  // Ingreso real (USD + Bs convertidos)
                  Container(
                    padding: const EdgeInsets.all(12),
                    decoration: BoxDecoration(
                      color: Colors.white.withValues(alpha: 0.10),
                      borderRadius: BorderRadius.circular(10),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text('Ingreso REAL en divisas',
                            style: TextStyle(
                                color: Colors.white70,
                                fontSize: 11,
                                letterSpacing: 0.5,
                                fontWeight: FontWeight.w600)),
                        const SizedBox(height: 4),
                        Text('\$${ingresoRealUsd.toStringAsFixed(2)}',
                            style: const TextStyle(
                                color: AppColors.brandYellow,
                                fontSize: 26,
                                fontWeight: FontWeight.w900)),
                        const SizedBox(height: 6),
                        Text(
                          '\$${totalUsdDirecto.toStringAsFixed(2)} en divisas + '
                          'Bs ${totalBs.toStringAsFixed(2)} '
                          '(≈ \$${totalBsEnUsd.toStringAsFixed(2)})',
                          style: const TextStyle(
                              color: Colors.white70, fontSize: 11),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(height: 10),
                  // Total facturado y ganancia
                  Row(children: [
                    Expanded(
                      child: _totalChip(
                        'Total facturado',
                        formatCurrency(_totalGeneral),
                        Colors.white,
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: _totalChip(
                        'Ganancia neta',
                        formatCurrency(_gananciaGeneral),
                        AppColors.statusGreen,
                      ),
                    ),
                  ]),
                ],
              ),
            ),
          );
        }
        // ── Cards de vendedores ──────────────────────────────────
        final entry = sorted[i - 1]; // -1 por el banner
        final vendedor = entry.key;
        final datos = entry.value;
        final medalla = (i - 1) == 0 ? '🥇'
            : (i - 1) == 1 ? '🥈'
            : (i - 1) == 2 ? '🥉'
            : '#$i';

        final cobradoBs   = datos['cobradoEnBs'] as double;
        final cobradoUsd  = datos['cobradoEnDivisas'] as double;
        final bsEnUsd     = datos['cobradoBsEnUsd'] as double;
        final ingresoUsd  = datos['ingresoTotalUsd'] as double;
        final ganancia    = datos['ganancia'] as double;

        return Card(
          margin: const EdgeInsets.only(bottom: 10),
          shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(12)),
          elevation: 2,
          child: Padding(
            padding: const EdgeInsets.all(14),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // Cabecera: medalla + nombre + total facturado
                Row(children: [
                  Container(
                    width: 40, height: 40,
                    decoration: BoxDecoration(
                      gradient: const LinearGradient(colors: [
                        AppColors.brandYellow, AppColors.brandYellowDark]),
                      borderRadius: BorderRadius.circular(20),
                    ),
                    alignment: Alignment.center,
                    child: Text(medalla,
                      style: const TextStyle(
                          fontSize: 16, fontWeight: FontWeight.w900)),
                  ),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(vendedor,
                            style: const TextStyle(
                                fontSize: 15,
                                fontWeight: FontWeight.w800,
                                color: AppColors.textPrimary)),
                        Text('${datos['facturas']} factura(s) · '
                            '${datos['productos']} producto(s)',
                            style: const TextStyle(
                                fontSize: 11,
                                color: AppColors.textSecondary)),
                      ],
                    ),
                  ),
                  Column(
                    crossAxisAlignment: CrossAxisAlignment.end,
                    children: [
                      const Text('Facturado',
                          style: TextStyle(
                              fontSize: 10,
                              color: AppColors.textSecondary)),
                      Text(formatCurrency(datos['total'] as double),
                          style: const TextStyle(
                              fontSize: 16,
                              fontWeight: FontWeight.w900,
                              color: AppColors.brandBlue)),
                    ],
                  ),
                ]),
                const SizedBox(height: 12),
                // ── Desglose de cobros: Bs y $ por separado ──
                Row(children: [
                  Expanded(
                    child: _bloqueCobro(
                      icono: Icons.payments,
                      colorIcon: AppColors.statusOrange,
                      titulo: 'Cobrado en Bs',
                      valor: 'Bs ${cobradoBs.toStringAsFixed(2)}',
                      subValor: '≈ \$${bsEnUsd.toStringAsFixed(2)}',
                    ),
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: _bloqueCobro(
                      icono: Icons.attach_money,
                      colorIcon: AppColors.statusGreen,
                      titulo: 'Cobrado en divisas',
                      valor: '\$${cobradoUsd.toStringAsFixed(2)}',
                      subValor: 'directo',
                    ),
                  ),
                ]),
                const SizedBox(height: 10),
                // ── Ingreso real total convertido ──
                Container(
                  padding: const EdgeInsets.symmetric(
                      horizontal: 12, vertical: 10),
                  decoration: BoxDecoration(
                    gradient: LinearGradient(
                      colors: [
                        AppColors.brandBlue.withValues(alpha: 0.08),
                        AppColors.brandBlueDark.withValues(alpha: 0.04),
                      ],
                    ),
                    borderRadius: BorderRadius.circular(8),
                    border: Border.all(
                        color: AppColors.brandBlue.withValues(alpha: 0.3),
                        width: 1),
                  ),
                  child: Row(children: [
                    const Icon(Icons.account_balance_wallet,
                        color: AppColors.brandBlueDark, size: 18),
                    const SizedBox(width: 8),
                    Text('Ingreso REAL ($etiquetaTasa)',
                        style: const TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w700,
                            color: AppColors.textPrimary)),
                    const Spacer(),
                    Text('\$${ingresoUsd.toStringAsFixed(2)}',
                        style: const TextStyle(
                            fontSize: 17,
                            fontWeight: FontWeight.w900,
                            color: AppColors.brandBlueDark)),
                  ]),
                ),
                const SizedBox(height: 8),
                // ── Ganancia ──
                Container(
                  padding: const EdgeInsets.symmetric(
                      horizontal: 12, vertical: 8),
                  decoration: BoxDecoration(
                    color: AppColors.statusGreen.withValues(alpha: 0.10),
                    borderRadius: BorderRadius.circular(8),
                    border: Border.all(
                        color: AppColors.statusGreen.withValues(alpha: 0.3),
                        width: 0.5),
                  ),
                  child: Row(children: [
                    const Icon(Icons.trending_up,
                        color: AppColors.statusGreen, size: 18),
                    const SizedBox(width: 8),
                    const Text('Ganancia generada',
