  /// Diálogo para editar la tasa Binance usada en la conversión Bs→$.
  Future<void> _editarTasaBinance() async {
    final ctrl = TextEditingController(
        text: ConfigSistema.tasaBinance > 0
            ? ConfigSistema.tasaBinance.toStringAsFixed(2)
            : '');
    final nueva = await showDialog<double>(
      context: context,
      builder: (c) => AlertDialog(
        shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(14)),
        icon: const Icon(Icons.currency_bitcoin,
            color: Color(0xFFF7931A), size: 36),
        title: const Text('Tasa Binance del día'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text(
              'Ingresa la tasa Binance actual (bolívares por dólar). '
              'Se usará para convertir cobros en Bs a divisas en este reporte.',
              style: TextStyle(fontSize: 12),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: ctrl,
              keyboardType: const TextInputType.numberWithOptions(decimal: true),
              autofocus: true,
              decoration: InputDecoration(
                prefixText: 'Bs ',
                suffixText: '/ \$',
                border: const OutlineInputBorder(),
                hintText: 'Ej: 580.50',
                helperText: 'BCV actual: ${ConfigSistema.tasaCambio.toStringAsFixed(2)}',
              ),
              style: const TextStyle(
                  fontSize: 18, fontWeight: FontWeight.bold),
            ),
          ],
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(c),
              child: const Text('Cancelar')),
          if (ConfigSistema.tasaBinance > 0)
            TextButton(
                onPressed: () => Navigator.pop(c, 0.0),
                child: const Text('Usar BCV',
                    style: TextStyle(color: AppColors.textSecondary))),
          FilledButton.icon(
            icon: const Icon(Icons.check, size: 18),
            label: const Text('Guardar'),
            onPressed: () {
              final v = double.tryParse(
                  ctrl.text.replaceAll(',', '.').trim());
              Navigator.pop(c, v);
            },
          ),
        ],
      ),
    );
    if (nueva == null) return;
    await ConfigSistema.guardarTasaBinance(nueva);
    if (mounted) {
      setState(() {}); // recalcular el reporte con la nueva tasa
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(nueva > 0
            ? 'Tasa Binance: Bs ${nueva.toStringAsFixed(2)} / \$'
            : 'Tasa cambiada a BCV (${ConfigSistema.tasaCambio.toStringAsFixed(2)})'),
        backgroundColor: AppColors.statusGreen,
      ));
    }
  }

