  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.surfaceTintBlue,
      appBar: AppBar(
        title: const Text('Reporte por Financiadora'),
        actions: [
          IconButton(
            tooltip: 'Refrescar',
            icon: const Icon(Icons.refresh),
            onPressed: _cargar),
        ],
      ),
      body: _cargando
          ? const Center(child: CircularProgressIndicator())
          : _error != null
              ? Center(child: Padding(
                  padding: const EdgeInsets.all(24),
                  child: Text('Error al cargar: $_error',
                    style: const TextStyle(color: AppColors.statusRed)),
                ))
              : _buildContenido(),
    );
  }

  Widget _buildContenido() {
    final datos = _porFinanciadora;

    return Column(children: [
      // ── Barra de filtros ──────────────────────────────────────
      Container(
        color: Colors.white,
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
        child: Row(children: [
          Expanded(child: InkWell(
            onTap: _seleccionarRango,
            borderRadius: BorderRadius.circular(8),
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
              decoration: BoxDecoration(
                color: AppColors.surfaceTintBlue,
                borderRadius: BorderRadius.circular(8),
                border: Border.all(color: AppColors.brandBlue.withValues(alpha: 0.30)),
              ),
              child: Row(children: [
                const Icon(Icons.date_range, color: AppColors.brandBlue, size: 18),
                const SizedBox(width: 8),
                Expanded(child: Text(
                  _desde == null || _hasta == null
                      ? 'Seleccionar rango'
                      : '${_desde!.day.toString().padLeft(2,'0')}/'
                        '${_desde!.month.toString().padLeft(2,'0')}/${_desde!.year}'
                        ' → ${_hasta!.day.toString().padLeft(2,'0')}/'
                        '${_hasta!.month.toString().padLeft(2,'0')}/${_hasta!.year}',
                  style: const TextStyle(
                    fontWeight: FontWeight.w600, fontSize: 13))),
              ]),
            ),
          )),
          const SizedBox(width: 8),
          IconButton(
            tooltip: 'Limpiar rango',
            icon: const Icon(Icons.clear),
            onPressed: () => setState(() {
              _desde = null;
              _hasta = null;
            }),
          ),
        ]),
      ),
      if (datos.isEmpty)
        const Expanded(child: Center(child: Padding(
          padding: EdgeInsets.all(40),
          child: Text(
            'No hay ventas con financiadora en el rango seleccionado.',
            textAlign: TextAlign.center,
            style: TextStyle(color: AppColors.textSecondary)),
        )))
      else
        Expanded(child: _buildListado(datos)),
    ]);
  }

  Widget _buildListado(Map<String, Map<String, dynamic>> datos) {
    // Totales globales
    final totalDeuda  = datos.values.fold<double>(0,
        (s, e) => s + (e['deuda_financ'] as double));
    final totalPagos   = datos.values.fold<double>(0,
        (s, e) => s + (e['pagos_recib'] as double));
    // ── Separar pendientes positivos (deuda real) de negativos (sobrepagos) ──
    // El KPI "Pendiente" muestra SOLO lo que falta cobrar.
    // El KPI "Sobrepago" muestra el total que la financiadora pagó de más
    // (en valor absoluto, para mostrarlo como dinero a devolver/aplicar).
    final totalPend    = datos.values.fold<double>(0, (s, e) {
      final p = e['pendiente'] as double;
      return p > 0 ? s + p : s;
    });
    final totalSobrepago = datos.values.fold<double>(0, (s, e) {
      final p = e['pendiente'] as double;
      return p < 0 ? s + p.abs() : s;
    });
    final haySobrepago = totalSobrepago > 0.01;

    // Ordenar: primero sobrepagos (al final), luego por pendiente desc.
    // Las financiadoras con saldo a favor van AL FINAL de la lista para
    // que las que necesitan cobro aparezcan primero.
    final sorted = datos.entries.toList()
      ..sort((a, b) => (b.value['pendiente'] as double)
          .compareTo(a.value['pendiente'] as double));

    return Column(children: [
      // ── Header con totales globales ───────────────────────────
      Container(
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 16),
        decoration: const BoxDecoration(
          gradient: LinearGradient(colors: [
            AppColors.brandBlue, AppColors.brandBlueDark]),
        ),
        child: Row(children: [
          Expanded(child: _kpiHeader('Deuda total',
              totalDeuda, AppColors.brandYellow, Icons.account_balance)),
          Container(width: 1, height: 40, color: Colors.white24),
          Expanded(child: _kpiHeader('Recibido',
              totalPagos, AppColors.statusGreen, Icons.check_circle_outline)),
          Container(width: 1, height: 40, color: Colors.white24),
          Expanded(child: _kpiHeader('Pendiente',
              totalPend, AppColors.statusOrange, Icons.pending_actions)),
          if (haySobrepago) ...[
            Container(width: 1, height: 40, color: Colors.white24),
            Expanded(child: _kpiHeader('Sobrepago',
                totalSobrepago, AppColors.statusRed, Icons.warning_amber)),
          ],
        ]),
      ),
      // ── Tarjetas por financiadora ─────────────────────────────
      Expanded(child: ListView.builder(
        padding: const EdgeInsets.all(12),
        itemCount: sorted.length,
        itemBuilder: (ctx, i) {
          final f = sorted[i];
          return _buildCardFinanciadora(f.key, f.value);
        },
      )),
    ]);
  }

  Widget _buildCardFinanciadora(String financiadora,
      Map<String, dynamic> data) {
    final precioLista = data['precio_lista'] as double;
    final inicial     = data['inicial']      as double;
    final comision    = data['comision']     as double;
    final comFormula  = (data['comision_formula'] as String?) ?? '3.5%';
    final deudaFin    = data['deuda_financ'] as double;
    final pagosRecib  = data['pagos_recib']  as double;
    final pendiente   = data['pendiente']    as double;
    final facturas    = (data['facturas'] as Set).length;
    final equipos     = (data['equipos'] as List).cast<Map<String, dynamic>>();
    // ── Estado del cobro ──
    // pendiente > 0  → falta cobrar (naranja)
    // pendiente == 0 → cobrado exacto (verde)
    // pendiente < 0  → sobrepago — la financiadora pagó MÁS de lo que
    //                  debía (rojo, hay que devolver o aplicar a crédito)
    final hayCobroExcesivo = pendiente < -0.01;
    final estaCobradoCompleto = pendiente.abs() <= 0.01;
    final colorPendiente = hayCobroExcesivo
        ? AppColors.statusRed
        : (estaCobradoCompleto
            ? AppColors.statusGreen
            : AppColors.statusOrange);
    final etiquetaPendiente = hayCobroExcesivo
        ? '= Sobrepago (devolver)'
        : '= Pendiente por cobrar';
    final pctCobrado  = deudaFin > 0
        ? (pagosRecib / deudaFin).clamp(0.0, 1.0) : 0.0;
    // Neto = Base − Inicial (antes de aplicar la comisión del 3.5%)
    final neto = (precioLista - inicial).clamp(0.0, double.infinity);

    return Card(
      margin: const EdgeInsets.only(bottom: 12),
      child: Padding(
        padding: const EdgeInsets.all(14),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // Cabecera con nombre y stats rápidos
            Row(children: [
              Container(
                width: 44, height: 44,
                decoration: BoxDecoration(
                  color: AppColors.brandBlue.withValues(alpha: 0.10),
                  borderRadius: BorderRadius.circular(12),
                ),
                child: const Icon(Icons.account_balance,
                    color: AppColors.brandBlue, size: 24),
              ),
              const SizedBox(width: 12),
              Expanded(child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(financiadora,
                    style: const TextStyle(
                      fontSize: 16,
                      fontWeight: FontWeight.w800,
                      color: AppColors.textPrimary)),
                  Text('$facturas factura(s) · ${equipos.length} equipo(s)',
                    style: const TextStyle(
                      color: AppColors.textSecondary, fontSize: 12)),
                ])),
            ]),
            const SizedBox(height: 14),
            // ── Desglose del cálculo ─────────────────────────────
            // Fórmula:  (Base − Inicial) − 3.5% = Deuda
            Container(
              padding: const EdgeInsets.all(10),
              decoration: BoxDecoration(
                color: AppColors.surfaceTintBlue,
                borderRadius: BorderRadius.circular(8),
              ),
              child: Column(children: [
                _lineaCalculo('Base (precio lista financiadora)', precioLista,
                    color: AppColors.brandBlue),
                _lineaCalculo('− Inicial cliente', inicial,
                    color: AppColors.textSecondary, prefix: '-'),
                const Divider(height: 14),
                _lineaCalculo('= Neto', neto,
                    color: AppColors.textPrimary, bold: true),
                _lineaCalculo('− Comisión financiadora ($comFormula)', comision,
                    color: AppColors.statusOrange, prefix: '-'),
                const Divider(height: 14),
                _lineaCalculo('= Deuda de la financiadora', deudaFin,
                    color: AppColors.brandBlueDark, bold: true),
                _lineaCalculo('− Pagos recibidos', pagosRecib,
                    color: AppColors.statusGreen, prefix: '-'),
                const Divider(height: 14),
                _lineaCalculo(etiquetaPendiente, pendiente,
                    color: colorPendiente,
                    bold: true),
              ]),
            ),
            const SizedBox(height: 10),
            // Barra de progreso
            ClipRRect(
              borderRadius: BorderRadius.circular(6),
              child: LinearProgressIndicator(
                value: pctCobrado,
                minHeight: 8,
                backgroundColor: AppColors.surfaceGrey,
                valueColor: AlwaysStoppedAnimation(
                  hayCobroExcesivo
                      ? AppColors.statusRed
                      : AppColors.statusGreen),
              ),
            ),
            const SizedBox(height: 4),
            Text(
              hayCobroExcesivo
                  ? '${(pctCobrado * 100).toStringAsFixed(1)}% cobrado '
                    '— sobrepago: ${formatCurrency(pendiente.abs())}'
                  : '${(pctCobrado * 100).toStringAsFixed(1)}% cobrado',
              style: TextStyle(
                color: hayCobroExcesivo
                    ? AppColors.statusRed
                    : AppColors.textSecondary,
                fontSize: 11,
                fontWeight: hayCobroExcesivo
                    ? FontWeight.bold
                    : FontWeight.normal,
              )),
            const SizedBox(height: 14),
            // ── Botones de acción ─────────────────────────────
            Wrap(spacing: 8, runSpacing: 8, children: [
              OutlinedButton.icon(
                onPressed: () => _registrarPago(financiadora),
                icon: const Icon(Icons.payments, size: 18),
                label: const Text('Registrar pago'),
                style: OutlinedButton.styleFrom(
                  foregroundColor: AppColors.brandBlue,
                  side: const BorderSide(color: AppColors.brandBlue),
                ),
              ),
              OutlinedButton.icon(
                onPressed: equipos.isEmpty
                    ? null
                    : () => _verEquiposVendidos(financiadora, equipos),
                icon: const Icon(Icons.inventory_2, size: 18),
                label: Text('Ver equipos (${equipos.length})'),
              ),
              OutlinedButton.icon(
                onPressed: equipos.isEmpty
                    ? null
                    : () => _exportarExcel(financiadora, equipos, data),
                icon: const Icon(Icons.table_chart, size: 18,
                    color: Colors.green),
                label: const Text('Excel'),
              ),
              OutlinedButton.icon(
                onPressed: equipos.isEmpty
                    ? null
                    : () => _exportarPDF(financiadora, equipos, data),
                icon: const Icon(Icons.picture_as_pdf, size: 18,
                    color: Colors.red),
                label: const Text('PDF'),
              ),
            ]),
          ],
        ),
      ),
    );
  }

  /// Línea de cálculo (etiqueta a la izquierda, monto a la derecha).
  /// El prefijo "-" se usa para mostrar restas, el "+" para sumas, "" para nada.
  Widget _lineaCalculo(String label, double valor,
      {Color color = AppColors.textPrimary,
       bool bold = false, String prefix = ''}) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 2),
      child: Row(children: [
        Expanded(child: Text(label,
          style: TextStyle(
            color: color,
            fontSize: bold ? 14 : 13,
            fontWeight: bold ? FontWeight.w800 : FontWeight.w500))),
        Text('$prefix${formatCurrency(valor)}',
          style: TextStyle(
            color: color,
            fontSize: bold ? 15 : 13,
            fontWeight: bold ? FontWeight.w900 : FontWeight.w600)),
      ]),
    );
  }

  Widget _kpiHeader(String label, double valor, Color color, IconData icon) {
    return Column(children: [
      Icon(icon, color: color, size: 22),
      const SizedBox(height: 6),
      Text(formatCurrency(valor),
        style: TextStyle(
          color: color,
          fontWeight: FontWeight.w900,
          fontSize: 14)),
      Text(label,
        style: const TextStyle(
          color: Colors.white70, fontSize: 11, letterSpacing: 0.5)),
    ]);
  }

  Widget _kpiCelda(String label, String valor, Color color) {
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Text(label,
        style: const TextStyle(
          color: AppColors.textSecondary, fontSize: 11)),
      const SizedBox(height: 2),
      Text(valor,
        style: TextStyle(
          fontWeight: FontWeight.w800,
          color: color, fontSize: 14)),
    ]);
  }
}

// ════════════════════════════════════════════════════════════════════
//                                                                  
//  VENTANA: REPORTE DE RENTABILIDAD DE SERVICIOS TÉCNICOS          
//                                                                  
// ════════════════════════════════════════════════════════════════════
//  Calcula la rentabilidad real del servicio técnico:             
//    Cobrado al cliente − Costo de repuestos = Ganancia            
//                                                                  
//  Vista en 3 pestañas:                                            
//    · POR SERVICIO (línea por línea)                              
//    · POR TÉCNICO (cuánto facturó y ganó cada técnico)            
//    · POR PERÍODO (resumen mensual)                               
// ════════════════════════════════════════════════════════════════════
class VentanaReporteRentabilidadServicios extends StatefulWidget {
  final List<ServicioTecnico> servicios;
  const VentanaReporteRentabilidadServicios({super.key, required this.servicios});
  @override
  State<VentanaReporteRentabilidadServicios> createState() =>
      _VentanaReporteRentabilidadServiciosState();
}

class _VentanaReporteRentabilidadServiciosState
    extends State<VentanaReporteRentabilidadServicios>
    with SingleTickerProviderStateMixin {
  late TabController _tabCtrl;
  DateTime? _desde;
  DateTime? _hasta;

  @override
  void initState() {
    super.initState();
    _tabCtrl = TabController(length: 3, vsync: this);
  }

  @override
  void dispose() { _tabCtrl.dispose(); super.dispose(); }

  List<ServicioTecnico> get _filtrados {
    return widget.servicios.where((s) {
      if (_desde != null && s.fecha.isBefore(_desde!)) return false;
      if (_hasta != null) {
        final fin = DateTime(_hasta!.year, _hasta!.month, _hasta!.day, 23, 59, 59);
        if (s.fecha.isAfter(fin)) return false;
      }
      return true;
    }).toList();
  }

  double get _totalCobrado    => _filtrados.fold(0, (s, x) => s + x.monto);
  double get _totalCostos     => _filtrados.fold(0, (s, x) => s + x.costoRepuestos);
  double get _totalGanancia   => _totalCobrado - _totalCostos;
  double get _margenGlobal    =>
      _totalCobrado > 0 ? (_totalGanancia / _totalCobrado * 100) : 0;

  /// Distribución de la ganancia entre la tienda y el técnico:
  ///   · 60% queda para la TIENDA (cubre gastos operativos: local,
  ///     servicios, gerencia, herramientas, garantía implícita).
  ///   · 40% es el pago del TÉCNICO por su trabajo.
  /// La fórmula NO aplica al cobrado bruto, sino a la GANANCIA neta
  /// (cobrado − costo de repuestos). Esto porque los repuestos son
  /// material que la tienda ya pagó, no es ganancia para nadie.
  static const double _pctTienda  = 0.60; // 60%
  static const double _pctTecnico = 0.40; // 40%
  double get _gananciaTienda  => _totalGanancia * _pctTienda;
  double get _gananciaTecnico => _totalGanancia * _pctTecnico;

  String _ymd(DateTime d) =>
    '${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.surfaceTintBlue,
      appBar: AppBar(
        title: const Text('Rentabilidad de Servicios'),
        bottom: TabBar(
          controller: _tabCtrl,
          isScrollable: true,
          tabAlignment: TabAlignment.start,
          tabs: const [
            Tab(icon: Icon(Icons.list_alt_outlined), text: 'Por servicio'),
            Tab(icon: Icon(Icons.engineering_outlined), text: 'Por técnico'),
            Tab(icon: Icon(Icons.calendar_month_outlined), text: 'Por mes'),
          ],
        ),
      ),
      body: Column(children: [
        // ── Filtro de fechas ──
        _buildFiltroFechas(),
        // ── Banner global ──
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
          decoration: const BoxDecoration(
            gradient: LinearGradient(colors: [
              AppColors.brandBlue, AppColors.brandBlueDark]),
          ),
          child: Row(children: [
            Expanded(child: _kpiBanner('Cobrado',
                formatCurrency(_totalCobrado), Colors.white, Icons.attach_money)),
            Container(width: 1, height: 36, color: Colors.white24),
            Expanded(child: _kpiBanner('Costo Rep.',
                formatCurrency(_totalCostos), Colors.orangeAccent, Icons.build_outlined)),
            Container(width: 1, height: 36, color: Colors.white24),
            Expanded(child: _kpiBanner('Ganancia',
                formatCurrency(_totalGanancia),
                _totalGanancia >= 0 ? AppColors.brandYellow : Colors.redAccent,
                Icons.trending_up)),
            Container(width: 1, height: 36, color: Colors.white24),
            Expanded(child: _kpiBanner('Margen',
                '${_margenGlobal.toStringAsFixed(1)}%',
                _totalGanancia >= 0 ? Colors.greenAccent : Colors.redAccent,
                Icons.percent)),
          ]),
        ),
        // ── Panel de distribución 60% Tienda / 40% Técnico ──
        Container(
          margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            gradient: const LinearGradient(
              colors: [Color(0xFFF1F8E9), Color(0xFFE8F5E9)],
            ),
            borderRadius: BorderRadius.circular(12),
            border: Border.all(
                color: AppColors.statusGreen.withValues(alpha: 0.3),
                width: 1),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(children: [
                const Icon(Icons.pie_chart_outline,
                    color: AppColors.statusGreen, size: 18),
                const SizedBox(width: 6),
                const Text(
                  'Distribución de la ganancia',
                  style: TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.w700,
                      color: AppColors.textPrimary,
                      letterSpacing: 0.3),
                ),
                const Spacer(),
                Text(
                  formatCurrency(_totalGanancia),
                  style: TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w800,
                    color: _totalGanancia >= 0
                        ? AppColors.statusGreen
                        : AppColors.statusRed,
                  ),
                ),
              ]),
              const SizedBox(height: 10),
              Row(children: [
                // 60% Tienda
                Expanded(
                  flex: 60,
                  child: Container(
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: AppColors.brandBlue.withValues(alpha: 0.10),
                      borderRadius: const BorderRadius.only(
                        topLeft: Radius.circular(8),
                        bottomLeft: Radius.circular(8),
                      ),
                      border: Border.all(
                          color: AppColors.brandBlue.withValues(alpha: 0.4),
                          width: 1),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(children: const [
                          Icon(Icons.storefront,
                              size: 14, color: AppColors.brandBlueDark),
                          SizedBox(width: 4),
                          Text('60% TIENDA',
                              style: TextStyle(
                                  fontSize: 10,
                                  fontWeight: FontWeight.w700,
                                  color: AppColors.brandBlueDark,
                                  letterSpacing: 0.5)),
                        ]),
                        const SizedBox(height: 6),
                        Text(
                          formatCurrency(_gananciaTienda),
                          style: const TextStyle(
                              fontSize: 18,
                              fontWeight: FontWeight.w900,
                              color: AppColors.brandBlueDark),
                        ),
                      ],
                    ),
                  ),
                ),
                // 40% Técnico
                Expanded(
                  flex: 40,
                  child: Container(
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: AppColors.statusOrange.withValues(alpha: 0.10),
                      borderRadius: const BorderRadius.only(
                        topRight: Radius.circular(8),
                        bottomRight: Radius.circular(8),
                      ),
                      border: Border.all(
                          color: AppColors.statusOrange.withValues(alpha: 0.4),
                          width: 1),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(children: const [
                          Icon(Icons.engineering,
                              size: 14, color: AppColors.statusOrange),
                          SizedBox(width: 4),
                          Text('40% TÉCNICO',
                              style: TextStyle(
                                  fontSize: 10,
                                  fontWeight: FontWeight.w700,
                                  color: AppColors.statusOrange,
                                  letterSpacing: 0.5)),
                        ]),
                        const SizedBox(height: 6),
                        Text(
                          formatCurrency(_gananciaTecnico),
                          style: const TextStyle(
                              fontSize: 18,
                              fontWeight: FontWeight.w900,
                              color: AppColors.statusOrange),
                        ),
                      ],
                    ),
                  ),
                ),
              ]),
            ],
          ),
        ),
        Expanded(child: TabBarView(
          controller: _tabCtrl,
          children: [
            _vistaPorServicio(),
            _vistaPorTecnico(),
            _vistaPorMes(),
          ],
        )),
      ]),
    );
  }

  Widget _buildFiltroFechas() {
    return Container(
      color: Colors.white,
      padding: const EdgeInsets.fromLTRB(12, 10, 12, 10),
      child: Row(children: [
        Expanded(child: InkWell(
          onTap: () async {
            final d = await showDatePicker(
              context: context,
              initialDate: _desde ?? DateTime.now(),
              firstDate: DateTime(2020),
              lastDate: DateTime.now().add(const Duration(days: 1)),
            );
            if (d != null) setState(() => _desde = d);
          },
          child: InputDecorator(
            decoration: const InputDecoration(
              labelText: 'Desde', isDense: true,
              prefixIcon: Icon(Icons.calendar_today_outlined, size: 16),
            ),
            child: Text(_desde != null ? _ymd(_desde!) : '—'),
          ),
        )),
        const SizedBox(width: 10),
        Expanded(child: InkWell(
          onTap: () async {
            final d = await showDatePicker(
              context: context,
              initialDate: _hasta ?? DateTime.now(),
              firstDate: DateTime(2020),
              lastDate: DateTime.now().add(const Duration(days: 1)),
            );
            if (d != null) setState(() => _hasta = d);
          },
          child: InputDecorator(
            decoration: const InputDecoration(
              labelText: 'Hasta', isDense: true,
              prefixIcon: Icon(Icons.calendar_today_outlined, size: 16),
            ),
            child: Text(_hasta != null ? _ymd(_hasta!) : '—'),
          ),
        )),
        const SizedBox(width: 8),
        IconButton(
          icon: const Icon(Icons.restart_alt),
          tooltip: 'Limpiar fechas',
          onPressed: () => setState(() { _desde = null; _hasta = null; }),
        ),
      ]),
    );
  }

  Widget _kpiBanner(String label, String valor, Color color, IconData icon) {
    return Column(children: [
      Icon(icon, color: color, size: 18),
      const SizedBox(height: 4),
      Text(valor,
        style: TextStyle(
          color: color, fontWeight: FontWeight.w900, fontSize: 13)),
      Text(label,
        style: const TextStyle(
          color: Colors.white70, fontSize: 10, letterSpacing: 0.4)),
    ]);
  }

  // ── Vista 1: por servicio ──────────────────────────────────────
  Widget _vistaPorServicio() {
    final lista = List<ServicioTecnico>.from(_filtrados)
      ..sort((a, b) => b.fecha.compareTo(a.fecha));
    if (lista.isEmpty) {
      return const Center(child: Text('Sin servicios en el rango.',
        style: TextStyle(color: AppColors.textSecondary)));
    }
    return ListView.builder(
      padding: const EdgeInsets.all(10),
      itemCount: lista.length,
      itemBuilder: (ctx, i) {
        final s = lista[i];
        final ganancia = s.ganancia;
        final margen = s.monto > 0 ? (ganancia / s.monto * 100) : 0;
        return Card(
          margin: const EdgeInsets.only(bottom: 8),
          child: Padding(
            padding: const EdgeInsets.all(12),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                Expanded(child: Text(
                  '${s.marca} ${s.modelo}'.trim().isEmpty
                      ? s.nombreCliente
                      : '${s.marca} ${s.modelo}',
                  style: const TextStyle(
                    fontWeight: FontWeight.w700, fontSize: 14))),
                Text(_ymd(s.fecha),
                  style: const TextStyle(
                    color: AppColors.textSecondary, fontSize: 11)),
              ]),
              const SizedBox(height: 2),
              Text('Cliente: ${s.nombreCliente} · Téc: ${s.tecnico}',
                style: const TextStyle(
                  color: AppColors.textSecondary, fontSize: 12)),
              const SizedBox(height: 8),
              Row(children: [
                Expanded(child: _miniKpi('Cobro',
                    formatCurrency(s.monto), AppColors.brandBlue)),
                Expanded(child: _miniKpi('Repuestos',
                    formatCurrency(s.costoRepuestos), AppColors.statusOrange)),
                Expanded(child: _miniKpi('Ganancia',
                    formatCurrency(ganancia),
                    ganancia >= 0 ? AppColors.statusGreen : AppColors.statusRed)),
                Expanded(child: _miniKpi('Margen',
                    '${margen.toStringAsFixed(1)}%',
                    ganancia >= 0 ? AppColors.statusGreen : AppColors.statusRed)),
              ]),
            ]),
          ),
        );
      },
    );
  }

  // ── Vista 2: por técnico ───────────────────────────────────────
  Widget _vistaPorTecnico() {
    final r = <String, Map<String, dynamic>>{};
    for (final s in _filtrados) {
      final tec = s.tecnico.trim().isEmpty ? '(sin asignar)' : s.tecnico;
      final e = r.putIfAbsent(tec, () => {
        'cobrado': 0.0, 'costo': 0.0, 'ganancia': 0.0, 'cantidad': 0,
      });
      e['cobrado']  = (e['cobrado']  as double) + s.monto;
      e['costo']    = (e['costo']    as double) + s.costoRepuestos;
      e['ganancia'] = (e['ganancia'] as double) + s.ganancia;
      e['cantidad'] = (e['cantidad'] as int) + 1;
    }
    if (r.isEmpty) {
      return const Center(child: Text('Sin servicios en el rango.',
        style: TextStyle(color: AppColors.textSecondary)));
    }
    final sorted = r.entries.toList()
      ..sort((a, b) =>
          (b.value['ganancia'] as double).compareTo(a.value['ganancia'] as double));
    return ListView.builder(
      padding: const EdgeInsets.all(12),
      itemCount: sorted.length,
      itemBuilder: (ctx, i) {
        final e = sorted[i];
        final cobrado  = e.value['cobrado']  as double;
        final costo    = e.value['costo']    as double;
        final ganancia = e.value['ganancia'] as double;
        final cantidad = e.value['cantidad'] as int;
        final margen = cobrado > 0 ? (ganancia / cobrado * 100) : 0;
        return Card(
          margin: const EdgeInsets.only(bottom: 10),
          child: Padding(
            padding: const EdgeInsets.all(14),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                Container(
                  width: 40, height: 40,
                  decoration: BoxDecoration(
                    color: AppColors.brandBlue.withValues(alpha: 0.1),
                    borderRadius: BorderRadius.circular(20),
                  ),
                  child: const Icon(Icons.engineering_outlined,
                      color: AppColors.brandBlue),
                ),
                const SizedBox(width: 10),
                Expanded(child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(e.key,
                      style: const TextStyle(
                        fontWeight: FontWeight.w800, fontSize: 14)),
                    Text('$cantidad servicio${cantidad == 1 ? "" : "s"}',
                      style: const TextStyle(
                        color: AppColors.textSecondary, fontSize: 11)),
                  ],
                )),
                Text('${margen.toStringAsFixed(1)}%',
                  style: TextStyle(
                    fontWeight: FontWeight.w800,
                    color: ganancia >= 0
                        ? AppColors.statusGreen : AppColors.statusRed)),
              ]),
              const SizedBox(height: 12),
              Row(children: [
                Expanded(child: _miniKpi('Cobrado',
                    formatCurrency(cobrado), AppColors.brandBlue)),
                Expanded(child: _miniKpi('Repuestos',
                    formatCurrency(costo), AppColors.statusOrange)),
                Expanded(child: _miniKpi('Ganancia',
                    formatCurrency(ganancia),
                    ganancia >= 0 ? AppColors.statusGreen : AppColors.statusRed)),
              ]),
              const SizedBox(height: 10),
              // ── Distribución 60% tienda / 40% técnico ──
              Row(children: [
                Expanded(
                  flex: 60,
                  child: Container(
                    padding: const EdgeInsets.symmetric(
                        horizontal: 10, vertical: 8),
                    decoration: BoxDecoration(
                      color: AppColors.brandBlue.withValues(alpha: 0.08),
                      borderRadius: const BorderRadius.only(
                          topLeft: Radius.circular(6),
                          bottomLeft: Radius.circular(6)),
                      border: Border.all(
                          color: AppColors.brandBlue.withValues(alpha: 0.3)),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(children: const [
                          Icon(Icons.storefront, size: 12,
                              color: AppColors.brandBlueDark),
                          SizedBox(width: 4),
                          Text('Tienda (60%)',
                              style: TextStyle(
                                  fontSize: 10,
                                  fontWeight: FontWeight.w600,
                                  color: AppColors.brandBlueDark)),
                        ]),
                        const SizedBox(height: 3),
                        Text(formatCurrency(ganancia * 0.60),
                            style: const TextStyle(
                                fontSize: 14,
                                fontWeight: FontWeight.w900,
                                color: AppColors.brandBlueDark)),
                      ],
                    ),
                  ),
                ),
                Expanded(
                  flex: 40,
                  child: Container(
                    padding: const EdgeInsets.symmetric(
                        horizontal: 10, vertical: 8),
                    decoration: BoxDecoration(
                      color: AppColors.statusOrange.withValues(alpha: 0.10),
                      borderRadius: const BorderRadius.only(
                          topRight: Radius.circular(6),
                          bottomRight: Radius.circular(6)),
                      border: Border.all(
                          color: AppColors.statusOrange.withValues(alpha: 0.4)),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(children: const [
                          Icon(Icons.engineering, size: 12,
                              color: AppColors.statusOrange),
                          SizedBox(width: 4),
                          Text('Pago técnico (40%)',
                              style: TextStyle(
                                  fontSize: 10,
                                  fontWeight: FontWeight.w600,
                                  color: AppColors.statusOrange)),
                        ]),
                        const SizedBox(height: 3),
                        Text(formatCurrency(ganancia * 0.40),
                            style: const TextStyle(
                                fontSize: 14,
                                fontWeight: FontWeight.w900,
                                color: AppColors.statusOrange)),
                      ],
                    ),
                  ),
                ),
              ]),
            ]),
          ),
        );
      },
    );
  }

  // ── Vista 3: por mes ───────────────────────────────────────────
  Widget _vistaPorMes() {
    final r = <String, Map<String, dynamic>>{};
    for (final s in _filtrados) {
      final clave = '${s.fecha.year}-${s.fecha.month.toString().padLeft(2, '0')}';
      final e = r.putIfAbsent(clave, () => {
        'cobrado': 0.0, 'costo': 0.0, 'ganancia': 0.0, 'cantidad': 0,
      });
      e['cobrado']  = (e['cobrado']  as double) + s.monto;
      e['costo']    = (e['costo']    as double) + s.costoRepuestos;
      e['ganancia'] = (e['ganancia'] as double) + s.ganancia;
      e['cantidad'] = (e['cantidad'] as int) + 1;
    }
    if (r.isEmpty) {
      return const Center(child: Text('Sin servicios en el rango.',
        style: TextStyle(color: AppColors.textSecondary)));
    }
    // Ordenar por mes descendente (más reciente primero)
    final sorted = r.entries.toList()..sort((a, b) => b.key.compareTo(a.key));

    final meses = ['Ene','Feb','Mar','Abr','May','Jun',
                   'Jul','Ago','Sep','Oct','Nov','Dic'];

    return ListView.builder(
      padding: const EdgeInsets.all(12),
      itemCount: sorted.length,
      itemBuilder: (ctx, i) {
        final e = sorted[i];
        final partes = e.key.split('-');
        final anio = partes[0];
        final mes = int.tryParse(partes[1]) ?? 1;
        final nombreMes = '${meses[mes-1]} $anio';
        final cobrado  = e.value['cobrado']  as double;
        final costo    = e.value['costo']    as double;
        final ganancia = e.value['ganancia'] as double;
        final cantidad = e.value['cantidad'] as int;
        final margen = cobrado > 0 ? (ganancia / cobrado * 100) : 0;

        return Card(
          margin: const EdgeInsets.only(bottom: 10),
          child: Padding(
            padding: const EdgeInsets.all(14),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                const Icon(Icons.calendar_month, color: AppColors.brandBlue),
                const SizedBox(width: 10),
                Expanded(child: Text(nombreMes,
                  style: const TextStyle(
                    fontWeight: FontWeight.w800, fontSize: 15))),
                Text('$cantidad servicios',
                  style: const TextStyle(
                    color: AppColors.textSecondary, fontSize: 12)),
              ]),
              const SizedBox(height: 10),
              Row(children: [
                Expanded(child: _miniKpi('Cobrado',
                    formatCurrency(cobrado), AppColors.brandBlue)),
                Expanded(child: _miniKpi('Repuestos',
                    formatCurrency(costo), AppColors.statusOrange)),
                Expanded(child: _miniKpi('Ganancia',
                    formatCurrency(ganancia),
                    ganancia >= 0 ? AppColors.statusGreen : AppColors.statusRed)),
                Expanded(child: _miniKpi('Margen',
                    '${margen.toStringAsFixed(1)}%',
                    ganancia >= 0 ? AppColors.statusGreen : AppColors.statusRed)),
              ]),
            ]),
          ),
        );
      },
    );
  }

  Widget _miniKpi(String label, String valor, Color color) {
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Text(label,
        style: const TextStyle(
          color: AppColors.textSecondary, fontSize: 10)),
      const SizedBox(height: 1),
      Text(valor,
        style: TextStyle(
          fontWeight: FontWeight.w800, color: color, fontSize: 13)),
    ]);
  }
}

// ════════════════════════════════════════════════════════════
//  VENTANA DE ESTADÍSTICAS DE PRODUCTOS
// ════════════════════════════════════════════════════════════
//  Muestra rankings de productos y modelos por unidades vendidas
//  e ingreso generado, filtrable por rango de fechas. Permite
//  responder preguntas como: ¿cuál fue el modelo más vendido el
//  mes pasado? ¿cuánto ingresó la marca Xiaomi? ¿qué categoría
//  está rindiendo más?
class VentanaEstadisticasProductos extends StatefulWidget {
  const VentanaEstadisticasProductos({super.key});
  @override State<VentanaEstadisticasProductos> createState() =>
      _VentanaEstadisticasProductosState();
}

class _VentanaEstadisticasProductosState
    extends State<VentanaEstadisticasProductos>
    with SingleTickerProviderStateMixin {
  // Filtros
  DateTime? _desde;
  DateTime? _hasta;
  String? _marcaFiltro;     // null = todas
  String? _categoriaFiltro; // null = todas

  late TabController _tabs;
  bool _cargando = false;
  /// Tiendas activas según el backend (orden de la tabla `tiendas`).
  List<String> _tiendas = [];

  @override
  void initState() {
    super.initState();
    _tabs = TabController(length: 3, vsync: this);
    final now = DateTime.now();
    _desde = DateTime(now.year, now.month, 1);
    _hasta = now;
    _cargar();
  }

  @override
  void dispose() {
    _tabs.dispose();
    super.dispose();
  }

  Future<void> _cargar() async {
    setState(() => _cargando = true);
    try {
      // Cargar productos, IMEIs y facturas frescas en paralelo.
      final results = await Future.wait([
        _Api.get('productos'),
        _Api.get('stock_imei'),
        _Api.get('facturas'),
      ]);
      catalogoGlobal = ((results[0] as List?) ?? [])
          .map((m) => Producto.fromMap(m as Map<String, dynamic>))
          .toList();
      stockImeiGlobal = ((results[1] as List?) ?? [])
          .map((m) => ImeiRegistro.fromMap(m as Map<String, dynamic>))
          .toList();

      // Usamos el parser global que captura vendedorPorImei/vendedorPorCodigo
      // y creadorRol desde el JSON. Antes este bloque tenía su propio parser
      // que NO leía esos campos, perdiendo la atribución de vendedor por
      // producto que se necesita para la Fase 2.
      ventasGlobal = ((results[2] as List?) ?? [])
          .map((m) => construirFacturaModelDesdeJson(m as Map<String, dynamic>))
          .toList();
      // Tiendas activas, para que el Excel muestre también las que no
      // vendieron en el rango (con 0). Si falla, el reporte usa las
      // tiendas que aparecen en ventas y existencias.
      try {
        final rawT = (await _Api.get('tiendas') as List?) ?? [];
        _tiendas = rawT.whereType<Map>().where((m) {
          final a = m['activa'];
          return a == null || a == 1 || a == '1' || a == true;
        }).map((m) => (m['nombre'] ?? '').toString().trim())
          .where((n) => n.isNotEmpty).toList();
      } catch (e) {
        debugPrint('[Estadisticas] tiendas: $e');
      }
    } catch (e) {
      debugPrint('[Estadisticas] error: $e');
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  /// Recorre las facturas filtradas y agrega TODOS los productos
  /// vendidos (con IMEI y sin IMEI). Devuelve un map producto→stats
  /// con unidades y total ingresado.
  ///
  /// CAMBIO FASE 2: cada producto se atribuye a SU vendedor (no al
  /// creador de la factura). Si el producto no tiene vendedor asignado,
  /// cae al creador. Esto permite ver en el ranking quién vendió
  /// realmente cada modelo.
  Map<String, _StatsItem> _calcularRanking() {
    final m = <String, _StatsItem>{};
    for (final f in ventasGlobal) {
      final fecha = parseFechaFlexible(f.fecha);
      if (fecha == null) continue;
      if (_desde != null && fecha.isBefore(
          DateTime(_desde!.year, _desde!.month, _desde!.day))) continue;
      if (_hasta != null) {
        final fin = DateTime(_hasta!.year, _hasta!.month, _hasta!.day, 23, 59, 59);
        if (fecha.isAfter(fin)) continue;
      }
      for (final eq in f.equipos) {
        // Vendedor de ESTE equipo (puede ser distinto al creador).
        final vendedor = f.vendedorDeEquipo(eq.imei);
        _registrar(m, eq.producto, 1, eq.producto.precioVenta,
            vendedor: vendedor, factura: f, imei: eq.imei);
      }
      for (final it in f.itemsSinImei) {
        final vendedor = f.vendedorDeItem(it.codigo);
        _registrar(m, it, 1, it.precioVenta,
            vendedor: vendedor, factura: f, imei: '');
      }
    }
    return m;
  }

  void _registrar(Map<String, _StatsItem> m, Producto p,
      int unidades, double monto,
      {required String vendedor,
       required FacturaModel factura,
       required String imei}) {
    // Filtros
    if (_marcaFiltro != null && p.marca != _marcaFiltro) return;
    if (_categoriaFiltro != null && p.categoria != _categoriaFiltro) return;
    final key = p.codigo;
    final e = m.putIfAbsent(key, () => _StatsItem(producto: p));
    e.unidades += unidades;
    e.total    += monto;
    e.costo    += p.precioCosto * unidades;
    // Desglose por vendedor
    e.unidadesPorVendedor[vendedor] =
        (e.unidadesPorVendedor[vendedor] ?? 0) + unidades;
    e.montoPorVendedor[vendedor] =
        (e.montoPorVendedor[vendedor] ?? 0) + monto;
    // Detalle plano para la pestaña detalle / exportación
    e.ventas.add({
      'nroFactura': factura.nroFactura,
      'fecha'     : factura.fecha,
      'cliente'   : factura.cliente,
      'cedula'    : factura.cedula,
      'vendedor'  : vendedor,
      'creador'   : factura.vendedor,
      'imei'      : imei,
      'tienda'    : factura.tienda,
      'precio'    : monto,
      'costo'     : p.precioCosto * unidades,
    });
  }

  List<String> get _marcasDisponibles {
    final set = catalogoGlobal
        .map((p) => p.marca)
        .where((m) => m.isNotEmpty && m != 'Genérico')
        .toSet();
    return set.toList()..sort();
  }

  List<String> get _categoriasDisponibles {
    return List<String>.from(CategoriasProductos.lista)..sort();
  }

  @override
  Widget build(BuildContext context) {
    final ranking = _calcularRanking().values.toList()
      ..sort((a,b) => b.unidades.compareTo(a.unidades));
    final porModelo = _agruparPor((p) => '${p.marca} ${p.modelo}'.trim(), ranking);
    final porMarca  = _agruparPor((p) => p.marca, ranking);
    final totalU = ranking.fold<int>(0, (s,e) => s + e.unidades);
    final totalI = ranking.fold<double>(0, (s,e) => s + e.total);

    return Scaffold(
      appBar: AppBar(
        title: const Text('Estadísticas de Productos'),
        backgroundColor: AppColors.brandBlue,
        foregroundColor: Colors.white,
        bottom: TabBar(
          controller: _tabs,
          labelColor: Colors.white,
          unselectedLabelColor: Colors.white60,
          indicatorColor: AppColors.brandYellow,
          tabs: const [
            Tab(icon: Icon(Icons.inventory_2), text: 'Productos'),
            Tab(icon: Icon(Icons.phone_android), text: 'Modelos'),
            Tab(icon: Icon(Icons.business), text: 'Marcas'),
          ],
        ),
        actions: [
          IconButton(
              icon: const Icon(Icons.file_download_outlined),
              tooltip: "Exportar Excel",
              onPressed: _exportarExcel),
          IconButton(
              icon: const Icon(Icons.refresh),
              tooltip: "Actualizar",
              onPressed: _cargar),
        ],
      ),
      body: Column(children: [
        _buildFiltros(),
        _buildKPIs(totalU, totalI),
        Expanded(child: _cargando
            ? const Center(child: CircularProgressIndicator())
            : TabBarView(controller: _tabs, children: [
                _buildLista(ranking),
                _buildLista(porModelo),
                _buildLista(porMarca),
              ])),
      ]),
    );
  }

  /// Agrupa el ranking de productos por una clave arbitraria.
  /// Devuelve una lista de _StatsItem con la suma agregada y un
  /// "producto representativo" (el primero del grupo) para mostrar.
  /// Conserva el desglose por vendedor y las ventas individuales para
  /// que la vista agrupada también pueda mostrarlos.
  List<_StatsItem> _agruparPor(
      String Function(Producto) keyOf, List<_StatsItem> items) {
    final agrup = <String, _StatsItem>{};
    for (final e in items) {
      final k = keyOf(e.producto);
      if (k.trim().isEmpty) continue;
      final a = agrup.putIfAbsent(k, () => _StatsItem(producto: e.producto));
      a.unidades += e.unidades;
      a.total    += e.total;
      a.costo    += e.costo;
      // Fusionar desglose por vendedor
      e.unidadesPorVendedor.forEach((v, u) {
        a.unidadesPorVendedor[v] = (a.unidadesPorVendedor[v] ?? 0) + u;
      });
      e.montoPorVendedor.forEach((v, mo) {
        a.montoPorVendedor[v] = (a.montoPorVendedor[v] ?? 0) + mo;
      });
      a.ventas.addAll(e.ventas);
    }
    return agrup.values.toList()
      ..sort((a,b) => b.unidades.compareTo(a.unidades));
  }

  Widget _buildFiltros() {
    return Container(
      padding: const EdgeInsets.all(12),
      color: AppColors.surfaceTintBlue,
      child: Column(children: [
        InkWell(
          onTap: () async {
            final r = await showDateRangePicker(
              context: context,
              firstDate: DateTime(2020),
              lastDate: DateTime.now(),
              initialDateRange: _desde != null && _hasta != null
                  ? DateTimeRange(start: _desde!, end: _hasta!) : null,
            );
            if (r != null) setState(() {
              _desde = r.start; _hasta = r.end;
            });
          },
          child: InputDecorator(
            decoration: const InputDecoration(
              labelText: 'Rango de fechas',
              prefixIcon: Icon(Icons.event),
              isDense: true,
              border: OutlineInputBorder(),
            ),
            child: Text(
              '${_desde?.day.toString().padLeft(2,"0")}/'
              '${_desde?.month.toString().padLeft(2,"0")}/${_desde?.year}'
              '  →  '
              '${_hasta?.day.toString().padLeft(2,"0")}/'
              '${_hasta?.month.toString().padLeft(2,"0")}/${_hasta?.year}',
            ),
          ),
        ),
        const SizedBox(height: 8),
        Row(children: [
          Expanded(child: DropdownButtonFormField<String?>(
            value: _marcaFiltro,
            isExpanded: true,
            decoration: const InputDecoration(
                labelText: 'Marca', isDense: true,
                border: OutlineInputBorder()),
            items: [
              const DropdownMenuItem<String?>(value: null,
                  child: Text('Todas')),
              ..._marcasDisponibles.map((m) =>
                  DropdownMenuItem<String?>(value: m, child: Text(m))),
            ],
            onChanged: (v) => setState(() => _marcaFiltro = v),
          )),
          const SizedBox(width: 8),
          Expanded(child: DropdownButtonFormField<String?>(
            value: _categoriaFiltro,
            isExpanded: true,
            decoration: const InputDecoration(
                labelText: 'Categoría', isDense: true,
                border: OutlineInputBorder()),
            items: [
              const DropdownMenuItem<String?>(value: null,
                  child: Text('Todas')),
              ..._categoriasDisponibles.map((c) =>
                  DropdownMenuItem<String?>(value: c, child: Text(c))),
            ],
            onChanged: (v) => setState(() => _categoriaFiltro = v),
          )),
        ]),
      ]),
    );
  }

  Widget _buildKPIs(int unidades, double total) {
    return Container(
      color: AppColors.brandBlue,
      padding: const EdgeInsets.all(14),
      child: Row(children: [
        Expanded(child: _kpi(
          'Unidades vendidas', '$unidades', Icons.shopping_bag,
          AppColors.brandYellow)),
        Container(width: 1, height: 30, color: Colors.white24),
        Expanded(child: _kpi(
          'Ingreso total',
          '\$${total.toStringAsFixed(2)}',
          Icons.attach_money,
          AppColors.statusGreen)),
      ]),
    );
  }

  Widget _kpi(String label, String value, IconData icon, Color color) {
    return Column(children: [
      Icon(icon, color: color, size: 22),
      const SizedBox(height: 4),
      Text(value, style: TextStyle(
          color: color, fontWeight: FontWeight.w900, fontSize: 18)),
      Text(label, style: const TextStyle(
          color: Colors.white70, fontSize: 11)),
    ]);
  }

  Widget _buildLista(List<_StatsItem> items) {
    if (items.isEmpty) {
      return const Center(child: Padding(
        padding: EdgeInsets.all(40),
        child: Text(
          'Sin ventas en el rango seleccionado',
          style: TextStyle(color: AppColors.textSecondary)),
      ));
    }
    final maxU = items.first.unidades;
    return ListView.builder(
      padding: const EdgeInsets.all(12),
      itemCount: items.length,
      itemBuilder: (_, i) {
        final e = items[i];
        final pct = maxU > 0 ? e.unidades / maxU : 0.0;
        return Container(
          margin: const EdgeInsets.only(bottom: 8),
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(10),
            border: Border.all(color: Colors.grey.shade300),
          ),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start,
              children: [
            Row(children: [
              Container(
                width: 32, height: 32,
                decoration: BoxDecoration(
                  color: i < 3
                      ? AppColors.brandYellow.withValues(alpha: 0.2)
                      : AppColors.surfaceGrey,
                  borderRadius: BorderRadius.circular(8),
                ),
                child: Center(child: Text('#${i+1}',
                    style: TextStyle(
                        fontWeight: FontWeight.w900,
                        color: i < 3 ? AppColors.brandBlue
                                     : AppColors.textSecondary))),
              ),
              const SizedBox(width: 10),
              Expanded(child: Column(
                crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text(_etiqueta(e.producto),
                      style: const TextStyle(
                          fontWeight: FontWeight.w700, fontSize: 14)),
                  Text('${e.producto.categoria} · ${e.producto.marca}',
                      style: const TextStyle(
                          fontSize: 11,
                          color: AppColors.textSecondary)),
                ])),
              Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
                Text('${e.unidades} u.',
                    style: const TextStyle(
                        fontWeight: FontWeight.w900,
                        color: AppColors.brandBlue, fontSize: 15)),
                Text('\$${e.total.toStringAsFixed(2)}',
                    style: const TextStyle(
                        color: AppColors.statusGreen,
                        fontWeight: FontWeight.w700, fontSize: 12)),
              ]),
            ]),
            const SizedBox(height: 8),
            ClipRRect(
              borderRadius: BorderRadius.circular(4),
              child: LinearProgressIndicator(
                value: pct,
                minHeight: 6,
                backgroundColor: AppColors.surfaceGrey,
                valueColor: AlwaysStoppedAnimation<Color>(
                    i < 3 ? AppColors.brandYellow : AppColors.brandBlue),
              ),
            ),
            // ── Desglose por vendedor (expandible) ──
            // Muestra quién(es) vendió(eron) este producto en el rango.
            // Si hay un solo vendedor para todas las unidades, se muestra
            // como chip simple; si hay varios, como ExpansionTile.
            if (e.unidadesPorVendedor.isNotEmpty) ...[
              const SizedBox(height: 6),
              _buildDesgloseVendedores(e),
            ],
          ]),
        );
      },
    );
  }

  /// Muestra el desglose de vendedores de un producto:
  /// · 1 vendedor → un único chip pequeño con su nombre.
  /// · 2+ vendedores → ExpansionTile con la lista ordenada por unidades.
  Widget _buildDesgloseVendedores(_StatsItem e) {
    final vendedores = e.vendedoresOrdenados;
    if (vendedores.length == 1) {
      final v = vendedores.first;
      return Align(
        alignment: Alignment.centerLeft,
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
          decoration: BoxDecoration(
            color: AppColors.brandBlue.withValues(alpha: 0.08),
            borderRadius: BorderRadius.circular(6),
            border: Border.all(
              color: AppColors.brandBlue.withValues(alpha: 0.3), width: 0.5,
            ),
          ),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            const Icon(Icons.person, size: 12, color: AppColors.brandBlue),
            const SizedBox(width: 4),
            Text('Vendido por ${v.key}',
                style: const TextStyle(
                    fontSize: 11,
                    fontWeight: FontWeight.w600,
                    color: AppColors.brandBlue)),
          ]),
        ),
      );
    }
    // Múltiples vendedores → expandible
    return Theme(
      data: Theme.of(context).copyWith(dividerColor: Colors.transparent),
      child: ExpansionTile(
        tilePadding: EdgeInsets.zero,
        childrenPadding: const EdgeInsets.only(left: 8, bottom: 6),
        dense: true,
        title: Row(children: [
          const Icon(Icons.group, size: 14, color: AppColors.brandBlue),
          const SizedBox(width: 6),
          Text('${vendedores.length} vendedores',
              style: const TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.w600,
                  color: AppColors.brandBlue)),
        ]),
        children: vendedores.map((v) {
          final monto = e.montoPorVendedor[v.key] ?? 0;
          return Padding(
            padding: const EdgeInsets.symmetric(vertical: 2),
            child: Row(children: [
              const Icon(Icons.person_outline, size: 12, color: Colors.grey),
              const SizedBox(width: 4),
              Expanded(child: Text(v.key,
                  style: const TextStyle(fontSize: 11))),
              Text('${v.value} u.',
                  style: const TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w700,
                      color: AppColors.brandBlue)),
              const SizedBox(width: 8),
              Text('\$${monto.toStringAsFixed(2)}',
                  style: const TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      color: AppColors.statusGreen)),
            ]),
          );
        }).toList(),
      ),
    );
  }

  /// Nombre de tienda normalizado para agrupar (vacío → "Sin asignar").
  String _nombreTienda(String t) {
    final s = t.trim();
    return s.isEmpty ? 'Sin asignar' : s;
  }

  bool _pasaFiltros(Producto p) {
    if (_marcaFiltro != null && p.marca != _marcaFiltro) return false;
    if (_categoriaFiltro != null && p.categoria != _categoriaFiltro) return false;
    return true;
  }

  /// Existencia ACTUAL por producto y tienda: código → (tienda → unidades).
  /// Teléfonos: IMEIs no vendidos según su ubicación. Resto: stock
  /// manual del producto en su tienda. Respeta los filtros de marca y
  /// categoría (la existencia es de hoy, no del rango de fechas).
  Map<String, Map<String, int>> _existenciaPorTienda(
      Map<String, Producto> productos) {
    final ex = <String, Map<String, int>>{};
    final codigosConImei = <String>{};
    final catalogo = {for (final p in catalogoGlobal) p.codigo: p};
    for (final i in stockImeiGlobal) {
      final codigo = i.producto.codigo;
      if (codigo.isEmpty) continue;
      codigosConImei.add(codigo);
      if (i.vendido) continue;
      final p = catalogo[codigo] ?? i.producto;
      if (!_pasaFiltros(p)) continue;
      productos.putIfAbsent(codigo, () => p);
      final t = _nombreTienda(i.ubicacion);
      final m = ex.putIfAbsent(codigo, () => {});
      m[t] = (m[t] ?? 0) + 1;
    }
    for (final p in catalogoGlobal) {
      if (p.stockManual <= 0) continue;
      if (codigosConImei.contains(p.codigo) || p.categoria == 'Telefono') continue;
      if (!_pasaFiltros(p)) continue;
      productos.putIfAbsent(p.codigo, () => p);
      final t = _nombreTienda(p.tienda);
      final m = ex.putIfAbsent(p.codigo, () => {});
      m[t] = (m[t] ?? 0) + p.stockManual;
    }
    return ex;
  }

  /// Exporta a Excel el análisis del rango y filtros actuales.
  /// Hojas:
  ///   1. Rentabilidad por tienda — ventas, unidades, ingresos, costo,
  ///      ganancia, margen, ticket promedio y existencia de cada tienda.
  ///   2. Modelos por tienda — unidades vendidas de cada modelo en cada
  ///      tienda, existencia actual por tienda y alerta de reposición.
  ///   3. Ranking — productos ordenados por unidades, con ganancia.
  ///   4. Por vendedor — fila por (producto × vendedor).
  ///   5. Detalle — fila por cada venta individual (auditoría).
  Future<void> _exportarExcel() async {
    try {
      final ranking = _calcularRanking().values.toList()
        ..sort((a, b) => b.unidades.compareTo(a.unidades));
      final productos = <String, Producto>{
        for (final e in ranking) e.producto.codigo: e.producto,
      };
      final existencia = _existenciaPorTienda(productos);
      if (ranking.isEmpty && existencia.isEmpty) {
        if (mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
          content: Text('No hay ventas ni existencias para exportar con estos filtros'),
          backgroundColor: AppColors.statusOrange));
        return;
      }

      // ── Agregados por tienda y por (producto × tienda) ──
      final facturasPorTienda = <String, Set<String>>{};
      final unidadesTienda = <String, int>{};
      final ingresoTienda = <String, double>{};
      final costoTienda = <String, double>{};
      final vendidoProdTienda = <String, Map<String, int>>{};
      for (final e in ranking) {
        for (final v in e.ventas) {
          final t = _nombreTienda((v['tienda'] ?? '').toString());
          facturasPorTienda.putIfAbsent(t, () => {})
              .add((v['nroFactura'] ?? '').toString());
          unidadesTienda[t] = (unidadesTienda[t] ?? 0) + 1;
          ingresoTienda[t] = (ingresoTienda[t] ?? 0) +
              ((v['precio'] as num?)?.toDouble() ?? 0);
          costoTienda[t] = (costoTienda[t] ?? 0) +
              ((v['costo'] as num?)?.toDouble() ?? 0);
          final m = vendidoProdTienda.putIfAbsent(e.producto.codigo, () => {});
          m[t] = (m[t] ?? 0) + 1;
        }
      }
      final existTienda = <String, int>{};
      final valorInvTienda = <String, double>{};
      existencia.forEach((codigo, porTienda) {
        final costo = productos[codigo]?.precioCosto ?? 0;
        porTienda.forEach((t, u) {
          existTienda[t] = (existTienda[t] ?? 0) + u;
          valorInvTienda[t] = (valorInvTienda[t] ?? 0) + costo * u;
        });
      });

      // Tiendas: primero las del backend en su orden; luego cualquier
      // otra ubicación que aparezca en ventas o existencias.
      final tiendas = <String>[..._tiendas.map(_nombreTienda)];
      final extras = <String>{
        ...unidadesTienda.keys, ...existTienda.keys,
      }.where((t) => !tiendas.contains(t)).toList()..sort();
      tiendas.addAll(extras);

      final excel = Excel.createExcel();

      final ts = DateTime.now().millisecondsSinceEpoch;
      String f2(int n) => n.toString().padLeft(2, '0');
      String fecha(DateTime? d) =>
          d == null ? '?' : '${f2(d.day)}/${f2(d.month)}/${d.year}';
      final ahora = DateTime.now();
      final subtitulo = [
        'Período: ${fecha(_desde)} al ${fecha(_hasta)}',
        'Categoría: ${_categoriaFiltro ?? "Todas"}',
        'Marca: ${_marcaFiltro ?? "Todas"}',
        'Generado: ${fecha(ahora)} ${f2(ahora.hour)}:${f2(ahora.minute)}',
      ].join('   ·   ');

      // ════════ Hoja 1: Rentabilidad por tienda ════════
      {
        final h = _HojaXlsx(excel['Rentabilidad por tienda']);
        // 'Sheet1' (la hoja por defecto del paquete) solo se puede
        // borrar cuando ya existe otra; borrarla antes no hace nada y
        // el archivo abría en una hoja vacía.
        excel.delete('Sheet1');
        const cols = [
          ('TIENDA', _XlsxColores.navy, _XlsxColores.naranja),
          ('# VENTAS', _XlsxColores.azul, _XlsxColores.blanco),
          ('UNIDADES', _XlsxColores.teal, _XlsxColores.blanco),
          ('INGRESOS', _XlsxColores.verde, _XlsxColores.blanco),
          ('COSTO', _XlsxColores.gris, _XlsxColores.blanco),
          ('GANANCIA TOTAL', _XlsxColores.coral, _XlsxColores.blanco),
          ('MARGEN %', _XlsxColores.teal2, _XlsxColores.blanco),
          ('TICKET PROM.', _XlsxColores.azul, _XlsxColores.blanco),
          ('% DE LAS VENTAS', _XlsxColores.teal, _XlsxColores.blanco),
          ('EXISTENCIA HOY', _XlsxColores.morado, _XlsxColores.blanco),
          ('VALOR INVENTARIO', _XlsxColores.morado, _XlsxColores.blanco),
        ];
        h.titulo(0, cols.length, 'RENTABILIDAD POR TIENDA — TECNO LÍDER', subtitulo);
        const fh = 4;
        for (var c = 0; c < cols.length; c++) {
          h.encabezado(c, fh, cols[c].$1, fondo: cols[c].$2, texto: cols[c].$3);
        }
        h.alto(fh, 30);
        final totalIngreso = ingresoTienda.values.fold<double>(0, (s, v) => s + v);
        var r = fh + 1;
        var tVentas = 0, tUnid = 0, tExist = 0;
        var tIng = 0.0, tCosto = 0.0, tValInv = 0.0;
        for (var i = 0; i < tiendas.length; i++) {
          final t = tiendas[i];
          final ventas = facturasPorTienda[t]?.length ?? 0;
          final unid = unidadesTienda[t] ?? 0;
          final ing = ingresoTienda[t] ?? 0;
          final costo = costoTienda[t] ?? 0;
          final gan = ing - costo;
          final exist = existTienda[t] ?? 0;
          final valInv = valorInvTienda[t] ?? 0;
          tVentas += ventas; tUnid += unid; tExist += exist;
          tIng += ing; tCosto += costo; tValInv += valInv;
          final fondo = i.isEven ? _XlsxColores.fila1 : _XlsxColores.fila2;
          h.celda(0, r, t, fondo: _XlsxColores.paleta[i % _XlsxColores.paleta.length],
              color: _XlsxColores.blanco, negrita: true);
          h.entero(1, r, ventas, fondo: fondo);
          h.entero(2, r, unid, fondo: fondo);
          h.dinero(3, r, ing, fondo: fondo);
          h.dinero(4, r, costo, fondo: fondo);
          h.dinero(5, r, gan, fondo: _XlsxColores.verdeClaro,
              color: _XlsxColores.verdeTexto, negrita: true);
          h.porcentaje(6, r, ing > 0 ? gan / ing : 0, fondo: _XlsxColores.amarillo);
          h.dinero(7, r, ventas > 0 ? ing / ventas : 0, fondo: fondo);
          h.porcentaje(8, r, totalIngreso > 0 ? ing / totalIngreso : 0, fondo: fondo);
          h.entero(9, r, exist, fondo: fondo);
          h.dinero(10, r, valInv, fondo: fondo);
          h.alto(r, 22);
          r++;
        }
        final tGan = tIng - tCosto;
        h.celda(0, r, '⚡ TOTAL GENERAL', fondo: _XlsxColores.navy,
            color: _XlsxColores.naranja, negrita: true);
        h.entero(1, r, tVentas, fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        h.entero(2, r, tUnid, fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        h.dinero(3, r, tIng, fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        h.dinero(4, r, tCosto, fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        h.dinero(5, r, tGan, fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        h.porcentaje(6, r, tIng > 0 ? tGan / tIng : 0, fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        h.dinero(7, r, tVentas > 0 ? tIng / tVentas : 0, fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        h.porcentaje(8, r, tIng > 0 ? 1 : 0, fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        h.entero(9, r, tExist, fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        h.dinero(10, r, tValInv, fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        h.alto(r, 26);
        h.nota(0, r + 2, cols.length,
            'Ingresos y costo según precios del catálogo de cada producto vendido. '
            '# Ventas = facturas distintas. Existencia y valor de inventario son de hoy '
            '(teléfonos por IMEI disponible en su ubicación).');
        h.anchos([24, 11, 11, 15, 15, 17, 11, 14, 15, 14, 17]);
      }

      // ════════ Hoja 2: Modelos por tienda ════════
      {
        final h = _HojaXlsx(excel['Modelos por tienda']);
        final nT = tiendas.length;
        // Columnas: MODELO, CATEGORÍA, [vendidos × tienda], TOTAL VENDIDO,
        //           [existencia × tienda], TOTAL EXISTENCIA, INGRESOS,
        //           GANANCIA, ESTADO
        const cVend = 2;
        final cTotV = cVend + nT;
        final cExist = cTotV + 1;
        final cTotE = cExist + nT;
        final cIng = cTotE + 1;
        final cGan = cIng + 1;
        final cEst = cGan + 1;
        final nCols = cEst + 1;
        h.titulo(0, nCols, 'VENTAS Y EXISTENCIA POR MODELO Y TIENDA — TECNO LÍDER', subtitulo);
        // Fila de grupos
        const fg = 4, fh = 5;
        h.grupo(cVend, cTotV, fg, 'VENDIDOS EN EL PERÍODO', _XlsxColores.azul);
        h.grupo(cExist, cTotE, fg, 'EXISTENCIA HOY', _XlsxColores.morado);
        h.grupo(cIng, cGan, fg, 'RESULTADO', _XlsxColores.verde);
        h.encabezado(0, fh, 'MODELO', fondo: _XlsxColores.navy, texto: _XlsxColores.naranja);
        h.encabezado(1, fh, 'CATEGORÍA', fondo: _XlsxColores.navy, texto: _XlsxColores.naranja);
        for (var i = 0; i < nT; i++) {
          h.encabezado(cVend + i, fh, tiendas[i].toUpperCase(), fondo: _XlsxColores.azul);
          h.encabezado(cExist + i, fh, tiendas[i].toUpperCase(), fondo: _XlsxColores.morado);
        }
        h.encabezado(cTotV, fh, 'TOTAL VENDIDO', fondo: _XlsxColores.navy, texto: _XlsxColores.naranja);
        h.encabezado(cTotE, fh, 'TOTAL EXISTENCIA', fondo: _XlsxColores.navy, texto: _XlsxColores.naranja);
        h.encabezado(cIng, fh, 'INGRESOS', fondo: _XlsxColores.verde);
        h.encabezado(cGan, fh, 'GANANCIA', fondo: _XlsxColores.coral);
        h.encabezado(cEst, fh, 'ESTADO', fondo: _XlsxColores.teal2);
        h.alto(fh, 32);

        final porCodigo = {for (final e in ranking) e.producto.codigo: e};
        final codigos = productos.keys.toList();
        int vendidoDe(String c) => porCodigo[c]?.unidades ?? 0;
        int existeDe(String c) =>
            (existencia[c]?.values ?? const <int>[]).fold(0, (s, v) => s + v);
        codigos.sort((a, b) {
          final d = vendidoDe(b).compareTo(vendidoDe(a));
          if (d != 0) return d;
          final d2 = existeDe(b).compareTo(existeDe(a));
          if (d2 != 0) return d2;
          return _nombreModelo(productos[a]!).compareTo(_nombreModelo(productos[b]!));
        });

        final totVendT = List<int>.filled(nT, 0);
        final totExistT = List<int>.filled(nT, 0);
        var totV = 0, totE = 0;
        var totIng = 0.0, totGan = 0.0;
        var r = fh + 1;
        for (var k = 0; k < codigos.length; k++) {
          final c = codigos[k];
          final p = productos[c]!;
          final st = porCodigo[c];
          final fondo = k.isEven ? _XlsxColores.fila1 : _XlsxColores.fila2;
          h.celda(0, r, _nombreModelo(p), fondo: fondo, negrita: true);
          h.celda(1, r, p.categoria, fondo: fondo);
          final vend = vendidoDe(c);
          final exist = existeDe(c);
          for (var i = 0; i < nT; i++) {
            final u = vendidoProdTienda[c]?[tiendas[i]] ?? 0;
            final e = existencia[c]?[tiendas[i]] ?? 0;
            totVendT[i] += u;
            totExistT[i] += e;
            h.entero(cVend + i, r, u, fondo: fondo, gris: u == 0);
            h.entero(cExist + i, r, e, fondo: fondo, gris: e == 0);
          }
          h.entero(cTotV, r, vend, fondo: _XlsxColores.azulClaro, negrita: true);
          h.entero(cTotE, r, exist, fondo: _XlsxColores.moradoClaro, negrita: true);
          final ing = st?.total ?? 0;
          final gan = ing - (st?.costo ?? 0);
          totV += vend; totE += exist; totIng += ing; totGan += gan;
          h.dinero(cIng, r, ing, fondo: fondo);
          h.dinero(cGan, r, gan, fondo: _XlsxColores.verdeClaro,
              color: _XlsxColores.verdeTexto, negrita: true);
          final String estado;
          final String fondoEstado;
          if (exist == 0 && vend > 0) {
            estado = 'AGOTADO'; fondoEstado = _XlsxColores.rojoClaro;
          } else if (exist < vend) {
            estado = 'REPONER'; fondoEstado = _XlsxColores.amarillo;
          } else if (vend == 0) {
            estado = 'SIN MOVIMIENTO'; fondoEstado = _XlsxColores.grisClaro;
          } else {
            estado = 'OK'; fondoEstado = _XlsxColores.verdeClaro;
          }
          h.celda(cEst, r, estado, fondo: fondoEstado, negrita: true, centrado: true);
          r++;
        }
        h.celda(0, r, '⚡ TOTAL', fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        h.celda(1, r, '', fondo: _XlsxColores.navy);
        for (var i = 0; i < nT; i++) {
          h.entero(cVend + i, r, totVendT[i], fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
          h.entero(cExist + i, r, totExistT[i], fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        }
        h.entero(cTotV, r, totV, fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        h.entero(cTotE, r, totE, fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        h.dinero(cIng, r, totIng, fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        h.dinero(cGan, r, totGan, fondo: _XlsxColores.navy, color: _XlsxColores.naranja, negrita: true);
        h.celda(cEst, r, '', fondo: _XlsxColores.navy);
        h.alto(r, 24);
        h.nota(0, r + 2, nCols,
            'ESTADO: AGOTADO = se vendió y no queda existencia · REPONER = queda menos '
            'de lo que se vendió en el período · SIN MOVIMIENTO = hay existencia pero '
            'no se vendió en el período.');
        h.anchos([
          30, 14,
          for (var i = 0; i < nT; i++) 13.0, 13,
          for (var i = 0; i < nT; i++) 13.0, 14,
          15, 15, 16,
        ]);
      }

      // ════════ Hoja 3: Ranking ════════
      {
        final h = _HojaXlsx(excel['Ranking']);
        const cab = [
          '#', 'Código', 'Producto', 'Marca', 'Modelo', 'Categoría',
          'Unidades', 'Precio Unit USD', 'Ingresos USD', 'Costo USD',
          'Ganancia USD', 'Margen %',
        ];
        h.titulo(0, cab.length, 'RANKING DE PRODUCTOS — TECNO LÍDER', subtitulo);
        for (var c = 0; c < cab.length; c++) {
          h.encabezado(c, 4, cab[c]);
        }
        var r = 5;
        for (var i = 0; i < ranking.length; i++) {
          final e = ranking[i];
          final fondo = i.isEven ? _XlsxColores.fila1 : _XlsxColores.fila2;
          final gan = e.total - e.costo;
          h.entero(0, r, i + 1, fondo: i < 3 ? _XlsxColores.amarillo : fondo, negrita: i < 3);
          h.celda(1, r, e.producto.codigo, fondo: fondo);
          h.celda(2, r, e.producto.nombre, fondo: fondo);
          h.celda(3, r, e.producto.marca, fondo: fondo);
          h.celda(4, r, e.producto.modelo, fondo: fondo);
          h.celda(5, r, e.producto.categoria, fondo: fondo);
          h.entero(6, r, e.unidades, fondo: fondo, negrita: true);
          h.dinero(7, r, e.producto.precioVenta, fondo: fondo);
          h.dinero(8, r, e.total, fondo: fondo);
          h.dinero(9, r, e.costo, fondo: fondo);
          h.dinero(10, r, gan, fondo: _XlsxColores.verdeClaro,
              color: _XlsxColores.verdeTexto, negrita: true);
          h.porcentaje(11, r, e.total > 0 ? gan / e.total : 0, fondo: fondo);
          r++;
        }
        h.anchos([6, 14, 34, 14, 18, 14, 10, 14, 14, 14, 14, 10]);
      }

      // ════════ Hoja 4: Por vendedor ════════
      // Una fila por cada combinación producto × vendedor.
      // Útil para tablas dinámicas y para calcular comisiones manuales.
      {
        final h = _HojaXlsx(excel['Por vendedor']);
        const cab = [
          'Producto', 'Código', 'Marca', 'Categoría',
          'Vendedor', 'Unidades', 'Monto USD',
        ];
        for (var c = 0; c < cab.length; c++) {
          h.encabezado(c, 0, cab[c]);
        }
        var r = 1;
        for (final e in ranking) {
          for (final v in e.vendedoresOrdenados) {
            final fondo = r.isEven ? _XlsxColores.fila2 : _XlsxColores.fila1;
            h.celda(0, r, e.producto.nombre, fondo: fondo);
            h.celda(1, r, e.producto.codigo, fondo: fondo);
            h.celda(2, r, e.producto.marca, fondo: fondo);
            h.celda(3, r, e.producto.categoria, fondo: fondo);
            h.celda(4, r, v.key, fondo: fondo);
            h.entero(5, r, v.value, fondo: fondo);
            h.dinero(6, r, e.montoPorVendedor[v.key] ?? 0, fondo: fondo);
            r++;
          }
        }
        h.anchos([34, 14, 14, 14, 22, 10, 14]);
      }

      // ════════ Hoja 5: Detalle (cada venta individual) ════════
      {
        final h = _HojaXlsx(excel['Detalle']);
        const cab = [
          'Fecha', 'Nro Factura', 'Cliente', 'Cédula',
          'Producto', 'Código', 'Marca', 'Categoría', 'IMEI',
          'Vendedor', 'Creador (cajero)', 'Tienda', 'Precio USD',
          'Costo USD', 'Ganancia USD',
        ];
        for (var c = 0; c < cab.length; c++) {
          h.encabezado(c, 0, cab[c]);
        }
        var r = 1;
        for (final e in ranking) {
          for (final v in e.ventas) {
            final fondo = r.isEven ? _XlsxColores.fila2 : _XlsxColores.fila1;
            final precio = (v['precio'] as num?)?.toDouble() ?? 0;
            final costo = (v['costo'] as num?)?.toDouble() ?? 0;
            h.celda(0, r, (v['fecha'] ?? '').toString(), fondo: fondo);
            h.celda(1, r, (v['nroFactura'] ?? '').toString(), fondo: fondo);
            h.celda(2, r, (v['cliente'] ?? '').toString(), fondo: fondo);
            h.celda(3, r, (v['cedula'] ?? '').toString(), fondo: fondo);
            h.celda(4, r, e.producto.nombre, fondo: fondo);
            h.celda(5, r, e.producto.codigo, fondo: fondo);
            h.celda(6, r, e.producto.marca, fondo: fondo);
            h.celda(7, r, e.producto.categoria, fondo: fondo);
            h.celda(8, r, (v['imei'] ?? '').toString(), fondo: fondo);
            h.celda(9, r, (v['vendedor'] ?? '').toString(), fondo: fondo);
            h.celda(10, r, (v['creador'] ?? '').toString(), fondo: fondo);
            h.celda(11, r, _nombreTienda((v['tienda'] ?? '').toString()), fondo: fondo);
            h.dinero(12, r, precio, fondo: fondo);
            h.dinero(13, r, costo, fondo: fondo);
            h.dinero(14, r, precio - costo, fondo: fondo);
            r++;
          }
        }
        h.anchos([18, 12, 26, 12, 30, 14, 12, 12, 18, 18, 18, 16, 12, 12, 13]);
      }

      final bytes = excel.encode();
      if (bytes == null) throw 'No se pudo generar el archivo';
      await descargarArchivo(
        Uint8List.fromList(bytes),
        'estadisticas_productos_$ts.xlsx',
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      );
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text('Excel generado correctamente'),
        backgroundColor: AppColors.statusGreen));
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text('Error al exportar Excel: $e'),
        backgroundColor: AppColors.statusRed));
    }
  }

  /// Nombre del modelo para el Excel: el nombre del producto (incluye
  /// la variante, p. ej. "HONOR PLAY 10 4/128"); si falta, marca+modelo.
  String _nombreModelo(Producto p) {
    final n = p.nombre.trim();
    if (n.isNotEmpty) return n;
    return _etiqueta(p);
  }

  String _etiqueta(Producto p) {
    if (p.modelo.isNotEmpty && p.modelo != 'N/A') {
      return '${p.marca} ${p.modelo}'.trim();
    }
    return p.nombre;
  }
}

class _StatsItem {
  final Producto producto;
  int unidades;
  double total;
  /// Costo de lo vendido (precio de costo del catálogo × unidades).
  double costo;
  /// Desglose: unidades vendidas por cada vendedor.
  /// Clave = nombre del vendedor (de `vendedorDeEquipo`/`vendedorDeItem`).
  /// Valor = cantidad de unidades que ese vendedor movió.
  /// Permite mostrar quién vendió cada producto y cuántas unidades de
  /// ese producto le tocan a cada uno en el ranking.
  final Map<String, int> unidadesPorVendedor;
  /// Desglose: monto USD generado por cada vendedor en este producto.
  final Map<String, double> montoPorVendedor;
  /// Detalle plano de cada venta individual (para la pestaña detallada
  /// y la exportación). Una entrada por unidad vendida.
  /// Cada item: {nroFactura, fecha, cliente, vendedor, creador, imei,
  ///             tienda, precio}.
  final List<Map<String, dynamic>> ventas;
  _StatsItem({
    required this.producto,
    this.unidades = 0,
    this.total = 0,
    this.costo = 0,
    Map<String, int>? unidadesPorVendedor,
    Map<String, double>? montoPorVendedor,
    List<Map<String, dynamic>>? ventas,
  })  : unidadesPorVendedor = unidadesPorVendedor ?? {},
        montoPorVendedor    = montoPorVendedor    ?? {},
        ventas              = ventas              ?? [];

  /// Devuelve la lista de vendedores ordenada por cantidad (desc).
  List<MapEntry<String, int>> get vendedoresOrdenados {
    final entries = unidadesPorVendedor.entries.toList()
      ..sort((a, b) => b.value.compareTo(a.value));
    return entries;
  }
}

// ════════════════════════════════════════════════════════════
//  Helpers de Excel con formato (Estadísticas de Productos)
// ════════════════════════════════════════════════════════════
//  Pequeña capa sobre el paquete `excel` para escribir celdas con
//  fondo, bordes y formato numérico sin repetir CellStyle en cada
//  llamada. Los colores siguen el reporte "Rentabilidad por tienda".
class _XlsxColores {
  static const navy = '#1B2A41';
  static const naranja = '#F5A524';
  static const blanco = '#FFFFFF';
  static const azul = '#1E88E5';
  static const teal = '#2E7D83';
  static const teal2 = '#3A8A96';
  static const verde = '#2E6B4F';
  static const coral = '#E8623A';
  static const gris = '#607D8B';
  static const morado = '#5E35B1';
  static const fila1 = '#EEF6FB';
  static const fila2 = '#FFFFFF';
  static const amarillo = '#FFF4B8';
  static const verdeClaro = '#E6F4EA';
  static const verdeTexto = '#1E7B34';
  static const azulClaro = '#DCEBFA';
  static const moradoClaro = '#EAE3F7';
  static const rojoClaro = '#FAD4D0';
  static const grisClaro = '#ECEFF1';
  static const textoGris = '#9E9E9E';
  static const borde = '#B0BEC5';
  /// Colores de la columna TIENDA, uno por tienda (se repiten).
  static const paleta = [
    '#1E88E5', '#26A69A', '#3949AB', '#8E24AA', '#F4511E', '#6D4C41',
  ];
}

class _HojaXlsx {
  final Sheet hoja;
  _HojaXlsx(this.hoja);

  static final _fmtDinero =
      NumFormat.custom(formatCode: r'"$"#,##0.00;[Red]-"$"#,##0.00');
  static final _fmtPorc = NumFormat.custom(formatCode: '0.0%');
  static final _fmtEntero = NumFormat.custom(formatCode: '#,##0');

  xl.Border get _borde => xl.Border(
      borderStyle: xl.BorderStyle.Thin,
      borderColorHex: ExcelColor.fromHexString(_XlsxColores.borde));

  CellStyle _estilo({
    String? fondo,
    String color = '#000000',
    bool negrita = false,
    HorizontalAlign alineado = HorizontalAlign.Left,
    NumFormat numFormat = NumFormat.standard_0,
    int? tamano,
    bool bordes = true,
    bool ajustar = false,
  }) =>
      CellStyle(
        backgroundColorHex:
            fondo == null ? ExcelColor.none : ExcelColor.fromHexString(fondo),
        fontColorHex: ExcelColor.fromHexString(color),
        bold: negrita,
        fontSize: tamano,
        horizontalAlign: alineado,
        verticalAlign: VerticalAlign.Center,
        textWrapping: ajustar ? TextWrapping.WrapText : null,
        numberFormat: numFormat,
        leftBorder: bordes ? _borde : null,
        rightBorder: bordes ? _borde : null,
        topBorder: bordes ? _borde : null,
        bottomBorder: bordes ? _borde : null,
      );

  CellIndex _i(int c, int r) =>
      CellIndex.indexByColumnRow(columnIndex: c, rowIndex: r);

  /// Combina c0..c1 × r0..r1 y escribe el valor con estilo en la celda
  /// inicial. `setMergedCellStyle` del paquete no siempre conserva el
  /// estilo (probado con excel 4.0.6); escribir después de combinar sí.
  void _combinar(int c0, int r0, int c1, int r1, String valor, CellStyle estilo) {
    if (c1 > c0 || r1 > r0) hoja.merge(_i(c0, r0), _i(c1, r1));
    hoja.updateCell(_i(c0, r0), TextCellValue(valor), cellStyle: estilo);
  }

  /// Título grande combinado (filas 0-1) + subtítulo combinado (fila 2).
  void titulo(int c0, int nCols, String texto, String subtitulo) {
    final fin = c0 + nCols - 1;
    _combinar(c0, 0, fin, 1, texto, _estilo(
        fondo: _XlsxColores.navy, color: _XlsxColores.blanco, negrita: true,
        tamano: 16, alineado: HorizontalAlign.Center, bordes: false));
    _combinar(c0, 2, fin, 2, subtitulo, _estilo(
        fondo: _XlsxColores.grisClaro, color: '#37474F', tamano: 10,
        alineado: HorizontalAlign.Center, bordes: false));
    hoja.setRowHeight(0, 22);
    hoja.setRowHeight(1, 22);
    hoja.setRowHeight(2, 18);
  }

  /// Encabezado de grupo combinado sobre las columnas c0..c1.
  void grupo(int c0, int c1, int r, String valor, String fondo) {
    _combinar(c0, r, c1, r, valor, _estilo(fondo: fondo,
        color: _XlsxColores.blanco, negrita: true,
        alineado: HorizontalAlign.Center));
  }

  void encabezado(int c, int r, String valor,
      {String fondo = _XlsxColores.navy, String texto = _XlsxColores.blanco}) {
    hoja.updateCell(_i(c, r), TextCellValue(valor), cellStyle: _estilo(
        fondo: fondo, color: texto, negrita: true,
        alineado: HorizontalAlign.Center, ajustar: true));
  }

  void celda(int c, int r, String valor,
      {String? fondo, String color = '#000000', bool negrita = false,
       bool centrado = false}) {
    hoja.updateCell(_i(c, r), TextCellValue(valor), cellStyle: _estilo(
        fondo: fondo, color: color, negrita: negrita,
        alineado: centrado ? HorizontalAlign.Center : HorizontalAlign.Left));
  }

  /// Entero centrado. `gris` atenúa los ceros para que resalten los datos.
  void entero(int c, int r, int valor,
      {String? fondo, String? color, bool negrita = false, bool gris = false}) {
    hoja.updateCell(_i(c, r), IntCellValue(valor), cellStyle: _estilo(
        fondo: fondo,
        color: color ?? (gris ? _XlsxColores.textoGris : '#000000'),
        negrita: negrita, alineado: HorizontalAlign.Center,
        numFormat: _fmtEntero));
  }

  void dinero(int c, int r, double valor,
      {String? fondo, String color = '#000000', bool negrita = false}) {
    hoja.updateCell(_i(c, r), DoubleCellValue(_redondear(valor)),
        cellStyle: _estilo(fondo: fondo, color: color, negrita: negrita,
            alineado: HorizontalAlign.Right, numFormat: _fmtDinero));
  }

  /// `valor` es una fracción (0.25 = 25%).
  void porcentaje(int c, int r, double valor,
      {String? fondo, String color = '#000000', bool negrita = false}) {
    hoja.updateCell(_i(c, r), DoubleCellValue(valor), cellStyle: _estilo(
        fondo: fondo, color: color, negrita: negrita,
        alineado: HorizontalAlign.Center, numFormat: _fmtPorc));
  }

  /// Texto explicativo combinado a lo ancho de la tabla.
  void nota(int c0, int r, int nCols, String valor) {
    _combinar(c0, r, c0 + nCols - 1, r, valor, _estilo(
        color: '#546E7A', tamano: 9, bordes: false, ajustar: true));
    hoja.setRowHeight(r, 30);
  }

  void alto(int r, double alto) => hoja.setRowHeight(r, alto);

  void anchos(List<num> anchos) {
    for (var c = 0; c < anchos.length; c++) {
      hoja.setColumnWidth(c, anchos[c].toDouble());
    }
  }

  static double _redondear(double v) => (v * 100).roundToDouble() / 100;
}

// ════════════════════════════════════════════════════════════
//  VENTANA DE TRASLADOS ENTRE TIENDAS
// ════════════════════════════════════════════════════════════
//  Permite enviar productos de una ubicación a otra:
//   · Para teléfonos (IMEI): cambia la ubicación del IMEI seleccionado
//   · Para no-teléfonos: ajusta la tienda del producto si se traslada
//     todo el stock; si es parcial, avisa al usuario que el modelo
//     actual no soporta stock partido entre tiendas.
//  Lleva bitácora histórica en la tabla `traslados`.
// ════════════════════════════════════════════════════════════
class VentanaTraslados extends StatefulWidget {
  const VentanaTraslados({super.key});
  @override
  State<VentanaTraslados> createState() => _VentanaTrasladosState();
}

class _VentanaTrasladosState extends State<VentanaTraslados> {
  List<Traslado> _traslados = [];
  bool _cargando = false;

  @override
  void initState() {
    super.initState();
    _cargar();
  }

  Future<void> _cargar() async {
    setState(() => _cargando = true);
    try {
      final raw = await _Api.get('traslados');
      _traslados = ((raw as List?) ?? [])
          .map((m) => Traslado.fromMap(m as Map<String, dynamic>))
          .toList();
    } catch (e) {
      debugPrint('[Traslados] error al cargar: $e');
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text('Error al cargar traslados: $e'),
          backgroundColor: AppColors.statusRed));
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.surfaceTintBlue,
      appBar: AppBar(
        title: const Text('Traslados entre tiendas'),
        actions: [
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: 'Actualizar',
            onPressed: _cargando ? null : _cargar),
        ],
      ),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: _abrirDialogoNuevo,
        icon: const Icon(Icons.local_shipping_outlined),
        label: const Text('Nuevo traslado'),
        backgroundColor: AppColors.primaryBlue,
      ),
      body: _cargando
          ? const Center(child: CircularProgressIndicator())
          : _traslados.isEmpty
              ? const Center(
                  child: Padding(
                    padding: EdgeInsets.all(32),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Icon(Icons.local_shipping_outlined,
                            size: 64, color: Colors.grey),
                        SizedBox(height: 16),
                        Text(
                          'No hay traslados registrados.\n\n'
                          'Pulsa "Nuevo traslado" para enviar un producto '
                          'de una tienda a otra.',
                          textAlign: TextAlign.center,
                          style: TextStyle(color: Colors.grey),
                        ),
                      ],
                    ),
                  ),
                )
              : ListView.separated(
                  padding: const EdgeInsets.all(8),
                  itemCount: _traslados.length,
                  separatorBuilder: (_, __) => const SizedBox(height: 6),
                  itemBuilder: (_, i) => _tileTraslado(_traslados[i]),
                ),
    );
  }

  Widget _tileTraslado(Traslado t) {
    final fechaStr = t.fecha == null ? '?'
        : '${t.fecha!.day.toString().padLeft(2,"0")}/'
          '${t.fecha!.month.toString().padLeft(2,"0")}/'
          '${t.fecha!.year}';
    return Card(
      child: ListTile(
        leading: CircleAvatar(
          backgroundColor: t.esTelefono
              ? AppColors.primaryBlue.withValues(alpha: 0.15)
              : AppColors.statusOrange.withValues(alpha: 0.15),
          child: Icon(
            t.esTelefono ? Icons.phone_android : Icons.inventory_2_outlined,
            color: t.esTelefono
                ? AppColors.primaryBlue : AppColors.statusOrange,
            size: 20),
        ),
        title: Text(t.productoNombre.isEmpty
            ? t.productoCodigo : t.productoNombre,
            style: const TextStyle(fontWeight: FontWeight.w600)),
        subtitle: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          const SizedBox(height: 2),
          Row(children: [
            Text('${t.tiendaOrigen.isEmpty ? "(sin asignar)" : t.tiendaOrigen}'),
            const Padding(
                padding: EdgeInsets.symmetric(horizontal: 6),
                child: Icon(Icons.arrow_forward, size: 14)),
            Text(t.tiendaDestino,
                style: const TextStyle(fontWeight: FontWeight.w600)),
          ]),
          Text(
              '$fechaStr · '
              '${t.esTelefono ? "IMEI ${t.imei}" : "${t.cantidad} und."}'
              '${t.usuario.isEmpty ? "" : " · por ${t.usuario}"}',
              style: const TextStyle(fontSize: 11, color: Colors.grey)),
          if (t.nota.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 2),
              child: Text('“${t.nota}”',
                  style: const TextStyle(
                      fontSize: 11, fontStyle: FontStyle.italic)),
            ),
        ]),
      ),
    );
  }

  /// Diálogo para crear un nuevo traslado. Pasos:
  ///  1. Cargar productos e IMEIs disponibles
  ///  2. Selector de producto + (si es teléfono) IMEI específico
  ///  3. Selector de tienda origen y destino
  ///  4. Confirmar → POST a /traslados + ajustes físicos
  Future<void> _abrirDialogoNuevo() async {
    // Cargar catálogo
    showDialog(
      context: context,
      barrierDismissible: false,
      builder: (_) => const Center(child: CircularProgressIndicator()),
    );
    List<Producto> productos = [];
    List<ImeiRegistro> imeis = [];
    List<String> tiendas = [];
    try {
      // Cargar productos, IMEIs y TIENDAS en paralelo desde el backend.
      // Antes leíamos tiendas de `ConfigSistema.tiendas` (cache local),
      // lo que ignoraba tiendas creadas por otros usuarios o insertadas
      // directamente en la BD. Ahora traemos la lista fresca cada vez.
      final results = await Future.wait([
        _Api.get('productos'),
        _Api.get('stock_imei'),
        _Api.get('tiendas'),
      ]);
      productos = ((results[0] as List?) ?? [])
          .map((m) => Producto.fromMap(m as Map<String, dynamic>))
          .where((p) => p.productoPadreCodigo.isEmpty)
          .toList();
      imeis = ((results[1] as List?) ?? [])
          .map((m) => ImeiRegistro.fromMap(m as Map<String, dynamic>))
          .where((i) => !i.vendido)
          .toList();
      // Cargar TODAS las tiendas activas del backend. También sumamos
      // las ubicaciones únicas presentes en los IMEIs por si algún IMEI
      // está en una ubicación histórica que no existe en la tabla
      // `tiendas`. Así el dropdown incluye TODOS los destinos posibles
      // aunque la tabla tiendas esté incompleta.
      final rawTiendas = ((results[2] as List?) ?? [])
          .map((m) {
            if (m is Map) {
              final nombre = (m['nombre'] ?? '').toString().trim();
              // Ignorar tiendas marcadas como inactivas (activa=0).
              final activa = m['activa'];
              final estaActiva = activa == null
                  || activa == 1 || activa == '1' || activa == true;
              return estaActiva ? nombre : '';
            }
            return '';
          })
          .where((n) => n.isNotEmpty)
          .toSet();
      // Sumar ubicaciones de los IMEIs (por si son históricas y no
      // están en la tabla `tiendas`).
      for (final i in imeis) {
        if (i.ubicacion.trim().isNotEmpty) rawTiendas.add(i.ubicacion.trim());
      }
      // Sumar tiendas de los productos no-teléfono.
      for (final p in productos) {
        if (p.tienda.trim().isNotEmpty) rawTiendas.add(p.tienda.trim());
      }
      tiendas = rawTiendas.toList()..sort();
      // Actualizar el cache global para las próximas ventanas
      ConfigSistema.tiendas = List<String>.from(tiendas);
    } catch (e) {
      if (mounted) {
        Navigator.pop(context); // cierra el loading
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
            content: Text('Error al cargar datos: $e'),
            backgroundColor: AppColors.statusRed));
      }
      return;
    }
    if (!mounted) return;
    Navigator.pop(context); // cierra loading

    if (tiendas.length < 2) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
          content: Text('Necesitas al menos 2 tiendas configuradas '
              'para hacer traslados.')));
      return;
    }

    // Estado del formulario
    Producto? prodSel;
    ImeiRegistro? imeiSel;
    int cantidad = 1;
    String? tiendaDestino;
    final notaCtrl = TextEditingController();

    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => StatefulBuilder(builder: (ctx, setS) {
        // Capturar en variable local para que Dart no pierda la
        // promoción de null-safety dentro del closure.
        final ps = prodSel;
        final esTel = ps != null && CategoriasProductos.usaIMEI(ps.categoria);
        // IMEIs disponibles para el producto seleccionado
        final imeisDelProd = ps == null ? <ImeiRegistro>[]
            : imeis.where((i) =>
                i.producto.codigo == ps.codigo).toList();
        // Tienda origen se infiere automáticamente
        String tiendaOrigen = '';
        if (esTel && imeiSel != null) {
          tiendaOrigen = imeiSel!.ubicacion;
        } else if (!esTel && ps != null) {
          tiendaOrigen = ps.tienda;
        }

        return AlertDialog(
          title: const Row(children: [
            Icon(Icons.local_shipping_outlined,
                color: AppColors.primaryBlue),
            SizedBox(width: 8),
            Text('Nuevo traslado'),
          ]),
          content: SizedBox(
            width: 480,
            child: SingleChildScrollView(
              child: Column(mainAxisSize: MainAxisSize.min, children: [
                // ── Selector de producto: búsqueda + scanner ────
                // Permite buscar por nombre o SKU. El botón de cámara
                // abre el escáner; al detectar un código de barras se
                // busca el producto por SKU exacto y se selecciona.
                Row(children: [
                  Expanded(child: Autocomplete<Producto>(
                    displayStringForOption: (p) =>
                        '${p.nombre} (${p.codigo})',
                    optionsBuilder: (tv) {
                      if (tv.text.isEmpty) return productos.take(20);
                      final q = tv.text.toLowerCase();
                      return productos.where((p) =>
                          p.nombre.toLowerCase().contains(q) ||
                          p.codigo.toLowerCase().contains(q) ||
                          p.marca.toLowerCase().contains(q));
                    },
                    fieldViewBuilder: (c, ctrl, node, _) => TextField(
                      controller: ctrl,
                      focusNode: node,
                      decoration: const InputDecoration(
                        labelText: 'Producto (nombre o SKU)',
                        hintText: 'Ej: REDMI-A5 o "Redmi A5"',
                        prefixIcon: Icon(Icons.search),
                      ),
                    ),
                    onSelected: (p) => setS(() {
                      prodSel = p;
                      imeiSel = null;
                      cantidad = 1;
                    }),
                  )),
                  const SizedBox(width: 6),
                  // Botón de escáner para SKU
                  IconButton.filledTonal(
                    icon: const Icon(Icons.qr_code_scanner),
                    tooltip: 'Escanear código de barras',
                    onPressed: () async {
                      await Navigator.push(context, MaterialPageRoute(
                        builder: (_) => ScannerPage(onDetect: (code) {
                          // Buscar por SKU exacto primero, luego por
                          // SKU que contenga el código escaneado.
                          final encontrado = productos.firstWhere(
                              (p) => p.codigo == code,
                              orElse: () => productos.firstWhere(
                                  (p) => p.codigo.contains(code),
                                  orElse: () => Producto(
                                      codigo: '', nombre: '', categoria: '',
                                      marca: '', modelo: '', tipo: '',
                                      precioCosto: 0, precioVenta: 0)));
                          if (encontrado.codigo.isEmpty) {
                            if (mounted) ScaffoldMessenger.of(context)
                                .showSnackBar(SnackBar(
                                    content: Text(
                                        'SKU "$code" no encontrado'),
                                    backgroundColor: AppColors.statusOrange));
                          } else {
                            setS(() {
                              prodSel = encontrado;
                              imeiSel = null;
                              cantidad = 1;
                            });
                            if (mounted) ScaffoldMessenger.of(context)
                                .showSnackBar(SnackBar(
                                    content: Text(
                                        '✓ ${encontrado.nombre}'),
                                    duration: const Duration(seconds: 1),
                                    backgroundColor: AppColors.statusGreen));
                          }
                        }),
                      ));
                    },
                  ),
                ]),
                if (prodSel != null) Padding(
                  padding: const EdgeInsets.only(top: 6),
                  child: Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(8),
                    decoration: BoxDecoration(
                      color: AppColors.statusGreen.withValues(alpha: 0.08),
                      borderRadius: BorderRadius.circular(6),
                    ),
                    child: Text(
                      '✓ ${prodSel!.nombre}  ·  SKU: ${prodSel!.codigo}'
                      '  ·  Categoría: ${prodSel!.categoria}',
                      style: const TextStyle(fontSize: 12,
                          fontWeight: FontWeight.w600),
                    ),
                  ),
                ),
                const SizedBox(height: 12),

                // ── Selector de IMEI (solo teléfonos) ────────
                if (esTel) ...[
                  if (imeisDelProd.isEmpty)
                    Container(
                      padding: const EdgeInsets.all(10),
                      decoration: BoxDecoration(
                        color: AppColors.statusOrange.withValues(alpha: 0.1),
                        borderRadius: BorderRadius.circular(8),
                      ),
                      child: const Row(children: [
                        Icon(Icons.warning_amber_rounded,
                            color: AppColors.statusOrange, size: 18),
                        SizedBox(width: 8),
                        Expanded(child: Text(
                            'No hay IMEIs disponibles de este producto.')),
                      ]),
                    )
                  else
                    DropdownButtonFormField<ImeiRegistro>(
                      value: imeiSel,
                      isExpanded: true,
                      decoration: const InputDecoration(
                        labelText: 'IMEI a trasladar',
                        prefixIcon: Icon(Icons.fingerprint),
                      ),
                      items: imeisDelProd.map((i) => DropdownMenuItem(
                        value: i,
                        child: Text(
                          '${i.imei} · '
                          '${i.ubicacion.isEmpty ? "?" : i.ubicacion}',
                          overflow: TextOverflow.ellipsis,
                        ),
                      )).toList(),
                      onChanged: (v) => setS(() => imeiSel = v),
                    ),
                  const SizedBox(height: 12),
                ],

                // ── Cantidad (solo no-teléfonos) ─────────────
                if (!esTel && prodSel != null) ...[
                  TextField(
                    decoration: InputDecoration(
                      labelText: 'Cantidad a trasladar',
                      prefixIcon: const Icon(Icons.numbers),
                      helperText: 'Stock disponible: ${prodSel!.stockManual}',
                    ),
                    keyboardType: TextInputType.number,
                    controller: TextEditingController(
                        text: cantidad.toString()),
                    onChanged: (v) => cantidad = int.tryParse(v) ?? 1,
                  ),
                  const SizedBox(height: 12),
                ],

                // ── Tienda origen (informativo) ──────────────
                if (prodSel != null) Container(
                  padding: const EdgeInsets.all(10),
                  decoration: BoxDecoration(
                    color: AppColors.surfaceTintBlue,
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: Row(children: [
                    const Icon(Icons.store_outlined,
                        color: AppColors.brandBlue, size: 18),
                    const SizedBox(width: 8),
                    Expanded(child: Text(
                        'Origen: '
                        '${tiendaOrigen.isEmpty ? "(sin asignar)" : tiendaOrigen}',
                        style: const TextStyle(fontWeight: FontWeight.w600))),
                  ]),
                ),
                const SizedBox(height: 12),

                // ── Selector tienda destino ──────────────────
                DropdownButtonFormField<String>(
                  value: tiendaDestino,
                  isExpanded: true,
                  decoration: const InputDecoration(
                    labelText: 'Tienda destino',
                    prefixIcon: Icon(Icons.flag_outlined),
                  ),
                  items: tiendas
                      .where((t) => t != tiendaOrigen)
                      .map((t) => DropdownMenuItem(
                          value: t, child: Text(t)))
                      .toList(),
                  onChanged: (v) => setS(() => tiendaDestino = v),
                ),
                const SizedBox(height: 12),

                // ── Nota opcional ────────────────────────────
                TextField(
                  controller: notaCtrl,
                  maxLines: 2,
                  decoration: const InputDecoration(
                    labelText: 'Nota (opcional)',
                    hintText: 'Ej: Pedido del cliente Juan Pérez',
                    prefixIcon: Icon(Icons.note_outlined),
                  ),
                ),
              ]),
            ),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(ctx, false),
                child: const Text('Cancelar')),
            ElevatedButton.icon(
              icon: const Icon(Icons.send, size: 18),
              label: const Text('Trasladar'),
              onPressed: () => Navigator.pop(ctx, true),
            ),
          ],
        );
      }),
    );

    if (ok != true) return;

    // ── Validar ─────────────────────────────────────────────
    if (prodSel == null) {
      _toast('Selecciona un producto'); return;
    }
    if (tiendaDestino == null || tiendaDestino!.isEmpty) {
      _toast('Selecciona la tienda destino'); return;
    }
    final esTel = CategoriasProductos.usaIMEI(prodSel!.categoria);
    if (esTel && imeiSel == null) {
      _toast('Selecciona el IMEI a trasladar'); return;
    }
    if (!esTel && cantidad <= 0) {
      _toast('Cantidad debe ser mayor a 0'); return;
    }
    if (!esTel && cantidad > prodSel!.stockManual) {
      _toast('No hay suficiente stock. '
          'Disponible: ${prodSel!.stockManual}'); return;
    }

    final tiendaOrigen = esTel
        ? (imeiSel?.ubicacion ?? '')
        : prodSel!.tienda;
    if (tiendaOrigen == tiendaDestino) {
      _toast('Origen y destino son iguales'); return;
    }

    // ── Aplicar el traslado ─────────────────────────────────
    await _aplicarTraslado(
      producto: prodSel!,
      imei: imeiSel,
      cantidad: cantidad,
      tiendaOrigen: tiendaOrigen,
      tiendaDestino: tiendaDestino!,
      nota: notaCtrl.text.trim(),
    );
  }

  void _toast(String msg) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(msg),
        backgroundColor: AppColors.statusOrange));
  }

  /// Genera un sufijo corto y limpio a partir del nombre de la tienda
  /// para usarlo en el SKU. Toma las iniciales/letras alfanuméricas
  /// y deja un máximo de 8 caracteres en mayúsculas.
  /// Ejemplo: "Tecno Líder Principal" → "TLP"
  ///          "Sucursal Norte"        → "SN"
  ///          "Local 2"               → "L2"
  String _sufijoTienda(String tienda) {
    final palabras = tienda.split(RegExp(r'\s+'))
        .where((p) => p.isNotEmpty).toList();
    if (palabras.isEmpty) return 'T';
    if (palabras.length == 1) {
      // Una sola palabra: tomar primeras letras alfanuméricas
      final limpio = palabras.first
          .replaceAll(RegExp(r'[^a-zA-Z0-9]'), '')
          .toUpperCase();
      return limpio.length > 8 ? limpio.substring(0, 8) : limpio;
    }
    // Múltiples palabras: iniciales
    var sufijo = palabras
        .map((p) => p.replaceAll(RegExp(r'[^a-zA-Z0-9]'), ''))
        .where((p) => p.isNotEmpty)
        .map((p) => p[0].toUpperCase())
        .join();
    if (sufijo.isEmpty) sufijo = 'T';
    return sufijo.length > 8 ? sufijo.substring(0, 8) : sufijo;
  }

  /// Ejecuta el traslado de forma ATÓMICA llamando al endpoint
  /// `traslado_aplicar` del backend, que hace todo en una transacción
  /// SQL: actualiza el IMEI o producto y registra la bitácora. Si algo
  /// falla, hace rollback automáticamente — no quedan datos a medias.
  ///
  /// Esto resuelve el problema histórico de tener que hacer 2-3 PUTs
  /// secuenciales donde uno podía fallar dejando inconsistencia.
  Future<void> _aplicarTraslado({
    required Producto producto,
    ImeiRegistro? imei,
    required int cantidad,
    required String tiendaOrigen,
    required String tiendaDestino,
    required String nota,
  }) async {
    final esTel = imei != null;

    // Mostrar indicador de carga
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Row(children: [
            const SizedBox(width: 16, height: 16,
                child: CircularProgressIndicator(
                    strokeWidth: 2, color: Colors.white)),
            const SizedBox(width: 12),
            const Text('Aplicando traslado...'),
          ]),
          duration: const Duration(seconds: 30)));
    }

    try {
      // ── Construir el payload para el endpoint atómico ──
      final payload = <String, dynamic>{
        'tipo': esTel ? 'imei' : 'producto',
        'producto_codigo': producto.codigo,
        'tienda_origen': tiendaOrigen,
        'tienda_destino': tiendaDestino,
        'nota': nota,
        'usuario': usuarioSesion?.correo ?? '',
      };
      if (esTel) {
        payload['imei'] = imei.imei;
        payload['cantidad'] = 1;
      } else {
        payload['cantidad'] = cantidad;
      }

      debugPrint('[Traslado] Enviando: $payload');

      // ── Llamar al endpoint atómico ──
      // El backend hace TODO en transacción: cambio físico + bitácora.
      // Si responde OK, está garantizado que todo se aplicó.
      // Si falla, hace ROLLBACK — no queda nada a medias.
      final resp = await _Api.post('traslado_aplicar', payload);
      debugPrint('[Traslado] Respuesta: $resp');

      // ── Actualizar listas locales INMEDIATAMENTE ──
      // No esperamos al recargar desde servidor para que la UI muestre
      // el cambio al instante.
      if (esTel) {
        final idxLocal = stockImeiGlobal.indexWhere((x) => x.imei == imei.imei);
        if (idxLocal != -1) {
          stockImeiGlobal[idxLocal].ubicacion = tiendaDestino;
        }
      }

      // ── Refrescar listas globales desde el servidor ──
      // Aunque ya actualizamos lo más urgente en memoria, hacemos un
      // refresh completo para mantener consistencia con la BD.
      await _refrescarListasGlobales();

      if (!mounted) return;
      ScaffoldMessenger.of(context).hideCurrentSnackBar();
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Row(children: [
            const Icon(Icons.check_circle, color: Colors.white, size: 18),
            const SizedBox(width: 8),
            Expanded(child: Text(
                esTel
                    ? '✅ ${producto.nombre} (IMEI ${imei.imei}) trasladado a $tiendaDestino'
                    : '✅ $cantidad × ${producto.nombre} trasladado a $tiendaDestino')),
          ]),
          backgroundColor: AppColors.statusGreen,
          duration: const Duration(seconds: 4)));

      _cargar();
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).hideCurrentSnackBar();

      // ── Traducir errores técnicos a mensajes claros ──
      String mensaje;
      final err = e.toString();
      if (err.contains('404') &&
          (err.contains('traslado_aplicar') || err.contains('Recurso'))) {
        // El endpoint nuevo no está instalado en el servidor.
        // Avisamos al usuario para que actualice el backend.
        mensaje = 'El endpoint traslado_aplicar no está instalado en el '
            'servidor. Pídele al administrador que suba el archivo '
            'traslado_aplicar.php a /tecnolider/endpoints/';
      } else if (err.contains('IMEI') && err.contains('no encontrado')) {
        mensaje = 'El IMEI no existe en la base de datos. '
            'Refresca la pantalla e intenta de nuevo.';
      } else if (err.contains('ya está vendido')) {
        mensaje = 'Este IMEI ya está marcado como vendido. '
            'No se puede trasladar.';
      } else if (err.contains('No hay suficiente stock')) {
        mensaje = err.replaceAll('Exception: ', '');
      } else if (err.contains('Origen y destino')) {
        mensaje = 'La tienda de origen y destino no pueden ser iguales.';
      } else if (err.contains('Timeout') || err.contains('SocketException')) {
        mensaje = 'Error de conexión. Verifica tu internet e intenta de nuevo.';
      } else if (err.contains('500')) {
        // NO asumir que el endpoint no está instalado — hay muchas
        // causas de error 500 (BD caída, columna faltante, permisos,
        // etc.). Mostrar el detalle real que devuelve el servidor
        // (viene en el campo `detalles` de la respuesta JSON) para
        // poder diagnosticar. Solo si el detalle está vacío se
        // asume problema de instalación.
        final limpio = err.replaceAll('Exception: ', '');
        mensaje = limpio.isNotEmpty
            ? 'Error del servidor: $limpio'
            : 'Error del servidor. Reintente en unos segundos.';
      } else {
        mensaje = err.length > 200
            ? '${err.substring(0, 200)}...'
            : err.replaceAll('Exception: ', '');
      }

      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Row(children: [
            const Icon(Icons.error_outline, color: Colors.white, size: 18),
            const SizedBox(width: 8),
            Expanded(child: Text('Error al trasladar: $mensaje')),
          ]),
          backgroundColor: AppColors.statusRed,
          duration: const Duration(seconds: 8)));
    }
  }


  /// Recarga `catalogoGlobal` y `stockImeiGlobal` desde el servidor.
  /// Se llama tras un traslado para que las demás pantallas (Inventario,
  /// Catálogo, Gestión de IMEIs, etc.) reflejen los cambios al instante
  /// sin que el usuario tenga que refrescar manualmente.
  Future<void> _refrescarListasGlobales() async {
    try {
      final results = await Future.wait([
        _Api.get('productos'),
        _Api.get('stock_imei'),
      ]);
      // 1) Productos primero — ImeiRegistro.fromMap los usa
      final rawP = results[0];
      catalogoGlobal = ((rawP as List?) ?? [])
          .map((m) => Producto.fromMap(m as Map<String, dynamic>))
          .toList();
      // 2) IMEIs
      final rawI = results[1];
      stockImeiGlobal = ((rawI as List?) ?? [])
          .map((m) => ImeiRegistro.fromMap(m as Map<String, dynamic>))
          .toList();
      // 3) Recalcular stockTotal de cada producto
      for (final p in catalogoGlobal) {
        if (CategoriasProductos.usaIMEI(p.categoria)) {
          p.stockTotal = stockImeiGlobal.where((i) =>
              i.producto.codigo == p.codigo && !i.vendido).length;
        } else {
          p.stockTotal = p.stockManual;
        }
      }
      debugPrint('[Traslado] Listas globales refrescadas: '
          '${catalogoGlobal.length} productos, '
          '${stockImeiGlobal.length} IMEIs');
    } catch (e) {
      debugPrint('[Traslado] No se pudo refrescar listas globales: $e');
    }
  }
}

