// ════════════════════════════════════════════════════════════
//  CELDAS EDITABLES PARA DATATABLES
// ════════════════════════════════════════════════════════════
//  El problema de TextFormField con initialValue es que solo lo
//  aplica en el primer build. Si el valor externo cambia (como
//  al llenar la tabla automáticamente desde la BD), el campo se
//  queda con el valor vacío del primer build.
//
//  Estos widgets usan un controller propio y comparan el valor
//  externo con el actual del controller; sincronizan SOLO cuando
//  hay diferencia real, sin perder el cursor mientras el usuario
//  está escribiendo.
// ════════════════════════════════════════════════════════════

/// Celda de texto editable inline para nombres, SKUs y otros campos
/// de texto en las listas de precios. Versión texto del
/// _CeldaPrecioInline. Mantiene su propio TextEditingController y
/// solo actualiza al padre cuando hay cambio real.
class _CeldaTextoInline extends StatefulWidget {
  final String valor;
  final ValueChanged<String> onCambio;
  final double fontSize;
  final FontWeight fontWeight;
  final Color color;
  const _CeldaTextoInline({
    super.key,
    required this.valor,
    required this.onCambio,
    this.fontSize = 12,
    this.fontWeight = FontWeight.normal,
    this.color = Colors.black87,
  });
  @override
  State<_CeldaTextoInline> createState() => _CeldaTextoInlineState();
}

class _CeldaTextoInlineState extends State<_CeldaTextoInline> {
  late final TextEditingController _ctrl;
  late final FocusNode _focus;

  @override
  void initState() {
    super.initState();
    _ctrl = TextEditingController(text: widget.valor);
    _focus = FocusNode();
  }

  @override
  void didUpdateWidget(_CeldaTextoInline old) {
    super.didUpdateWidget(old);
    if (old.valor != widget.valor && !_focus.hasFocus) {
      if (_ctrl.text != widget.valor) _ctrl.text = widget.valor;
    }
  }

  @override
  void dispose() {
    _ctrl.dispose();
    _focus.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return TextField(
      controller: _ctrl,
      focusNode: _focus,
      style: TextStyle(
          fontSize: widget.fontSize,
          fontWeight: widget.fontWeight,
          color: widget.color),
      decoration: const InputDecoration(
        isDense: true,
        border: InputBorder.none,
        contentPadding: EdgeInsets.symmetric(vertical: 2, horizontal: 0),
      ),
      onChanged: widget.onCambio,
    );
  }
}

/// Widget de celda con TextField inline para editar precios en las
/// listas de precios. Permite que el admin/dueño escriba el precio
/// directamente sin tener que abrir un diálogo. Guarda el cambio en
/// cuanto el usuario teclea (con un pequeño debounce visual: el padre
/// recibe el nuevo valor en cada keystroke).
class _CeldaPrecioInline extends StatefulWidget {
  final double valor;
  final String moneda;
  final ValueChanged<double> onCambio;
  const _CeldaPrecioInline({
    super.key,
    required this.valor,
    required this.moneda,
    required this.onCambio,
  });
  @override
  State<_CeldaPrecioInline> createState() => _CeldaPrecioInlineState();
}

class _CeldaPrecioInlineState extends State<_CeldaPrecioInline> {
  late final TextEditingController _ctrl;
  late final FocusNode _focus;

  String _fmt(double v) => v == 0 ? '' : v.toStringAsFixed(2);

  @override
  void initState() {
    super.initState();
    _ctrl = TextEditingController(text: _fmt(widget.valor));
    _focus = FocusNode();
  }

  @override
  void didUpdateWidget(_CeldaPrecioInline old) {
    super.didUpdateWidget(old);
    // Solo refrescamos desde fuera si el usuario no está tecleando
    // (sin foco) para no interrumpirlo.
    if (old.valor != widget.valor && !_focus.hasFocus) {
      final nuevo = _fmt(widget.valor);
      if (_ctrl.text != nuevo) _ctrl.text = nuevo;
    }
  }

  @override
  void dispose() {
    _ctrl.dispose();
    _focus.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 4),
      child: Row(mainAxisAlignment: MainAxisAlignment.end, children: [
        Text('${widget.moneda} ',
            style: const TextStyle(
                fontSize: 11, color: Colors.grey, fontWeight: FontWeight.w500)),
        Expanded(
          child: TextField(
            controller: _ctrl,
            focusNode: _focus,
            textAlign: TextAlign.right,
            keyboardType: const TextInputType.numberWithOptions(decimal: true),
            style: const TextStyle(
                fontSize: 12,
                fontWeight: FontWeight.bold,
                color: AppColors.primaryBlue),
            decoration: const InputDecoration(
              isDense: true,
              border: InputBorder.none,
              hintText: '0.00',
              hintStyle: TextStyle(
                  fontSize: 12, color: Colors.grey,
                  fontWeight: FontWeight.normal),
              contentPadding: EdgeInsets.symmetric(vertical: 4, horizontal: 2),
            ),
            onChanged: (v) {
              final n = double.tryParse(v.replaceAll(',', '.')) ?? 0;
              widget.onCambio(n);
            },
          ),
        ),
      ]),
    );
  }
}

class _CeldaNumerica extends StatefulWidget {
  final double value;
  final ValueChanged<double> onChanged;
  final double width;
  final double fontSize;
  final int decimales;
  const _CeldaNumerica({
    required this.value,
    required this.onChanged,
    this.width = 72,
    this.fontSize = 11,
    this.decimales = 2,
  });
  @override
  State<_CeldaNumerica> createState() => _CeldaNumericaState();
}

class _CeldaNumericaState extends State<_CeldaNumerica> {
  late final TextEditingController _ctrl;
  late final FocusNode _focus;

  String _formatear(double v) =>
      v == 0 ? '' : v.toStringAsFixed(widget.decimales);

  @override
  void initState() {
    super.initState();
    _ctrl = TextEditingController(text: _formatear(widget.value));
    _focus = FocusNode();
  }

  @override
  void didUpdateWidget(_CeldaNumerica old) {
    super.didUpdateWidget(old);
    // Solo actualizamos si el valor externo cambió Y el campo no
    // está siendo editado por el usuario (sin foco). Así no
    // interrumpimos a alguien escribiendo.
    if (old.value != widget.value && !_focus.hasFocus) {
      final nuevo = _formatear(widget.value);
      if (_ctrl.text != nuevo) {
        _ctrl.text = nuevo;
      }
    }
  }

  @override
  void dispose() {
    _ctrl.dispose();
    _focus.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: widget.width,
      child: TextField(
        controller: _ctrl,
        focusNode: _focus,
        style: TextStyle(fontSize: widget.fontSize),
        keyboardType: const TextInputType.numberWithOptions(decimal: true),
        decoration: const InputDecoration(
          isDense: true, border: InputBorder.none,
          contentPadding: EdgeInsets.symmetric(horizontal: 4, vertical: 2)),
        onChanged: (v) => widget.onChanged(double.tryParse(v) ?? 0),
      ),
    );
  }
}

