    this.width = 120,
  });
  @override
  State<_CeldaTexto> createState() => _CeldaTextoState();
}

class _CeldaTextoState extends State<_CeldaTexto> {
  late final TextEditingController _ctrl;
  late final FocusNode _focus;

  @override
  void initState() {
    super.initState();
    _ctrl = TextEditingController(text: widget.value);
    _focus = FocusNode();
  }

  @override
  void didUpdateWidget(_CeldaTexto old) {
    super.didUpdateWidget(old);
    if (old.value != widget.value && !_focus.hasFocus) {
      if (_ctrl.text != widget.value) {
        _ctrl.text = widget.value;
      }
    }
  }

  @override
  void dispose() {
    _ctrl.dispose();
    _focus.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: widget.width,
      child: TextField(
        controller: _ctrl,
        focusNode: _focus,
        style: const TextStyle(fontSize: 11),
        decoration: const InputDecoration(
          isDense: true, border: InputBorder.none,
          contentPadding: EdgeInsets.symmetric(horizontal: 4, vertical: 2)),
        onChanged: widget.onChanged,
      ),
    );
  }
}

// ═══════════════════════════════════════════════════════════════════
//  BLUETOOTH PRINTER SERVICE — Módulo autocontenido para Flutter
//  ──────────────────────────────────────────────────────────────────
//  Servicio completo de impresión térmica vía Bluetooth Low Energy
//  para Android e iOS. Soporta impresoras ESC/POS de 58mm y 80mm.
//
//  CONVIVE con la clase ImpresoraBT original (mucho más arriba en
//  este archivo). Se diferencia en:
//    · Persistencia con claves distintas en SharedPreferences.
//    · API más simple: `BluetoothPrinter.imprimir(bytes)` hace todo.
//    · Diagnóstico detallado en `ultimoDiagnostico`.
//
//  USO BÁSICO:
//   await BluetoothPrinter.solicitarPermisos();
//   await BluetoothPrinter.cargarPreferida();     // ya se hace en main()
//   final dispositivos = await BluetoothPrinter.escanearDispositivos();
//   await BluetoothPrinter.conectar(dispositivos.first);
//   await BluetoothPrinter.enviarBytes([0x1B, 0x40, ...]);
// ═══════════════════════════════════════════════════════════════════

class BluetoothPrinter {
  // ═══════════════════════════════════════════════════════════════
  //  CONFIGURACIÓN
  // ═══════════════════════════════════════════════════════════════

  /// UUIDs conocidos de characteristics de impresoras térmicas chinas.
  /// Probamos en orden de preferencia. La mayoría exponen uno de estos.
  /// Si no encuentra ninguno coincidente, usa el primer characteristic
  /// con write disponible.
  static const List<String> _uuidsPreferidos = [
    '00002af1-0000-1000-8000-00805f9b34fb', // SPP write estándar
    '0000ff02-0000-1000-8000-00805f9b34fb', // Common Chinese printers
    '49535343-8841-43f4-a8d4-ecbe34729bb3', // Microchip RN4870/71
    '0000ffe1-0000-1000-8000-00805f9b34fb', // HC-05/HC-06 derivative
    '0000fee7-0000-1000-8000-00805f9b34fb', // Tencent / generic
  ];

  // ═══════════════════════════════════════════════════════════════
  //  ESTADO
  // ═══════════════════════════════════════════════════════════════

  /// Identificador del dispositivo BLE preferido (en memoria + disco).
  static String? macImpresoraPreferida;

  /// Nombre amigable de la impresora BLE preferida (en memoria + disco).
  static String? nombreImpresoraPreferida;

  /// Ancho del papel en milímetros (58 ó 80). Se usa para calcular
  /// el ancho en caracteres al generar comandos ESC/POS.
  static int anchoPapel = 80;

  /// Dispositivo actualmente conectado (caché en memoria).
  static BluetoothDevice? _dispositivoActual;

  /// Characteristic GATT donde escribimos los bytes ESC/POS.
  static BluetoothCharacteristic? _caracteristicaEscritura;

  /// Log estructurado del último intento (escaneo/conexión/envío).
  /// Útil para mostrar al usuario "qué pasó" cuando algo falla.
  static List<String> ultimoDiagnostico = <String>[];

  static void _log(String msg) {
    debugPrint('[BTPrinter] $msg');
    ultimoDiagnostico.add(msg);
    if (ultimoDiagnostico.length > 200) {
      ultimoDiagnostico.removeRange(0, ultimoDiagnostico.length - 200);
    }
  }

  // ═══════════════════════════════════════════════════════════════
  //  PERMISOS Y ESTADO DEL BLUETOOTH
  // ═══════════════════════════════════════════════════════════════

  /// Solicita los permisos runtime necesarios para Bluetooth.
  /// Si ya están concedidos, no muestra nada y retorna true.
  static Future<bool> solicitarPermisos() async {
    if (kIsWeb) return false;
    if (!Platform.isAndroid && !Platform.isIOS) return false;

    if (Platform.isIOS) {
      // iOS pide permiso vía Info.plist al primer uso del Bluetooth
      // — no hace falta solicitar manualmente.
      return true;
    }

    // Verificar si YA están concedidos antes de molestar al usuario.
    final scanYa = await Permission.bluetoothScan.status;
    final connectYa = await Permission.bluetoothConnect.status;
    if (scanYa.isGranted && connectYa.isGranted) {
      _log('Permisos ya concedidos previamente.');
      return true;
    }

    // Android: pedir permisos según versión
    final scan = await Permission.bluetoothScan.request();
    final connect = await Permission.bluetoothConnect.request();
    final location = await Permission.locationWhenInUse.request();

    final ok = scan.isGranted && connect.isGranted;
    _log('Permisos: scan=${scan.name} connect=${connect.name} '
        'location=${location.name} → ${ok ? "OK" : "DENEGADOS"}');
    return ok;
  }

  /// Variante que muestra un diálogo EXPLICATIVO antes de invocar al SO.
  /// Sube la tasa de aceptación de permisos porque el usuario entiende
  /// para qué se le piden.
  ///
  /// FLUJO:
  ///   1. Si ya están concedidos → retorna true sin diálogos.
  ///   2. Si están denegados permanentemente → diálogo "Abrir ajustes".
  ///   3. Si nunca se preguntaron → diálogo explicativo + SO prompt.
  static Future<bool> solicitarPermisosConExplicacion(
      BuildContext context) async {
    if (kIsWeb) return false;
    if (!Platform.isAndroid && !Platform.isIOS) return false;
    if (Platform.isIOS) return true;

    final scanYa = await Permission.bluetoothScan.status;
    final connectYa = await Permission.bluetoothConnect.status;

    // 1) Ya concedidos
    if (scanYa.isGranted && connectYa.isGranted) {
      return true;
    }

    // 2) Denegados permanentemente
    if (scanYa.isPermanentlyDenied || connectYa.isPermanentlyDenied) {
      if (!context.mounted) return false;
      final irAAjustes = await showDialog<bool>(
        context: context,
        builder: (c) => AlertDialog(
          icon: const Icon(Icons.bluetooth_disabled,
              color: AppColors.statusRed, size: 40),
          title: const Text('Permisos bloqueados'),
          content: const Text(
            'El acceso a Bluetooth fue denegado previamente.\n\n'
            'Para usar la impresora térmica habilítalos manualmente '
            'desde los ajustes del sistema:\n\n'
            '  Ajustes → Apps → Tecno Líder → Permisos\n'
            '  Activar: Dispositivos cercanos / Bluetooth\n'
            '  Activar: Ubicación\n\n'
            '¿Abrir los ajustes ahora?',
            style: TextStyle(fontSize: 13),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(c, false),
                child: const Text('Cancelar')),
            ElevatedButton.icon(
              icon: const Icon(Icons.settings, size: 18),
              label: const Text('Abrir ajustes'),
              style: ElevatedButton.styleFrom(
                  backgroundColor: AppColors.royalBlue,
                  foregroundColor: Colors.white),
              onPressed: () => Navigator.pop(c, true),
            ),
          ],
        ),
      );
      if (irAAjustes == true) {
        await openAppSettings();
      }
      final scanFinal = await Permission.bluetoothScan.status;
      final connectFinal = await Permission.bluetoothConnect.status;
      return scanFinal.isGranted && connectFinal.isGranted;
    }

    // 3) Mostrar diálogo explicativo antes de invocar al SO
    if (!context.mounted) return false;
    final continuar = await showDialog<bool>(
      context: context,
      barrierDismissible: false,
      builder: (c) => AlertDialog(
        shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16)),
        icon: Container(
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: AppColors.royalBlue.withValues(alpha: 0.1),
            shape: BoxShape.circle,
          ),
          child: const Icon(Icons.bluetooth_searching,
              color: AppColors.royalBlue, size: 44),
        ),
        title: const Text(
          'Permisos de Bluetooth',
          textAlign: TextAlign.center,
        ),
        content: const Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'Para conectar la impresora térmica, la app necesita:',
              style: TextStyle(fontSize: 13),
            ),
            SizedBox(height: 14),
            Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Icon(Icons.bluetooth, color: AppColors.royalBlue, size: 24),
              SizedBox(width: 10),
              Expanded(child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('Bluetooth',
                      style: TextStyle(
                          fontWeight: FontWeight.bold, fontSize: 13)),
                  Text('Para detectar y conectar la impresora.',
                      style: TextStyle(
                          fontSize: 11.5, color: AppColors.textSecondary)),
                ],
              )),
            ]),
            SizedBox(height: 10),
            Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Icon(Icons.location_on_outlined,
                  color: AppColors.royalBlue, size: 24),
              SizedBox(width: 10),
              Expanded(child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('Ubicación',
                      style: TextStyle(
                          fontWeight: FontWeight.bold, fontSize: 13)),
                  Text(
                      'Android la exige para escanear dispositivos Bluetooth. '
                      'No registramos ni enviamos tu ubicación.',
                      style: TextStyle(
                          fontSize: 11.5, color: AppColors.textSecondary)),
                ],
              )),
            ]),
          ],
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(c, false),
              child: const Text('Ahora no')),
          ElevatedButton.icon(
            icon: const Icon(Icons.check_circle_outline, size: 18),
            label: const Text('Continuar'),
            style: ElevatedButton.styleFrom(
                backgroundColor: AppColors.royalBlue,
                foregroundColor: Colors.white),
            onPressed: () => Navigator.pop(c, true),
          ),
        ],
      ),
    );

    if (continuar != true) return false;

    final ok = await solicitarPermisos();

    // Manejo final: si quedaron permanentemente denegados
    if (!ok && context.mounted) {
      final scanDespues = await Permission.bluetoothScan.status;
      final connectDespues = await Permission.bluetoothConnect.status;
      if (scanDespues.isPermanentlyDenied ||
          connectDespues.isPermanentlyDenied) {
        final irAAjustes = await showDialog<bool>(
          context: context,
          builder: (c) => AlertDialog(
            icon: const Icon(Icons.warning_amber_rounded,
                color: AppColors.statusOrange, size: 40),
            title: const Text('Permisos necesarios'),
            content: const Text(
              'Sin permisos de Bluetooth la impresora no funcionará.\n\n'
              'Puedes habilitarlos manualmente desde los ajustes del sistema.',
              style: TextStyle(fontSize: 13),
            ),
            actions: [
              TextButton(
                  onPressed: () => Navigator.pop(c, false),
                  child: const Text('Más tarde')),
              ElevatedButton.icon(
                icon: const Icon(Icons.settings, size: 18),
                label: const Text('Abrir ajustes'),
                style: ElevatedButton.styleFrom(
                    backgroundColor: AppColors.royalBlue,
                    foregroundColor: Colors.white),
                onPressed: () => Navigator.pop(c, true),
              ),
            ],
          ),
        );
        if (irAAjustes == true) {
          await openAppSettings();
        }
      }
    }

    return ok;
  }

  /// Verifica si el adaptador Bluetooth del teléfono está encendido.
  static Future<bool> estaBluetoothActivo() async {
    if (kIsWeb) return false;
    if (!Platform.isAndroid && !Platform.isIOS) return false;
    try {
      final estado = await FlutterBluePlus.adapterState.first
          .timeout(const Duration(seconds: 2),
              onTimeout: () => BluetoothAdapterState.unknown);
      return estado == BluetoothAdapterState.on;
    } catch (_) {
      return false;
    }
  }

  /// Intenta encender el Bluetooth (solo Android — iOS no lo permite).
  static Future<bool> intentarEncenderBluetooth() async {
    if (!Platform.isAndroid) return await estaBluetoothActivo();
    try {
      await FlutterBluePlus.turnOn();
      await Future.delayed(const Duration(milliseconds: 500));
      return await estaBluetoothActivo();
    } catch (e) {
      _log('turnOn falló: $e');
      return false;
    }
  }

  // ═══════════════════════════════════════════════════════════════
  //  ESCANEO DE DISPOSITIVOS
  // ═══════════════════════════════════════════════════════════════

  /// Escanea dispositivos Bluetooth y devuelve la lista combinada de:
  ///   1. Dispositivos emparejados con el sistema (BT Classic + BLE)
  ///   2. Dispositivos actualmente conectados (cualquier app)
  ///   3. Dispositivos BLE descubiertos durante el escaneo activo
  static Future<List<BluetoothDevice>> escanearDispositivos({
    Duration tiempo = const Duration(seconds: 8),
  }) async {
    final List<BluetoothDevice> resultado = [];
    final idsVistos = <String>{};

    // 1) Emparejados con el sistema (clave para BT Classic).
    try {
      final bonded = await FlutterBluePlus.bondedDevices;
      for (final d in bonded) {
        if (idsVistos.add(d.remoteId.str)) resultado.add(d);
      }
    } catch (e) {
      _log('bondedDevices: $e');
    }

    // 2) Conectados ahora mismo a otras apps.
    try {
      final conectados = FlutterBluePlus.connectedDevices;
      for (final d in conectados) {
        if (idsVistos.add(d.remoteId.str)) resultado.add(d);
      }
    } catch (e) {
      _log('connectedDevices: $e');
    }

    // 3) Escaneo activo de dispositivos BLE visibles.
    try {
      await FlutterBluePlus.stopScan();
      final sub = FlutterBluePlus.scanResults.listen((results) {
        for (final r in results) {
          if (idsVistos.add(r.device.remoteId.str)) {
            resultado.add(r.device);
          }
        }
      });
      await FlutterBluePlus.startScan(timeout: tiempo);
      await Future.delayed(tiempo + const Duration(milliseconds: 300));
      await sub.cancel();
      try { await FlutterBluePlus.stopScan(); } catch (_) {}
    } catch (e) {
      _log('escaneo: $e');
      try { await FlutterBluePlus.stopScan(); } catch (_) {}
    }

    _log('Escaneo encontró ${resultado.length} dispositivo(s)');
    return resultado;
  }

  // ═══════════════════════════════════════════════════════════════
  //  CONEXIÓN
  // ═══════════════════════════════════════════════════════════════

  /// Conecta a un dispositivo Bluetooth y prepara el characteristic
  /// para enviar datos.
  static Future<bool> conectar(BluetoothDevice device) async {
    try {
      if (ultimoDiagnostico.isNotEmpty) {
        ultimoDiagnostico.add('───── nuevo intento ─────');
      }
      final targetId = device.remoteId.str;
      _log('Conectando a $targetId '
          '(${device.platformName.isEmpty ? "sin nombre" : device.platformName})');

      // ── Reusar conexión activa si es al mismo dispositivo ──
      if (_dispositivoActual != null &&
          _dispositivoActual!.remoteId.str == targetId &&
          _caracteristicaEscritura != null) {
        try {
          final estado = await _dispositivoActual!.connectionState.first
              .timeout(const Duration(seconds: 1),
                  onTimeout: () => BluetoothConnectionState.disconnected);
          if (estado == BluetoothConnectionState.connected) {
            _log('Ya conectado al mismo dispositivo, reusando');
            return true;
          }
        } catch (_) {}
      }

      // ── Desconectar dispositivo anterior si era distinto ──
      if (_dispositivoActual != null &&
          _dispositivoActual!.remoteId.str != targetId) {
        try { await _dispositivoActual!.disconnect(); } catch (_) {}
        _dispositivoActual = null;
        _caracteristicaEscritura = null;
      }

      // ── Conectar con timeout ──
      try {
        await device.connect(
          timeout: const Duration(seconds: 8),
          autoConnect: false);
        _log('connect() OK');
      } catch (e) {
        final msg = e.toString().toLowerCase();
        if (msg.contains('already') && msg.contains('connect')) {
          _log('Ya conectado a nivel SO (ignorando excepción)');
        } else {
          _log('connect() FALLÓ: $e');
          rethrow;
        }
      }

      // ── Negociar MTU grande en Android ──
      if (!kIsWeb && Platform.isAndroid) {
        try {
          final mtu = await device.requestMtu(512);
          _log('MTU negociado: $mtu bytes');
        } catch (e) {
          _log('requestMtu falló (no crítico): $e');
        }
      }

      // ── Descubrir servicios ──
      final servicios = await device.discoverServices();
      _log('Servicios descubiertos: ${servicios.length}');

      final candidatos = <BluetoothCharacteristic>[];
      for (final srv in servicios) {
        _log('  Servicio: ${srv.uuid}');
        for (final ch in srv.characteristics) {
          final p = ch.properties;
          final flags = <String>[];
          if (p.write) flags.add('write');
          if (p.writeWithoutResponse) flags.add('writeWR');
          if (p.read) flags.add('read');
          if (p.notify) flags.add('notify');
          _log('    Char: ${ch.uuid} [${flags.join("|")}]');
          if (p.write || p.writeWithoutResponse) {
            candidatos.add(ch);
          }
        }
      }

      if (candidatos.isEmpty) {
        _log('Ningún characteristic con write. Esta impresora '
            'es probablemente BT Classic/SPP only (iOS no lo soporta).');
        return false;
      }

      // ── Seleccionar el mejor characteristic ──
      BluetoothCharacteristic? elegido;
      for (final uuidPref in _uuidsPreferidos) {
        final cortoPref = uuidPref.substring(4, 8).toLowerCase();
        for (final ch in candidatos) {
          final uuidCh = ch.uuid.toString().toLowerCase();
          if (uuidCh == uuidPref.toLowerCase() ||
              uuidCh.contains(cortoPref)) {
            elegido = ch;
            _log('Match por UUID conocido: ${ch.uuid}');
            break;
          }
        }
        if (elegido != null) break;
      }

      // Si no hubo match, preferir write CON respuesta (ACK).
      if (elegido == null) {
        for (final ch in candidatos) {
          if (ch.properties.write) {
            elegido = ch;
            _log('Sin match. Usando primer write con ACK: ${ch.uuid}');
            break;
          }
        }
      }

      // Último recurso: cualquier characteristic con write.
      elegido ??= candidatos.first;

      _dispositivoActual = device;
      _caracteristicaEscritura = elegido;
      _log('Conexión completada con characteristic ${elegido.uuid}');
      return true;
    } catch (e) {
      _log('conectar error: $e');
      return false;
    }
  }

  /// Conecta usando el remoteId guardado anteriormente.
  static Future<bool> conectarPorId(String remoteId) async {
    try {
      _log('conectarPorId: $remoteId');

      // 1) Buscar en emparejados / conectados primero (rápido).
      BluetoothDevice? encontrado;
      try {
        for (final d in await FlutterBluePlus.bondedDevices) {
          if (d.remoteId.str == remoteId) { encontrado = d; break; }
        }
      } catch (_) {}

      if (encontrado == null) {
        // 2) Escaneo corto para refrescar caché de iOS y descubrir.
        final completer = Completer<BluetoothDevice?>();
        StreamSubscription? sub;
        sub = FlutterBluePlus.scanResults.listen((results) {
          for (final r in results) {
            if (r.device.remoteId.str == remoteId
                || (nombreImpresoraPreferida != null
                    && r.device.platformName == nombreImpresoraPreferida)) {
              if (!completer.isCompleted) completer.complete(r.device);
              return;
            }
          }
        });

        try {
          await FlutterBluePlus.startScan(
              timeout: const Duration(seconds: 4));
          encontrado = await completer.future.timeout(
              const Duration(seconds: 5),
              onTimeout: () => null);
        } catch (_) {}
        await sub.cancel();
        try { await FlutterBluePlus.stopScan(); } catch (_) {}
      }

      // 3) Si nada lo encontró, último intento con fromId directo.
      final device = encontrado ?? BluetoothDevice.fromId(remoteId);
      return await conectar(device);
    } catch (e) {
      _log('conectarPorId error: $e');
      return false;
    }
  }

  /// Desconecta el dispositivo actual y libera recursos.
  static Future<void> desconectar() async {
    try {
      if (_dispositivoActual != null) {
        await _dispositivoActual!.disconnect();
        _log('Desconectado');
      }
    } catch (e) {
      _log('desconectar error: $e');
    } finally {
      _dispositivoActual = null;
      _caracteristicaEscritura = null;
    }
  }

  /// Verifica si actualmente hay una conexión activa con la impresora.
  static Future<bool> estaConectado() async {
    if (_dispositivoActual == null || _caracteristicaEscritura == null) {
      return false;
    }
    try {
      final estado = await _dispositivoActual!.connectionState.first
          .timeout(const Duration(seconds: 1),
              onTimeout: () => BluetoothConnectionState.disconnected);
      return estado == BluetoothConnectionState.connected;
    } catch (_) {
      return false;
    }
  }

  // ═══════════════════════════════════════════════════════════════
  //  ENVÍO DE BYTES
  // ═══════════════════════════════════════════════════════════════

  /// Envía bytes a la impresora en chunks.
  static Future<bool> enviarBytes(List<int> bytes) async {
    try {
      final ch = _caracteristicaEscritura;
      if (ch == null) {
        _log('No hay characteristic activa');
        return false;
      }

      final usarConRespuesta = ch.properties.write;
      final chunkSize = usarConRespuesta ? 180 : 200;
      _log('Enviando ${bytes.length} bytes en chunks de $chunkSize '
          '(${usarConRespuesta ? "con ACK" : "sin ACK"})');

      var enviadosOk = 0;
      for (var i = 0; i < bytes.length; i += chunkSize) {
        final fin = (i + chunkSize < bytes.length)
            ? i + chunkSize : bytes.length;
        final chunk = bytes.sublist(i, fin);

        // Reintento de un solo chunk si falla la primera vez
        Object? errorChunk;
        for (var intento = 0; intento < 2; intento++) {
          try {
            await ch.write(chunk, withoutResponse: !usarConRespuesta);
            errorChunk = null;
            break;
          } catch (e) {
            errorChunk = e;
            await Future.delayed(Duration(milliseconds: 100 * (intento + 1)));
          }
        }

        if (errorChunk != null) {
          _log('Chunk ${i ~/ chunkSize} falló tras reintento: $errorChunk');
          return false;
        }
        enviadosOk = fin;

        // Pequeño delay entre chunks. Sin ACK es más necesario.
        if (!usarConRespuesta) {
          await Future.delayed(const Duration(milliseconds: 12));
        }
      }

      _log('$enviadosOk bytes enviados correctamente');
      return true;
    } catch (e) {
      _log('enviarBytes error: $e');
      return false;
    }
  }

  // ═══════════════════════════════════════════════════════════════
  //  PERSISTENCIA DE IMPRESORA PREFERIDA
  // ═══════════════════════════════════════════════════════════════

  /// Persiste la impresora preferida en SharedPreferences.
  static Future<void> guardarPreferida() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      if (macImpresoraPreferida == null) {
        await prefs.remove('impresora_bt_mac');
        await prefs.remove('impresora_bt_nombre');
        await prefs.remove('impresora_bt_ancho');
      } else {
        await prefs.setString('impresora_bt_mac', macImpresoraPreferida!);
        await prefs.setString('impresora_bt_nombre',
            nombreImpresoraPreferida ?? 'Impresora BT');
        await prefs.setInt('impresora_bt_ancho', anchoPapel);
      }
    } catch (e) {
      _log('guardarPreferida error: $e');
    }
  }

  /// Carga la impresora preferida desde SharedPreferences.
  /// LLAMAR EN main() ANTES DE runApp() para tenerla disponible.
  static Future<void> cargarPreferida() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      macImpresoraPreferida = prefs.getString('impresora_bt_mac');
      nombreImpresoraPreferida = prefs.getString('impresora_bt_nombre');
      anchoPapel = prefs.getInt('impresora_bt_ancho') ?? 80;
      if (macImpresoraPreferida != null) {
        _log('Preferida restaurada: $nombreImpresoraPreferida '
            '($macImpresoraPreferida) ancho=${anchoPapel}mm');
      }
    } catch (e) {
      _log('cargarPreferida error: $e');
      macImpresoraPreferida = null;
      nombreImpresoraPreferida = null;
    }
  }

  /// Limpia la impresora preferida (memoria y disco).
  static Future<void> limpiarPreferida() async {
    macImpresoraPreferida = null;
    nombreImpresoraPreferida = null;
    await guardarPreferida();
  }

  // ═══════════════════════════════════════════════════════════════
  //  HELPER COMPLETO: imprimir desde cero
  // ═══════════════════════════════════════════════════════════════

  /// Helper "todo en uno" para imprimir bytes sin preocuparte por
  /// los detalles de conexión.
  static Future<ImprimirResultado> imprimir(List<int> bytes) async {
    if (macImpresoraPreferida == null) {
      return ImprimirResultado(
        exitoso: false,
        mensaje: 'No hay impresora configurada. Conectá una primero.',
      );
    }

    if (!await estaBluetoothActivo()) {
      final encendido = await intentarEncenderBluetooth();
      if (!encendido) {
        return ImprimirResultado(
          exitoso: false,
          mensaje: 'El Bluetooth está apagado. Activalo desde los '
                   'ajustes rápidos del teléfono.',
        );
      }
    }

    // Reconectar si es necesario
    if (!await estaConectado()) {
      _log('No conectado, reconectando a $macImpresoraPreferida...');
      final ok = await conectarPorId(macImpresoraPreferida!);
      if (!ok) {
        return ImprimirResultado(
          exitoso: false,
          mensaje: 'No se pudo conectar a "$nombreImpresoraPreferida". '
                   'Verificá que esté encendida y dentro del rango.',
        );
      }
    }

    // Enviar bytes
    final enviado = await enviarBytes(bytes);
    if (!enviado) {
      return ImprimirResultado(
        exitoso: false,
        mensaje: 'Error enviando los datos. Mirá el diagnóstico para '
                 'más detalles.',
      );
    }

    return ImprimirResultado(
      exitoso: true,
      mensaje: 'Impreso correctamente en "$nombreImpresoraPreferida"',
    );
  }
}

/// Resultado de una operación de impresión.
/// Pensado para usar directamente en SnackBar / Dialog.
class ImprimirResultado {
  final bool exitoso;
  final String mensaje;
  ImprimirResultado({required this.exitoso, required this.mensaje});
}

// ═══════════════════════════════════════════════════════════════════
//  ESC/POS HELPER — Comandos comunes para impresoras térmicas
//  ──────────────────────────────────────────────────────────────────
//  Wrappers cómodos sobre los comandos ESC/POS más usados. Para
//  layouts complejos (tablas, imágenes, códigos de barras) usar el
//  paquete `esc_pos_utils_plus` — esto cubre lo básico sin
//  dependencias adicionales.
//
//  USO:
//    final bytes = EscPos.builder()
//      .center().bold().texto('MI TIENDA').reset()
//      .salto()
//      .left().texto('Cliente: Juan').salto()
//      .linea('-')
//      .corte()
//      .build();
//    await BluetoothPrinter.imprimir(bytes);
// ═══════════════════════════════════════════════════════════════════

class EscPos {
  // ═══════════════════════════════════════════════════════════════
  //  COMANDOS ESC/POS CRUDOS (constantes)
  // ═══════════════════════════════════════════════════════════════

  /// Reset completo de la impresora (limpia estilos).
  static const List<int> init = [0x1B, 0x40];

  /// Avance de línea (\n).
  static const List<int> lf = [0x0A];

  /// Carriage return.
  static const List<int> cr = [0x0D];

  // ── Alineación ──
  static const List<int> alignLeft   = [0x1B, 0x61, 0x00];
  static const List<int> alignCenter = [0x1B, 0x61, 0x01];
  static const List<int> alignRight  = [0x1B, 0x61, 0x02];

  // ── Estilo de texto ──
  static const List<int> boldOn     = [0x1B, 0x45, 0x01];
  static const List<int> boldOff    = [0x1B, 0x45, 0x00];
  static const List<int> underlineOn  = [0x1B, 0x2D, 0x01];
  static const List<int> underlineOff = [0x1B, 0x2D, 0x00];

  // ── Tamaño de texto ──
  static const List<int> sizeNormal     = [0x1D, 0x21, 0x00];
  static const List<int> sizeDoubleW    = [0x1D, 0x21, 0x10]; // ancho doble
  static const List<int> sizeDoubleH    = [0x1D, 0x21, 0x01]; // alto doble
  static const List<int> sizeDouble     = [0x1D, 0x21, 0x11]; // ambos

  /// Corte completo del papel (GS V 0).
  static const List<int> cutFull = [0x1D, 0x56, 0x00];

  /// Corte parcial (deja un puente).
  static const List<int> cutPartial = [0x1D, 0x56, 0x01];

  /// Avance de N líneas (ESC d n).
  static List<int> feed(int lineas) => [0x1B, 0x64, lineas.clamp(0, 255)];

  /// Apertura de cajón (típicamente conectado al RJ-11 de la impresora).
  static const List<int> abrirCajon = [0x1B, 0x70, 0x00, 0x19, 0xFF];

  // ═══════════════════════════════════════════════════════════════
  //  BUILDER FLUIDO
  // ═══════════════════════════════════════════════════════════════

  /// Crea un nuevo builder para construir tickets de forma fluida.
  static EscPosBuilder builder({int anchoColumnas = 32}) {
    return EscPosBuilder(anchoColumnas: anchoColumnas);
  }
}

/// Builder fluido para construir un ticket línea por línea.
/// Cada método devuelve `this` para encadenar llamadas.
///
/// `anchoColumnas` típico:
///   • Papel 58mm fuente normal: 32 columnas
///   • Papel 80mm fuente normal: 48 columnas
class EscPosBuilder {
  final List<int> _bytes = [];
  final int anchoColumnas;

  EscPosBuilder({this.anchoColumnas = 32}) {
    _bytes.addAll(EscPos.init);
  }

  /// Agrega bytes crudos.
  EscPosBuilder bytes(List<int> b) {
    _bytes.addAll(b);
    return this;
  }

  /// Agrega texto codificado en UTF-8 (sin salto de línea).
  EscPosBuilder texto(String s) {
    _bytes.addAll(utf8.encode(s));
    return this;
  }

  /// Texto + salto de línea.
  EscPosBuilder ln([String s = '']) {
    if (s.isNotEmpty) _bytes.addAll(utf8.encode(s));
    _bytes.addAll(EscPos.lf);
    return this;
  }

  // ── Alineación ──
  EscPosBuilder left()   { _bytes.addAll(EscPos.alignLeft);   return this; }
  EscPosBuilder center() { _bytes.addAll(EscPos.alignCenter); return this; }
  EscPosBuilder right()  { _bytes.addAll(EscPos.alignRight);  return this; }

  // ── Estilo ──
  EscPosBuilder bold([bool on = true]) {
    _bytes.addAll(on ? EscPos.boldOn : EscPos.boldOff);
    return this;
  }
  EscPosBuilder underline([bool on = true]) {
    _bytes.addAll(on ? EscPos.underlineOn : EscPos.underlineOff);
    return this;
  }

  // ── Tamaño ──
  EscPosBuilder size({bool doble = false, bool dobleAncho = false,
                       bool dobleAlto = false}) {
    if (doble) { _bytes.addAll(EscPos.sizeDouble); }
    else if (dobleAncho) { _bytes.addAll(EscPos.sizeDoubleW); }
    else if (dobleAlto) { _bytes.addAll(EscPos.sizeDoubleH); }
    else { _bytes.addAll(EscPos.sizeNormal); }
    return this;
  }

  /// Reset completo de estilos (alignment + bold + size).
  EscPosBuilder reset() {
    _bytes.addAll(EscPos.alignLeft);
    _bytes.addAll(EscPos.boldOff);
    _bytes.addAll(EscPos.underlineOff);
    _bytes.addAll(EscPos.sizeNormal);
    return this;
  }

  /// Salto de línea simple.
  EscPosBuilder salto([int n = 1]) {
    for (var i = 0; i < n; i++) _bytes.addAll(EscPos.lf);
    return this;
  }

  /// Línea horizontal repitiendo un carácter (típicamente '-' o '=').
  EscPosBuilder linea([String char = '-']) {
    return ln(char * anchoColumnas);
  }

  /// Dos textos en la misma línea, izquierda y derecha.
  EscPosBuilder par(String izquierda, String derecha) {
    final libre = anchoColumnas - izquierda.length - derecha.length;
    if (libre > 0) {
      return ln(izquierda + ' ' * libre + derecha);
    } else {
      return ln(izquierda).right().ln(derecha).left();
    }
  }

  /// Tres columnas (izq | centro | der). Útil para tablas de productos.
  EscPosBuilder tres(String izq, String centro, String der,
      {int anchoIzq = 0, int anchoDer = 0}) {
    anchoIzq = anchoIzq > 0 ? anchoIzq : (anchoColumnas * 0.5).floor();
    anchoDer = anchoDer > 0 ? anchoDer : (anchoColumnas * 0.2).floor();
    final anchoCen = anchoColumnas - anchoIzq - anchoDer;

    final l = izq.length > anchoIzq ? izq.substring(0, anchoIzq)
                                     : izq.padRight(anchoIzq);
    final c = centro.length > anchoCen ? centro.substring(0, anchoCen)
                                        : centro.padLeft(anchoCen);
    final d = der.length > anchoDer ? der.substring(0, anchoDer)
                                     : der.padLeft(anchoDer);
    return ln('$l$c$d');
  }

  /// Corte de papel (con 3 saltos antes para no cortar texto).
  EscPosBuilder corte() {
    _bytes.addAll(EscPos.feed(3));
    _bytes.addAll(EscPos.cutFull);
    return this;
  }

  /// Solo avance — útil si no querés cortar (tickets para gancho).
  EscPosBuilder avance([int lineas = 5]) {
    _bytes.addAll(EscPos.feed(lineas));
    return this;
  }

  /// Devuelve la lista de bytes lista para enviar a la impresora.
  List<int> build() => List<int>.unmodifiable(_bytes);
}

// ═══════════════════════════════════════════════════════════════════════
//  MÓDULO DE COTIZACIONES
// ═══════════════════════════════════════════════════════════════════════
//
// Permite generar cotizaciones profesionales para clientes, guardarlas
// en la base de datos, consultar el historial, y cobrar la cotización
// vinculándola a un número de factura cuando se convierte en venta real.
//
// FLUJO:
//   1. Admin/Gerente/Dueño abre "Nueva Cotización" desde el drawer.
//   2. Escribe cliente, elige moneda, agrega productos del catálogo.
//   3. Ajusta cantidades, precios, opcionalmente IVA, y foto por producto.
//   4. Al guardar: se persiste en tablas `cotizaciones` + `cotizacion_items`
//      y se genera un PDF profesional (imprimir/guardar).
//   5. Desde "Historial de Cotizaciones" se busca, se ve el detalle, se
//      cobra (asignando número de factura), o se elimina.
//
// REUTILIZA de la app existente:
//   · Modelo Producto y catalogoGlobal
//   · Cliente HTTP _Api
//   · Control de acceso checkAccess([...])
//   · ConfigSistema.tasaCambio y ConfigSistema.encabezadoDe(tienda) para el PDF
// ═══════════════════════════════════════════════════════════════════════

/// Colores del módulo de cotizaciones (paleta profesional coherente
/// con la marca Tecno Líder — azul principal, amarillo acento).
class _CotizColors {
  static const primario   = Color(0xFF1E3A8A); // azul profundo
  static const acento     = Color(0xFFEAB308); // amarillo Tecno Líder
  static const fondoClaro = Color(0xFFF3F4F6); // gris muy claro para filas
  static const textoOscuro= Color(0xFF111827); // gris casi negro
  static const linea      = Color(0xFFE5E7EB); // gris claro para bordes
  static const verde      = Color(0xFF16A34A); // cobrada
  static const naranja    = Color(0xFFEA580C); // pendiente
}

// ────────────────────────────────────────────────────────────────────
//  MODELOS
// ────────────────────────────────────────────────────────────────────

/// Una línea de la cotización — un producto con su cantidad y precio.
class ItemCotizacion {
  Producto producto;
  int cantidad;
  double precioUnitario; // editable
  Uint8List? imagenBytes;

  ItemCotizacion({
    required this.producto,
    this.cantidad = 1,
    required this.precioUnitario,
    this.imagenBytes,
  });

  double get subtotal => cantidad * precioUnitario;
}

/// Registro completo de una cotización (cabecera + items) tal como
/// viene del backend o se envía a él.
class CotizacionRegistro {
  int? id;
  String clienteNombre;
  String clienteCedula;
  String clienteTelefono;
  String clienteCorreo;
  String moneda;         // 'USD' o 'Bs'
  bool incluyeIva;
  double tasa;           // tasa BCV usada al guardar
  double subtotal;
  double montoIva;
  double total;
  String fechaCreacion;  // YYYY-MM-DD
  String fechaVence;     // YYYY-MM-DD
  String estado;         // 'pendiente' | 'cobrada'
  String nroFactura;
  String? fechaCobro;
  List<Map<String, dynamic>> items; // producto_codigo, producto_nombre, marca, modelo, cantidad, precio_unitario

  CotizacionRegistro({
    this.id,
    this.clienteNombre = '',
    this.clienteCedula = '',
    this.clienteTelefono = '',
    this.clienteCorreo = '',
    this.moneda = 'USD',
    this.incluyeIva = false,
    this.tasa = 0,
    this.subtotal = 0,
    this.montoIva = 0,
    this.total = 0,
    this.fechaCreacion = '',
    this.fechaVence = '',
    this.estado = 'pendiente',
    this.nroFactura = '',
    this.fechaCobro,
    List<Map<String, dynamic>>? items,
  }) : items = items ?? [];

  factory CotizacionRegistro.fromMap(Map<String, dynamic> m) {
    return CotizacionRegistro(
      id             : m['id'] is int
          ? m['id']
          : int.tryParse(m['id']?.toString() ?? ''),
      clienteNombre  : (m['cliente_nombre'] ?? '').toString(),
      clienteCedula  : (m['cliente_cedula'] ?? '').toString(),
      clienteTelefono: (m['cliente_tel'] ?? '').toString(),
      clienteCorreo  : (m['cliente_correo'] ?? '').toString(),
      moneda         : (m['moneda'] ?? 'USD').toString(),
      incluyeIva     : m['incluye_iva'] == 1 || m['incluye_iva'] == '1'
                       || m['incluye_iva'] == true,
      tasa           : double.tryParse(m['tasa']?.toString() ?? '0') ?? 0,
      subtotal       : double.tryParse(m['subtotal']?.toString() ?? '0') ?? 0,
      montoIva       : double.tryParse(m['monto_iva']?.toString() ?? '0') ?? 0,
      total          : double.tryParse(m['total']?.toString() ?? '0') ?? 0,
      fechaCreacion  : (m['fecha_creacion'] ?? '').toString(),
      fechaVence     : (m['fecha_vence'] ?? '').toString(),
      estado         : (m['estado'] ?? 'pendiente').toString(),
      nroFactura     : (m['nro_factura'] ?? '').toString(),
      fechaCobro     : m['fecha_cobro']?.toString(),
      items          : ((m['items'] as List?) ?? [])
          .map((e) => Map<String, dynamic>.from(e as Map))
          .toList(),
    );
  }
}

/// Porcentaje de IVA aplicado en las cotizaciones (Venezuela: 16%).
const double kIvaCotizacion = 16.0;

// ────────────────────────────────────────────────────────────────────
//  VENTANA — NUEVA COTIZACIÓN
// ────────────────────────────────────────────────────────────────────

class VentanaCotizacion extends StatefulWidget {
  const VentanaCotizacion({super.key});
  @override
  State<VentanaCotizacion> createState() => _VentanaCotizacionState();
}

class _VentanaCotizacionState extends State<VentanaCotizacion> {
  // Cliente
  final _ctrlNombre  = TextEditingController();
  final _ctrlCedula  = TextEditingController();
  final _ctrlTel     = TextEditingController();
  final _ctrlCorreo  = TextEditingController();
  final _ctrlBuscar  = TextEditingController();

  // Estado
  final List<ItemCotizacion> _items = [];
  String _moneda = 'USD';                       // 'USD' o 'Bs'
  bool _incluyeIva = false;
  DateTime _fechaCreacion = DateTime.now();
  DateTime _fechaVence = DateTime.now().add(const Duration(days: 15));
  final Map<String, Uint8List> _cacheImagenes = {}; // codigo → bytes
  bool _guardando = false;

  @override
  void initState() {
    super.initState();
    _cargarImagenesGuardadas();
  }

  @override
  void dispose() {
    _ctrlNombre.dispose();
    _ctrlCedula.dispose();
    _ctrlTel.dispose();
    _ctrlCorreo.dispose();
    _ctrlBuscar.dispose();
    super.dispose();
  }

  /// Carga desde el backend todas las imágenes de producto guardadas y
  /// las mete en `_cacheImagenes`. Se usan para pre-poblar la foto de
  /// cada producto al agregarlo a la cotización.
  Future<void> _cargarImagenesGuardadas() async {
    try {
      final raw = await _Api.get('producto_imagenes');
      if (raw is! List) return;
      for (final m in raw) {
        if (m is! Map) continue;
        final cod = (m['producto_codigo'] ?? '').toString();
        final b64 = (m['imagen_base64'] ?? '').toString();
        if (cod.isEmpty || b64.isEmpty) continue;
        try {
          final bytes = base64Decode(b64);
          _cacheImagenes[cod] = bytes;
        } catch (_) {}
      }
      // Repoblar imágenes de items ya agregados (por si el usuario
      // agregó productos antes que terminara la carga).
      for (final it in _items) {
        it.imagenBytes ??= _cacheImagenes[it.producto.codigo];
      }
      if (mounted) setState(() {});
    } catch (e) {
      debugPrint('[Cotización] cargar imágenes: $e');
    }
  }

  // ─── Cálculos ──────────────────────────────────────────────
  double get _subtotalUsd => _items.fold(0.0, (a, it) => a + it.subtotal);
  double get _ivaUsd      => _incluyeIva ? _subtotalUsd * (kIvaCotizacion / 100) : 0;
  double get _totalUsd    => _subtotalUsd + _ivaUsd;

  double _aMoneda(double usd) {
    if (_moneda == 'USD') return usd;
    return usd * ConfigSistema.tasaCambio;
  }

  String get _simbolo => _moneda == 'USD' ? '\$' : 'Bs.';

  // ─── Manejo de productos ───────────────────────────────────
  void _agregarProducto(Producto p) {
    // Si ya existe en la lista, sumar cantidad
    final idx = _items.indexWhere((it) => it.producto.codigo == p.codigo);
    setState(() {
      if (idx >= 0) {
        _items[idx].cantidad += 1;
      } else {
        _items.add(ItemCotizacion(
          producto: p,
          cantidad: 1,
          precioUnitario: p.precioVenta,
          imagenBytes: _cacheImagenes[p.codigo],
        ));
      }
      _ctrlBuscar.clear();
    });
  }

  /// Abre un diálogo con buscador sobre `catalogoGlobal`.
  Future<void> _abrirBuscadorProductos() async {
    String filtro = '';
    await showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setStBd) {
          final query = filtro.toLowerCase().trim();
          final resultados = catalogoGlobal
              .where((p) => p.productoPadreCodigo.isEmpty) // solo productos base
              .where((p) {
                if (query.isEmpty) return true;
                return p.nombre.toLowerCase().contains(query)
                    || p.codigo.toLowerCase().contains(query)
                    || p.marca.toLowerCase().contains(query)
                    || p.modelo.toLowerCase().contains(query);
              })
              .take(40)
              .toList();
          return AlertDialog(
            title: const Text('Agregar producto'),
            content: SizedBox(
              width: 500,
              height: 500,
              child: Column(children: [
                TextField(
                  autofocus: true,
                  decoration: const InputDecoration(
                    labelText: 'Buscar por nombre, código, marca o modelo',
                    prefixIcon: Icon(Icons.search),
                  ),
                  onChanged: (v) => setStBd(() => filtro = v),
                ),
                const SizedBox(height: 8),
                Expanded(
                  child: resultados.isEmpty
                      ? const Center(child: Text(
                          'Sin resultados. Escribe para buscar.',
                          style: TextStyle(color: Colors.grey)))
                      : ListView.separated(
                          itemCount: resultados.length,
                          separatorBuilder: (_, __) => const Divider(height: 1),
                          itemBuilder: (_, i) {
                            final p = resultados[i];
                            return ListTile(
                              dense: true,
                              leading: _cacheImagenes[p.codigo] != null
                                  ? Image.memory(_cacheImagenes[p.codigo]!,
                                      width: 40, height: 40, fit: BoxFit.cover)
                                  : Container(
                                      width: 40, height: 40,
                                      color: _CotizColors.fondoClaro,
                                      child: const Icon(Icons.image_outlined,
                                          size: 20, color: Colors.grey)),
                              title: Text(p.nombre,
                                  maxLines: 1, overflow: TextOverflow.ellipsis),
                              subtitle: Text('${p.marca} · ${p.modelo}',
                                  style: const TextStyle(fontSize: 11)),
                              trailing: Text(
                                '\$${p.precioVenta.toStringAsFixed(2)}',
                                style: const TextStyle(
                                    fontWeight: FontWeight.w600)),
                              onTap: () {
                                _agregarProducto(p);
                                Navigator.pop(ctx);
                              },
                            );
                          }),
                ),
              ]),
            ),
            actions: [
              TextButton(onPressed: () => Navigator.pop(ctx),
                  child: const Text('Cerrar')),
            ],
          );
        },
      ),
    );
  }

  Future<void> _elegirImagen(ItemCotizacion it) async {
    final origen = await showModalBottomSheet<ImageSource>(
      context: context,
      builder: (ctx) => SafeArea(
        child: Wrap(children: [
          ListTile(
            leading: const Icon(Icons.photo_library),
            title: const Text('Galería'),
            onTap: () => Navigator.pop(ctx, ImageSource.gallery),
          ),
          ListTile(
            leading: const Icon(Icons.camera_alt),
            title: const Text('Cámara'),
            onTap: () => Navigator.pop(ctx, ImageSource.camera),
          ),
        ]),
      ),
    );
    if (origen == null) return;
    try {
      final picker = ImagePicker();
      final xf = await picker.pickImage(source: origen, imageQuality: 70,
          maxWidth: 800);
      if (xf == null) return;
      final bytes = await xf.readAsBytes();
      if (!mounted) return;
      setState(() {
        it.imagenBytes = bytes;
        _cacheImagenes[it.producto.codigo] = bytes;
      });
      // Persistir al backend en background
      final b64 = base64Encode(bytes);
      final ext = xf.path.split('.').last.toLowerCase();
      unawaited(_Api.post('producto_imagen_guardar', {
        'producto_codigo': it.producto.codigo,
        'imagen_base64'  : b64,
        'imagen_ext'     : ext.length <= 4 ? ext : 'jpg',
      }).catchError((e) {
        debugPrint('[Cotización] guardar imagen: $e');
      }));
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
            content: Text('No se pudo cargar la imagen: $e')));
      }
    }
  }

  Future<void> _elegirFecha(bool esVencimiento) async {
    final actual = esVencimiento ? _fechaVence : _fechaCreacion;
    final pick = await showDatePicker(
      context: context,
      initialDate: actual,
      firstDate: DateTime(2020),
      lastDate: DateTime(2100),
    );
    if (pick == null) return;
    setState(() {
      if (esVencimiento) {
        _fechaVence = pick;
      } else {
        _fechaCreacion = pick;
      }
    });
  }

  // ─── Guardar ───────────────────────────────────────────────
  Future<void> _guardarYGenerarPDF() async {
    if (_ctrlNombre.text.trim().isEmpty) {
      _snack('El nombre del cliente es obligatorio', esError: true);
      return;
    }
    if (_items.isEmpty) {
      _snack('Agregue al menos un producto', esError: true);
      return;
    }
    setState(() => _guardando = true);
    try {
      final tasa = _moneda == 'Bs' ? ConfigSistema.tasaCambio : 0.0;
      final body = <String, dynamic>{
        'cliente_nombre' : _ctrlNombre.text.trim(),
        'cliente_cedula' : _ctrlCedula.text.trim(),
        'cliente_tel'    : _ctrlTel.text.trim(),
        'cliente_correo' : _ctrlCorreo.text.trim(),
        'moneda'         : _moneda,
        'incluye_iva'    : _incluyeIva ? 1 : 0,
        'tasa'           : tasa,
        'subtotal'       : _subtotalUsd,
        'monto_iva'      : _ivaUsd,
        'total'          : _totalUsd,
        'fecha_creacion' : _fechaCreacion.toIso8601String().substring(0, 10),
        'fecha_vence'    : _fechaVence.toIso8601String().substring(0, 10),
        'items'          : _items.map((it) => {
          'producto_codigo': it.producto.codigo,
          'producto_nombre': it.producto.nombre,
          'marca'          : it.producto.marca,
          'modelo'         : it.producto.modelo,
          'cantidad'       : it.cantidad,
          'precio_unitario': it.precioUnitario,
        }).toList(),
      };
      final resp = await _Api.post('cotizacion_guardar', body);
      final idNuevo = resp is Map ? resp['id'] : null;
      // Generar PDF ANTES de limpiar el formulario
      await _generarYMostrarPDF(idNuevo);
      // Limpiar
      if (mounted) {
        setState(() {
          _ctrlNombre.clear();
          _ctrlCedula.clear();
          _ctrlTel.clear();
          _ctrlCorreo.clear();
          _items.clear();
          _incluyeIva = false;
          _fechaCreacion = DateTime.now();
          _fechaVence = DateTime.now().add(const Duration(days: 15));
        });
        _snack('Cotización guardada correctamente');
      }
    } catch (e) {
      _snack('No se pudo guardar: $e', esError: true);
    } finally {
      if (mounted) setState(() => _guardando = false);
    }
  }

  Future<void> _generarYMostrarPDF(dynamic idCotiz) async {
    try {
      final bytes = await _generarPdfCotizacion(
        idCotizacion   : idCotiz?.toString() ?? '',
        clienteNombre  : _ctrlNombre.text.trim(),
        clienteCedula  : _ctrlCedula.text.trim(),
        clienteTelefono: _ctrlTel.text.trim(),
        clienteCorreo  : _ctrlCorreo.text.trim(),
        items          : _items,
        moneda         : _moneda,
        tasa           : ConfigSistema.tasaCambio,
        incluyeIva     : _incluyeIva,
        subtotalUsd    : _subtotalUsd,
        ivaUsd         : _ivaUsd,
        totalUsd       : _totalUsd,
        fechaCreacion  : _fechaCreacion,
        fechaVence     : _fechaVence,
        tienda         : usuarioSesion?.tienda ?? '',
      );
      await Printing.layoutPdf(onLayout: (_) async => bytes);
    } catch (e) {
      _snack('Error generando PDF: $e', esError: true);
    }
  }

  void _snack(String msg, {bool esError = false}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(msg),
      backgroundColor: esError ? AppColors.statusRed : AppColors.statusGreen,
    ));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Nueva Cotización'),
        backgroundColor: _CotizColors.primario,
        foregroundColor: Colors.white,
        actions: [
          IconButton(
            icon: const Icon(Icons.history),
            tooltip: 'Historial',
            onPressed: () => Navigator.push(context, MaterialPageRoute(
                builder: (_) => const VentanaHistorialCotizaciones())),
          ),
        ],
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          _seccion('Datos del cliente'),
          _campo(_ctrlNombre, 'Nombre y apellido *', Icons.person),
          Row(children: [
            Expanded(child: _campo(_ctrlCedula, 'Cédula / RIF', Icons.badge)),
            const SizedBox(width: 10),
            Expanded(child: _campo(_ctrlTel, 'Teléfono', Icons.phone,
                keyboard: TextInputType.phone)),
          ]),
          _campo(_ctrlCorreo, 'Correo (opcional)', Icons.email,
              keyboard: TextInputType.emailAddress),

          const SizedBox(height: 20),
          _seccion('Moneda y opciones'),
          Row(children: [
            const Text('Moneda: '),
            const SizedBox(width: 8),
            ChoiceChip(
              label: const Text('USD'),
              selected: _moneda == 'USD',
              onSelected: (_) => setState(() => _moneda = 'USD'),
            ),
            const SizedBox(width: 8),
            ChoiceChip(
              label: const Text('Bolívares'),
              selected: _moneda == 'Bs',
              onSelected: (_) => setState(() => _moneda = 'Bs'),
            ),
            const Spacer(),
            if (_moneda == 'Bs')
              Text('Tasa: ${ConfigSistema.tasaCambio.toStringAsFixed(2)} Bs/\$',
                  style: const TextStyle(fontSize: 11, color: Colors.grey)),
          ]),
          const SizedBox(height: 10),
          SwitchListTile(
            title: const Text('Incluir IVA (16%)'),
            value: _incluyeIva,
            onChanged: (v) => setState(() => _incluyeIva = v),
            dense: true,
            contentPadding: EdgeInsets.zero,
          ),
          Row(children: [
            Expanded(child: OutlinedButton.icon(
              icon: const Icon(Icons.event, size: 18),
              label: Text('Emitida: '
                  '${DateFormat('dd/MM/yyyy').format(_fechaCreacion)}'),
              onPressed: () => _elegirFecha(false),
            )),
            const SizedBox(width: 10),
            Expanded(child: OutlinedButton.icon(
              icon: const Icon(Icons.event_available, size: 18),
              label: Text('Vence: '
                  '${DateFormat('dd/MM/yyyy').format(_fechaVence)}'),
              onPressed: () => _elegirFecha(true),
            )),
          ]),

          const SizedBox(height: 20),
          Row(children: [
            Expanded(child: _seccion('Productos (${_items.length})')),
            ElevatedButton.icon(
              icon: const Icon(Icons.add, size: 18),
              label: const Text('Agregar'),
              style: ElevatedButton.styleFrom(
                backgroundColor: _CotizColors.primario,
                foregroundColor: Colors.white,
              ),
              onPressed: _abrirBuscadorProductos,
            ),
          ]),
          const SizedBox(height: 6),
          if (_items.isEmpty)
            Container(
              padding: const EdgeInsets.all(24),
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: _CotizColors.fondoClaro,
                borderRadius: BorderRadius.circular(8),
              ),
              child: const Text(
                'Aún no hay productos. Presione "Agregar".',
                style: TextStyle(color: Colors.grey),
              ),
            )
          else
            ..._items.asMap().entries.map((e) => _filaItem(e.key, e.value)),

          const SizedBox(height: 24),
          _seccionTotales(),

          const SizedBox(height: 24),
          SizedBox(
            width: double.infinity,
            child: ElevatedButton.icon(
              icon: _guardando
                  ? const SizedBox(width: 18, height: 18,
                      child: CircularProgressIndicator(
                          strokeWidth: 2, color: Colors.white))
                  : const Icon(Icons.picture_as_pdf),
              label: Text(_guardando
                  ? 'Guardando...'
                  : 'Guardar y generar PDF'),
              style: ElevatedButton.styleFrom(
                backgroundColor: _CotizColors.acento,
                foregroundColor: Colors.black,
                padding: const EdgeInsets.symmetric(vertical: 14),
                textStyle: const TextStyle(
                    fontSize: 15, fontWeight: FontWeight.w700),
              ),
              onPressed: _guardando ? null : _guardarYGenerarPDF,
            ),
          ),
          const SizedBox(height: 20),
        ]),
      ),
    );
  }

  Widget _seccion(String s) => Padding(
    padding: const EdgeInsets.only(bottom: 8, top: 8),
    child: Text(s, style: const TextStyle(
        fontSize: 14, fontWeight: FontWeight.w700,
        color: _CotizColors.primario)),
  );

  Widget _campo(TextEditingController c, String label, IconData icon,
      {TextInputType? keyboard}) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: TextField(
        controller: c,
        keyboardType: keyboard,
        decoration: InputDecoration(
          labelText: label,
          prefixIcon: Icon(icon, size: 20),
          border: const OutlineInputBorder(),
          isDense: true,
        ),
      ),
    );
  }

  Widget _filaItem(int i, ItemCotizacion it) {
    return Container(
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: Colors.white,
        border: Border.all(color: _CotizColors.linea),
        borderRadius: BorderRadius.circular(8),
      ),
      child: Row(crossAxisAlignment: CrossAxisAlignment.center, children: [
        GestureDetector(
          onTap: () => _elegirImagen(it),
          child: it.imagenBytes != null
              ? ClipRRect(
                  borderRadius: BorderRadius.circular(6),
                  child: Image.memory(it.imagenBytes!,
                      width: 56, height: 56, fit: BoxFit.cover))
              : Container(
                  width: 56, height: 56,
                  decoration: BoxDecoration(
                    color: _CotizColors.fondoClaro,
                    borderRadius: BorderRadius.circular(6),
                    border: Border.all(color: _CotizColors.linea, width: 1),
                  ),
                  child: const Icon(Icons.add_photo_alternate,
                      color: Colors.grey, size: 24),
                ),
        ),
        const SizedBox(width: 10),
        Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start,
          children: [
          Text(it.producto.nombre,
              maxLines: 1, overflow: TextOverflow.ellipsis,
              style: const TextStyle(fontWeight: FontWeight.w600)),
          Text('${it.producto.marca} · ${it.producto.modelo}',
              style: const TextStyle(fontSize: 11, color: Colors.grey)),
          const SizedBox(height: 4),
          Row(children: [
            // Cantidad
            IconButton(
              icon: const Icon(Icons.remove_circle_outline),
              padding: EdgeInsets.zero,
              constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
              onPressed: () => setState(() {
                if (it.cantidad > 1) it.cantidad--;
              }),
            ),
            Text('${it.cantidad}',
                style: const TextStyle(fontWeight: FontWeight.w600)),
            IconButton(
              icon: const Icon(Icons.add_circle_outline),
              padding: EdgeInsets.zero,
              constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
              onPressed: () => setState(() => it.cantidad++),
            ),
            const SizedBox(width: 10),
            // Precio unitario (editable)
            SizedBox(
              width: 90,
              child: TextFormField(
                initialValue: it.precioUnitario.toStringAsFixed(2),
                keyboardType: const TextInputType.numberWithOptions(
                    decimal: true),
                textAlign: TextAlign.right,
                decoration: const InputDecoration(
                  isDense: true,
                  prefixText: '\$',
                  border: OutlineInputBorder(),
                  contentPadding: EdgeInsets.symmetric(
                      horizontal: 6, vertical: 6),
                ),
                onChanged: (v) {
                  final n = double.tryParse(v.replaceAll(',', '.'));
                  if (n != null) setState(() => it.precioUnitario = n);
                },
              ),
            ),
          ]),
        ])),
        Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
          IconButton(
            icon: const Icon(Icons.delete_outline, color: Colors.red, size: 20),
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
            onPressed: () => setState(() => _items.removeAt(i)),
          ),
          const SizedBox(height: 4),
          Text('${_simbolo} ${_aMoneda(it.subtotal).toStringAsFixed(2)}',
              style: const TextStyle(
                  fontWeight: FontWeight.w700, fontSize: 13)),
        ]),
      ]),
    );
  }

  Widget _seccionTotales() {
    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: _CotizColors.fondoClaro,
        borderRadius: BorderRadius.circular(8),
      ),
      child: Column(children: [
        _filaTotal('Subtotal', _aMoneda(_subtotalUsd)),
        if (_incluyeIva)
          _filaTotal('IVA (${kIvaCotizacion.toStringAsFixed(0)}%)',
              _aMoneda(_ivaUsd)),
        const Divider(),
        _filaTotal('TOTAL', _aMoneda(_totalUsd), destacado: true),
      ]),
    );
  }

  Widget _filaTotal(String label, double v, {bool destacado = false}) {
    final style = TextStyle(
      fontSize: destacado ? 16 : 13,
      fontWeight: destacado ? FontWeight.w800 : FontWeight.w500,
      color: destacado ? _CotizColors.primario : _CotizColors.textoOscuro,
    );
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 3),
      child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
        Text(label, style: style),
        Text('$_simbolo ${v.toStringAsFixed(2)}', style: style),
      ]),
    );
  }
}

// ────────────────────────────────────────────────────────────────────
//  PDF PROFESIONAL DE COTIZACIÓN
// ────────────────────────────────────────────────────────────────────

/// Genera un PDF profesional (estilo factura comercial) con encabezado,
/// datos del cliente, tabla de productos, totales y pie.
///
/// Reutiliza `ConfigSistema.encabezadoDe(tienda)` para logo/RIF/dirección.
Future<Uint8List> _generarPdfCotizacion({
  required String idCotizacion,
  required String clienteNombre,
  required String clienteCedula,
  required String clienteTelefono,
  required String clienteCorreo,
  required List<ItemCotizacion> items,
  required String moneda,          // 'USD' | 'Bs'
  required double tasa,
  required bool incluyeIva,
  required double subtotalUsd,
  required double ivaUsd,
  required double totalUsd,
  required DateTime fechaCreacion,
  required DateTime fechaVence,
  required String tienda,
}) async {
  final pdf = pw.Document();
  final enc = ConfigSistema.encabezadoDe(tienda);
  pw.MemoryImage? logo;
  if (enc.logoBytes != null) {
    try { logo = pw.MemoryImage(enc.logoBytes!); } catch (_) {}
  }

  // Convertir imágenes de productos a MemoryImage
  final imgsProducto = <String, pw.MemoryImage>{};
  for (final it in items) {
    if (it.imagenBytes != null) {
      try {
        imgsProducto[it.producto.codigo] = pw.MemoryImage(it.imagenBytes!);
      } catch (_) {}
    }
  }

  double convertir(double usd) => moneda == 'USD' ? usd : usd * tasa;
  final sim = moneda == 'USD' ? '\$' : 'Bs.';
  final fmt = NumberFormat('#,##0.00', 'es_VE');

  // Paleta PDF
  final pdfPrimario   = PdfColor.fromInt(0xFF1E3A8A);
  final pdfAcento     = PdfColor.fromInt(0xFFEAB308);
  final pdfFondoClaro = PdfColor.fromInt(0xFFF3F4F6);
  final pdfTextoOsc   = PdfColor.fromInt(0xFF111827);
  final pdfLinea      = PdfColor.fromInt(0xFFE5E7EB);
  final pdfGrisTexto  = PdfColor.fromInt(0xFF6B7280);

  pdf.addPage(pw.MultiPage(
    pageFormat: PdfPageFormat.a4,
    margin: const pw.EdgeInsets.all(28),
    build: (ctx) => [
      // ── ENCABEZADO ─────────────────────────────────────────
      pw.Row(crossAxisAlignment: pw.CrossAxisAlignment.start, children: [
        // Izquierda: datos de la empresa
        pw.Expanded(flex: 3, child: pw.Column(
            crossAxisAlignment: pw.CrossAxisAlignment.start, children: [
          if (logo != null)
            pw.Container(width: 100, height: 70, child: pw.Image(logo,
                fit: pw.BoxFit.contain))
          else
            pw.Text(ConfigSistema.nombreEmpresa,
                style: pw.TextStyle(fontSize: 20, fontWeight: pw.FontWeight.bold,
                    color: pdfPrimario)),
          pw.SizedBox(height: 6),
          if (enc.nombreSede.isNotEmpty)
            pw.Text(enc.nombreSede,
                style: pw.TextStyle(fontSize: 11, fontWeight: pw.FontWeight.bold)),
          if (enc.rif.isNotEmpty)
            pw.Text('RIF: ${enc.rif}',
                style: pw.TextStyle(fontSize: 10, color: pdfGrisTexto)),
          if (enc.direccion.isNotEmpty)
            pw.Text(enc.direccion,
                style: pw.TextStyle(fontSize: 10, color: pdfGrisTexto)),
          if (enc.telefono.isNotEmpty)
            pw.Text('Tel: ${enc.telefono}',
                style: pw.TextStyle(fontSize: 10, color: pdfGrisTexto)),
          if (enc.correo.isNotEmpty)
            pw.Text(enc.correo,
                style: pw.TextStyle(fontSize: 10, color: pdfGrisTexto)),
        ])),
        // Derecha: bloque de cotización
        pw.Expanded(flex: 2, child: pw.Container(
          padding: const pw.EdgeInsets.all(12),
          decoration: pw.BoxDecoration(
            color: pdfPrimario,
            borderRadius: const pw.BorderRadius.all(pw.Radius.circular(6)),
          ),
          child: pw.Column(crossAxisAlignment: pw.CrossAxisAlignment.start,
              children: [
            pw.Text('COTIZACIÓN',
                style: pw.TextStyle(fontSize: 18,
                    fontWeight: pw.FontWeight.bold,
                    color: PdfColors.white, letterSpacing: 1)),
            pw.SizedBox(height: 6),
            if (idCotizacion.isNotEmpty)
              _pdfLineaEnc('Nº', idCotizacion.padLeft(6, '0')),
            _pdfLineaEnc('Fecha',
                DateFormat('dd/MM/yyyy').format(fechaCreacion)),
            _pdfLineaEnc('Vence',
                DateFormat('dd/MM/yyyy').format(fechaVence)),
            _pdfLineaEnc('Moneda', moneda == 'USD' ? 'Dólares' : 'Bolívares'),
            if (moneda == 'Bs')
              _pdfLineaEnc('Tasa', '${fmt.format(tasa)} Bs/\$'),
          ]),
        )),
      ]),
      pw.SizedBox(height: 20),

      // ── DATOS DEL CLIENTE ─────────────────────────────────
      pw.Container(
        padding: const pw.EdgeInsets.all(10),
        decoration: pw.BoxDecoration(
          border: pw.Border.all(color: pdfLinea, width: 1),
          borderRadius: const pw.BorderRadius.all(pw.Radius.circular(6)),
        ),
        child: pw.Column(crossAxisAlignment: pw.CrossAxisAlignment.start,
            children: [
          pw.Text('CLIENTE',
              style: pw.TextStyle(fontSize: 9, color: pdfGrisTexto,
                  letterSpacing: 1, fontWeight: pw.FontWeight.bold)),
          pw.SizedBox(height: 4),
          pw.Text(clienteNombre,
              style: pw.TextStyle(fontSize: 13,
                  fontWeight: pw.FontWeight.bold)),
          pw.SizedBox(height: 3),
          pw.Wrap(spacing: 20, runSpacing: 3, children: [
            if (clienteCedula.isNotEmpty)
              pw.Text('C.I./RIF: $clienteCedula',
                  style: const pw.TextStyle(fontSize: 10)),
            if (clienteTelefono.isNotEmpty)
              pw.Text('Tel: $clienteTelefono',
                  style: const pw.TextStyle(fontSize: 10)),
            if (clienteCorreo.isNotEmpty)
              pw.Text(clienteCorreo,
                  style: const pw.TextStyle(fontSize: 10)),
          ]),
        ]),
      ),
      pw.SizedBox(height: 14),

      // ── TABLA DE ITEMS ────────────────────────────────────
      pw.Table(
        columnWidths: {
          0: const pw.FixedColumnWidth(45),   // imagen
          1: const pw.FlexColumnWidth(4),     // descripción
          2: const pw.FixedColumnWidth(35),   // cantidad
          3: const pw.FixedColumnWidth(65),   // precio unit
          4: const pw.FixedColumnWidth(45),   // IVA
          5: const pw.FixedColumnWidth(70),   // importe
        },
        border: pw.TableBorder.all(color: pdfLinea, width: 0.5),
        children: [
          // Encabezado
          pw.TableRow(
            decoration: pw.BoxDecoration(color: pdfPrimario),
            children: [
              _pdfCeldaHead('IMG'),
              _pdfCeldaHead('DESCRIPCIÓN', align: pw.TextAlign.left),
              _pdfCeldaHead('CANT'),
              _pdfCeldaHead('P. UNIT'),
              _pdfCeldaHead('IVA'),
              _pdfCeldaHead('IMPORTE'),
            ],
          ),
          // Filas de items (alternadas)
          for (int i = 0; i < items.length; i++)
            pw.TableRow(
              decoration: pw.BoxDecoration(
                color: i.isEven ? PdfColors.white : pdfFondoClaro,
              ),
              children: [
                // Imagen
                pw.Container(
                  height: 40, padding: const pw.EdgeInsets.all(2),
                  alignment: pw.Alignment.center,
                  child: imgsProducto[items[i].producto.codigo] != null
                      ? pw.Image(imgsProducto[items[i].producto.codigo]!,
                          fit: pw.BoxFit.contain)
                      : pw.Text('—', style: pw.TextStyle(color: pdfGrisTexto)),
                ),
                // Descripción
                pw.Padding(
                  padding: const pw.EdgeInsets.all(6),
                  child: pw.Column(crossAxisAlignment: pw.CrossAxisAlignment.start,
                      children: [
                    pw.Text(items[i].producto.nombre,
                        style: pw.TextStyle(fontSize: 10,
                            fontWeight: pw.FontWeight.bold)),
                    if (items[i].producto.marca.isNotEmpty
                        || items[i].producto.modelo.isNotEmpty)
                      pw.Text('${items[i].producto.marca} · '
                              '${items[i].producto.modelo}',
                          style: pw.TextStyle(fontSize: 9,
                              color: pdfGrisTexto)),
                    if (items[i].producto.codigo.isNotEmpty)
                      pw.Text('Cód: ${items[i].producto.codigo}',
                          style: pw.TextStyle(fontSize: 8,
                              color: pdfGrisTexto)),
                  ]),
                ),
                _pdfCeldaBody('${items[i].cantidad}'),
                _pdfCeldaBody('$sim ${fmt.format(convertir(items[i].precioUnitario))}'),
                _pdfCeldaBody(incluyeIva ? '${kIvaCotizacion.toStringAsFixed(0)}%' : '—'),
                _pdfCeldaBody(
                    '$sim ${fmt.format(convertir(items[i].subtotal))}',
                    negrita: true),
              ],
            ),
        ],
      ),

      pw.SizedBox(height: 12),

      // ── TOTALES ───────────────────────────────────────────
      pw.Row(children: [
        pw.Expanded(flex: 3, child: pw.Container()),
        pw.Expanded(flex: 2, child: pw.Column(children: [
          _pdfFilaTotal('Base imponible',
              '$sim ${fmt.format(convertir(subtotalUsd))}',
              pdfTextoOsc, pdfGrisTexto),
          if (incluyeIva)
            _pdfFilaTotal('IVA (${kIvaCotizacion.toStringAsFixed(0)}%)',
                '$sim ${fmt.format(convertir(ivaUsd))}',
                pdfTextoOsc, pdfGrisTexto),
          pw.SizedBox(height: 4),
          // Total destacado
          pw.Container(
            padding: const pw.EdgeInsets.symmetric(horizontal: 10, vertical: 8),
            decoration: pw.BoxDecoration(color: pdfAcento,
                borderRadius: const pw.BorderRadius.all(pw.Radius.circular(4))),
            child: pw.Row(mainAxisAlignment: pw.MainAxisAlignment.spaceBetween,
                children: [
              pw.Text('TOTAL',
                  style: pw.TextStyle(fontSize: 13,
                      fontWeight: pw.FontWeight.bold, color: pdfTextoOsc)),
              pw.Text('$sim ${fmt.format(convertir(totalUsd))}',
                  style: pw.TextStyle(fontSize: 15,
                      fontWeight: pw.FontWeight.bold, color: pdfTextoOsc)),
            ]),
          ),
        ])),
      ]),

      pw.SizedBox(height: 30),

      // ── PIE ───────────────────────────────────────────────
      pw.Container(
        padding: const pw.EdgeInsets.all(10),
        decoration: pw.BoxDecoration(
          color: pdfFondoClaro,
          borderRadius: const pw.BorderRadius.all(pw.Radius.circular(6)),
        ),
        child: pw.Column(crossAxisAlignment: pw.CrossAxisAlignment.start,
            children: [
          pw.Text('IMPORTANTE',
              style: pw.TextStyle(fontSize: 9, color: pdfGrisTexto,
                  letterSpacing: 1, fontWeight: pw.FontWeight.bold)),
          pw.SizedBox(height: 4),
          pw.Text(
              'Esta cotización tiene carácter informativo y no representa '
              'una factura. Los precios y disponibilidad están sujetos a '
              'cambios sin previo aviso. Válida hasta la fecha de '
              'vencimiento indicada.',
              style: pw.TextStyle(fontSize: 9, color: pdfTextoOsc)),
        ]),
      ),
      pw.SizedBox(height: 16),
      pw.Center(child: pw.Text(
          'Gracias por su preferencia.',
          style: pw.TextStyle(fontSize: 10, color: pdfPrimario,
              fontStyle: pw.FontStyle.italic))),
    ],
  ));

  return pdf.save();
}

pw.Widget _pdfLineaEnc(String k, String v) => pw.Padding(
  padding: const pw.EdgeInsets.only(top: 2),
  child: pw.Row(children: [
    pw.SizedBox(width: 45,
        child: pw.Text(k, style: pw.TextStyle(fontSize: 9,
            color: PdfColors.grey300))),
    pw.Text(v, style: pw.TextStyle(fontSize: 10,
        color: PdfColors.white, fontWeight: pw.FontWeight.bold)),
  ]),
);

pw.Widget _pdfCeldaHead(String s, {pw.TextAlign align = pw.TextAlign.center}) =>
    pw.Padding(
      padding: const pw.EdgeInsets.symmetric(vertical: 6, horizontal: 4),
      child: pw.Text(s, textAlign: align, style: pw.TextStyle(
          color: PdfColors.white, fontSize: 9,
          fontWeight: pw.FontWeight.bold, letterSpacing: 0.5)),
    );

pw.Widget _pdfCeldaBody(String s, {bool negrita = false}) => pw.Padding(
  padding: const pw.EdgeInsets.all(6),
  child: pw.Text(s, textAlign: pw.TextAlign.center,
      style: pw.TextStyle(fontSize: 10,
          fontWeight: negrita ? pw.FontWeight.bold : pw.FontWeight.normal)),
);

pw.Widget _pdfFilaTotal(String k, String v, PdfColor c1, PdfColor c2) =>
    pw.Padding(
      padding: const pw.EdgeInsets.symmetric(vertical: 3, horizontal: 10),
      child: pw.Row(mainAxisAlignment: pw.MainAxisAlignment.spaceBetween,
          children: [
        pw.Text(k, style: pw.TextStyle(fontSize: 10, color: c2)),
        pw.Text(v, style: pw.TextStyle(fontSize: 11,
            color: c1, fontWeight: pw.FontWeight.bold)),
      ]),
    );

// ────────────────────────────────────────────────────────────────────
//  VENTANA — HISTORIAL DE COTIZACIONES
// ────────────────────────────────────────────────────────────────────

class VentanaHistorialCotizaciones extends StatefulWidget {
  const VentanaHistorialCotizaciones({super.key});
  @override
  State<VentanaHistorialCotizaciones> createState()
      => _VentanaHistorialCotizacionesState();
}

class _VentanaHistorialCotizacionesState
    extends State<VentanaHistorialCotizaciones> {
  bool _cargando = true;
  String? _error;
  List<CotizacionRegistro> _todas = [];
  String _filtroTexto = '';
  String _filtroEstado = 'todas'; // todas | pendiente | cobrada
  final _ctrlBuscar = TextEditingController();

  @override
  void initState() {
    super.initState();
    _cargar();
  }

  @override
  void dispose() {
    _ctrlBuscar.dispose();
    super.dispose();
  }

  Future<void> _cargar() async {
    setState(() { _cargando = true; _error = null; });
    try {
      final raw = await _Api.get('cotizaciones');
      if (raw is! List) throw Exception('Respuesta inválida del servidor');
      _todas = raw
          .map((m) => CotizacionRegistro.fromMap(m as Map<String, dynamic>))
          .toList();
    } catch (e) {
      _error = e.toString();
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  List<CotizacionRegistro> get _filtradas {
    final q = _filtroTexto.toLowerCase().trim();
    return _todas.where((c) {
      if (_filtroEstado != 'todas' && c.estado != _filtroEstado) return false;
      if (q.isEmpty) return true;
      return c.clienteNombre.toLowerCase().contains(q)
          || c.clienteCedula.toLowerCase().contains(q)
          || c.nroFactura.toLowerCase().contains(q);
    }).toList();
  }

  Future<void> _cobrar(CotizacionRegistro c) async {
    final ctrl = TextEditingController();
    final nro = await showDialog<String>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Cobrar cotización'),
        content: Column(mainAxisSize: MainAxisSize.min, children: [
          Text('Cliente: ${c.clienteNombre}'),
          const SizedBox(height: 8),
          TextField(
            controller: ctrl,
            autofocus: true,
            decoration: const InputDecoration(
              labelText: 'Nº de factura',
              border: OutlineInputBorder(),
            ),
          ),
        ]),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx),
              child: const Text('Cancelar')),
          ElevatedButton(
              onPressed: () => Navigator.pop(ctx, ctrl.text.trim()),
              child: const Text('Cobrar')),
        ],
      ),
    );
    if (nro == null || nro.isEmpty) return;
    try {
      await _Api.post('cotizacion_cobrar', {
        'id': c.id, 'nro_factura': nro,
      });
      await _cargar();
      _snack('Cotización marcada como cobrada');
    } catch (e) {
      _snack('Error: $e', esError: true);
    }
  }

  Future<void> _eliminar(CotizacionRegistro c) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Eliminar cotización'),
        content: Text('¿Eliminar la cotización de ${c.clienteNombre}?\n\n'
            'Esta acción no se puede deshacer.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancelar')),
          TextButton(onPressed: () => Navigator.pop(ctx, true),
              style: TextButton.styleFrom(foregroundColor: AppColors.statusRed),
              child: const Text('Eliminar')),
        ],
      ),
    );
    if (ok != true) return;
    try {
      await _Api.post('cotizacion_eliminar', {'id': c.id});
      await _cargar();
      _snack('Cotización eliminada');
    } catch (e) {
      _snack('Error: $e', esError: true);
    }
  }

  void _verDetalle(CotizacionRegistro c) {
    final sim = c.moneda == 'USD' ? '\$' : 'Bs.';
    final fmt = NumberFormat('#,##0.00', 'es_VE');
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text('Cotización #${(c.id ?? '').toString().padLeft(6, '0')}'),
        content: SizedBox(
          width: 500,
          child: SingleChildScrollView(child: Column(
              crossAxisAlignment: CrossAxisAlignment.start, children: [
            _detalleLinea('Cliente', c.clienteNombre),
            if (c.clienteCedula.isNotEmpty)
              _detalleLinea('C.I./RIF', c.clienteCedula),
            if (c.clienteTelefono.isNotEmpty)
              _detalleLinea('Teléfono', c.clienteTelefono),
            if (c.clienteCorreo.isNotEmpty)
              _detalleLinea('Correo', c.clienteCorreo),
            const Divider(),
            _detalleLinea('Emisión', c.fechaCreacion),
            _detalleLinea('Vence', c.fechaVence),
            _detalleLinea('Moneda', c.moneda),
            if (c.moneda == 'Bs')
              _detalleLinea('Tasa', '${fmt.format(c.tasa)} Bs/\$'),
            _detalleLinea('Estado', c.estado.toUpperCase()),
            if (c.nroFactura.isNotEmpty)
              _detalleLinea('Factura', c.nroFactura),
            const Divider(),
            const Text('Productos:',
                style: TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 6),
            ...c.items.map((it) {
              final cant = int.tryParse(it['cantidad']?.toString() ?? '1') ?? 1;
              final pu = double.tryParse(
                  it['precio_unitario']?.toString() ?? '0') ?? 0;
              final subUsd = cant * pu;
              final subMoneda = c.moneda == 'USD'
                  ? subUsd
                  : subUsd * c.tasa;
              return Padding(
                padding: const EdgeInsets.symmetric(vertical: 3),
                child: Row(children: [
                  Expanded(child: Text(
                    '${cant}× ${it['producto_nombre'] ?? ''}',
                    style: const TextStyle(fontSize: 12))),
                  Text('$sim ${fmt.format(subMoneda)}',
                      style: const TextStyle(fontSize: 12,
                          fontWeight: FontWeight.w600)),
                ]),
              );
            }),
            const Divider(),
            _detalleLinea('Subtotal', '$sim ${fmt.format(c.moneda == "USD" ? c.subtotal : c.subtotal * c.tasa)}'),
            if (c.incluyeIva)
              _detalleLinea('IVA', '$sim ${fmt.format(c.moneda == "USD" ? c.montoIva : c.montoIva * c.tasa)}'),
            _detalleLinea('TOTAL', '$sim ${fmt.format(c.moneda == "USD" ? c.total : c.total * c.tasa)}',
                destacado: true),
          ])),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx),
              child: const Text('Cerrar')),
        ],
      ),
    );
  }

  Widget _detalleLinea(String k, String v, {bool destacado = false}) =>
      Padding(
        padding: const EdgeInsets.symmetric(vertical: 2),
        child: Row(children: [
          SizedBox(width: 90,
              child: Text(k, style: TextStyle(
                  fontSize: destacado ? 13 : 11,
                  color: destacado ? _CotizColors.primario : Colors.grey))),
          Expanded(child: Text(v, style: TextStyle(
              fontSize: destacado ? 14 : 12,
              fontWeight: destacado ? FontWeight.w700 : FontWeight.w500))),
        ]),
      );

  void _snack(String msg, {bool esError = false}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(msg),
      backgroundColor: esError ? AppColors.statusRed : AppColors.statusGreen,
    ));
  }

  @override
  Widget build(BuildContext context) {
    final fmt = NumberFormat('#,##0.00', 'es_VE');
    return Scaffold(
      appBar: AppBar(
        title: const Text('Historial de Cotizaciones'),
        backgroundColor: _CotizColors.primario,
        foregroundColor: Colors.white,
        actions: [
          IconButton(icon: const Icon(Icons.refresh),
              onPressed: _cargar, tooltip: 'Recargar'),
        ],
      ),
      body: Column(children: [
        // Buscador + filtro estado
        Padding(
          padding: const EdgeInsets.all(12),
          child: Column(children: [
            TextField(
              controller: _ctrlBuscar,
              decoration: const InputDecoration(
                labelText: 'Buscar por cliente, cédula o factura',
                prefixIcon: Icon(Icons.search),
                border: OutlineInputBorder(),
                isDense: true,
              ),
              onChanged: (v) => setState(() => _filtroTexto = v),
            ),
            const SizedBox(height: 8),
            Row(children: [
              const Text('Estado:'),
              const SizedBox(width: 8),
              ChoiceChip(label: const Text('Todas'),
                  selected: _filtroEstado == 'todas',
                  onSelected: (_) => setState(() => _filtroEstado = 'todas')),
              const SizedBox(width: 4),
              ChoiceChip(label: const Text('Pendientes'),
                  selected: _filtroEstado == 'pendiente',
                  onSelected: (_) => setState(() => _filtroEstado = 'pendiente')),
              const SizedBox(width: 4),
              ChoiceChip(label: const Text('Cobradas'),
                  selected: _filtroEstado == 'cobrada',
                  onSelected: (_) => setState(() => _filtroEstado = 'cobrada')),
            ]),
          ]),
        ),
        const Divider(height: 1),
        // Lista
        Expanded(child: _cargando
            ? const Center(child: CircularProgressIndicator())
            : _error != null
                ? Center(child: Padding(
                    padding: const EdgeInsets.all(24),
                    child: Text('Error: $_error',
                        style: const TextStyle(color: Colors.red))))
                : _filtradas.isEmpty
                    ? const Center(child: Text(
                        'Sin cotizaciones que coincidan',
                        style: TextStyle(color: Colors.grey)))
                    : ListView.separated(
                        itemCount: _filtradas.length,
                        separatorBuilder: (_, __) => const Divider(height: 1),
                        itemBuilder: (_, i) {
                          final c = _filtradas[i];
                          final sim = c.moneda == 'USD' ? '\$' : 'Bs.';
                          final totalMoneda = c.moneda == 'USD'
                              ? c.total
                              : c.total * c.tasa;
                          final esCobrada = c.estado == 'cobrada';
                          return ListTile(
                            leading: CircleAvatar(
                              backgroundColor: esCobrada
                                  ? _CotizColors.verde
                                  : _CotizColors.naranja,
                              child: Icon(
                                esCobrada ? Icons.check : Icons.pending_actions,
                                color: Colors.white),
                            ),
                            title: Text(c.clienteNombre,
                                style: const TextStyle(fontWeight: FontWeight.w600)),
                            subtitle: Column(crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                              Text('${c.fechaCreacion} · $sim ${fmt.format(totalMoneda)}',
                                  style: const TextStyle(fontSize: 11)),
                              if (esCobrada && c.nroFactura.isNotEmpty)
                                Text('Factura: ${c.nroFactura}',
                                    style: const TextStyle(
                                        fontSize: 10, color: Colors.grey)),
                            ]),
                            trailing: PopupMenuButton<String>(
                              onSelected: (v) {
                                if (v == 'ver') _verDetalle(c);
                                else if (v == 'cobrar') _cobrar(c);
                                else if (v == 'eliminar') _eliminar(c);
                              },
                              itemBuilder: (_) => [
                                const PopupMenuItem(value: 'ver',
                                    child: Text('Ver detalle')),
                                if (!esCobrada)
                                  const PopupMenuItem(value: 'cobrar',
                                      child: Text('Cobrar')),
                                const PopupMenuItem(value: 'eliminar',
                                    child: Text('Eliminar',
                                        style: TextStyle(color: Colors.red))),
                              ],
                            ),
                            onTap: () => _verDetalle(c),
                          );
                        },
                      )),
      ]),
    );
  }
}
